INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 1, 'Rahman ve rahim Allah adiyle', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 2, 'Hamd, alemlerin rabbi Allah''a:', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 3, 'Rahmandır, rahimdir,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 4, 'din gününün sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 5, 'Ancak sana ibadet ederiz ve ancak senden yardım dileriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 6, 'Bize doğru yolu göster,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (1, 7, 'nimetlendirdiğin kişilerin yolunu; gazebe uğramışların da değil, sapıkların da', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 1, 'Elif lam mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 2, 'Bu, bir kitaptır ki onda şüphe yok. Takva sahiplerine yol göstericidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 3, 'Onlar, gaybe inanırlar, namaz kılarlar, rızıklandırdığımız şeylerin bir kısmını yoksullara harcarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 4, 'Onlar, sana indirilene de inanırlar, senden önce indirilenlere de; ahirete de iyice inanmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 5, 'Onlardır rablerinden doğru yolu bulanlar, onlardır kurtulup muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 6, 'Kafir olanlara gelince: İster korkut onları, ister korkutma, birdir; inanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 7, 'Allah kalplerini, kulaklarını mühürlemiştir, gözlerinde de perde var, pek büyük azab onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 8, 'İnsanlardan Allah''a ve son güne inandık diyenler de var, inanmamışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 9, 'Allah''ı ve inanları kandırırlar sanki Halbuki haberleri yok, ancak kendilerini kandırırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 10, 'Kalplerinde hastalık var, Allah da hastalıklarını arttırmıştır. Yalan söylediklerinden dolayı onlara elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 11, 'Onlara, yeryüzünde fesat çıkarmayın dendi mi, derler ki: Biz ıslah edicileriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 12, 'Bilin ki onlardır fesatçılar ama anlamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 13, 'Onlara, inanan insanlar gibi siz de inanın dendi mi, derler ki: Akılsızlar gibi biz de mi inanacağız? Bilin ki aklı az olanlar onlardır ama bilmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 14, 'İnananlarla buluştular mı inandık derler. Şeytanlarıyla yalnız kaldılar mı şüphe yok ki derler, biz sizinleyiz, biz ancak alay etmekdeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 15, 'Allah onlarla alay eder, taşkınlıklarında, azgınlıklarında başı boş dolaşsınlar diye mühlet verir onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 16, 'Onlardır doğru yolu satıp azgınlığı alanlar. Alışverişlerinden faydalanmadıkları gibi bir kazanç yolu da tutmamışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 17, 'Onlar, bir ateş yakıp ışıklanmak isteyen kimseye benzerler. Ateş, çevrelerindeki şeyleri aydınlattı mı Allah, nurlarını alıverir de onları karanlıklarda bırakır, görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 18, 'Sağırdırlar, dilsizdirler, kördürler, doğru yola dönemezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 19, 'Yahut da gökten boşana boşana yağan yağmura tutulmuşa benzerler; orada karanlıklar var, gök gürlemede, şimşek çakmada. Ölüm korkusuyla yıldırımların sesini duymamak için parmaklarıyla kulaklarını tıkarlar. Allah''sa inanmayanları çepçevre kaplamış, kavramıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 20, 'Şimşek neredeyse gözlerini alacak onların. Çakıp etraf aydınlandı mı yürürler, karanlıkta kaldılar mı dururlar. Allah dilerse duymalarını da alır, gözlerini de kör eder. Şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 21, 'Ey insanlar, sizi de, sizden öncekileri de yaratan Rabbinize ibadet edin de takva sahiplerinden olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 22, 'Öyle bir Allah''tır ki size yeryüzünü döşek etmiştir, gökyüzünü tavan. Gökten yağmur yağdırır, o yağmurla meyveler yetiştirir. Sizi rızıklandırır. Ona eşitler var demeyin, zaten olmadığını bilirsiniz de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 23, 'Kulumuza indiregeldiğimiz Kur''an''da şüpheniz varsa ona benzer bir sure getirin, doğrucuysanız Allah''tan başka tanıklarınızı da çağırın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 24, 'Bunu yapamazsanız, kesin olarak da yapamazsınız ya, sakının odunu insanlarla taşlar olan ve kafirlere hazırlanan ateşten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 25, 'İnananlara ve iyi işlerde bulunanlara müjde ver: Onlar içindir kıyılarından ırmaklar akan bahçeler. Orada bir meyveyle rızıklandılar mı bundan önce de bunu tatmıştık derler, onları dünyadakilere benzetirler. Onlara, dünyadakilere benzer rızıklar sunulur. Orada tertemiz eşler de var onlara, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 26, 'Şüphe yok ki Allah, sivrisineği de örnek getirmekten çekinmez, ondan üstün olanları da. İnananlar bilirler ki bu örnek, yerindedir ve Rablerindendir. Fakat inanmayanlar, Allah bu örnekle ne demek istiyor ki derler. O, bununla çoklarını şaşırtıp azdırır, çoklarını da doğru yola getirir. Azdırıp şaşırttıkları, ancak kötü işler yapanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 27, 'Kötülükte bulunanlar onlardır ki Allah''la ahdettikten sonra ahitlerini bozarlar. Allah''ın ulaştırılmasını emrettiği şeyi keserler, yeryüzünde bozgunculuk ederler. Onlardır ziyankarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 28, 'Allah''ı nasıl inkar edebilirsiniz ki ölüydünüz, diriltti sizi. Sonra öldürür, sonra gene diriltir, sonra da gerisin geriye ona dönersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 29, 'Öyle bir Allah''tır ki yeryüzünde ne varsa hepsini sizin için yarattı, sonra iradesini yücelere yöneltti de gökleri nizam ve intizam üzere yedi kat olarak yarattı. O, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 30, 'Hani Rabbin meleklere, ben yeryüzünde mutlaka bir halife yaratacağım demişti. Demişlerdi ki: Orada bozgunculuk edecek ve kan dökecek birini mi yaratacaksın? Biz, sana hamd ederek noksan sıfatlardan arılığını söylemede, seni kutlamadayız ya; ben, sizin bilmediğinizi bilirim demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 31, 'Âdem''e bütün adları bildirmişti de meleklere o adlarla anılan şeyleri gösterip hadi demişti, doğrucuysanız bunların adlarını haber verin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 32, 'Demişlerdi ki: Noksan sıfatlardan seni arı biliriz, bize bildirdiğin şeylerden başka bilgimiz yok. Şüphe yok ki sen, her şeyi bilirsin, hüküm ve hikmet sahibisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 33, 'Demişti ki: Ey Âdem onlara, yaratıkları adlarıyla haber ver, Âdem, her şeyi adlı adınca haber verince demişti ki: Ben size demedim mi, göklerdeki gizli şeyleri de bilirim, yeryüzünde ki gizli şeyleri de. Açığa vurduğunuzu da bilirim, gizlediğinizi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 34, 'Hani meleklere, Âdem''e secde edin demiştik de İblisten başka bütün melekler secde etmişlerdi. O, secde etmekten çekinmiş, ululanmak istemişti de kafirlerden olmuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 35, 'Demiştik ki: Ey Âdem, sen ve eşin cennette oturun, dilediğinizi bol bol yiyin. Ancak şu ağaca yaklaşmayın, yoksa haddini aşanlardan olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 36, 'Şeytansa oradan onların ayaklarını kaydırdı, onları bulundukları makamdan çıkarıverdi. Dedik ki: Bazınız, bazınıza düşman olarak inin buradan. Bir zamana kadar yeryüzünde oturmanız, oradan rızıklanmanız mukadder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 37, 'Âdem, Rabbinden bazı sözler belledi de Allah tövbesini kabul etti. Şüphe yok ki o, bütün tövbeleri kabul eder, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 38, 'Dedik ki: Hepiniz de cennetten inin. Fakat benden size bir doğru yol gösterici geldi mi o doğru yolu gösterenin izinden gidenlere ne korku vardır, ne hüzün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 39, 'İnanmayanlarla delillerimizi yalanlayanlara gelince: Onlardır ateş ehli; onlar, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 40, 'Ey İsrailoğulları, anın size verdiğim nimeti. Vefa edin ahdime de vefa edeyim ahdinize ve ancak benden korkun artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 41, 'İndirdiğim Kur''an''a inanın. Sizdeki kitabı da doğrulayıcıdır o. Ona ilk inanmayan siz olmayın. Delillerimi az ve değersiz bir parayla değişmeyin, ancak benden sakının.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 42, 'Doğruyu batılla karıştırıp da bile bile gerçeği unutup gizlemeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 43, 'Namaz kılın, zekat verin, rüku edin rüku edenlerle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 44, 'İnsanlara iyilik etmelerini emrediyorsunuz da kendinizi unutuyor musunuz? Ve kitabı okumaktasınız siz. Aklınız mı yok, düşünmez misiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 45, 'Sabretmek ve namaz kılmak hususunda Allah''tan yardım dileyin. Bunlar ağır ve büyük şeylerdir ama saygılı kimselere göre değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 46, 'Saygılılar, öyle kimselerdir ki Rablerine ulaşacaklarını iyiden iyiye umarlar, ona döneceklerini iyiden iyiye bilirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 47, 'Ey İsrail oğulları, anın size verdiğim nimetlerimi, anın sizi bütün alemlerden üstün ettiğimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 48, 'Korkun o günden ki hiç kimse, bir başkasının yerine bir şey ödeyemez o gün; kimsenin kimseye şefaati kabul edilmez, kimseden karşılık da alınmaz, onlara yardım da edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 49, 'Hatırlayın o zamanı ki sizi Firavun''un soyundan kurtardık. Onlar, size kötü bir surette azap ediyorlar, oğullarınızı kesiyorlar, kızlarınızı diri bırakmak istiyorlardı. Bu işte Rabbinizin bir sınaması vardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 50, 'Bir vakit sizin için denizi yardık da kurtardık sizi; Firavun''un soyunu sopunu sulara boğduk; siz de buna bakıp duruyordunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 51, 'Bir vakit Musa''ya kırk gecelik vade verdik. Sonra siz, o yokken tuttunuz da buzağıya kapıldınız, böylece zulmediyordunuz işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 52, 'Bundan sonra gene sizi affettik, şükretmeniz gerekti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 53, 'Doğru yolu bulasınız diye bir vakit Musa''ya kitap ve doğruyla eğriyi ayırt eden hükümler verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 54, 'Hani Musa, kavmine, siz buzağıya kapılmakla gerçekten kendinize zulmettiniz; tertemiz yaratıcınıza tövbe edin de nefislerinizi öldürün. Bu, yaratıcınız katında sizin için çok hayırlıdır demişti de Allah, bu yüzden tövbenizi kabul etmişti. Şüphe yok ki o, tövbeleri kabul eden rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 55, 'Bir zamanlar ya Musa demiştiniz, Allah''ı apaçık görmedikçe inanmayız sana. Derken bakınıp duruyordunuz, bir yıldırım düşmüş de sizi yakıvermişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 56, 'Sonra da gene şükredesiniz diye ölümünüzden sonra sizi dirilttik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 57, 'Bulutla gölgelendirmiştik sizi. Rızıklandırdığımız tertemiz şeylerden yiyin diye size kudret helvasıyla bıldırcın indirmiştik. Onlar, zulmü bize etmediler, kendilerine ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 58, 'Bir vakit şu şehre girin, nimetlerinden, nerede dilerseniz orada bolbol yiyin, kapısından secde ederek girin, burası yurttur deyin, yarlıganma dileyin de suçlarınızı örtelim; iyilikte bulunanların sevabını daha da arttıracağız demiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 59, 'Fakat zulmedenler, sözü, kendilerine söylenen şekilden başka bir şekle sokmuşlar, değiştirmişlerdi. Biz de zulmedenlere, kötülükte bulunduklarından dolayı gökten bir azap indirivermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 60, 'Gene bir zaman oldu ki Musa, kavmi için su diledi de ona, sopanla vur taşa demiştik. Vurunca taştan on iki pınar fışkırmıştı. Halkın her bölüğü, su içeceği kaynağı bilmiş, anlamıştı. Allah''ın rızkından yiyin, için de haddinizi aşıp yeryüzünü fesada vermeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 61, 'Bir zaman demiştiniz ki: Ya Musa, biz bir türlü yemeğe dayanamayız. Rabbinden bizim için iste de bize yerin yetiştirdiği şeylerden versin. Yerden yeşillik, kabak, sarımsak, mercimek, soğan bitirsin. Musa demişti ki: Daha hayırlı olanı, ondan daha aşağılık bir şeyle değiştirmek mi istiyorsunuz? Mısır''a inin, orada dilediğiniz şey var. Üzerlerine aşağılık ve yoksulluk çullanmıştı, Allah''ın da gazabına uğradılar. Evet, öyle de oldu; çünkü Allah''ın delillerine inanmamışlardı, haksız yere peygamberleri öldürüyorlardı. Evet, öyle de oldu; çünkü isyana boğulmuşlardı, çünkü aşırı gidiyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 62, 'Şüphe yok ki insanlarla Yahudi olanlardan, Nasranilerden, Sabiilerden, Allah''a ve son güne inanan ve iyi işler gören kimselere, Rableri katında ecir var. Onlar için ne korku vardır, ne hüzün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 63, 'Gene bir vakit sizden söz almıştık, Tur dağını üstünüze yüceltmiştik. Size verdiğimiz kitabı azimle alın, sakınanlardan olmak için de içindeki emirleri anın demiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 64, 'Bundan sonra gene yüz çevirmiştiniz. Allah''ın ihsanı ve rahmeti olmasaydı ziyankarlardan olurdunuz ya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 65, 'Bilirsiniz elbet, içinizde cumartesi gününe hürmet etmeyip emirden çıkanlara aşağılık maymun olun demiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 66, 'O zaman bunu görenlerle sonradan gelenlere ibret, sakınanlara da bir öğüt olmak üzere onları maymun şekline sokmuştuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 67, 'Gene bir zaman Musa, kavmine demişti ki: Şüphe yok ki Allah, size bir inek boğazlamanızı emrediyor. Kavmi, bizimle alay mı ediyorsun demişti. Musa, Allah''a sığınırım bilgisizlere katılmaktan demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 68, 'Peki demişlerdi, Rabbine dua et de ne biçim inek keselim, açıklasın bize. Musa, Allah diyor ki demişti, ne işten kalmış kart olacak, ne genç. İkisi arası dinç bir inek olmalı. Hadi, size emredilen şeyi yapın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 69, 'Demişlerdi ki: Rengi nasıl olsun? Rabbine dua et de açıklasın bize. Musa, Allah diyor ki demişti, sapsarı, lekesiz olacak, bakanlara sevinç, neşe verir bir renk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 70, 'Demişlerdi ki: Bu nasıl inek? Bizce inek ineğe benzer. Rabbine dua et de bize bildirsin. Allah dilerse buluruz elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 71, 'Musa, Allah diyor ki demişti, ne çifte koşulup tarla sürmüş olacak, ne ekin sulamış olacak. Ayıpsız, lekesiz, alacasız olmalı. Hah demişlerdi, şimdi gerçeği söyledin. İneği boğazladılar, boğazladılar ama az kaldı bu emri yerine getiremeyeceklerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 72, 'O vakit birisini öldürmüş, çekişip suçu üstünüzden atmıştınız hani. Allah''sa gizlediğinizi açığa vuracaktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 73, 'Demiştik ki: O adama, ineğin bir uzvuyla vurun işte Allah, aklınız başınıza gelsin diye ölüleri böyle diriltir, delillerini size böyle gösterir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 74, 'Ama bundan sonra kalpleriniz katılaştı, taşa döndü, Hatta taştan da katı bir hale geldi. Çünkü öyle taşlar var ki içinden nehirler kaynar. Öylesi var ki çatladı mı bağrından su fışkırır. Öylesi de var ki Allah korkusundan yerlere yuvarlanır. Allah, yaptığınızdan gafil değil ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 75, 'Bunların, size inanıvereceklerini mi umuyor, buna mı tamah ediyorsunuz? İçlerinde bir bölük var ki Allah sözünü duyduktan, akılları o sözleri aldıktan sonra da bilebile değiştirirlerdi o sözleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 76, 'Onlar, inananlarla buluştular mı inandık derler de sonra birbirleriyle yalnız kaldılar mı aklınız mı yok derler, Rabbiniz indinde sizinle çekişsinler, aleyhinize delil göstersinler diye mi Allah''ın size açıkladığı şeyi tutup onlara söylüyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 77, 'Bilmezler mi ki Allah, onların gizlediklerini de bilir, açığa vurduklarını da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 78, 'İçlerinde, anasından doğduğu gibi kalan, okuma yazma bilmeyenler de var ki onlar, kitap nedir bilmezler. Bildikleri şey, ancak kuruntularıdır, onlar, ancak zanna kapılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 79, 'Elleriyle kitap yazıp sonra da az bir para almak için bu, Allah tarafından geldi diyenlerin vay hallerine. Elleriyle yazdıklarından, o kitabı, kendileri düzdüklerinden dolayı vay hallerine, kazançları yüzünden vay hallerine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 80, 'Dediler ki: Ateş, bizi yaksa bile birkaç gün yakar. De ki: Allah''tan bir söz mü aldınız? Aldınızsa Allah sözünden hiç dönmez. Yoksa Allah hakkında bilmediğiniz şeyi mi söylüyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 81, 'Hayır, iş öyle değil; kim bir günah kazandı, vebali kendisini sardı, kapladıysa işte o çeşit adamlardır ateş ehli. Onlar, ateşte ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 82, 'İnananlarla iyi işler görenlere gelince: Onlar cennet ehlidir, onlar da cennette ebedidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 83, 'Bir zaman İsrailoğullarından, Allah''tan başkasına tapmamak, anaya, babaya, akrabaya, yetimlere, yoksullara iyilik etmek üzere kesin söz almıştık. İnsanlara güzellikle söz söyleyin, iyi şeyler buyurun, namaz kılın, zekat verin demiştik. Sonra pek azınız müstesna, sözünüzden dönmüştünüz, hala da dönmedesiniz zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 84, 'Bir zaman birbirinizin kanını dökmemek, yerinizden yurdunuzdan çıkmamak hususunda kesin söz almıştık sizden. Sonra siz de bunu ikrar etmiş, siz de buna tanık olmuştunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 85, 'Sonra da sizler, o kişilersiniz ki birbirinizi öldürüyorsunuz. Bir bölüğünüzü yerinden yurdundan çıkarıyorsunuz. Onların aleyhinde, kötülükte, düşmanlıkta bulunmak üzere birleşiyorsunuz. Elinize esir düşerlerse onlara karşılık esirler veriyor, gene onları yurtlarına sokmuyorsunuz. Halbuki onları yurtlarından çıkarmak bile haramdı size. Yoksa kitabın bir kısmına inanıyor, bir kısmına inanmıyor musunuz? İçinizde bunları yapanların kazancı, dünya hayatında ancak horluktan ibaret, kıyamet günüyse onlar daha çetin bir azaba atılırlar. Allah, yaptıklarınızdan gafil değildir ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 86, 'Onlar, ahireti dünya yaşayışına satmış kimselerdir. Onların azabı da hafifletilmez, onlara yardım da edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 87, 'Şüphe yok ki Musa''ya Tevrat''ı verdik, ardından birtakım peygamberler gönderdik. Meryem oğlu İsa''ya apaçık deliller verip onu RuhülKudüs''le kuvvetlendirdik. Nefsinizin hoşlanmadığı bir emirle peygamber geldi mi demek ululanmak isteyeceksiniz, kiminiz onları yalanlayacak, kiminiz öldürecek ha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 88, 'Dediler ki: kalplerimiz örtülü, kılıf içinde. İş öyle değil. Küfürleri yüzünden Allah onları rahmetinden uzaklaştırdı. Onun için azı, pek azı inanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 89, 'Evvelce kafir olanlara üst gelmek için imdat isterlerken Allah tarafından, onların inandığı kitabı tasdik eden bir kitap geldi, bildikleri, tanıdıkları zuhur etti mi ona kafir oldular. Hay Allah''ın laneti kafirlere olsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 90, 'Ne pis şeydir o kendilerini satmaları, bu suretle de Allah''ın indirdiği Kur''an''a kafir olmaları, Allah''ın, kullarından dilediğine ihsan edip kitap indirmesine haset ederek kafirlikte bulunmaları. Bu yüzden gazap üstüne gazaba uğradılar. Kafirler için aşağılık bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 91, 'Onlara, Allah''ın indirdiğine inanın denince biz, bize indirilene inandık derler de ondan başkasına inanmazlar. Halbuki o, gerçektir, onlara inen kitabın gerçekliğini söyler. De ki: İnanmışsanız neden önceleri Tanrı peygamberlerini öldürdünüz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 92, 'Andolsun ki Musa, size açık delillerle geldi de ondan sonra tuttunuz, buzağıya taptınız, siz o zalimlersiniz işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 93, 'De ki: O vakit sizden kesin söz almıştık, Tur dağını üstünüze yüceltmiştik. Size verdiğimizi azimle tutun, dinleyin demiştik. Onlar da duyduk demişlerdi ve asi olduk. Buzağı sevgisi, küfürleri yüzünden ta iliklerine işlemişti. İnanmışsanız inancınız, ne de kötü ve pis şey emrediyor size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 94, 'De ki: Âhiret yurdu, Allah katında başkalarının değil de bilhassa sizinse ve sözünüzde doğrucuysanız ölümü dilesenize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 95, 'Fakat elleriyle kazandıkları suçlardan dolayı hiçbir zaman dilemezler. Allah, zalimleri iyice bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 96, 'Andolsun ki onları, insanların hayata en düşkünü olarak bulursun. Onlar, müşriklerden de düşkündür hayata. Her biri bin yıl yaşamayı arzular. Fakat yaşasa ne olacak? Onu azaptan kurtaramaz ki. Allah, ne yapıyorlarsa görmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 97, 'De ki: Kim Cibril''e düşmansa iyi bilsin ki o, Allah''ın izniyle evvelce inen kitapların doğruluğunu bildiren, inananlara doğru yolu gösteren ve bir müjdeci olan Kur''an''ı, senin kalbine indirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 98, 'Kim, Allah''a ve meleklerine ve peygamberlerine ve Cibril''e ve Mikal''e düşman olursa bilsin ki Allah da kafirlere düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 99, 'Andolsun ki sana apaçık ayetler indirdik. Onlara, ancak kötü işlerde bulunanlar kafir olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 100, 'Onlarla bir ahde girişildi mi içlerinden bir bölüğü o ahdi bozacak ha. Bir bölüğünün ahdini bozması şöyle dursun, zaten çokları inanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 101, 'Allah tarafından onlarda bulunan kitabın doğruluğunu bildiren bir peygamber geldi mi kitap ehlinin bir kısmı, Allah''ın kitabını artlarına atarlar, sanki de bilmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 102, 'Tuttular da Süleyman''ın saltanatı aleyhine, Şeytanların kapıldıkları şeylere uydular. Halbuki Süleyman kafir olmamıştı, Şeytanlar kafir olmuşlardı. İnsanlara büyü yapmasını ve Babil''deki Harut, Marut adlı iki meleğe indirilen şeyleri öğretiyorlardı. O iki melek, hiçbir kimseye biz, ancak ve ancak Allah tarafından bir sınamayız, sakın kafir olma demeden bir şey öğretmiyordu. Onlardan, karıyla kocanın arasını açan şeyleri öğreniyorlardı. Öğrenenler de Allah''ın izni olmaksızın hiçbir kimseye zarar veremezlerdi. Kendilerine zarar verecek, fakat hiçbir faydası olmayacak şeyleri öğrenmekteydiler. Andolsun ki bu bilgiyi satın alanın ahiretten nasibi yoktur, bunu iyice bilmişlerdi de. Fakat bir de canları pahasına satın aldıkları o şeyin ne pis şey olduğunu bilselerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 103, 'İman edip de kötülüklerden korunsalardı elbette Allah''tan elde edecekleri sevap, daha hayırlı olacaktı. Bir bilselerdi bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 104, 'Ey insanlar, "bizi de gözet, bırak da anlayalım" demeyin. "Bize de bak, bizi de gözet" deyin ve dinleyin. Kafirlere pek elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 105, 'Ne kitap ehlinden kafir olanlar, ne de müşrikler, size Rabbinizden bir hayır indirilmesini istemezler. Allah''sa dilediğini rahmetiyle seçer de ona bir hususiyet verir. Allah büyük bir ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 106, 'Bir ayetin hükmünü değiştirir, yahut geri bırakırsak ya ondan hayırlısını getiririz, yahut onun eşidini. Bilmez misin ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 107, 'Bilmez misin ki şüphesiz göklerin saltanatı da Allah''ındır, yeryüzünün saltanatı da ve sizin için Allah''tan başka ne bir dost vardır, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 108, 'Yoksa siz de peygamberinizi, evvelce Musa''ya olduğu gibi sorguya mı çekmek istersiniz? Kim küfrü imanla değişirse artık doğru yoldan sapmış, azıtmış gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 109, 'Kitap ehli olanların çoğu, sizi imana geldikten sonra döndürmek ister, kafir olmanızı diler. Gerçek, kendilerince de besbellidir ama sonra bunu, özlerindeki hasetlerinden isterler. Allah emri gelinceye dek bırakın, aldırış bile etmeyin. Şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 110, 'Namaz kılın, zekat verin. Kendiniz için; Önceden ne hayırda bulunursanız onu, Allah katında bulursunuz. Şüphe yok ki Allah, yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 111, 'Cennete Yahudi yahut Nasrani olmayan kesin olarak giremez dediler, kendi kuruntuları bu. De ki: Doğrucuysanız hadi, delillerinizi getirin bakalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 112, 'Evet, kim, özü halis olarak yüzünü tertemiz bir surette Allah''a çevirir, ona teslim olursa ecri Rabbinin katındadır. Onlara ne korku vardır, ne de mahzun olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 113, 'Yahudiler, Nasranilere, hiçbir şeye dayanmıyorlar dediler. Nasraniler de, Yahudiler, hiçbir şeye dayanmıyorlar dediler. Halbuki hepsi de kitap okurlar. Bilgisi olmayanlar da tıpkı onların dediklerini dedi. Allah, aykırılığa düştükleri şey yüzünden, kıyamet gününde aralarını bulur, gerçek hükmü verir elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 114, 'Allah için yapılan mescitlerde Allah''ın adının anılmasını men''eden ve onların yıkılmasına çalışan kimseden daha zalim kim var ki? Bunlar, ancak oralara korka korka girebilirler. Onlara dünyada horluk var, ahirette de pek büyük bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 115, 'Doğu da Allah''ındır, batı da. Artık nereye dönerseniz dönün, orada Allah''a dönmüş olursunuz. Şüphe yok ki Allah''ın lütfü, rahmeti boldur, o her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 116, 'Allah, kendisine oğul edindi dediler, haşa. Belki göklerde de ne varsa onundur, yeryüzünde de; hepsi de ona ram olmuştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 117, 'Gökleri de eşsiz, örneksiz yaratan odur, yeryüzünü de. Bir işin olmasını diledi mi ona ancak ol der, o iş oluverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 118, 'Bilgisi olmayanlar, Allah bizimle konuşsa, yahut bize bir delil, bir mucize gelse dediler. Önce gelenler de tıpkı onlar gibi söylemişlerdi. Kalpleri, ne kadar da birbirine benzedi onların. Gerçeği iyice bilmek isteyenlere ayetlerimizi apaçık gösterdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 119, 'Şüphe yok ki biz, seni dosdoğru bir müjdeci ve korkutucu olarak gönderdik, zaten sen, o cehennemliklerden sorumlu da değilsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 120, 'Onların dinine uymadıkça ne Yahudiler senden razı olurlar, ne Nasraniler. De ki: Ancak Allah''ın hidayet yolu, doğru yoldur. Bilgi sahibi olduktan sonra da onların nefsani dileklerine uyarsan sana Allah''tan başka ne bir dost vardır artık, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 121, 'Kendilerine kitap verdiğimiz kimseler, onu hakkıyla okurlar. İşte onlar kitaba inanırlar. Ona inanmayanlarsa ziyankarların ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 122, 'Ey İsrailoğulları, size verdiğim nimetimi ve sizi alemlere üstün ettiğimi anın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 123, 'Sakının o günden ki kimse, o gün kimsenin bir şeyini ödeyemez, kimseden bir karşılık kabul edilmez, kimsenin kimseye şefaati fayda vermez, onlara yardım da edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 124, 'O zamanlar Rabbi, İbrahim''i bazı sözlerle sınadı. O, bunları yerine getirip tamamlayınca dedi ki: Ben seni insanlara imam edeceğim. İbrahim, soyumu da imam et dedi. Allah, benim ahdime dedi, zalimler nail olamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 125, 'O sıralarda Ka''be''yi sevap kazanma yeri ve emniyet yurdu ettik. İbrahim''in makamını namazgah edinin. İbrahim''le İsmail''e de, evimi, dönüp dolaşanlara, burada oturup ibadette bulunanlara, rüku ve sücud edenlere tertemiz tutun diye kesin emir verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 126, 'O zaman İbrahim, Ya Rabbi dedi, bu şehri emniyetli bir yer et. Buradakilerden Allah''a ve son güne inananları meyvelarla rızıklandır. Allah, kafir olanı da bir müddet rızıklandıracağım da sonra zorla onu, ateşle azaba uğratacağım. Oraya gidiş, ne yaman bir sonuçtur, ne kötü bir gidiştir dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 127, 'O vakit İbrahim ve İsmail Kabe''nin temel duvarlarını yükselttiler de Rabbimiz dediler, bu evi yaptık, sen kabul et. Şüphe yok ki sen, her şeyi duyansın, bilensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 128, 'Rabbimiz, bizi sana teslim olmuş kullardan et, soyumuzdan da Müslüman bir ümmet izhar eyle. İbadet yerlerini, ibadetimizin yolunu yordamını göster bize. Tövbe ettikçe tövbemizi kabul et. Şüphe yok ki sen, tövbeleri kabul eden rahimsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 129, 'Rabbimiz, onların içinden bir peygamber gönder de onlara, senin ayetlerini okusun, kitabı, hikmeti öğretsin, onları tertemiz bir hale getirsin. Şüphe yok ki sen, yücelik, hüküm ve hikmet sahibisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 130, 'Kendini bilmeyenden, aklı başında olmayandan başka kim, İbrahim''in dininden döner? Andolsun ki biz onu dünyada seçtik, ahirette de şüphe yok ki o, salihlerdendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 131, 'O zaman Rabbi, İbrahim''e, ram ol, teslim ol dedi. İbrahim dedi ki: Âlemlerin Rabbine teslim oldum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 132, 'İbrahim de bunu oğullarına vasiyet etti, Yakup da, oğullarım dedi, Allah şüphesiz sizin için bir din seçti, siz de artık ancak Müslüman olarak ölün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 133, 'Yoksa Yakup ölürken oradaydınız da gözlerinizle mi gördünüz? Yakup, ölüm haline gelince oğullarına, benden sonra kime tapacaksınız dedi. Dediler ki: Senin Allah''ına tapacağız. Babalarının, İbrahim''in, İsmail''in, İshak'' ın Allah''ı olan bir Allah''a. Biz, ona teslim olanlarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 134, 'Onlar birer ümmetti, gelip geçtiler. Onların kazançları kendilerine, sizin kazancınız size. Onların yaptıkları sizden sorulmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 135, 'Yahudi, yahut Nasrani olun da doğru yolu bulun dediler. De ki: Hayır, küfürden, şirkten uzak ve temiz olan İbrahim''in dinindeyiz. O, hiçbir zaman şirk koşanlardan olmadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 136, 'Deyin ki: Allah''a, bize indirilen kitaba, İbrahim''e İsmail''e, İshak''a, Yakup''a, Yakup''un oğullarına indirilenlere, Musa''ya, İsa''ya ve peygamberlere Rablerinden verilene inandık, onların hiçbirini öbüründen ayırt etmeyiz ve biz, Allah''a teslim olanlarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 137, 'Sizin iman ettiğiniz gibi iman ederlerse mutlaka doğru yolu buldular demektir. Fakat yüz çevirdiler mi onlar, ancak ayrılık, aykırılık içindedir. Onlara karşı koymak için sana, Allah yeter ve o, her şeyi duyandır, bilendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 138, 'Allah''ın verdiği renk. Allah''tan daha güzel renk veren kim? Ve biz ona tapanlarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 139, 'De ki: Allah hakkında bizimle mücadeleye mi girişiyorsunuz? O, bizim de Rabbimizdir, sizin de Rabbiniz. Bizim yaptıklarımız bize ait, sizin yaptıklarınız size ve biz, bütün kalbimizle Allah''a bağlıyız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 140, 'Yoksa İbrahim de, İsmail de, İshak da, Yakup da, oğulları da Yahudi, yahut Nasraniydi mi diyorsunuz? De ki: Siz mi daha iyi bilirsiniz, Allah mı? Allah''ın bildiği, bildirdiği şeyi bilerek gizleyenden daha zalim kim var? Allah, yaptıklarınızdan gafildeğildir ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 141, 'Onlar birer ümmetti, gelip geçtiler. Onların kazançları onlara, sizin kazancınız size. Onların yaptıkları sizden sorulmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 142, 'İnsanlardan aklı, idraki olmayanlar diyecekler ki: Bunları, yöneldikleri kıbleden döndüren sebep de nedir? Doğu da Allah''ındır de, batı da. Dilediğine doğru ve düz yolu buldurur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 143, 'İşte böylece bütün insanlara tanıklık etmeniz, Peygamberin de size tanık olması için sizi, doğru yolun tam ortasında giden bir ümmet yapmışızdır. Zaten evvelce yöneldiğin Ka''be''yi kıble yapışımızdan maksat da ancak Peygambere uyacak olanları, iki topuğu üstünde gerisin geriye döneceklerden ayırt etmektir. Bu, elbette Allah''ın doğru yolu gösterdiği kimselerden başkalarına ağır gelecek. Allah, imanınızı zayi etmez. Şüphe yok ki Allah, insanları esirgeyicidir, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 144, 'Gerçekten de yüzünü göğe çevirip arandığını görmekteyiz. Seni, razı olacağın bir kıbleye yönelteceğiz. Hadi, yüzünü Mescidi Haram''a çevir. Siz de Nerede bulunursanız bulunun, yüzlerinizi o tarafa döndürün. Kendilerine kitap verilenler de bilirler ki bu, Rablerinden gelmiştir, yerindedir, gerçektir ve Allah, onların yaptıklarından gafil değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 145, 'Andolsun ki sen, kendilerine kitap indirilmiş olanlara bütün delilleri getirsen gene de senin kıblene uymazlar. Sen de onların kıblesine uymazsın. Zaten onların bir kısmı da bir kısmının kıblesine uymaz. Bunu iyice bildikten sonra artık tutar, onların dileklerine uyarsan şüphe yok ki zalimlerden olursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 146, 'Kendilerine kitap indirdiğimiz kimseler, Peygamberi, oğullarını tanır gibi tanırlar. Tanırlar ama gene de içlerinden bir kısmı bilebile gerçeği gizler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 147, 'Gerçek, Rabbindendir. Artık sakın şüpheye düşenlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 148, 'Herkesin yöneldiği bir yer var, oraya döner. Siz de hep hayırlara yönelin, hayır yolunda yarışın. Nerede olursanız olun, Allah sizi toplar, birleştirir. Şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 149, 'Nerede bulunursan bulun, hemen yüzünü Mescidi Haram''a doğru çevir. Bu emir şüphesiz gerçektir, Rabbindendir ve Allah yaptığınız şeylerden gafil değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 150, 'Nerede bulunursan bulun, yüzünü Mescidi Haram''a çevir. Nerede olursanız olun, yüzünüzü o tarafa çevirin de insanlar, aleyhinizde bir itirazda bulunamasınlar, ama haksızlık edenler ve zulümde bulunanlar başka. Siz korkmayın onlardan, benden korkun da hem size verdiğim nimetimi tamamlayayım, hem de bu suretle hidayete erişin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 151, 'Nasıl ki içinizden size bir Peygamber gönderdik. Size ayetlerimizi okumada, ahlakınızı temiz bir hale koymada. Size kitap ve hikmet öğretmede ve bilmediğiniz şeyler hakkında size malumat verip sizi bilgi sahibi etmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 152, 'Artık siz de anın beni, anın da ben de anayım sizi. Nankörlüğü bırakın da şükredin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 153, 'Ey inananlar, sabretmek ve namaz kılmakla Allah''tan yardım dileyin. Şüphesiz ki Allah, sabredenlerledir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 154, 'Allah yolunda öldürülenlere de ölü demeyin. Onlar diridir ama siz anlamazsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 155, 'Andolsun ki mutlaka sizi birazcık korkuyla, açlıkla, mal, can ve meyve noksanıyla sınayacağız. Müjdele sabredenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 156, 'O sabredenleri ki onlar, bir musibete uğradılar mı biz Allah''ınız, gene de gerisin geriye ona döneceğiz derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 157, 'Öyle kimselerdir onlar ki Rablerinden yarlıganma ve rahmet onlara. Onlardır doğru yolu bulanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 158, 'Şüphe yok ki Safa ve Merve, Allah alametlerindendir. Artık kim hac veya umre etmek için Ka''be''yi tavaf edip Safa ve Merve arasında koşarsa suçsuzdur. Kim gönlünden koparak hayır işlerse şüphe yok ki Allah, ona mükafatta bulunur ve her şeyi de bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 159, 'İndirdiğimiz apaçık delilleri, bildirdiğimiz dosdoğru yolu, insanlara Kur''an''da tamamıyla anlattıktan sonra bunu gizleyenlere gelince: Allah da onlara lanet eder, lanet edenler de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 160, 'Ancak içlerinden tövbe edenler, hallerini düzeltenler ve doğruyu söyleyenler müstesna. Onların tövbesini kabul ederim. Ben tövbeleri kabul eden rahimim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 161, 'Kafir olup küfründe ısrar ederek bu halle can verenler yok mu! Allah''ın laneti de onlara, meleklerin laneti de, bütün insanların laneti de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 162, 'Ebedi olarak lanette kalırlar. Ne azapları hafifletilir, ne yüzlerine bakılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 163, 'Allah''ınız, bir Allah''tır ondan başka tapacak yok, rahman ve rahim odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 164, 'Göklerin ve yeryüzünün yaratılışında, gece ile gündüzün birbiri ardınca gelişinde, insanlara fayda vermek üzere denizde yürüyüp giden gemide, Allah''ın, gökten yağmur yağdırarak yeryüzünü, ölümünden sonra diriltmesinde, sonra da yeryüzüne, yürüyen hayvanları yaymasında, yelleri dilediği gibi estirip değiştirmesinde, gökle yer arasında emrine münkad olan bulutta, şüphe yok ki aklı erenler için varlığına, birliğine deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 165, 'İnsanların bir kısmı Allah''tan başka ona birtakım eşitler edinirler de onları, Allah''ı sever gibi severler. İnananlarsa, Allah''ı onlardan daha kuvvetli bir sevgiyle severler. Zulmedenler, bir görselerdi ki azaba düşecekleri vakit bütün kuvvet, ancak ve ancak Allah''ındır ve Allah, çok şiddetli azap eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 166, 'O vakit kendilerine uyulanlar, azabı görerek kendilerine uyanlardan kaçınır, uzaklaşırlar, aralarındaki vesile ve sebepler de tamamıyla kesilir gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 167, 'Onlara uyanlar da muhakkak derler ki: Keşke bir kere daha dünyaya dönseydik de onlar bizden nasıl kaçındıysa biz de onlardan kaçınsaydık, çekinseydik. İşte Allah, onlara yaptıkları işleri, üstlerine çöken bir hasretten ibaret olarak gösterir. Onlar, ateşten dışarı çıkamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 168, 'Ey insanlar, yeryüzünde helal ve temiz olan şeyleri yiyin. Şeytan''ın izini izlemeyin. Şüphe yok ki o, size apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 169, 'O, size ancak ve ancak çirkin ve kötü şeyler buyurur, Allah hakkında bilmediğiniz şeyleri söylemenizi emreder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 170, 'Onlara, Allah neyi indirdiyse ona uyun dendi mi dediler ki: Hayır, biz atalarımız neye uyduysa ona uyarız. İyi ama atalarınızın aklı bir şeye ermiyorsa ve doğru yolu bulmadılarsa ne olacak?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 171, 'Kafirler, hiçbir şey duyup dinlemeden, anlamadan bağırıp çağıran kimseye benzerler. Sağırdırlar, dilsizdirler, kördürler, akıl da edemez onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 172, 'Ey inananlar, size rızık olarak verdiğimiz temiz şeyleri yiyin ve ancak ona tapıyorsanız karşılık olarak şükredin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 173, 'Söz budur ancak. O, size ölü hayvan etini, kanı, domuz etini, Allah''tan başkası için kesilen hayvanı haram etmiştir. Fakat zorda kalan, başkasının hakkına el uzatmamak ve zaruret miktarını da aşmamak üzere yerse günah etmiş olmaz. Çünkü Allah, suçları örten rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 174, 'O kimseler ki Allah''ın indirdiği kitaptan bir emri, bir hükmü gizlerler de buna karşılık değersiz bir miktar para alırlar, işte muhakkak onlardır ateş yiyenler. Karınlarında ateşten başka bir şey yoktur. Allah kıyamet gününde onlarla ne konuşur, nede onları temizler. Onlara ancak elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 175, 'Onlardır sapıklığı doğru yola, azabı yarlıganmaya karşılık olarak satın alanlar; ateşe ne de sabırlı kimselerdir ya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 176, 'Bu, haksız da değildir. Çünkü Allah, kitabı şüphe yok ki hak olarak, doğruyu söylemek için indirdi. Allah kitabında ihtilafa düşenler, elbette haktan uzak bir ayrılıktadırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 177, 'Yüzlerinizi doğuya, batıya çevirip durmanız, hayır sayılmaz ki. Hayır ve taat sahipleri, Allah''a, son güne, meleklere, kitaba, peygamberlere inanan, Allah sevgisiyle yakınlara, yetimlere, yoksullara, yolda kalmışlara, isteyenlere ve esirlere mal veren, namaz kılan, zekat veren, ahdettikleri zaman ahitlerine vefa eden, sıkıntı ve şiddet vakitlerinde sabreden kişilerdir. Onlardır sözleri doğru olanlar, onlardır sakınanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 178, 'Ey inananlar, öldürülenler hakkında size kısas farz edilmiştir: Hüre karşılık hür, kula karşılık kul, kadına karşılık kadın. Fakat öldüren, kardeşinden azıcık bir affa nail olursa o zaman kısas kalkar; öldürülenin velisinin, akla ve örfe uygun olarak iyiliğe uyması, öldürenin de, öldürdüğü kişinin velisine güzellikle bir şey vermesi kalır. Bu, Rabbinizden hükmü hafifletmedir, rahmettir. Bundan sonra da gene zulme kalkan ve aşırı giden olursa artık ona elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 179, 'Ey aklı erenler, özü sözü temiz kimseler, korunmanız, sakınmanız için kısasta size hayat var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 180, 'Biriniz ölürken kendisinden sonra bir hayır bırakacaksa anasına, babasına ve yakınlarına, örfe uyarak vasiyette bulunmalı. Bu, sakınanlara bir haktır, bir borçtur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 181, 'Vasiyeti duyduktan sonra değiştiren olursa şüphe yok ki bu işin vebali, ancak değiştirenedir. Muhakkak ki Allah, her şeyi duyar ve bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 182, 'Vasiyet edenin yanılmasından, suç işlemesinden ürküp aralarını bulana suç yok. Şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 183, 'Ey inananlar, kötülüklerden, şüpheli şeylerden korunmanız için oruç, sizden öncekilere farz edildiği gibi size de farz edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 184, 'Oruç, sayılı günlerdedir. İçinizden biri hastalanır, yahut yolda bulunursa orucunu yer, sonra başka günlerde, o yediği gün sayısınca oruç tutar. Kime oruç zor gelirse her gün için bir yoksulu doyurur. Hayır için verdiği şeyi çoğaltırsa bu da kendi hayrına. Fakat bilseniz oruç tutmanız, sizin için daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 185, 'Ramazan ayı, bir aydır ki insanlara doğruyu bildiren, doğruluğa ait apaçık delillerden ibaret olan, hakla batılı ayırt eden Kur''an, bu ayda indirildi. Sizden kim, bu aya erişirse orucunu tutsun. Hasta olan ve yolcu bulunan, hastalığında, yolculuğunda orucunu yer, sonra yediği günler kadar tutar. Allah sizin için kolaylık diler, güçlük değil. Bu da sayıyı tamamlamanız, Allah''ın size doğru yolu göstermesine karşılık onu ululamanız içindir, böylece de ona şükretmiş olabilirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 186, 'Kullarım, sana beni sorarlarsa bilsinler ki ben, muhakkak onlara pek yakınım. Beni çağıran, bana dua eden kişiye çağırdığı, dua ettiği anda icabet ederim. Artık onlar da benim çağırmama koşsunlar, bana inansınlar da doğru yolu bulsunlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 187, 'Oruçlu olduğunuz günün gecesinde kadınlarınızla buluşmanız, size helal edilmiştir. Onlar sizin için elbisedir, siz onlar için elbisesiniz. Allah bildi ki nefsinizi yenemeyecek, sabredemeyecek, bir iştir, işleyeceksiniz, bu yüzden tövbenizi kabul etti, sizi bağışladı. Gayri onlarla buluşun ve Allah''ın size yazdığını dileyin. Fecir doğup da aydınlığıyla kara iplik, sizce beyaz iplikten ayırt edilinceye dek yiyin, için. Sonra orucu ertesi geceye kadar tamam olarak tutun. Fakat mescitlerde ibadet için niyetlendiniz, oturdunuz kaldınız mı kadınlarınıza dokunmayın. İşte bunlar, Allah sınırlarıdır, yaklaşmayın o sınırlara. İnsanlar, sakınıp korunsunlar diye Allah, delillerini bu suretle apaçık bildirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 188, 'Mallarınızı aranızda boş yere yemeyin. İnsanların bir kısım mallarını da günah ederek yemek için bilebile hakimlere mal vermeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 189, 'Sana yeni ayları sorarlarsa de ki: Onlar, insanlara vakitlerini bildirir, hac zamanı da onlarla bilinir. Sonra hayır, evlere arka taraflarından girmek değildir. Hayır sahibi, Allah''tan çekinendir. Evlere kapılarından girin. Allah''tan sakının ki kurtulmuş kimselerden olup muradınıza eresiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 190, 'Sizinle savaşıp vuruşanlarla Allah yolunda siz de savaşın, vuruşun, fakat haddi aşmayın, zulmetmeyin. Şüphe yok ki Allah, haddini aşanları ve zulmedenleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 191, 'Onları Nerede yakalarsanız öldürün. Sizi yurdunuzdan çıkardıkları gibi siz de onları yurtlarından çıkarın. Fitne, adam öldürmeden beterdir. Yalnız onlar, Mescidi Haram yanında sizinle savaşa kalkışmazlarsa siz de onlarla Mescidi Haram yanında savaşmayın. Ama onlar, sizi orada öldürmeye kalkışırlarsa öldürün onları. Budur kafirlerin cezası işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 192, 'Fakat vazgeçerlerse şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 193, 'Bir fitne kalmayıncaya, din tamamıyla Allah''ın dini oluncaya dek onlarla çarpışın. Vazgeçtiler mi artık düşmanlık, yalnız zalimleredir, başkalarına değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 194, 'Haram ay, haram aya bedel. Saygı karşılıklıdır. Şu halde kim size tecavüz ederse onun tecavüz ettiği gibi siz de ona saldırın, düşmanlara tecavüzde bulunun. Sakının Allah''tan ve bilin ki Allah, ancak kendisinden korunanlarla ve sakınanlarladır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 195, 'Mallarınızı Allah yoluna sarfedin, kendinizi, ellerinizle tehlikeye atmayın, iyilik edin. Şüphe yok ki Allah, iyilik edenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 196, 'Haccı ve umreyi de Allah için tamamlayın. Tamamlayamayacaksanız gücünüz yettiği kadar bir şey kurban edin ve kurbanı, yerinde boğazlayıncaya dek başınızı tıraş ettirmeyin. İçinizde hasta olan, başında bir eziyet bulunan varsa tıraş olur ve karşılığında oruç tutar, sadaka verir, yahut kurban keser. Sonra emin oldunuz, muktedir bulundunuz mu hac zamanına dek umre yapmak isteyen, gücü neye yeterse kurban eder. Buna imkan bulamayan üç gün hacda, yedi gün de dönünce oruç tutar, işte bu, tam on gündür. Bu da ayali Mescidi Haram''da olmayan içindir. Allah''tan sakının ve bilin ki şüphe yok, Allah''ın azabı çok şiddetlidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 197, 'Hac, malum aylarda olur. Kim o aylarda hacca niyet ederse bilsin ki hacda ne kadınla buluşma vardır, ne kötülükte bulunma, ne de kavga ve dövüş. Hayra dair ne işlerseniz Allah bilir. Yol azığı hazırlayın. Şüphe yok ki azıkların hayırlısı da sakınıp çekinmedir. Ey aklı eren temiz kişiler, sakının benden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 198, 'Rabbinizden rızık fazlalığı isteyerek ticarette bulunmanızda bir beis yok. Arafat''tan seller gibi boşanıp hep beraber inince de Meş''arülHaram''da Allah''ı anın. Hem de o, size doğru yolu nasıl gösterdi, onu anmanızı nasıl bellettiyse öyle anın. Bundan önce gerçekten de sapıklardandınız ya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 199, 'Sonra insanların, hep birden Arafat''tan döndüğü yerden siz de dönün, Allah''tan yarlıganmak dileyin. Şüphe yok ki Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 200, 'Hacca ait ibadetlerinizi bitirince babalarınızı andığınız gibi, hatta ondan da üstün bir surette Allah''ı anın. Çünkü insanlardan, Rabbimiz, bize dünyada ihsanda bulun diyenler vardır ki bu çeşit adama ahiretten nasip yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 201, 'Öylesi de vardır ki Rabbimiz der, dünyada da iyilik, güzellik ver, ahirette de iyilik ve güzellik, bizi ateşin azabından koru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 202, 'İşte kazançlarından nasibi olanlar bunlardır. Allah''ın hesap görmesi de pek tezdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 203, 'Sayılı hac günlerinde Allah''ı anın. İki gün içinde acele edip de dönmek isteyenlere suç yok. Geri kalanlara da suç yok ama sakınmak şartıyla. Allah''tan sakının ve bilin ki siz, şüphe yok onun tapısında haşr edileceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 204, 'İnsanlardan öylesi var ki dünya yaşayışı hakkında söylediği söz, seni şaşırtır, imrendirir, kalbindekine de Allah''ı tanık tutar. Halbuki o, düşmanların en yamanı, en inatçısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 205, 'Bir işe koyuldu mu yeryüzünde çalışır çabalar, orayı bozmak, ekini, soyu sopu helak etmek için uğraşır. Allah''sa fesadı sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 206, 'Ona, Allah''tan sakın, kork dendi mi suçla, günahla ululanmaya girişir. Cehennem gelir onun hakkından. Orası, gerçekten de ne kötü, ne pis yataktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 207, 'İnsanların öylesi de var ki Allah rızasına nail olmak için adeta kendisini satar, Allah rızasını alır. Allah kullarını pek esirger.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 208, 'Ey inananlar, hepiniz birden sulha, selamete girin, Şeytan''ın izini izlemeyin; şüphe yok ki o, size apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 209, 'Size bunca açık deliller geldikten sonra gene de ayağınız kayarsa artık bilin ki Allah, şüphesiz pek yüce ve üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 210, 'Yoksa onlar, Allah''ın, bulutların gölgelerinde, meleklerle gelivermesini ve işlerinin olup bitivermesini mi gözetirler? Halbuki bütün işler, döner, Allah''a varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 211, 'Sor İsrail oğullarına, onlara nice apaçık deliller getirdik. Kim Allah''ın nimetini, ona nail olduktan sonra tebdil ederse yok mu. Şüphesiz ki Allah''ın azabı ve mihneti pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 212, 'Kafir olanlara dünya yaşayışı, süslü gösterildi de inananların bir kısmıyla alay ediyorlar. Fakat Allah''tan sakınan iman sahipleri, kıyamet gününde onlardan üstündür. Allah, dilediğine sayısız nimet verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 213, 'İnsanlar tek bir ümmetti. Allah müjdeci ve korkutucu olarak peygamberler gönderdi. İnsanların ayrılığa düştükleri şeylerde, aralarında dosdoğru hükmetmek üzere onlara kitap da indirdi. Onlara bunca açık deliller geldikten sonra da gene ancak ihtirasları yüzünden tuttular da ihtilafa düştüler. Halbuki Allah inananları, onların ihtilafa düştükleri doğru şeye, kendi izniyle muvaffak etti, gerçeğe ulaştırdı. Allah, dilediğini doğru ve düz yola çıkarır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 214, 'Yoksa sizden öncekilerin örnek olan, ibret veren halleri, başınıza gelmeden cennete giriveririz mi sandınız? Onlar yoksulluklara uğradılar, zararlara düştüler, çetin sıkıntılara çattılar. Öylesine sürçtüler, öylesine kaydılar, sarsıldılar ki peygamber ve onunla beraber bulunan iman ehli bile, Allah yardımı ne vakit dediler. Bilin ki şüphe yok, Allah''ın yardımı yakındır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 215, 'Ne gibi nafaka vereceklerini, mallarını nereye sarfedeceklerini soruyorlar sana. De ki: Hayra ait sarf edeceğiniz şey, anaya, babaya, yakınlara, yetimlere, yoksullara, yolda kalanlaradır. Hayra dair ne yaparsanız şüphe yok ki Allah onu bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 216, 'Hoşlanmazsınız, size ağır gelir ama düşmanlarla savaşmak, size farz edilmiştir. Bazı şeyler vardır ki hoşlanmazsınız, fakat hayırlıdır size. Bazı şeyler de vardır, hoşlanırsınız, şerdir size. Allah bilir, siz bilmezsiniz ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 217, 'Sana, savaş haram olan ayda savaşı soruyorlar. De ki: O ayda savaş büyük bir günahtır. Fakat insanları Allah yolundan çıkarmak, onu inkar etmek, halkı Mescidi Haram''dan menetmek ve mescit ehlini, oradan çıkarmak, Allah katında daha büyük bir günahtır. Fitneyse adam öldürmeden de beterdir. Gücü yeterse sizi dininizden döndürmedikçe sizinle savaştan geri kalmaz onlar. Sizden birisi dininden döndü de kafir olarak öldü mü işlediği hayırlı işler, dünyada da heder olup gitmiş demektir, ahirette de. Onlardır ateş ehli, orada da ebediyen kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 218, 'İnananlar, Allah yolunda muhacir olanlar ve savaşanlarsa, onlar Allah rahmetini umarlar. Allah da suçları örtücüdür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 219, 'Sana şarap ve kumarın hükümlerini soruyorlar. De ki: İkisinde de hem büyük günah var, hem insanlara faydalar var; fakat günahları, faydalarından daha çok. Sonra mallarından neyi vereceklerini soruyorlar. De ki: Kendilerini sıkmayanını, sıkıntıya düşürmeyenini, fazlasını. İşte Allah, delillerini size böylece bildirir, ta ki düşünesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 220, 'Dünyada da, ahirette de. Yetimleri de soruyorlar. De ki: Onların hallerini düzene koymak, işlerine karışmamaktan hayırlıdır. Onlara karışır, onlarla uzlaşırsanız sonucu onlar da kardeşlerinizdir sizin. Allah, onların işlerini bozanı, düzgün bir hale getirenden ayırt eder, bilir. Allah dileseydi işinizi sarpa sardırırdı sizin. Şüphe yok ki Allah pek üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 221, 'Allah''a şirk koşan kadınları, imana gelmedikçe nikahlamayın. İman sahibi bir cariye bile sizi imrendiren bir müşrik kadından daha hayırlıdır. Şirk koşan erkeklere de kızlarınızı vermeyin. Müşrik, sizi imrendirse bile iman ehli bir kul, ondan hayırlıdır. Onlar, sizi ateşe çağırırlar, Allah''sa, izniyle cennete ve yarlıganmaya. Anarlar, hatırda tutarlar diye de insanlara delillerini apaçık bildirmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 222, 'Sana hayız hakkında da soruyorlar. De ki: O bir pisliktir. Hayız vaktinde kadınlardan çekilin, temizleninceye dek onlara yaklaşmayın. Temizlendiler mi Allah size nasıl emrettiyse öylece yaklaşın. Şüphe yok ki Allah, adamakıllı tövbe edenleri ve iyice temizlenenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 223, 'Kadınlarınız, tarlalarınızdır. Tarlalarınıza dilediğiniz gibi girin ve kendiniz için de önceden hazırlıkta bulunun. Allah''tan sakının ve bilin ki ona ulaşacaksınız. Müjdele inananları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 224, 'Ettiğiniz yeminlerden dolayı iyilik etmenize, sakınmanıza, insanların arasını bulmanıza Allah''ı engel etmeyin. Allah duyar ve bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 225, 'Allah, boş yere yemin ettiğiniz için sizi suçlu tutmaz, kalplerinizde, niyet yüzünden kazandığınız günah dolayısıyla sizi suçlu tutar. Allah suçları örter, ceza vermede acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 226, 'Kadınlarına yaklaşmamak için yemin edenler, dört ay beklerler. Erkekler, bundan vazgeçerlerse şüphe yok ki Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 227, 'Boşamayı kurmuşlarsa şüphe yok ki Allah duyar ve bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 228, 'Boşanan kadınlar, üç ay adet beklerler. Allah''a ve son güne inanmışlarsa Allah''ın, rahimlerinde yarattığını gizlemeleri helal değildir. Kocaları, bu müddet içinde barışmak isterlerse tekrar kadınlarını almaya tam hakları vardır. Aşırı ve eksik olmamak üzere kadınlar, kendi aleyhlerine olduğu gibi, lehlerine de hak sahipleridir. Ancak erkekler, kadınlardan üstündür. Allah yüce ve üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 229, 'Boşamak, iki defa olur. Ondan sonra ya güzellikle kadını tutmak gerek, ya hoşlukla bırakmak. Onlara verdiğinizden bir şey almak da helal değildir. Fakat erkek ve kadın, Allah sınırlarını koruyamayacaklarından korkarlarsa o başka. Siz de onların Allah sınırlarını muhafaza edemeyeceklerinden korkarsanız kadının, hakkından vazgeçmesinde ikisi için de günah yok. Bunlar, Allah''ın tayin ettiği sınırlardır, bunları aşmayın sakın. Kim Tanrı sınırlarını aşarsa o ve o çeşit adamlar, zalimin ta kendisi olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 230, 'Erkek, kadını bir kere daha boşayacak olursa bundan sonra kadın, başka bir kocaya varmadıkça eski kocasına helal olmaz. Kadını almış olan adam, onu boşarsa o vakit Allah''ın sınırlarını koruyacaklarına ümitleri varsa kadının, eski kocasına dönmesinde, tekrar evlenmelerinde bir beis yoktur. İşte bunlar, Allah sınırlarıdır ki bilen kavme açıklanmadadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 231, 'Kadınları boşadınız da boşandıktan sonraki müddetlerini geçirdiler mi artık onları ya iyilikle tutun, yahut hoşlukla salıverin. Haklarında aşırı muamelede bulunmak için zararlarına olarak onları zorla tutmayın. Bunu kim yaparsa ancak kendisine zarar eder. Allah''ın ayetlerini şaka sanmayın. Size verilen Allah nimetlerini, öğüt vermek için indirdiği kitabı ve ondaki hikmeti anın. Sakının Allah''tan ve bilin ki o, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 232, 'Kadınları boşadınız da zamanlarını geçirdiler mi aralarında güzellikle uzlaşırlarsa kocalarına varmalarına engel olmayın. Bu, içinizde Allah''a ve son güne inananlara verilmiş bir öğüttür. Bu, sizin için daha hayırlıdır, daha temiz bir iştir. Siz bilmezsiniz ama Allah bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 233, 'Analar, emzirme zamanını tamamlamak isterlerse tam iki yıl, çocuklarına süt verirler. Evlat sahibi olana da evladını emzirenin rızkını, elbisesini, örfe göre, vermesi borçtur. Kimseye gücünden fazla bir şey teklif edilemez. Ne ana evladından zarar görmeli, ne baba. Mirasçıya da hüküm aynıdır. Anayla baba, birbirleriyle danışırlar da, razı olurlar, çocuğu memeden kesmek isterlerse beis yok. Çocuklarınızı başkalarına emzirtmek isterseniz vereceğiniz şeyi güzelce, yollu yordamlı verdikten sonra artık size suç yoktur. Sakının Allah''tan ve bilin ki Allah, ne yaparsanız görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 234, 'İçinizden biri ölür de arkasında kadın bırakırsa bu çeşit adamların kadınları dört ay, on gün beklerler. Bu müddeti geçirdikten sonra meşru bir surette kendiliklerinden dilediklerine varabilirler, bu hususta size bir suç yoktur artık. Allah, ne yaparsanız, hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 235, 'Alacağınız kadınlara, onları alacağınızı anlatmanızda, yahut da bunu gizlemenizde bir beis yok. Allah bilir ki siz, onları anacak, hatırlayacaksınız. Yalnız onlarla gizlice de sözleşmeyin, doğru ve yolunda bir söz söylerseniz o başka. Farz olan müddet geçmedikçe nikah bağını bağlamaya kalkışmayın. Şüphe yok ki Allah, gönlünüzdekini de bilir, bundan dolayı çekinin ondan. Bilin ki Allah suçları örter, cezada acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 236, 'Kadınları, onlara dokunmadan, yahut nikah parası kesişmeden boşadınızsa beis yok. Ama onları da faydalandırın. Gücü yeten, gücü yettiği kadar, kudreti olmayan da kendi miktarınca ve örfe uygun olarak bir şey versin. Bu, ihsan sahiplerine bir borçtur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 237, 'Onlara dokunmadan boşarsanız nikah parası kesmiş olduğunuz takdirde kabul ettiğiniz paranın yarısını vermeniz gerek. Ancak kadın, hakkını bağışlar, yahut nikahın düğümü kimin elindeyse o, bu hakkı bahşederse bu ayrı. Sizin bağışlamanız, takvaya daha yakındır. Aranızdaki üstünlüğü unutmayın. Şüphe yok ki Allah, yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 238, 'Koruyun namazları, hele orta namazına çok dikkat edin ve Allah''a itaat ederek namaz kılın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 239, 'Korkuyorsanız yürüyerek, yahut hayvana binmiş olduğunuz halde kılın. Emniyete çıktınız mı bilmediğiniz şeyleri size belleten Allah''ı anın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 240, 'İçinizden ölüp de karısını geride bırakacaklara gelince, onlara, evlerinden çıkarmaksızın yılına kadar bir geçim vasiyet etmeleri gerek. Yok, eğer karıları evlerini bırakıp giderlerse yapacakları meşru bir şeyden dolayı size suç yok. Allah üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 241, 'Boşanan kadınlar için de artık ve eksik olmamak üzere bir şey vermek gerek. Bu da sakınanlara bir borçtur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 242, 'İşte Allah, aklınız ersin diye size ayetlerini böyle apaçık bildirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 243, 'Görmez misin ki binlerce kişi, ölümden çekinerek yurtlarından nasıl çıktılar da sonra Allah onlara ölün dedi, sonra da diriltti onları. Şüphe yok ki Allah, insanlara karşı ihsan sahibidir ama insanların çoğu şükretmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 244, 'Allah yolunda vuruşun, savaşın ve bilin ki Allah, şüphesiz duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 245, 'Kimdir o ki Allah''a güzel bir surette borç versin de Allah onu, o kimseye fazlasıyla ve kat kat ödemesin? Allah daraltır da, ferahlatır da. Hepiniz de sonunda ona dönüp ulaşacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 246, 'Görmez misin İsrailoğullarının ileri gelenlerini? Hani Musa''dan sonra bir zaman geldi ki peygamberlerine, bize bir padişah gönder de ona uyup Allah yolunda savaşa girişelim demişlerdi. Peygamberleri, size savaş farz edilir de savaşmayıverirseniz demişti. Neden savaşmayacakmışız demişlerdi, yurtlarımızdan çıkarıldık, evladımızdan ayırdılar bizi. Fakat savaş farz edilince pek azı katlandı, öbürleri dönüverdiler. Allah bilir zalimleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 247, 'Peygamberleri, Allah size padişah olarak Talut''u gönderdi dedi. Nasıl olur da dediler, bize buyruk yürütür o? Bizim ondan ziyade padişahlığa hakkımız var, malca da bizden üstün değil. Peygamberleri, şüphe yok ki dedi, onu Allah seçmiş sizden üstün etmiş, ona bilgi ve vücut bakımından üstünlük vermiştir. Allah, mülkünü dilediğine verir. Allah''ın rahmeti boldur, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 248, 'Gene peygamberleri demişti ki: Onun padişahlığının apaçık alameti, Rabbinizden size itminan ve sükun veren, içinde, Musa ile Harun soyundan artakalanlar bulunan ve melekler tarafından taşınan tabutla gelmesidir. İnanmışsınız işte bunda, size kesin bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 249, 'Talut, orduyla harekete geçince dedi ki: Allah sizi bir ırmakla sınayacak. Kim o ırmağın suyundan içerse benden değil, onu tatmayan benden. Yalnız eliyle bir avuç su alana söz yok. Irmağa gelince hemen hepsi içti, içlerinden pek azı içmedi. Talut ve onunla beraber bulunan inananlar, o ırmağı geçince, bizim bugün Calut''la ordusuna karşı duracak takatimiz yok dediler. Allah''a kavuşacaklarını umanlarsa nice azlık taife vardır ki dediler, Allah''ın izniyle çokluk taifeye üst olmuştur, Allah sabredenlerledir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 250, 'Calut''la ordusuna karşı çıkınca da Rabbimiz dediler, sen bize sabırlar ver, ayaklarımızı diret, bizi kafirlere üstün et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 251, 'Allah''ın izniyle onları bozdular. Davud da Calut''u öldürdü. Allah, kendisine saltanat ve hikmet ihsan etti, dilediği bazı şeyleri de belletti. Allah insanları, birbiriyle savıp gidermeseydi yeryüzü mutlaka bozulup giderdi fakat Allah''ın alemlere ihsanı var, lütfü var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 252, 'İşte bunlar, Allah''ın delilleridir. Onları sana hakkıyla okumadayız ve muhakkak ki sen, gönderilenlerdensin, peygamberlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 253, 'O peygamberlerden bazısını bazısına üstün ettik. Onlardan Allah''la konuşan var, bazılarının da derecelerini yüceltmiştir. Meryemoğlu İsa''ya apaçık deliller verdik, onu, RuhulKudüs''le kuvvetlendirdik. Allah dileseydi onlardan sonrakiler, kendilerine apaçık deliller geldikten sonra artık birbirlerini öldürmezlerdi. Ama gene de aykırılığa düştüler. İçlerinde inanan var, inanmayan var. Allah dileseydi birbirlerini öldürmezlerdi, fakat Allah dilediğini, dilediği gibi yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 254, 'Ey inananlar, sizi rızıklandırdığımız şeylerden bir kısmını yoksullara harcayın o gün gelip çatmadan ki o gün ne alışveriş var, ne dostluk, ne şefaat. Kafirlere gelince onlardır zalimler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 255, 'Öyle bir Allah ki ondan başka yoktur tapacak. Diridir, her an yarattıklarını tedbir ve tasarruf edip durur. Ne uyuklamaya kapılır, ne uykuya dalar. Onundur ne varsa göklerde ve yeryüzünde. Kimdir izni olmadıkça onun yanında şefaate kalkışacak? Önlerindekini de bilir, artlarındakini de. Onun bilgisinden, dilediği miktardan başka hiçbir şeyi kavrayamazlar. Kürsüsü gökleri de kaplayıp kucaklamıştır, yeryüzünü de. Göğü, yeri korumak, ona ağır da gelmez. O''dur çok yüce ve çok ulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 256, 'Dinde zor yok. Gerçekten de doğru yolla azgınlık apaçık meydana çıkmıştır. Kim putları inkar edip Tanrı''ya inanırsa şüphe yok, öyle sağlam bir kulpa yapışmıştır ki hiç kopmaz o ve Allah her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 257, 'Allah, dostudur inananların. Onları karanlıklardan ışığa çıkarır. İnanmayanlarınsa dostları Şeytan''dır, onları ışıktan karanlıklara götürür. Onlardır ateş ehli, onlardır orada ebedi kalanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 258, 'Kendisine Allah''ın saltanat verdiği kişinin, İbrahim''le çekişmeye başladığını görmedin mi? O zaman İbrahim, benim Rabbim diriltir, öldürür demişti. O, ben de diriltirim, öldürürüm dedi. İbrahim dedi ki: Şüphe yok ki Allah, güneşi doğudan çıkarmada, sen batıdan doğdur. İnanmayan, bu söze şaşırıp kalmıştı. Allah zalim kavmi doğru yola sevketmez ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 259, 'Bir de hani yapıları çökmüş, çatıları döşemelerinin üstüne yıkılmış şehre uğrayan, Allah bu şehri, ölümünden sonra nasıl diriltecek ki demişti. Allah, onu tam yüz yıl ölü bir halde bırakmış, sonra diriltmişti de demişti ki: Ne kadar yattın? O da bir gün, yahut günün birkaç saati kadar bir müddet demişti. Allah, tam yüz yıl yata kaldın. Yiyeceğine, içeceğine bak, henüz bozulmamış bile. Eşeğine de bak; bu iş seni, insanlara bir delil göstermek maksadıyla oldu; eşeğin kemiklerini nasıl birleştiriyor, sonra onlara nasıl et giydiriyoruz, hele dikkat et demişti. Bu, ona apaçık belli olunca dedi ki: Bilirim, şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 260, 'An o zamanı da, hani İbrahim, Rabbim demişti, ölüyü nasıl diriltirsin? Allah, inanmıyor musun demişti de İbrahim, evet, inanıyorum ama kalbim tam yatışsın, iyice anlayayım demişti. Allah da demişti ki: Dört kuş al, onları kesip paramparça et, parçalarını birbirine kat, sonra o karışık parçalardan her birini bir dağın üstüne koy, sonra da onları çağır, koşarak sana gelecekler. Bil ki Allah, şüphe yok ki pek yücedir, hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 261, 'Mallarını Allah yolunda harcayanlar, her başağında yedi yüz tanesi olan ve tam yedi tane başak bitiren tek bir tohuma benzer. Allah dilediğine kat kat verir, arttırır. Allah''ın ihsanı boldur ve her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 262, 'Mallarını verip ardından da, verdiklerinin başlarına kakmayanların, onlara minnet yüklemeyen ve eziyette bulunmayanların ecri, Rableri katındadır. Onlara ne korku vardır, ne hüzün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 263, 'Güzel söz ve suç bağışlama, ardında minnet olan sadakadan hayırlıdır. Allah müstağnidir, ceza vermede acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 264, 'Ey inananlar, malını insanlara gösteriş için harcayan ve Allah''a, ahiret gününe inanmayan kişi gibi sadakalarınızı, başa kakmakla minnet ve eziyetle hiç verilmemiş bir hale getirmeyin. O çeşit adam, sanki şiddetli bir yağmur altında kalıp üstündeki toprağın kayarak sıvışmasıyla kaypak bir hale gelen kayadır. O çeşit adamlar, kazançlarından hiçbir sevap elde edemezler ve Allah, inanmayan kavmi doğru yola sevk etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 265, 'Mallarını, Tanrı rızasını kazanmak ve özlerindekini yerli bir hale getirip kendilerine mal etmek için verenlerse bir tepedeki bahçeye benzerler; bolbol yağan yağmur, o bahçenin meyvelerini iki misline çıkarır. Hatta bu çeşit yağmur yağmasa bile mutlaka bir çisentiye kavuşur orası ve Allah, bütün yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 266, 'Biriniz arzular mı ki onun bir hurma fidanlığı, bir üzüm bağı olsun, kıyısından ırmaklar aksın, o fidanlıkta, o bağda bütün meyveler yetişsin, kendisi de ihtiyarlığa düşsün, küçük ve aciz dölüdöşü bulunsun da tam bu çağda fidanlığına, bağına, yakıp kavurucu bir sam yeli gelip çatsın, bahçe ve bağ, yanıp mahvolsun? İşte Allah, düşünürsünüz diye size delillerini böyle açıklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 267, 'Ey inananlar, kazandığınız temiz şeylerden, yeryüzünden sizin için çıkardığımız nesneleri verin, görmemek için gözlerinizi yummadan ele alamayacağınız bayağı ve aşağılık şeyleri değil ve bilin ki Allah, müstağnidir ve tam hamda layık olan odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 268, 'Şeytan, sizi yoksulluğa çağırır, size kötülüğü buyurur. Allah''sa yarlıgamasına, ihsanına davet eder ve Allah''ın ihsanı boldur, her şeyi o bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 269, 'Dilediğine hikmet ihsan eder ve kime hikmet ihsan ederse şüphe yok ki o, çok hayra nail olmuş demektir, fakat bunu, aklı başında olanlardan başkaları düşünmez bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 270, 'Ne sadaka verir ve ne adak adarsanız şüphe yok ki Tanrı, bilir onu ve zalimlere hiçbir yardımcı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 271, 'Sadakalarınızı açık verirseniz ne hoş, fakat gizlice yoksullara verecek olursanız bu, size daha hayırlıdır ve bu, günahlarınızın karşılığı olur; Allah ne yaparsanız hepsinden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 272, 'Onları doğru yola götürmek sana ait değil. Fakat Allah dilediğine doğru yolu gösterir. Hayra ait bir şey verirseniz bunun faydası size. Zaten yoksullara vermeniz de ancak Allah rızası içindir. Hayır yapmak için verdiğiniz şey, size fazlalaştırılır ve siz zulüm görmezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 273, 'Verilen şeyler, kendilerini tamamıyla Allah yoluna vermiş olup yeryüzünde dolaşamayan yoksullara aittir. Bilmeyen kişi, onların istiğnalarını görüp zengin sanır, halbuki sen, yüzlerinden tanırsın onları. Yüzsuyu dökerek halktan bir şey istemez onlar. Hayır için ne harcarsanız şüphe yok ki Allah, onu bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 274, 'Mallarını gece ve gündüz, gizli ve açık harcayanlar yok mu, onların ecirleri, Rableri katındadır ve onlara ne korku vardır, ne de mahzun olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 275, 'Faiz yiyenler, ancak Şeytan tarafından çarpılmış gibi bir hale geliverirler. Bu da onların, alışveriş de faiz almaya benzer, onun eşidi demelerindendir. Allah, alışverişi helal etti, faizi haram. Rabbinden kendisine öğüt verilen, faizden vazgeçerse eskiden aldıkları ona aittir, işi de Allah''a ait. Fakat bundan sonra gene tutup faiz alanlar, ateş ehlidir, orada da ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 276, 'Allah faizi eksiltir, sadakalarıysa arttırır ve Allah, fazlasıyla inkara düşüp çok suç işleyenlerin hiçbirini sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 277, 'İnananlara, iyi işler yapanlara, namaz kılanlara, zekat verenlere gelince: Onların ecirleri Rableri katındadır, onlara ne korku vardır, ne hüzün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 278, 'Ey inananlar, Allah''tan sakının ve artık almadığınız faizleri bırakın inancınız varsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 279, 'Bunu yapmazsanız bilin ki Allah''la ve Peygamberiyle savaşa giriştiniz. Tövbe ederseniz anamalınız sizindir, ne zulmedersiniz, ne zulüm görürsünüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 280, 'Borçlu dardaysa genişleyinceye dek mühlet verin ona. Borcunuzu sadaka olarak bağışlarsanız bu, bilseniz, sizin için daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 281, 'Sakının o günden ki dönüp Allah''a ulaşacaksınız, sonra da herkese kazancının karşılığı verilecek ve onlara zulmedilmeyecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 282, 'Ey inananlar, muayyen bir müddet için borçlandığınız vakit bunu mutlaka yazın. Aranızda bir yazıcı bulunsun ve bunu dosdoğru yazsın. Yazıcı, Allah kendisine nasıl bellettiyse öylece yazmaktan çekinmesin borçlanan da yazdırsın, onu geliştiren Allah''tan çekinsin de hiçbir noktayı eksik bırakmasın. Borçlu, akılsız biriyse, yahut aklı azsa, yazdırmaya gücü yetmezse velisi, doğru olarak yazdırsın. Adamlarınızdan iki erkeği de bu muameleye tanık tutun. İki erkek olmazsa biri unuttuğu vakit öbürünün hatırlatması için razı olacağınız kimselerden bir erkekle iki kadın tanık olsun. Tanıklar da, çağrıldıkları vakit kaçınmasınlar. Az olsun, çok olsun, muayyen müddete kadar verilen borcu yazmaktan üşenmeyin. Bu, Allah katında daha ziyade adalete uyan, tanıklık için daha sağlam olan, tereddüde ve şüpheye düşmemenize daha ziyade yarayan bir şeydir. Ancak peşin alışverişte bulunuyor, malı, aranızda elden ele devrediyorsanız onu yazmamakta bir suç yok size. Alışverişte de tanık bulunsun, yazan da hiç zarar görmesin, tanık da. Zarar verirseniz bu, şüphe yok ki bir isyandır sizin için. Sakının Allah''tan, Allah size öğretmededir ve Allah, her şeyi tamamıyla bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 283, 'Eğer bir yolculuktaysanız, katip de bulamadınızsa alınan rehin de kafi. Birbirinize emniyetiniz varsa emniyet edilen borçlu, kendisini geliştiren Allah''tan sakınsın da emanetini tamamıyla ödesin ve tanıklığı gizlemeyin. Kim gizlerse şüphe yok, kalbi günaha batar ve Allah yapıklarınızı tamamıyla bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 284, 'Allah''ındır göklerde ne varsa ve yeryüzünde ne varsa. İçinizdekini açıklasanız da, gizleseniz de Allah, onunla sizi hesaba çeker. Dilediğini yarlıgar, dilediğini azaplandırır ve Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 285, 'Peygamber de kendisine Rabbinden indirilene inanmıştır, inananlar da. Hepsi de Allah''a, meleklerine, kitaplarına, peygamberlerine inanmıştır. Peygamberlerinden hiçbirini öbüründen ayırmayız, duyduk demişlerdir ve itaat ettik, Rabbimiz, yarlıganma dileriz senden, varacağımız yer, tapındır senin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (2, 286, 'Allah, hiç kimseye gücünün yeteceğinden fazla bir şey teklif etmez. Herkesin kazandığı sevap kendisine aittir, elde ettiği suç gene kendisine ait. Rabbimiz, bizi muaheze etme unuttuysak, yahut yanıldıysak. Rabbimiz, bize ağır yük yükleme bizden öncekilere yüklediğin gibi. Rabbimiz, yükleme gücümüzün yetmeyeceği şeyi. Bağışla bizi, yarlıga bizi, acı bize, sensin yardımcımız, artık yardım et bize inanmayanlara karşı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 1, 'Elif lam mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 2, 'Öyle bir Allah''tır ki yoktur ondan başka tapacak; diridir, daimi olarak mahlukatının işlerini tedbir ve her şeyi tasarruf eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 3, 'Kitabı, sana gerçek ve ellerinde bulunanı gerçekleyici olarak indirdi, Tevrat ve İncil''i de indirdi', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 4, 'Evvelce, insanlara hidayet olarak, gerçekle batılı ayırt eden kitabı da indirdi. Tanrı ayetlerine inanmayanlardır çetin azap ve Allah öyle üstün bir kudret sahibidir ki aman vermez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 5, 'Şüphe yok ki ne yeryüzünde bir şey Allah''a gizli kalır, ne gökyüzünde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 6, 'O, size, daha analarınızın karnındayken dilediği gibi şekil verir. Yoktur ondan başka üstün, hüküm ve hikmet sahibi tapacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 7, 'Öyle bir Tanrı''dır ki sana kitap indirdi. Onun bir kısmı, manasıapaçık ayetlerdir ve bunlar, kitabın temelidir. Diğer kısmıysa çeşitli manalara benzerlik gösterir ayetlerdir. Yüreklerinde eğrilik olanlar, fitne çıkarmak ve onları tevil etmek için manaları açık olmayan ayetlere uyarlar. Halbuki onların tevilini ancak Allah bilir. Bilgide şüpheleri olmayacak kadar kuvvetli olanlarsa derler ki: Biz inandık ona, hepsi de Rabbimizdendir; bunu aklı tam olanlardan başkaları düşünemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 8, 'Rabbimiz, bizi doğru yola sevk ettikten sonra kalplerimizi saptırma ve kendi katından bize rahmet bağışla, şüphe yok ki sen, fazlasıyla bağışlayansın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 9, 'Rabbimiz, muhakkak sen, geleceğinde şüphe bulunmayan günde insanları toplayansın. Şüphe yok ki Allah, vaadinden dönmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 10, 'Kafir olanları, Allah katında, ne malları birşeyden kurtaRabilir, ne evlatları. Onlardır ateşin yakacağı kişiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 11, 'Firavun soyu ve ondan öncekiler gibi hani. Âyetlerimizi yalanladılar, Allah da onları suçlarıyla alıverdi ve Allah''ın cezası çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 12, 'Kafirlere de ki; Yakında alt olacaksınız, cehennemde toplanacaksınız ve orası ne kötü bir yatılacak yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 13, 'İbretti size birbirleriyle karşılaşan o iki bölüğün hali. Bir bölük, Allah yolunda savaşmadaydı, öbürüyse kafirdi ve inananları, gözleriyle iki misli görmedeydiler. Allah, dilediğini yardımıyla kuvvetlendirir ve şüphe yok ki bunda, görenlere kesin bir ibret var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 14, 'Kadınlara, oğullara, yığın yığın biriktirilmiş altın ve gümüşlere, güzel ve cins atlara, hayvanlara ve ekinlere karşı insanların aşırı sevgisi vardır ve bu sevgi, insanlar için bezetilmiş bir sevgidir. Fakat bunlar, dünya yaşayışına ait birer matahtan ibarettir. Sonucu varılıp gidilecek yerin güzelliğiyse ancak Tanrı katındadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 15, 'De ki: Size bunlardan daha hayırlısını haber vereyim mi: O da, sakınanlar için, ebedi olan ve kıyılarından ırmaklar akan, içinde tertemiz eşler bulunan bahçelerdir ve Allah''ın sizden razı oluşudur. Allah, kullarını görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 16, 'Onlar öyle kişilerdir ki Rabbimiz derler, inandık, suçlarımızı yarlıga ve bizi koru ateşin azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 17, 'Onlar, sabredenler, gerçekler, itaat eyleyenler, mallarını yoksullara harcayanlar ve seher çağlarında, suçlarının yarlıganmasını dileyenlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 18, 'Allah, kesin olarak bildirdi ki kendisinden başka yoktur tapacak. Meleklerle bilgi sahipleri de tam bir doğrulukla bunu bildiler, bildirdiler. O üstün Tanrıdan, o hüküm ve hikmet sahibinden başka yoktur tapacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 19, 'Allah katında din, ancak İslam dinidir. Kendilerine kitap verilenler, bunu adamakıllı bildikten sonra aralarındaki azgınlık ve haddini aşma yüzünden ihtilafa düştüler ve kim Allah''ın ayetlerine inanmazsa bilsin ki Allah, pek tez hesap görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 20, 'Seninle çekişirlerse hemen de ki: Ben ve bana uyanlar, özümüzü Allah''a teslim ettik. Kendilerine kitap verilenlerle analarından doğdukları gibi kalanlara de ki: Siz de teslim oldunuz mu? Özlerini Allah''a tapşırırlar, İslam dinini kabul ederlerse şüphe yok ki doğru yolu bulmuş olurlar. Yüz çevirirlerse sana düşen ancak bildirmedir ve Allah, kullarını görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 21, 'Allah''ın ayetlerini inkar edip haksız yere peygamberleri öldürenlere, insanlardan, doğruluğu emredenlerin canlarına kıyanlara gelince: Onları elemli bir azapla müjdele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 22, 'Onlardır bütün yaptıkları, dünyada da boşa gidenler, ahirette de. Bir tek yardımcıları bile yoktur onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 23, 'Görmez misin kitaptan, kendilerine bir pay verilenleri; aralarında hakemlik etsin diye Allah''ın kitabına çağrılırlar da sonra onların bir kısmı arkalarını çevirir; onlar zaten bunu adet edinmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 24, 'Bu da, sayılı günlerden başka ateşte kalmayız demelerindendir. Kendi uydurmaları olan bu kanaat, onları dinlerinde de aldatmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 25, 'Onları toplayıverdiğimiz gün ne olacak halleri? O günün geleceğinde hiç şüphe yok ve o gün herkese kazancının karşılığı verilecek, zulmedilmeyecek onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 26, 'De ki: Allah''ım, mülkün sahibi sensin, mülkü dilediğine verirsin, dilediğinden alırsın. Dilediğini yükseltirsin, dilediğini alçaltırsın. Senin elindedir hayır, sensin her şeye gücü yeten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 27, 'Geceyi uzatırsın, gündüzün bir kısmı gece olur. Gündüzü uzatırsın, gecenin bir kısmı gündüz olur. Ölüden diri çıkarırsın, diriden ölü izhar edersin ve dilediğini sayısız rızıklandırırsın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 28, 'İnananlar iman edenleri bırakıp da kafirleri dost edinmesinler. Bu işi yapan, Allah''tan bir şey beklemesin, fakat kafirlerden çekinmeniz gerekse o başka. Allah, kendisinden sakınmanızı emretmektedir ve dönüp varılacak yer de Allah tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 29, 'De ki: Gönlünüzdekini gizleseniz de Allah bilir, açığa vursanız da. Göklerde ve yeryüzünde ne varsa bilir ve Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 30, 'O gün bir gündür ki herkes, yaptığı hayrı hazırlanmış bir halde karşısında bulacak, işlediği kötülükle de arasında pek uzun bir mesafe olmasını arzulayacak. Tanrı, kendinden korunmanızı buyurur ve Allah, kullarını pek esirgeyicidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 31, 'De ki: Allah''ı seviyorsanız bana uyun da Allah da sizi sevsin ve suçlarınızı yarlıgasın. Allah yarlıgayıcıdır ve rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 32, 'De ki: Allah''a ve Peygambere itaat edin. Fakat yüz çevirirlerse Allah da kafirleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 33, 'Şüphe yok ki Allah, Âdem''i, Nuh''u, İbrahim soyunu ve İmran soyunu seçti, alemlere üstün etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 34, 'Birbirlerinden türemiş bir soydur onlar ve Allah duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 35, 'An o zamanı ki İmran''ın zevcesi, ya Rabbi demişti, karnımdakini, azatlı bir kul olmak üzere sana adadım, kabul et. Şüphe yok ki sen duyarsın, bilirsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 36, 'Doğurunca da ya Rabbi demişti kız doğurdum; zaten Tanrı, onun ne doğurduğunu biliyordu; erkek kıza benzemez, ona Meryem adını verdim, onu da, soyunu da sana ısmarladım, taşlanmış Şeytan''dan sen koru demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 37, 'Rabbi, onu iyi bir surette kabul etti, bir nebat yetiştirir gibi onu yetiştirdi, geliştirdi, Zekeriyya''yı da onun hizmetine memur etti. Zekeriyya, ne vakit mihRaba girse yanında bir yiyecek bulurdu. Ya Meryem demişti, bunlar nereden geliyor sana? Meryem, Allah''tan demişti, şüphe yok ki Allah dilediğini sayısız rızıklarla rızıklandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 38, 'Zekeriyya, orada Rabbine dua etmiş, ya Rabbi demişti, sen katından tertemiz bir soy ver bana, muhakkak ki duaları duyansın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 39, 'Mihrapta durmuş, namaz kılıyordu ki melekler, gerçekten de Allah, sana Yahya''yı müjdelemededir. O, Tanrıdan gelen sözü tasdik eden bir erdir, uludur, kötülüklerden tamamıyla çekinmiştir, iyilerden ve doğrulardan bir peygamberdir o diye nida etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 40, 'Zekeriyya, Rabbim demişti, benim nasıl oğlum olabilir ki ihtiyarlık, üstüme çökmüştür, karım da kısır. Böyle de olsa demişti, Allah dilediğini yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 41, 'Zekeriyya demişti ki: Rabbim, bana bir delil ver. Allah da, insanlarla işaretleşmen ayrı, tam üç gün, konuşmaman onlarla, delildir sana. Çok an Rabbini, akşam ve sabah çağlarında, onun noksan sıfatlardan arı olduğunu söyle demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 42, 'An o zamanı da, hani melekler Meryem''e, ya Meryem, Allah gerçekten de seni seçti, arıttı ve alemlerdeki kadınlara üstün etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 43, 'Ya Meryem, Rabbine itaat et, secdeye kapan, rüku edenlerle rüku et demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 44, 'Bunlar, gaibe ait haberler ki sana vahyetmekteyiz. Meryem''i yetiştirmeyi tekeffül edecek kimdir diye kura çekmek için kalemlerini attıkları zaman da yanlarında değildin, bu hususta çekiştikleri zaman da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 45, 'Hani melekler, ya Meryem, gerçekten de Allah seni, kendisinin bir kelimesiyle müjdelemektedir adı da Meryemoğlu Mesih İsa''dır onun ve o, dünyada da kadri yüce bir erdir, ahirette de ve yakınlardandır o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 46, '- Beşikteyken de, olgunluk çağındayken de insanlarla konuşacaktır ve o, temiz kişilerdendir demişti de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 47, 'Meryem, ya Rabbi demişti, benim nasıl çocuğum olabilir? Bana hiçbir insan dokunmadı. Allah, öyledir ama demişti, dilediğini yapar Allah ve bir işin olmasını diledi mi hemencecik ol der ona ve o oluverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 48, 'Tanrı ona bilgiyi, hikmeti, Tevrat''ı, İncil''i öğretir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 49, 'İsrailoğullarına peygamber olarak gönderir, o da onlara der ki: Ben, Rabbinizden delille geldim size. Balçığı yoğurur, kuş şekline sokar, ona üflerim, Allah''ın izniyle kuş olur. Anadan doğma körü körlükten kurtarırım, abraş illetine tutulmuşu, Allah''ın izniyle iyileştiririm ve Allah''ın izniyle ölüyü diriltirim, evlerinizde yediklerinizi, sakladıklarınızı size bildiririm. İnanmışsanız şüphe yok ki, bunlar size delildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 50, 'Tevrat''ın gerçekliğini söylemekte, size haram edilen bazı şeyleri helal etmekteyim, Rabbinizden delillerle geldim. Sakının Tanrıdan da bana itaat edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 51, 'Şüphe yok ki Allah, benim de Rabbimdir, sizin de Rabbiniz; ona kulluk edin, budur doğru yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 52, 'İsa, onların küfrünü duyunca dedi ki: Kimlerdir Allah uğrunda yardımcılarım? Havariler, biziz Allah için yardım edenler dediler, Allah''a inandık, sen de tanık ol ki, biz, ona teslim olanlarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 53, 'Rabbimiz, inandık indirdiğine, uyduk Peygambere, bizi buna tanık olanlarla haşret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 54, 'Düzene koyuldular, Allah da düzenlerine karşılık cezalarını verdi. Allah, düzencilere ceza verenlerin hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 55, 'Hani o zaman Allah ya İsa demişti, seni öldürecek de benim, kendime yüceltecek de, kafirlerden kurtarıp arıtacak da. Sana uyanları kıyamete dek kafirlere üst edeceğim. Sonra, dönüp geleceğiniz yer, benim tapımdır, aranızda, aykırılığa düştüğünüz şeylerin hükmünü de ben vereceğim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 56, 'Kafir olanlara gelince: Onları dünyada da çetin bir azapla azaplandıracağım, ahirette de ve onlara hiçbir yardımcı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 57, 'İnananlar ve iyi işlerde bulunanlarsa ecirlerini tam olarak alırlar. Allah zulmedenleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 58, 'Bunları, sana ayetlerimizden ve doğrulukla hükmeden Kur''an''dan okuyoruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 59, 'Gerçekten de Allah katında İsa, Âdem''in örneğidir, onu topraktan yarattı da sonra ol dedi, oluverdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 60, 'Gerçek, Rabbindendir, şüphe edenlerden olma artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 61, 'Sana iyice bildirildikten sonra da gene bu hususta seninle tartışan olursa de ki: Gelin, oğullarımızı ve oğullarınızı, kadınlarımızı ve kadınlarınızı çağıralım, biz bizzat gelelim, siz de gelin. Ondan sonra da dua edelim ve Allah''ın lanetini yalancılara havale edelim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 62, 'İşte budur gerçek söz: Allah''tan başka yoktur tapacak ve şüphe yok ki Allah, üstündür, hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 63, 'Gene yüz çevirirlerse muhakkak ki Allah bozguncuları bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 64, 'De ki: Ey kitap ehli, gelin aramızda eşit olan tek söze: Ancak Allah''a kulluk edelim, ona hiçbir şeyi eş ve ortak etmeyelim, Allah''ı bırakıp da bazılarımız, bazılarımızı Tanrı tanımayalım. Gene de yüz döndürürlerse deyin ki tanık olun, özümüzü Tanrıya teslim edenleriz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 65, 'Ey kitap ehli, ne diye İbrahim hakkında çekişip tartışırsınız? Tevrat da ondan sonra inmiştir, İncil de. Akıl etmiyor musunuz ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 66, 'Şöyleböyle bilginiz olan şeye dair tartışıp duruyorsunuz ama hiç bilginiz olmayan şeyde de ne diye tartışmaya kalkışırsınız? Allah bilir, siz bilmezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 67, 'İbrahim ne Yahudi''ydi, ne Nasrani. Dosdoğru Müslüman''dı ve müşriklerden değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 68, 'İbrahim''e gerçekten de en yakın olanlar, ona inananlarla bu Peygamberdir ve iman edenlerdir. Allah, inananların dostu ve yardımcısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 69, 'Kitap ehlinin bir bölüğü, yolunuzu sapıtmak ister. Halbuki sizi değil, ancak kendilerini yoldan çıkarırlar, kendileri sapıklığa düşerler de farkında değillerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 70, 'Ey kitap ehli, Allah''ın ayetlerini neden inkar edersiniz, halbuki onları görüp duruyorsunuz da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 71, 'Ey kitap ehli, ne diye hakkı batılla karıştırıyor, gerçeği gizliyorsunuz? Halbuki biliyorsunuz da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 72, 'Kitap ehlinin bir bölüğü de dedi ki: İman edenlere indirilene gündüzün inanın, akşam üstü inanmayın, kafir olun, belki iman edenler de inançlarından dönerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 73, 'Ve dininize uyan kişiden başkasına inanmayın. De ki: Doğru yol, ancak Allah yoludur. Size verilenin başkalarına da verildiğine ve onların, Rabbiniz katında deliller göstererek sizinle tartışacaklarına inanmayın dediler mi de, de ki: Lütuf ve ihsan ancak Allah''ın elindedir, dilediğine lütfeder ve Allah''ın lütfü boldur ve her şeyi bilir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 74, 'Dilediğini rahmetiyle tahsis eder ve Allah, büyük bir lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 75, 'Kitap ehlinin içinde öylesi vardır ki ona bir kantar altın emanet etsen onu, olduğu gibi öder. Öylesi de vardır ki bir altın emanet etsen ayak direyip ısrar etmedikçe geri vermez. Bu da, okumayazma bilmeyenlerin mallarını almada bir vebal yok bize demelerindendir. Bile bile Allah''a karşı yalan söylerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 76, 'Yok, öyle değil iş. Kim ahdine vefa eder ve ondan sakınırsa bilsin ki gerçekten de Allah sakınanları sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 77, 'Allah''a verdikleri sözü ve onun adına, etmiş oldukları yeminleri, değeri az bir mataha değişenler yok mu, onlardır ahirette nasibi olmayanlar ve Allah, kıyamet gününde onlarla konuşmaz, yüzlerine bile bakmaz, onları arıtmaz ve onlar içindir elemli bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 78, 'Kitap ehlinin bir bölüğü de kitaptan bir şey okuyorlarmış zannına kapılmanız için dillerini oynatıp dururlar, halbuki okudukları, kitapta yoktur. Bu, Allah katındandır derler, değildir Allah katından ve bile bile Tanrıya bühtan ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 79, 'Hiçbir insana yakışmaz ki Allah, ona kitap, hüküm ve peygamberlik versin de sonra o, insanlara, Tanrıyı bırakın da bana kul olun desin. Ancak öğretmekte, okumakta ve okumakta olduğunuz kitaba uyup Rabbani olun der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 80, 'Meleklerle peygamberleri Tanrı tanıyın diye de emretmez. Artık siz Müslüman olduktan sonra küfrü emreder mi size?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 81, 'An o zamanı ki Allah, peygamberlerden, size kitap ve hikmet verdim, sonra da sizdeki kitabı gerçekleyen bir peygamber göndereceğim, ona mutlaka inanacaksınız, mutlaka yardım edeceksiniz diye söz almıştı ve ikrar ettiniz mi, size yüklediğim bu ağır yükü aldınız, yüklendiniz mi demişti. İkrar ettik demişlerdi de o da öyleyse tanık olun demişti, ben de sizinle beraber tanıklık edenlerdenim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 82, 'Bundan sonra kim dönerse o çeşit kişilerdir kötülükte bulunanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 83, 'Artık Allah''ın dininden başka bir din mi arıyorlar? Göklerde ve yeryüzündekiler, istekleriyle ve zorla ona teslim olmuşlardır ve her şey de, sonucu, gerisin geriye, dönüp onun tapısına varacaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 84, 'De ki: İnandık Allah''a ve bize indirilene, İbrahim''e, İsmail''e, İshak''a, Yakup''a, torunlarına indirilene. Musa''ya, İsa''ya ve peygamberlere, Rablerinden verilene; aralarından hiçbirini ayırt etmeyiz ve biz, ona teslim olmuşuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 85, 'Kim Müslümanlıktan başka bir din arar, dilerse arayıp bulduğu din, asla makbule geçmez ve o, ahirette ziyana uğrayanlardandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 86, 'Allah, o kavme nasıl doğru yolu gösterir ki inandıktan sonra kafir olmuştur. Halbuki onlar, Peygamberin gerçek olduğuna da tanıklık etmişlerdi, onlara apaçık deliller de gelmişti ve Allah, zalim kavmi doğru yola sevk etmez ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 87, 'Onlar, o kişilerdir ki şüphesiz yaptıklarına karşılık Allah''ın, meleklerin ve bütün insanların laneti onlaradır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 88, 'Ve bu lanette ebedi kalırlar, ne azapları hafifletilir, ne de yüzlerine bakılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 89, 'Ancak bundan sonra tövbe edenler ve düzgün bir hale gelenler müstesna. Çünkü Allah, suçları örter ve rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 90, 'İnandıktan sonra kafir olanlara, sonra da kafirliklerini arttıranlara gelince: Tövbeleri hiç kabul edilmez ve onlardır sapıklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 91, 'Gerçekten de, kafir olanlar ve kafir olarak ölenler yok mu, kurtulmak için dünya dolusu altın feda etseler makbule geçmez, hiçbiri kurtulmaz, onlaradır elemli bir azap ve onlara bir tek yardımcı bile yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 92, 'Kesin olarak hayır ve ihsan mertebesine erişmezsiniz sevdiğiniz şeyleri harcamadıkça ve şüphe yok ki Allah, harcadığınız şeyleri bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 93, 'İsrail, Tevrat inmeden kendisine neleri haram ettiyse onlardan başka her çeşit yiyecek, İsrailoğullarına helaldi. De ki: Sözünüz doğruysa getirin Tevrat''ı da okuyun bakalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 94, 'Bundan sonra da kim Allah''a yalan isnat ederse artık o çeşit adamlardır zalimler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 95, 'De ki: Allah doğru söylemiştir, siz de artık doğru yolu tutan İbrahim''in dinine uyun ve o, şirk koşanlardan değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 96, 'Şüphe yok ki ilk kurulan ev, Mekke''deki evdir. Kutludur ve alemlere doğru yolu gösterir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 97, 'Oradadır apaçık deliller ve İbrahim''in durağı ve kim oraya girerse emin olur. İnsanlardan, oraya gitmeye gücü yetene, Allah için gidip o evi ziyaret ederek haccetmesi farzdır. İnkar eden eder, Allah şüphe yok ki bütün alemlerden müstağnidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 98, 'De ki: Ey kitap ehli, ne diye Allah''ın delillerini inkar eder, kafir olursunuz? Halbuki Allah, bütün yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 99, 'De ki: Ey kitap ehli, kendiniz de tanıksınız, öyle olduğu halde gene zor zoruna ne diye bir eğrilik bulmaya yeltenir de inananları, Allah yolundan döndürmeye çalışırsınız? Allah''sa yaptıklarınızdan gafil değildir ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 100, 'Ey inananlar, kendilerine kitap verilenlerin herhangi bir kısmına uyarsanız sizi döndürür, inancınızdan sonra kafir yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 101, 'Fakat siz nasıl kafir olabilirsiniz ki Allah''ın ayetleri size okunmada, Allah''ın Resulü de içinizde. Kim Allah''a sımsıkı yapışırsa şüphe yok ki o, dosdoğru yola sevk edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 102, 'Ey inananlar, Allah''tan nasıl sakınmak lazımsa öyle sakının ve ancak Müslüman olarak can verin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 103, 'Hep birden Allah''ın ipine sımsıkı sarılın, bölük bölük olmayın ve anın Allah''ın size verdiği nimeti, anın o zamanı ki düşmandınız birbirinize, kalplerinizi uzlaştırdı, nimetiyle kardeş oldunuz. İçinde ateş dolu bir çukurun tam kenarındaydınız, sizi kurtardı oradan. Allah, doğru yolu bulursunuz diye delillerini böyle açıklar işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 104, 'İçinizde öyle kişiler bulunmalı ki onlar, sizi hayra çağırsın, size iyiliği emretsin, sizi kötülükten vazgeçirmeye çalışsın ve onlardır kurtulanlar, muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 105, 'Kendilerine apaçık deliller geldikten sonra da gene bölük bölük olanlara, gene ayrılığa düşenlere benzemeyin. Öyle kişilerdir onlar ki onlaradır pek büyük azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 106, 'Bir gündür o gün ki yüzler ağarır, yüzler kararır. Yüzleri kararanlara, inandıktan sonra denir, kafir mi oldunuz? Kafir olmanıza karşılık tadın azabı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 107, 'Yüzleri ağaranlara gelince onlar, Allah''ın rahmetindedir, onlar, o rahmette ebedi olarak kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 108, 'İşte bunlar, Allah''ın ayetleridir. Gerçek olarak onları sana okumadayız ve Allah, alemlere zulmetmeyi istemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 109, 'Allah''ındır ne varsa göklerde ve yeryüzünde ve işler, dönüp ona varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 110, 'Siz insanlar için meydana çıkarılan en hayırlı ümmetsiniz; insanlara iyiliği emredersiniz, kötülükte bulunmamalarını söylersiniz ve Allah''a inanırsınız. Kitap ehli de inansaydı hayırlı olurdu kendilerine. Onlardan inananlar da var, fakat çoğu dinden çıkmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 111, 'Onlar size hiçbir suretle zarar veremezler, ancak incitirler sizi. Onlara bir tek yardımcı bile bulunmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 112, 'Nerede bulunurlarsa bulunsunlar, aşağılık bir hale getirilmiştir onlar; ancak Allah''ın ipine ve insanların yapıştıkları ipe yapışanlar müstesna. Allah''ın gazabına uğradılar ve üstlerine miskinlik çullandı. Bu da Allah''ın delillerini inkar ettikleri ve haksız yere peygamberleri öldürdükleri için, bu da isyan ettikleri ve hadlerini aştıkları için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 113, 'Ama hepsi bir değil. Kitap ehlinden dosdoğru hareket edip ibadetten vazgeçmeyen, geceleri secdeye kapanarak Allah''ın ayetlerini okuyan bir bölük de var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 114, 'Allah''a ve ahiret gününe inanırlar, insanlara iyiliği emrederler, onları kötülükten nehyederler ve onlar iyi kişilerdendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 115, 'Hayra ait ne yaparlarsa mutlaka mükafatını görecekler ve Allah, kendisinden sakınanları pek iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 116, 'Gerçekten de o kafirlerin ne malları Allah azabından onları koruyabilir, ne evlatları ve onlardır ateş ehli olanlar, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 117, 'Onların şu dünya hayatında harcadıkları, tıpkı kendilerine zulmeden bir kavmin tarlalarına vuran zemheri yeline benzer, eser, ekinleri mahvedip gider. Onlara Allah zulmetmez, onlar, kendi kendilerine zulmederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 118, 'Ey inananlar, birbirinizi bırakıp da başkalarını dost edinmeye kalkışmayın. Onlar, size zarar vermekten, kötülükte bulunmaktan geri kalmazlar, sizin zahmete düşmenizi dilerler. Düşmanlıkları, ağızlarından dökülen sözlerden açıkça belli olur, yüreklerinde gizledikleri düşmanlıksa daha da büyüktür. İşte, aklınızı başınıza almanız için size bu delilleri açıkladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 119, 'İşte siz o kişilersiniz ki onları seversiniz, fakat onlar sizi sevmez. Siz, kitabın hepsine inanırsınız, onlarsa sizinle buluştular mı inandık derler, yalnız kaldılar mı size karşı besledikleri kin yüzünden parmaklarını ısırırlar. De ki: Geberin kininizle. Şüphe yok Allah, gönüllerde ne varsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 120, 'Size bir iyilik gelse tasalanırlar, kötülük gelse ferahlanırlar. Sabreder ve sakınırsanız düzenleri size hiçbir hususta zarar vermez ve Allah, şüphe yok ki ne yaparlarsa hepsini de kavramıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 121, 'An o zamanı, hani insanları savaş yerlerine yerleştirmek için sabahleyin erkenden ailenden ayrılmıştın ve Allah duyuyordu, biliyordu bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 122, 'Hani içinizden iki bölük, korkup geri dönmek üzereydi, halbuki Allah, onların yardımcısıydı ve ancak Allah''a dayanmalı inananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 123, 'Siz zayıf olduğunuz halde Allah size Bedir''de yardım etmişti, artık siz de Allah''tan sakının da şükredenlerden olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 124, 'Hani sen o zaman inananlara demiştin ki: Rabbiniz, size yardım için üç bin melek indirecek, yetmez mi size?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 125, 'Evet, sabreder de çekinirseniz düşmanlar, size ansızın saldırsa bile Rabbiniz, alametleri besbelli tam beş bin melekle yardım eder size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 126, 'Allah, bunu ancak size bir müjde olsun da yürekleriniz yatışsın diye yapmıştır ve yardım, ancak hüküm ve hikmet sahibi Allah''tandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 127, 'O, kafirlerin ileri gelenlerinden bir kısmını öldürmek, bir kısmını da baş aşağı edip ümitsiz bir hale getirerek döndürmek için yardım etti size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 128, 'Senin bu işle ilgin yok bile; o, dilerse tövbelerini kabul eder, dilerse zalim olduklarından dolayı onları azaplandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 129, 'Allah''ındır göklerde ne varsa ve yeryüzünde ne varsa. Dilediğini yarlıgar, dilediğine azap eder ve Allah yarlıgayıcıdır, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 130, 'Ey inananlar, faizi kat kat arttırarak yemeyin, Allah''tan sakının da kurtulun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 131, 'Sakının o ateşten ki hazırlanmıştır kafirlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 132, 'Ve Allah''a ve Peygambere itaat edin de acınmışlardan olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 133, 'Yarış edercesine koşun Rabbinizin yarlıgamasına, sakınanlar için hazırlanmış bulunan ve eni, göklerle yerler kadar olan cennete.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 134, 'O sakınanlar, ferahlıkta, darlıkta mallarını yoksullara harcayanlar, öfkelerini yenenler ve insanları affedenlerdir ve Allah, ihsanda bulunanları sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 135, 'Onlar, kötü bir iş işlediler mi, yahut nefislerine bir zulümde bulundular mı Allah''ı anıp suçlarının yarlıganmasını dileyenlerdir ve Allah''tan başka kimdir günahları yarlıgayan? Onlar, işledikleri suçta, bile bile ısrar da etmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 136, 'Onlar, öyle kişilerdir ki yaptıklarının karşılığı, Rablerinin yarlıgaması ve kıyılarından ırmaklar akan cennetlerdir, ebedi olarak kalırlar orada ve iyi işlerde bulunanların mükafatı, ne de güzeldir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 137, 'Sizden önce nice dinler gelip geçti. Yeryüzünü gezin, dolaşın da yalanlayanların sonucu ne olmuş, bakın, görün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 138, 'Bu, insanlara açıklamadır ve sakınanları doğru yola sevk etmedir, öğüttür onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 139, 'Ve gevşeklik etmeyin, mahzun olmayın, inanmışsanız mutlaka üstünsünüz siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 140, 'Size bir yara deydiyse o kavim de tıpkı sizin gibi yaralandı. Bu günler, öyle günler ki onları insanlar arasında nöbetle döndürür, dururuz. Böylece de Allah, bilgisini, inananlara açıklar, içinizden şahitler edinir ve Allah zalimleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 141, 'Ve Allah, inananları arıtır, tertemiz bir hale getirir, kafirleri de helak eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 142, 'Yoksa Allah, içinizden savaşanları belli etmeden, sabredenleri bildirmeden cennete girivereceğinizi mi sanıyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 143, 'Andolsun, ölümle karşılaşmadan önce arzulamıştınız ölümü. İşte onu gördünüz, bakıp duruyordunuz ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 144, 'Muhammed, ancak bir peygamberdir. Ondan önce nice peygamberler geldi geçti. Ölürse, yahut öldürülürse gerisingeriye mi döneceksiniz? Kim dönerse bilsin ki Allah''a hiçbir suretle zarar vermez ve Allah şükredenlerin karşılığını yakında verecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 145, 'Allah''ın izni olmadıkça hiçbir kimse ölmez. Ölüm, vakti tayin edilmiş bir yazıdır. Kim dünya nimetlerini isterse ona dünyadan nimetler veririz ve kim ahiret mükafatını dilerse ona ahirete ait mükafatlar ihsan ederiz ve biz, şükredenleri yakında mükafatlandıracağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 146, 'Nice peygamberler gelip geçti ki onlarla beraber birçok bilginler, savaşa girişti. Onlar, Allah yolunda başlarına gelenlere dayandılar, ne gevşediler, ne zayıflık gösterdiler, ne de boyun eğdiler ve Allah, sabredenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 147, 'Sözleri ancak şuydu: Rabbimiz, yarlıga suçlarımızı, bağışla işlerimizde taşkınlık göstermemizi ve diret ayaklarımızı, yardım et bize kafir kavme karşı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 148, 'Allah da onlara dünya nimetlerini ve ahiretin güzelim mükafatını verdi ve Allah, iyilik edenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 149, 'Ey inananlar, kafirlere itaat ederseniz sizi döndürür onlar ve ziyan edersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 150, 'Yok yok, sizin yardımcınız, dostunuz Allah''tır ve o, yardımcıların en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 151, 'Hiçbir şeye dayanmaksızın Allah''a şirk koştuklarından dolayı kafirlerin yüreklerine yakında bir korkudur salacağız. Ateştir yurtları onların ve zalimlerin barınacağı yer, ne de kötüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 152, 'Andolsun ki Allah, size ettiği vaadi doğruladı; izniyle onları bozup öldürdünüz de sonra gevşeklik gösterdiniz, verilen buyruk hakkında çekiştiniz ve sevdiğiniz şeyi size gösterdikten sonra tuttunuz, isyan ettiniz. Sizden dünyayı dileyen olduğu gibi ahireti dileyen de vardı. Sonra sizi sınamak için onlardan geri çevirdi ve gerçekten de bağışladı sizi ve Allah, inananlara karşı lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 153, 'O anda boyuna uzaklaşıyor, hiç kimseye bakmıyordunuz bile. Peygamberse arkanızdan sizi çağırıp durmadaydı. Tanrı, elinizden çıkana hayıflanmayasınız, gelip çatan felaketlerden mahzun olmayasınız diye sizi, gam üstüne gam vererek cezalandırdı ve Allah, yaptıklarınızdan haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 154, 'Bu gamdan sonra size emniyetle bir uyku verdi ki içinizden bir bölüğü sarıp kapladı. Bir bölükse can kaygısına düşmüştü. Allah hakkında, Müslümanlıktan önceki bilgisizlik çağında olduğu gibi haksız zanlara kapıldılar. Diyorlar ki: Bu işte nemiz var bizim? De ki: Bütün işler Allah''ındır. Onlar, sana açıklamadıklarını yüreklerinde gizliyorlar ve bu işte payımız olsaydı burada öldürülmezdik diyorlar. De ki: Evlerinizde de olsanız, öldürmeleri yazılanlar, gene çıkarlar, öldürülüp yatacakları yerlere giderlerdi ve Allah, gönüllerinizde olanları yoklamak, yüreklerinizdekini artırmak için yaptı bunu ve Allah, yüreklerinizde ne varsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 155, 'İki topluluğun karşılaştığı gün içinizden yüz çevirenler, şüphe yok ki bazı hareketleri yüzünden Şeytan''a kapılmışlardı, fakat andolsun ki Allah onları bağışladı ve şüphe yok ki Allah, suçları örter ve ceza vermede acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 156, 'Ey inananlar, sakın kafir olup da sefere çıkan, yahut savaşa giden kardeşlerine, bizim yanımızda olsalardı ölmezlerdi, öldürülmezlerdi diyenlere benzemeyin. Allah, bunu, onların yüreklerine bir hasret olarak yerleştirdi. Halbuki dirilten de Allah''tır, öldüren de ve Allah, bütün yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 157, 'Andolsun ki Allah yolunda öldürülmeniz, yahut ölmeniz, Allah''ın yarlıgaması ve rahmeti, onların topladıklarından hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 158, 'Andolsun ki ölseniz de mutlaka Allah tapısında toplanacaksınız, öldürülseniz de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 159, 'Allah''ın rahmetiyle onlara karşı yumuşak davrandın, yoksa kaba ve katı yürekli olsaydın mutlaka yanından ayrılıp giderlerdi. Bağışla onları, yarlıganmalarını dile onların, iş hususunda danış onlarla. Fakat işe girişmeyi de kurdun mu dayan Allah''a. Şüphe yok ki Allah, dayananları sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 160, 'Allah size yardım ederse üst olacak yoktur size. Fakat o sizi yardımsız bırakırsa kimdir ondan başka yardım edecek size? Mutlaka Allah''a dayanmalı inananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 161, 'Bir peygamber, emanete hıyanet edemez ve kim hıyanet ederse kıyamet günü, hıyanet ettiği neyse onunla haşrolur, sonra herkese kazandığının karşılığı verilir ve onlara zulmedilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 162, 'Allah rızasına uyanla Allah''ın hışmına uğrayıp yurdu cehennem olan bir olur mu hiç? Ve orası, dönülüp varılan ne kötü bir yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 163, 'Onlara Allah katında dereceler var ve Allah ne yapıyorlarsa hepsini görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 164, 'Andolsun ki Allah, müminlere büyük bir lütufta bulundu onların içinden bir Peygamber gönderdiği zaman; o Peygamber, müminlere Tanrı ayetlerini okumada, onları arıtmada, onlara kitap ve hikmet öğretmede ve onlar, bundan önce apaçık bir sapıklık içindeydiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 165, 'Başlarına iki misli olarak gelen felakete siz de uğrayınca, bu da nereden dediniz. De ki: Bu, sizin katınızdan geldi ve Allah''ın, şüphe yok ki her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 166, 'İki topluluğun karşılaştığı gün size gelip çatan musibet, Allah''ın izniyle gelip çatmıştı. Böylece de inananları bildirmeyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 167, 'Münafıklık edenleri de açığa vurmayı murad etmişti. Onlara, gelin, Allah yolunda savaşın, yahut da onları defedin deyince, savaşmayı bilseydik elbette size uyardık dediler. Halbuki onlar, o gün imandan ziyade küfre yakındılar. Özlerinde olmayan söze getiriyorlardı. Onların bütün gizlediklerini Allah bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 168, 'Onlar öyle kişilerdir ki otururlar da kardeşlerine, eğer derler, bizi dinleselerdi öldürülmeyeceklerdi. De ki: Ölümü çevirin kendinizden sözünüz doğruysa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 169, 'Allah yolunda öldürülenleri ölü sanma. Onlar diridir ve Rableri katında rızıklanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 170, 'Ferahfahur bir halde Allah''ın onlara ettiği lütuf ve ihsanlarla ve onlar, henüz kendilerine katılmayanlara, fakat artlarından gelmekte olanlara da bilin ki ne korku vardır onlara, ne de mahzun olurlar diye müjde vermeyi isterler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 171, 'Allah''ın nimet ve ihsanına nail olduklarından dolayı sevinç içindedir onlar ve Allah, inananların ecrini zayi etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 172, 'Yaralandıktan sonra bile Allah''ın ve Peygamberin davetine icabet edenlere, hele onların içinden iyiliklerde bulunup sakınanlara pek büyük bir ecir var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 173, 'Öyle kişilerdir onlar ki halk, kendilerine, bütün insanlar, aleyhinizde birleşti, korkun onlardan dedi de bu söz, onların inancını arttırdı ve Allah yeter bize, ne de güzel vekildir o dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 174, 'Kendilerine hiçbir kötülük erişmeksizin Allah''ın nimetlerine ve ihsanına nail olarak geri döndüler ve Allah rızasına da uymuş oldular; Allah, pek büyük lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 175, 'Şüphe yok ki Tanrı dostlarını korkutan ancak ve ancak Şeytan''dır. Onlardan korkmayın, benden korkun inanmışsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 176, 'Ve o, küfre doğru koşakoşa, yarışarak gidenler, seni mahzun etmesin, onlar Allah''ı hiçbir suretle zararlandıramazlar. Allah, onlara ahiretten hiçbir pay vermeyi murad etmemiştir ki ve onlaradır pek büyük azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 177, 'İmanı satıp da küfrü alanlar, Allah''ı zararlandıramazlar, onlaradır elemli azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 178, 'Küfredenler, kendilerine mühlet ve fırsat vermemizi, kendileri için hayırlı sanmasınlar. Onlara mühlet ve fırsat verişimiz, suçlarını arttırmaları içindir ve onlaradır horhakir edici azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 179, 'Allah, inananları, şu bulunduğunuz halde bırakmayacak, sonucu, pisi temizden mutlaka ayırt edecek. Ve Allah size gaybı da bildirecek değil, fakat peygamberlerinden dilediğini seçer, gaybı bildirir ona. İnanır ve sakınırsanız hiç şüphe yok ki size büyük bir ecir var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 180, 'Allah''ın ihsan ettiğini vermekten sakınanlar, bunu kendileri için hayırlı sanmasınlar. Hatta bu, onlar için şerdir de. Sakındıkları şey, kıyamet günü, boyunlarına dolanacak ve Allah''ındır göklerin ve yeryüzünün mirası ve Allah, bütün yaptıklarınızdan haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 181, 'Andolsun ki Allah yoksuldur, biz zenginiz ama diyenin sözünü işitmiştir Allah. Ne söyledilerse onu da yazacağız, peygamberleri haksız yere öldürmelerini de ve diyeceğiz ki: Tadın yakıcı kavurucu azabı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 182, 'Bu da, ancak elleriyle kazandıklarının cezası ve Allah, şüphe yok ki kullarına zulmetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 183, 'Kurban ettiğini, bir yıldırım düşüp yakmadıkça inanmayız hiçbir peygambere, bize böyle emretti Allah gerçekten de dediler. De ki: Benden önce apaçık mucizelerle ve söylediğiniz mucizeyle birçok peygamberler gelip geçti, doğruysa sözünüz ne diye öldürdünüz onları?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 184, 'Seni yalan sayarlarsa senden önce apaçık delillerle, sahifelerle ve aydınlatıcı kitapla gelen peygamberler de yalan sayılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 185, 'Herkes ölümü tadacak ve hiç şüphe yok ki cennete giren, gerçekten de kurtulmuştur, muradına ermiştir. Dünya yaşayışı, zaten aldatıcı bir matahtan ibaret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 186, 'Andolsun ki mallarınızla, canlarınızla sınanacaksınız, sizden önce kendilerine kitap verilenlerle Tanrıya şirk koşanlardan kötü sözler işiteceksiniz, birçok eziyetlere, zahmetlere uğrayacaksınız. Sabreder ve sakınırsanız şüphe yok ki bu, hadiselere karşı gösterilen metanetten sayılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 187, 'An o zamanı ki Allah, kendilerine kitap verilenlerden, o kitabı insanlara mutlaka açıklayacaksınız, gizlemeyeceksiniz onu diye söz almıştı; onlarsa o sözü artlarına attılar, azcık bir menfaat karşılığında sattılar onu, ama o aldıkları şey, ne de kötünesne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 188, 'Sakın sanma yaptıklarıyla sevinenlerin, yapmadıkları işlerden dolayı övülmeyi arzulayanların azaptan kurtulacakları bir yer olabileceğini, sakın sanma onların azaptan kurtulacağını. Onlar içindir elemli bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 189, 'Allah''ındır göklerin ve yeryüzünün saltanatı ve Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 190, 'Gerçekten de göklerin ve yeryüzünün yaratılışında, geceyle gündüzün birbiri ardınca gelişinde aklı tam olanlara deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 191, 'Onlar, Allah''ı ayaktayken, otururken ve yan üstü yatarken anarlar ve göklerle yeryüzünün yaratılışını düşünürler de Rabbimiz derler, bunları boş yere yaratmadın, noksan sıfatlardan arısın sen, koru bizi ateşin azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 192, 'Rabbimiz, gerçekten de sen kimi ateşe atarsan şüphe yok ki onu hor hakir bir hale sokarsın ve zalimlere hiçbir yardımcı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 193, 'Rabbimiz, gerçekten de biz, bir seslenen duyduk, inanç için sesleniyor, Rabbinize inanın, diyordu, hemencecik inandık. Rabbimiz, yarlıga suçlarımızı, ört kötülüklerimizi, iyilere kat bizi, onlarla al ruhumuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 194, 'Rabbimiz, bize ver peygamberlerine vaadettiklerini ve aşağılık bir hale getirme bizi kıyamet gününde, gerçekten de sen vaadinden dönmezsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 195, 'Gerçekten de Rableri, dualarını kabul etti, ben, erkek olsun, kadın olsun, içinizden iyilik yapanın iyiliğini boşa çıkarmam, bazınız bazınızdan meydana gelmedir ve hepiniz birsiniz bence. Ama benim yolumda göçenlerin, yurtlarından çıkarılanların, eziyete uğrayanların, savaşıp vuruşanların, vurulup ölenlerin kusurlarını, andolsun ki mutlaka örteceğim ve onları, kıyılarından ırmaklar akan cennetlere sokacağım, Allah katından mükafattır bu, daha güzel mükafat da gene Allah katında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 196, 'Kafir olanların şehirlerde gezip dolaşmaları, aldatmasın seni sakın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 197, 'Bu, azıcık bir faydalanmadan ibaret, sonra sığınacakları yer cehennemdir ve orası, ne kötü bir yurttur, ne kötü bir yatak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 198, 'Fakat Rablerinden çekinenleredir kıyılarından ırmaklar akan cennetler, orada ebedi kalış, Allah katından ziyafetler ve Allah katında, iyi kişilere daha da hayırlı şeyler var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 199, 'Şüphe yok ki kitap ehlinden, Allah''a içten bir saygı besleyerek, Allah''a inananlar ve size indirilene de, kendilerine indirilene de, iman edenler var. Allah ayetlerini değersiz bir menfaate satmaz onlar. Onların karşılığı, Rableri katındadır. Şüphe yok ki Allah, pek tez hesap görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (3, 200, 'Ey inananlar, sabredin, sebat edin, karşı durun ve Allah''tan sakının, ancak bu sayede kurtulur, bu sayede üst olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 1, 'Ey insanlar, sizi tek bir candan yarattı, o canın eşini de ondan yaratıp ikisinden birçok erkek ve kadın türetti. Sakının Allah''tan ki onunla haklarınızı dilemektesiniz ve akrabalık hukukuna da riayet edin. Şüphe yok ki Allah, sizi tamamıyla görüp gözetmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 2, 'Yetimlere mallarını verin ve iyisinin yerine kötüsünü koyup değiştirmeyin ve onların mallarını, kendi mallarınıza katıp yemeyin; çünkü bu, pek büyük bir suçtur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 3, 'Yetim kızlar hakkında adaletle muamele edemeyeceğinizden korkarsanız, beğendiğiniz, hoşunuza giden başka kadınlardan iki, üç ve dört kadın alın. Fakat bunların arasında adaleti gözetmeyeceğinizden korkarsınız o vakit bir zevceyle, yahut sahip olduğunuz cariyelerle iktifa edin. Bu, doğruluktan sapmamanıza daha yakın ve size daha uygundur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 4, 'Kadınlarınızın mehirlerini bir bağış olarak verin, ama onlar, gönül hoşluğuyla mehirlerinin bir miktarını size bağışlarlarsa o vakit de onu içinize sindire sindire ve afiyetle yiyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 5, 'Allah''ın, size geçinmek için verdiği mallarınızı akılsızlara vermeyin, onları rızıklandırın, giydirin ve kendilerine tatlı ve güzel sözler söyleyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 6, 'Yetimleri, nikah çağına dek deneyin, ergenlik çağına ulaştıklarını, olgunlaştıklarını gördünüz mü mallarını kendilerine verin. Onların malını israf ederek, yahut büyüyünce geri alırlar diyerek yemeyin. Zengin olan, yetimin malına hiç dokunmasın. Fakir olan, örfe uygun bir miktar yiyebilir. Mallarını geri vereceğiniz vakit bu muameleyi tanıklar huzurunda yapın. Allah, gereğince hesap sorucudur ve o, yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 7, 'Erkekler için pay var anayla babanın ve yakınların bıraktıkları malda, kadın için de pay var anayla babanın ve yakınların bıraktıklarında. Mal, az olsun, çok olsun, mirasta muayyen bir pay var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 8, 'Miras taksim edilirken yakınlar, yetimler, yoksullar bulunursa o maldan onları da rızıklandırın ve kendilerine güzel sözler söyleyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 9, 'Artlarında aciz ve küçük soysop bırakacağını düşünerek onlar için nasıl korkup üzüntüye düşerler; yetimler için de Allah''tan korksunlar da sözün doğrusunu söylesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 10, 'Yetimlerin mallarını zulümle yiyenler, ancak ateş yerler, o mallar, karınlarında ateştir adeta ve onlar, alevli ateşe atılacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 11, 'Allah, evladınız hakkında size şunu tavsiye eder: Erkeğin payı, iki kızın payı kadardır. Kızlar, ikiden fazlaysa terekenin üçte ikisi onlarındır, kız bir taneyse yarısı onun. Bir çocuğu varsa anayla babanın her birine, terekenin altıda biri kalır. Çocuğu yok da anasıyla babası mirasçı olursa üçte biri ananındır. Kardeşleri varsa bıraktığı maldan, vasiyeti yerine getirildikten ve borcu ödendikten sonra kalanın altıda biri anaya aittir. Babalarınızdan, oğullarınızdan hangisi, size daha faydalıdır, bilemezsiniz. Bu, Allah''tan farzdır. Şüphe yok ki Allah her şeyi bilir, hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 12, 'Çocukları yoksa zevcelerinizin, kalan mallarının yarısı sizindir. Çocukları varsa, vasiyeti yerine getirilip borcu ödendikten sonra dörtte biri sizin. Çocuğunuz yoksa sizden kalanın dörtte biri zevcelerinizin, çocuğunuz varsa, kalan maldan, vasiyet ettiğiniz şey yerine getirilip borcunuz ödendikten sonra sekizde biri onların. Miras, çocuğu ve babası olmayan bir erkeğe, yahut kadına aitse ve onun da erkek, yahut kız kardeşi varsa her birinin hakkı, altıda birdir. Bunlar birden fazlaysa, mirasçının vasiyeti yerine getirilip borcu ödendikten sonra kalan malın üçte birine ortak olurlar ve kimsenin de zarar görmemesi gerekir. Allah tarafından size öğüttür ve Allah her şeyi bilir, ceza vermede acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 13, 'İşte bunlardır Allah sınırları ve kim Allah''a ve Resulüne itaat ederse Allah onu, kıyılarından ırmaklar akan cennetlere sokar ve onlar, ebedi kalırlar orada ve budur pek büyük bir kurtuluş ve kutluluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 14, 'Ve kim Allah''a ve Resulüne isyan eder ve sınırlarını aşarsa onu, daimi kalmak üzere, ateşe atar ve onadır horlayıcı, aşağılık bir hale getirici azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 15, 'Kadınlarınızdan kötülükte bulunanların kötülüğüne, içinizden dört tanık getirin. Onlar, tanıklık ederlerse kadınları, ölümlerine dek, yahut Allah onlara bir yol açıncaya kadar evlerde tutun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 16, 'Sizden, kötülükte bulunanlar olursa iki tarafı da incitin. Tövbe ederler ve hallerini düzeltirlerse vazgeçin onlardan, şüphe yok ki Allah, tövbeleri kabul eder, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 17, 'Şüphe yok ki Allah katında tövbe, ancak bilgisizlikle kötülükte bulunup sonra derhal tövbe edenlerin tövbesidir. Onlardır Allah''ın, tövbelerini kabul ettiği kişiler ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 18, 'Tövbe, o kişilerin tövbesi değildir ki kötülüklerde bulunup dururlar da sonucu içlerinden birine ölüm gelip çattı mı işte şimdi tövbe ettim ben der ve kafir olarak ölenlerin tövbesi de tövbe değildir. O kişilerdir onlar ki onlar için elemli bir azap hazırlamışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 19, 'Ey inananlar, zorla kadınları miras olarak almanız helal değildir size. Apaçık kötülükte bulunmadıkları halde onlara verdiğinizin bir kısmını ele geçirmek için sıkıştırmayın onları ve onlarla iyi ve güzel geçinin, onlardan hoşlanmadığınız takdirde deolabilir ki sizin hoşunuza gitmeyen bir şeyde Allah, birçok hayırlar takdir etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 20, 'Zevcenizi bırakıp yerine bir başkasını almak isterseniz bırakacağınıza, yığınlarla mehir vermiş olsanız bile ondan hiçbir şey almayın. İftira ederek ve apaçık günaha girerek alır mısınız onu hiç?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 21, 'Nasıl alabilirsiniz ki birbirinizle kaynaşmıştınız ve onlar, sizden adamakıllı söz de almışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 22, 'Babalarınızın nikahladığı kadınları almayın. Bu, ancak geçmiş bir adettir ve geçen, geçip gitmiştir. Şüphe yok ki bu, kötü bir şeydi, iğrenç bir adetti ve ne de kötü bir yolduyordamdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 23, 'Haram edilmiştir size analarınız, kızlarınız, kız kardeşleriniz, halalarınız, teyzeleriniz, erkek kardeşlerinizin kızları, kız kardeşlerinizin kızları, sizi emziren sütanneleriniz, süt emme yüzünden kardeşleriniz olan kızlar ve zevcelerinizin anneleri, zifafa girdiğiniz zevcelerinizin, sizin himayenizde bulunan ve üvey kızlarınız olan kızları. Ancak zevcelerinizle zifafa girmedinizse kızlarını almanızda bir beis yok. Haram edilmiştir belinizden gelen oğullarınızın zevceleri ve iki kız kardeşi birlikte almak, çünkü bu adet de geçmiştir artık; şüphe yok ki Allah, bütün suçları örter rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 24, 'Kocalı kadınlarla evlenmek de haram; ancak sahibi olduğunuz cariyeler müstesna. Allah''ın yazısı bu, emri bunlar size ve bunlardan başkalarını, evlenmeniz ve zinada bulunmamanız için arayıp istemeniz helal edilmiştir size. Kadınlardan biriyle evlenerek faydalandığınız takdirde mehirlerini kararlaştırıldığı veçhile verin. Miktarını tayin ettikten sonra gönül hoşluğuyla herhangi bir hususta uyuşursanız suç yok size. Şüphe yok ki Allah her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 25, 'İçinizden, hür ve inanmış kadınları almaya gücü yetmeyenler, inanmış erlerin sahip oldukları cariyeleri alsın ve Allah, sizin inancınızı çok iyi bilir. Hepiniz de birsiniz, birbirinizden türediniz. Kötülükte bulunmayan, birisini dost tutmayan namuslu cariyeleri, sahiplerinin izniyle alın, ücretlerini de örfe uygun olarak güzellikle verin, onlar evlendikten sonra kötülükte bulunurlarsa cezaları, hür kadınların cezasının yarısıdır. Bu, içinizden zina etmekten korkanlara bir ruhsattır, fakat sabretmeniz size daha hayırlıdır ve Allah, suçları tamamıyla örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 26, 'Allah, size her şeyi açıklamak ve size, sizden öncekilerin yollarını göstermek ve tövbenizi kabul etmek ister ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 27, 'Ve Allah, tövbenizi kabul etmeyi diler, şehvetlerine uyanlarsa, sizin doğru yoldan tamamıyla sapmanızı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 28, 'Allah, sizin yükünüzü hafifletmeyi diler ve insan, zaten de zayıf olarak yaratılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 29, 'Ey inananlar, aranızda, mallarınızı haksız yere ve boşuboşuna yemeyin, ancak karşılıklı bir uzlaşmayla yapılan alışveriş başka ve birbirinizi öldürmeyin, şüphe yok ki Allah, size rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 30, 'Ve kim haddini aşarak zulmedip bu işi işlerse onu ateşe sokarız ve bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 31, 'Nehyedildiğiniz büyük günahlardan kaçınırsanız suçlarınızı örteriz ve sizi büyük ve şerefli bir mevkie ulaştırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 32, 'Allah''ın, bazılarınızı, bir kısmınıza üstün etmesine haset etmeyin. Erkeklerin, kendi kazançlarından payları var, kadınların da kendi kazançlarından payları var. Allah''tan, lütfünü, inayetini dileyin, çünkü şüphe yok ki Allah her şeyi tamamıyla bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 33, 'Ana ve babayla yakınların bıraktıkları mallara mirasçı olacak erkek ve kadınları tayin ettik. Kendileriyle ahitleştiğiniz kişilere de paylarını verin, şüphe yok ki Allah her şeyi görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 34, 'Erkekler, kadınlardan üstündür, çünkü Allah onları bir çok şeylerde kadınlardan üstün etmiştir, çünkü onlar, kadınları, mallarıyla geçindirirler, doyururlar; iyi kadınlar da itaatli olurlar ve Allah, onların hakkını nasıl korumuşsa onlar da, kocaları yanlarında olmasa bile, iffetlerini korurlar. Kadınlarınızın serkeşliğinden korkunca onlara öğüt verin, onları yatakta yalnız bırakın, dövün onları. Fakat itaat ettikleri takdirde de aleyhlerine bir sebep araştırmayın, şüphe yok ki Allah çok yüce ve büyüktür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 35, 'Karıyla kocanın arasında bir ayrılık olacağından korkarsanız koca tarafından bir hakem, kadın tarafından da bir hakem gönderin. Aralarının düzelmesini dilerlerse Allah da bu hususta başarı verir onlara. Şüphe yok ki Allah her şeyi bilir ve her şeyden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 36, 'İbadet edin Allah''a ve ona hiçbir şeyi eş etmeyin. Anaya, babaya, yakınlara, yetimlere, yoksullara, yakın komşulara, uzak komşulara, yolda kalmışlara ve sahibi olduğunuz köle ve cariyelere iyilik edin, çünkü Allah, kendini beğenip övenleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 37, 'Onlar, hem nekeslik ederler, hem de insanlara, nekes olmalarını emrederler ve Allah''ın, kendilerine lütfedip verdiği şeyleri gizlerler ve biz, kafirlere, horlayıcı, onları aşağılatıcı bir azap hazırlamışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 38, 'Onlar, Allah''a ve ahiret gününe inanmadıkları halde mallarını, ancak insanlara gösteriş olmak üzere sarfederler. Şeytan kime arkadaş olursa o, arkadaşların en kötüsüne düşmüştür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 39, 'Ne olurdu Allah''a ve ahiret gününe inanıp Allah''ın kendilerini rızıklandırdığı şeyleri harcasalardı; ve Allah, onları çok iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 40, 'Şüphe yok ki Allah zerre kadar zulmetmez. Zerre miktarı iyilik bile olsa onu katkat arttırır ve yapana, kendi katından büyük bir mükafat verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 41, 'Ne olacak halleri her ümmetten bir tanık getirdiğimiz, seni de hepsine tanık tuttuğumuz gün?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 42, 'O gün, bir gündür ki kafirlerle Peygambere isyan edenler, yerle yeksan olmalarını ve Allah''tan hiçbir sözü gizlememiş bulunmalarını dileyecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 43, 'Ey inananlar, namaza yaklaşmayın ne söylediğinizi bilmeyecek kadar sarhoşken ve yolda değilseniz yıkanıncaya dek cünüpken. Hastaysanız, yahut yolculuktaysanız, yahut biriniz ayakyolundan gelirse, yahut da kadınlara dokunursanız, su bulamadığınız takdirde temiz toprakla teyemmüm edin, toprağı, yüzünüze ve ellerinize sürün. Şüphe yok ki Allah, bağışlayıcıdır, suçları örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 44, 'Görmez misin kendilerine kitaptan bir pay verilenleri? Sapıklığı satın alıyorlar ve sizi de yoldan saptırmak istiyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 45, 'Ve Allah, sizin düşmanlarınızı daha iyi bilir ve dost olarak da Allah yeter, yardımcı olarak da Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 46, 'Yahudi olanlardan, sözleri yerlerinden alıp değiştirenler de var ve işittik de isyan ettik derler, işit, işitmeyesice ve dillerini eğip bükerek ve dini kınayarak bizi de gözet derler. İşittik ve itaat ettik, bizi de dinle ve bize de bak deselerdi onlar için daha hayırlı, daha doğru olurdu, fakat Allah, küfürleri yüzünden onları rahmetinden uzaklaştırdı, pek azından başkası imana gelmez onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 47, 'Ey kendilerine kitap verilenler, yüzlerinizi mahvedip eski haline getirmeden, yahut cumartesi gününü tanıyanlara lanet ettiğimiz gibi size de lanet etmeden, sizdeki kitabı da gerçeklemek üzere indirdiğimiz kitaba inanın ve Allah''ın emri, mutlaka yerine gelecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 48, 'Şüphe yok ki Allah, kendisine eş tanıyanları yarlıgamaz, ondan başka dilediğinin bütün suçlarını yarlıgar ve kim Allah''a eş tanırsa gerçekten de büyük bir iftirada bulunmuş, pek büyük bir suç işlemiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 49, 'Görmez misin kendilerini temize çıkarmaya savaşanları, halbuki Allah, dilediğini arıtır, temizler ve onlar, hurma çekirdeğinin içindeki incecik kıl kadar bile zulüm görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 50, 'Hele bak, Allah''a nasıl iftira ediyor, ona yalan isnat ediyorlar ve yeter bu apaçık suç onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 51, 'Görmez misin, kendilerine kitaptan bir pay verilenler, puta, Şeytan''a inanırlar da kafirler için bunlar derler, inananlara nispetle daha doğru yolda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 52, 'Onlar, o kişilerdir ki Allah onlara lanet etmiştir ve Allah kime lanet ettiyse ona gerçekten de hiçbir yardımcı bulunmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 53, 'Yoksa onların saltanattan bir payları mı var? Böyle olsa da insanlara bir habbe bile vermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 54, 'Yoksa Allah''ın, lütfedip insanlara ihsan ettiği şeylere haset mi ediyorlar? Gerçekten de biz İbrahim soyuna kitap ve hikmet verdik ve onlara büyük bir saltanat ihsan ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 55, 'Onlardan, ona inanan da var, ondan yüz çeviren de ve bunlara alevli, yakıp kavuran cehennem yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 56, 'Şüphe yok ki ayetlerimizi inkar edenleri, yakında ateşe atarız. Derileri yanıp eridikçe de azabı tatsınlar diye yerlerine yeniden yeniye deri bitiririz. Şüphe yok ki Allah üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 57, 'İnanıp iyi işlerde bulunanlarıysa kıyılarından ırmaklar akan cennetlere sokarız. Ebedi kalırlar orada. Onlara orada her çeşit ayıptan arınmış tertemiz eşler var ve onları kaba gölgelikte huzura, rahata kavuştururuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 58, 'Şüphe yok ki Allah, emanetleri ehline vermenizi ve insanlar arasında hükmettiğiniz zaman adaletle hükmetmenizi emrediyor. Gerçekten de Allah, size ne de güzel öğüt vermede. Şüphe yok ki Allah, her şeyi duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 59, 'Ey inananlar, Allah''a, peygambere ve içinizden emredecek kudret ve liyakata sahip olanlara itaat edin. Allah''a ve ahiret gününe inanıyorsanız bir şeyde ihtilafa düştünüz mü o hususta Allah''a ve Peygambere müracaat edin; bu hareket, hem hayırlıdır, hem de sonu pek güzeldir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 60, 'Görmez misin sana indirilene de, senden önce indirilenlere de inandıklarını sananlar, Şeytan tarafından yargılanmalarını dilerler, halbuki onu inkar etmeleri emredilmişti onlara ve Şeytan, onları tamamıyla sapıtmak, doğru yoldan pek uzak bırakmak ister.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 61, 'Onlara, Allah''ın indirdiğine ve peygambere gelin dendi mi görürsün ki münafıklar, senden tamamıyla uzaklaşırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 62, 'Elleriyle hazırladıkları bir felakete uğrayınca da halleri nice olur? Sonra sana gelirler Allah''a yemin ederek ve biz, ancak iyilik etmek, ara bulmak istedik diyerek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 63, 'Onlar, öyle kişilerdir ki Allah bilir kalplerinde olanı, yüz çevir onlardan, öğüt ver onlara, kendi hallerine dair tesirli, dokunaklı sözler söyle onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 64, 'Biz, her peygamberi ancak, Allah izniyle ona itaat edilsin diye gönderdik; onlar da nefislerine zulmettikleri vakit sana gelerek Allah''ın, kendilerini yarlıgamasını isteselerdi, Peygamber de onların yarlıganmalarını dileseydi elbette Allah''ın tövbeleri kabul edici rahim olduğunu görür, anlarlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 65, 'Fakat öyle değil; andolsun Rabbine ki onlar iman etmiş olmazlar aralarında çıkan ihtilaflarda seni hakem etmedikçe ve sonra da yüreklerinde hiçbir sıkıntı, üzüntü duymadan verdiğin hükmü kabul eylemedikçe ve tamamıyla sana teslim olmadıkça.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 66, 'Biz onlara, kendinizi öldürün, yahut ülkenizden çıkın diye emretseydik, bunu onlara farz etmiş olsaydık ancak içlerinden pek azı bunu yapardı. Halbuki kendilerine verilen öğüdü tutsalar, deneni yapsalardı bu, hem onlara daha hayırlı olurdu, hem de inançlarını kökleştirirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 67, 'Biz de o vakit, onları, katımızdan büyük bir mükafatla mükafatlandırırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 68, 'Ve onları dosdoğru yola sevk ederdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 69, 'Ve kim Allah''a ve Peygambere itaat ederse o ve o çeşit kişiler Allah''ın, nimetleriyle nimetlendirdiği peygamberlerle,gerçeklerle, şehitlerle ve iyi adamlarla eş olur, onlara katılırlar ve onlar, ne de güzel arkadaştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 70, 'Bu lütuf ve ihsan, Allah''tandır ve Allah''ın her şeyi bilmesi yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 71, 'Ey inananlar, ihtiyata ait gereken tedbirleri alın da bölükbölük, yahut hep birden ilerleyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 72, 'İçinizde mutlaka ağır davranan olacak ve size bir felaket gelip çatınca da diyecek ki: Allah, gerçekten de bana lütfetti de o zaman, onlarla beraber bulunmadım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 73, 'Size Allah''tan bir lütuf ve ihsan gelince de onunla sizin aranızda hiçbir dostluk yokmuş gibi keşke diyecek, ben de onlarla beraber olsaydım da ben de o büyük lütfe nail olsaydım, ben de muradıma erseydim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 74, 'Artık Allah yolunda savaşsın dünya yaşayışı yerine ahireti satın alanlar ve kim Allah yolunda savaşır da öldürülür, yahut üst olursa ona büyük bir ecir vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 75, 'Ne oluyor size ki zayıf ve aciz erkeklerle kadınlar ve çocuklar, Rabbimiz bizi ahalisi zalim olan şu şehirden çıkar, bize katından bir sahip gönder, bize katından bir yardımcı yolla deyip dururlarken siz, Allah yolunda savaşmıyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 76, 'İnananlar, Allah yolunda savaşırlar, kafir olanlar, Şeytan yolunda savaşırlar. Savaşın Şeytan''ın dostlarıyla ve şüphe yok ki Şeytan''ın hilesi zayıftır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 77, 'Görmez misin savaştan el çekin ve namaz kılın, zekat verin denenleri? Onlara savaş farz edilince içlerinden bir kısmı, insanlardan, Allah''tan korkar gibi, hatta daha da fazla korkmaya başladılar da ne olurdu, yakın olan ölümümüze dek bu emri geciktirseydin, bize savaşı emretmeseydin dediler. De ki: Dünyanın zevki azdır, ahiretse sakınanlar için daha hayırlıdır ve onlar, hurma çekirdeğinin içindeki incecik kıl kadar bile zulüm görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 78, 'Nerede olursanız olun, ölüm sizi bulur; hatta isterseniz sağlamlaştırılmış yüksek kalelerde olun. Onlara bir iyilik geldi mi bu derler, Allah''tan. Bir kötülük geldi mi, bu derler, senden. De ki: Hepsi Allah''tan. Ne oldu bu kavme ki hiçbir sözü anlamaya yanaşmıyor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 79, 'Sana gelen iyiliğe ait şey Allah''tandır, kötülüğe ait olansa nefsinden ve biz seni insanlara peygamber olarak gönderdik, buna tanık olarak Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 80, 'Peygambere itaat eden, gerçekten de Allah''a itaat etmiştir, yüz çevirene gelince; zaten biz seni onları korumak için göndermedik ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 81, 'Bizden itaat etmek derlerse de yanından ayrıldılar mı onların bir kısmı, geceleyin senin dediğinden bambaşka şeyler kurar, Allah da onların kurduklarını yazar. Yüz çevir onlardan de dayan Allah''a, Allah yeter koruyucu olarak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 82, 'Hala mı düşünmezler Kur''an''ı Allah katından gayrı bir yerden gelseydi onda, birbirini tutmaz birçok şeyler bulurlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 83, 'Emniyete, yahut korkuya ait bir haber duysalar derhal yayarlar. Halbuki Peygambere ve içlerinden emre salahiyeti olanlara başvursalardı bu haberi arayıp duyarak yayanlar, elbette onlardan gerçeğini öğrenirlerdi. Allah''ın ihsanı ve acıması olmasaydı pek azınız müstesna, Şeytan''a uyup gitmiştiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 84, 'Gayrı savaş Allah yolunda, kendinden başkasından sorumlu değilsin sen ve teşvik et inananları. Olur da Allah kafirlerin zararını ve zulmünü defedip giderir ve Allah''ın azabı da pek çetindir, cezası da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 85, 'Kim iyi bir şefaatte bulunursa o şefaatten payı vardır ve kim kötü bir şefaatte bulunursa ondan payı var ve Allah her şeyi bilir korur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 86, 'Size selam verildiği vakit selamı daha güzel bir sözle, yahut aynı sözle alın ve Allah, şüphe yok ki her şeyi hakkıyla hesaplar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 87, 'Bir Allah''tır ki yoktur ondan başka tapacak. Kıyamet gününde hepinizi toplayacaktır ve o günde hiç şüphe yoktur ve kimdir Allah''tan daha doğru sözlü?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 88, 'Ne oluyor size de münafıklar hakkında iki bölük oluyorsunuz, Allah onları, kazandıkları suçları yüzünden gerisin geri küfre döndürdü; Allah''ın yoldan çıkarıp azdırdığını doğru yola getirmek mi istersiniz? Ve Allah kimi azdırdıysa artık onun için hiçbir yol bulamazsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 89, 'Onlar, sizin de kendileri gibi kafir olmanızı ve böylece de hepinizin bir olmanızı isterler, onun için Allah yolunda yurtlarından göçmedikçe onların hiçbirini dost edinmeyin. Bunu kabul etmez de yüz çevirirlerse tutun onları ve öldürün onları bulduğunuz yerde ve onlardan ne dost edinin, ne yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 90, 'Ancak sizinle onların arasında ahitleşme olan bir kavme sığınanlar, yahut sizinle veya kendi kavimleriyle savaşmaya yürekleri dayanmayıp size gelenler, bu hükümden dışarıdır ve Allah dileseydi onları size musallat ederdi de sizinle savaşırlardı. Sizi bırakırlar, sizinle savaşmazlar ve barış teklifinde bulunurlarsa Allah da onların aleyhinde bulunmaya bir yol bırakmamıştır size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 91, 'Başka bir bölüğünü de şöyle bulacaksınız: Onlar, sizden de emin olmak isterler, kavimlerinden de. Fakat bir fitneye sevk edilince ta içine dalıverirler. Onlar sizi bırakmazlar, sizinle barış halinde yaşamazlar ve sizden el çekmezlerse tutun onları, öldürün onları bulduğunuz yerde ve işte size, onlara karşı apaçık bir kudret ve salahiyet verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 92, 'İnanan birisinin, bir inanmış kişiyi öldürmesi caiz değildir, ancak yanlışlıkla olursa o başka. Yanlışlıkla bir mümini öldüren, mümin bir köle azat eder, öldürülenin ailesine de kan pahası verir, ancak ailesi, kan pahasını sadaka olarak bağışlarsa vermez. Öldürülen, mümin olmakla beraber size düşman olan bir kavimdense öldüren, mümin bir köle azat eder. Öldürülen, aranızda ahitleşme olan bir kavimdense ailesine kan pahası vermek ve bir mümin azat etmek gerek. Bunları yapamayan, Allah''a tövbe ederek iki ay, birbiri ardınca oruç tutar ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 93, 'Ve kim bir mümini kasten öldürürse cezası cehenneme atılmaktır, ebedi kalır orada ve Allah ona gazap eder ve rahmetinden uzaklaştırır onu ve ona pek büyük bir azap hazırlamıştır da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 94, 'Ey inananlar, Allah yolunda savaşa gittiğiniz zaman pek dikkatli ve ihtiyatlı olun ve size selam verene, dünya menfaatini dileyerek sen mümin değilsin demeyin, şüphe yok ki Allah katında çok ganimetler var. Siz de önce böyleydiniz de Allah size lütfetti, o halde dikkat edin, ihtiyatlı olun; hiç şüphe yok ki Allah, bütün yaptıklarınızdan haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 95, 'Mazeretleri olanlar müstesna, müminlerden savaşa katılmayıp oturanlarla Allah yolunda mallarıyla, canlarıyla savaşanlar, eşit olamaz. Allah, mallarıyla, canlarıyla Allah yolunda savaşanları, derece bakımından, oturanlardan üstün etmiştir. Allah, hepsine de iyilikler, güzellikler vaat etti ve Allah üstün etti savaşanları oturanlardan, pek büyük bir ecirle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 96, 'Kendi katından ihsan ettiği derecelerle, yarlıgamayla ve rahmetle ve Allah suçları örtüp yarlıgayan rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 97, 'Melekler, nefislerine zulmedenlerin canlarını alırken ne haldeydiniz derler. Onlar da, yeryüzünde derler, aciz kişilerdik biz. Melekler, Allah''ın yeri geniş değil miydi derler, siz de hicret edeydiniz. İşte onlardır yurtları cehennem olanlar ve orası, ne de kötü bir yurttur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 98, 'Ancak yurtlarından göçmek için bir düzen, bir yol bulamayan gerçekten de aciz erkeklerle kadınlar ve çocuklar bu hükümden dışarı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 99, 'Onlardır Allah''ın bağışlayacağı umulanlar ve Allah bağışlayıcıdır, suçları örtücüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 100, 'Allah yolunda yurdundan göçen, yeryüzünde barınacak birçok yerler bulur, ferahlığa erer ve kim, Allah ve Peygamberi uğrunda evinden çıkıp hicret eder de sonra ona ölüm gelip çatarsa onun ecri Allah''a aittir ve Allah suçları örter rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 101, 'Yeryüzünde sefere çıktığınız zaman kafirlerin, size bir zarar vereceğinden ürkerseniz namazı kısaltmada bir vebal yok size ve kafirler, zaten size apaçık düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 102, 'Onların içinde bulunur da namaz kıldırırsan onların bir kısmı seninle beraber ve silahları yanlarında olarak namaz kılsın, secde ettiler mi öbür kısmı, arkanızda dursun. Sonra namaz kılmayan takım gelsin, seninle namaz kılsın, kalkanlarını, silahlarını üstlerinde bulundursunlar. Kafirler, birdenbire üstünüze bir saldırışta bulunmak için sizin silahlarınızdan, eşyanızdan gafil olmanızı isterler. Ancak yağmurdan dolayı müşkülata uğrarsanız, yahut hastaysanız silahlarınızı çıkarmada vebal yok size, fakat ihtiyatlı davranın; şüphe yok ki Allah, kafirlere aşağılatıcı bir azap hazırlamıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 103, 'Namazı kıldıktan sonra ayaktayken, otururken ve yanınıza yaslanınca Allah''ı anın, tam emniyete ve huzura ulaşınca da namazı dosdoğru kılın, çünkü namaz, müminlere muayyen vakitlerde kılınmak üzere farz edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 104, 'Düşman olan kavmi takipte gevşek davranmayın. Siz acı duyuyorsanız şüphe yok ki onlar da sizin duyduğunuz acıyı duyuyorlar ve siz Allah''tan, onların ummadığı şeyleri umuyorsunuz ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 105, 'Biz sana kitabı, insanlar arasında Allah''ın sana gösterdiği gibi hükmedesin diye bir gerçek olarak indirdik, hainleri savunma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 106, 'Allah''tan yarlıganma dile, şüphe yok ki Allah, suçları örten rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 107, 'Nefislerine hainlik edenlerden yana çıkıp uğraşma; şüphe yok ki Allah, hainlikte ileri giden suçluları sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 108, 'İnsanlardan gizlerler de Allah''tan gizlemezler, halbuki Tanrının razı olmadığı sözü geceleyin söylerler, düzenler düzerlerken de o, onlarlaydı ve Allah, onların bütün yaptıklarını kavrar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 109, 'İşte siz o kişilersiniz ki dünya hayatında onları tuttunuz, onlar için uğraştınız; fakat kıyamet gününde, Allah''a karşı kim savunacak onları, yahut kim koruyacak onları?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 110, 'Kim bir kötülük eder, yahut nefsine karşı zulümde bulunur da sonra Allah''tan yarlıganmak dilerse Allah''ı, suçları örtücü ve rahim olarak bulur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 111, 'Kim bir suç işlerse o suçu kendi aleyhine kazanmıştır, zararı kendine ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 112, 'Kim bir hatada bulunur, yahut suç işler de onu bir suçsuza isnat ederse iftirada bulunmuş, apaçık bir günahı yüklenmiş olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 113, 'Allah''ın sana lütfü, ihsanı ve rahmeti olmasaydı onların bir kısmı seni bile doğru yoldan çıkarmayı kurmuştu, fakat onlar, ancak kendilerini sapıklığa sevk ederler ve hiçbir hususta sana zarar veremezler ve Allah, sana kitabı ve hikmeti indirdi ve evvelce bilmediğin şeyleri öğretti sana ve Allah''ın, sana lütfü ve ihsanı pek büyüktür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 114, 'Onların toplanıp gizlice konuşmalarının çoğunda hayır yoktur; ancak kim sadakayı, iyiliği ve insanların arasını bulmayı emrederse onun sözünde hayır var. Allah''ın razılığını kazanmak için bunları yapana pek büyük bir mükafat vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 115, 'Kendisince doğru yol apaçık belli olduktan sonra Peygambere aykırı hareket eden ve inananların yolundan başka bir yola giden kişiyi döndüğü yolda bırakırız ve cehenneme atarız; orası, ne de kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 116, 'Şüphe yok ki Allah, kendisine eş tanıyanı yarlıgamaz, bundan başka dilediği kişinin bütün suçlarını örter, yarlıgar ve kim Allah''a eş tanırsa öylesine sapıtmıştır ki tuttuğu yol, doğru yoldan pek uzaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 117, 'Onlar, Allah''ı bırakırlar da dişi saydıkları putlara taparlar, böylece de ancak inatçı Şeytan''a tapmış olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 118, 'Allah''sa ona lanet etmişti, o da demişti ki: Andolsun ki kullarından bir kısmını, ayartacağım da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 119, 'Onları doğru yoldan saptıracağım, olmaz isteklere sürükleyeceğim, putlara hayvanlar adatacağım da onların kulaklarını yarmalarını, Allah''ın yarattığını bozmalarını emredeceğim. Allah''ı bırakıp Şeytan''ı dost edinen, apaçık bir zarara düşmüş, ziyana uğramıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 120, 'Şeytan, onlara vaatlerde bulunur, onları olmayacak isteklere sürükler, kuruntular verir; fakat Şeytan''ın vaatleri, ancak aldatıştan ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 121, 'Onlardır yurtları cehennem olanlar ve oradan başka bir sığınak bulamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 122, 'İnananları ve iyi işlerde bulunanları, kıyılarından ırmaklar akan cennetlere sokacağız, oralarda ebedi kalacaklar; işte Allah''ın gerçek vaadi ve kimdir Allah''tan daha doğru sözlü?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 123, 'Ne sizin boşuna kuruntularınızın aslı var, ne kitap ehlinin kuruntularının aslı. Kim kötülük ederse cezasını görür ve Allah''tan başka ne bir dost bulur, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 124, 'Erkek olsun, kadın olsun, inanıp da iyi işlerde bulunanlar, cennete girerler ve kıl kadar bile zulüm görmezler, hakları zayi olmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 125, 'Kimin dini daha güzeldir iyilikte bulunarak özünü Allah''a teslim eden ve Tanrıyı bir tanıyan İbrahim''in dinine uyan kişinin dininden ve Allah İbrahim''i dost edinmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 126, 'Allah''ındır ne varsa göklerde ve ne varsa yeryüzünde ve Allah, her şeyi kavramış, kuşatmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 127, 'Kadınlar hakkında senden fetva istiyorlar, de ki: Onlar hakkındaki fetvayı Allah veriyor ve kendilerine verilmesi icap eden mirası vermediğiniz ve beğenip almadığınız yetim kızlarla aciz çocuklar hakkında ve yetimlere adaletle muamele hususunda işte size kitapta okunan hüküm. Hayra ait neler yaparsanız şüphe yok ki Allah hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 128, 'Kadın, kocasının kendisine eziyet edeceğinden, yahut kendisini ihmal edeceğinden korkarsa karıyla kocanın, kendi aralarında uzlaşıp barışmaları hususunda her ikisine de vebal yok ve barış, daha hayırlıdır da. Zaten nefislerde nekeslik meyli vardır, fakat iyilik eder, hoş geçinir ve sakınırsanız şüphe yok ki Allah bütün yaptıklarınızdan haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 129, 'Kadınlar arasında adaletle muamele etmeyi ne kadar isteseniz, bu hususa ne kadar düşseniz imkan yok, yapamazsınız, adaletle muamele edemezsiniz. Hiç olmazsa onların birine tamamıyla meyledip öbürünü muallaktaymış gibi bir vaziyete düşürmeyin, uzlaşır ve sakınırsanız şüphe yok ki Allah, suçları örter rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 130, 'Karıyla koca ayrılacak olurlarsa Allah, her birini lütuf ve keremiyle ihtiyaçtan kurtarır ve Allah''ın lütfü boldur, hüküm ve hikmet sahibidir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 131, 'Ve Allah''ındır ne varsa göklerde ve ne varsa yeryüzünde Andolsun ki sizden önce kendilerine kitap verilenlere de, size de Allah''tan çekinmenizi tavsiye ettik. Fakat kafir olursanız şüphe yok ki Allah''ındır ne varsa göklerde ve ne varsa yeryüzünde ve Allah, her şeyden müstağnidir ve övüş ona layıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 132, 'Ve Allah''ındır ne varsa göklerde ve ne varsa yeryüzünde ve koruyucu olarak Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 133, 'Dilerse ey insanlar, sizi ortadan kaldırır, başkalarını getirir ve Allah''ın buna gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 134, 'Dünya mükafatını dileyen bilsin ki dünya mükafatı da Allah''ın yanındadır, ahiret mükafatı da ve Allah her şeyi duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 135, 'Ey inananlar, Allah için daima adaleti tam yerine getirin ve tanıklığı o yolda yapın, hatta kendi aleyhinize, yahut anayla babanın ve yakınların aleyhine bile olsa. Hatta zengin, yahut yoksul bile olsa, çünkü Allah ikisine de sizden daha ziyade sahiptir, sizden daha fazla korur onları ve siz, adaleti icra ederken nefsinizin dileğine uymayın. Bir tarafı gözeterek hüküm verir, yahut birinden yüz çevirirseniz bilin ki Allah, şüphe yok, yaptıklarınızın hepsinden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 136, 'Ey inananlar, inanın Allah''a ve Peygamberine ve Peygamberine indirdiği kitaba ve evvelce inen kitaba ve kim Allah''a, meleklerine, kitaplarına, peygamberlerine ve ahiret gününe inanmazsa şüphe yok ki doğru yoldan pek uzak kalmış, tamamıyla sapıtmış gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 137, 'O kişiler ki iman ettiler de sonra kafir oldular, sonra gene iman ettiler, sonra gene kafir oldular, sonra da küfürlerini arttırdılar, Allah suçlarını örtmez onların ve doğru yola getirmez onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 138, 'Münafıkları, elemli bir azapla müjdele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 139, 'Onlar, inananları bırakırlar da kafirleri dost edinirler. Yüceliği, kudreti onlardan mı umuyorlar, onlardan mı arıyorlar? Hiç şüphe yok ki bütün yücelik ve kudret Allah''ındır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 140, 'Kitapta, Allah''ın ayetlerini inkar ettiklerini ve onlarla eğlendiklerini duyarsanız, başka bir bahisten söz açıncaya dek onlarla oturmayın, yoksa siz de onlara benzersiniz diye size bir emir indirmiştir. Şüphe yok ki Allah, münafıklarla kafirlerin hepsini de cehennemde toplayacaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 141, 'Onlar, sizin ahvalinizi gözetip dururlar. Siz, Allah''ın lütfüyle bir fetih elde ederseniz biz de derler, sizinle değil miydik? Kafirlere bir zafer payı düşse üstünlüğünüzü temin etmedik mi, inananların, size hücumunu menetmedik mi derler. Kıyamet gününde, Allah hakkınızda hükmeder ve Allah, kafirlere, müminler aleyhine bir yol, bir başarı vermez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 142, 'Münafıklar, Allah''ı kandırmak isterler ve o da onların cezasını verir. Onlar, namaza üşenerek kalkarlar, halk görsün diye kılarlar ve Allah''ı pek az anarlar ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 143, 'Onlar, imanla küfür arasında bocalayıp dururlar, ne onlara mal olurlar, ne bunlara ve Allah, kimi doğru yolundan saptırdıysa onu yola getiremezsin artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 144, 'Ey inananlar, müminleri bırakıp da kafirleri dost edinmeyin. İster misiniz kendi aleyhinizde Allah''a apaçık bir delil veresiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 145, 'Şüphe yok ki münafıklar, ateşin en aşağı katındadırlar ve kesin olarak onlara bir tek yardımcı bile bulamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 146, 'Ancak tövbe edenler, ıslah olanlar, Allah''a sarılanlar ve Allah için dinlerinde ihlas sahibi bulunanlar müstesna. Onlar, inananlarladır ve Allah, müminlere pek büyük bir ecir verecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 147, 'Allah ne diye azab etsin size şükrederseniz ve inanırsanız ve Allah şükredenlerin mükafatını verir ve onları bilir zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 148, 'Allah, zulüm gören müstesna, kötü sözün apaçık söylenmesini sevmez ve Allah duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 149, 'Açıkça bir hayır yaparsanız, yahut yaptığınız hayrı gizlerseniz, yahut da gördüğünüz kötülüğü bağışlarsanız bilin ki Allah, şüphe yok, bağışlayıcıdır, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 150, 'Onlar, öyle kişilerdir ki Allah''ı ve peygamberlerini inkar ederler, Allah''la peygamberlerinin arasını ayırmak isterler ve bazısına inandık, bazısına inanmadık derler ve imanla küfür arasında bir yol tutmak isterler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 151, 'İşte onlardır gerçekte kafirler ve biz kafirler için, aşağılatıcı bir azap hazırlamışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 152, 'Allah''a ve peygamberlerine inananlara ve içlerinden hiçbirini ayırt etmeyenlere gelince: Onlara ecirleri verilecektir ve Allah, suçları örten rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 153, 'Kitap ehli, onlara gökten bir kitap indirmeni isterler, Musa''dan bundan da büyük bir şey istemişler, bize Allah''ı apaçık göster demişlerdi de zulümleri yüzünden bir yıldırım düşüp yakıvermişti onları. Sonra da onlara apaçık deliller geldiği halde buzağıya tanrı demişlerdi, gene de bu suçlarını bağışlamıştık da Musa''ya apaçık bir kudret vermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 154, 'Ettikleri ahdi yerine getirsinler diye Tur dağını, oldukları yerin üstünde yüceltmiş ve onlara, şehrin kapısından secde ederek girin demiştik ve cumartesi günü demiştik, haddi aşmayın ve onlardan pek kuvvetli bir söz almıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 155, 'Sonra sözlerinde durmayıp ahitlerini bozmaları, Allah''ın ayetlerini inkar etmeleri, peygamberleri haksız yere öldürmeleri ve kalplerimiz kapalı, anlamıyoruz demeleri yüzünden cezalarını buldular; kalplerini, küfürleri yüzünden Allah kapamıştır, o yüzden de içlerinden ancak pek azı imana gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 156, 'Ve inkar etmeleri, Meryem hakkında söz söylemeleri, ona pek büyük bir iftirada bulunmaları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 157, 'Ve biz Allah''ın peygamberi Meryemoğlu ve Mesih İsa''yı öldürdük demeleri yüzünden cezalarını buldular. Onu öldüremediler de, asamadılar da, onlara öyle göründü. Zaten ihtilafa düştükleri şeyde de onun hakkında zan içindedir onlar, ona ait bir bilgileri yoktur da ancak şüpheye kapılırlar. Gerçekten de apaçık onu öldüremediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 158, 'Allah onu kendisine yüceltti ve Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 159, 'Ve kitap ehlinden hiçbiri kalmayacak ki onun ölümünden önce ona inanmasın, o da kıyamet günü, onların aleyhine tanık olacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 160, 'Yahudi olanlardan meydana gelen zulüm yüzünden de onlara helal edilen tertemiz şeyleri haram ettik ve bu, halkın çoğunu Allah yolunda menetmeleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 161, 'Nehyedildikleri halde faiz almaları ve insanların mallarını haksız yere yemeleri yüzündendir ve biz, içlerinden kafir olanlara elemli bir azap hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 162, 'Fakat onlardan bilgide ileri olanlar ve inananlar, sana indirilene de inanırlar, senden önce indirilenlere de ve namaz kılanlardır, zekat verenlerdir, Allah''a ve ahiret gününe inananlardır onlar ve biz onlara büyük bir ecir vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 163, 'Biz vahyettik sana, nitekim vahyettik Nuh''a ve ondan sonraki peygamberlere ve vahyettik İbrahim''e, İsmail''e, İshak''a, Yakup''a ve evlatlarına ve İsa''ya, Eyyub''a, Yunus''a, Harun''a ve Süleyman''a ve Davud''a Zebur''u verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 164, 'Ve öyle peygamberler var ki onların ahvalini anlattık sana önceden ve Allah Musa ile de konuşmuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 165, 'Ve peygamber, müjdeleyenlerdir ve korkutucu haber verenler; ta ki insanların, peygamberler geldikten sonra Allah''a karşı bir mazeretleri, bir bahaneleri kalmasın artık ve Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 166, 'Fakat Allah, sana indirdiği kitapla tanıklık eder ki onu, bilerek indirmiştir ve melekler de tanıklık ederler ve tanık olarak Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 167, 'Kafir olanlar ve halkı Allah yolundan çıkaranlarsa öylesine sapıtmışlardır ki tuttukları yol, doğru yoldan pek uzaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 168, 'Kafir olanları ve zulmedenleri Allah yarlıgamaz ve onları hiç bir yola sevk etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 169, 'Ancak cehennem yoluna sevk eder, ebedi kalırlar orada ve bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 170, 'Ey insanlar, şüphe yok ki peygamber, Rabbinizden gerçek olarak gelmiştir size, siz de inanın, hayırlıdır size bu. İnkar ederseniz şüphe yok ki Allah''ındır ne varsa göklerde ve yeryüzünde ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 171, 'Ey kitap ehli, dininizde aşırı gitmeyin ve Allah hakkında gerçek olanı söyleyin. Meryemoğlu Mesih İsa, ancak Allah''ın peygamberidir ve Meryem''e ilga ettiği kelimesidir ve kendisine ait bir ruhtur. Artık inanın Allah''a ve peygamberlerine ve Tanrı üçtür demeyin, vazgeçin bundan, bu hayırlıdır size. Allah, ancak tek tanrıdır, oğul sahibi olmaktan münezzehtir ve onundur ne varsa göklerde ve ne varsa yeryüzünde ve koruyucu olarak Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 172, 'Ne Mesih, Allah''a kul olmaktan çekinir, ne de Tanrının kendisine yakınlaştırdığı melekler ve ona kulluktan çekinen ve ululanmak isteyenleri o, tapısında toplayacaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 173, 'İnananların ve iyi işler işleyenlerin ecirlerini ödeyecek ve lütfünü, onlar hakkında daha da arttıracaktır. Kulluktan çekinip ululanmak isteyenleriyse elemli bir azapla azaplandıracaktır ve onlar, Allah''tan başka ne bir dost bulurlar, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 174, 'Ey insanlar, size Rabbinizden reddi mümkün olmayan bir delil gelmiştir ve size apaçık bir nur indirmişizdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 175, 'Allah''a inanıp ona sarılanları o, kendi rahmetine ve ihsanına alacak ve onları doğru yola sevkedecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (4, 176, 'Fetva isterler senden, de ki; Allah size fetva vermede babası ve çocuğu olmayanın mirasına ait: Evladı olmayan bir erkek ölür de onun bir tek kız kardeşi kalırsa bıraktığı malın yarısı onundur. Mirasçı erkek kardeşse çocuğu ve babası olmayan kız kardeşinin bıraktığı bütün mal, onundur; kız kardeş ikiyse, yahut daha fazlaysa erkek kardeşin bıraktığı malın üçte ikisini alırlar. Mirasçılar, aynı şartlar dahilinde erkek ve kız kardeşlerse erkeğe, kadına nispetle iki pay verilir. Allah, size doğru yoldan sapmamanız için bunları açıklamaktadır ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 1, 'Ey inananlar, ahitlerinizi yerine getirin. Dört ayaklı hayvanlar helal edilmiştir size, ancak size söylenecekler müstesna; ihramdayken, helal olan hayvanları avlanmak da haramdır. Şüphe yok ki Allah, dilediğini hükmeder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 2, 'Ey inananlar, Allah''a ibadete vesile olan, hac töreni yapılan yerlerin ve savaşın haram edildiği ayların hürmetini koruyun, hac kurbanlarına, kurban edilecekleri belli olsun diye boynuna bir şey takılan hayvanlara, Rablerinden bir lütfe ve razılığa ulaşmak için Beytül Haram''ı ziyarete gelenlere hürmetsizlik etmeyin. İhramdan çıkınca avlanın. Sizi Mescidi Haram''dan meneden kavme karşı beslediğiniz kin aşırı hareket etmenize, tecavüzde bulunmanıza sebep olmasın. İyilik etmek ve kötülükten sakınmak hususunda birbirinize yardım edin, suç işlemek ve düşmanlık etmek için yardımlaşmayın ve Allah''tan sakının, şüphe yok ki Allah''ın cezası, çok çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 3, 'Haram edilmiştir size ölü, kan, domuz eti, Allah''tan gayrı putlar adına kesilen hayvanlar, boğulmuş, vurulmuş, yüksek bir yerden düşüp ölmüş, başka bir hayvan tarafından süsülüp öldürülmüş, canavar tarafından parçalanmış olanlar; ancak ölmeden yetişip kestikleriniz müstesna; ve taştan yapılmış ve dikilmiş putlar adına kesilenler ve fal için çekilen oklarla rızık arayış. Bunlar, kötülüktür. Bugün kafirler, dininiz yüzünden meyus olmuşlardır artık sizden, korkmayın onlardan, benden korkun. Bugün dininizi ikmal ettim, size verdiğim nimetimi tamamladım, size din olarak Müslümanlığı verdim de hoşnut oldum. Pek aç kalıp zora düşen, suç işlemek niyetinde olmamak şartıyla haram edilen şeyleri yiyebilir ve şüphe yok ki Allah, suçları örter rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 4, 'Kendilerine neler helal edilmiştir diye sana sorarlar. De ki: Size temiz şeyler ve Allah''ın, size öğrettiği bilgiyle öğretip yetiştirdiğiniz avcı hayvanların tuttukları avlar helal edilmiştir. Sizin için tuttuklarını yiyin ve avlanır, avı tutup keserken Allah adını anın ve Allah''tan sakının, şüphe yok ki Allah, pek tez hesap görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 5, 'Bugün size bütün temiz şeyler helal edilmiştir ve kendilerine kitap verilenlerin yemekleri de helaldir size, sizin yemekleriniz de helaldir onlara ve inanan kadınlardan namus ve iffet sahibi olanlarla kendilerine kitap verilenlere mensup namuslu kadınlar da, mehirlerini vermek, zina etmemek ve gizli dost tutmamak şartıyla size helaldir ve kim imanı inkar ederse bütün işledikleri boşa gider ve o, ahirette ziyan edenlerdendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 6, 'Ey inananlar, namaza kalktığınız zaman yıkayın yüzlerinizi ve dirseklerinizle beraber ellerinizi ve başınızın bir kısmını meshedip ayaklarınızı topuklarınızla beraber ve cünüpseniz iyice yıkanıp arının. Hastaysanız, yahut seferdeyseniz, yahut içinizden biri ayak yolundan geldiyse, yahut da kadınlara temas etmişseniz su bulamadığınız takdirde temiz toprakla teyemmüm edin de toprakla yüzünüzü, ellerinizi meshedin. Allah, sizi güce koşmayı istemez, fakat şükredesiniz diye tertemiz olmanızı ve size verdiği nimeti tamamlamayı diler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 7, 'Anın size verilen Allah nimetini ve duyduk, itaat ettik dediğiniz zaman ona vermiş olduğunuz sözü ki bu sözle bağlamıştır sizi ve çekinin Allah''tan. Şüphe yok ki Allah, yüreklerde ne var bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 8, 'Ey inananlar, Allah için daima doğru hükmedin, adalete tam uygun tanıklıkta bulunan ve bir kavme olan kininiz, sizi adaletten alıkoymasın. Adalette bulunun ki bu, takvaya daha yakındır ve çekinin Allah''tan. Şüphe yok ki Allah, ne yaparsanız hepsindende haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 9, 'Allah, inanıp iyi işlerde bulunanlara vaat etti, onlarındır yarlıganma ve pek büyük mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 10, 'Kafir olanlara ve ayetlerimizi inkar edenlere gelince: Onlardır cehennem ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 11, 'Ey inananlar, anın Allah''ın nimetini size, hani bir kavim, size el uzatmaya niyetlenmişti de onların ellerini çektirmişti sizden ve çekinin Allah''tan ve inananların, ancak Allah''a dayanmaları gerek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 12, 'Ve Allah İsrailoğullarından kuvvetli söz almıştı ve onlardan on iki emin adam göndermiştik ve Allah demişti ki: Ben, sizinleyim, namaz kılarsanız, zekat verirseniz, peygamberlerime inanır, onlara yardım edip ulularsanız ve Allah''a borç verircesine onun yolunda yoksulları doyurur, iyilik eder, para harcarsanız mutlaka kusurlarınızı örter ve mutlaka sizi, kıyılarından ırmaklar akan cennetlere sokarım. Fakat bundan sonra içinizden kafir olan, şüphe yok ki doğru yoldan sapmıştır artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 13, 'Ahitlerini bozdukları, verdikleri sözden döndükleri için lanet ettik onlara ve kalplerini katılaştırdık. Onlar, sözlerin yerini değiştirirler, kendilerine verilen öğütten bir hisse de almazlar. Pek azı müstesna daima hainliklerini duyarsın, gene de bağışla onları, geç suçlarından. Şüphe yok ki Allah, iyilik edenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 14, 'Onlardan, biz Nasraniyiz diyenler de var, onlardan da söz aldık, fakat kendilerine verilen öğütten hisse almayı unuttular, biz de kıyamete dek aralarına düşmanlık ve kin saldık. Allah, onların neler yaptığını bildirecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 15, 'Ey kitap ehli, kitapta olduğu halde gizlediklerinizin çoğunu apaçık size bildiren, çoğunu da affedip yüzünüze vurmayan Peygamberimiz gelmiştir size; Allah''tan bir nur ve apaçık bir kitap gelmiştir size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 16, 'Allah, kendi rızasına uyanları, onunla esenlik yollarına götürür ve dileğiyle onları karanlıklardan aydınlığa çıkarır ve onları doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 17, 'Gerçekten de şüphe yok ki Allah, Meryem oğlu Mesih''tir diyenler kafir oldular. De ki: Meryem oğlu Mesih''i de, anasını da ve yeryüzündekilerin hepsini de helak etmeyi dilese Allah''a karşı herhangi bir şeye kim sahip çıkabilir? Ve Allah''ındır göklerin, yeryüzünün ve ikisinin arasında olanların saltanatı. Dilediğini yaratır ve Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 18, 'Yahudiler ve Nasraniler, biz Allah''ın oğullarıyız ve sevgilileriyiz dediler. De ki: Öyleyse neden günahlarınızdan dolayı size azap ediyor? Hayır, siz, ancak onun yarattığı insanlardansınız; o, dilediğini yarlıgar, dilediğine azap eder ve Allah''ındır göklerin, yeryüzünün ve ikisinin arasında bulunanların saltanatı ve her iş, ona aittir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 19, 'Ey kitap ehli, bize ne bir müjdeci geldi, ne bir korkutucu dememeniz için peygamberlerin arasının kesildiği bir devirde size, her şeyi açıklayan Peygamberimiz geldi. İşte size şüphesiz olarak bir müjdeci, bir kokutucu geldi ve Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 20, 'Hatırla o zamanı ki Musa, kavmine, ey kavim demişti, anın Allah''ın size verdiği nimeti ki içinizden peygamberler gönderdi ve padişahlar çıkardı ve size, alemlerde, hiçbir kimseye vermediğini verdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 21, 'Ey kavmim, Allah''ın size vermeyi takdir ettiği kutlu yere girin ve gerisingeriye dönmeyin, yoksa ziyankar olursunuz, ancak ziyana dönersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 22, 'Onlarsa ya Musa demişlerdi, orada zorlu erler var, onlar orada oldukça biz, kesin olarak giremeyiz, ama oradan çıkarlarsa gireriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 23, 'İçlerinden, korkan ve Allah tarafından nimetlere mazhar olmuş bulunan iki kişi, kapıdan girip saldırın üstlerine demişti; oraya girerseniz şüphe yok ki üst olursunuz siz ve ancak Allah''a dayanın inanmışsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 24, 'Ya Musa demişlerdi, onlar orada bulundukça biz, oraya ebediyen giremeyiz. Sen, Rabbinle git, ikiniz çarpışın onlarla, biz burada oturup duracağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 25, 'Musa, ya Rabbi demişti, benim hükmüm ancak kendime, bir de kardeşime geçiyor. Şu kötülük eden kavimle aramızı sen ayır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 26, 'Tanrı demişti ki: Orası, tam kırk yıl onlara haram edildi. Çölde sersemcesine dolaşacaklar, tasalanma o kötülükte bulunanlar için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 27, 'Oku onlara Âdem''in iki oğluna ait gerçek haberi. Hani onlar, Tanrıya yaklaşmak için kurban sunmuşlardı da birininki kabul edilmişti, öbürününki kabul edilmemişti ve o, seni mutlaka öldüreceğim demişti ona, o da demişti ki: Allah ancak, kendisinden çekinenlerin kurbanını kabul eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 28, 'Andolsun, beni öldürmek için elini uzatsan da bana, ben sana, seni öldürmek için elimi uzatmayacağım; çünkü ben, alemlerin Rabbi Allah''tan korkarım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 29, 'Dilerim, kendi suçunla beraber benim suçumu da yüklenesin de cehennem ehlinden olasın ve budur cezası zulmedenlerin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 30, 'Nihayet kardeşini öldürme hususunda nefsine uydu da öldürdü onu ve ziyankarlardan oluverdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 31, 'Sonra, kardeşinin cesedini nasıl örteceğini göstermek için Allah, bir karga gönderdi. Bu karga, yeri eşmedeydi. Yazıklar olsun bana dedi, kardeşimin cesedini gömmede şu karga kadar bile olamadım ha? Ve o, artık nedamet edenlere katılmıştı zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 32, 'Bu yüzden şu hükmü yazdık İsrailoğullarına: Şüphe yok ki bir insanı öldürmesine, yahut yeryüzünde bozgunculuk etmesine karşılık olmayarak birisini öldüren, bütün insanları öldürmüş gibidir ve kim, birisini kurtarır, diriltirse bütün insanları diriltmiş gibidir. Andolsun ki peygamberlerimiz, onlara apaçık delillerle geldiler de gene onların çoğu, bundan sonra yeryüzünde hadlerini aştılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 33, 'Allah''a ve Resulüne savaş açanlarla yeryüzünde bozgunculuk etmeye koşanların cezaları, ancak öldürülmektir, yahut asılmaktır, çapraz olarak elleriyle ayaklarının kesilmesidir, yahut da bulundukları yerden sürülmeleridir. Bu, onların dünyada uğradıkları horluktur, ahiretteyse pek büyük bir azap vardır onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 34, 'Ancak onlardan, ele geçmeden tövbe edenler, bu hükümden dışarıdır. Şüphesiz olarak bilin ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 35, 'Ey inananlar, çekinin Allah''tan ve onu vesileyle arayın ve savaşın onun yolunda da muradına erenlerden olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 36, 'Kafir olanlar, yeryüzünde ne varsa hepsine, hatta bir misli fazlasına sahip olsalar da kıyamet gününün azabından kurtulmak için hepsini verseler gene makbule geçmez ve onlara pek elemli bir azap vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 37, 'Ateşten çıkmak isterlerse de çıkamaz onlar ve onlar içindir sürüp giden bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 38, 'Erkek olsun, kadın olsun, hırsızlık edenlerin, elde ettiklerine karşılık, Allah tarafından ibret verici bir ceza olarak kesin ellerini ve Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 39, 'Ettiği zulümden sonra tövbe eden ve düzgün bir hale gelenin tövbesini Allah kabul eder. Şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 40, 'Bilmez misin Allah''ı ki göklerin de tasarrufu ona aittir, yeryüzünün de ve dilediğine azap eder, dilediğini yarlıgar ve Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 41, 'Ey Peygamber, ağızlarıyla inandık diyen, fakat yürekleriyle inanmayanlardan ve Yahudilerden, boyuna kafirliğe koşuşanlar, seni mahzun etmesin. Onlar, sözleri, yalan söylemek için boyuna dinleyip dururlar, senin yanına gelmemiş olan bir başka kavim için dinlerler boyuna. Onlar, sözlerin bazısının yerlerini değiştirirler de size şu tarzda fetva verilirse derler, kabul edin, verilmezse çekinin kabul etmekten ve Allah, kime azab etmek isterse sen, Allah''ın isteğine karşı o adama hiçbir şey yapamazsın. Onlar, öyle kişilerdir ki Allah, yüreklerini temizlemeyi murad etmemiştir. Onlar içindir dünya da horluk ve onlar içindir ahirette pek büyük bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 42, 'Onlar, yalan söylemek için boyuna dinlerler, haramı ve rüşveti de boyuna yerler. Sana gelirlerse aralarında hüküm ver, yahut da yüz çevir onlardan. Yüz çevirirsen, kesin olarak sana hiçbir zarar veremez onlar ve eğer hüküm verirsen, aralarında, adaletle hüküm ver, şüphe yok ki Allah, adalet sahiplerini sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 43, 'Nasıl oluyor da içinde Allah''ın hükmü bulunan Tevrat, yanlarındayken senin hükmüne baş vuruyorlar, sonra da gene bu hükümden yüz çeviriyorlar? Onlar, zaten inanmamışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 44, 'Şüphe yok ki biz, Tevrat''ı indirdik, onda doğru yola sevk ediş ve nur var. Tanrıya teslim olan peygamberlerle hükümleri bilenler ve Allah kitabını korumaya memur olan bilginler, Yahudilere, hep ona göre hüküm verirlerdi ve hepsi de o kitabın doğruluğuna tanıktı. Artık insanlardan korkmayın, benden korkun ve ayetlerimi, az bir menfaat karşılığında satmayın ve kimler, Allah''ın indirdiği hükme uygun olarak hüküm vermezlerse onlardır kafirlerin ta kendileri', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 45, 'Ve o kitapta onlara hükmettik ki cana karşılık can, göze karşılık göz, burna karşılık burun, kulağa karşılık kulak, dişe karşılık diş ve yaralara karşılık da yaralarla kısas var. Fakat kim bağışlar da hakkından geçerse bu, suçlarının yarlıganmasına sebep olur ve kimler, Allah''ın indirdiği hükme göre hüküm vermezlerse onlardır zalimlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 46, 'Onların izinden de, ellerinde bulunan Tevrat''ı gerçeklemek üzere Meryemoğlu İsa''yı gönderdik ve ona, içinde doğru yola sevk eden hükümler ve nur bulunan ve ellerindeki Tevrat''ı gerçekleyen, çekinenleri doğru yola sevk eden sakınanlara öğüt olan İncil''i verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 47, 'İncil ehli de, Allah''ın o kitapta indirdiği hükümlerle hüküm versinler. Ve kimler Allah''ın indirdiği hükme göre hüküm vermezlerse onlardır Tanrı buyruğundan çıkanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 48, 'Ve sana da, önceki kitabı gerçekleyen ve ona, emin bir tanık olan kitabı, gerçek olarak indirdik. Artık aralarında, Allah''ın indirdiğine göre hüküm ver ve sana gelen gerçekten dönüp onların isteklerine uyma. Sizden her birerinize bir şeriat, bir yol tayin ettik ve Allah dileseydi bir ümmet yapardı sizi, fakat size verdiği hükümler hususunda sizi sınamaktadır, siz de hayırlı işlerde yarışın artık ve hepinizin dönüp varacağı yer, Allah tapısıdır ve o, haklarında ayrılığa düştüğünüz şeyleri size haber verecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 49, 'Aralarında, Allah''ın indirdiği hükümlere göre hükmet ve onların dileklerine uyma, Allah''ın, sana indirdiği hükümlerin bazısından seni saptıracaklarından çekin. Yüz çevirirlerse bil ki ancak Allah, onları bazı suçlarından dolayı musibete uğratacak veinsanların çoğu da buyruktan çıkmış olanlardır zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 50, 'Hala mı cahiliyet devrinin hükmünü aramadalar? Gerçeği, şüphesiz bir surette bilenler yanında hükmü, Allah''tan daha güzel olan kimdir ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 51, 'Ey inananlar, Yahudilerle Nasranileri dost edinmeyin. Onlar, birbirlerinin dostudur ve sizden kim onları dost edinirse şüphe yok ki o da, onlardandır. Şüphe yok ki Allah, zalim olan kavmi doğru yola sevk etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 52, 'Yüreklerinde bir hastalık olanları ve bir felakete uğramamızdan korkuyoruz, diyerek onların içine katılan, onlara koşanları görürsün. Fakat belki de Allah bir fetih verir, yahut kendi katından bir iş çıkarır meydana da onlar, içlerinde gizledikleri şeyden dolayı nadim oluverirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 53, 'İnananlar da derler ki, sizinle beraber olduklarına dair bütün kuvvetleriyle yemin edenler bunlar mı? İşte yaptıkları boşa çıktı, ziyankar oluverdiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 54, 'Ey inananlar, içinizden kim çıkar da dininden dönerse Allah onlara bedel öyle bir kavim getirecektir yakında ki o onları sevecek, onlar da, onu sevecek, inananlara karşı alçak gönüllü, kafirlere karşı yüce olacak o kavim. Allah yolunda savaşacaklar ve hiçbir kınayanın kınamasından korkmayacaklar. Bu, Allah''ın lütfü ve inayetidir ki dilediğine verir ve Allah''ın lütfü boldur, o her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 55, 'Sizin dostunuz, sahibiniz, ancak Allah''tır ve Peygamberidir ve inananlar, namaz kılanlar ve rüku ederken zekat verenlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 56, 'Ve kim, Allah''tan, Peygamberinden ve inananlardan yüz çevirirse bilsin ki hiç şüphesiz Allah''a mensup olanlardır üst olacak kişiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 57, 'Ey inananlar, sizden önce, kendilerine kitap verilenlerle kafirlerden, dininizi alay konusu yapan, onu oyuncak sayan kişileri dost edinmeyin, çekinin Allah''tan inanmışsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 58, 'Birbirinizi namaza çağırdığınız, ezan okuduğunuz zaman, bununla alay ederler, bir oyun sayarlar bunu. Bu da şüphe yok ki akılları olmayan, akıl edemeyen bir kavim olduklarındandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 59, 'De ki: Ey kitap ehli, bizden hoşlanmayışınızın sebebi, ancak Allah''a ve bize indirilene ve bizden önce indirilenlere inanmamızdan başka bir şey mi ki? Ve sizin çoğunuz, buyruktan çıkmış kişilersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 60, 'De ki: Bundan daha fena olanları, Allah''ın cezasına uğramış bulunanları haber vereyim mi size? Allah''ın lanet ettiği, gazabına uğrattığı, içlerinden bir kısmını maymun ve domuz şekline soktuğu kişiler ve Şeytan''a tapanlar. İşte bunlardır yeri daha kötü olanlar, doğru yoldan daha fazla sapmış bulunanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 61, 'Sizin yanınıza geldiler mi, inandık derler, halbuki onlar, bulunduğunuz yere kafirlikle girdikleri gibi gene kafirlikle çıkmışlardır ve Allah, onların gizlediğini, onlardan daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 62, 'Onların çoğunu görürsün ki suç işlemekte, düşmanlık etmekte, haram yemekte birbirleriyle yarışa girerler. Yaptıkları şey, ne de kötüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 63, 'Bari, hükümleri bilenleri ve bilginleri, onları, suç olan sözleri söylemekten ve haram yemekten menetselerdi. İşledikleri iş, ne de kötüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 64, 'Yahudiler, Allah''ın eli bağlıdır dediler, elleri bağlanasılar, söyledikleri söz yüzünden lanete uğrayasılar. Hayır, Allah''ın iki eli de açıktır, dilediği gibi ihsanda bulunur. Andolsun, Rabbinden sana indirilen, onlardan çoğunun azgınlığını, kafirliğini arttıracak ve biz, onların arasına kıyamete dek düşmanlık ve kin saldık. Ne vakit savaş için bir ateş yaktılarsa Allah söndürdü o ateşi ve onlar, yeryüzünde bozgunculuğa koşup dururlar ve Allah, bozguncuları sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 65, 'Kitap ehli olanlar inansalardı, çekinselerdi elbette kötülüklerini örterdik ve elbette onları da nimeti bol cennetlere sokardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 66, 'Tevrat''ın, İncil''in ve Rablerinden sana indirilen kitabın hükümlerini tutsalardı tepelerinden ayaklarının altlarından nimetlere nail olurlar, onları yerlerdi. İçlerinde geri ve aşırı olmayan insaf ehli de var, fakat çoğunun yaptığı işler, ne de kötü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 67, 'Ey Peygamber, bildir, sana Rabbinden indirilen emri ve eğer bu tebliği ifa etmezsen onun elçiliğini yapmamış olursun ve Allah, seni insanlardan korur. Şüphe yok ki Allah, kafir olan kavme, doğru yola gitmek hususunda başarı vermez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 68, 'De ki: Ey kitap ehli, hiçbir şeye inanmış sayılmazsınız Tevrat''ın, İncil''in ve Rabbinizden size indirilen kitabın hükümlerini yerine getirmedikçe ve andolsun ki Rabbinden sana indirilen, onlardan çoğunun azgınlığını, kafirliğini arttıracak, artık o kafir kavim yüzünden tasalanma sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 69, 'Fakat inananlarla Yahudi olanlardan, Sabilerden ve Hıristiyanlardan Allah''a ve ahiret gününe inanıp iyi işler işleyenlere ne bir korku vardır, ne de mahzun olur onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 70, 'Andolsun ki İsrailoğullarından söz almıştık, peygamberler göndermiştik onlara. Fakat hangi peygamber onlara gelip canlarının istemediği bir şey getirdiyse o peygamberlerin bir kısmını yalanlamışlardı, bir kısmını öldürmüşlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 71, 'Ve sandılar ki bir cezaya uğramayacaklar. Kör oldular adeta, sağır kesildiler, sonra tövbe ettiler, Allah kabul etti, sonra gene de çoğu körleşti, sağır oldu ve Allah, onların yaptıklarını tamamıyla görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 72, 'Allah, şüphe yok ki Meryem oğlu Mesih''tir diyenler kafir oldular ve Mesih, ey İsrailoğulları demişti, Rabbime ve Rabbinize kulluk edin; şüphe yok ki Allah''a eş tanıyana Allah, cenneti haram etmiştir, onun yurdu ateştir ve zalimlere hiçbir yardımcı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 73, 'Şüphe yok ki kafir olmuşlardır, Allah, üçün üçüncüsüdür diyenler ve kulluk edilecek tek bir Tanrı vardır ancak. Söyledikleri sözden dönmezlerse içlerinden kafir olanlar, pek elemli bir azaba uğrayacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 74, 'Hala mı tövbe etmeyecekler Allah''a ve hala mı yarlıgamasını istemeyecekler? Ve Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 75, 'Meryemoğlu Mesih, bir peygamberden başka bir şey değildi; ondan önce de nice peygamberler gelip geçtiler; annesi de gerçek bir kadındı, ikisi de yemek yerlerdi. Bak bir, onlara delillerimizi nasıl açıklamadayız, sonra da bak, nasıl yüz çeviriyor onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 76, 'De ki: Allah''ı bırakıp size ne bir zararı dokunacak, ne bir faydası gelecek bir varlığa mı kulluk ediyorsunuz? Ve Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 77, 'De ki: Ey kitap ehli, haksız yere dininizde, aşırı gitmeyin ve evvelce hem sapmış, hem çoğunu saptırmış ve doğru yolu bırakıp sapıklığa dalmış olan kavmin dileklerine uymayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 78, 'İsrailoğullarından kafir olanlara Davud''un diliyle de lanet edilmişti, Meryemoğlu İsa''nın diliyle de. Bu da isyan ettiklerinden ve aşırı gittiklerindendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 79, 'İşledikleri kötülükten, birbirlerini menetmezlerdi. Gerçekten de yaptıkları iş, ne de kötüydü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 80, 'Onların çoğunu görürsün ki kafirlere dostluk ederler. Ne de kötüdür nefislerinin, onlara hazırlayıp sunduğu şey; Allah''ın gazabına uğrayacaklardır ve azap içinde ebedi olarak kalacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 81, 'Allah''a, Peygambere ve ona indirilene inansalardı onları dost edinmezlerdi. Fakat onlardan çoğu, buyruktan çıkmış kötü kişilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 82, 'İnsanların, inananlara düşmanlıkta en ileri gidenleri, göreceksin, Yahudilerle müşriklerdir, inananlara sevgi bakımından en yakınları da biz Nasraniyiz diyenlerdir. Bunun sebebi de, onların içinde ilimle, ibadetle uğraşanlarla rahiplerin bulunuşudur ve bir de onlar, ululanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 83, 'Peygamberlere indirileni duydular mı gerçeği tanıdıklarından görürsün ki gözleri yaşla dolar da taşar. Derler ki: Rabbimiz, inandık biz, bizi gerçeğe tanık olanlardan et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 84, 'Zaten Rabbimizin bizi de iyi insanlara katmasını umup dururken ne oluyor bize ki Allah''a ve bize gelen gerçeğe inanmayalım?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 85, 'Allah da onları söyledikleri söz yüzünden, kıyısından ırmaklar akan cennetlere sokarak mükafatlandırır, orada ebedi olarak kalırlar ve budur işte iyilik edenlerin mükafatı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 86, 'Kafir olanlarla ayetlerimizi yalanlayanlara gelince onlardır cehennem ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 87, 'Ey inananlar, Allah''ın size helal ettiği tertemiz şeyleri haram etmeyin kendinize ve aşırı gitmeyin. Şüphe yok ki Allah, aşırı gidenleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 88, 'Ve yiyin Allah''ın size rızık olarak verdiği şeylerden helal ve temiz olanları ve inandığınız Allah''tan çekinin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 89, 'Boş yere yemin etmenizden dolayı sorumlu tutmaz sizi Allah, fakat yürekten ve kasten ettiğiniz yeminler yüzünden sorumlu tutar. Yemin kefareti, ailenize yedirdiğiniz yemeklerin orta derecede olanıyla on yoksulu doyurmak, yahut onları giydirmek, yahut da bir kul azat etmektir. Bunlara gücü yetmeyen üç gün oruç tutar. İşte yemininizi bozarsanız budur kefareti. Koruyun yeminlerinizi. Allah, şükredenlerden olursunuz diye ayetlerini işte böyle açıklar size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 90, 'Ey inananlar, şarap, kumar, tapınmak için dikilmiş olan taşlar, fal için kullanılan oklar, ancak Şeytan''ın işlerindendir ve birer pisliktir bunlar. Bunlardan kaçının da muradına erenlerden olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 91, 'Şeytan, şarap ve kumarla sizin aranıza düşmanlık ve kin salmak ister ancak, vazgeçtiniz artık değil mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 92, 'Ve itaat edin Allah''a ve Peygambere ve sakının. Yüz çevirirseniz iyice bilin ki Peygamberimize düşen vazife, ancak tebliğden ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 93, 'İman edip iyi işlerde bulunanlara; çekindikleri, inandıkları ve iyi işlerde bulundukları, sonra gene çekinmede devam ettikleri, inançlarını güttükleri, sonra da gene çekinip durdukları ve iyilik ettikleri takdirde haram edilmeden önce yedikleri şeyler yüzünden bir vebal yok ve Allah iyilik edenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 94, 'Ey inananlar, Allah, onu görmeksizin de kendisinden korkan kişiyi ayırt etmek için ellerinizin ulaşabileceği, mızraklarınızın yetişebileceği avları avlanma hususunda sizi sınayacak mutlaka. Bundan sonra kim aşırı hareket ederse ona pek acı bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 95, 'Ey inananlar, ihramdayken avlanmayın; içinizden kim, bir av hayvanını bilerek öldürürse sizden iki adalet sahibinin hükmüne göre cezası, öldürdüğü hayvanın benzeri olan ve Ka''be''ye götürülen bir hayvanı kurban etmek, yahut işlediği suça karşılık yoksulları doyurmak, yahut da bunlara denk olacak kadar oruç tutmaktır, böylece yaptığının cezasını tatması gerektir. Allah, geçmişte işlenen suçları bağışlamıştır. Fakat bundan böyle de kim bu suçu işlerse şüphe yok ki Allah öç alır ondan ve Allah üstündür, öç alıcıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 96, 'Denizde avlanmak ve avladığını yemek, geçiminiz için size de, misafirlerinize de helal edilmiştir de ihramda bulunduğunuz müddetçe kara avı haram edilmiştir size. Çekinin o Allah''tan ki onun tapısında toplanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 97, 'Allah, Kabe''yi hac ayını, kurbanı, kurbanlık olduğu bilinsin diye boynuna bir şey asılan hayvanları, insanların geçimine, düzenine sebep etti, böylece de şüphesiz olarak Allah''ın, göklerde ve yeryüzünde ne varsa hepsini bildiğini sizin de bilmenizi diledi ve Allah, şüphe yok ki her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 98, 'Bilin ki Allah''ın cezası, muhakkak pek çetindir ve şüphe yok ki Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 99, 'Peygamberin vazifesi, ancak tebliğdir ve Allah, açığa vurduğunuz şeyleri de bilir, gizlediğiniz şeyleri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 100, 'De ki: Pisle temiz bir değildir, pisin çokluğu seni şaşırtsa bile. Artık ey aklı tam olanlar, çekinin Allah''tan da muradınıza erin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 101, 'Ey inananlar, size açıklanınca hoşunuza gitmeyecek şeyleri sormayın Kur''an indirilirken bunlara ait bir şey sorarsanız hükmü açıklanır size, halbuki Allah geçmişti ondan, ona ait hükmü bildirmemişti ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 102, 'Sizden önce de bir kavim onları sordu da sonra kafir oluverdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 103, 'Allah, ne bahireyi meşru kılmıştır, ne saibeyi, ne vasilayı, ne de hamı; fakat kafir olanlar, Allah''a, yalan yere iftira ederler ve onların çoğunun da aklı ermez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 104, 'Onlara, gelin Allah''ın indirdiğine ve Peygambere dendi mi bize yeter atalarımızın yapageldikleri şeyler, böyle bulduk biz derler. Fakat ya ataları da bir şey bilmiyorlardı ve doğru yola gitmiyorlardıysa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 105, 'Ey inananlar, siz, kendinize bakın; doğru yolu buldunuzsa sapık kişi, size bir zarar veremez. Hepinizin de dönüp varacağı yer, Allah tapısıdır ve o mutlaka yaptığınız şeyleri bildirir size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 106, 'Ey inananlar, birinize ölüm gelip çatarsa aranızda vasiyet edeceğiniz zaman, sizden iki adil tanık bulunsun. Yolculuktaysanız ve gene size ölüm musibeti gelip çatacaksa sizden olmayan iki kişiyi de tanık tutabilirsiniz. Ancak onları, namazdan sonraya dek alıkoyun da akraba bile olsa Allah''ı bırakıp yerine hiçbir menfaati satın almayacağız, tanıklığımızı, Allah için gizlemeyeceğiz, gizlersek günahkarlardan olalım diye Allah''a yemin etsinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 107, 'O iki tanığın bir günahı hakkettikleri anlaşılırsa miras hakkında sahip olanlardan ve tanıklığa daha ziyade layık bulunanlardan iki kişi, onların yerine geçer, bizim tanıklığımız, onların tanıklığından daha doğrudur ve biz zulmetmedik, ettiysek zalimlerden olalım diye Allah''a yemin ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 108, 'Bu, hakkıyla tanıklık etmelerini, yahut yeminden sonra tanıklıklarının, yeminlerinin reddedilmesinden korkmamalarını sağlamaya daha yakındır. Ve çekinin Allah''tan ve dinleyin. Allah kötülükte, taşkınlıkta bulunan kavmi doğru yola sevk etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 109, 'O gün Allah, bütün peygamberleri toplayacak da ne cevap verildi size diyecek. Diyecekler ki: Bilgimiz yok bizim, şüphe yok ki sensin gizli şeyleri hakkıyla bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 110, 'An o zamanı ki Allah ey Meryemoğlu İsa, hatırla sana ve annene verdiğim nimetimi demişti, hatırla ki seni RuhülKudüs''le kuvvetlendirdim de beşikteyken de insanlarla konuştun, olgunluk çağında da. Hani sana kitabı, hikmeti, Tevratı ve İncil''i öğretmiştim. Hani topraktan kuş şeklinde bir şey yapardın iznimle de ona üfürürdün, o da iznimle kuş olurdu ve anadan doğma körün gözünü açar, abraş illetine uğrayanı o illetten kurtarırdın iznimle ve hani ölüyü, iznimle mezardan çıkarmış, diriltmiştin. Hani, İsrailoğullarına apaçık delillerle geldiğin zaman onlardan kafir olanlar, bu ancak açık bir büyü demişlerdi de ben seni kurtarmıştım onların elinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 111, 'Hani Havarilere, bana ve Peygamberime inanın demiştim de inandık demişlerdi tanık ol, biz Tanrıya teslim olanlarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 112, 'Hani Havariler, ey Meryemoğlu İsa demişlerdi, Rabbin, bize gökten bir sofra yemek indirebilir mi? İsa da inanmışsanız demişti, çekinin Allah''tan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 113, 'Demişlerdi ki: İstiyoruz ki o yemekten yiyelim, kalplerimiz tam bir inanca ulaşsın ve bilelim ki sen bize doğru söylüyorsun ve buna da tanık olalım biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 114, 'Meryemoğlu İsa, Rabbimiz demişti, bize gökten bir sofra yemek indir de bugün, hem önce gelenlerimize bayram olsun, hem sonra gelenlerimize, hem de senden bir delil olsun; sen bizi rızıklandır ve sen, rızık verenlerin en hayırlısısın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 115, 'Allah, onu size indireceğim ben, fakat bundan sonra içinizden kafir olanı öyle bir azapla azaplandıracağım ki demişti, alemler içinde hiçbir kimseyi o çeşit azaplandırmam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 116, 'Ve hani Allah, ey Meryemoğlu İsa diyecek, sen misin insanlara, Allah''ı bırakın da beni ve annemi iki tanrı tanıyın diyen? İsa da seni noksan sıfatlardan arı bilirim diyecek, hakkım olmayan bir sözü söyleyemem ki ben. Böyle bir söz söylediysem elbette bilirsin bunu. Benim içimde ne varsa hepsini mutlaka bilirsin sen. Fakat ben, senin bildiğini bilemem; şüphe yok ki sen gizli olan her şeyi, hakkıyla bilirsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 117, 'Onlara, ancak bana emrettiğini söyledim, Rabbime ve Rabbinize kulluk edin dedim. İçlerinde bulundukça gözetirdim, korurdum onları, fakat beni aldıktan sonra onların ne yaptıklarını sen gördün ve sen her şeye hakkıyla tanıksın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 118, 'Onlara azap edersen şüphe yok ki onlar, senin kullarındır ve eğer yarlıgarsan şüphe yok ki sensin üstün olan, hüküm ve hikmet sahibi bulunan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 119, 'Allah diyecek ki: Bugün, öyle bir gündür ki gerçeklerin gerçekliği fayda eder ancak. Onlarındır kıyılarından ırmaklar akan cennetler, ebedi kalırlar orada. Allah onlardan razı olmuştur, onlar da ondan razı olmuşlardır. İşte budur en büyük kurtuluş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (5, 120, 'Allah''a aittir göklerin yeryüzünün ve oralarda ne varsa hepsinin tasarrufu ve onun her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 1, 'Hamt Allah''a ki gökleri ve yeryüzünü halketti, karanlıkları ve ışığı yarattı, sonra da kafir olanlar, taptıklarını Rableriyle denk tutarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 2, 'O, öyle bir Tanrıdır ki sizi balçıktan yaratmıştır da ölüm vaktini takdir etmiştir ve kıyametin kopacağı zamana ait bilgi de ondadır, onun katındadır, sonra gene de şüphe edersiniz siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 3, 'Odur göklerde de, yeryüzünde de Allah. Gizlediğinizi de bilir, açığa vurduğunuzu da ve ne kazanacağınızı da bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 4, 'Onlara Rablerinin ayetlerinden bir ayet gelmemiştir ki ondan yüz çevirmesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 5, 'Kendilerine, gerçek olan Kur''an gelince onu yalanlarlar, fakat yakında gelecek onlara, alay ettikleri şeye ait haberler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 6, 'Görmediler mi onlardan önce nice nesilleri helak ettik ki onlara, yeryüzünde size vermediğimiz imkanları, kudretleri vermiş, onları yeryüzüne yerleştirmiştik, üstlerine bolbol yağmur yağdırmıştık, ayaklarını bastıkları yerlerden ırmaklar akıtmıştık, fakat sonra suçları yüzünden helak ettik onları ve onlardan sonra da başka başka nesiller meydana getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 7, 'Sana, kağıda yazılı bir kitap indirseydik ve ona elleriyle dokunsalardı gene de kafir olanlar derlerdi ki: Bu, ancak apaçık bir büyü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 8, 'Diyorlar ki: Ona bir melek indirilseydi. Melek indirseydik iş, olur biterdi ama sonra kendilerine gözlerini yumup açacak kadar bile bir mühlet verilmezdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 9, 'Peygamberi, bir melek olarak halk etseydik gene bir erkek şeklinde halk ederdik ve gene düştükleri şüpheden kurtulmazlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 10, 'Senden önceki peygamberlerle de alay edildi de alay edenler, alaylarının cezasına uğradılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 11, 'De ki: Gezin yeryüzünü de görün inkar edenlerin sonları ne olmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 12, 'De ki: Kimindir ne varsa göklerde ve yeryüzünde? De ki: Allah''ın; rahmet etmeyi gerekli kıldı özüne. Kıyamet günü hepinizi de tapısında toplayacak ve hiç şüphe yok o günün geleceğinde. Kendilerine ziyan edenlerdir inanmayanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 13, 'Geceleyin ve gündüzün yaşayıp barınan ne varsa hepsi, onundur ve odur duyan, bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 14, 'De ki: Gökleri ve yeryüzünü yoktan var eden Allah''tan başkasını mı dost edineyim ve o, yedirip doyurur, yiyip doymaya ihtiyacı yoktur. De ki: Bana, Müslüman olanların ilki olmam ve müşriklerden olmamam emredildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 15, 'De ki: Ben, Rabbime isyan edersem pek büyük günün azabından korkarım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 16, 'O gün azaptan kurtarılana şüphe yok ki rahmet etmiştir ve budur en büyük kurtuluş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 17, 'Allah sana bir zarar verirse o zararı, ondan başka açıp giderecek yoktur, sana bir hayır verirse zaten odur her şeye gücü yeten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 18, 'Kulların üstünde tek tasarruf sahibidir o ve odur hüküm ve hikmet sahibi her şeyden haberdar olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 19, 'De ki: En büyük tanıklık nedir, hangisidir? De ki: Allah, gerçek tanıktır benimle sizin aranızda ve bana bu Kur''an, sizi ve kime ulaşırsa onu korkutmam için vahyedildi. Siz, Allah''la beraber tapılacak başka bir mabud olduğuna mı tanıklık ediyorsunuz? De ki: Ben tanıklık etmem. De ki: O, ancak tek mabuttur ve benim, sizin ona eş tuttuklarınızla hiçbir ilgim yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 20, 'Kendilerine kitap verdiklerimiz, Peygamberi, oğullarını tanıdıkları gibi tanırlar, fakat kendilerine zarar verenlerdir inanmayanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 21, 'Kimdir Allah''a boş yere iftira edenden, yahut onun ayetlerini yalanlayandan daha zalim? Şüphe yok ki zalimler, muratlarına erişmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 22, 'Ve o gün hepsini de toplar da sonra Tanrıya şirk koşanlara deriz ki: Nerede size yardım edecek sanıp şirk koştuklarınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 23, 'Sonra onlar ancak Rabbimiz Allah, sana andederiz ki biz şirk koşanlardan değildik demekten başka bir özür serdedemezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 24, 'Hele bak, nasıl da bilebile yalan söylerler ve iftira konuları da nasıl ortadan kaybolup gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 25, 'Onlardan seni dinleyenler de var ve biz, dinledikleri sözleri anlamamaları için kalplerini perdeleriz, kulaklarını ağırlaştırırız da bütün delilleri görseler gene de inanmazlar onlara. Nihayet de yanına geldiler mi çekişmeye başlarlar seninle ve bunlar, ancak evvelce gelip geçenlere ait masallar derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 26, 'Onlar hem insanları uzaklaştırırlar ondan, hem kendileri uzaklaşırlar. Onlar anlamadan ancak kendilerini helak ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 27, 'Ateşin başında durduruldukları zaman bir görseydin onları. Keşke dünyaya tekrar döndürseler bizi de Rabbimizin ayetlerini yalanlamasak ve inananlardan olsak derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 28, 'Hayır; evvelce gizledikleri belirdi artık, göründü onlara. Geriye döndürülseler de gene nehyedildikleri şeyleri yapmaya koyulurlar ve şüphe yok ki onlar, yalancılardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 29, 'Ve dediler ki: Bu dünyada yaşayışımızdan başka bir yaşama yok bize ve biz tekrar dirilmeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 30, 'Rablerinin tapısında durduruldukları vakit onları bir görseydin. Rableri, bu gerçek değil mi der, Rabbimize andolsun derler, evet, gerçek. Rableri de öyleyse kafirliğiniz yüzünden tadın azabı der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 31, 'Gerçekten de ziyana uğramışlardır Allah''a kavuşmayı yalan sayanlar. Nihayet ansızın başlarına kıyamet kopunca günahlarını sırtlarına yüklenirler de yaptığımız taşkınlıklardan dolayı yazıklar olsun bize derler; ne de kötü yüktür taşıdıkları yükler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 32, 'Dünya yaşayışı, ancak bir oyundan, bir oyalanmadan ibaret. Âhiret yurduysa çekinenlere elbette daha hayırlı. Hala mı aklınız ermeyecek?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 33, 'İyice biliriz ki onların söylediği sözler, seni mahzun edecek. Fakat şüphe yok ki onlar seni yalanlamış olmazlar, o zalimler, bilebile Allah''ın ayetlerini inkar ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 34, 'Andolsun ki senden önceki peygamberler de yalanlandı da onlar, kendilerine yardımımız erişinceye dek sözlerinin yalan sayılmasına ve uğradıkları eziyetlere katlandılar ve Allah''ın sözlerini değiştirecek yoktur ve sana da o peygamberlerin haberleri gelmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 35, 'Onların yüz çevirmeleri sana pek ağır geliyorsa gücün yeterse yeraltında bir yurt kurmaya, yahut gökyüzüne bir merdiven dayamaya bak da onlara bir delil getir. Fakat Allah dileseydi onların hepsine de doğru yolu gösterirdi. Artık sakın bilgisizlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 36, 'Senin davetine ancak seni dinleyenler icabet eder. Ölüleriyse Allah diriltir de sonra gene dönüp onun tapısına varırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 37, 'Rabbinden ona bir delil indirilse derler. De ki: Allah''ın delil indirmiye gücü yeter ama onların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 38, 'Yeryüzünde yürüyen hiçbir hayvan ve kanatlarıyla uçan hiçbir kuş yoktur ki sizin gibi o da bir cinse mensup olmasın. Biz, kitapta hiçbir şeyi eksik bırakmadık, sonra da hepsi Rablerinin tapısında toplanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 39, 'Âyetlerimizi yalanlayanlar, karanlıklarda kalmış sağırlardır, körlerdir. Allah kimi isterse doğru yoldan saptırır ve kimi dilerse doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 40, 'De ki: Gerçekseniz, size Allah''ın azabı gelirçatar, yahut başınıza kıyamet koparsa Allah''tan başkasını mı çağırır, ondan başkasına mı dua edersiniz, bana haber verir misiniz siz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 41, 'Hayır; ancak onu çağırırsınız, o da dilerse duanızı kabul eder de uğradığınız belayı açıp giderir ve şirk koştuklarınızı unutur, gidersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 42, 'Andolsun ki senden önceki ümmetlere de peygamberler yolladık da yalvarmaya düşsünler diye onları şiddetli sıkıntılara, kıtlığa ve hastalığa uğrattık biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 43, 'Onlara azabımız geldiği vakit olsun, yalvarmaları gerekirdi, fakat yalvarmadılar bile, kalpleri katılaştı ve Şeytan, yaptıkları şeyleri süsleyip hoş gösterdi onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 44, 'Derken söylenenleri, verilen öğütleri unuttukları zaman her şeyin kapılarını açtık onlara ve onlar, kendilerine verilen şeylerle genişliğe ulaştıkları gibi hemen ve ansızın onları tutup alıverdik de bütün umduklarından mahrum oldular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 45, 'Böylece de zulmeden kavmin kökü kesildi ve hamd, alemlerin Rabbi Allah''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 46, 'De ki: Allah kulaklarınızı sağır, gözlerinizi kör eder ve kalplerinizi mühürlerse Allah''tan başka hangi mabuttur dersiniz onları size geri verecek? Bak da gör, nasıl deliller getiriyoruz da gene onlara yüz çeviriyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 47, 'De ki: Allah''ın azabı ansızın, yahut açıkça gelip çatsa size, zulmeden kavimden başkası helak edilir mi dersiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 48, 'Biz, peygamberleri ancak müjdeci ve korkutucu olarak gönderdik. Şu halde inananlara ve kendilerini düzgün bir hale getirenlere ne korku vardır, ne de mahzun olur onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 49, 'Âyetlerimizi inkar edenlerse kötülükte bulunduklarından dolayı azaba uğratılacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 50, 'De ki: Ben size, Allah''ın hazineleri yanımda da demiyorum, gaibi bilirim, ben bir meleğim de demiyorum. Ben, yalnız bana vahyedilen şeye uymadayım. De ki: Körle gözü açık kişi bir olur mu hiç? Ne diye hala düşünmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 51, 'Rablerinin tapısında hasredilmeden korkanları Kur''an''la korkut ve çekinsinler diye de bildir ki onlara, Rablerinden başka ne bir dost vardır, ne de bir şefaatçi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 52, 'Sabah, akşam, razılığını dileyerek Rablerine dua edenleri kovma; ne onlardan, herhangi bir hususta sen sorumlusun, ne de senin amelinden onlara bir şey sorulur, onun için onları kovup da haksızlık edenlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 53, 'Ve biz, Allah''ın, aramızdan seçip lütfettiği bunlar mı demeleri için halkın bir kısmını, bir kısmıyla sınarız. Allah, şükredenleri daha iyi bilmez mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 54, 'Âyetlerimize inananlar sana gelince de ki: Esenlik size, Rabbiniz, rahmet etmeyi kendisine gerekli kılmıştır; şüphe yok ki içinizden biri, bilgisizlik yüzünden bir kötülük yapar da sonradan tövbe eder, halini düzene korsa muhakkak ki Tanrı, suçları örter, yarlıgar, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 55, 'Suçluların yolu yoradamı iyice meydana çıksın diye delilleri bu çeşit açıklamadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 56, 'De ki: Ben, Allah''ı bırakıp da taptıklarınıza tapmaktan nehyedildim. De ki: Sizin dileğinize uymam ben. Uyarsam şüphe yok ki doğru yoldan sapmış olurum ve doğru yolu bulanlardan olmam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 57, 'De ki: Ben, sizin yalan saydığınız apaçık, bellibeyan deliline uydum Rabbimin. Çabucak gelmesini istediğiniz azap da benim elimde değil. Hüküm, ancak Allah''ın, doğruyu haber veren odur ve odur ayırt edenlerin en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 58, 'De ki: Hemencecik olmasını istediğiniz şey, benim elimde olsaydı sizinle aramdaki iş çoktan olur, biterdi ve Allah, zalimleri elbette daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 59, 'Gaibin anahtarları, onun yanındadır, onları ancak o bilir; karada ve denizde ne varsa bilir. Bir yaprak bile düşse bilir onu ve yeryüzünün karanlıkları içinde bir tek tane yoktur ki, yaş ve kuru hiçbir şey bulunamaz ki apaçık kitapta tespit edilmemiş olsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 60, 'O, öyle bir Tanrıdır ki geceleyin adeta sizi öldürür, gündüzün ne çeşit işlerde bulunacağınızı bilir, sonra sizi gündüz diriltir de mukadder olan ölümünüze dek bu, böyle gider, ölümden sonra da dönüp varacağınız yer, onun tapısıdır, sonra ne yaptıysanız hepsini size haber verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 61, 'Odur kullarından yüce tasarruf ve kudret sahibi ve size, amellerinizi hıfz ve kaydeden melekler göndermiştir. Nihayet birinizin ölümü geldi mi elçilerimiz, onu öldürürler ve onlar, artık ve eksik iş görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 62, 'Sonra, her işi doğru olan kudret ve tasarruf sahibi Tanrılarının tapısına götürülürler. Bilin ki hüküm onundur ve o, hesap görenlerin en tez hesap görenidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 63, 'De ki: Sızlanıp yalvararak gizlice, bizi bundan kurtarırsan şükredenlerden oluruz diye dua ettiğiniz zaman sizi karanın ve denizin karanlıklarından kurtaran kimdir?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 64, 'De ki: Ondan da sizi kurtaran Allah''tır, bütün sıkıntılardan da; sonra gene ona şirk koşarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 65, 'De ki: Üstünüzden, ayaklarınızın altından size azap göndermeye, yahut sizi bölükbölük edip bir kısmınızın azabını bir kısmınıza tattırmaya gücü yeter onun; anlasınlar diye bak, delilleri nasıl çeşitçeşit açıklamadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 66, 'Kavmin, Kur''an''ı yalan saymada, halbuki o, gerçektir. De ki: Ben, sizi koruyucu değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 67, 'Her haberin mukadder bir zamanı var, siz de öğrenir, bilirsiniz yakında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 68, 'Âyetlerimize dair münasebetsiz sözlere daldıklarını görünce bir başka bahse girişinceye dek yüz çevir onlardan. Şeytan, bunu sana unutturursa hatırladıktan sonra artık zulmeden kavimle oturma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 69, 'Çekinenler, onların meclislerinde bulunsalar da onların sorumluluğundan bir şey gelmez kendilerine, üstlerine düşen ödev, çekinsinler, sakınsınlar bu işten diye öğüt vermektir ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 70, 'Dinlerini bir oyundan, bir eğlenceden ibaret sayan ve dünya yaşayışına aldanan kişileri bırak kendi hallerine. Sen, ancak Kur''an''la öğüt ver de hiç kimse, kazandığı suçlar yüzünden helak olmasın. Ona, Allah''tan başka ne bir dost vardır, ne bir şefaatçi. Suçlu, varınıyoğunu, kurtuluşu için feda etse kabul edilmez. Kazançları yüzünden helak olanlar, inkarlarından dolayı kaynar su içeceklerdir ve pek acı bir azap vardır onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 71, 'De ki: Allah''ı bırakıp da bize ne faydaları dokunan, ne zararları erişen şeylere mi ibadet edelim ve Allah bize doğru yolu gösterdikten sonra tekrar geriye mi dönelim, hani Şeytanların şaşırtıp sersem bir halde çöle düşürmek istedikleri adam gibi, halbuki arkadaşları, bize gel diye onu doğru yola çağırıp durmadadır. De ki: Şüphe yok ki Allah''ın gösterdiği yoldur doğru yol ve bize, alemlerin Rabbine teslim olmamız emredildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 72, 'Namaz kılın ve Tanrıdan çekinin dendi ve o, öyle bir Tanrıdır ki varıp toplanacağınız yer, onun tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 73, 'Öyle bir Tanrıdır ki gökleri ve yeryüzünü, boş yere değil, hikmetiyle ve gerçek olarak yarattı. Ol dediği gün her şey oluverir. Sözü gerçektir ve surun üfürüldüğü gün saltanat ve tasarruf onundur, odur gizliyi de bilen, açıkta olanı da ve odur hüküm ve hikmet sahibi, her şeyden haberdar olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 74, 'Hani İbrahim, atası Âzer''e, putları mabut mu tanıyorsun demişti, şüphe yok ben, seni de, kavmini de apaçık bir sapıklığa düşmüş görmedeyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 75, 'Biz, gerçek ve şüphesiz bilgiye sahip olması için İbrahim''e, göklerdeki ve yeryüzündeki kudret ve saltanatı, tasarruf ve hikmeti böylece göstermedeydik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 76, 'Gece olup karanlık basınca bir yıldız görmüş de budur Rabbim demişti. Fakat yıldız battı mı demişti ki: Ben batanları sevmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 77, 'Sonra Ayın doğmakta olduğunu görmüş de Rabbim bu demişti. Fakat batınca andolsun ki demişti, Rabbim bana doğru yolu göstermezse sapık kavimden olacağım ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 78, 'Derken güneşin ışıklar saçarak doğduğunu görmüş, Rabbim bu demişti, bu daha büyük. Fakat güneş de batıp gidince ey kavim demişti, benim, sizin şirk koştuğunuz şeylerle hiçbir ilgim yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 79, 'Hiç şüphem olmaksızın mabudumu tek tanıyarak yüzümü, gökleri ve yeryüzünü yaratana döndüm ve ben, şirk koşanlardan değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 80, 'Kavmi, onunla çekişmeye girişince de Allah bana doğru yolu buldurduktan sonra da onun hakkında benimle çekişmeye mi kalkıyorsunuz demişti, ben, sizin Tanrıya eş tanıdıklarınızdan korkmam, Rabbim ne dilerse o olur. Rabbimin bilgisi her şeyi kavramıştır, hala mı düşünmeyecek, öğüt kabul etmeyeceksiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 81, 'Siz, hiçbir delile sahip olmadığınız halde o putları Allah''a eş tanımaktan korkmuyorken ben o eş tanıdıklarınızdan nasıl korkarım ki? Biliyorsanız söyleyin, bu iki taraftan hangisine, daha fazla inanılır, hangi taraf, daha ziyade emniyete hak kazanmıştır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 82, 'İnananlar ve inançlarını haksızlıkla karıştırmayanlardır emin olmaya hak kazananlar ve onlardır doğru yolu bulmuş olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 83, 'İşte, İbrahim''e, kavmine serdetmek için verdiğimiz kesin deliller bunlardı, dilediğimiz kişinin derecesini katkat yüceltiriz biz. Şüphe yok ki Rabbin hüküm ve hikmet sahibidir, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 84, 'Ona İshak''ı ve Yakup''u verdik, hepsine de doğru yolu ihsan ettik. Daha önce Nuh''u ve soyundan Davud''u, Süleyman''ı, Eyyub''u, Yusuf''u, Musa''yı ve Harun''u doğru yola sevketmiştik ve biz, iyilik edenleri böylece mükafatlandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 85, 'Zekeriyya''ya, Yahya''ya, İsa''ya ve İlyas''a da doğru yolu lütfettik, hepsi de doğru hareket eden kişilerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 86, 'İsmail''e, Elyesa''a, Yunus''a ve Lut''a da doğru yolu ihsan etmiştik, hepsini de alemlere üstün kılmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 87, 'Onların atalarından, soylarından ve kardeşlerinden bir kısmına da üstünlük verdik, onları seçtik ve doğru yola sevkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 88, 'İşte Allah''ın doğru yolu budur, kullarından dilediğini o yola sevk eder. Onlar da şirk koşsalardı bütün yaptıkları boşa giderdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 89, 'Bunlar, kendilerine kitap, hükmetme yetkisi ve peygamberlik verdiğimiz kişilerdir. Kafirler, bunları tanımazlar, inkar ederlerse zaten biz, kafir olmayacak bir topluluğu onların yerine geçmeye memur etmişizdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 90, 'Onlar, Allah''ın doğru yola sevkettiği kimselerdir, sen de onların yoluna uy. De ki: Ben, yaptığıma karşılık sizden bir ücret istemiyorum, bu, ancak alemlere bir öğüt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 91, 'Allah, hiçbir kimseye hiçbir şey indirmedi dedikleri zaman Allah''ı layıkıyla tanımadılar, ululamadılar. De ki: Musa''nın, insanlara bir ışık ve onları doğru yola sevk eden bir vasıta olarak getirdiği kitabı kim indirdi? Hanisiz onu kağıtlara yazdınız da yayıp açıklarsınız, hükümlerinden çoğunu da gizlersiniz, hani siz de, atalarınız da, bilmediğiniz şeyleri onun sayesinde bildiniz, öğrendiniz. De ki: Allah indirdi, sonra da bırak onları, düştükleri boş iddialarla oyalanıp dursunlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 92, 'Sana, şehirlerin anası olan Mekke halkını ve çevresindeki bütün insanları korkutmak, Tanrı azabını onlara haber vermek için bu kutlu ve onlarda bulunan kitapları gerçekleyici kitabı indirdik ve ahirete inananlar, namazlarını daima kılarak bu kitaba da inanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 93, 'Allah''a boş yere iftira edenden, yahut, kendisine hiçbir şey vahyedilmediği halde bana da vahyedildi diyenden ve Allah''ın indirdiği hükümlere benzer hükümleri ben de yakında indireceğim diye söylenenden daha zalim kimdir ki? Meleklerin, ellerini uzattıkları ve delillerine karşı ululuk satmak istediğinizden ve haksız olarak Allah hakkında söylediğiniz şeylerden dolayı horlukla cezalandırılacak, aşağılık bir azaba uğrayacaksınız, haydi, kurtarın bugün canlarınızı dedikleri zaman o zalimlerin, ölümün şiddetiyle nasıl kıvrandıklarını bir görmelisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 94, 'Andolsun ki size verdiğimiz her şeyi arkanızda bırakmışsınız da sizi evvelce nasıl yarattıysak tıpkı onun gibi tek başınıza, yapayalnız huzurumuza gelmişsiniz. Sizce Tanrıya eş olan şefaatçilerimizi de yanınızda görmüyoruz. Aranızdaki bağlar, tamamıyla kopmuş, boşuna umduklarınız elinizden çıkmış, kaybolup gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 95, 'Şüphe yok ki tohumları ve çekirdekleri yarıp nebatları ve ağaçları yetiştiren Allah''tır. Ölüden diri izhar eder, diriden ölü. Budur Allah işte, nasıl oluyor da ondan yüz çeviriyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 96, 'Sabahı ağartan oldur. Geceyi huzur ve istirahat için, güneşle ayı da muayyen bir hesapla devretmek üzere yaratmıştır. Bu, üstün ve her şeyi bilen Tanrının takdiridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 97, 'Öyle bir mabuttur ki karada ve denizde, karanlıklar içine dalmışken yolunuzu bulmanız için yıldızları yaratmıştır. Bilen topluluğa delillerimizi apaçık anlatmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 98, 'Sizi bir tek kişiden meydana getirmiştir de size bir eğlenecek yurt, bir de eğreti olarak kalınacak yer tayin etmiştir. Anlayan topluluğa delillerimizi açıkça bildirmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 99, 'Gökten yağmur yağdıran da odur. Sonra o yağmurla her çeşit nebatı tomurcuklandırır, yeşertir, ondan da başaklar içinde birbirine bitişmiş, istiflenmiş taneler meydana getirir. Hurma tomurcuklarından, elle yetişilecek kadar yakın salkımlar, bir bakımdan birbirine benzeyen, bir bakımdan benzemeyen üzümlerden, zeytinlerden, narlardan bağlarbahçeler yetiştiririz. Bir meyve verince bakın onlara, bir de meyveleri olunca. Şüphe yok ki bütün bunlarda, inanan topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 100, 'Bir de Allah''a cinleri eş tanıdılar, halbuki onları da yaratan odur ve bilgisizlikle, onun oğulları, kızları olduğunu da uydurdular. O onların tavsif ettiği şeylerden arıdır ve yücedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 101, 'Gökleri ve yeryüzünü eşsiz örneksiz yoktan var eden odur. Eşi bulunmasına imkan yokken oğlu nasıl olabilir? Ve her şeyi o yaratmıştır ve o, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 102, 'İşte Rabbiniz Allah; ondan başka tapacak yok. Her şeyi halk eden odur, ancak ona kulluk edin ve her şeyi gözetip koruyan odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 103, 'Gözler onu göremez, o, gözleri görür, odur lütfü bol ve her şeyden haberdar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 104, 'Şüphe yok ki Rabbinizden görgüler ihsan edildi size. Kim can gözünü açıp görürse faydası kendisine, kör olanın ziyanı da gene kendine ve ben, sizin üstünüze dikilmiş bir bekçi değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 105, 'Sen bunu öğrenmişsin dememeleri için delilleri çeşitçeşit bildirmede ve bilen topluluğa apaçık anlatmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 106, 'Rabbinden sana vahyedilene uy, ondan başka tapacak yoktur ve şirk koşanlardan yüz çevir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 107, 'Allah dileseydi şirk koşmazlardı ve biz, seni onların üstüne bir bekçi dikmedik, onları korumaya, işlerini görüp kendilerini gözetmeye memur da değilsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 108, 'Allah''tan başka çağırıp dua ettikleri şeylere sövmeyin ki sonra bilgisizlikle onlar da Allah''a söverler. İşte biz, böylece her topluluğa, yaptıklarını süsleyip güzel gösterdik, sonra da dönüp varacakları yer, Rablerinin tapısıdır ve o da, ne yaptıklarını bildirir onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 109, 'Onlar, kendilerine bir delil gelirse inanacaklarına dair çok sıkı yemin ettiler. De ki: Deliller, Allah katındadır, fakat delil gelse de inanmayacaklarını anlamaz mısınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 110, 'Biz, onların gönüllerini, gözlerini tersine çevirmişiz, evvelce inanmadıkları gibi gene inanmazlar ve biz, onları taşkınlıklarında şaşkın bir halde terketmişiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 111, 'Onlara melekler indirseydik, ölüler dirilip onlarla konuşsaydı, her şeyi toplayıp önlerine koysaydık gene Allah dilemedikçe inanmazlardı, fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 112, 'İşte biz, böylece her peygambere insan ve cin Şeytanlarını düşman ettik; bazısı, bazısına yaldızlı sözler söyleyerek aldatır. Rabbin dileseydi yapamazlardı bunu, onları da bırak, iftiralarını da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 113, 'Onlar, ahirete inanmayanların gönülleri meyletsin ve hoşnut olsunlar da yapageldiklerine devam etsinler diye söylerler o sözleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 114, 'Allah''tan başka bir hakem mi arayayım ki size, her muhtaç olduğunuz şeyi bildirip açıklayan kitabı, o indirmiştir. Kendilerine kitap verilenler de bilirler ki o, senin Rabbin tarafından gerçek olarak indirilmiş bir kitaptır; artık şüphe edenlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 115, 'Rabbinin sözleri, gerçek olarak ve adalet üzere tamdır, tekemmül etmiştir, sözlerini değiştirecek yoktur ve odur duyan, bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 116, 'Yeryüzünde bulunanların çoğuna uyarsan seni Allah yolundan saptırır; çünkü onlar, ancak zanna kapılırlar ve onlar, ancak yalan söylerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 117, 'Şüphe yok ki Rabbin, kendi yolundan sapanı daha iyi bilir ve o daha iyi bilir doğru yolu bulmuş olanları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 118, 'Onun ayetlerine inanmışsanız Allah''ın adı anılarak kesilenleri yiyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 119, 'Size ne oluyor da Allah''ın adı anılarak kesilenleri yemiyorsunuz? Halbuki zorada kaldığınız zamanlar hariç, size haram edilenleri ayırt etmişti. Şüphe yok ki halkın çoğu, bilmeden kendi istekleriyle sapıp gider. Şüphe yok ki Rabbin, haddini aşanları daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 120, 'Günahın açığa vurulanından da vazgeçin, gizli kalanından da. Günah kazananlar, kazançlarına karşılık cezalanacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 121, 'Allah''ın adı anılarak kesilmeyen hayvanları yemeyin ve şüphe yok ki kötülüktür bu ve şüphe yok ki Şeytanlar, sizinle çekişmeleri için dostlarına telkinde bulunurlar, onlara uyarsanız siz de şirk koşanlardan olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 122, 'Ölüyken diriltip insanların arasında yol alması için kendisine bir ışık verdiğimiz kimse, karanlıklara dalmış olan ve bir türlü de çıkamayan kimseye benzer mi hiç? İşte böylece kafirlere, yaptıkları şeyler, süslü ve hoş gösterilmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 123, 'Ve böylece her şehirde, hileler, düzenler kursunlar diye o şehrin günahkarlarını büyülttük, yücelttik, onlar ancak kendilerine karşı hilekarlıkta bulunurlar ama bilmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 124, 'Bir ayet geldi mi, Allah''ın peygamberlerine geldiği gibi bize de bir ayet gelmedikçe kesin olarak inanmayız derler. Peygamberliğini kime vereceğini Allah bilir. O suç işleyenlere, hilekarlıkları yüzünden Allah katından bir horluk ve çetin bir azap gelip çatacaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 125, 'Allah, kimi doğru yola götürmek isterse Müslümanlığı kabul etmesi için gönlünü açar ve kimi sapıtmak isterse gönlünü öyle bir daraltır, sıkar ki sanki göğe ağacakmış da imkan bulamıyor sanır kendisini. İşte Allah, inanmayanlara böyle azap verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 126, 'Ve budur Rabbinin doğru yolu, düşünüp öğüt alacak topluluğa ayetlerimizi apaçık bildirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 127, 'Onlarındır Rablerinin katında esenlik yurdu ve o, yaptıkları işlerden dolayı dosttur onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 128, 'O gün hepsini toplar da ey cin topluluğu, insanların birçoğunu baştan mı çıkardınız der. İnsanlardan, onlara dost olanlar, Rabbimiz derler, biz, birbirimizden faydalandık ve bize takdir ettiğin vakte de eriştik işte. Tanrı, ateştir yurdunuz der, orada Allah''ın dilediği hariç, ebedi olarak kalırsınız. Şüphe yok ki Rabbin hüküm ve hikmet sahibidir, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 129, 'İşte biz, kazandıkları suç yüzünden zalimlerin bir kısmını, bir kısmına böyle musallat ederiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 130, 'Ey cin ve insan topluluğu, içinizden, size ayetlerimi nakleden ve içinde bulunduğunuz şu günün bir zaman olup geleceğini haber vererek sizi korkutan peygamberler gelmedi mi? Aleyhimize tanıklık ediyoruz derler ve onları dünya yaşayışı aldatmıştır da sonucu, kafir olduklarına dair kendi aleyhlerine kendileri tanıklıkta bulunmuşlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 131, 'Bu da, halkının hiçbir şeyden haberi olmayan şehirleri, Rabbinin zulümle helak etmeyeceğinden dolayıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 132, 'Herkesin, yaptığına göre dereceleri var ve Rabbin, onların yaptıklarından gafil değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 133, 'Rabbin, her şeyden müstağni ve rahmet sahibi Rab''dir. Dilerse sizi ortadan kaldırır ve sizden sonra dilediğini yerinize getirir, nitekim sizi de başkabaşka toplulukların soyundan meydana getirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 134, 'Muhakkak size vaadedilen şeyler gelecek ve siz, olacak şeylerin önüne geçemezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 135, 'De ki: Ey kavmim, siz elinizden geleni yapın, ben de yapmadayım. Yakında bilir, anlarsınız kimin sonunun hayırlı olacağını. Şüphe yok ki zalimler, muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 136, 'Allah''ın yarattığı ekinlerle hayvanlardan Allah''a bir hisse ayırıp boş düşüncelerine göre bu Allah''ın diyorlardı, bu da ortaklarımız olan putların. Putlara ait olanlar, Allah''a ulaşmıyordu ama Allah''a ait olanlar, ortaklarına, putlara kavuşuyordu, hükmettikleri şey ne de kötüydü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 137, 'Ve gene böylece ortakları, onları helak etmek ve inançlarına şüpheler karıştırmak için müşriklerin çoğuna çocuklarını öldürmeyi hoş gösterdi. Allah dileseydi yapamazlardı bunu, artık sen onları da kendi hallerine bırak, boş yere ettikleri iftiralarına da aldırış etme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 138, 'Onlar, kendi akıllarınca bu hayvanlarla ekinler haramdır, ancak izin verdiğimiz kişiler yiyebilir onları ve şu hayvanlara da binmek haram edilmiştir dediler. Boş yere Allah''a iftira ederek adını anmadan hayvan kesiyorlar, yakında bu iftiralarının cezasını görecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 139, 'Ve şu hayvanların karınlarındaki yavrular, yalnız erkeklerimize helal, kadınlarımıza haram; ölü doğarsa erkek de ortak, kadın da dediler. Bu çeşit sözleri yüzünden cezalarını yakında verecek. Şüphe yok ki o, hüküm ve hikmet sahibidir, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 140, 'Muhakkak ki bilgisizlik yüzünden akılsızca hareket ederek çocuklarını öldürenlerle Allah''a boş yere iftirada bulunarak Allah''ın verdiği rızıkları haram sayanlar, zarara uğramışlar, mahrumiyet içinde kalmışlardır. Şüphesiz ki onlar sapıtmışlardır ve doğru yolu bulamamışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 141, 'Öyle bir mabuttur ki çardaklı ve çardaksız bağları, bahçeleri, tatları çeşitli hurmaları, ekilmiş şeyleri, bir bakıma birbirine benzeyen, bir bakıma benzemeyen zeytinleri ve narları yetiştirip meydana getirir. Meyve verince meyvelerinden yiyin, devşirme günü hakkını da israf etmemek şartıyla verin, şüphe yok ki o, müsrifleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 142, 'Hayvanlardan yüklerinizi taşıyanlar var, yününden faydalandıklarınız var ve onları da yaratan o Allah''ın, sizi rızıklandırdığı şeyleri yiyin ve Şeytan''ın izini izlemeyin; şüphe yok ki o, size apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 143, 'Derler ki sekiz çifttir o hayvanlar. Koyun iki çift, keçi iki çift. De ki: Erkekleri mi haram etti, dişileri mi, yoksa o dişilerin rahimlerindeki yavruları mı? Sözünüz gerçekse bilerek haber verin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 144, 'Deve iki çifttir, sığır iki çift derler. De ki: İki erkeği mi haram etti, yoksa dişileri mi, yahut da dişilerin rahimlerindeki yavruları mı? Allah, bunu size tavsiye ederken tanık mıydınız, gördünüz, duydunuz mu yoksa? Bilmeden insanları saptırmak için yalan yere Allah''a iftira edenden daha zalim kimdir ki? Şüphe yok ki Allah, zulmeden kavmi doğru yola sevk etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 145, 'De ki: Bana vahyedilenler arasında ölmüş hayvan etinden, dökülmüş kandan, yahut da domuz etinden başka, yiyene haram edilen bir şey bulamıyorum ben. Şüphe yok ki domuz, pistir ve bir de Allah''tan başkası için kesilen hayvan haramdır ki bu da pek kötü bir şeydir. Ancak zorada kalana, isyan etmeyi kurmamak ve ihtiyaçtan fazla da yememek şartıyla helaldir bunlar ve hiç şüphe yoktur ki Rabbin, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 146, 'Biz, Yahudilere, tırnakları bulunan bütün hayvanları ve sırtlarına yapışmış, yahut kemiklerine sıvanmış, yahut da bağırsaklarına karışmış olan yağlardan başka sığır ve koyunun tekmil yağlarını haram etmiştik. Bu da, isyanlarından dolayı onlara verdiğimiz ceza yüzündendi ve şüphe yok ki biz, sözümüzde doğruyuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 147, 'Seni yalanlarlarsa hemen de ki: Rabbiniz geniş, engin bir rahmete sahiptir, fakat azabını da suçlu kavimden reddetmeye imkan yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 148, 'Şirk koşanlar diyecekler ki: Allah dileseydi ne biz şirk koşardık, ne atalarımız; hiçbir şeyi de haram saymazdık. İşte onlardan önce gelenler de peygamberleri böyle yalanladılar da sonucu azabımızı tattılar. De ki: Bu hususta bir bilginiz varsa hemen bildirin bize. Fakat siz, ancak zannınıza uyuyorsunuz ve ancak yalan söylüyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 149, 'De ki: O halde reddedilemeyecek kesin delil, ancak Allah''ındır, elbette dileseydi hepinizi de doğru yola sevk ederdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 150, 'De ki: Allah''ın, şunu haram ettiğine tanıklık eden şahitlerinizi getirin bakalım. Fakat gelirler de tanıklık ederlerse sen, onlarla beraber tanıklık etme ve putları, Rableriyle bir tutup ahirete inanmayarak ayetlerimizi yalanlayanların dileklerine uyma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 151, 'De ki: Gelin de Rabbiniz, size neleri haram etti, ben okuyup anlatayım: Sakın ona hiçbir şeyi eş ve ortak saymayın, ananıza, babanıza karşı iyilikte bulunun ve yoksulluk korkusuyla çocuklarınızı öldürmeyin, sizi de ancak biz rızıklandırırız, onları da ve açığa çıkan kötülüklere de yaklaşmayın, gizli kalan kötülüklere de ve hiçbir cana kıymayın, çünkü Allah, haklı olmadıkça haram etmiştir bunu. İşte aklınızı başınıza alasınız diye size bunları emretmiştir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 152, 'Ergenlik çağına gelinceye dek, en iyi bir şekilde olmadıkça yetimin malına yaklaşmayın ve ölçeği, teraziyi dosdoğru ölçüp tartın. Hiçbir kimseye, kudretinden aşırı bir şey teklif edilmemiştir ve söz söylediğiniz zaman hısımınız bile olsa adaleti mutlaka gözetin ve Allah''la ettiğiniz ahde vefa edin. İşte düşünüp öğüt almanız için bunları emretmiştir size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 153, 'Ve şüphe yok ki budur benim dosdoğru yolum, ona uyun siz ve sizi, onun yolundan ayıracak yollara gitmeyin. Çekinip sakınasınız diye işte bunları emretmiştir size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 154, 'Sonra, Rablerine kavuşacaklarına inansınlar diye iyilik edenlere, nimetimizi tamamlamak ve her şeyi ayırt edip açıklamak üzere doğru yolu gösteren ve rahmetten ibaret olan kitabı Musa''ya vermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 155, 'Bu kitabıysa kutlu olarak indirdik, artık ona uyun ve çekinin de rahmete kavuşanlara katılın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 156, 'Hiç şüphe yok ki bizden önce ancak iki taifeye kitap indirildi ve bizse onu okumaktan acizdik, bir şey anlamıyorduk demeyesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 157, 'Yahut da bize de kitap indirilseydi onlardan daha mükemmel bir surette doğru yolu bulurduk diye söylenmeyesiniz diye şüphe yok ki Rabbinizden size de apaçık bir delil, bir hidayet ve rahmet geldi. Allah''ın delillerini yalanlayıp onlardan yüz çevirenden daha zalim kimdir ki? Delillerimizden yüz çevirenleri, bu yüz çevirmeleri yüzünden en kötü bir azapla azaplandıracağız yakında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 158, 'Hala kendilerine meleklerin inmesini, yahut Rabbinin, yahut da Rabbinden bazı delillerin gelmesini mi bekliyorlar? Rabbinin bazı delilleri geldiği gün hiç kimseye, önceden iman etmemişse, yahut inancından bir hayır kazanmamışsa o günkü inanması fayda etmez. De ki: Bekleyin ve biz de beklemekteyiz zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 159, 'Dinlerini parçaparça, bölüp bölükbölük fırkalara ayrılanlarla hiçbir ilgin olamaz ve şüphe yok ki onların bu hareketlerini Allah soracaktır ancak ve sonra da işledikleri işleri haber verecektir onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 160, 'Kim bir iyilikle Tanrı tapısına gelirse ona, yaptığının on misli mükafat verilecektir ve kim bir kötülükle gelirse ancak ona karşılık ve onun misli bir ceza ile cezalandırılacaktır ve onlara zulmedemeyecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 161, 'De ki: Şüphe yok, Rabbim, beni doğru yola sevketti, İbrahim''in tek Tanrı tanıyan dosdoğru dinine hidayet etti ve o, hiçbir zaman şirk koşanlardan değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 162, 'De ki: Şüphe yok, namazım da, ibadetlerim de, diriliğim de, ölümüm de alemlerin Rabbi olan Allah içindir ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 163, 'Eşi ortağı yoktur onun ve bana bu emredildi ve ben, ona teslim olanların ilkiyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 164, 'De ki: Allah''tan başka bir Rab mi arıyacakmışım, halbuki odur her şeyin Rabbi ve herkesin kazancı, ancak kendisine aittir; hiçbir suçlu, bir başkasının suçunu yüklenmez, sonra da dönüp varacağınız yer, Rabbinizin tapısıdır ve o, ayrılığa düştüğünüz şeyleri haber verir size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (6, 165, 'Öyle bir mabuttur ki sizi yeryüzüne hakim kılar ve size verdiği şeylerle sizi sınamak için bir kısmınızı, bir kısmınızdan mevki ve paye bakımından yüceltir. Şüphe yok ki Rabbin, cezaya layık olanın cezasını pek tez verir ve şüphe yok ki o, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 1, 'Elif lam mim sad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 2, 'Bu bir kitaptır ki insanları onunla korkutman, inananlara da öğüt vermen için sana indirildi; bu yüzden yüreğinde bir sıkıntı, göğsünde bir darlık hasıl olmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 3, 'Rabbinizden size ne indirildiyse ona uyun, ondan başkalarını dost edinip onlara uymayın, fakat ne kadar da azınız öğüt tutmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 4, 'Biz nice şehirler helak etmişiz ki azabımız gelip çattığı zaman ya geceydi; halk, uykuya dalmıştı, yahut da gündüzdü, öğle uykusundaydı, dinlenmedeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 5, 'Azabımız geldiği zaman ancak, biz zulmetmiştik diye niyaz edebildiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 6, 'Kendilerine peygamber gönderdiklerimizi de mutlaka sorguya çekeceğiz, peygamber olarak gönderdiklerimizi de sorumlu tutacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 7, 'Onlara, tam bir bilgiyle her şeyi nakledeceğiz, bizim bulunmadığımız bir zaman, kaybolduğumuz bir vakit yoktu ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 8, 'O gün tartı olacak, gerçektir bu. Kimlerin iyi amelleri, terazide ağır gelirse onlardır kurtulanlar, muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 9, 'Kimlerin hafif gelirse onlardır ayetlerimizi inkar ederek zulmettiklerinden kendilerine yazık edenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 10, 'Andolsun ki sizi yeryüzüne yerleştirdik, yaşama ve geçinme vasıtalarını da halkettik, ne de az şükredersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 11, 'Andolsun ki sizi yarattık, sonra bir suret, bir şekil verdik size, sonra da meleklere, Âdem''e secde edin dedik, hemen secdeye kapandılar, yalnız İblis secde edenlere katılmadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 12, 'Tanrı, sana emrettiğim zaman neden secde etmekten çekindin, seni meneden sebep neydi dedi. O, ben ondan daha hayırlıyım dedi, beni ateşten halkettin, onu balçıktan yarattın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 13, 'Tanrı in oradan dedi, artık orada kalıp ululanamazsın, çık, şüphe yok ki sen alçaklardansın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 14, 'İblis, bana, tekrar dirilecekleri, kalkacakları güne kadar mühlet ver dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 15, 'Tanrı, şüphe etme ki mühlet verilenlerdensin dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 16, 'İblis, beni azdıran sensin dedi, onun için ben de andolsun ki onları senin doğru yolundan çıkarmak için pusu kurup oturacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 17, 'Sonra andolsun ki önlerinden, arkalarından, sağlarından, sollarından çıkıp çatacağım onlara ve göreceksin ki çoğu şükür bile etmeyecek sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 18, 'Tanrı, sen kınanmış, kovulmuşsun, çık oradan dedi, andolsun ki cehennemi sizinle ve sana uyanlarla dolduracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 19, 'Ey Âdem, sen ve eşin, cennete yerleşin, ikiniz de dilediğiniz şeyleri yiyin, yalnız şu ağaca yaklaşmayın, çünkü zalimlerden olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 20, 'Şeytan, onlara gizli kalmış olan avret yerlerini belirtip göstermek için ikisini de vesveselendirdi ve bu ağacın meyvesini yerseniz mutlaka iki melek haline gelir, yahut da ebedi ömre kavuşursunuz, onun için Rabbiniz sizi nehyetti dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 21, 'Ve yemin ederek şüphe yok ki dedi, ben size öğüt verenlerdenim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 22, 'Onları böylece aldattı. Derken o ağacın meyvesinden tadınca avret yerlerini gördüler ve cennetteki ağaçların yapraklarıyla avret yerlerini örtmeye koyuldular. Rableri nida edip onlara dedi ki: Sizi, şu ağacın meyvesini yemeden menetmedim mi ve demedim mi ki Şeytan, hiç şüphe yok ki size apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 23, 'Her ikisi de Rabbimiz dedi, kendimize zulmettik biz, bizi yarlıgamazsan, bize acımazsan ziyankarlardan oluruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 24, 'Tanrı, inin dedi, bir kısmınız, bir kısmınıza düşman olacak ve yeryüzünde muayyen bir vaktedek kalmanız mukadder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 25, 'Orada dirileceksiniz dedi, orada öleceksiniz ve orada dirilip mezardan çıkarılacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 26, 'Ey Âdemoğulları, avret yerlerinizi örtecek libas ve giyip süsleneceğiniz elbise indirdik size. Tanrıdan çekinme elbisesine gelince: O, daha da hayırlıdır ve bunlar, insanların anıp öğüt almaları için indirilen Allah ayetlerindendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 27, 'Ey Âdemoğulları, Şeytan, ananızı, babanızı cennetten çıkardığı ve avret yerlerini onlara göstermek için büründükleri elbiseyi sıyırıp üstlerinden attığı gibi sakın sizi de bir derde uğratmasın. O ve ona mensup olanlar, sizin göremeyeceğiniz yerlerden görür, kollar sizi. Şüphe yok ki biz Şeytanları, inanmayanlara dost ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 28, 'Onlar, kötü bir iş yapınca babalarımız da derler, bu işi yaparlardı, öyle bulduk onları ve Allah emretti bunu bize. De ki: Allah kesin olarak kötülüğü emretmez. Allah''a, bilmediğiniz şeyi mi isnad ediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 29, 'De ki: Rabbim, adaletle hareket etmemi emretti bana ve her secde yerinde, her namazda yüzünüzü kıbleye döndürün, inancınızda, ibadetinizde halis olup ona bağlanarak kulluk edin nasıl sizi o yarattıysa, meydana getirdiyse gene öylece dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 30, 'Halkın bir bölüğünü doğru yola sevketmiştir, bir bölüğüyse sapıklığı haketti. Zanneder misiniz Allah''ı bırakıp da Şeytanları dost edinenler doğru yolu bulmuşlardır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 31, 'Ey Âdemoğulları, namaz kılacağınız her vakit, elbisenizi giyin, süslenin ve yiyin, için, israf etmeyin, şüphe yok ki o, müsrifleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 32, 'De ki: Allah''ın kulları için meydana getirdiği süslenilecek şeylerle rızık olarak verdiklerinin içinden tertemiz şeyleri kim haram etmiştir ki? De ki: Bunlar, dünyada, inanan kişilerindir, ahiretteyse yalnız onlara aittir. Delilleri, bilenlere bu çeşit açıklamadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 33, 'De ki: Rabbin ancak açığa vurulabilen ve gizlenen kötülüklerle günahı, haksız yere isyan etmeyi ve hiçbir delil indirmediği halde Allah''a şirk koşmanızı ve bilmediğiniz şeyleri tutup Allah''a isnad ederek söylemenizi haram etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 34, 'Her ümmetin başına gelecek musibete bir zaman takdir edilmiştir. Mukadder olan o zaman gelip çattı mı o musibeti ne bir an geriye atabilirler, ne bir an ileriye alabilirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 35, 'Ey Âdemoğulları, size, içinizden peygamberler gelip ayetlerimi okuyunca çekinen ve hallerini ıslah edenlere ne korku vardır, ne de mahzun olur onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 36, 'Âyetlerimizi inkar edenler ve onları kabul etmeyi ululuklarına yediremeyenlerse cehennem ehlidir ve orada ebedi kalır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 37, 'Yalan yere Allah''a iftira edenden, yahut onun ayetlerini inkar eyleyenden daha zalim kimdir ki? Kitaptan nasipleri neyse erişecek onlara; sonunda canlarını almak için elçilerimiz, onlara gelip çatınca Allah''ı bırakıp da kulluk ettiğiniz, kendilerini çağırıp durduğunuz putlar Nerede diyecekler. Onlar da kaybolup gittiler diyecekler ve kafir olduklarına dair kendileri, kendilerinin aleyhinde tanıklık edecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 38, 'Cinlerden ve insanlardan, sizden önce gelip geçen ümmetler arasında siz de girin ateşe diyecek. Her ümmet, ateşe girdikçe kendi dindaşına lanet edecek, sonunda birbiri ardınca hepsi de orada toplanacak. Son girenler, evvelce girenler için Rabbimiz diyecekler, işte bunlar bizi doğru yoldan çıkardı, bir kat daha fazla azab et onlara. Her zümre için diyecek, katkat fazla azap var ama siz bilmezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 39, 'Evvelce girenler, sonrakilere diyecekler ki: Sizin bir üstünlüğünüz yok bize, kazandığınız suçlar yüzünden tadın azabı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 40, 'Âyetlerimizi yalan sayıp onlara inanmaya tenezzül etmeyenlere gök kapıları kesin olarak açılmaz ve deve iğne yordamından geçer de onlar gene cennete giremezler ve biz, mücrimleri işte böyle cezalandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 41, 'Onlara, cehennemde ateşten döşekler, üstlerinde de ateşten örtüler var ve biz, zalimleri böyle cezalandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 42, 'İnananlara ve iyi işlerde bulunanlara gelince; hiç kimseye takatinden aşırı bir teklifte bulunmayız, onlardır cennet ehli ve orada ebedi kalır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 43, 'Gönüllerindeki kini, hasedi gideririz, bulundukları yerlerin altından ırmaklar akar ve hamd Allah''a ki derler, doğru yolu buldurdu da bu nimetlere kavuşturdu bizi; Allah hidayet etmeseydi doğru yolu bulamazdık; andolsun ki Rabbimizin peygamberleri gerçek olarak geldiler ve onlara işte yaptığınız işlere karşılık miras olarak elde ettiğiniz cennet diye nida edilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 44, 'Cennet ehli, cehennem ehline biz, Rabbimiz bize neler vaadettiyse gerçek olarak hepsini bulduk, hepsini elde ettik, siz de Rabbinizin size vaadettiğini gerçek bir surette elde ettiniz mi diye nida eder, onlar da evet derler, derken aralarında bir münadi, Allah''ın laneti zalimlere diye bağırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 45, 'O zalimlere ki halkı Allah yolundan menederlerdi o yolun eğri bir hale gelmesini isterlerdi ve onlar ahireti inkar ederlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 46, 'Cennetliklerle cehennemlikler arasında bir örtü var ve A''raf üstünde erler var ki herkesi, yüzlerinden tanırlar ve cennet ehline esenlik size diye nida ederler. Onlar, henüz cennete girmemişlerdir ama girmeyi umarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 47, 'Gözleri cehennemler tarafına ilişince Rabbimiz derler, bizi zulmeden kavimle beraber etme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 48, 'A''raf erleri, yüzlerinden tanıdıkları kişilere nida edip derler ki: Ne malınızın çok oluşu, ne sayınızın fazla bulunuşu, ne de kulluk etmeye tenezzül etmeyip ululanmanız bir fayda vermedi size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 49, 'Allah, onları rahmetine nail etmez diye yemin ettiğiniz kişiler, bunlar değil miydi? Sonra bunlara girin cennete denir, ne korku vardır size, ne de mahzun olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 50, 'Cehennem ehli, cennet ehline bize biraz su verin, yahut Allah''ın sizi rızıklandırdığı şeylerden bize de ihsan edin diye bağırırlar. Cennetlikler, şüphe yok ki derler, Allah suyu da, bize verdiklerini de kafirlere haram etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 51, 'Onlar, dinlerini eğlence ve oyun saymışlardır, dünya yaşayışı, onları aldatmıştır. Onlar, nasıl bugüne kavuşacaklarını unutup bilebile ayetlerimizi inkar ettilerse biz de bugün onları unuturuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 52, 'Biz onlara öyle bir kitap gönderdik ki onu bilgiyle açıkladık, o kitapta, ne lazımsa hepsini bildirdik, inananlara doğru yolu gösterir ve rahmettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 53, 'Onlar, kitapta söylenenlerin gelip çıkmasını mı bekliyorlar ancak? Bir gün o söylenen şeyler, o sözlerin sonucu gelecek de evvelce onu unutanlar, gerçekten de Rabbimizin peygamberleri diyecekler, hak olarak gelmişlerdi; şimdi şefaatçilerden biri varmı ki şefaat etsin bize, yahut da tekrar dünyaya dönmemize imkan verilse de oradayken yaptığımız işlerden başka işler yapsak. Gerçekten de kendilerine yazık etmişlerdir, aslı yokken inanıp durdukları mabutla da onları bırakmış, kaybolup gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 54, 'Şüphe yok, Rabbimiz, öyle bir Allah''tır ki gökleri ve yeryüzünü altı günde yaratmıştır da sonra Arşa hakim ve mutasarrıf olmuştur; aceleyle ve durmadan geceyi takib eden gündüze gecenin örtüsünü atar, o örtüyle örter onu ve güneş de onun emrine ram olmuştur, ay da, yıldızlar da. İyice bil ki yaratış da onun, buyruk da; alemlerin Rabbi Allah''ın şanı ne de yücedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 55, 'Dua edin Rabbinize yalvarıp yakararak gizlice. Şüphe yok ki o, duada haddini aşanları sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 56, 'Düzene girdikten sonra yeryüzünde bozgunculukta bulunmayın ve ona, azabından korkarak, lutfunu da umarak dua edin. Şüphe yok ki Allah''ın rahmeti, iyilik edenlere pek yakındır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 57, 'Öyle bir mabuttur ki rahmetinden önce müjdeci olarak rüzgarları yollar. Sonucu rüzgarlar, ağır yağmur bulutlarını yüklenince onları ölmüş bir ülkeye sevk ederiz, oraya böylece yağmur yağdırırız da her çeşit meyveler yetiştiririz. Düşünün de ibret almaya bakın, çünkü biz, ölüyü de işte böyle diriltiriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 58, 'Temiz ülkenin nebatı, Rabbinin izniyle çıkar, çorak yerdense pek az bir mahsul elde edilir. İşte biz, şükreden topluluğa delillerimizi bu çeşit tekrar edip durmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 59, 'Andolsun ki Nuh''u, kavmine peygamber olarak gönderdik de ey kavmim dedi, Allah''a kulluk edin, ondan başka bir mabudunuz yoktur. Şüphe yok ki ben, büyük bir günün azabına uğrayacağınızdan korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 60, 'Kavminden ileri gelenler, şüphe yok ki dediler, biz seni apaçık bir sapıklık içine dalmış görmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 61, 'O, ey kavmim dedi, bende sapıklık yok, fakat ben, alemlerin Rabbinden gelen bir elçiyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 62, 'Rabbimin bildirdiği haberleri size tebliğ etmede ve size öğüt vermedeyim ve Allah bana bildiriyor da sizin bilmediğiniz şeyleri biliyorum ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 63, 'Sizi korkutmak, sakınmanızı temin etmek ve böylece de rahmete nail olmanızı sağlamak için içinizden birisine Rabbinizden vahiy gelmesine şaşıyor musunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 64, 'Fakat onlar, onu inkar ettiler, yalancı saydılar, biz de onu ve onunla beraber gemide bulunanları kurtardık ve ayetlerimizi yalanlayanları suya boğduk. Şüphe yok ki onlar kör bir kavimdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 65, 'Âd kavmine kardeşleri Hud''u yolladık da ey kavmim dedi, Allah''a kulluk edin, ondan başka bir mabudunuz yoktur. Hala mı çekinmeyeceksiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 66, 'Kavminin kafir olanlarından ileri gelenler, şüphe yok ki dediler, biz seni sapıklık, bilgisizlik içine dalmış görmedeyiz ve sanıyoruz ki yalancılardansın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 67, 'O, ey kavmim dedi, bende sapıklık, bilgisizlik yok, fakat ben, alemlerin Rabbinden gelen bir elçiyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 68, 'Rabbimin bildirdiği haberleri size tebliğ etmedeyim ve ben size emniyet edilecek bir öğütçüyüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 69, 'Sizi korkutmak için içinizden birisine Rabbinizden vahiy gelmesine şaşıyor musunuz? Hatırlayın ki sizi Nuh kavminden sonra hükümdar etti, boypos, kuvvetkudret bakımından da onlardan üstün etti sizi. Siz de Allah''ın nimetlerini anın da muradınıza erin, kurtulun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 70, 'Dediler ki: Sen bize tek Allah''a kulluk etmemizi ve atalarımızın taptıklarını bırakmamızı sağlamak için mi geldin? Doğru söyleyenlerdensen tehdit ettiğin şeyi meydana getir bakalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 71, 'O, Rabbinizden azaba ve gazaba uğramayı hakettiniz dedi, Allah''ın, haklarında hiçbir delil indirmediği ve ancak sizin ve atalarınızın taktığı birtakım adlar için benimle çekişmeye kalkıyorsunuz demek, o halde bekleyin, şüphe yok ki ben de sizinle beraber bekleyenlerdenim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 72, 'Onu ve onunla beraber olanları rahmetimizle kurtardık da ayetlerimizi yalanlayanların ve inanmayanların kökünü kestik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 73, 'Semud''a da kardeşleri Salih''i gönderdik. Ey kavmin dedi, Allah''a kulluk edin, ondan başka bir mabudunuz yoktur. Rabbinizden size apaçık bir delil gelmiştir, işte şu Allah''ın mahluku dişi deve, size bir mucizedir o. Bırakın da Allah''ın yarattığı yeryüzünde otlayıp dursun ve ona kötülükle dokunmayın, sonra sizi elemli bir azaba uğratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 74, 'Hatırlayın ki sizi Âd kavminden sonra hükümdar etti ve yeryüzüne yerleştirdi, ovalarında köşkler kuruyor, dağlarında, kayaları yontup evler yapıyorsunuz. Allah''ın nimetlerini anın ve yeryüzünde bozgunculuk etmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 75, 'Kavminin ileri gelenlerinden olup iman etmeyi kibirlerine yediremeyenler, aciz sayıp hor gördükleri kimselerden ona iman etmiş olanlara, siz Salih''i, Rabbinden gönderilmiş mi biliyorsunuz dediler. Onlar da biz dediler, onun vasıtasıyla gönderilenlere inandık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 76, 'O ululanmak isteyenler, o kibirliler, dediler ki: Hiç şüphe yok ki biz, sizin inandıklarınızı inkar ettik, kafir olduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 77, 'Dişi deveyi, ayaklarını kesip öldürdüler ve Rablerinin emrinden çıktılar, isyan ettiler ve ey Salih dediler, peygamberlerdensen tehdid ettiğin şeyi yap bize bakalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 78, 'Derken onlar şiddetli bir sesle azaba uğradılar, yurtlarında diz çökmüş bir halde yüzükoyun kapanarak helak olup gittiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 79, 'Salih, onlardan yüz çevirdi de ey kavmim dedi, andolsun ki ben size Rabbimin bildirdiği haberleri tebliğ ettim ve öğüt verdim ama siz öğüt verenleri sevmiyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 80, 'Lut''u da gönderdik ve hani kavmine demişti ki: Sizden önce alemlerde hiçbir kimsenin yapmadığı kötülüğü mü yapacaksınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 81, 'Çünkü siz kadınları bırakıp şehvetle erkekleri kullanmadasınız ve siz, ancak haddini aşmış bir kavimsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 82, 'Kavminin cevabı ancak şu söz olmuştu, onları şehrinizden çıkarın demişlerdi, onlar pek fazla temiz olmak isteyen kişiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 83, 'Onu ve akRabasını kurtardık, ancak karısı kurtulmadı ve o, kavmiyle kalanlardandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 84, 'Onlara yağmur gibi taş yağdırdık, bak da gör suçluların sonucu ne olmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 85, 'Medyen''e de kardeşleri Şuayb''i gönderdik de ey kavmim dedi, Allah''a kulluk edin, ondan başka bir mabudunuz yoktur. Rabbinizden apaçık bir delil gelmiştir size, artık kileyi doğru ölçün, teraziyi doğru tartın, insanların haklarını yemeyin ve düzene girdikten sonra yeryüzünde bozgunculuk etmeyin. İnanmışsanız bunlar, daha hayırlıdır size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 86, 'İnananları tehdit ederek Allah yolundan menetmek ve o yolun eğri bir hale gelmesini sağlamak için her yolun başında oturup pusu kurmaya kalkmayın ve hatırlayın o zamanı ki azlıktınız, o sizi çoğalttı. Bozgunculukta bulunanların sonuçları ne olmuş, ne hale gelmişler, bakın da görün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 87, 'Sizin bir kısmınız, benimle gönderilene inanır, bir kısmınız inanmazsa Allah, aramızda hükmedinceye dek sabredin ve o, hükmedenlerin en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 88, 'Kavminin ileri gelenlerinden olup iman etmeyi kibirlerine yediremeyenler, ey Şuayb dediler, mutlaka seni de, sana inananları da hep beraber ya şehrimizden çıkaracağız, yahut da bizim dinimize dönersiniz. O da dedi ki: Biz istemesek de zorla mı yapacaksınız bunu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 89, 'Fakat Allah bizi ondan kurtardıktan sonra tutar da tekrar sizin dininize dönersek yalan yere Allah''a iftira etmiş oluruz. Artık o dine dönmemize imkan yok, meğer ki Rabbimiz olan Allah dileye. Rabbimizin bilgisi her şeye yeter, her şeyi şamildir. Allah''a dayandık biz. Rabbimiz, sen bizimle kavmimizin arasında gerçek olanı hükmet ve sen, hükmedenlerin en hayırlısısın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 90, 'Kavminin ileri gelenlerinden kafir olanlar, Şuayb''e uyduğunuz takdirde andolsun ki dediler, zarara uğrarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 91, 'Derken, şiddetli bir depremle azaba uğradılar, yurtlarında diz çökmüş bir halde yüzükoyun kapanarak helak olup gittiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 92, 'Şuayb''i yalanlayanlar, sanki oralarda hiç oturmamışlar, hiç yaşamamışlardı, Şuayb''i yalanlayanlar, asıl zarara uğramışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 93, 'Şuayb, onlardan yüz çevirdi de ey kavmim dedi, andolsun ki ben size Rabbimin bildirdiği haberleri tebliğ ettim ve öğüt verdim. Artık kafir bir kavme nasıl acıklanabilirim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 94, 'Hiçbir şehre peygamber göndermedik ki oranın halkını, yola gelsinler de yalvarıp yakarsınlar diye can ve malca bir sıkıntıya, bir azaba uğratmayalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 95, 'Sonra da kötülük yerine iyilik verdik, çoğaldılar ve atalarımız da malca zarara uğramışlardı, genişliğe kavuşmuşlardı, bu, böyledir dediler de ansızın onları azaba uğrattık, anlamadılar bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 96, 'Memleketlerin halkı inansalar ve çekinselerdi gökyüzünden üstlerine bereket yağdırır, yeryüzünden bereket fışkırtırdık, fakat inkar ettiler de kazandıkları suç yüzünden onları azaba uğrattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 97, 'Memleketlerdeki halk, uykuya dalmışken geceleyin ansızın azabımızın gelip çatmayacağından emin mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 98, 'Yahut memleketlerdeki halk, kuşluk çağı oynayıp dururken azabımızın birdenbire gelmeyeceğinden emin mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 99, 'Bütün bunlardan sonra Allah azabından emin mi olurlar? Allah azabından emin olanlar, ancak zarara uğramış topluluklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 100, 'Oralarda yaşayanların helakinden sonra miraslarına konarak yurtlarını elde edenler, hala anlamazlar mı ki dilersek, suçları yüzünden onları da musibetlere uğratırız ve kalplerini mühürleriz de işitmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 101, 'İşte bu yurtlara ait bazı vukuatı anlatmadayız sana. Andolsun ki peygamberleri, apaçık delillerle geldi onlara, fakat önce inkar ettikleri, yalan saydıkları şeylere inanmadılar. İşte Allah, kafirlerin gönüllerini böyle mühürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 102, 'Onların çoğunu, sözlerinde durur bulmadık ve çoğunu ancak hadlerini aşmış kötü kişiler bulduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 103, 'Onlardan sonra da Musa''yı, delillerimizle Firavun''a ve Firavun''un kavminden ileri gelenlere gönderdik, fakat kendilerine zulmetti onlar, bak da gör, bozguncuların sonucu ne olmuştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 104, 'Musa dedi ki: Ey Firavun, şüphe yok ki ben, alemlerin Rabbinden gelen bir peygamberim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 105, 'Allah hakkında ancak gerçek sözü söylemem borçtur bana. Rabbinizden apaçık bir delille geldim size, İsrailoğullarını benimle gönder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 106, 'Firavun, apaçık delille geldiysen ve doğru söz söyleyenlerdensen göster o delili dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 107, 'Musa, sopasını yere attı, derken sopa apaşikar kocaman bir yılan oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 108, 'Elini koltuğuna sokup çıkarınca bakanlar gördüler ki bembeyaz, parılparıl parlayan bir el.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 109, 'Firavun''un kavminden ileri gelenlerin bir kısmı, gerçekten de dediler, bu, bilgili bir büyücü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 110, 'Sizi yerinizden, yurdunuzdan çıkarmak istiyor, ne buyurursunuz şimdi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 111, 'Onunla kardeşini alıkoy da dediler, şehirlere adamlar gönder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 112, 'Ne kadar bilgili büyücü varsa hepsini tapına getirsinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 113, 'Büyücüler, Firavun''un tapısına geldiler ve üst gelirsek elbette mükafat var bize, değil mi dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 114, 'Evet dedi Firavun ve siz, mutlaka yakınlarımdan olacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 115, 'Dediler ki ya Musa, sen mi sopanı atacaksın, biz mi atalım önce?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 116, 'Siz atın dedi. Attıkları anda halkın gözünü boyadılar, korkuttular ve büyük bir büyü yaptılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 117, 'Musa''ya, at sopanı diye vahyettik. Atınca koca bir yılan şekline giren sopa, onların yalancıktan meydana çıkardıklarını yuttu, hepsini silip süpürdü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 118, 'Böylece de hak üstün oldu, yerine geldi ve yaptıkları şeyler, mahvolup gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 119, 'Oracıkta yenildiler ve horhakıyr bir halde yaptıklarından feragat ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 120, 'Ve büyücüler, hep birden secdeye kapandılar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 121, 'İnandık dediler, alemlerin Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 122, 'Musa''nın ve Harun''un Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 123, 'Firavun, ben size izin vermeden önce ona inanıyor musunuz dedi, bu, şüphe yok ki halkını oradan çıkarmak için şehirde kurup düzdüğünüz bir düzen; yakında ne yapacağımı öğrenirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 124, 'Ellerinizi, ayaklarınızı çaprazvari kestireceğim, sonra da hepinizi astıracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 125, 'Şüphe yok ki dediler, biz dönüp Rabbimizin tapısına varacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 126, 'Sen bizden, ancak Rabbimizin delilleri gelince onlara inandık diye öc alacaksın. Rabbimiz, üstümüze yağdırırcasına sabır ver bize ve bizi Müslüman olarak öldür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 127, 'Firavun''un kavminden ileri gelenler, Musa''yı ve kavmini, yeryüzünde bozgunculuk etsinler, senden ve taptıklarından yüz çevirsinler diye mi bırakıyorsun dediler. Firavun gene onların oğullarını öldürür, kadınlarını bırakırız ve şüphe yok ki biz, onlardan üstünüz ve kudret sahibiyiz dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 128, 'Musa, kavmine dedi ki: Allah''tan yardım dileyin ve sabredin. Şüphe yok ki yeryüzü Allah''ındır, kullarından dilediğine miras olarak kalır ve sonuç, çekinenlerindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 129, 'Sen gelmeden önce de eziyet çektik, geldikten sonra da çekiyoruz dediler. Musa, umarım ki dedi, Rabbiniz, düşmanlarınızı helak eder, yeryüzünde hükümdar eder sizi de neler yapacağınıza bakar, dener sizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 130, 'Andolsun ki biz, düşünüp ibret alsınlar diye Firavun''u ve soyunu yıllarca kuraklığa ve kıtlığa uğrattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 131, 'Onlara bir iyilik gelince hakkımızdı bu zaten derler, bir kötülük geldi mi Musa''nın ve onunla beraber bulunanların uğursuzluğuna verirlerdi. İyice bil ki uğradıkları uğursuzluk, Allah''tandı, fakat çoğu bilmezdi bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 132, 'Bizi büyülemek, kandırmak için hangi delili gösterirsen göster demişlerdi, biz sana inanmayacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 133, 'Bunun üzerine, ayrıayrı mucize olmak üzere onlara tufan, çekirge, haşerat, kurbağa ve kan gönderdik, fakat ululanıp inanmaya tenezzül etmediler ve zaten de suçlu bir topluluktu onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 134, 'Azaba uğrayınca ya Musa diyorlardı; icabet edeceğine dair verdiği söze uyarak Rabbine dua et de bizden bu belayı defetsin, muhakkak sana inanacağız ve İsrailoğullarını seninle göndereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 135, 'Uğrayacakları son belayadek üstlerine çöken musibeti giderdik mi derhal yeminlerini bozuyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 136, 'Sonucu öc aldık onlardan ve delillerimizi yalanladıkları, onlardan gaflet ettikleri için hepsini de denize garkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 137, 'Zayıf, horhakir bir hale getirilen kavme, yeryüzünün feyiz ve bereket ihsan ettiğimiz doğularını da, batılarını da miras olarak verdik ve sabrettiklerinden dolayı Rabbinin, İsrailoğullarına verdiği güzel söz, tamamlandı, yerine geldi ve Firavun''la kavminin yaptıklarını, yükselttiklerini yıkıp mahvettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 138, 'İsrailoğullarını denizden geçirdik de putlara tapmakta olan bir topluluğa rastladılar. Ya Musa dediler, onların taptığı putlar gibi bize de putlar yap. Musa, şüphe yok ki dedi, siz bilgisiz bir kavimsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 139, 'Onların taptıkları da helak olup gitmiştir, yaptıkları da boştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 140, 'Sizi alemlerden üstün kıldığı halde Allah''tan başka bir mabut mu arıyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 141, 'Hani sizi Firavun soyundan kurtarmıştık. Size en ağır işkenceleri yapıyorlardı, aşağılık bir hale getiriyorlardı sizi, oğullarınızı öldürüyorlar da kadınlarınızı bırakıyorlardı ve bunda da Rabbinizden büyük bir sınama vardı size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 142, 'Musa ile otuz gece münacatta bulunmayı sözleşmiştik de bu vadeyi, on gece daha katarak tamamlamıştık böylece Rabbinin tayin ettiği müddet, kırk geceyi bulmuştu ve Musa, kardeşi Harun''a, kavmimin içinde benim yerime geç, onları düzene koy ve bozguncuların yoluna uyma demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 143, 'Musa, tayin ettiğimiz vakitte gelip Rabbi onunla konuşunca Rabbim demişti, bana görün de bakayım sana. Rabbi, beni kesin olarak göremezsin sen demişti, fakat şu dağa bak, eğer yerinde durabilirse görebilirsin beni. Derken Rabbi, dağa tecelli edince dağ, yerle bir oldu ve Musa bayılıp yere yığıldı. Kendisine gelince de seni noksan sıfatlardan tenzih ederim dedi, tövbe ettim sana ve ben, inananların ilkiyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 144, 'Tanrı, ya Musa dedi, ben sana peygamberlik vererek ve seninle konuşarak bütün insanlara üstün ettim seni, seçtim seni, sana verdiğimi al ve şükredenlerden ol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 145, 'Tevrat levihlerinde, her şeye ait öğüdü, her şeyi açıklayan hükümleri yazdık ve azimle, kuvvetle al bunu dedik, kavmine de emret; en güzel hükümleriyle amel etsinler; haddi aşan, buyruktan çıkan kötü kişilerin yurtlarını da yakında göstereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 146, 'Yeryüzünde haksız yere ululuk satanlara ayetlerimizi idrak ettirmeyeceğiz, zaten onlar, hangi delili görseler inanmazlar, doğru yolu görseler o yola gitmezler, fakat azgınlık yolunu gördüler mi hemen o yola gitmeye koyulurlar; bu da ayetlerimizi yalan saymalarından ve onlardan gaflet etmelerinden ileri gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 147, 'Âyetlerimizi ve ahiret gününe ulaşmayı yalan sayanların bütün yaptıkları boşa gider. İşledikleri kötülüklerin karşılığı neyse ondan başka birşeyle mi cezalanır onlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 148, 'Musa''nın kavmi, o gittikten sonra ziynet eşyasından bir buzağı yaptılar. O buzağı, böğürüyordu da. O buzağının kendileriyle konuşmayacağını, onlara doğru yolu göstermeyeceğini görüp anlamadılar mı da ona sarıldılar ve kendilerine kıydılar, yazık ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 149, 'Adamakıllı nadim olup doğru yoldan sapıttıklarını görünce de Rabbimiz acımazsa bize ve yarlıgamazsa bizi mutlaka ziyankarlardan olacağız dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 150, 'Musa, kızgın bir halde acıklanarak kavmine dönünce dedi ki: Benden sonra ne de kötü bir iş işlediniz, Rabbinizin vaadettiği müddet bitmeden acele mi ettiniz? Ve levihleri atıp kardeşinin saçından, sakalından tutarak kendisine doğru çekmeye başladı. Harun, anam oğlu dedi, bu kavim, gerçekten de aciz bıraktı beni, az kaldı ki öldürüyorlardı da, onun için bana bu harekette bulunup düşmanları sevindirme ve beni zulmeden kavimle beraber tutma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 151, 'Musa, Rabbim dedi, beni ve kardeşimi yarlıga ve rahmetine al bizi, sen merhametlerin en merhametlisisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 152, 'Buzağıyı mabud edinenler, Rablerinden bir gazaba uğrayacaklar, dünya yaşayışında aşağılık bir hale düşeceklerdir ve biz, iftiracıları böyle cezalandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 153, 'Kötü işler yaptıktan sonra tövbe edip inananlara gelince: Şüphe yok ki Rabbin, tövbeden sonra suçları mutlaka örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 154, 'Musa''nın öfkesi yatışınca levihleri aldı. Tevrat''ın yazılı olduğu o levihlerde, hidayet ve rahmet, Rablerinden korkanlara aittir diye de yazılmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 155, 'Ve Musa, kendisine vade verdiğimiz yere götürmek üzere kavminden yetmiş kişi seçti. Derken bulundukları yerde şiddetli bir deprem başlayınca ya Rabbi dedi, dileseydin onları da daha önce helak ederdin, beni de. İçimizdeki akılsızların işledikleri suç yüzünden bizi de mi helak edeceksin? Bu, ancak senin bir sınamandan başka bir şey değil. Onunla dilediğini doğru yoldan çıkarırsın, dilediğini doğru yola sevk edersin. Sensin yardımcımız ve sahibimiz, ört bizim suçlarımızı ve acı bize, sensin suçları örtenlerin en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 156, 'Şu dünyada da iyilikler ver bize, ahirette de ve şüphesiz ki sana yöneldik biz. Tanrı, dilediğimi azabıma uğratırım dedi, fakat rahmetim, her şeyi kaplamıştır da çekinenleri, zekat verenleri ve ayetlerime inananları rahmetime mazhar ederim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 157, 'Onlar, öyle kişilerdir ki ellerindeki Tevrat''ta ve İncil''de de yazılmış olarak bulacakları şeriat sahibi Ümmi Peygambere uyarlar ve o, onlara iyiliği emreder, kötülükten nehy eder onları ve temiz şeyleri onlara helal etmededir, pis ve kötü şeyleri haram etmede. Sırtlarındaki ağır yükleri indirmededir, bağlandıkları zincirleri kırmada. Artık ona inananlar, onu ululayanlar, ona yardım edenler ve ona indirilen ışığa uyanlardır kurtulanlar, muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 158, 'De ki: Ey insanlar, şüphe yok ki ben, Allah tarafından sizin hepinize gönderilmiş olan peygamberim; o, öyle bir Allah''tır ki göklerin saltanat ve tasarrufu da onundur, yeryüzünün de. Ondan başka yoktur tapacak, odur dirilten ve öldüren. Artık Allah''a ve Allah''ın sözlerine inanın ve şeriat sahibi Ümmi Peygamberine inanın ve uyun ona da doğru yolu bulun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 159, 'Musa kavminden bir topluluk vardı ki halkı doğru yola sevk ederler ve adaletle muamelede bulunurlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 160, 'Onları on iki kabileye, on iki topluluğa böldük ve kavmi, Musa''dan su isteyince ona, sopanla taşa vur diye vahyettik, derken o taştan on iki kaynak aktı. Her topluluk, su içecekleri kaynağı belledi ve onları bulutla gölgelendirdik, onlara kudret helvasıyla bıldırcın kuşu indirdik. Size rızık olarak verdiğimiz şeylerin temizlerini yiyin dedik. Onlar bize zulmedemediler, ancak kendilerine zulmettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 161, 'Hani o zaman onlara, bu şehirde yerleşin ve dilediğiniz yerde dilediğiniz şeyi yiyin ve bu makam, suçların döküldüğü makamdır deyin, kapıdan yerlere kapanırcasına eğilerek girin de suçlarınızı örtelim, iyi hareket edenlerin mükafatını daha da fazlasıyla verelim denmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 162, 'Fakat onlardan zulmedenler, sözü kendilerine söylendiğinden bambaşka bir tarza döküp değiştirdiler, biz de ettikleri zulüm yüzünden onlara gökyüzünden kötü, pis bir azab indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 163, 'Denize pek yakın olan o şehrin halkına neler oldu, sor onlara. Hani onlar, cumartesi günü, emre isyan etmişlerdi, hani cumartesi günleri, balıklar, su üstüne çıkıyordu da cumartesiden başka günlerde onlara görünmüyordu, emirden çıktıkları için biz de onları böyle sınamadaydık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 164, 'Hani onlardan bir topluluk, Allah''ın helak edeceği, yahut da şiddetle azaplandıracağı bir kavme ne diye öğüt verirsiniz demişti de öğüt verenler, Rabbinize karşı bir özür serdedebilelim ve belki de sakınırlar ümidiyle demişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 165, 'Öğütçülerin öğütlerini unuttukları zaman biz de, onları kötülükten nehyedenleri kurtardık, zulmedenleriyse, emirden çıktıkları için pek şiddetli bir azaba uğrattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 166, 'Nehyedildikleri şeyleri yapmakta ısrar edince onlara aşağılık maymun olun dedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 167, 'An o zamanı ki Rabbin, kıyamet gününedek onlara en kötü azapla azaplandıracak olanları göndereceğini kesin olarak bildirmişti. Şüphe yok ki Rabbin, cezayı pek tez verir ve şüphe yok ki o, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 168, 'Onları, yeryüzünde takımtakım topluluklar haline getirdik, dağıttık. İçlerinde iyileri var, onlardan daha aşağı derecede bulunanları var. Belki Tanrıya dönerler, itaate girerler diye de onları iyiliklerle, kötülüklerle sınadık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 169, 'Onlardan sonra kitaba varis olan öyle bir nesil geldi ki hem şu dünyanın geçici matahını alırlar da elbette ilerde yarlıganırız, suçlarımız örtülür bizim derler, hem de gene ellerine ona benzer geçici bir matah geçse almakta devam ederler. Halbuki Allah''a karşı ancak gerçek olanı söyleyeceklerine dair onlardan o kitabın hükmünce söz alınmamış mıydı ve kitapta olanları okuyup dururlar da. Halbuki ahiret yurdu, sakınanlara daha hayırlıdır, hala mı aklınız ermiyor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 170, 'Kitaba sarılıp namaz kılanlara gelince: Biz, iyiliğe çalışanların mükafatını zayi etmeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 171, 'Hani biz, dağı adeta bir gölgelik gibi çekmiş, üstlerine doğru yüceltmiştik de nerdeyse üstlerine düşecek sanmışlardı. Size verdiğimiz kitabı kuvvetle, azimle tutun, içinde ne varsa hatırlayıp ona göre hareket edin de sakınanlardan olun demiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 172, 'Hani Rabbin Âdemoğullarının sırtlarından zürriyetlerini izhar etmişti de kendilerini kendilerine tanık tutarak ben, Rabbiniz değil miyim demişti; onlar da evet, tanığız, Rabbimizsin demişlerdi. Bu da kıyamet günü bizim bundan haberimiz yoktu dememeniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 173, 'Yahut da ancak atalarımız şirk koştu önce ve biz onlardan sonra gelmiş bir soyuz; bizi de o boş ve asılsız işlerde bulunanların amelleri yüzünden helak mı edeceksin gibi bir söz söylememeniz içindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 174, 'Belki doğru yola dönersiniz diye ayetlerimizi işte böyle açıklamadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 175, 'Oku onlara kendisine delillerimizi ihsan ettiğimiz halde bilebile onları inkar edip, onların hükmünden sıyrılıp Şeytan''a uyan ve helak olana ait kıssayı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 176, 'Dileseydik onu, delillerimizle yüceltirdik, fakat o, yeryüzüne sarıldı ve kendi isteğine uydu. O tıpkı köpeğe benzer; üstüne varıp kovsan da dilini çıkarıp solur, kendi haline bıraksan da dilini çıkarıp solur. İşte bu hal, delillerimizi yalanlayan topluluğun haline benzer; sen geçmişlerin hallerini anlat onlara da belki iyice bir düşünürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 177, 'Ne de çirkin bir örnektir delillerimizi yalanlayıp kendilerine zulmedenlerin hali.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 178, 'Allah, kimi doğru yola sevkettiyse odur doğru yolu bulan ve kimi yoldan çıkarırsa o ve onun gibilerdir ziyana uğrayanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 179, 'Andolsun ki biz, cinlerin ve insanların çoğunu cehennem için yarattık; onların kalpleri vardır; düşünmezler onunla; gözleri vardır, görmezler o gözlerle; kulakları vardır, duymazlar o kulaklarla. Onlar dört ayaklı hayvanlara benzerler, hatta daha da sapıktır onlar. Onlardır gaflette kalanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 180, 'Güzel adlar, Allah''ındır, o adlarla dua edin ona ve onun adlarını başka anlamlara çekenleri, o adları başkalarına verenleri, onu, ona layık olmayan adlarla çağıranları bırakın, onlar, yaptıklarının cezasını görecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 181, 'Yarattıklarımızdan bir topluluk var ki halkı gerçeğe irşad eder ve gerçek olarak adaletle muamelede bulunur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 182, 'Delillerimizi yalanlayanlara gelince: Biz onları yavaşyavaş hiç anlamayacakları noktalardan helake yaklaştırırdururuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 183, 'Ve ben onlara mühlet veririm, şüphe yok ki azabım pek şiddetlidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 184, 'Düşünmezler mi ki kendileriyle konuşanda delilikten eser bile yok; o ancak apaçık korkulu bir haber veren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 185, 'Bakmazlar mı göklerdeki ve yeryüzündeki saltanat ve tedbire ve Allah''ın yarattığı şeylerden herhangi birine ve ölüm çağlarının gelip çatmakta olduğuna? Bu sözden sonra da hangi söze inanırlar artık?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 186, 'Allah kimi yoldan çıkarırsa artık yoktur onu doğru yola sevkedecek ve onları can gözleri kör olarak şaşkınlıklarında bırakır gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 187, 'Senden kıyametin ne vakit kopacağını sorarlar. De ki: Onu ancak Rabbim bilir. Vakti geldi mi onu ancak o izhar eder; göklere de ağır basmıştır, yeryüzüne de ve size ancak ansızın gelip çatar. Biliyormuşsun da gizliyorsun gibi sana soruyorlar, de ki: Onu ancak Allah bilir, fakat insanların çoğu anlamaz bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 188, 'De ki: Allah''ın dilediğinden başka kendime ne bir fayda vermeye gücüm yeter, ne bir zarardan kaçınmaya. Gaibi bilseydim daha fazla hayır elde etmek isterdim ve bana bir kötülük gelmezdi. Fakat ben ancak inanan topluluğu korkutan ve müjdeleyen biriyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 189, 'Öyle bir mabuttur ki sizi tek bir kişiden yarattı, ülfet ve ünsiyet etmesi için ondan da eşini halketti. Derken erkek eşine yaklaşınca eşi, hafif bir yük taşımıya ve onunla gidip gelmeye başladı. O yük ağırlaşınca ikisi de, bize azası tam ve iyi birevlat verirsen şüphe yok ki biz de şükredenlerden oluruz diye Rablerine dua ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 190, 'Onlara azası tam ve düzgün bir evlat verince de o yüzden şirk koştular. Oysa onların şirk koştuklarından tamamıyla münezzehtir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 191, 'Hiçbir şeyi yaratamayan bir varlığı ona eş mi tutuyorlar, halbuki kendileri yaratılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 192, 'Onlara yardım etmeye güçleri yetmeyen ve kendilerine de yardım etmeye muktedir olmayan şeyleri eş mi sayıyorlar ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 193, 'Onları doğru yola çağırırsanız size uymazlar. İster çağırın onları, ister susun, sizce ikisi de bir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 194, 'Allah''tan başka çağırdıklarınızın hepsi de sizin gibi kuldur. Sözünüz gerçekse çağırın da cevap versinler size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 195, 'Ayakları mı var ki yürüsünler, yahut elleri mi var ki tutsunlar, yoksa gözleri mi var ki görsünler, yahut da kulakları mı var ki duysunlar? De ki: Çağırın Tanrıya eş sandıklarınızı da sonra hep beraber bana düzen kurun, göz bile açtırmayın bakalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 196, 'Çünkü şüphe yok ki benim yardımcım, kitabı indiren Allah''tır ve o, bütün temiz ve iyi kişilere yardım eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 197, 'Ondan başka bütün taptıklarınızın ne size yardıma güçleri vardır, ne kendilerine yardıma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 198, 'Onları doğru yola çağırırsan dinlemezler ve görürsün ki sana bakıyorlar, fakat baktıkları halde görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 199, 'Özrü kabul edip suçları bağışla, iyiliği emret ve bilgisizlerden yüz çevir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 200, 'Şeytan seni buna aykırı bir yola meylettirmeye kalkışırsa Allah''a sığın, şüphe yok ki o, her şeyi duyar ve bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 201, 'Tanrıdan çekinenler, Şeytan''ın bir vesvesesine uğradılar mı düşünürler, bir de bakarsın ki doğru yolu görmüşler bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 202, 'Müşriklerin kardeşleri olan Şeytanlar, müşrikleri azgınlığa sürerler, sonra da onları azdırmaktan hiç geri kalmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 203, 'Onlara bir ayet gelmeyince kendinden düzüp koşsaydın derler. De ki: Ben ancak Rabbim bana neyi vahy ederse ona uyarım. Budur Rabbinizden gelen ve can gözlerinizi açacak olan aşikar deliller ve inanan topluluğa doğru yolu gösteren vasıta ve rahmet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 204, 'Kur''an okununca dinleyin ve susun da rahmete erin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 205, 'Sabah ve akşam çağları, yalvarıp yakararak ve ondan korkarak, fakat fazla bağırmamak şartıyla ve içinden gelerek an Rabbini ve gaflet edenlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (7, 206, 'Şüphe yok ki Rabbinin katında bulunanlar, ona kulluk etmekten çekinmezler ve onu noksan sıfatlardan tenzih ederler ve yalnız ona secde ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 1, 'Sana harp ganimetlerinin hükmünü sorarlar. De ki: Ganimetler, Allah''ın ve Peygamberindir. Artık Allah''tan sakının ve aranızı ıslah edin ve inanmışsanız Allah''a ve Peygamberine itaat edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 2, 'İnananlar, ancak onlardır ki Allah anılınca yürekleri titrer, onlara ayetleri okununca da inançlarını arttırır ve Rablerine dayanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 3, 'Onlardır ki namaz kılarlar ve rızıklandırdığımız şeylerin bir kısmını harcarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 4, 'Onlardır gerçek inananlar, onlarındır Rableri katında dereceler, yarlıganma ve daimi, bitmeztükenmez rızık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 5, 'Nasıl ki Rabbin, seni hak uğruna evinden çıkarmıştı ve şüphe yok ki inananların bir kısmı bundan hoşlanmamıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 6, 'Gerçek, apaçık meydana çıktıktan sonra bile bu hususta, gözleri bakabaka ölüme sürükleniyorlarmış gibi seninle çekişmeye kalkışıyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 7, 'Hani Allah, o iki bölükten birinin muhakkak sizin olacağını vaad ediyordu da siz, silahı bulunmayanların, elinize düşmesini istiyordunuz. Halbuki Allah, sözleriyle, gerçeği yerine getirmek ve kafirlerin kökünü kesmek istiyordu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 8, 'Böylece de suçlular istemese de gerçeği gerçek olarak izhar etmeyi ve batılın boşluğunu bildirmeyi murad etmekteydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 9, 'Hani, siz, Rabbinizden imdat istemiştiniz de Rabbiniz, şüphe yok ki ben, birbiri ardınca binlerce melekle size yardım edeceğim diye duanızı kabul etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 10, 'Ve Allah, bunu ancak bir müjde olarak ve kalpleriniz yatışsın diye yapmıştı. Yardım, ancak Allah''tandır. Şüphe yok ki Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 11, 'Hani bir emniyet vermek için sizi hafif bir uykuya daldırmıştı ve sizi arıtmak, sizden Şeytan''ın pisliğini gidermek, yüreklerinizi sağlamlaştırmak ve ayaklarınızı pekiştirip metanetinizi arttırmak için de gökten bir yağmur yağdırmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 12, 'Hani Rabbin, şüphe yok ki ben, sizinleyim, inananları sebat ettirin, kafirlerin yüreklerine korku salacağım, hadi vurun boyunlarını, vurun onların ellerine, ayaklarına diye meleklere vahyetmedeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 13, 'Bu da onların, Allah''a ve Peygamberine karşı gelmelerindendi ve kim, Allah''a ve Peygamberine karşı gelirse bilsin ki Allah''ın cezası, şüphe yok ki pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 14, 'İşte tadın şimdi bunu ve şüphe yok ki kafirler için bir de ateşle azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 15, 'Ey inananlar, savaşmak üzere kafirlerle karşılaştınız mı onlara arkanızı dönmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 16, 'Ve kim, tekrar savaşmak için bir tarafa çekilmek, yahut bir bölüğe ulaşmak niyetinde olmadan öyle bir günde onlara arka çevirir, dönerse muhakkak Allah''ın gazabına uğrayacaktır, yurdu cehennemdir ve orası, dönüp varılacak ne kötü bir yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 17, 'Onları siz öldürmediniz, fakat Allah öldürdü ve attığın zaman sen atmadın, fakat Allah attı ve böylece de kendi katından, inananlara güzel bir nimet vermek, onları denemek istedi. Şüphe yok ki Allah her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 18, 'Böyledir bu ve şüphe yok ki Allah, kafirlerin düzenlerini gevşetir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 19, 'Fetih istiyordunuz ya, işte size fetih. Vazgeçerseniz daha hayırlı olur size, fakat savaşa dönerseniz biz de döneriz ve topluluğunuz çok bile olsa hiçbir işinize yaramaz sizin ve şüphe yok ki Allah, inananlarla beraberdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 20, 'Ey inananlar, Allah''a ve Peygamberine itaat edin, Kur''an''ı dinlediğiniz halde ondan yüz çevirmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 21, 'Ve işittik dedikleri halde duyup kabul etmeyenlere benzemeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 22, 'Şüphesiz ki yerde yürüyen canlıların Allah katında en kötüsü, aklı, idraki olmayan sağır ve dilsiz mahluklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 23, 'Allah, onlarda bir hayır olduğunu bilseydi elbette onlara duyururdu. Fakat duyursaydı da gene onlar arkalarını dönerek yüz çevirirlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 24, 'Ey inananlar, sizi diriltecek, size can verecek şeylere çağırdıkları zaman Allah''a ve Peygambere icabet edin ve bilin ki Allah, hiç şüphe yok, insanın kendisiyle kalbinin arasına girer ve hiç şüphe yok ki onun tapısında toplanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 25, 'Ve sakının o fitneden ki yalnız zulmedenlerinize gelip çatmaz ve bilin ki şüphesiz Allah''ın cezası pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 26, 'Hatırlayın o zamanı ki azlıktınız, yeryüzünde hor, aciz tanınanlardandınız, insanların size saldırıp yok etmesinden korkuyordunuz. Derken sizi, şükredesiniz diye yeryurt sahibi etti, yardımıyla kuvvetlendirdi ve tertemiz şeylerle rızıklandırdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 27, 'Ey inananlar, Allah''a ve Peygambere hıyanet etmeyin ve bilebile emanetlerinize de hıyanette bulunmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 28, 'Ve bilin ki mallarınız ve evladınız, sizin için bir sınamadır ancak ve şüphe yok ki Allah katındadır büyük mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 29, 'Ey inananlar, Allah''tan çekinirseniz hayırla şerri ayırt etme kabiliyetini verir size ve suçlarınızı örter, yarlıgar sizi ve Allah, pek büyük bir lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 30, 'Hani bir zaman, kafir olanlar, seni bağlayıp hapsetmek, yahut öldürmek, yahut da yurdundan çıkarmak için düzenlere baş vurmuşlardı. Onlar, bu düzeni kurarken Allah da cezalarını hazırlamadaydı ve Allah hilekarları cezalandıranların en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 31, 'Onlara ayetlerimiz okunurken dediler ki: Duyduk, dilersek biz de buna benzer sözler söyleriz ve bu, eskilerin masallarından başka bir şey de değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 32, 'Hani Allah''ım demişlerdi, bu, senin katındansa ve gerçekse başımıza gökten taş yağdır, yahut da bize elemli bir azap ver.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 33, 'Fakat sen, onların içinde oldukça onları azaplandırmaz ve gene yarlıganma dilerlerken Allah onlara azap vermez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 34, 'Ne diye Allah onları azaplandırmasın ki onlar, hizmetine layık olmadıkları halde halkı Mescidi Haram''dan menediyorlar, onun hizmetine layık olanlar, ancak çekinenlerdir, fakat çoğu bilmez bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 35, 'Tanrı evine karşı namazları, ancak ıslık çalmak ve el çırpmaktan ibaret. Artık kafir olmanıza karşılık tadın azabı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 36, 'Şüphe yok ki kafir olanlar, mallarını ancak halkı Allah yolundan alıkoymak için harcarlar. Harcayacaklar da, sonra o harcadıkları mallar, kendilerine bir iç acısı olacak, sonra da alt edilecekler ve kafir olanlar cehenneme götürülecekler, orada toplanacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 37, 'Allah pisi temizden ayıracak ve pis olanları yığınyığın birbiri üstüne koyup yığacak ve topunu birden cehenneme atacak; onlardır ziyankarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 38, 'Kafir olanlara de: Kafirliklerinden vazgeçerlerse geçmiş günahları örtülür, yarlıganır, fakat vazgeçmezler de savaşa kalkışırlarsa şüphe yok ki onlardan önceki hüküm ve kanun yürüyüp gidecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 39, 'Hiçbir fitne kalmayıncaya ve din, tamamıyla Allah''a münhasır oluncaya dek savaşın onlarla. Savaştan vazgeçerlerse şüphe yok ki Allah, onların yaptıklarını görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 40, 'Ve yüz çevirirlerse artık bilin ki Allah sizin yariniz, yardımcınızdır ve o, ne güzel dosttur, ne güzel yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 41, 'Ve iyice bilin ki ganimet olarak elde ettiğiniz şeyin mutlaka beşte biri Allah''ın ve Peygamberin ve yakınların ve yetimlerin ve yoksulların ve yolda kalmışlarındır. Allah''a inanmışsanız ve hak ile batılın ayrıldığı, yani iki ordunun birbiriyle buluştuğu gün kulumuza indirdiğimize iman etmişseniz ve Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 42, 'Hani siz vadinin yakın bir yerindeydiniz, onlar uzak bir kıyısında, kervansa sizden daha aşağı tarafta ve eğer muayyen yerlerde buluşmak üzere sözleşseydiniz gene ihtilafa düşerdiniz. Fakat helak olanın, apaçık bir delil görerek helak olması, diri kalanın da gene apaçık bir delil görerek diri kalması için Allah, olacak bir işi yerine getirmek üzere bunu böyle yaptı ve şüphe yok ki Allah, mutlaka her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 43, 'Hani Allah, rüyanda sana onların az olduğunu göstermişti; çok gösterseydi ürker, gevşerdiniz ve iş hususunda da çekişe kalkışırdınız. Fakat Allah sizi bundan kurtardı ve şüphe yok ki o, gönüllerdekini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 44, 'Hani karşılaştığınız zamanda Allah, onları sizin gözünüze az gösterdiği gibi sizi de onlara az göstermişti; çünkü Allah, olacak işi yapacak, yerine getirecekti ve bütün işlerin mercii Allah''tır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 45, 'Ey inananlar, bir toplulukla karşılaştınız mı mutlaka sebat edin ve Allah''ı çok anın da kurtulun muradınıza erişin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 46, 'Allah''a ve Peygamberine itaat edin, birbirinizle çekişmeyin, sonra zayıflarsınız ve kuvvetiniz kalmaz ve sabredin, şüphe yok ki Allah, sabredenlerle beraberdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 47, 'Ülkelerinden böbürlenmek ve halka gösteriş yapmak için çıkanlara ve insanları Allah yolundan menedenlere benzemeyin ve Allah onların bütün yaptıklarını bilgisiyle kavramıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 48, 'Hani o zaman Şeytan, onların yaptıklarını, kendilerine süslü ve hoş göstermişti de bugün insanlardan size üstün olacak yoktur, ben de şüphe yok ki size yardımcıyım demişti. Fakat iki ordu da görününce geri dönüp ben demişti, şüphe yok, sizden uzağım, çünkü ben, sizin görmediklerinizi görmedeyim ve Allah''tan korkmadayım ve Allah''ın cezası pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 49, 'Hani münafıklarla gönüllerinde hastalık olanlar, bunları dinleri aldatmıştır demişlerdi; halbuki kim Allah''a dayanırsa bilsin ki Allah, şüphe yok ki üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 50, 'Melekler, kafirlerin suratlarına ve sırtlarına vura vura canlarını alır ve şiddetle yakıcı azabı tadın derlerken bir görmeliydin onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 51, 'Bu, evvelce ellerinizle kendinize hazırladığınız şeydir ve şüphe yok ki Allah, kullarına zulmetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 52, 'Firavun''un soyuyla onlardan önce gelip geçenlerin gidişleri gibi hani Allah''ın delillerini inkar edip kafir olmuşlardı da Allah, suçlarına karşılık onları azabına uğratmıştı: Şüphe yok ki Allah, pek kuvvetlidir, azabı da pek çetindir onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 53, 'Bu da, şundan ileri gelir: Şüphe yok ki Allah, bir topluluğa ihsan ettiği nimeti, onlar kendi huylarını değiştirmedikçe değiştirmez ve şüphe yok ki Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 54, 'Firavun''un soyuyla onlardan önce gelip geçenlerin gidişleri gibi hani. Rablerinin ayetlerini yalanladılar da suçlarına karşılık helak ettik onları ve Firavun''un soyunu sulara garkettik, hepsi de zalimdi onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 55, 'Allah katında yeryüzünde yürüyen mahlukların en kötüsü kafir olanlardır ve onlar inanmazlar zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 56, 'Onlar, kendileriyle ahitleştiğin kimselerdir, sonra her defasında da ahitlerini bozarlar ve onlar, hiç çekinmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 57, 'Savaşta üst gelirsen onları, izlerini izliyenlere de tesir edecek ve onları da korkutacak bir tarzda cezalandır da bunu ansınlar, ibret alsınlar bundan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 58, 'Kafirler, işin geçip gittiğini, kendilerinin unutulduğunu ve bir daha da horlanmayacaklarını, aciz bir hale getirilmeyeceklerini sanmasınlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 59, 'Bir topluluğun hainlikte bulunacağından korkarsan aradaki muahedeyi boz ve bunu, yani iki tarafın da bir sözle bağlı olmadığını onlara bildir. Şüphe yok ki Allah, hainleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 60, 'Allah düşmanlarıyla size düşman olanları ve bunlardan başka sizin bilmediğiniz, fakat Allah''ın bildiği düşmanları korkutmak için onlara karşı kullanmak üzere gücünüz yettiği kadar kuvvet ve besili at hazırlayın, Allah yolunda ne harcarsanız size karşılığı tamamıyla ödenecektir ve asla zulme uğramayacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 61, 'Fakat barışa yanaşırlarsa sen de yanaş ve Allah''a dayan. Şüphe yok ki o, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 62, 'Sana karşı bir hile yapmayı dilerler, buna yeltenirlerse hiç şüphe yok ki Allah yeter sana; öyle bir mabuttur ki seni, kendi yardımıyla ve inananlarla kuvvetlendirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 63, 'Onların gönüllerini birleştirmiştir. Yeryüzünde ne varsa hepsini harcasaydın gene de gönüllerini birleştiremezdin onların, fakat Allah, aralarını uzlaştırdı. Şüphe yok ki o, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 64, 'Ey Peygamber, sana da, iman sahiplerinden sana uyanlara da Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 65, 'Ey Peygamber, inananları savaşa teşvik et. Sizden yirmi tane sabırlı er bulunsa onların iki yüzüne üst gelir ve siz yüz kişi olsanız kafirlerin bin tanesine üst olursunuz, çünkü onlar, hiçbir şeyden anlamaz bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 66, 'Fakat şimdi Allah size savaştaki hükmü hafifletti ve bildi ki sizde muhakkak bir zaaf var. Artık sizden yüz tane sabır ve sebat sahibi, ikiyüzü yener ve siz bin kişi olsanız Allah''ın izniyle iki binini altedersiniz ve Allah, sabır ve sebat edenlerle beraberdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 67, 'Hiç bir peygamber, yeryüzünde kafirlere üstolup onları iyice kahretmedikçe tutsak almamıştır. Siz, geçici dünya malını istiyorsunuz, Allah''sa ahireti istemekte ve Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 68, 'Allah, bunu helal olarak takdir etmeseydi helal olduğu açıklanmadan tutsaklara karşılık aldığımız para yüzünden pek büyük bir azaba uğrardınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 69, 'Artık elde ettiğiniz ganimeti helal ve temiz olarak yiyin ve çekinin Allah''tan. Şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 70, 'Ey Peygamber, ellerinizde bulunan tutsaklara de ki: Allah, yüreklerinizde bir hayırlı niyet bulunduğunu bilirse size, sizden alınandan daha hayırlısını verir ve suçlarınızı örter ve Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 71, 'Fakat sana hainlik etmeyi kurarlarsa bilsinler ki daha önce Allah''a hainlik etmişlerdi de seni onlara üstetmişti o ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 72, 'İnanıp yurtlarından göçenler, mallarıyla, canlarıyla Allah yolunda savaşanlar, bunları yeryurt sahibi edip barındıranlar ve yardımda bulunanlarsa işte bunlar, mirasta birbirlerinin velileridir. İnandıkları halde yurtlarından göçmeyenlere gelince, göçünceye dek onların miraslarında bir hakkınız yoktur. Dine ait bir hususta sizden yardım isterlerse, aranızda bir ahit bulunan topluluğa karşı olmamak şartıyla onlara yardım etmeniz gerektir ve Allah, ne yaparsanız hepsini de görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 73, 'Kafir olanlarsa birbirlerinin dostudur, yardımcısıdır. Birbirinize yardım etmezseniz yeryüzünde bir fitne belirir, büyük bir bozgun meydana gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 74, 'İnananlar ve yurtlarından göçenler, Allah yolunda savaşanlar ve bir de bunları yeryurt sahibi edenler ve yardımda bulunanlarsa onlardır gerçekten inanmış olanlar. Onların hakkıdır yarlıganmak ve sayısız, tükenmez rızık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (8, 75, 'Sonradan inanıp göçen ve sizinle beraber savaşanlar da sizdendir. Allah''ın takdirinde sabit olduğu veçhiyle bir kısım akraba, bazı akrabanın mirasında daha ileri bir hakka sahiptir. Şüphe yok ki Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 1, 'Allah ve Resulü, kendileriyle ahitleştiğiniz müşriklerden beridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 2, 'Yeryüzünde dört ay daha dolaşın ve bilin ki siz Allah''ı aciz bir hale getiremezsiniz ve şüphe yok ki Allah, kafirleri aşağılık bir hale getirecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 3, 'Haccı ekber günü, Allah''tan ve Peygamberinden insanlara bir ilandır bu: Şüphe yok ki Allah ve Peygamberi, müşriklerden beridir. Artık tövbe ederseniz bu, daha hayırlıdır size. Fakat gene yüz çevirirseniz iyice bilin ki siz hiç şüphe yok, Allah''ı aciz bırakamazsınız ve kafir olanlara pek acıklı azapla müjde ver.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 4, 'Ancak müşriklerden ahitleştiğiniz kimseler, bu ahitten sonra size karşı sözlerinden hiçbir suretle dönmemiş, şartlardan hiçbirini bozmamış ve aleyhinize hiçbir kimseye yardıma kalkışmamış olanlar müstesna. Onlarla olan ahdinizi, müddeti bitinciyedek tamamlayın. Şüphe yok ki Allah, çekinenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 5, 'Haram aylar çıkınca müşrikleri Nerede bulursanız öldürün, yakalayın, kuşatın, hapsedin onları, gelip geçecekleri bütün yolları tutun. Fakat tövbe ederler, namaz kılarlar ve zekat verirlerse bırakın onları, şüphe yok ki Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 6, 'Müşriklerden biri, senden aman dilerse aman ver ona da Allah sözünü dinlesin, sonra da emin olduğu yere dek yolla onu. Bunun sebebi de, onların, bilmeyen bir topluluk olmalarıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 7, 'Müşriklerin, Allah ve Peygamberi katında nasıl bir ahitleri olabilir ki? Ancak Mescidi Haram yanında ahitleştikleriniz müstesna. Onlar, size karşı doğru hareket ederlerse siz de onlara karşı doğru hareket edin. Şüphe yok ki Allah, çekinenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 8, 'Nitekim onlar size üstolsaydı hakkınızda ne bir yakınlık gösterirlerdi, ne bir ahde riayet ederlerdi. Onlar, sizi ancak ağızlarıyla hoşnut ederler, yüreklerindeyse düşmanlık ve gadir var ve onların çoğu, buyruktan çıkmış kişilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 9, 'Allah''ın ayetlerini satarlar da karşılık olarak pek az ve adi bir şey elde ederler ve halkı Allah yolundan menederler. Gerçekten de yaptıkları şey, ne de kötü şeydir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 10, 'İnanan birisine karşı ne bir yakınlık gözetirler, ne bir ahde riayet ederler ve onlardır haddi aşanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 11, 'Fakat tövbe ederler, namaz kılarlar ve zekat verirlerse onlar da din kardeşlerinizdir ve biz, bilen topluluğa ayetlerimizi açıklar, bildiririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 12, 'Ahitlerinden sonra gene yeminlerini bozarlar ve dininizi kınarlarsa kafirliğe baş olanlarla savaşın, şüphe yok ki yeminini tutmayan kişilerdir onlar, belki bu suretle yaptıklarından vazgeçerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 13, 'Yeminlerinden dönen ve Peygamberi, ülkesinden çıkarmaya çabalayan ve size karşı ahitlerini ilkin bozan bir toplulukla savaşmaz mısınız, korkar mısınız onlardan? İnanmışsanız kendisinden korkulmaya daha layık olan Allah''tır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 14, 'Savaşın onlarla da Allah, ellerinizle onları azaplandırsın, aşağılatsın onları, onlara karşı yardım etsin size ve inanan topluluğun göğüslerini ferahlatsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 15, 'Ve yüreklerindeki gazabı gidersin ve Allah, dilediğine tövbe nasip eder ve tövbesini kabul eyler ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 16, 'Sanır mısınız ki kendi halinize bırakılacaksınız ve Allah, sizden savaşanlarla Allah''tan, Peygamberinden ve inananlardan başkasını sır dostu edinmeyenleri bilmeyecek? Ve Allah, ne yaparsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 17, 'Kendileri kendi kafirliklerine tanık olup dururlarken müşriklerin Allah''a secde edilen yerleri imara hakları yoktur. Onlar, bütün yaptıkları boşa gidenlerdir ve onlar, ateşte ebedi olarak kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 18, 'Allah''a secde edilen yerleri, ancak ve ancak Allah''a ve ahiret gününe inanan, namaz kılan, zekat veren ve Allah''tan başka kimseden korkmayanlar imar eder. İşte doğru yolu bulmaları umulanlar da onlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 19, 'Hacılara su verme ve Mescidi Haram''ı imar etme işiyle uğraşanların derecesini Allah''a ve ahiret gününe inanıp Allah yolunda savaşan kimsenin derecesiyle bir mi tutarsınız? Ve Allah, zulmeden topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 20, 'İnananların, yurtlarından göçenlerin ve Allah yolunda mallarıyla, canlarıyla savaşanların Allah katında dereceleri pek büyüktür ve onlardır muratlarına erenlerin, kurtulup nusrat bulanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 21, 'Rableri, onları öz rahmetiyle, razılığıyla ve tükenmez nimetleri bulunan cennetlerle müjdeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 22, 'Orada ebedi kalırlar. Şüphe yok ki pek büyük mükafat, Allah katındadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 23, 'Ey inananlar, kafirliği severler ve küfrü imana tercih ederlerse babalarınızı ve kardeşlerinizi de dost edinmeyin ve içinizden kim onları severse onlardır zulmedenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 24, 'De ki: Babalarınız, oğullarınız, kardeşleriniz, karılarınız, aşiretiniz, elde ettiğiniz mallar, kesada uğramasından korktuğunuz alışveriş ve hoşunuza giden evler, sizce Allah''tan, Peygamberinden ve onun yolunda savaş etmeden daha sevimliyse bekleyin Allah''ın emri gelinciye dek ve Allah, buyruktan çıkan kötü topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 25, 'Andolsun ki Allah size birçok yerlerde ve Huneyn gününde yardım etmişti; hani o gün çokluğunuzla övünüp sevinmiştiniz de bu çokluk, düşmanı defedememişti, hiçbir işinize yaramamıştı, yeryüzü, o kadar genişken daralmıştı size, sonra da arka çevirip geri çekilmiştiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 26, 'Sonra da Allah, Peygamberine ve inanlara manevi kuvvetini ihsan etmişti ve görmediğiniz orduları indirerek kafirleri azaplandırmıştı ve işte kafirlerin cezası da budur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 27, 'Bundan sonra da Allah, dilediğine tövbe nasib etmiş ve tövbesini kabul eylemişti ve Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 28, 'Ey inananlar, müşrikler, mutlaka pis insanlardır, bu yıldan sonra artık onları Mescidi Haram''a yaklaştırmayın. Yoksulluktan korkarsanız bilin ki Allah dilerse yakında sizi lutfuyla, ihsanıyla zenginleştirir ve şüphe yok ki Allah her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 29, 'Kendilerine kitap verilenlerden Allah''a ve ahiret gününe inanmayanlarla, Allah''la Peygamberinin haram ettiğini haram saymayanlarla ve hak dinini kabul etmeyenlerle savaşın cizye vermeye razı olup bizzat kendi elleriyle ve alçalarak gelip verinceye dek onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 30, 'Yahudiler, Uzeyr, Allah''ın oğludur dedi, Nasraniler de Mesih, Allah''ın oğludur dedi. Bu söz, onların uydurup ağızlarına aldıkları bir söz. Daha önce kafir olanların sözlerini taklit etmedeler, hay Allah kahredesiler, nasıl da yalana kapılıyorlar, batıla uyuyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 31, 'Allah''ı bırakıp bilginleriyle rahiplerini ve Meryemoğlu Mesih''i Rab tanımışlardır; halbuki onlara da ancak tek mabuda kulluk etmek emredilmiştir. Ondan başka tapacak yok; o onların şirk koştukları şeylerden münezzehtir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 32, 'İsterler ki Allah''ın nurunu nefesleriyle söndürsünler, halbuki Allah, kafirler istemese de, onlara zor gelse de nurunu yüceltip itmam etmekten başka hiçbir şeye razı değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 33, 'Öyle bir mabuttur ki müşrikler istemese de, zorlarına gitse de Peygamberini, insanları doğru yola sevkeden apaçık ve kesin delillerle ve bütün dinlere üstolmak üzere gerçek dinle göndermiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 34, 'Ey inananlar, o bilginlerle rahiplerin çoğu, boş sebeplerle insanların mallarını yerler ve halkı Allah yolundan menederler. Altını, gümüşü biriktirip Allah yolunda harcamayanları elemli bir azapla müjdele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 35, 'O gün, cehennem, o altını, gümüşü alevleyecek ve onlar, cehennem ateşinde kızdırılıp alınlarına, yanlarına, sırtlarına bastırılacak, onlarla dağlanacaklar ve işte bunlardır kendiniz için biriktirdiğiniz şeyler denecek, tadın biriktirdiklerinizin azabını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 36, 'Ayların sayısı, gerçekten de Allah katında on ikidir ve göklerle yeryüzünü yarattığı günden beri Allah''ın takdirinde bu, böyledir. Onların dört tanesi haram aylardır. Budur dosdoğru hesap. Artık bu haram aylarda kendinize zulmetmeyin, fakat müşriklerin hepsiyle de savaşın, nitekim onların da topu sizinle savaşmadadır ve bilin ki Allah, şüphe yok ki çekinenlerle beraberdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 37, 'Haram ayı geciktirme, ancak kafirliği artırmadadır ki kafir olanlar, bu suretle doğru yoldan çıkarılmadadır; onlar, Allah''ın haram ettiği ayların sayısını denk getirsinler de Allah''ın haram ettiğini helal etsinler diye haram ayı bir yıl helal sayarlar, bir yıl haram sayarlar. Onların kötü işleri, kendilerine hoş görünmededir ve Allah, kafir olan topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 38, 'Ey inananlar, size ne oldu da Allah yolunda savaşa çıkın dendiği zaman olduğunuz yerde mıhlanıp kaldınız. Âhireti bıraktınız da dünya yaşayışına mı razı oldunuz? Fakat dünya hayatının faydası, ahirete nispetle pek azdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 39, 'Hep birden savaşa çıkmazsanız sizi acıklı bir azapla azaplandırır ve yerinize, sizden başka bir topluluk getirir ve siz, ona hiçbir zarar vermezsiniz ve Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 40, 'Siz ona yardım etmezseniz hatırlayın o zamanı ki kafirler, onu yurdundan çıkardıkları zaman yardım etmişti ona. O, iki kişinin ikincisiydi ancak ve hani ikisi de mağaradaydılar, arkadaşına, mahzun olma demişti, şüphe yok ki Allah, bizimle beraberdir. Şüphe yok ki Allah, ona manevi bir kuvvet ve huzur vermişti ve onu, sizin görmediğiniz ordularla kuvvetlendirmişti ve kafir olanların sözlerini alçaltmıştı, Allah''ın sözüyse zaten yüceydi ve Allah, her şeye üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 41, 'Genciniz, ihtiyarınız, hep beraber savaşa çıkın ve mallarınızla, canlarınızla Allah yolunda savaşın, bilirseniz bu, sizin için daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 42, 'Onları hazır bir ganimete, yahut yakın bir yolculuğa çağırsaydın sana uyarlardı, fakat meşakkatle alınacak olan bu yol, onlara uzak geldi. Allah''a andiçerek gücümüz yetseydi sizinle beraber çıkardık diyecekler. Onlar, kendilerini helak ediyorlar ve Allah biliyor ki onlar yalancıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 43, 'Allah seni affetsin, ne diye izin verdin onlara? Vermeseydin de sence gerçekler de açığa çıksaydı, yalancıları da bilseydin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 44, 'Zaten Allah''a ve ahiret gününe inananlar, mallarıyla, canlarıyla, savaşacaklarından senden izin istemezler ki ve Allah, çekinenleri tamamıyla bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 45, 'Senden ancak Allah''a ve son güne inanmayıp yürekleri şüpheye düşenler ve şüpheleri içinde tereddüde düşüp bocalayanlar izin isterler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 46, 'Savaşa çıkmayı kursalardı elbette bir hazırlıkta bulunurlardı, fakat Allah, onların çıkmasını hoş görmedi de onları alıkoydu ve kendilerine, oturun oturanlarla denildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 47, 'Sizin aranızda onlar da çıksalardı içinizde şerri ve fesadı arttırmaktan başka bir şey yapamazlar, mutlaka içinizde fitne ve fesat çıkarmak için koşardururlardı. Sizden onları adamakıllı dinleyecekler, onlara kulak asacaklar da var ve Allah, zulmedenleri bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 48, 'Andolsun ki onlar, bundan önce de fitne ve fesat peşinde koşmuşlar, işini gevşetmeye uğraşıp aleyhine düzenler kurmuşlardı da sonucu gerçek olan yardım vaadi gelip çatmış ve Allah''ın dini, onların zoruna gitse de meydana çıkmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 49, 'Onlardan bana izin ver de bir muhalefete, bir fitneye düşürme beni diyenler de var. Bil ki onlar, muhalefetin tam içine düşmüşlerdir ve şüphe yok ki cehennem, kafirleri muhakkak surette tamamıyla kavramış, kuşatmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 50, 'Sana bir iyilik geldi mi kötüleşir onlar; bir musibete uğrarsan biz derler, daha önce tedbir aldık, ihtiyata riayet ettik ve güvenle, gururla yüz çevirip giderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 51, 'De ki: Bize Allah''ın takdir ettiğinden başka bir şey gelip çatmaz kesin olarak. Odur yardımcımız ve inananlar, Allah''a dayanmalıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 52, 'De ki: Bizim ya gazi yahut şehit olmamızdan, o iki güzel akibetten birine uğramamızdan başka bir şey mi gözetmedesiniz? Ve biz de sizin ya Allah katından, yahut da bizim elimizle, bizim tarafımızdan bir azaba uğramanızı gözleyip beklemedeyiz. Haydi siz gözetleyedurun, biz de sizinle beraber gözetlemekteyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 53, 'De ki: İster gönül rızasiyle, ister zorla ve istemeyerek Tanrı uğrunda mal harcedin, kesin olarak bu harcayışınız kabul edilmeyecek, şüphe yok ki siz, buyruktan çıkmış kötü bir topluluksunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 54, 'Mal harcayışlarının kabulüne mani olan da ancak onların Allah''ı ve Peygamberini inkar edip kafir oluşları, namazı, ancak üşene üşene kılışları ve zorla, istemeyerek Tanrı uğrunda mallarını verişleridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 55, 'Artık onların malları ve evlatları, seni şaşırtıp imrendirmesin. Şüphe yok ki Allah, onları o malla, o evlatla dünya hayatında azaplandırmayı diler ve kafir olarak da güçlükle can vermelerini murad eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 56, 'Şüphe yok ki onlar, sizden olduklarına dair Allah''a andederler, sizden değildirler, fakat onlar, ancak korkularından sizden görünen bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 57, 'Bir sığınacak yer, yahut mağaralar, yahut da bir delik bulsalardı yüzlerini derhal o tarafa döndürüverirlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 58, 'Onlardan, sadakaları vermede seni ayıplayan da var. O maldan diledikleri verilseydi hoşlanırlardı, verilmeyince de hemen kızarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 59, 'Ne olurdu şüpheden sıyrılıp Allah''ın ve Peygamberinin verdiğine hoşnut olsalardı ve Allah yeter bize, yakında lutfeder bize de Allah da verir, Peygamberi de, şüphe yok ki biz, ümidimizi Allah''a bağlamışız deselerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 60, 'Söz budur ancak; sadakalar, yoksulların, hiçbir şeyi bulunmayanların, o malı toplayıp devşirmeye memur olanların, gönülleri Müslümanlıkla uzlaştırılmak istenen kişilerin, kölelerle tutsakların, borçluların, Allah yolunda savaşanların ve yolda kalmışların hakkıdır, Allah''ın hükmüdür bu ve Allah her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 61, 'Onlardan öyleleri de var ki Peygamberi incitirler ve o derler, her söyleneni dinleyen bir kulak adeta. De ki: O, sizin için bir hayır kulağıdır, Allah''a ve inananlara inanır ve sizden inananlara rahmettir. Allah''ın Peygamberini incitenlere elemli bir azap vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 62, 'Sizi hoşnut etmek için gelirler de Allah''a andederler, halbuki inanmışsalar Allah''ı ve Resulünü hoşnut etmeleri daha doğrudur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 63, 'Bilmezler mi ki şüphesiz Allah''tan ve Resulünden kaçıp onlara yanaşmayanındır cehennem ateşi ve o, cehennemde ebedi kalır. Buysa pek büyük bir aşağılanmadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 64, 'Münafıklar, yüreklerindekini haber verecek bir surenin indirilmesinden ürkmekle beraber alay da ederler. De ki: Alay edin bakalım, şüphe yok ki Allah, ürküp çekindiğinizi meydana çıkaracaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 65, 'Kendilerine sorsan andolsun ki biz diyeceklerdir, ancak dalmıştık da şakalaşmada, oynaşmadaydık. De ki: Allah''la, ayetleriyle ve Peygamberiyle mi alay ediyordunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 66, 'Özür dilemeye kalkışmayın, siz kafir oldunuz sözde iman ettikten sonra. Sizin bir bölüğünüzü affetsek bile suçlu olduklarından dolayı bir bölüğünüzü azaplandıracağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 67, 'Nifak sahibi erkeklerle kadınların hepsi de birbirindendir, aynıdır; kötülüğü emrederler, halkı iyilikten vazgeçirmeye uğraşırlar ve ellerini yumarlar. Onlar Allah''ı unuttular da o da onları unuttu. Şüphe yok ki münafıklardır buyruktan çıkan kötü kişilerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 68, 'Allah, nifak sahibi erkeklerle kadınlara ve kafirlere cehennem ateşini vaadetmiştir, orada ebedi kalırlar, o yeter onlara ve Allah onlara lanet etmiştir ve onlar içindir bitip tükenmeyen daimi azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 69, 'Siz de, sizden öncekilere benziyorsunuz; onlar, kuvvetçe daha ileriydi sizden, malları, evlatları da daha fazlaydı. Nasibiniz kadar faydalanmak istediniz, nitekim sizden öncekiler de nasipleri kadar faydalanmak istediler ve onlar nasıl kafirliğe daldılarsa siz de daldınız. Yaptıkları iş, dünyada da boşa gitti, ahirette de ve onlardır ziyankarların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 70, 'Sizden önce gelip geçen Nuh, Âd ve Semud kavimleriyle İbrahim''in kavmine, Medyen ve Mu''tefikeler ehline ait haberler gelmedi mi size? Peygamberleri, apaçık delillerle onlara geldiler de onlara Allah zulmetmedi, fakat onlar kendilerine zulmettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 71, 'Erkek ve kadın müminler, birbirlerinin yardımcısıdır; iyiliği emrederler, halkı kötülükten vazgeçirmeye çalışırlar, namaz kılarlar, zekat verirler, Allah''a ve Peygamberine itaat ederler. Allah''ın rahmet edeceği insanlar, bunlardır. Şüphe yok ki Allah üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 72, 'Allah, inanan erkek ve kadınlara, kıyılarından ırmaklar akan cennetler, içlerinde tertemiz zevk ve sefalar edilecek olan ebedi Adn cennetlerinde bulunan meskenler vaadetmiştir. Allah''ın razılığıysa daha da büyüktür. İşte budur en büyük kurtuluş ve murada eriş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 73, 'Ey Peygamber, kafirlerle ve münafıklarla savaş, onlara karşı şiddetli davran. Onların yurdu cehennemdir ve orası, ne de kötü dönülüp varılacak bir yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 74, 'Söylemediklerine dair yemin ederler Allah adına, fakat andolsun ki, küfür sözünü söyledi onlar ve Müslüman olduklarını izhar ettikten sonra kafir oldular, elde edemedikleri şeyi de yapmaya çalıştılar, bu öç almaya kalkışmaları da ancak Allah''ın ve Peygamberinin, lütfedip onları zenginleştirmesine karşılıktı. Tövbe ederlerse hayırlı olur onlara, fakat yüz çevirirlerse Allah, onları dünyada da, ahirette de elemli bir azapla azaplandırır ve yeryüzünde onlara ne bir dost bulunur, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 75, 'Onlardan, bize lutfuyla, keremiyle ihsanda bulunursa biz de yoksullara tasadduk ederiz ve mutlaka iyi kişilerden oluruz diye Allah''la ahdedenler de var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 76, 'Fakat lutfedip ihsan edince verdiği şeyde nekesliğe başlarlar, ahitlerinden dönerler, zaten onlar dinden dönmüş kişilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 77, 'Böylece de Allah''a ettikleri vaadi tutmadıklarından ve yalan söylediklerinden dolayı kendisine kavuşacakları güne dek yüreklerine münafıklığı ilka etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 78, 'Hala da bilmezler mi ki Allah, şüphe yok ki onların gizlediklerini de bilir, fısıltıyla konuşup aralarında gizli kalan sözlerini de ve şüphe yok ki gizli şeyleri en iyi bilen, Allah''tır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 79, 'İnananlardan, istekleriyle ve farz edilenden fazla tasadduk edenlerle ve güçleri neye yetiyorsa ancak o kadar verenlerle alay edip onları ayıplayanları Allah, bu hareketlerinin karşılığı olarak cezalandırır ve onlar için elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 80, 'İstersen onların yarlıganmalarını dile, istersen dileme. Suçlarının örtülmesi için yetmiş kere niyaz etsen gene de Allah, kesin olarak yarlıgamaz onları. Bu da, Allah''ı ve Peygamberini inkar etmeleri, kafir olmaları dolayısıyladır ve Allah buyruktan çıkan kötü topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 81, 'Allah''ın Peygamberine muhalefet edenler, savaşa çıkmayıp oldukları yerde oturup kalmalarına sevindiler ve mallarıyla, canlarıyla, Allah yolunda savaşmak, onlara zor ve kötü geldi de bu sıcakta savaşa çıkmayın dediler. De ki: Cehennem ateşi, daha da sıcak; bir anlasalar şunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 82, 'Artık az gülsünler de çok ağlasınlar; bu da kazandıkları suç yüzünden uğradıkları cezadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 83, 'Allah seni şu seferden döndürür de onlardan bir toplulukla buluşursan onlar, savaşa çıkmak için senden izin istedikleri takdirde hemen de ki: Artık benimle ebediyen çıkamazsınız siz ve benimle beraber düşmanla kesin olarak savaşamazsınız. Şüphe yok ki ilk defa oturup kalmaya razı olmuştunuz, oturun geri kalanlarla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 84, 'Ve onlardan biri ölürse kesin olarak namazını kılma ve mezarının başında durma. Şüphe yok ki onlar Allah''a ve Peygamberine kafir oldular ve buyruktan çıkmış kötü kişi olarak öldüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 85, 'Onların malları, evlatları, seni şaşırtıp imrendirmesin. Şüphe yok ki Allah, onları o malla, o evlatla dünyada azaplandırmayı diler ve kafir olarak da güçlükle can vermelerini murad eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 86, 'Allah''a inanın ve Peygamberinin maiyetinde savaşın diye bir sure indirilince içlerinden malı, kudreti olanlar, senden izin isterler ve bırak bizi de oturanlarla kalalım derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 87, 'Onlar, oturup kalanlarla beraber olmaya razı olmuşlardır ve kalplerine mühür vurulmuştur onların, muhakkak ki onlar anlamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 88, 'Fakat Peygamber ve onunla beraber bulunan iman sahipleri, mallarıyla, canlarıyla savaşmışlardır ve onlardır bütün hayırlara sahip olanlar, onlardır kurtulup muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 89, 'Allah, onlara kıyılarından ırmaklar akan cennetler hazırlamıştır. Budur en büyük kurtuluş ve saadet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 90, 'Bedevilerin bir kısmı özür dilemek ve izin almak için geldi, Allah''a ve Peygamberine yalan söyleyenler de oturup kaldı. İçlerinden kafir olanlar, elemli bir azaba uğrayacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 91, 'Allah''a ve Peygamberine bağlı kaldıkça zayıflara, hastalara ve sefer levazımını tedarike kudreti yetmeyenlere bir suç yok. Fakat iyilik eden iyi kişilere savaştan geri kalmak için bir vesile yoktur ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 92, 'Bir de sana gelince onları bindirmek için senden binek istemişlerdi de sizi bindirecek binek bulamıyorum demiştin; bu uğurda sarfedecek bir şey bulamadıklarından mahzun olup gözleri yaşlarla dolarak dönmüşlerdi; onlara da suç yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 93, 'Suçlu sayılanlar, ancak zengin oldukları halde gelip senden izin isteyenlerdir. Onlar, geri kalanlarla kalmaya razı olmuşlardır ve Allah, kalplerini mühürlemiştir, fakat anlamaz onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 94, 'Seferden dönüp de onlarla buluştuğunuz zaman size özürler getirecek onlar; de ki: Özür dilemeyin, kesin olarak size inanmıyoruz; Allah, sizin ahvalinizi haber vermiştir bize ve bundan sonraki hareketlerinizi de Allah ve Peygamberi görecek, sonra da gizliyi ve açığı bilen Tanrının tapısına döneceksiniz de o, bütün yaptıklarınızı size bildirecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 95, 'Döndüğünüz zaman kendilerinden vazgeçmeniz için Allah''a ant verecekler; vazgeçin onlardan, şüphe yok ki onlar murdardır ve yurtları cehennemdir, bu da kazandıkları suçların karşılığıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 96, 'Onlardan razı olmanız için size ant verecekler, fakat siz razı olsanız da Allah, şüphe yok ki buyruktan çıkan topluluğun hareketlerine razı olmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 97, 'Bedeviler, kafirlik ve münafıklık bakımından şehirlilerden beterdir ve Allah''ın, Peygamberine indirdiği hükümlerin sınırlarını daha ziyade bilmezler, buna daha fazla onlar layıktır ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 98, 'Bedevilerden öyleleri vardır ki sarfedileni ziyan sayar ve size belalar gelip çatmasını gözetirdurur, bekledikleri kötü belalar, kendi başlarına gelsin ve Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 99, 'Bedevilerden Allah''a ve son güne inanıp sarfedileni Allah katında halis bir ibadet sayan ve Peygamberin dualarını kazanmaya vesile addedenler de var. Haberiniz olsun ki bu, gerçekten de onlar için bir ibadettir, Tanrıya yakın olmaya vesiledir. Allah, onları öz rahmetine ithal edecektir, şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 100, 'Muhacirlerle ensardan ilk olarak inanmada ileri dereceyi alanlarla iyilikte onlara uyanlara gelince: Allah onlardan razı olmuştur, onlar da ondan razı olmuşlardır ve onlara, kıyılarından ırmaklar akan cennetler hazırlamıştır, orada ebedi kalır onlar. Budur en büyük kurtuluş ve saadet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 101, 'Çevrenizdeki yerlerdeki bedevilerden münafıklar olduğu gibi Medinelilerden de münafıklığa cüret edenler, münafıklık edip duranlar var; sen onları bilmezsin, biz biliriz. Onları iki kere azaplandıracağız da sonra pek büyük bir azaba uğratılacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 102, 'Bedevilerle Medinelilerden başka bir bölüğü de günahlarını itiraf etmiştir, onlar, iyi bir işi bir başka kötü işe katmışlardır. Allah''ın, onlara tövbe nasib etmesi ve tövbelerini kabul eylemesi umulur. Şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 103, 'Mallarından sadaka al da temizle, arıt onları o sadakayla ve dua et onlara. Şüphe yok ki senin duan, onlara bir sükun, bir huzur verir ve Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 104, 'Bilmezler mi, şüphe yok ki Allah, öyle bir mabuttur ki odur kullarının tövbelerini kabul eden ve sadakaları alan ve şüphe yok ki Allah öyle bir mabuttur ki odur tövbeleri kabul eden rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 105, 'Ve de ki: Yapın yapacağınızı, muhakkak yaptıklarınızı Allah da görür, Peygamberi de, inananlar da ve gizliyi de, açığı da bilenin tapısına gideceksiniz ve mutlaka yaptıklarınızı haber verecek size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 106, 'Bir başka bölük de var ki işleri, Allah''ın emrine kalmış; dilerse azaplandırır onları, dilerse tövbelerini kabul eder ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 107, 'Zarar vermek, kafirlikte bulunmak, inananların aralarını açmak, daha önce Allah''la ve Peygamberiyle savaşanın gelmesini gözlemek için mescit kuranlara gelince: Biz ancak iyilik istemekteyiz diye yemin edecekler ve Allah''sa tanıklık etmektedir ki onlar yalancıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 108, 'Orada hiçbir zaman namaz kılma. İlk günden itibaren Allah''tan çekinmek ve ona itaat etmek temeli üstüne kurulmuş olan mescit, elbette namaz kılmana daha layıktır. Orada öyle erler var ki arınmayı severler ve Allah, temizlenip arınanları sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 109, 'Yapıyı Allah''tan korkup çekinme ve rızasını kazanma temelleri üstüne yapan mı daha hayırlıdır, yoksa temelini, kayıp gitmekte olan bir yarın kıyısına yapıp da o yapıyla beraber cehennem ateşine yıkılıp göçen mi? Ve Allah, zulmeden topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 110, 'Onların kurdukları yapı, kalpleri parçalanıp gitmedikçe kalplerine şüphe vermeden bir an bile geri kalmaz ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 111, 'Şüphe yok ki Allah, kendilerine cenneti vermek üzere inananların canlarını, mallarını satın almıştır adeta; onlar öldürürler, öldürülürler, her iki surette de vaadi gerçektir ve Tevrat''ta da sabittir, İncil''de de, Kur''an''da da ve ahdine Allah''tan daha ziyade vefa eden kimdir ki? Artık şu giriştiğiniz alışverişten dolayı sevinin ve budur işte en büyük kurtuluş ve saadet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 112, 'Tövbe edenler, ibadette bulunanlar, hamd eyleyenler, oruç tutanlar (savaş veya bilgi elde etmek için yurttan yurda gezenler), rüku edenler, secdeye kapananlar, iyiliği emredenler, kötülüğü nehyeyleyenler ve Allah sınırlarını koruyanlar. İşte bu inanmış kişileri de müjdele.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 113, 'Şüphesiz olarak cehennem ehli oldukları kendilerince bilindikten sonra akraba bile olsalar Peygamberin ve inananların, müşriklerin yarlıganmalarına dua etmeleri yakışmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 114, 'İbrahim''in, atası için yarlıganma dilemesi, ancak ona vaadettiğini tutmak içindi. Fakat onun, Allah düşmanı olduğu kendisince iyice anlaşıldığı zaman ondan vazgeçti. Şüphe yok ki İbrahim, çok ağlayıp dua eden, insanlara fazlasıyla merhamet eden bir zattı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 115, 'Allah, bir topluluğu doğru yola sevkettikten sonra sakınacakları şeyleri apaçık bildirinceye dek tekrar onları sapıklığa terketmez. Şüphe yok ki Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 116, 'Şüphe yok Allah, öyle bir mabuttur ki onundur göklerin ve yeryüzünün saltanat ve tedbiri; öldürür, diriltir ve ondan başka size ne bir dost vardır, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 117, 'Allah, Peygamberi ve içlerinden bir bölüğünün gönlü nerdeyse imandan dönecekken güçlük anında Peygambere uyan muhacirlerle ensarı tövbeye muvaffak etti ve onların tövbelerini kabul eyledi. Şüphe yok ki o, onları fazlasıyle esirger, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 118, 'Geri kalan üç kişiye, yeryüzü o kadar genişken daraldıkça daralmış, gönülleri sıkıldıkça sıkılmıştı da sonucu Allah''tan, gene ancak Allah''a kaçılabileceğini anlamışlardı. Sonra Allah, onları da tövbeye muvaffak etmişti. Şüphe yok ki Allah bir mabuttur ki odur tövbeleri kabul eden rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 119, 'Ey inananlar, çekinin Allah'' tan ve gerçeklerle beraber olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 120, 'Medinelilerle çevrelerindeki bedevilerin, Allah''ın Peygamberinden geri kalmaları ve onun katlandığı zahmetlere katlanmaları gerekmez. Çünkü Allah yolunda bir susuzluğa, bir yorgunluğa, bir açlığa düşerlerse, kafirleri kızdırıp kinlendirecek bir yereayak basarlarsa, herhangi bir düşmana karşı başarı elde ederlerse mutlaka karşılık olarak iyi bir iş yaptıkları yazılır; şüphe yok ki Allah iyilik edenlerin ecrini zayi etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 121, 'Az olsun, çok olsun, hiçbir şey harcamazlar, hiçbir vadiyi aşmazlar ki Allah onları, yaptıklarının daha güzeliyle mükafatlandırmayı takdir etmemiş olsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 122, 'İnananların hepsinin savaşa gitmesi lazım değil; bir kısmı savaşa gitmeli, bir topluluk da çekinmelerini sağlamak için kavimleri savaştan dönüp gelerek onlarla buluşunca onları korkutmak için dini hükümleri iyice öğrenmeye çalışmalıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 123, 'Ey inananlar, önce kafirlerden yakınınızda bulunanlarla savaşın, onlar, sizde bir şiddet ve azim bulsunlar ve bilin ki Allah, hiç şüphe yok, çekinenlerle beraberdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 124, 'Bir sure indirilince içlerinden bu hanginizin imanını artırdı diyen de var. Fakat inen sureler, inananların inançlarını artırır ve onlar birbirlerini müjdelerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 125, 'Ama gönüllerinde hastalık olanların pisliklerine pislik katarak küfürlerini artırır ve onlar, kafir olarak ölüp giderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 126, 'Görmezler mi ki onlar her yıl bir, yahut iki kere musibetlere uğratılırlar da gene ne tövbe ederler, ne ibret alırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 127, 'Bir sure indiği zaman birbirlerine bakarlar, sizi bir gören var mı derler de sonra dönüp giderler. Allah gönüllerini döndürmüştür onların, çünkü onlar, anlamaz bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 128, 'Andolsun, size içinizden, sizden öyle bir Peygamber gelmiştir ki bir sıkıntıya düşmeniz pek ağır gelir ona, pek düşkündür size, müminleri esirger, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (9, 129, 'Fakat döner, yüz çevirirlerse hemen de ki: Allah yeter bana, yoktur ondan başka tapacak, ona dayandım ve odur büyük arşın sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 1, 'Elif lam ra, işte hükmü kesin ve gerçek olan kitabın ayetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 2, 'İnsanları korkutmak ve inananlara, gerçek bir güzel mükafat, inançlarına karşılık yücelik ve nimet verileceğini, şefaate mazhar olacaklarını müjdelemek için içlerinden bir ere vahyetmemiz, insanlara tuhaf mı geldi de kafirler, şüphe yok ki dediler, bu, apaçık bir büyücü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 3, 'Şüphe yok Rabbiniz, öyle bir Allah''tır ki gökleri ve yeryüzünü altı günde yarattı da sonra arşında kudret ve tedbiriyle her şeye hakim oldu. Her işi o, takdir ve gereğince tedbir eder. Onun izni olmadıkça hiçbir şefaatçi, şefaatte bulunamaz. İşte Rabbiniz olan Allah budur, artık kulluk edin ona. Düşünmez, ibret almaz mısınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 4, 'Hepinizin dönüp varacağı yer, onun tapısıdır, gerçek olarak bunu vaadetmiştir Allah. Hiç şüphe yok ki o, halkı önce yaratır, sonra da inanıp iyi işlerde bulunanları, adalet üzere ve tam karşılığıyla mükafatlandırmak için ölümden sonra tekrar diriltir; kafir olanlaraysa, inkarlarından dolayı, içmek üzere kaynar su ve elemli bir azap vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 5, 'Öyle bir mabuttur o ki güneşi parlak ziyalı, ayı aydın ışıklı yarattı ve yılların sayısını ve hesabı bilmeniz için ona menziller tayin etti. Allah bunları boş yere değil, gerçek bir fayda için halketti. Bilen topluluğa delillerini açıklayıp bildirmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 6, 'Geceyle gündüzün, birbiri ardınca gelip gitmesinde ve Allah''ın, göklerde ve yeryüzünde halkettiği şeyler de, çekinen topluluğa elbette deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 7, 'Şüphe yok ki bize kavuşacaklarını ummayanlar ve dünya yaşayışına razı olup yürekleri onunla yatışanlar ve delillerimizden gaflet edenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 8, 'Öyle kişilerdir ki onların yurtları, kazançlarına karşılık ateştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 9, 'İnanıp iyi işlerde bulunanlaraysa Rableri, nimetlerle dolu olan ve kıyılarından ırmaklar akan cennetlerin yolunu gösterir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 10, 'Orada duaları, seni tenzih ederiz, noksan sıfatlardan arısın ey Allah''ım sözüdür, birbirlerine iltifatları, esenlik sana sözü ve dualarının, senalarının sonu da hamd, alemlerin Rabbi Allah''a cümlesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 11, 'Allah, insanların, hayrın çarçabuk oluvermesini istedikleri gibi şerri çarçabuk veriverseydi ecellerinin gelip çatmasına çoktan hükmedilmiş olurdu. Fakat biz, bize kavuşmayı ummayanları, azgınlıklarında sersem bir halde bırakırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 12, 'İnsana bir zarar gelince yanüstü yatarak, yahut oturduğu halde, yahut da ayakta dua eder bize; o zararı ondan giderdik mi sanki o zarara uğramamış da o yüzden bize dua etmemiştir, öylece dönergider. İşte aşkın hareketlerde bulunanlara, yaptıkları işler, böylece hoş görünmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 13, 'Andolsun ki sizden önce gelip geçen nice toplulukları zulmettikleri için helak ettik. Peygamberleri, onlara apaçık delillerle gelseydi gene de inanmazlardı. İşte mücrim topluluğu böyle cezalandırırız biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 14, 'Onlardan sonra da bakalım nasıl hareket edeceksiniz diye yeryüzünde sizi hüküm ve kudret sahibi kıldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 15, 'Onlara apaçık delilleri muhtevi olan ayetlerimiz okunduğu zaman bize kavuşmayı ummayanlar, bize bundan başka bir Kur''an getir, yahut da değiştir onu dediler. De ki: Ben onu kendiliğimden değiştiremem, ben, ancak bana vahyedilene uyarım ve şüphe yok ki ben, isyan ettiğim takdirde o pek büyük günün azabından korkarım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 16, 'De ki: Allah isteseydi okumazdım onu size ve o da, onda ne olduğunu bildirmez, anlatmazdı size. O inmeden önce de aranızda ömür sürmüştüm, hala mı aklınızı başınıza almıyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 17, 'Yalan yere Allah''a iftira edenden, yahut onun ayetlerini inkar edenden daha zalim kimdir ki? Şüphe yok ki suçlular, asla kurtulmazlar, muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 18, 'Ve Allah''ı bırakırlar da kendilerine ne bir zarar edebilecek, ne bir fayda verebilecek şeylere taparlar ve bunlar derler, Allah katında şefaatçilerimiz bizim. De ki: Allah''a, göklerde ve yeryüzünde bilmediği birşeyi mi haber vermedesiniz? O, müşriklerin şirk koştukları şeylerden tamamıyla münezzehtir ve çok yücedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 19, 'İnsanlar, ancak tek bir ümmetti, sonradan ayrılıklara düştüler. Rabbinin ezeli takdiri olmasaydı ayrılıklara düştükleri şeyler hakkında çoktan aralarında bir hüküm verilirdi, mücrimler, çoktan helak olup giderdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 20, 'Ve derler ki: Ona Rabbinden bir mucize indirilse ya. De ki: Gaip, ancak ve ancak Allah katında, hemen bekleyin siz ve şüphe yok ki ben de sizinle beraber beklemekteyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 21, 'Uğradıkları sıkıntıdan sonra insanlara bir rahmet tattırdık mı bir de bakarsın ki çabucak ayetlerimizle alaya girişirler. De ki: Allah''ın cezası daha çabuk gelip çatar. Şüphesiz ki elçilerimiz de sizin düzenlerinizi, alaylarınızı yazmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 22, 'Öyle bir mabuttur ki sizi karada ve denizde gezdirir. Hatta gemide bulunduğunuz ve güzel, temiz bir yel, gemileri sürüp akıttığı ve içindekiler ferahlayıp sevindiği sırada birden şiddetli bir fırtınadır kopar, denizin her yanından dalgalar köpürüp saldırır, gemidekiler, çepçevre o dalgalarla kuşatılmış sanırlar kendilerini. İhlasla Allah''a dua ederler, bizi bundan kurtarırsan şükredenlerden olacağız derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 23, 'Onları kurtarınca da görürsün ki gene yeryüzünde haksız yere azgınlığa girişmişler. Ey insanlar, azgınlığınız, ancak kendinize, dünya menfaatlerinin sonucudur bu, sonra dönüp geleceğiniz yer, bizim tapımızdır ve biz, neler yaptıysanız hepsini haber vereceğiz size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 24, 'Dünya yaşayışı, gökten yağdırdığımız yağmura benzer ancak; insanların ve hayvanların yiyecekleri nebatların bünyelerine girer, karışır onlara, yeşertir, yetiştirir onları ve sonucu, yeryüzü güzelleşip bezenince ve tarlaların, bağların sahipleri, kendilerini, onlardan faydalanmaya güçleri yeter sanınca bir gece, yahut gündüz, apansızın emrimiz gelip çatar, her şeyi öylesine kökünden kesip biçer, kurutup gider ki sanki dün, hiçbiri yokmuş. İşte biz, düşünce sahibi olan topluluğa delillerimizi böyle açıklar, böyle bildiririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 25, 'Ve Allah, esenlik yurduna çağırmadadır ve dilediğini doğru yola sevketmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 26, 'İyilik edenleri iyilikle mükafatlandırırız, daha da fazlasını veririz ve yüzleri kararmaz, zillete düşmez onlar. Onlardır cennet ehli, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 27, 'Kötülük kazananların cezasıysa yapılan kötülüğe karşılık onun kadar bir suçtur ve kötülükte bulunanlar zillete düşerler; onları Allah''tan kurtaracak hiç kimse yoktur; yüzleri, kapkaranlık gecenin bir parçasına bürünmüştür sanki. Onlardır cehennem ehli, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 28, 'O gün hepsini toplayacağız, sonra da şirk koşanlara siz de diyeceğiz, yerinizde durun, şirk koştuğunuz şeyler de yerlerinde dursun; aralarını tamamıyla ayırmışızdır ve şirk koştukları şeyler, siz zaten bize tapmıyordunuz ki demişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 29, 'Şüphe yok, bizimle sizin aranızda Allah tanıktır ki sizin kulluğunuzdan haberimiz bile yoktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 30, 'Herkes, evvelce yaptığını bulur, cezasını çeker orada ve hepsi de gerçek mevlalarının tapısına döndürülmüştür ve iftira ettikleri şeyler de gözlerinden kaybolmuş, helak olup gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 31, 'De ki: Size gökten, yerden rızık veren kimdir, kulaklarla gözlere malik olan kim ve ölüden diriyi izhar eden, diriden ölüyü meydana getiren kim ve işleri tedbir eden kim? Diyecekler ki Allah. O vakit de ki: Neden çekinmezsiniz öyleyse?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 32, 'İşte gerçek Rabbiniz Allah, budur, gerçekten sonra sapıklıktan başka ne kalır ki? Artık nereye dönmedesiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 33, 'Buyruktan çıkanlar, Rabbinin şu sözünü haketmişlerdir: Onlar, inanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 34, 'De ki: Ona eş saydıklarınızın içinde halkı önce yaratıp sonra öldüren, sonra da yeniden hayata getiren var mı? De ki: Allah, her şeyi ve herkesi yaratır, öldürür de sonra gene hayata getirir artık nasıl oluyor da gerçeği bırakıp batıla dönersiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 35, 'De ki: Ona eş saydıklarınız içinde hangisi halkı gerçeğe sevkedip yol gösterir? De ki: Allah, gerçek yola sevk eder, doğru yolu gösterir. Halkı gerçeğe sevk eden mi uyulmaya daha layıktır, doğru yola sevkedilmedikçe o yolu bulamayan mı? Nasıl hükmediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 36, 'Onların çoğu, ancak zanna kapılmışlardır. Şüphe yok ki zan, gerçek karşısında hiçbir şeye yaramaz. Şüphe yok ki Allah, onlar ne yapıyorlarsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 37, 'Bu Kur''an, Allah''tan başkasına izafe edilemez, ancak önceki kitapları gerçeklemede, onlardaki şeyleri açıklayıp ayanbeyan bildirmededir, hiçbir şüphe yoktur ki o, alemlerin Rabbi Allah tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 38, 'Yoksa onu Peygamber uydurdu mu diyorlar? De ki: Eğer öyle diyorsanız ve gerçekseniz Allah''tan başka gücünüz yettiği kim varsa yardıma çağırın da hep beraber onun bir suresine benzer bir sure meydana getirin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 39, 'Hayır, onlar bilgileriyle kavrayamadıkları ve henüz zuhur etmeyen vaitleri yalanladılar. Tıpkı bunun gibi evvelce gelip geçen ümmetler de peygamberlerini yalanlamışlardı. Bak da gör, zulmedenlerin sonları neye varmış, nice olmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 40, 'Onlardan inanan da var, inanmayan da ve Rabbin bozguncuları daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 41, 'Seni yalanlarlarsa sen de de ki: Benim yaptığım iş bana ait, sizin yaptıklarınız size. Siz, benim yaptığımdan uzaksınız, ben de sizin yaptıklarınızdan uzağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 42, 'İçlerinde seni dinleyen de var, fakat sen, üstelik bir de akılları olmayan sağırlara söz duyurabilir misin hiç?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 43, 'Onlardan sana bakan da var, fakat sen, üstelik bir de kör olanlara doğru yolu gösterebilir misin hiç?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 44, 'Şüphe yok ki Allah, insanlara hiçbir suretle zulmetmez, fakat insanlar, kendi kendilerine zulmederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 45, 'O gün onları tapısında öyle bir toplar ki kendilerini, dünyada sanki bir günün bir saati kadar eğlenmişler sanırlar. Aralarında tanışırlar, birbirlerini tanırlar. Allah''a kavuşacaklarını inkar edenler, şüphe yok ki zarara uğrarlar ve doğru yolu da bulamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 46, 'Onlara vaadettiğimiz azabın bir kısmını sana göstersek de onların dönüp gelecekleri yer, bizim tapımızdır, seni öldürsek ve sana göstermesek de; sonra da Allah, yaptıklarına tanıktır onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 47, 'Her ümmetin bir peygamberi var. Peygamberleri geldi mi aralarında adaletle hükmedilir ve onlara zulmedilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 48, 'Ve derler ki: Gerçekseniz bu vait ne zaman yerine gelecek', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 49, 'De ki: Allah dilemedikçe kendimden bile bir zararı gidermeye, bir hayrı elde etmeye gücüm yetmez. Her ümmetin mukadder bir zamanı var. Mukadder zamanları geldi mi ne bir an geri kalırlar, ne bir an önce helak olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 50, 'De ki: Azabı geceleyin, yahut gündüzün birdenbire gelip çatarsa ne yaparsınız, söyleyin bakalım. Suçlular, azabın çabucak gelmesini ne diye isterler ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 51, 'Ona, azap gelip çattıktan sonra mı iman edeceksiniz, halbuki böyle bir şeyin olmayacağını sanıp alay ederek çabucak gelmesini istiyordunuz hani.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 52, 'Sonra da zulmedenlere, tadın ebedi azabı denecek, kazandığınızın karşılığı neyse ondan başka bir şeyle mi cezaya uğrayacaktınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 53, 'O gerçek mi diye soruyorlar senden; de ki: Evet, andolsun Rabbime ki gerçektir ve siz de ondan kurtulmayacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 54, 'Zulmeden kişi, yeryüzünde ne varsa hepsine sahip olsaydı kurtulmak için hepsini de bağışlardı. Azabı görünce nadim olurlar ve aralarında adaletle hükmedilir. Zulüm görmez onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 55, 'Bilin ki hiç şüphe yok, göklerde ve yeryüzünde ne varsa Allah''ındır. Bilin ki Allah''ın vaadi, hiç şüphe yok gerçektir, fakat çokları bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 56, 'Odur dirilten ve öldüren ve hepiniz de dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 57, 'Ey insanlar, Rabbinizden size bir öğüt, gönüllerdeki dertlere şifa, inananlara hidayet ve rahmet geldi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 58, 'De ki: Allah''ın ihsanıyla, rahmetiyle, yalnız bunlarla ferahlanıp sevinsinler. Bu, onların derleyip topladıklarından daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 59, 'De ki: Allah''ın, size verdiği rızıklardan bir kısmını haram, bir kısmını helal saymanıza ne dersiniz? De ki: Allah mı izin verdi size, yoksa Allah''a iftira mı ediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 60, 'Allah''a yalan yere iftirada bulunanların kıyamet günü hakkındaki zanları nedir? Şüphe yok ki Allah, insanlara lütuf ve ihsanda bulunmadadır ama çokları şükretmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 61, 'Hiçbir işe girişmezsin, onun vahyettiği Kur''an''dan hiçbir ayet okumazsın ve siz hiçbir iş işlemezsiniz ki o işe koyulduğunuz zaman biz, sizi görmeyelim, tanık olmayalım ve yeryüzünde ve gökte zerre miktarı bir şey bile yoktur ki Rabbinden gizli kalsın; bundan daha da küçük, daha da büyük hiçbir şey yoktur ki apaçık kitapta tespit edilmiş olmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 62, 'Bilin, haberdar olun ki şüphe yok Allah dostlarına ne korku vardır, ne de mahzun olur onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 63, 'Onlar öyle kişilerdir ki inanmışlardır ve çekinir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 64, 'Onlara müjde var dünya yaşayışında da, ahirette de. Allah''ın sözlerinin değişmesine imkan yok. Budur en büyük kurtuluş ve saadet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 65, 'Onların sözü mahzun etmesin seni. Şüphe yok ki üstünlük, yücelik Allah''ındır. Odur duyan, bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 66, 'Bilin, haberdar olun ki Allah''ındır ne varsa göklerde ve ne varsa yeryüzünde ve ondan başka ona eş saydıkları şeylere tapanlar, onlara uymuyorlar, ancak kuru bir zanna uyuyorlar ve ancak yalan söylüyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 67, 'Öyle bir mabuttur ki geceyi dinlenmeniz için yaratmış, gündüzü de ışıklı halketmiştir. Şüphe yok ki bunda, duyan topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 68, 'Allah, kendisine evlat edinmiştir dediler, münezzehtir o, müstağnidir. Onundur ne varsa göklerde ve yeryüzünde: Şu iddianıza dair bir deliliniz var mı? Allah hakkında bilmediğiniz birşeyi mi söylüyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 69, 'De ki: Allah''a yalan isnat edip iftira edenler kurtulmazlar, muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 70, 'Dünyada değersiz menfaatler elde ettikten sonra dönüp tapımıza gelirler, sonra da kafir oldukları, inkar ettikleri şeyler yüzünden biz, onlara şiddetli bir azap tattırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 71, 'Oku onlara Nuh kıssasını. Hani kavmine, ey kavmim demişti, aranızda bulunmam ve Allah''ın ayetleriyle öğüt vermem ağır geliyorsa size, ben Allah''a dayanmışım, siz de, ortaklarınız da toplanın, ne yapacağınızı kararlaştırın, sonradan da yaptığınız şey, sizi kederlendirmesin, sonra kararınızı bildirin bana ve hiç mühlet de vermeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 72, 'Yüz çevirirseniz zaten sizden bir mükafat istemem, benim mükafatım, ancak Allah''a ait ve Müslümanlardan olmam emredildi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 73, 'Derken onu yalanladılar da onu ve onunla beraber gemide bulunanları kurtardık ve onları hükümdar ettik ve delillerimizi yalanlayanları sulara boğduk, bak da gör, korkutulanların sonları ne oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 74, 'Ondan sonra da insan topluluklarına peygamberler gönderdik, apaçık delillerle geldikleri halde önceden yalanladıkları şeylere bir türlü inanmadılar. İşte biz, haddini aşanların gönüllerini böyle mühürleriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 75, 'Onlardan sonra da Musa ve Harun''u, delillerimizle Firavun''a ve ona uyan ileri gelenlere gönderdik, fakat ona uymayı kibirlerine yediremediler ve zaten de mücrim bir topluluktu onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 76, 'Gerçek olan şey, katımızdan onlara gelince bu dediler, şüphe yok ki apaçık bir büyü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 77, 'Musa, size gerçek, gelince böyle mi dersiniz dedi, büyü mü bu? Ve büyücüler, kurtulmazlar, muratlarına erişmez onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 78, 'Bizi atalarımızdan bulup gördüğümüz şeylerden çevirip yeryüzünde bize hakim olmak için mi geldiniz ve biz, ikinize de inanmıyoruz dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 79, 'Ve Firavun, ne kadar bilgin büyücü varsa dedi, hepsini çağırın huzuruma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 80, 'Büyücüler gelince Musa, ne atacaksanız atın bakalım dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 81, 'Onlar atınca Musa, bu yaptığınız büyüdür dedi, ve şüphe yok ki Allah, onu bozacak, boşa çıkaracak, şüphe yok ki Allah, bozguncuların işlerini düzene sokmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 82, 'Suçluların zoruna gitse de Allah, sözleriyle gerçeğin gerçek olduğunu izhar eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 83, 'Firavun''un, kendilerini bir musibete uğratmasından korktukları için Musa''ya, kavminden bir soy inandı ancak, başkaları inanmadı ve gerçekten de Firavun, yeryüzünde pek yüceydi ve gerçekten o, buyruktan çıkmış kişilerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 84, 'Musa, ey kavmim dedi, Allah''a inandıysanız ve ona teslim olduysanız güvenin, dayanın ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 85, 'Dediler ki: Dayandık, Rabbimiz, sen bizi zalim toplulukla sınama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 86, 'Ve bizi, rahmetinle kurtar kafirler topluluğundan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 87, 'Ve Musa''ya ve kardeşine, kavminize Mısır''da barınacak evler kurun, evlerinizi kıble yapın ve namaz kılın ve müjdele inananları diye vahyettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 88, 'Ve Musa, Rabbimiz dedi, sen Firavun''a ve ona uyanlardan ileri gelenlere gerçekten de dünya yaşayışına ait ziynetler ve mallar verdin. Rabbimiz, onlar bu yüzden halkı doğru yoldan çıkarmada, saptırmadalar. Rabbimiz, mallarını mahvet, yurtlarında kendi sefaletlerini göster onlara da yüreklerini sık, çünkü onlar, o elemli azabı görünceye dek inanmayacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 89, 'Tanrı, ikinizin de duası kabul edilmiştir dedi, artık doğru hareket etmekte devam edin ve sakın ha bilmezlerin yoluna gitmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 90, 'İsrailoğullarını denizden geçirdik, derken Firavun''la askeri de azgınlıkla, düşmanlıkla peşlerine düştü onların, sonucu su boğazına girince boğulurken inandım, gerçekten de İsrailoğullarının inandığı Tanrıdan başka tapacak yok ve ben Müslümanlardanım dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 91, 'Fakat şimdi mi? Halbuki bundan evvel isyan etmiştin, bozgunculardan olmuştun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 92, 'O halde bugün biz de, senden sonra gelenlere ibret olasın diye yalnız cesedini kurtaracağız ve şüphe yok ki insanların çoğu, bizim delillerimizden gaflettedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 93, 'Andolsun ki biz İsrailoğullarını güzel bir yere yerleştirdik ve onları, tertemiz şeylerle rızıklandırdık. Kendilerine bilgi gelinceye dek de ayrılığa düşmediler. Şüphe yok ki Rabbin, ayrılığa düştükleri şeyler hakkında kıyamet günü, aralarında hükmedecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 94, 'Sana indirdiğimiz şeyde şüpheye düşersen (imkan yok ya), senden önce kitap okuyanlara sor. Andolsun ki gerçek, Rabbinden gelmiştir sana, artık şüphelenenlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 95, 'Ve Allah''ın delillerini yalanlayanlardan olma sakın, yoksa ziyankarlara katılırsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 96, 'Öyle kişilerdir onlar ki Rabinin, onlara söylediği sözü haketmiştir onlar, inanmaz onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 97, 'Kendilerine her çeşit deliller, mucizeler gösterilse de elemli azabı görmedikçe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 98, 'İnanıp da inançlarından fayda gören şehir halkı, ancak Yunus''un kavmidir. İnandıkları zaman, dünya yaşayışında onlardan zillet azabını giderdik ve bir zamanadek faydalandırdık onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 99, 'Rabbin dileseydi yeryüzünde bulunanların hepsi de inanırdı. Artık inansınlar diye insanları zorlayıp duracak mısın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 100, 'Allah''ın izni olmadıkça hiç kimse inanamaz. Düşünüp akıl etmeyenlere de azap eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 101, 'De ki: Bir bakın da görün, neler var göklerde ve yeryüzünde. Fakat bunca deliller, bunca korkutan peygamberler, inanmayan topluluğa ne fayda eder?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 102, 'Onlar, kendilerinden önce gelip geçenlerin uğradıkları felaket günlerine benzer günlerden başka bir şey mi bekliyorlar? De ki: Bekleyin bakalım, şüphe yok ki ben de sizinle beraber bekleyenlerdenim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 103, 'Sonra peygamberlerimizi ve inananları böylece kurtarırız biz ve inananları kurtarmak, bir haktır bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 104, 'De ki: Ey insanlar, dinimde bir şüpheniz varsa bilin ki ben, Allah''ı bırakıp taptıklarınıza tapamam ve ancak sizi öldüren Allah''a kulluk ederim ve inananlardan olmam emredildi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 105, 'Ve doğru dine yüz çevir, sakın müşriklerden olma dendi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 106, 'Ve Allah''ı bırakıp da sana ne bir faydası dokunan, ne bir zarar veren şeylere tapma, bunu yaparsan şüphe yok ki zalimlerden olursun dendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 107, 'Allah, sana bir zarar verirse o zararı, ondan başka giderecek yoktur ve hayır etmek dilerse de ihsanını reddeden bulunmaz; bunu, kullarından dilediğine verir ve odur suçları örten rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 108, 'De ki: Ey insanlar, gerçekten de Rabbinizden hak ve hakikat gelmiştir size. Artık kim doğru yola giderse faydası kendisinedir ve kim saparsa zararı kendine ve ben, sizi koruyucu değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (10, 109, 'Sana ne vahyedilirse ona uy ve Allah hükmedinceye dek sabret ve odur hükmedenlerin en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 1, 'Elif lam ra; bir kitaptır bu ki ayetleri, delillerle sağlamlaştırılmış, sonra apaçık bildirilmiştir, hüküm ve hikmet sahibi olan ve her şeyden haberdar bulunan Tanrı katından inmedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 2, 'Emreder ki ancak Allah''a kulluk edin; şüphe yok ki ben, onun tarafından sizi korkutmak ve size müjde vermek için gelmişim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 3, 'Ve Rabbinizden yarlıganma dileyin, sonra da tövbe edin ona da sizi mukadder zamanadek güzel bir surette geçindirsin, nimetlerinden faydalandırsın ve her ihsan sahibine, ettiği lütuf ve ihsanın mükafatını versin. Fakat döner, yüz çevirirseniz şüphe yok ki ben, o büyük günün azabına uğrayacağınızdan korkmaktayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 4, 'Dönüp varacağınız yer, Allah''ın tapısıdır ve onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 5, 'Haberiniz olsun ki onlar, içlerindekini gizlemek için göğüslerini kapatırlar; bilin ki onlar, duymamak için elbiselerine katkat bürünmeye çalışırlar; fakat o vakit bile gizlediklerini de bilir, açığa vurduklarını da. Şüphe yok ki o, gönüllerde ne varsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 6, 'Yeryüzünde hiçbir mahluk yoktur ki rızkını vermek, Allah''a ait olmasına ve karar ettikleri ata bellerini de bilir, tevdi edildikleri ana rahimlerini de. Ve her şey, apaçık kitapta tespit edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 7, 'Öyle bir mabuttur ki hanginiz daha iyi hareket edecek, bunu size bildirmek ve sizi sınamak için gökleri ve yeryüzünü altı günde yarattı, daha önce emri ve saltanatı, yarattığı suya cariydi. Onlara, siz ölümden sonra tekrar dirileceksiniz dersen kafir olanlar derler ki: Bu, ancak apaçık bir aldatma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 8, 'Onların uğrayacakları azabı, mukadder bir zamana kadar geciktirirsek, bunun teahhuruna da sebep nedir derler. Bilin ki onlara azabın gelip çattığı gün o azap, artık geriye bırakılamaz ve alay ettikleri musibet, onları çepeçevre kuşatır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 9, 'İnsana, katımızdan bir rahmet tattırsak da sonra alıversek onu insandan, şüphe yok ki her şeyden ümidini keser, bir nankör olur gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 10, 'Fakat ona, bir dertten, bir musibetten sonra nimeti tattırırsak benden bütün kötülükler gitti der. Şüphe yok ki o şımarır, böbürlenmeye övünmeye koyulur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 11, 'Ancak sabredenler ve iyi işlerde bulunanlar müstesnadır. Öyle kişilerdir onlar ki onların hakkıdır yarlıganmak ve büyük bir ecir ve mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 12, 'Ona bir hazine indirilseydi, yahut onunla beraber yanında bir melek de gelseydi demelerine sıkılarak sana vahyedilenlerin bir kısmını terk ediverecek misin? Sen ancak bir korkutucusun ve Allah her şeyi korur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 13, 'Yoksa kendi uyduruyor mu diyorlar? De ki: Hadi, gerçekseniz, Allah''tan başka gücünüz kime yetiyorsa, kimlere güveniyorsanız onları da çağırın da hep beraber, buna eşit on sure meydana getirin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 14, 'Fakat davetinize icabet etmezlerse artık iyice bilin ki o, ancak Allah''ın bilgisiyle indirilmiştir ve ondan başka hiçbir tapacak yoktur. Hala mı Müslüman olmuyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 15, 'Kim dünya yaşayışını ve ziynetini dilerse bu çeşit kişilerin yaptıklarının karşılığını tam olarak öderiz ve onlar, bu hususta hiçbir zarara uğramazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 16, 'Öyle kişilerdir onlar ki ahirette onlara ancak ateş var, dünyada işledikleri işlerse boşa gitmiştir, zaten de bütün işledikleri boştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 17, 'Rabbinden apaçık bir delile sahip olan, bundan başka bir de tanığı olup daha önce din ve dünya işlerinde uyulan ve aynı rahmet olan Musa''nın kitabında da bildirilen kişi, yalnız dünyayı dileyene benzer mi? Rablerinden açık bir delile sahib olanlar, Kur''an''a inanırlar; topluluklardan onu inkar edenlere vaadedilen yerse ateştir. Artık bu hususta şüpheye düşme, çünkü o, Rabbinden gelmedir, gerçektir, fakat insanların çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 18, 'Yalan yere Allah''a iftira edenden daha zalim kimdir ki? Onlar, Rablerine arzedilecekler, tanıklar da işte bunlardı diyecekler, Rablerine karşı yalan söyleyenler. İyice bilin, Allah''ın laneti zalimleredir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 19, 'Onlar, halkı Allah yolundan menederler ve o yoldan saptırmak isterler, onlar ahiret inkar edenlerin ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 20, 'Onlar, ne yeryüzünde azaptan kaçıp kurtulabilirler, ne de Allah''tan başka bir yardımcıları vardır. Azapları da katkat arttırılır. Çünkü onların işitmeye tahammülleri yoktu, görmezlerdi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 21, 'Onlar, öyle kişilerdir ki kendilerine zarar verdiler ve uydurdukları şeyler de onlardan çekildi, kaybolup gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 22, 'Gerçekten de onlar ahirette en çok ziyana uğrayanların ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 23, 'İnanıp iyi işlerde bulunanlara ve Rablerine yalvarıp yakaranlara gelince: Onlardır cennet ehli ve onlar, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 24, 'Bu iki bölük, kör ve sağırla gören ve duyan adama benzer sanki; bu ikisi, birbirine eşit olur mu hiç? Yoksa düşünmez misiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 25, 'Andolsun ki biz Nuh''u, kavmine gönderdik de şüphe yok ki dedi, ben, size apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 26, 'Ancak Allah''a kulluk edin, çünkü gerçekten de elemli bir günün azabı gelip çatacak size, bundan korkuyorum ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 27, 'Kavminin kafir olanlarından ileri gelenler, biz dediler, seni de bizim gibi bir adam görmedeyiz ve sana uyanları da görüyoruz ki düşünmeden ve derhal sana kapılıveren ve ancak aşağılık tabakadan olan adamlarımız ve sizin, bize bir üstünlüğünüzü de görmüyoruz, hatta yalancı olduğunuzu sanıyoruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 28, 'Nuh, ey kavmim dedi, ya ben Rabbimden apaçık bir delille gelmişsem ve katından bana bir rahmet vermişse, fakat bunu, siz görmüyorsanız. İstemediğiniz halde kabul etmeniz için de sizi zorlayacak mıyım ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 29, 'Ey kavmim, bu yüzden bir mal da istemem sizden; ecrim, ancak Allah''a ait ve ben, inananları kovacak da değilim; şüphe yok ki onlar, Rablerine kavuşacaklar, fakat sizi görüyorum ki bilgisiz bir kavimsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 30, 'Onları kovarsam ey kavmim, Allah''tan başka kim yardım eder bana, hiç de mi düşünmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 31, 'Ve ben, Allah''ın hazineleri yanımda demediğim gibi gaybı bilirim de demiyorum ve ben bir meleğim gibi bir söz de etmiyorum, fakat sizin gözünüze hor görünenler hakkında, Allah onlara hiçbir suretle ve kesin olarak bir hayır vermez de diyemem. İçlerinde ne var, Allah daha iyi bilir. Ancak onları kovar, haklarında bu çeşit sözler söylersem mutlaka zulmedenlerden olurum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 32, 'Ya Nuh dediler, gerçekten de bizimle uğraşmadasın ve uğraşmanda ileri de gittin, gerçeklerdensen hadi, tehdit edip durduğun azaba uğrat bizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 33, 'Nuh, dilerse dedi, Allah uğratır ancak o azaba sizi ve onu aciz bir hale getiremezsiniz siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 34, 'Azgınlığınıza karşılık Allah sizi helak etmeyi murad etmişse öğüt vermek istesem de öğüdüm bir fayda vermez size. Odur Rabbiniz ve dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 35, 'Yoksa kendisi uyduruyor bunları mı diyorlar. De ki: Eğer uyduruyorsam benim suçum, bana ait ve ben sizin yaptığınız suçlardan uzağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 36, 'Nuh''a, kavminden inananlardan başkaları kesin olarak inanmayacak, artık sen de onların yaptıkları işler yüzünden kederlenme diye vahyedildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 37, 'Nezaretimiz altında ve vahyimize uyarak bir gemi yap, zulmedenler için af dileme benden, şüphe yok ki sularda boğulacak onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 38, 'Gemiyi yapmaya koyulmuştu ve kavminin ileri gelenleri, yanından geçerken alay ediyorlardı onunla, o da, alay ediyorsunuz bizimle ama diyordu, siz nasıl alay ediyorsanız biz de sizinle öyle alay edeceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 39, 'Artık, uğrayanı horhakir edecek azabın kime gelip çatacağını ve daimi azaba kimin uğrayacağını yakında bilir, anlarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 40, 'Sonucu emrimiz gelip tandırın altından su kaynamaya başlayınca her mahluktan birer çifti ve helaki taktir edilenden başka ailenden olanları ve inananları gemiye yükle dedik; zaten maiyetinde bulunan inanmış kişiler de pek azdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 41, 'Ve Nuh, binin gemiye dedi; akıp gitmesi de Allah adıyladır onun, durması da. Şüphe yok ki Rabbim, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 42, 'Gemi, içindekilerle dağlar gibi dalgalar üstünde akıp gidiyordu. Nuh, kendisinden çekilip ayrı bir yerde bulunan oğluna oğulcuğum dedi, bin sen de bizimle ve kafirlerle beraber olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 43, 'O, dağda bir yere sığınırım ben dedi. Nuh, bugün dedi Allah''ın acıdığı kişilerden başka onun emrinden kurtulacak yok ve derken aralarına bir dalgadır giriverdi ve o da boğulanlara katıldı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 44, 'Ve dendi ki: Ey yeryüzü, em suyunu ve ey gök kes yağmurunu ve su emildi ve iş yapıldıbitti ve oturdu Cudi''ye gemi ve uzaklık denildi, zulmeden topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 45, 'Ve Nuh Rabbine niyaz edip dedi ki: Rabbim, oğlum da şüphe yok ki ailemdendi ve şüphe yok ki vaadin gerçektir senin ve sen, hükmedenlerin en hayırlısısın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 46, 'De ki: Ya Nuh, o, kesin olarak senin ailenden değil, çünkü o, kötü bir iş işledi. Artık bilmediğin şeyi isteme benden şüphe yok ki bilgisizlerden olmaman için öğüt vermedeyim sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 47, 'Nuh, Rabbim dedi, bilmediğim şeyi senden istemekten, gene sana sığınırım ve beni yarlıgamazsan, bana acımazsan ziyankarlardan olurum ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 48, 'Dendi ki: Nuh, sana ve seninle beraber bulunanlardan türeyecek ümmetlere bizden gönderilen esenlikler ve bereketlerle in gemiden. Onlardan türeyecek ümmetler içinde öyleleri de var ki onları da bir müddet faydalandıracak, geçindireceğiz de sonra bizden elemli bir azaba uğrayacaktır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 49, 'İşte bunlar, gaibe ait haberlerdir ki sana onları vahyediyoruz. Bundan önce ne sen onları biliyordun, ne kavmin biliyordu, sabret artık; şüphe yok ki sonuç, çekinenlerindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 50, 'Âd kavmine de kardeşleri Hud''u göndermiştik de ey kavmim demişti, Allah''a kulluk edin, ondan başka bir mabudunuz yok; siz ancak iftira etmedesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 51, 'Ey kavmim, buna karşılık sizden bir ecir de istemiyorum, ecrim, ancak beni yaratana ait, hala akıl etmeyecek misiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 52, 'Ey kavmim, Rabbinizden yarlıganma dileyin de sonra tövbe edin ona, size gökten bol bol yağmur yağdırsın, kuvvetinize, fazlasıyla kuvvet katsın ve mücrim olarak yüz çevirmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 53, 'Ey Hud dediler, sen bize apaçık bir delil gösteremiyorsun, biz de senin sözünle tanrılarımızı bırakmayız ve biz sana inanmıyoruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 54, 'Tanrılarımızın bir kısmı seni fena çarpmış deriz de başka bir şeycik demeyiz. O, şüphe yok ki dedi, ben Allah''ı tanık tutmadayım, siz de tanık olun, ben sizin şirk koştuğunuz şeylerden tamamıyla uzağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 55, 'Onu bırakıyor da taptıklarınızı ona eş tutuyorsunuz, uzağım onlardan, hadi, hepiniz, aleyhime düzen kurun, sonra da hiç göz açtırmayın bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 56, 'Şüphe yok ki ben, Rabbim ve Rabbiniz Allah''a dayandım; yeryüzünde yürür hiçbir mahluk yoktur ki o, onun alnına düşen saçlardan tutup çekmesin, onun mukadderatını tayin etmesin ve şüphe yok ki Rabbim, dosdoğru yoldadır, bütün kudretiyle beraber adaletiyle, lütfuyla hükmeder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 57, 'Yüz çevirirseniz bilin ki ben, size neyi tebliğ etmek için gönderildiysem onu tamamıyla tebliğ ettim ve Rabbim, sizin yerinize, sizden başka bir topluluğu geçirecek ve siz ona hiçbir suretle zarar veremezsiniz. Şüphe yok ki Rabbim her şeyi korur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 58, 'Emrimiz gelince Hud''u ve onunla beraber bulunan inanmış kişileri, bizden bir rahmet olarak kurtardık ve onlara ağır bir azaptan necat verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 59, 'İşte Âd, Rablerinin delillerini bilebile inkar ettiler ve peygamberlerine asi oldular ve her inatçı cebbar kişiye uydular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 60, 'Ve şu dünyada da lanete uğratıldılar, kıyamet gününde de. Bilin ki hiç şüphe yok Âd, Rablerine karşı kafir oldu; bilin, uzaklık Hud''un kavmi Âd''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 61, 'Semud kavmine de kardeşleri Salih''i göndermiştik. Ey kavmim demişti, Allah''a kulluk edin, ondan başka bir mabudunuz yok. Sizi yeryüzünden yaratıp meydana getirdi ve orayı imara memur etti sizi; artık ondan yarlıganma dileyin, sonra da tövbe edin ona. Şüphe yok ki Rabbim, yakındır, duaları kabul eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 62, 'Ey Salih dediler, bundan önce sen aramızda, hakkında iyi ümitler beslediğimiz birisiydin, şimdi atalarımızın taptıkları şeylerden bizi vaz geçirmek mi istiyorsun? Ve biz, gerçekten de senin bizi davet ettiğin şey hakkında şüphe içindeyiz, tereddüt etmekteyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 63, 'O, ey kavmim dedi, ya ben Rabbimden apaçık bir delille gelmişsem ve katından bana bir rahmet vermişse. Ona isyan edersem Allah''a karşı kim yardım edebilir bana? Ve beni boyuna ziyana sokmaktan başka bir şey de yapmıyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 64, 'Ey kavmim, işte şu Allah''ın dişi devesi, size bir mucize. Bırakın onu da yeryüzünde yiyip gezsin ve ona kötülükle dokunmayın, sonra pek yakın bir azap gelip çatar size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 65, 'Ayaklarını kesip öldürdüler onu, Salih de yurdunuzda üç gün daha yaşayıp geçinin dedi, bu, yalan denmesine imkan bulunmayan bir vait.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 66, 'Emrimiz gelince Salih''i ve onunla beraber bulunan inananları, bir rahmet olarak kurtardık ve o günün horluğundan necat verdik onlara. Şüphe yok ki Rabbin, çok kuvvetlidir, o, pek üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 67, 'Bir bağırış, o zulmedenleri kapıverdi, yurtlarında, diz çökmüş bir halde helak oluverdiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 68, 'Sanki orada hiç yaşamamışlar, hiç oturmamışlardı. Bilin ki hiç şüphe yok Semud, Rablerine karşı kafir oldu, bilin, uzaklık Semud''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 69, 'Elçilerimiz, İbrahim''e müjde vermek üzere gelip esenlik sana dediler. O da esenlik size dedi ve durup eğlenmeden hemen kızarmış bir buzağı getirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 70, 'Yemeğe el uzatmadıklarını görünce de halleri, hoşuna gitmedi ve onlardan, içine bir korku düştü. Dediler ki: Korkma, biz Lut kavmine gönderildik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 71, 'Karısı, ayakta durup sevincinden gülmedeydi ki biz ona, İshak''ı müjdeledik, İshak''tan sonra da Yakup''u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 72, 'O, eyvahlar olsun dedi, ben mi doğuracağım? Ben bir kocakarıyım, şu kocam da ihtiyar. Şüphe yok ki bu, pek şaşılacak bir şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 73, 'Onlar, Allah''ın işine mi şaşıyorsun dediler, ey Ehli Beyt, Allah''ın rahmeti ve bereketleri size; şüphe yok ki o, övülmeye layık, kullara müstahak olmadan ihsanda bulunan bir Tanrıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 74, 'İbrahim''in korkusu yatışıp müjdelenince Lut kavmi hakkında bizimle mücadeleye girişmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 75, 'Çünkü İbrahim, gerçekten de pek halimdi, fazla dua edip ağlardı, kendisini tamamıyla Tanrıya vermişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 76, 'Ey İbrahim dediler, vazgeç bundan, şüphe yok ki Rabbinin emri gelip çatmıştır ve şüphe yok ki onlar reddine imkan olmayan bir belaya uğrayacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 77, 'Elçilerimiz, Lut''a gelince Lut, gelişlerinden endişeye düştü, içine bir korku girdi, gönlü daraldı ve bu dedi, pek çetin bir gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 78, 'Kavmi, koşa koşa onun yanına geldi, onlar, önceden de kötülükler yapar dururlardı. Lut, ey kavmim dedi, işte kızlarım, onlar, sizin için daha temiz, artık Allah''tan çekinin de beni, konuklarımdan utandırmayın. İçinizde, aklı başında bir adam da mı yok?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 79, 'Andolsun ki dediler, sen de bilirsin, kızlarında hiç gözümüz yok, sen bizim ne istediğimizi bilirsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 80, 'Lut, size karşı koyacak gücüm, kuvvetim olsaydı, yahut da kuvvetli bir aşiretim olsaydı da ona sığınsaydım dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 81, 'Melekler, ey Lut dediler, şüphe yok ki biz, Rabbinin elçileriyiz, onlar, sana kesin olarak ilişemezler; sen gece karanlığı basınca ailene mensup olanlarla yola düş, hiçbiriniz, ardına bakmasın, ancak karını beraber götürme, çünkü o da onların uğrayacağı azaba uğrayacak. Şüphe yok ki uğrayacakları azabın mukadder zamanı, sabah çağıdır; sabah da yakın değil mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 82, 'Emrimiz gelince, o şehirlerin altını üstüne getirdik, tepelerine, üstüste yığılıp taş kesilmiş balçıktan meydana gelmiş taşlar yağdırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 83, 'Sanki damgalanmıştı Rabbinin indinde de azap için hazırlanmıştı o taşlar ve onlar, şimdi de zalimlerden uzak değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 84, 'Medyen''e de, kardeşleri Şuayb''i göndermiştik de ey kavmim demişti, Allah''a kulluk edin, ondan başka bir mabudunuz yok. Ölçeğitartıyı eksik tutmayın, çünkü ben gerçekten de hayırlara uğradığınızı görmedeyim ve şüphe yok ki ben, bir gün sizi çepeçevre kuşatıverecek bir azaba uğramanızdan korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 85, 'Ey kavmim, ölçeği doğru ölçün, teraziyi doğru tartın, halkın mallarını eksiltmeyin, yeryüzünde bozgunculuk etmeye çalışmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 86, 'İnanmışsanız Allah''ın bıraktığı kar, daha hayırlıdır size ve ben de size bir bekçi değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 87, 'Ey Şuayb dediler, kıldığın namaz mı, tuttuğun din mi emrediyor sana da bizi atalarımızın taptıklarından vazgeçirmeye uğraşıyor, mallarımızı da dilediğimiz gibi tasarruf etmemize mani olmaya kalkışıyorsun? Halbuki sen, şüphe yok ki halimselim ve aklı başında bir adamsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 88, 'Ey kavmim dedi Şuayb, ya Rabbimden apaçık bir delille gelmişsem, ya kendi katından beni güzel bir rızıkla rızıklandırmışsa. Sizi nehyettiğim şeye kendim aykırı hareket edemem ki. Gücümün yettiği kadar ıslah etmek istiyorum sizi ve başarım, ancak Allah''tandır, ona dayandım ve sonunda da dönüp onun tapısına varacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 89, 'Ey kavmim, bana karşı güttüğünüz düşmanlık, Nuh, yahut Hud, yahut da Salih kavimlerinin uğradıkları azaba benzer bir azaba uğratmasın sizi; Lut kavmi de uzak değil sizden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 90, 'Rabbinizden yarlıganma dileyin, sonra da tövbe edin ona; şüphe yok ki Rabbim rahimdir, kullarını sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 91, 'Ey Şuayb dediler, söylediğin sözlerin çoğunu anlamıyoruz ve seni de içimizde zayıf görmedeyiz. Kabilen olmasaydı seni taşlardık ve sen, bizden üstün değilsin zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 92, 'Şuayb, ey kavmim dedi, kabilem, sizce Allah''tan daha fazla mı saygıya değer ki onu ardınıza attınız? Şüphe yok ki Rabbim, bütün yaptıklarınızı kavrar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 93, 'Ey kavmim, elinizden ne geliyorsa yapın, ben de yapmadayım elimden geleni. Kime, aşağılatıcı azap gelecek ve kim yalancıdır, yakında bilir, anlarsınız; gözetip durun, ben de gözlüyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 94, 'Emrimiz gelince Şuayb''i ve onunla beraber inanmış olanları, bizden bir rahmet olarak kurtardık, zulmedenleriyse bir bağırış kavrayıverdi ve hepsi de yurtlarında diz çökmüş bir halde helak oluverdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 95, 'Sanki yurtlarında hiç yaşamamışlar, hiç oturmamışlardı. Bilin ki uzaklık Medyen ehline, nitekim Semud da öylece uzaklaşıp gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 96, 'Andolsun ki biz Musa''yı, delillerimizle ve apaçık bir burhanla göndermiştik', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 97, 'Firavun''a ve kavminden ileri gelenlere fakat gene de onlar Firavun''un buyruğuna uymuşlardı, halbuki Firavun''un buyruğu, hiç de doğruyu göstermiyor, hayra sevketmiyordu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 98, 'O, kıyamet günü de kavminin önüne düşecektir ve artık onları ateşe götürmüş, gitmiştir ve vardıkları yer, ne de kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 99, 'Burada da lanete uğradılar, kıyamet gününde de. Şu bağışlanan bağış, ne de kötü bağıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 100, 'Bunlar, maceralarını sana hikaye ettiğimiz şehirlere ait haberler; o şehirlerden harabeleri hala duranlar var, biçilmiş ekin gibi yerle bir olanlar, eseri bile kalmayanlar var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 101, 'Biz zulmetmedik onlara, fakat onlar, kendi kendilerine zulmettiler; Rabbinin emri gelince, Allah''ı bırakıp da kulluk ettikleri tanrıları, onlara hiçbir fayda veremedi ve ziyanlarını arttırmaktan başka bir şey yapamadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 102, 'İşte Rabbin, zulmeden şehirleri böyle alıverir, aldığı, azabına uğrattığı zaman da şüphe yok ki onun kavrayışı pek elemlidir, pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 103, 'Gerçekten de bunda, ahiret azabından korkanlara bir ibret var; o gün, bütün insanların bir araya toplanacağı bir gündür ve bütün insanların hazır olacağı bir gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 104, 'Ve biz o günün gelip çatmasını, ancak sayılı bir müddet için geciktiririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 105, 'O gün geldi mi hiçbir kimse, Rabbinin izni olmaksızın konuşamaz; onların bir kısmı kutsuzdur, bir kısmı kutlu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 106, 'Ama kutsuz olanlar, gerçekten de ateştedir, onların inliyerek nefes almaları da oradadır, biten bir inilti gibi nefes vermeleri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 107, 'Rabbinin dilediğinden başka hepsi de orada ebedi kalır göklerle yeryüzü durdukça; şüphe yok ki Rabbin, dilediğini dilediği gibi yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 108, 'Ama kutlu olanlarsa cennettedir, orada ebedi kalır Rabbinin dilediğinden başka hepsi, gökler ve yeryüzü durdukça; bitip tükenmesi olmayan bir bağıştır bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 109, 'Artık bunların taptıkları şeylerin boşluğunda bir şüphen olmasın; önceden ataları nasıl tapıyorsa onlar da tıpkı o çeşit tapıyorlar ve biz de onların nasibini eksiksiz olarak vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 110, 'Andolsun ki biz Musa''ya da kitap vermiştik de onda ihtilafa düşmüşlerdi; Rabbinin taktir ettiği vaadi olmasaydı çoktan aralarında hükmedilir, iş bitmiş olurdu ve onlar, gerçekten de bu hususta şiddetli bir şüphe ve tereddüd içinde kalmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 111, 'Ve şüphe yok ki Rabbin, onların yaptıkları şeylere tam bir karşılık verecektir, şüphe yok ki o, ne yapıyorlarsa hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 112, 'Artık sen, sana nasıl emredildiyse öylece dosdoğru hareket et ve seninle beraber bulunan ve tövbe etmiş olanlar da dosdoğru hareket etsinler ve taşkınlıkta bulunmayın, çünkü şüphe yok ki o, ne yapıyorsanız hepsini de görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 113, 'Ve zulmedenlere meyletmeyin, sonra ateşle azaba uğrarsınız ve Allah''tan başka bir dostunuz yoktur, sonra yardım da görmezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 114, 'Ve gündüzün başlangıcıyla son kısmında ve gecenin ilk çağlarında namaz kıl; şüphe yok ki güzel işler, kötülükleri giderir. İşte bu, iyi düşünenlere bir öğüttür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 115, 'Ve sabret, çünkü Allah, gerçekten de iyilik edenlerin ecrini zayi etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 116, 'Sizden önceki çağlarda, halkı, yeryüzünde bozgunculuktan vazgeçirmeye çalışan idrak ve ibadet ehli bir bölük halk bulunsaydı ne olurdu; halbuki içlerinden kurtardıklarımız pek azdı ve zulmedenler, yalnız kendilerine verilmiş olan devlete uydular ve suçlu oldular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 117, 'Rabbin, ahalisi, birbirini ıslah edip duran şehirleri zulümle helak etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 118, 'Rabbin dileseydi insanları bir tek ümmet haline getirirdi, fakat onlar, aykırılığa düşmekten bir türlü kurtulamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 119, 'Ancak Rabbinin merhamet ettiği kimseler müstesna ve zaten de bunun için halketmiştir onları ve Rabbinin sözü de tamamıyla yerine gelmiştir: Andolsun ki cehennemi, cinlerin ve insanların bir kısmıyla dolduracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 120, 'Peygamberlere ait haberlerin hepsinden, gönlünü yatıştıracak olanlarını, sana hikaye ediyoruz ve bu kıssalarda, sana gerçek haberler, inananlara da öğüt ve ibret var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 121, 'İnanmayanlara de ki: Gücünüzün yettiğini yapın, şüphe yok ki biz de yapmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 122, 'Ve bekleyin, şüphe yok ki biz de beklemedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (11, 123, 'Ve göklerle yeryüzünde gaibe ait olan, bilinmeyen her şey, Allah''ındır ve bütün işler, dönüp ona varır, artık ona kulluk et ve ona dayan. Rabbin, yaptığınız şeylerden gafil değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 1, 'Elif lam ra. Bunlar, her şeyi apaçık bildiren kitabın ayetleridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 2, 'Onu, akıl edesiniz diye Arapça olarak Kur''an''da da indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 3, 'Sana bu Kur''an''ı vahyederek kıssaların en güzelini hikaye edeceğiz ve bundan önce sen elbette onu bilmeyenlerdendin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 4, 'Bir zaman Yusuf, babasına babacığım demişti, ben onbir yıldızla güneşi ve ayı gördüm, bir de baktım ki onlar, bana secde ediyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 5, 'Babası, oğulcağızım demişti, rüyanı kardeşlerine söyleme, sana bir düzen kurarlar sonra. Şüphe yok ki Şeytan, insanlara apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 6, 'Böylece Rabbin, seni seçecek ve rüyalara ait tabirleri öğretecek sana. Ve bundan önceki ataların İbrahim''e ve İshak''a nasıl nimetlerini tam olarak ihsan ettiyse sana ve Yakup soyuna da nimetlerini tam olarak ihsan edecek. Şüphe yok ki Rabbin, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 7, 'Andolsun ki Yusuf''la kardeşlerine ait vakalarda soranlar için nice ibretler var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 8, 'Hani onlar, Yusuf''la kardeşi demişlerdi, babamıza bizden fazla sevgili ve bizse birbirini tutan ve daha kuvvetli bulunan bir topluluğuz. Şüphe yok ki babamız, yanlış bir yol tutmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 9, 'Öldürün Yusuf''u, yahut da öyle bir yere atın ki babanız, artık onu göremesin, ondan sonra tövbe eder, düzgün bir topluluk olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 10, 'İçlerinden biri Yusuf''u öldürmeyin demişti, mutlaka bir şey yapacaksınız bir kuyuya atın bari de gelip geçenlerden onu bulup alan olsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 11, 'Onlar, baba demişlerdi, ne diye Yusuf''u emniyet etmiyorsun bize ve biz, hiç şüphe yok ki ona öğütler vermedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 12, 'Yarın onu bizimle yolla da bolbol yesin, içsin, oynasın ve biz onu mutlaka koruruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 13, 'Yakup, onu götürür, giderseniz kederlenirim ben ve korkarım ki siz, ondan gaflet edersiniz de gelip kurt yer onu demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 14, 'Biz demişlerdi, güçlü kuvvetli bir toplulukken gelip onu kurt yerse artık şüphe yok ki ziyankarlardan oluruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 15, 'Sonucu onu götürüp kuyuya atmaya hep beraber karar verdikleri zaman ona, andolsun ki farkında bile olmadıkları bir anda şu yaptıklarını haber vereceksin onlara diye vahyetmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 16, 'Akşam olunca ağlayaağlaya babalarına gelmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 17, 'Baba demişlerdi, biz yarışa gitmiştik, Yusuf''u da elbiselerimizin başında bırakmıştık, bir kurt gelip yemiş onu, fakat biz doğru söylesek de sen inanmazsın bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 18, 'Gömleğini de kana bulayıp yalanlarını ispat için getirmişlerdi. Yakup, olsaolsa demişti, nefisleriniz, yaptığınız işi size güzel, o güç işi kolay göstermiş; fakat ben, pek güzel dayanır, sabrederim ve anlattıklarınıza karşı da ancak Allah''tan yardımdilerim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 19, 'Derken bir yolcu kafilesi geçerken kuyudan su almak için birini yollamışlardı, o da kovasını kuyuya salınca müjde diye bağırmıştı, burada bir genç var ve onu çıkarıp bir ticaret malı gibi gizlemişlerdi; Allah''sa onların yaptıklarını biliyordu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 20, 'Ve onu değersiz bir kar, sayılı birkaç kuruş karşılığında satmışlardı ve onu satarlarken paraya pek o kadar rağbetleri de yoktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 21, 'Mısır halkından olup onu satın alan kişi, karısına, buna izzetle muamele et, umarım ki bize faydası dokunur, yahut da onu evlat ediniriz demişti. İşte Yusuf''u, Mısır''da böylece yerleştirdik de ona rüya yormasını öğrettik ve Allah, yaptığı işte üstündür daima, fakat insanların çoğu, bunu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 22, 'Ergenlik çağına girince ona hükmetme kabiliyeti ve bilgi verdik ve işte iyilik edenleri böyle mükafatlandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 23, 'Evinde bulunduğu kadın, ondan murat almak istedi de kapıları sımsıkı kapattı ve hadi dedi, beri gel. O, Allah''a sığınırım dedi; şüphe yok ki kocan, benim efendimdir ve şüphe yok ki zulmedenler, asla kurtulamaz, muradına eremez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 24, 'Andolsun ki kadın, ondan murat almayı iyice kurmuştu, eğer Rabbinin burhanını görmeseydi Yusuf da onun hakkında niyetini bozardı, işte biz ondan çirkin ve kötü şeyleri böylece giderdik, çünkü şüphe yok ki o, gönlünü bize bağlamış kullarımızdandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 25, 'Derken ikisi de kapıya doğru koştu. Kadın, onun gömleğini arkadan boydan boya yırtmıştı ki tam bu sırada kapıdan çıkarlarken kadının kocasına kapı önünde rastladılar. Kadın, karına kötülük etmek isteyenin cezası, zindana atılmaktan, yahut elemli bir azaba uğratılmaktan başka ne olabilir ki dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 26, 'Yusuf, o benden murat almak istedi dedi ve kadının yakınlarından biri tanıklık ederek dedi ki: Eğer Yusuf''un gömleği, ön taraftan yırtılmışsa kadın doğrudur, o yalancılardandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 27, 'Yok, eğer gömleği arka taraftan yırtılmışsa kadın yalan söylemektedir, o doğruculardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 28, 'Kocası, Yusuf''un gömleğini arka taraftan yırtılmış görünce hiç şüphe yok ki dedi bu, sizin düzenlerinizden. Gerçekten de ey kadınlar, düzenleriniz pek büyüktür sizin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 29, 'Ey Yusuf, sen de bu meseleyi bırak artık ve sen ey kadın, suçundan tövbe et, şüphe yok ki sen, hata işleyenlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 30, 'Şehirdeki kadınlar, azizin karısı, kölesinden murat almak istemiş, sevgi, bütün kalbini kaplamış, görüyoruz ki o, apaçık bir sapıklıkta dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 31, 'Dedikodularını duyunca davet etti onları ve dayanacak şeyler getirdi, sofra çıkardı ve her birine birer bıçak verdi ve Yusuf''a, görün şunlara, gel dedi. Kadınlar, onu görünce şaşırdılar, meyve yerine ellerini doğradılar ve tenzih ederiz Allah''ı dediler, haşa bu insan değil, olsaolsa büyük ve şerefli bir melek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 32, 'O da, işte dedi, hakkında beni kınayıp durduğunuz bu zat. Ondan murat almak istedim de o namusunu korudu, kötülük etmedi. Fakat yemin ederim ki emredileni yapmazsa zindana attıracağım onu ve herhalde horluğa uğrayanlara katılacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 33, 'Yusuf, Rabbim dedi, zindan, bunların davet ettikleri şeyden daha hayırlı bence. Bunların düzenlerini benden uzaklaştırmazsan belki onlara meyleder de bilgisizlerden olurum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 34, 'Rabbi de artık onun duasını kabul etti ve düzenlerini defetti ondan; şüphe yok ki o, duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 35, 'Sonra onun suçsuzluğuna dair bunca deliller görmekle beraber gene de bir müddet hapsedilmesini muvafık bir tedbir saydılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 36, 'Ve onunla beraber zindana iki de delikanlı girmişti. Bunların biri, ben dedi, rüyamda gördüm, şarap yapmak için üzüm sıkıyormuşum ve öbürü ben de dedi, rüyamda gördüm, başımda ekmek var, kuşlar gelip tepemdeki ekmeği yiyormuş. Bunları yor bize, çünkü biz seni görüyoruz ki iyilik edenlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 37, 'Yusuf, size dedi, rızıklanacağınız hiçbir yemek gelmiyor ki ben onu, önceden haber vermiş olmayayım; bu da Rabbimin bana öğrettiklerinden. Şüphe yok ki ben, Allah''a inanmayan ve ahireti inkar eden topluluğun dinini terkettim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 38, 'Ve atalarım İbrahim''in, İshak''ın ve Yakup''un dinine uydum. Hiçbir şeyi Allah''a eş tutmamıza imkan yok, bu da bize ve insanlara, Allah''ın bir lütfü, fakat insanların çoğu şükretmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 39, 'Ey benim iki zindan arkadaşım, birbirine aykırı Rabler mi daha hayırlı, yoksa bir ve her şeye üstün olan Allah mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 40, 'Sizin, ondan başka taptığınız şeyler, ancak sizin ve atalarınızın uydurup adlandırdığı şeylerden ibaret, Allah, onların tanrılığına dair hiçbir delil indirmemiştir; hüküm ancak Allah''ındır. Ancak ona kulluk etmenizi emretmiştir, başkasına değil. İşte dosdoğru din de budur, fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 41, 'Ey benim iki zindan arkadaşım, sizin biriniz, tekrar efendisine içki sunacak, fakat öbürü asılacak ve kuşlar, başını didip yiyecekler. İşte esasını anlamak istediğiniz şey böylece taktir edilmiş, bitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 42, 'Ve onlardan, kurtulacağını sandığına beni dedi, efendine anlat. Fakat Şeytan, efendisine bunu anlatmayı unutturdu ona ve bu yüzden daha nice yıllar zindanda kaldı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 43, 'Padişah dedi ki: Rüyamda gördüm, yedi zayıf inek, yedi semiz ineği yiyordu; bir de yedi terütaze yeşil başakla yedi tane de kurumuş başak gördüm. Ey ileri gelenler, rüya yormayı biliyorsanız bu rüyamı yorun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 44, 'Onlar, karmakarışık ve aslı olmayan bir düş; biz bu çeşit boş rüyaları yormayı bilmeyiz dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 45, 'O iki adamdan biri olan ve zindandan kurtulan adam, nice zaman sonra hatırlayıp ben dedi bu rüyayı yorarım, beni hemen gönderin o zata.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 46, 'Ey Yusuf dedi, ey çok gerçek, yedi semiz ineği yiyen yedi zayıf ineği, yedi yeşil ve bir de yedi kuru başağı yor bize de belki insanlara varır anlatırım, onlar da belki bilirler, anlarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 47, 'Yusuf dedi ki: Yedi yıl, adet olduğu gibi ekip biçin, hasılatın pek azını yiyin, geri kalanını saklayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 48, 'Bu yedi yıldan sonra yedi yıl kurak olacak, bu yıllarda da önceden biriktirdiğinizi, az bir miktarın saklamak şartıyla yiyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 49, 'Bundan sonra da bir yıl gelecek ki halk, yağmura kavuşacak, o yıl bol bol yağmurlar yağacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 50, 'Padişah, o zatı getirin bana dedi. Elçi gelince dön efendine de dedi, ellerini doğrayan kadınların neydi zorları, bir sor ona; şüphe yok ki Rabbim, onların düzenini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 51, 'Padişah, o kadınlara, Yusuf''tan murat almak istediğiniz zaman ne haldeydiniz dedi. Allah için dediler, onun bir kötülüğünü görmedik, bilmedik. Azizin karısı da şimdi işte dedi, hak çıktı meydana, ondan murat almak isteyen bendim ancak ve o, hiç şüphe yok ki gerçeklerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 52, 'Yusuf, bu da dedi, padişahın, o yokken ona bir hainlik yapmadığımı bilmesi içindi ve şüphe yok ki Allah, hainlerin düzenlerini başarıyla sonuçlandırmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 53, 'Ve ben kendimi, hiç kötülükte bulunmam diye tamamıyla temize çıkaramam, ancak Rabbim acırsa kötülük yapmam. Şüphe yok ki Rabbim, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 54, 'Padişah, onu tapıma getirin de dedi, kendime öz yakınım edineyim onu. Yusuf''la konuşunca da gerçekten de dedi, bugün sen büyük bir mevki sahibisin, emin bir adamsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 55, 'Yusuf, beni ülkenin hazinelerine memur et, şüphe yok ki ben onları iyi korurum ve ne yapacağımı bilirim dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 56, 'İşte Yusuf''a Mısır''da böylece bir mevki verdik, nereyi isterse orada, dilediği gibi konaklardı. Rahmetimizi, kime dilersek ona nasib ederiz ve iyilikte bulunanların ecrini zayi etmeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 57, 'Âhiret mükafatıysa inanan ve çekinenlere daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 58, 'Yusuf''un kardeşleri gelip huzuruna girdiler; Yusuf, onları tanıdı, fakat onlar, Yusuf''u tanıyamadılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 59, 'Yüklerini hazırlayınca onlara, aynı babadan olma bir kardeşinizi getirin bana dedi, görmüyor musunuz, ben ölçeği tamam ölçmedeyim ve konuk ağırlayanların da en hayırlısıyım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 60, 'Onunla beraber gelmezseniz size benden bir ölçek bir şey bile yok, yaklaşmayın artık buraya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 61, 'Babasından izin almaya çalışırız ve herhalde bu işi başarırız dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 62, 'Kullarına da, aldıkları zahireler içinde bulup gördükleri ikramı anlasınlar da tekrar gelsinler diye zahire bedellerini yüklerinin içine koyun diye emretti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 63, 'Dönüp babalarına varınca baba dediler, bize artık zahire verilmeyecek, kardeşimizi de bizimle gönder de zahire alalım ve şüphe yok ki biz, onu iyice koruruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 64, 'Yakup, bundan önce kardeşini ne kadar emniyet ettiysem bunu da o kadar emniyet ederim size; şüphe yok ki Allah, koruyanların hayırlısıdır ve o, merhametlilerin en merhametlisidir dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 65, 'Yüklerini açıp aldıkları zahireye karşılık verdikleri bedelleri de yüklerinin içinde bulunca baba dediler, daha ne istiyoruz? İşte zahire bedellerimiz de bize geri verilmiş. Onlarla tekrar ailemize zahire getiririz, kardeşimizi koruruz, daha fazla zahire alırız. Zaten bu seferki bize yetmeyecek kadar da az.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 66, 'Etrafınız kuşatılmadıkça dedi, onu mutlaka geri getireceğinize dair Allah adına bir söz vermezseniz sizinle imkanı yok göndermem onu. Onlar, söz verince de bu dediklerimize Allah tanık olsun dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 67, 'Ve oğullarım dedi, hepiniz aynı kapıdan girmeyin, ayrıayrı kapılardan girin. Fakat gene de Allah''ın takdir ettiği hiçbir şeyi gideremem sizden; hüküm, ancak Allah''ındır. Ona dayandım ve dayananlar da ancak ona dayanmalı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 68, 'Babalarının emrettiği gibi Mısır''a girdiler ama bu, Allah''ın takdirinden hiçbir şeyi gideremedi, ancak Yakup''un dileği yerine gelmiş oldu ve şüphe yok ki Yakup, kendisine öğretmiş olduğumuzdan dolayı bir bilgiye sahipti, fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 69, 'Yusuf''un huzuruna girdikleri zaman Yusuf, kardeşini yanına aldı da ben senin kardeşinim dedi, onların yaptıkları hareketten kederlenme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 70, 'Onların yüklerini hazırlayınca şerbet içtiği bardağı kardeşinin yükünün içine koydurdu, sonra da ey kafile, siz hırsızsınız diye bir münadiye nida ettirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 71, 'Yakup''un oğulları, onlara dönerek ne kaybettiniz dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 72, 'Padişahın şerbet bardağını kaybettik, bulup getirene bir deve yükü zahire verilecek, ben de kefilim buna dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 73, 'Onlar, andolsun Allah''a ki dediler, biz yeryüzünde bir bozgunculuk, bir kötülük yapmak için gelmedik buraya, bunu siz de biliyorsunuz ve biz hırsız değiliz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 74, 'Onlara, yalan söylüyorsanız hangi cezaya razısınız dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 75, 'Kimin yükünde bulunursa dediler, o, malını çaldığı adama köle olur. Biz zulmedenleri böyle cezalandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 76, 'Yusuf, kardeşinin yükünden önce onların yüklerini araştırmaya başladı, sonra da yitiğini kardeşinin yükünden çıkardı. Yusuf''a, böyle bir düzende bulunmasını emrettik, yoksa Allah dilemedikçe padişahın dinince kardeşini esir edemezdi; dilediğimizin derecelerini yüceltiriz ve her bilgi sahibinin üstünde bir bilen var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 77, 'Bu dediler, hırsızlık ettiyse daha önce bir kardeşi de hırsızlık etmişti. Yusuf, bunu gizledi onlardan ve kendi kendine dedi ki: Sizin durumunuz daha kötü, anlattığınız şeyi Allah daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 78, 'Ey aziz dediler, onun ihtiyar bir babası var, onun yerine bizim birimizi al; seni görüyoruz ki gerçekten de iyilik edenlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 79, 'Allah''a sığınırım dedi, bir başkasını tutup köle yapmaktan; ancak malımızı kimde bulduysak onu köle yaparız biz; yoksa şüphesiz zulmedenlerden oluruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 80, 'Ondan tamamıyla ümitlerini kesince gizlice konuşarak çekildiler. Büyükleri, bilmiyor musunuz dedi, babanız Allah adına sizden kuvvetli bir söz aldı, daha önce de Yusuf hakkındaki vazifenizde ne çeşit kusur ettiniz? Babam izin verinceye dek, yahut Allah, benim hakkımda bir hüküm yürütünceye kadar ben buradan ayrılmayacağım ve o, hükmedenlerin en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 81, 'Siz babanıza dönün de baba deyin, oğlun hırsızlık etti ve biz, ancak bildiğimizi söyleyerek tanıklıkta bulunduk, gizli olanıysa zaten bilemeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 82, 'İçinde bulunduğumuz şehir halkına da sor, beraber geldiğimiz kervan halkına da ve şüphe yok ki doğru söylemekteyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 83, 'Yakup, olsaolsa dedi, nefisleriniz, yaptığınız işi size güzel, o güç işi kolay göstermiş; fakat ben, pek güzel dayanır, sabrederim. Umarım ki Allah hepsine birden kavuşturur beni, hiç şüphe yok ki o, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 84, 'Ve onlardan yüz çevirdi de ey beni tükenmez, sonu gelmez kederlere salan Yusuf demeye başladı ve kederden gözleri ağardı ve artık derdini yutmaktaydı o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 85, 'Allah''a andolsun dediler, hala Yusuf''u anıp durmadasın, sonunda hastalanıp eriyecek, yahut da helak olup gideceksin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 86, 'Ben dedi, taşan derdimi, kederimi ancak Allah''a arzetmedeyim ve Allah tarafından sizin bilmediğiniz şeyleri biliyorum ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 87, 'Oğullarım dedi, gidin, Yusuf''la kardeşinden bir haber getirin ve Allah''ın rahmetinden ümit kesmeyin; çünkü kafir olan topluluktan başka kimsecikler, Allah''ın rahmetinden ümit kesmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 88, 'Huzuruna girdikleri zaman ey aziz dediler, biz de darda kaldık, açlığa düştük, ailemiz de ve pek değersiz bir karşılıkla geldik, bize zahire ver ve tasadduk et bize, şüphe yok ki Allah lutfedenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 89, 'Dedi ki: Bilgisiz olduğunuz çağlarda Yusuf''a ve kardeşine neler yaptığınızı biliyor musunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 90, 'Yoksa dediler, sen Yusuf musun? Ben dedi Yusuf''um, bu da kardeşim. Allah lutfetti bize. Şüphe yok ki kim çekinir ve sabrederse mutlaka Allah, bu çeşit iyilik edenlerin ecrini zayi etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 91, 'Allah''a andolsun ki dediler, Allah seni gerçekten de bizden üstün etmiş ve doğrucası biz hata etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 92, 'Bugün sizi ne ayıplama var dedi, ne kınama; Allah yarlıgasın sizi ve o, merhametlilerin en merhametlisidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 93, 'Şu gömleğimi alın da götürün, babamın gözlerine sürün, iyileşir, görmeye başlar. Bütün ailenizle gelin buraya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 94, 'Kervan, Mısır''dan ayrılınca babaları, bana bunak demeseniz bari, Yusuf''un kokusunu duyuyorum dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 95, 'Andolsun Allah''a ki dediler, sen hala eski yanlışında ısrar etmedesin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 96, 'Müjdeci gelip de gömleği gözlerine sürünce Yakup''un gözleri açıldı, görmeye başladı. Demedim mi size, şüphe yok ki Allah bana bildirmiştir, sizin bilmediğiniz şeyleri bilirim ben dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 97, 'Babamız dediler, suçlarımızın yarlıganmasını dile, gerçekten de yanlış bir harekette bulunduk biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 98, 'Rabbimden yarlıganmanızı dileyeceğim dedi, şüphe yok ki o, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 99, 'Yusuf''un huzuruna girdikleri zaman o, anasına, babasına sarıldı, kucakladı onları ve Allah''ın izniyle dedi, emin olarak girin Mısır''a', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 100, 'Anasıyla babasını tahta çıkartıp oturttu ve hepsi de ona karşı secdeye kapandılar. Babacığım dedi, evvelce gördüğüm rüya, bu işte, Rabbim onu gerçekleştirdi ve beni zindandan çıkararak lutfetti bana; Şeytan, benimle kardeşlerimin arasını bozduktan sonra da sizi çölden getirdi. Şüphe yok ki Rabbim, dilediği şeyi tedbir edip lütfüyle meydana getirir; şüphe yok ki o her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 101, 'Rabbim, sen bana saltanat ihsan ettin ve rüya yormasını bellettin. Ey gökleri ve yeryüzünü yaratan, sensin benim dostum, yardımcım dünyada da, ahirette de, beni Müslüman olarak öldür ve düzgün, iyi kullarına kat beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 102, 'İşte bu, gaibe ait haberlerdendir ki sana vahyetmedeyiz. Düzene girişerek yapacakları işi kararlaştırdıkları zaman yanlarında değildin ya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 103, 'Sen ne kadar üstlerine düşersen düş, gene de insanların çoğu imana gelmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 104, 'Buna karşılık bir ücret de istemiyorsun, bu, alemlere öğütten başka bir şey değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 105, 'Göklerde ve yeryüzünde nice deliller vardır ki onları görmezler ve yüz çevirip giderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 106, 'Çoğu inanmaz da ona şirk koşar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 107, 'Yoksa onlar, herkesi gelip kaplayacak Allah azabından, yahut hiç haberleri yokken ansızın gelip çatacak kıyametten emin mi oluyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 108, 'De ki: İşte bu, benim yolum; ben de can gözüm açık olarak sizi Allah''a çağırmadayım, bana uyanlar da o çeşit çağırmada ve Allah''ı tenzih ederim ve ben müşriklerden değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 109, 'Senden önce gönderdiğimiz kimseler de şehirlerin ahalisinden birtakım adamlardı ancak. Yeryüzünde hiç mi gezmezler de kendilerinden öncekilerin sonucu ne olmuş, görmezler? Ve ahiret yurdu, çekinenler için elbette daha hayırlıdır, hala mı akıl etmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 110, 'Sonucu peygamberler, tamamıyla ümitlerini kesip tamamıyla inkar edileceklerini sandıkları zaman yardımımız gelmiştir de dilediğimizi kurtarmışızdır. Fakat azabımız, suçlu topluluktan hiçbir suretle geriye çevrilemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (12, 111, 'Andolsun ki onların hikayelerinde akıl ve dirayet sahiplerine ibretler var. Uydurulmuş bir söz değil, önceki kitapları gerçekleyen ve her şeyi bildiren bir söz bu ve inanan topluluğa da hidayet ve rahmet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 1, 'Elif lam mim ra. Bunlardır kitabın ayetleri. Sana, Rabbinden indirilen gerçektir, fakat insanların çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 2, 'Öyle bir Allah''tır ki görmekte olduğunuz gökleri direksiz yüceltmiştir de sonra arşa hakim ve mutasarrıf olmuştur ve güneşi ve ayı ram etmiştir, hepsi de muayyen bir zamana dek yürürgider. Rabbinize kavuşacağınızı iyice anlamanız için işleri tedbir ve tasarruf edip yapan odur, delilleri bildirip açıklayan o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 3, 'Öyle bir mabuttur ki yeryüzünü enine, boyuna uzatıp döşemiş, orada yerleşmiş dağlarla ırmaklar yaratmış, gene orada her çeşit meyveyi çifterçifter halketmiştir; gündüzü de geceyle bürür. Şüphe yok ki bunlarda düşünen topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 4, 'Ve yeryüzünde birbirine komşu bölgeler, üzüm bağları, ekinler, bir kökten yetişmiş hurma ağaçlarıyla ayrı ayrı köklerden yetişmiş hurmalıklar var ki hepsi de bir suyla sulanmada, fakat lezzet bakımından bir kısmını, öbürlerinden üstün etmedeyiz. Şüphe yok ki akıl edenlere, bunlarda da deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 5, 'Şaşıyorsan asıl şaşılacak şey, toprak olduktan sonra yeniden mi yaratılacağız diyenlerin sözü. Onlar, öyle kişilerdir ki Rablerine kafir olmuşlardır. Onlar, öyle kişilerdir ki boyunlarında demir zincirler var ve onlar, cehennem ehlidir; onlar, orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 6, 'Senden, iyilikten önce bir kötülük gelmesini, hem de bunun çabucak olmasını isterler, onların çağlarından önceki çağlarda nice azaplar gelip çatmıştır ve şüphe yok ki Rabbin, insanların zulmüne rağmen yarlıgamıya, suçlarını örtme sıfatına sahiptir vegene şüphe yok ki Rabbinin azabı da pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 7, 'Kafir olanlar derler ki: Rabbinden ona bir mucize verilseydi ya. Şüphesiz ki sen, ancak korkutucusun ve her topluluğa hidayet verensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 8, 'Allah, her dişinin, neye gebe kalıp ne doğuracağını ve ana karnında dölün zamanına göre orada ne kadar eksik, ne kadar fazla kalacağını bilir ve onun katında her şeyin sayılı bir zamanı, ölçülü bir müddeti var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 9, 'Gizliyi de bilen, açıkta olanı da bilen çok büyük ve yüce bir Tanrıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 10, 'Sözünü gizleyeniniz de birdir onca, açıkça söyleyeniniz de, geceleyin saklanıp gizlenen de, gündüzün yoluna giden de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 11, 'Herkesin önünde, ardında, birbiri ardınca gelip giden melekler var, onu, Allah''ın emriyle koruyup gözetirler. Şüphe yok ki bir topluluk, ahlakını değiştirmedikçe Allah o topluluğu değiştirmez. Allah, bir topluluğun kötülüğünü dilerse o kötülüğü geriye atmaya imkan yoktur ve onlara, ondan başka bir yardımcı da bulunamaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 12, 'Öyle bir Tanrıdır ki sizi korkutan ve umduran şimşeği o çaktırır ve yağmurla dolu ağır bulutları o meydana getirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 13, 'Gök gürültüsü, hamdederek tenzih eder onu, melekler de korkularından tenzih ederler ve yıldırımları yollar da dilediğine isabet ettirir ve hala da onlar, Allah hakkında çekişip dururlar ve onun birdenbire gelen azabı pek kuvvetlidir, pek çetin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 14, 'Gerçek dua, ancak onadır. Ondan başkalarına dua edenlerin duaları kabul edilmez. Bu çeşit adam, ağzına gelsin diye suya ellerini uzatmış, bekleyip duran adama benzer, su ağzına gelmez onun ve kafirlerin duası, sapıklıkta kalmadan başka bir şey değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 15, 'Göklerde ve yeryüzünde ne varsa, sabah ve akşam, isteristemez, kendileri de, gölgeleri de Allah''a secde eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 16, 'De ki: Göklerin ve yeryüzünün Rabbi kim? De ki: Allah. De ki: Onu bırakıp da kendilerine bile bir faydaları, bir zararları dokunamayan tanrılar mı edindiniz? De ki: Bir olur mu körle gören? Yahut bir olur mu karanlıklarla ışık? Yoksa mabutları da yaratıyor mu ki şüphelenip onları Allah''a eş koştular? De ki: Her şeyi yaratan Allah''tır ve o birdir, acze düşmez, her şeyden üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 17, 'Gökten yağmur yağdırır da vadilerde alabildikleri kadar seller, ırmaklar olur, çağlayıp akar, akarken de üste çıkan köpükleri sürükler götürür. Ziynet eşyası, yahut faydalanmak için kullanılan araçları yaparken ateşte eritilen şeylerde de buna benzerbir köpük, bir posa meydana gelir. İşte Allah gerçekle boş şeyi bu çeşit bir örnekle anlatır. Köpük, dağılır gider, halka fayda verecek şeyse yerinde kalır. İşte Allah, böyle örnekler getirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 18, 'Rablerinin davetine icabet edenlere güzel bir mükafat var; fakat icabet etmeyenlere gelince: O çeşit adamlar, yeryüzünde ne varsa hepsine sahip olsalar ve bir misli daha malları olsa da kurtulmak için hepsini feda etseler gene onlar için kötü bir soru var, yurtları cehennemdir ve orası ne de kötü yataktır ya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 19, 'Bunların, sana bir gerçek olarak Rabbinden indirildiğini bilen kişi, o kör adama benzer mi? Şüphe yok ki ancak aklı, anlayışı, olanlar, düşünüp ibret alırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 20, 'Onlardır Allah''la ahdettikleri şeye vefa edenler ve verdikleri sözden caymayanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 21, 'Onlardır Allah neyi ulaştırmayı emrettiyse ulaştıranlar ve Rablerinden ürkerler ve kötü hesaptan korkarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 22, 'Onlar, Rablerinin rızasını dileyerek sabrederler, namaz kılarlar, kendilerini rızıklandırdığımız şeyden, gizli ve açık harcarlar ve kötülüğü iyilikle giderirler. Öyle kişilerdir onlar ki onlarındır güzel sonuç.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 23, 'Ebedi Adn cennetleri. Oraya girerler atalarından, eşlerinden, soylarından temiz ve düzgün kişilerle ve melekler, her kapıdan onların tapısına girerler de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 24, 'Esenlik size derler, sabrettiğinizden dolayı; gerçekten de dünya yurdunun bu sonucu, ne de güzeldir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 25, 'Allah''ın ahdini, ona söz verdikten sonra bozanlara ve Allah''ın ulaştırmayı emrettiği şeyi kesenlere ve yeryüzünde bozgunculuk edenlere gelince: Öyle kişilerdir onlar ki lanet onlara ve onlarındır kötü sonuç.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 26, 'Allah, dilediğinin rızkını genişletir ve daraltır ve onlar, dünya yaşayışıyla sevinip övünürler, halbuki dünya yaşayışı, ahirete nispetle değersiz, müddeti az ve geçici bir şeyden ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 27, 'Kafir olanlar derler ki: Ona Rabbinden bir mucize indirilseydi ya. De ki: Şüphe yok ki Allah, dilediğini sapıklığa ve gönlüyle ona, onun tapısına dönenleriyse doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 28, 'İnananlar, öyle kişilerdir ki Allah''ı anmakla yatışır, kuvvetlenir gönülleri. İyice bilin ki gönüller, Allah''ı anmakla yatışır, kuvvet bulur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 29, 'İnananlara ve iyi işlerde bulunanlara gelince: Kutluluk da onlara, dönüp varılacak güzel yurt da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 30, 'İşte böylece seni de, sana vahyettiğimizi onlara okuman için bir ümmete gönderdik ki onlardan önce nice ümmetler gelip geçmiştir; onlar, rahmanı inkar ettiler; de ki: O, benim Rabbimdir, yoktur ondan başka tapacak. Ona dayandım, sonucu varıp gideceğim yer de onun tapısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 31, 'Kur''an''la dağlar yürütülse, yahut yeryüzü parçalansa, yahut da ölü konuşsa. Fakat bütün işler, ancak Allah''ın. İnananlar anlamazlar mı ki Allah dileseydi bütün insanları doğru yola sevk ederdi. Kafir olanlarsa, yaptıklarına karşılık, Allah''ın vaadi yerine gelinceye dek, bir belaya uğrayıp dururlar, yahut da yurtlarına yakın bir yere iner bu bela. Şüphe yok ki Allah, vaadinden dönmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 32, 'Andolsun ki senden önceki peygamberlerle de alay edildi de kafirlere mühlet verdim, sonra da onları helak ediverdim. Nasıl bu azap?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 33, 'Herkesin yaptığı ve elde ettiği şeyi bilip görene ve karşılığını verene benzer mi onlar, tutup Allah''a eş tanıyorlar onları. De ki: Bir ad takın onlara. Yoksa yeryüzünde bilmediği birşeyi mi haber veriyorsunuz ona, yahut da geçici bir boş laf mı ediyorsunuz? Kafir olanlara düzenleri hoş ve sevimli görünmede ancak ve yoldan çıkarılmadalar ve Allah, kimi doğru yoldan saptırırsa onu doğru yola sevkedecek yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 34, 'Onlara dünya hayatında azap var, ahiret azabıysa daha da ağırdır ve onları Allah''tan koruyacak kimse de yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 35, 'Çekinenlere vaat edilen cennetin örneği şu: Kıyılarından ırmaklar akar. Yemişleri ve gölgesi daimidir. Çekinenlerin sonucu budur, kafirlerin sonucuysa ateştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 36, 'Kendilerine kitap verdiğimiz kimseler, sana indirilen şeyden dolayı sevinirler ve bölükler içinde onun bir kısmını inkar edenler de var. De ki: Bana, Allah''a kulluk etmem ve ona şirk koşmamam emredildi. Ona davet etmedeyim, sonucu dönüp varacağım yerde onun tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 37, 'İşte böylece ona Arapça bir hükümdür indirdik. Sence bilindikten sonra tutar da onların dileklerine uyarsan Allah''a karşı ne bir dost bulunur sana, ne de seni ondan koruyacak biri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 38, 'Andolsun ki senden önce de peygamberler gönderdik, onlara eşler ve soysop verdik. Hiçbir peygamber yoktur ki Allah''ın izni olmadıkça bir mucizeyle gelsin. Her mukadder zaman, tespit edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 39, 'Allah, dilediğini bozar, dilediğini yazar ve kitabın aslı, esası, onun katındadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 40, 'Onlara vaat ettiğimiz şeylerin bir kısmını sana göstersek de sana düşen vazife, ancak tebliğdir, seni öldürsek de ve hesap, bize aittir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 41, 'Görmediler mi ki adeta onların yerlerine geliyor, etrafından yurtlarını eksiltip duruyoruz. Allah hükmeder, hükmünü bozacak yoktur ve o pek tez hesap görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 42, 'Onlardan öncekiler de düzenler kurdular, iş ve tedbir, tamamıyla onundur, herkesin ne kazanacağını da bilir. Kafirler, yakında bilirler, anlarlar, dünya yurdunun sonundaki hayır kimin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (13, 43, 'Kafirler, sen peygamber değilsin derler; de ki: Sizinle aramda tanık olarak Allah ve kitap bilgisine sahip olan yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 1, 'Elif lam ra. Bir kitaptır bu ki insanları karanlıklardan nura çıkarman, Rablerinin izniyle üstün ve gerçekten de hamde layık olan Tanrı yoluna götürmen için onu sana indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 2, 'Bir Allah''tır ki onundur göklerde ne varsa ve yeryüzünde ne varsa. Vay kafirlere çetin azaptan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 3, 'Onlar dünya yaşayışını ahiretten üstün tutup severler, halkı Allah yolundan menederler ve o yolu eğriltmek isterler. Onlardır pek uzak bir sapıklığa dalanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 4, 'Onlara iyice anlatabilmesi için kendi kavminin dilinden başka bir dille hiçbir peygamber göndermedik. Gerçekten de Allah, dilediğini saptırır, dilediğini doğru yola sevk eder ve odur üstün ve hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 5, 'Andolsun ki Musa''yı, kavmini karanlıklardan nura çıkar ve onlara Allah''ın günlerini an diye delillerimizle gönderdik. Şüphe yok ki bunda, çok sabreden ve çok şükreden herkes için deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 6, 'An o zamanı ki Musa, kavmine Allah''ın size nimetlerini anın demişti; hani sizi kötü bir azapla azaplandıran, oğullarınızı kestirip kızlarınızı bırakan Firavun soyundan kurtarmıştı ve bunda Rabbinizden büyük bir sınama vardı size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 7, 'Hani Rabbiniz size, andolsun ki nimetlerime şükrederseniz arttırırım ve andolsun ki nankörlük ederseniz şüphe yok ki azabım pek çetindir diye hükmünü bildirmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 8, 'Ve Musa demişti ki: Siz de nankörlük etseniz, yeryüzünde kim varsa hepsi de nankörlük etse şüphe yok ki Allah, müstağnidir ve gerçekten de hamda layıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 9, 'Sizden önce gelip geçen Nuh, Âd ve Semud kavimleriyle onlardan sonra gelip geçen ve ancak Allah''ın bildiği kavimlere ait olan haberler gelmedi mi size? Onlara peygamberleri, apaçık delillerle gelmişti de onlar, elleriyle peygamberlerinin ağızlarını örtmüşler ve biz demişlerdi, sizinle gönderilenleri inkar ediyoruz ve gerçekten de bizi davet ettiğiniz şeyler hakkında şüphe ve tereddüt içindeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 10, 'Peygamberleri, Allah''tan şüphe edilir mi dediler, gökleri ve yeryüzünü yaratandır o; suçlarınızı örtmek ve muayyen vakte dek size mühlet vermek için çağırmada sizi. Siz de dediler, bizim gibi insansanız ancak; bizi atalarımızın taptıklarından vazgeçirmek istiyorsunuz, öyleyse apaçık bir delil gösterin bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 11, 'Peygamberleri, biz de dediler, sizin gibi insanız, fakat Allah, kullarından dilediğine lutfeder, ihsanda bulunur ve biz, Allah''ın izni olmadıkça size bir delil ve mucize gösteremeyiz ve inananlar, artık Allah''a dayanmalı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 12, 'Ve ne diye Allah''a dayanmayalım ki gerçekten de o sevketmiştir bizi doğru yola ve elbette bize ettiğiniz eziyetlere katlanacağız ve dayananlar, artık ancak Allah''a dayanmalı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 13, 'Kafir olanlar, peygamberlerine dediler ki: Ya sizi yurdumuzdan çıkarırız, yahut da bizim dinimize dönersiniz. Rableri, onlara vahyetti: Mutlaka zalimleri helak edeceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 14, 'Sonra da onlardan sonra sizi, yerlerine yerleştireceğiz. İşte bu, benim huzuruma gelmekten korkanlara ve azabımdan korkanlara ait bir şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 15, 'Peygamberler, fetih ve yardım istediler ve her inatçı cebbar, mahrum olup gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 16, 'Önünde de cehennem var, orada kanlı, irinli su içirilecek ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 17, 'Yudumyudum içmeye çalışacak, fakat bir türlü boğazından geçmeyecek; her taraftan ölüm gelecek ona, fakat ölmeyecek de ve ilerde daha da ağır bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 18, 'Rablerine kafir olanların örneği, bir küle benzer, kasırga estiği bir günde bu kül, yelle savrulur gider. Kazançlarından hiçbir şey elde edemezler, işte budur doğru yoldan çok uzak bir sapıklık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 19, 'Görmedin mi ki Allah, gökleri ve yeryüzünü hak ve gerçek olarak yarattı. Dilerse sizi helak eder ve yerinize yeni bir halk getirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 20, 'Ve bu da Allah''a güç bir şey değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 21, 'Hepsi de toplanıp Allah''ın tapısına çıkar; zayıflar, ululanan büyüklere şüphe yok ki derler, biz size uymuştuk, Allah''ın azabından bir kısmını olsun bizden defedebilir misiniz? Onlar da Allah bizi doğru yola sevketseydi biz de size doğru yolu gösterirdik derler, artık ağlayıp sızlasak da bir bizim için, sabredip katlansak da; sığınacak hiçbir yerimiz yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 22, 'İş olup bitince Şeytan der ki: Şüphe yok ki Allah, gerçek olarak vaitte bulundu size. Ben de size vaat ettim ama vaadimde durmadım ve zaten de size karşı bir gücümkuvvetim yoktu, ancak sizi davet ettim, siz de icabet ettiniz bana; beni kınamayın, kendinizi kınayın. Artık ne benim size bir yardımım dokunabilir, ne sizin bana bir yardımınız dokunabilir. Zaten daha önceden de beni ona eş tutmanızı tanımamıştım ben. Şüphe yok ki zulmedenlere elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 23, 'İnananlar ve iyi iş işleyenler, kıyılarından ırmaklar akan cennetlere alınırlar, orada, Rablerinin izniyle ebedi kalırlar. Orada birbirlerine iltifatları, esenlik size sözüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 24, 'Görmedin mi Allah nasıl örnek getirmede, temiz söz, tertemiz bir ağaca benzer; kökü sabittir, dalları, budakları gökte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 25, 'Meyvesini her zaman verir Rabbinin izniyle ve Allah, düşünüp ibret alsınlar diye insanlara örnekler getirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 26, 'Pis söz de pis ağaca benzer; kesilip yerden çıkarılmıştır, duracak hali yoktur onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 27, 'Allah, inananlara dünya yaşayışında da, ahirette de o sabit sözle sebat verir ve zulmedenleri saptırır ve Allah, dilediğini yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 28, 'Görmedin mi Allah''ın nimetini küfre değişenleri ve kavimlerini de sürükleyip helak yurduna konduranları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 29, 'Cehenneme sokanları? Hepsi de oraya gider ve orası, karar edilecek ne kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 30, 'Onlar, halkı onun yolundan çıkarıp saptırmak için Allah''a benzerler kabul ettiler. De ki: Geçinin şimdilik, çünkü gerçekten de dönüp varacağınız yurt ateştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 31, 'İman eden kullarıma söyle: Namaz kılsınlar ve onları rızıklandırdığımız şeylerin bir kısmını yoksullara harcasınlar o gün gelip çatmadan ki ne alışveriş var o günde ne karşılıklı dostluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 32, 'Bir Allah''tır ki gökleri ve yeryüzünü yaratmıştır ve gökten yağmur yağdırıp o suretle size rızık olarak meyveler bitirmiştir ve emriyle denizde akıp giden gemileri ram etmiştir size ve ram etmiştir ırmakları size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 33, 'Ve devir ve hizmetlerinde daim olan güneşle ayı ram etmiştir geceyle gündüzü size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 34, 'Ve Allah ne dilediyseniz hepsini de vermiştir size ve Allah''ın nimetlerini saymaya kalkışırsanız sayamazsınız. Gerçekten de insan, pek zalimdir, küfrü pek boldur onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 35, 'An o zamanı ki İbrahim, Rabbim demişti, bu şehri emin et, beni de, oğlumu da putlara tapmaktan uzaklaştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 36, 'Rabbim, şüphe yok ki onlar, insanların çoğunu doğru yoldan saptırdılar. Artık kim bana uyarsa o bendendir ve bana isyan edene gelince: Şüphe yok ki sen, suçları örtersin, rahimsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 37, 'Rabbimiz, soyumun bir kısmını ekin bitmez bir yere, hürmeti vacib olan evinin yanına yerleştirdim, Rabbimiz, namaz kılsınlar diye. Artık insanların bir kısmı da onlara gönül versin, sevsinler onları ve şükretmeleri için de meyvelerle rızıklandır onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 38, 'Rabbimiz, şüphe yok ki gizlediğimizi de bilirsin sen, açığa vurduğumuzu da ve Allah''tan hiçbir şey gizlenemez ne yeryüzünde, ne de gökte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 39, 'Hamd Allah''a ki ihtiyarlığımda bana İsmail''i ve İshak''ı verdi. Şüphe yok ki Rabbim, duayı mutlaka duyar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 40, 'Rabbim, beni de, soyumdan gelenleri de namaza müdavim et; Rabbimiz duamızı da kabul et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 41, 'Rabbimiz, benim suçlarımı ört, yarlıga beni ve anamı, babamı ve inananları halkın sorusorgu için kalktığı gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 42, 'Zalimlerin yaptıklarından gafil sanma Allah''ı sakın; ancak onların cezasını, gözlerin dikilip kalacağı güne tehir etmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 43, 'O gün, başları göğe çevrilmiş, koşup dururlar, göz çevirip kendilerine bile bakmazlar ve yürekleri bomboştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 44, 'Kendilerine azabın gelip çatacağı o günü haber ver, korkut insanları. Zulmedenler diyecekler ki: Rabbimiz, yakın bir zamanadek bırak bizi, tekrar dünyaya dönelim de davetine icabet edelim ve peygamberlere uyalım. Siz değil misiniz daha önce, bize bir zeval yoktur diye yemin edenler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 45, 'Kendilerine zulmedenlerin yurtlarında oturdunuz ve onlara nasıl azap ettiğimiz sizce apaçık belli oldu ve size nice örnekler getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 46, 'Düzenlerini yaptılar, düzdükleri hilelerin cezasıysa Allah katında, hatta hilelerinden dağlar bile yerinden oynasa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 47, 'Sakın Allah, peygamberlerine vaadettiğinden döner sanma. Şüphe yok Allah üstündür, intikam alır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 48, 'O gün, bir gündür ki yeryüzü de başka bir yeryüzüne döner, gökler de. Herkes, bir ve kahhar Allah''ın tapısında toplanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 49, 'O gün görürsün ki suçluların boyunlarına zincirler vurulmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 50, 'Gömlekleri katrandandır, yüzlerini de ateş kaplamış.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 51, 'Allah, herkese yaptığının karşılığını verir. Şüphe yok ki Allah''ın hesap görmesi, pek tezdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (14, 52, 'İşte bu, insanlara bir tebliğdir; ibret alsınlar ondan ve bilsinler ki odur ancak tapacak bir mabut ve düşünüp ibret alsın akıl ve dirayet sahipleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 1, 'Elif lam ra, budur kitabın ve her şeyi açıklayan Kur''an''ın ayetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 2, 'Nice demler gelecek ki kafirler, ne olur keşke biz de Müslüman olsaydık diyecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 3, 'Bırak onları, yesinler, geçinsinler ve isteklere düşüp oyalansınlar, yakında bilecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 4, 'Ve biz hiçbir şehri helak etmedik ki helak edeceğimiz zaman, malum ve mukadder olmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 5, 'Hiçbir ümmet, ne helak edileceği zamanı mukadder vaktinden öne alabilir, ne de onu geciktirebilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 6, 'Ve derler ki: Ey kendisine Kur''an indirilen sen gerçekten de delisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 7, 'Gerçeklerdensen neden meleklerle gelmiyorsun bize?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 8, 'Biz melekleri, ancak hak ve gerçek olarak indiririz, indiririz ama o vakit de mühlet vermeyiz, göz açtırmayız kafirlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 9, 'Şüphe yok ki Kur''an''ı biz indirdik ve şüphe yok ki onu mutlaka koruyacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 10, 'Andolsun ki senden önce, evvelki ümmetlere de peygamberler göndermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 11, 'Hiçbir peygamber göndermedik ki alay etmesinler onunla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 12, 'Biz böylece, Kur''an''ı, yüreklerine kadar sokarız da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 13, 'Gene ona inanmazlar ve gerçekten, eskilerin yoluyoradamı da böylece olup bitmiş, onlar da bu yüzden azaba uğrayıp gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 14, 'Onlara gökten bir kapı açsak da melekler, o kapıdan inip çıksalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 15, 'Bunu görürler de gene ancak derler, gözlerimiz bağlandı bizim, hatta büyülenmiş bir topluluğuz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 16, 'Andolsun ki gökte burçlar halkettik ve göğü, seyredenlere bezedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 17, 'Ve onu, bütün taşlanmış Şeytanlardan koruduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 18, 'Ancak hırsızlama bir şey duymaya kalkışan olursa onun da ardından apaçık görünen bir ateş yalımıdır gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 19, 'Yeryüzünü, enine boyuna döşedik ve orada metin dağlar yarattık ve oradan, taktirimize göre, her şeyi bitirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 20, 'Orada sizin için de, sizin rızıklandırmadığınız mahlukat için de geçim sebepleri halkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 21, 'Hiçbir şey yoktur ki hazineleri, katımızda olmasın ve biz onu ancak malum bir miktarda indiririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 22, 'Yüklü rüzgarlar gönderdik de gökten yağmur yağdırdık, suya kandırdık sizi ve onu koruyup saklayan siz değilsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 23, 'Ve şüphe yok ki ancak biz diriltiriz, biz öldürürüz ve biziz her şeye varis olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 24, 'Ve andolsun ki önce geçip gidenlerinizi de biliriz, sonraya kalanlarınızı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 25, 'Ve şüphe yok ki Rabbin, hepsini de haşreder; şüphe yok ki o, hüküm ve hikmet sahibidir ve her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 26, 'Andolsun ki biz Âdem''i, kuru, kokmuş, şekil ve suret verilmiş balçıktan yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 27, 'Şeytan''ıysa daha önce, yakıp öldürücü bir harareti olan ateşten yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 28, 'An o zamanı ki Rabbin, meleklere demişti: Gerçekten de ben, kuru, kokmuş, şekil ve suret verilmiş balçıktan bir insan yaratacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 29, 'Onun yaratılışını tamamlayıp kemale getirerek ruhumdan ruh üfürünce derhal ona karşı secdeye kapanın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 30, 'Meleklerin hepsi birden secde ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 31, 'Ancak İblis secde etmedi, secde edenlere katılmaktan çekindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 32, 'Ey İblis dedi, sana ne oldu da secde edenlere katılmaktan çekindin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 33, 'Kuru, kokmuş, şekil ve suret verilmiş balçıktan yarattığın insana dedi, ben secde etmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 34, 'Çık buradan dedi, şüphe yok ki taşlanmış, kovulmuşsun sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 35, 'Ve gerçekten de din gününe dek lanet sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 36, 'Rabbim dedi, onların tekrar dirilecekleri güne dek mühlet ver, yaşat beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 37, 'Şüphe yok ki dedi, sen, mühlet verilmişlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 38, 'Malum vaktin gelip çatacağı güne dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 39, 'Rabbim dedi, beni rahmetinden mahrum ettiğin gibi bende kötülükleri, yeryüzünde onlara bezeyecek, onları isyan ettirerek hepsini de rahmetinden mahrum edeceğim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 40, 'Ancak ihlasa sahip edilmiş kulların müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 41, 'Tanrı, işte bu yol dedi, dosdoğru bana varan yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 42, 'Şüphe yok ki kullarıma hiçbir suretle gücün yetmez, ancak sana uyan azgınlara yeter senin gücün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 43, 'Ve şüphe yok ki onların hepsine de vaadedilen yer, cehennemdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 44, 'Orasının yedi kapısı var, her kapıya da onlardan bir kısmı ayrılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 45, 'Şüphe yok ki çekinenler, cennetlerde ve ırmak başlarındadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 46, 'Esenlikle emin olarak girin cennetlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 47, 'Gönüllerindeki kini, hasedi, ta kökünden söküp attık onların, kardeşlerdir, birbirlerine karşı tahtlar üstünde otururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 48, 'Orada ne bir yorgunluk duyarlar, ne de oradan çıkarılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 49, 'Haber ver kullarıma, şüphe yok ki ben suçları örterim, rahimim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 50, 'Ve şüphe yok ki azabım da pek elemli bir azaptır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 51, 'Onları, İbrahim''e gelen misafirlerden de haberdar et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 52, 'Hani, huzuruna girmişler de esenlik sana demişlerdi; o da, biz gerçekten de sizden korkuyoruz demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 53, 'Korkma demişlerdi, biz sana, bilgi sahibi bir erkek evlat müjdeliyoruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 54, 'İhtiyarlık çağımda mı demişti, bana müjde veriyorsunuz? Neye istinaden müjde vermektesiniz bana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 55, 'Sana öyle bir müjde veriyoruz ki gerçektir bu, sakın ümidini kesenlerden olma demişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 56, 'O da Rabbinin rahmetinden demişti, ancak doğru yoldan sapanlardan başka kim ümit keser?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 57, 'Ey elçiler demişti, başka ne memuriyetiniz var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 58, 'Biz demişlerdi, şüphe yok ki mücrim bir topluluğa gönderildik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 59, 'Ancak Lut ve soyu müstesna; onların hepsini de mutlaka kurtaracağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 60, 'Yalnız karısını kurtarmayacağız, onun, helak olanlarla beraber şehirde kalmasını takdir ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 61, 'Elçiler Lut ailesine geldikleri zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 62, 'O, siz dedi tanınmamış kimselersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 63, 'Onlar, biz dediler, onların şüphe ettikleri şeyi getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 64, 'O gerçek haberle geldik sana ve biz doğru sözlüyüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 65, 'Gece yarısından sonra aileni yola çıkar, sen de artlarına düş, hiçbiriniz arkanıza bakmayın, emrolunacak yere geçingidin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 66, 'Ve bu işi ona vahyettik de hiç şüphe yok ki dedik, sabah çağı bunların kökleri kesilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 67, 'Şehir halkı, birbirlerini müjdeleyerek misafirlerin yanına geldi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 68, 'Lut, bunlar benim konuklarım dedi, onlara karşı utandırmayın beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 69, 'Allah''tan çekinin de mahzun etmeyin beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 70, 'Seni konuk kabul etmekten menetmedik miydi dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 71, 'Lut, evlenecekseniz işte kızlarım, onları alın dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 72, 'Ömrün hakkı için onlar, gafletten adeta sarhoştular, gaflet içinde şaşkın bir haldeydiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 73, 'Güneş doğduktan sonra onları bir bağırış, helak ediverdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 74, 'Ülkelerinin altını üstüne getirdik, üstlerine balçıktan meydana gelmiş taşlar yağdırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 75, 'Şüphe yok ki bunda düşünenlere ibretler var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 76, 'Ve şüphe yok ki o şehir, hala herkesin yol uğrağı olan bir yerde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 77, 'Şüphe yok ki bunda, inananlar için bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 78, 'Ashab-ı Eyke de gerçekten zalimdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 79, 'Öcaldık onlardan; iki şehir de apaçık görünmede, yol uğrağında hala.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 80, 'Ashabı Hicr de peygamberini inkar etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 81, 'Delillerimizi göstermiştik onlara, fakat onlardan yüz çevirmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 82, 'Ve evlerini dağlarda oyarlar, emin bir halde yaşarlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 83, 'Sabah çağına erdikleri gibi bir bağırış yüzünden helak olup gittiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 84, 'Kazandıkları mal ve servet, azabı defedemedi onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 85, 'Ve biz, gökleri ve yeryüzünü abes olarak halketmedik ve kıyamet, mutlaka gelecektir, aldırış bile etme, bir hoşça vaz geç onlardan şimdilik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 86, 'Şüphe yok ki Rabbin, her şeyi yaratandır ve her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 87, 'Andolsun ki biz sana, tekrarlanan yedi ayeti ve pek büyük olan Kur''an''ı verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 88, 'Onlara verdiğimiz mala, evlada göz dikme, onlar için tasalanıp gam yeme, inananlara karşı kanadını indir, onları koru, onlara karşı mütevazı ol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 89, 'Ve de ki: Hiç şüphe yok ki ben, gerçekten de bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 90, 'Nitekim bölükbölük olanlara da indirmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 91, 'Öyle kişilerdi onlar ki Kuran''ı parçaparça ettiler; bir kısmına inandılar da bir kısmına inanmadılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 92, 'Andolsun Rabbine ki onların hepsine soracağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 93, 'Yaptıkları şeyleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 94, 'Artık sen emredildiğin şeyi açıkla ve şirk koşanlardan yüz çevir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 95, 'O alaycılara karşı biz yeteriz sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 96, 'Onlar, Allah''tan başka tanrılar da kabul etmişlerdir; yakında bilip anlayacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 97, 'Ve andolsun biliriz ki şüphe yok, söyledikleri sözlerden yüreğin sıkılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 98, 'Artık Rabbine hamd ederek tenzih et ve secde edenlerden ol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (15, 99, 'Ve ölüm gelip çatıncaya dek Rabbine ibadet et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 1, 'Allah''ın emri gelip çatmada, sakın hemencecik gelmesini istemeyin. O, müşriklerin şirk koştuklarından münezzehtir ve yücedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 2, 'Benden başka yoktur tapacak o halde çekinin benden, hükmünü bildirip insanları korkutun diye, kullarından dilediğine melekleri indirerek vahyeder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 3, 'Göklerle yeryüzünü abes değil, hak ve gerçek olarak yaratmıştır, yücedir müşriklerin şirk koştuklarından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 4, 'İnsanı bir damla sudan yarattı, böyleyken bir de bakarsın o, apaçık bir düşman kesilmiş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 5, 'Davarları da o çeşit halketmiştir; onlardan giyiminizi temin edersiniz ve size faydalar var onlardan ve bir kısmını da yersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 6, 'Akşamleyin yayımdan getirir, sabahleyin yayıma götürürken de güzellikleri var, zevk alırsınız onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 7, 'Kendinize meşakkatler vererek ancak varabileceğiniz şehirlere de yüklerinizi taşırlar; şüphe yok ki Rabbiniz mutlaka esirgeyicidir, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 8, 'Binmeniz için ve ziynet için atları, katırları, merkepleri yaratmıştır, daha da bilmediğiniz neler yaratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 9, 'Doğru yolu bildirmek, Allah''a aittir, yolların eğrisi de var ve dileseydi hepinizi de doğru yola sevk ederdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 10, 'Öyle bir mabuttur ki size gökten yağmur yağdırır da suyunu içersiniz, hayvanlarınızı otlattığınız ağaçlar ve otlar da onunla biter, yeşerir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 11, 'Onunla size, ekinler, zeytinler, hurmalar, üzümler ve çeşitçeşit meyveler bitirir. Şüphe yok ki bunda, düşünen topluluğa bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 12, 'Ve ram etmiştir size geceyle gündüzü, güneşle ayı; yıldızlar da ram olmuştur emriyle. Şüphe yok ki bunda, akıl eden topluluk için deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 13, 'Ve yeryüzünde sizin için yarattığı, ayrıayrı, çeşitli renklerde ne varsa hepsi ram olmuştur size. Şüphe yok ki bunda da ibret alacak topluluk için bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 14, 'Öyle bir mabuttur ki ram etmiştir size denizi ondan çıkan terütaze balıkları yemeniz, çıkardığınız ziynet eşyasını takınmanız için ve görürsün ki gemi, denizde, suları yarayara gitmede; ram etmiştir size denizi, nasibinizi onun lutfundan arayıp bularak şükredesiniz diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 15, 'Sizinle beraber sallanmaması, çalkalanmaması için yeryüzünde muhkem ve metin dağlar yaratmıştır, ırmaklar halketmiştir ve gideceğiniz yeri bulmanız için yollar meydana getirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 16, 'Ve alametler halktemiştir ve yıldızla yollarını bulur onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 17, 'Yaratan, yaratmayana benzer mi? Hala mı düşünmeyeceksiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 18, 'Ve Allah nimetlerini saymaya kalkışsanız imkan yok, sayamazsınız; şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 19, 'Ve Allah gizlediğinizi de bilir, açığa vurduğunuzu da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 20, 'Allah''tan başka tapıp çağırdıkları putlar, hiçbir şey yaratamaz, kendileri yaratılmıştır onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 21, 'Ölülerdir onlar, diriler değil, ne vakit diriltilecekler, ondan da haberleri yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 22, 'Mabudunuz, tek mabuttur, ahirete inanmayanlarınsa gönülleri inkar eder bunu ve onlar, ululanmayı dileyen kişilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 23, 'Gerçekten de şüphe yok ki Allah, gizlenen şeyleri de bilir, açığa vurulanları da; şüphe yok ki o, ululananları sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 24, 'Onlara, Rabbiniz ne indirdi size dense derler ki: Geçmişlere ait masallar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 25, 'Bu da, kıyamet günü kendi günahlarını tamamıyla yüklendikten başka bilgisizlikle doğru yoldan çıkarıp saptırdıkları kişilerin suçlarının bir kısmını da yüklenmeleri içindir. Bilin ki yüklendikleri yük, ne de kötü yüktür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 26, 'Gerçekten, onlardan önce gelip geçenler de düzenler kurdular, Allah, yapılarını temellerinden yıktı da tavan, başlarına yıkılıverdi ve hem de bu azap, anlayamadıkları bir yerden gelip çattı onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 27, 'Sonra kıyamet gününde de onları horhakir bir hale getirecek de Nerede diyecek, onların yüzünden inananlara düşman kesildiğiniz ortaklarım? Bilgiye sahib olanlarsa bugün diyecekler, gerçekten de horluk ve kötülük kafirlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 28, 'Melekler, kendi kendilerine zulmedenlerin canlarını alırken onlar, biz hiçbir kötülük yapmadık diyediye can verirler. Evet, şüphe yok ki Allah, sizin yaptıklarınızı tamamıyla bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 29, 'Artık girin cehennem kapılarından, ebedi kalacaksınız orada. Ululuk satanların yurtları, ne de kötüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 30, 'Çekinenlere, Rabbiniz ne indirdi size denince hayır indirdi derler. Bu dünyada güzel hareket edenlere güzel bir mükafat var, ahiret eviyse elbette daha da hayırlı ve çekinenlerin evleri, gerçekten de ne güzeldir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 31, 'Ebedi Adn cennetleridir yurtları, oraya girerler, kıyılarından ırmaklar akar, ahiret eviyse elbette daha da hayırlı ve çekinenleri böyle mükafatlandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 32, 'Öyle kişilerdir onlar ki melekler, tertemiz olarak canlarını alır onların ve onlara, esenlik size derler, yaptığınız işlere karşılık girin cennete.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 33, 'Kafirler, meleklerin gelip çatmasından, yahut Rabbinin emrinin gelmesinden başka bir şey mi beklerler? Onlardan öncekiler de böyle yapmışlardı ve onlara Allah zulmetmedi, fakat onlar, kendi kendilerine zulmettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 34, 'Yaptıkları kötülüğe uğradılar ve alay ettiklerinin cezasını çektiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 35, 'Şirk koşanlar, Allah dileseydi dediler, ne biz ondan başka birşeye tapardık, ne atalarımız taparlardı; ne de emri olmadan birşeyi haram sayardık. İşte onlardan öncekiler de tıpkı böyle hareket ettiler. Peygamberlere apaçık tebliğden başka ne vazife var ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 36, 'Andolsun ki biz her ümmete, Allah''a kulluk edin ve Şeytan''dan uzaklaşın diye bir peygamber gönderdik; içlerinde, Allah''ın doğru yola sevkettiği de var, sapıklığı hakedeni de. Gezin yeryüzünde de bakın, görün, yalanlayanların sonuçları ne olmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 37, 'Onları doğru yola sevketmek için üstlerine düştükçe düşsen de şüphe yok ki Allah, sapıklığı kabul edeni doğru yola getirmez ve onlara bir tek yardımcı da yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 38, 'Onlar, Allah''a kesin olarak ant içtiler de Allah dediler, ölen kişiyi tekrar diriltmez. Evet, diriltecek, bir vaittir bu ki gerçektir ve yerine getirecektir onu, fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 39, 'İhtilaf ettikleri şeylerin kendilerince apaçık anlaşılması için ve kafir olanların, yalancı olduklarını bilmeleri için diriltecek onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 40, 'Sözümüz budur ancak, birşeyin olmasını diledik mi ona ol deriz, derhal olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 41, 'Zulme uğradıktan sonra Allah yolunda yurtlarından göçenlere mutlaka dünyada güzel yurtlar vereceğiz ve ahiret mükafatıysa elbette bundan da büyüktür bilseler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 42, 'Onlar öyle kişilerdir ki sabrettiler ve Rablerine dayandılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 43, 'Andolsun ki senden önce de gönderdiğimiz ve kendilerine vahyettiğimiz kimseler, insandı. Sorun bilmiyorsanız bilenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 44, 'Onları, delillerle, kitaplarla gönderdik ve sana da, onlara ne indirildiğini açıkça anlatman, düşünmelerini sağlaman için Kur''an''ı indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 45, 'Kötülük düzenleri kuranlar emin mi oldular Allah''ın, onları yere batırmayacağından, yahut hiç anlamadıkları bir yerden başlarına bir azap gelmeyeceğinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 46, 'Yahut onu aciz bırakamayacaklarına göre dönüp dolaşırlarken tutup onları helak etmeyeceğinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 47, 'Yahut da yavaşyavaş azaltarak onları mahvetmeyeceğinden? Şüphe yok ki Rabbiniz, esirgeyicidir, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 48, 'Allah''ın halkettiği şeyleri görmezler mi? Hepsinin de gölgesi, sağdan, soldan, alçalarak Allah''a secde etmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 49, 'Ve Allah''a secde etmededir göklerde ne varsa ve yeryüzünde yürüyen ne varsa ve melekler de ululanmadan Allah''a secde etmededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 50, 'Her şeye gücü yeten Rablerinden korkarlar da emredileni yaparlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 51, 'Allah, iki mabut tanımayın dedi, o, ancak bir mabuttur ve artık benden korkun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 52, 'Onundur ne varsa göklerde ve ne varsa yeryüzünde, ibadet ve itaat de daima onadır, hala mı Allah''tan başka birinden çekinmede, korkmadasınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 53, 'Size bir nimet gelse o, mutlaka Allah''tandır, sonra bir zarara uğrasanız gene ona yalvarırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 54, 'Sonra da sizden o zararı defetti mi o vakit içinizden bir kısmı, Rablerine şirk koşar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 55, 'Kendilerine verdiğimiz nimetlere nankörlük etmek için. Geçine durun, yakında bilir, anlarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 56, 'Kendilerini rızıklandırdığımız şeylerden, mahiyetlerini bilmedikleri putlara bir hisse ayırırlar; andolsun Allah''a ki iftira ettikleri şeyler yüzünden sorguya çekilecek onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 57, 'Haşa, münezzehtir o, kızları olduğunu söylerler Allah''ın, hoşlarına gidenlerse kendilerinindir onlarca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 58, 'Onların birine kızı olduğu müjdelenirse pek ziyade kızar da yüzü simsiyah olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 59, 'Müjdelendiği kötü şey yüzünden, kavminden gizlenir; onu horlukla yaşatacak mı, yoksa toprağa mı gömecek, buna dalar. Bilin ki hükmettikleri şey, ne de kötüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 60, 'Âhirete inanmayanlar, kötü sıfatlara sahiptir, en yüce sıfatsa Allah''ındır ve o üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 61, 'Allah, insanları zulümleri yüzünden helak etseydi yeryüzünde yürür bir tek mahluk kalmazdı, fakat onlara azap etmeyi mukadder bir zamana tehir etti; vakitleri gelince de ne bir an geri kalırlar, ne bir an önce gelipçatar o mukadder vakit.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 62, 'Allah''a, kendilerinin bile hoşlanmadıkları şeyleri atfederler ve dilleri de güzel ve hayırlı sonucun kendilerine mukadder olduğunu yalan yere söyler durur. Hiç şüphe yok ki onlarındır ateş ve tezcek, herkesten önce onlar girerler ateşe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 63, 'Andolsun Allah''a ki senden önce de ümmetlere peygamberler göndermiştik de Şeytan, onların yaptıkları şeyleri bezemiş, hoş göstermişti onlara ve o, bugün de dostudur onların ve onlara elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 64, 'Biz sana kitabı, ancak hakkında ayrılığa düştükleri nesneleri onlara apaçık bildirmen için indirdik ve inanan topluluğa da hidayettir ve rahmettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 65, 'Ve Allah, gökten yağmur yağdırır da yeryüzünü, ölümünden sonra diriltir onunla; şüphe yok ki duyan topluluğa bunda bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 66, 'Davarlarda da ibret alacağınız şeyler var. Karınlarındaki fışkıyla kan arasındaki halis sütü içirmedeyiz size ve süt, içenlerin boğazlarından kayıp gitmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 67, 'Hurma ağacının meyveleriyle üzümlerden de şarap yaparsınız, güzel bir rızk elde edersiniz; şüphe yok ki bunda da akıl eden topluluğa bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 68, 'Ve Rabbin, bal arısına, dağlarda, ağaçlarda ve çardak kurulan yerlerde kovan yapın diye vahyetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 69, 'Sonra dedi, bütün meyvelerden bal toplayın ve gönül alçaklığıyla Rabbinizin yollarını tutun. Karınlarından çeşitli renkte ballar çıkar, onlarda şifa var insanlara. Şüphe yok ki bunda da düşünen topluluk için bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 70, 'Ve Allah sizi halketti, sonra öldürür ve içinizden yaşayışın en aşağılık çağına, kocalığa kadar ömür sürdürülenler de vardır ki bildikleri şeyleri bilmez olurlar; şüphe yok ki Allah her şeyi bilir, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 71, 'Ve Allah, rızık bakımından bir kısmınızı, bir kısmınızdan üstün etmiştir. Geçimi üstün olanlar, rızıklarını, elleri altında bulunanlara verip onları da geçim bakımından kendilerine eşit etmezler, Allah''ın nimetini bilebile inkar mı ederler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 72, 'Ve Allah size, kendi cinsinizden eşler halketti, eşlerinizden de size oğullar, torunlar verdi ve tertemiz şeylerle rızıklandırdı sizi. Hala batıla inanırlar da Allah''ın nimetine karşı nankörlükle mi bulunurlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 73, 'Allah''ı bırakırlar da ne göklerde, ne yeryüzünde hiçbir şeye sahip olmayan ve hiçbir şeye gücü yetmeyen putlara kulluk ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 74, 'Artık Allah''a eşit varlıklar tanımayın; şüphe yok ki Allah bilir her şeyi ve siz bilmezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 75, 'Allah bir örnek getirmiştir: Bir köle olsa ve hiçbir şeye gücü yetmese ve bir de güzel bir surette rızıklandırdığımız birisi bulunsa da rızıklandırdığımız şeylerin bir kısmını, gizli, açık yoksullara harcasa, onları geçindirse bunlar eşit ve denk olur mu hiç? Hamd Allah''a, eşit değildir bunlar, fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 76, 'Ve Allah, gene iki kişiyi örnek getirir: Biri dilsizdir, hiçbir şeye gücü yetmez, sahibine bir yüktür, nereye yollasa hayırlı bir iş becerip gelemez. O, hiç adaletle emreden ve doğru yolu tutmuş olan adamla eşit olur mu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 77, 'Ve göklerin ve yeryüzünün gizli şeyleri Allah''ındır ve kıyametin kopması da göz kırpıp açacak bir an içinde olup biter, belki ondan daha da çabuk bir an içinde. Şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 78, 'Ve Allah sizi, analarınızın karnından çıkardı, hiçbir şey bilmezdiniz ve size, şükredesiniz diye kulak verdi, gözler verdi, gönüller verdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 79, 'Gökle yer arasında uçup duran kuşları görmezler mi? Onları boşlukta tutan, ancak Allah''tır. Şüphe yok ki bunda da inanan topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 80, 'Ve Allah, evlerinizi oturma ve dinlenme yeri yaptı ve davarların derilerinden, göç gününüzde de, konak gününüzde de taşıyabileceğiniz çadırlar yapmanızı sağladı ve yünlerinden, yapağılarından, tüylerinden bir zamana dek kullanacağınız ve alıp satacağınız eşyalar meydana getirmenizi temin etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 81, 'Ve Allah, yarattığı şeylerden gölgeler halketti size ve dağlarda kovuklar, mağaralar meydana getirdi sizin için, sizi sıcaktan, soğuktan koruyacak elbiseler, savaşta zarardan koruyacak zırhlar yapmanızı da sağladı. Ona teslim olmanız için nimetlerini böylece tamamlar size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 82, 'Bütün bunlara rağmen yüz çevirirlerse şüphe yok ki sana düşen vazife, açıkça tebliğden ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 83, 'Onlar, Allah''ın nimetini tanırlar da sonra inkar ederler ve çoğu kafirdir onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 84, 'Ve o gün her ümmete bir tanık getiririz de sonra kafirlere, ağız açıp özür dilemeye bile izin verilmez ve yaptıkları kötülüklerden vazgeçeceklerine dair verdikleri söz de kabul edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 85, 'Zulmedenler azabı görmeye başladılar mı hafifletilmez azapları ve mühlet de verilmez onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 86, 'Şirk koşanlar, Tanrıya eş olarak kabul ettikleri şeyleri görünce Rabbimiz derler, seni bırakıp kulluk ettiğimiz eşlerimiz bunlar işte. Sözleri reddedilir de şüphe yok ki denir, yalancılarsınız siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 87, 'O gün Allah''a teslim olurlar ve uydurdukları şeyler, önlerinden kaybolup gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 88, 'Kafir olup halkı Allah yolundan menedenleri, yaptıkları bozgunculuk yüzünden azap üstüne azap katarak cezalandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 89, 'Her ümmete, kendi cinsinden bir tanık getireceğiz ve seni de bunlara tanık tutacağız ve biz, sana her şeyi açıklayıp anlatan ve Müslümanlara hidayet, rahmet ve müjde olan kitabı indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 90, 'Şüphe yok ki Allah, adaleti, lütuf ve keremde bulunmayı ve yakınlara ihtiyaçları olan şeyleri vermeyi emreder ve çirkin olan, kötü görünen şeylerle haksızlığı nehyeder; öğüt alasınız diye de size öğüt vermededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 91, 'Karşılıklı bir ahde girişince Allah ahdine vefa edin ve Allah''ı kefil göstererek ettiğiniz yeminleri, bu suretle pekiştirdikten sonra bozmayın; şüphe yok ki Allah, ne yaparsanız hepsini de bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 92, 'İpliğini iyice büktükten sonra onu söken kadına benzemeyin. Bir topluluk diğer bir topluluktan daha çok ve üstün diye yeminlerinizi bir düzen haline koymayın; Allah sizi bununla sınar ancak ve hakkında ayrılığa düştüğünüz şeyi de kıyamet günü, size açıklar, bildirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 93, 'Allah dileseydi sizi bir tek ümmet olarak halk ederdi, fakat o, dilediğini saptırır, dilediğini doğru yola sevk eder ve yaptıklarınızdan dolayı mutlaka sorguya çekileceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 94, 'Yeminlerinizi, birbirinizi aldatmaya vasıta edinmeyin, sonra ayağınız adamakıllı pekişip yerleştikten sonra kayıverir ve halkı, Allah yolundan menetmenize karşılık kötülüğe uğrarsınız ve hakkınız olur pek büyük azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 95, 'Allah''la giriştiğiniz ahdi, az bir menfaat karşılığında satmayın ve Allah''ın katındaki yok mu, bilirseniz o, daha da hayırlıdır size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 96, 'Sizde ne varsa bitip tükenir, Allah''ın katındakiyse kalır. Sabredenlerin mükafatını, yaptıkları en güzel işlere karşılık olarak mutlaka vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 97, 'Erkek olsun, kadın olsun, inanarak iyi işlerde bulunanı tertemiz bir yaşayışa mazhar ederiz ve mükafatını, yaptığı en güzel işlere karşılık olarak mutlaka vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 98, 'Kur''an okuyacağın vakit Allah''a sığın taşlanmış Şeytan''dan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 99, 'Şüphe yok ki inanan ve Rablerine dayanan kimselere karşı gücükuvveti yoktur, hükmü yürümez onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 100, 'Onun kudreti, ancak ona dost olup itaat edenlere yeter ve onlar da Tanrıya şirk koşanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 101, 'Bir ayeti, başka bir ayetin yerine koyup hükmünü değiştirdik mi, Allah neyi indireceğini daha iyi bildiği halde, sen derler, ancak bir iftiracısın; halbuki onların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 102, 'De ki: Onu, inananların inançlarını sağlamlaştırmak için Müslümanlara hidayet ve müjde olarak RuhülKudüs, Rabbinden hak ve gerçek olarak indirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 103, 'Andolsun ki biz biliyoruz, onlar, bunu ona ancak birisi öğretmede diyorlar. Bellettiğini sandıkları adam, yabancıdır, Arapçayı doğru düzen konuşamaz, bu Kur''an''sa, apaçık Arap diliyle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 104, 'Allah''ın ayetlerine inanmayanları Allah, doğru yola sevketmez; onlara elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 105, 'Allah''ın ayetlerine inanmayanlar, yalan söylerler, iftirada bulunurlar, onlardır yalancıların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 106, 'Canla, gönülle inanmışken ve yüreği, inançla yatışmışken zorla, cebirle, istemediği halde dininden döndüğünü söyleyenden başka inandıktan sonra Allah''ı inkar eden, hatta kafirlikle yüreği genişleyen, hoşlanan kişi yok mu, bu çeşit kişileredir Allah''ın gazabı ve onlara pek büyük bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 107, 'Bu da, dünya yaşayışını sevip ahiretten üstün tutmalarındandır ve şüphe yok ki Allah, kafir olan topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 108, 'Onlar, öyle kişilerdir ki Allah, onların kalplerini, kulaklarını, gözlerini mühürlemiştir ve onlardır gaflet edenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 109, 'Hiç şüphe yok ki onlar, ahirette de ziyana uğrayanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 110, 'Sonra şüphe yok ki Rabbin, mihnetlere uğradıktan sonra yurtlarından göçenleri ve sabredenleri yarlıgar; zorla dine aykırı söz söyledikten sonra da Rabbin, şüphe yok ki onların suçlarını örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 111, 'Bir gün gelir ki herkes, ancak canıyla uğraşır ve herkese, ne yaptıysa karşılığı tastamam verilir ve onlar, zulüm görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 112, 'Allah bir örnek getirir, bir şehir var mesela ahalisi, emniyet içinde yaşamada, gönülleri rahat, rızıkları, her yandan bol bol gelmede; derken Allah''ın nimetlerine nankörlük ederler de Allah onları açlık ve korku elbisesine bürür, onlara açlığı ve korkuyu tattırır işledikleri işler yüzünden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 113, 'Andolsun ki onlara, kendi cinslerinden bir peygamber geldi de onu yalanladılar, onları helak ediverdi azap ve onlardır zulmedenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 114, 'Ancak ona kulluk ediyorsanız Allah''ın size verdiği helal ve temiz rızıkları yiyin ve Allah''ın nimetine şükredin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 115, 'Allah size ancak ölüyü, kanı, domuz etini ve Allah''tan başkası için kesilmiş hayvanı haram etmiştir. Zorda kalan, isyan etmek niyetini gütmeden ve fazla olmamak şartıyla yiyebilir, şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 116, 'Yalanlar uydurup dile getirerek Allah''a iftira etmeyin şu helaldir, bu haram diye; şüphe yok ki yalan söyleyip Allah''a iftira edenler, kurtulmazlar, muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 117, 'Elde ettikleri pek az bir geçimden ibarettir ve onlara elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 118, 'Yahudi olanlara da daha önce sana anlattığımız şeyleri haram etmiştik. Onlar, bize zulmetmediler, kendilerine zulmettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 119, 'Sonra şüphe yok ki Rabbin, bilgisizlikle kötü işler yapıp da tövbe ederek hallerini düzeltenleri, yaptıkları kötü işlerden sonra da yarlıgar muhakkak, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 120, 'Şüphe yok ki İbrahim, tek başına bir ümmetti, Allah''a itaat ederdi daima, doğruydu ve müşriklerden değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 121, 'Onun nimetlerine şükrederdi. Tanrı onu seçmiş ve doğru yola sevketmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 122, 'Ve dünyada ona iyilik vermiştik, ahirette de gerçekten, salih kişilerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 123, 'Sonra sana da, doğru hareket eden İbrahim''in dinine uy diye vahyettik ve o, müşriklerden değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 124, 'Cumartesi gününün hürmeti, ancak o gün hakkında ihtilafa düşenlere farzedilmiştir ve şüphe yok ki Rabbin, kıyamet günü, ihtilafa düştükleri şeyler hususunda aralarında hükmeder onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 125, 'Rabbinin yoluna hikmetle ve güzel öğütle çağır ve onlarla en güzel bir tarzda münakaşa ve mübahasede bulun. Şüphe yok ki Rabbin, kendi yolundan sapanları daha iyi bilir ve o, daha iyi bilir doğru yolu tutanları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 126, 'Mücazatta bulunacaksanız sizi cezalandırdıkları gibi ve o kadar cezalandırın onları, fakat sabrederseniz elbette bu hareket, sabredenlere daha da hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 127, 'Sabret, sabretmen, ancak Allah''ın vereceği başarıyla mümkündür. Sana düzen kurduklarından dolayı da daralma, sıkıntıya düşme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (16, 128, 'Şüphe yok ki Allah, çekinenlerle ve iyilik eden kişilerledir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 1, 'Noksan sıfatlardan münezzehtir kulunu geceleyin Mescidi Haram''dan çevresini kutladığımız Mescidi Aksa'' ya götüren, ayetlerimizden bir kısmını ona da gösterelim diye, şüphe yok ki o, her şeyi duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 2, 'Ve biz, Musa''ya kitap verdik ve o kitabı, benden başka hiçbir koruyucu tanımayın emriyle İsrailoğulları için doğru yola bir rehber ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 3, 'Ey Nuh''la beraber gemiye bindirip kurtardığımız insanların soyundan gelenler, şüphe yok ki Nuh, çok şükreden bir kuldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 4, 'Ve İsrailoğullarına kitapta şu haberi vermiştik: Yurtta mutlaka iki kere bozgunculuk edeceksiniz ve iki kere baş kaldıracak, büyük bir taşkınlıkta bulunacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 5, 'O iki taşkınlıktan birincisinin mukadder zamanı gelince size, azap etmede çetin, kuvvetli kullarımızı gönderdik de yurdunuzun ta içine girip sizi araştırdılar ve bu, yerine getirilen bir vaatti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 6, 'Sonra onlara karşı size gene devlet ve kudret verdik, mallar, oğullar ihsan ederek yardım ettik size ve sizi, topluluk bakımından da pek çoğalttık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 7, 'İyilik ederseniz faydası kendinize kötülükte bulunursanız zararı gene size. İkinci vaadimizin mukadder zamanı gelince gene yüzünüzü karartacaklar, ilk defa girdikleri gibi gene mescide girecekler, üst geldiklerini büsbütün mahiv ve helak edeceklerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 8, 'Rabbinizin size acıyacağı umulur, fakat tekrar kötülüğe dönerseniz biz de döner, cezanızı veririz ve biz, cehennemi kafirlere bir zindan olarak halkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 9, 'Şüphe yok ki bu Kur''an, insanları en doğru bir yola sevk eder ve iyi işlerde bulunan inanmış kimselere, gerçekten de büyük bir mükafata nail olacaklarını müjdeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 10, 'Âhirete inanmayanlara gelince: Onlara elemli bir azap hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 11, 'İnsan, hayra dua ediyormuşçasına şerre de dua eder ve insan, pek acelecidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 12, 'Geceyle gündüzü, iki delil olarak yarattık ve bir delil olan geceyi giderdik de Rabbinizin lutfunu aramanız, yılların sayısını bilmeniz, hesabını anlamanız için yerine başka bir delil olan ve her şeyi gösterip belirten gündüzü getirdik ve biz, her şeyi apaçık anlatmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 13, 'Her insanın yaptığı işleri boynuna astık, kıyamet günü de apaçık yazılmış bir kitap olarak meydana çıkaracağız onları, herkes, ne yapmışsa hepsini o kitapta yazılmış bulacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 14, 'Oku kitabını, bugün hesap görmek için sen yetersin sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 15, 'Kim doğru yolu bulursa ancak kendisi için bulmuştur ve kim doğru yoldan sapmışsa kendisini sapıtmıştır ve kimse, bir başkasının yükünü yüklenmez ve biz, peygamber göndermedikçe hiçbir topluluğu azaplandırmayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 16, 'Bir şehri helak etmek istersek ileri gelenlerine emrimizi tebliğ ederiz, buyruktan çıkar, orada isyana koyulurlar da azabı hak ederler, biz de onları tamamıyla helak eder, orasını yerle yeksan ederiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 17, 'Nuh''tan sonra nice toplulukları helak ettik. Rabbin, kullarının suçlarından haberdardır, görür onları ve bu, yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 18, 'Kim, şu hemencecik, pek tez geçen dünyayı dilerse biz de dilediğimize, dilediğimiz şeyi hemencecik veririz orada, sonra biz, cehennemi de onun için halkettik, oraya kınanmış, kovulmuş bir halde girer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 19, 'Ve kim, inanarak ahireti diler ve bu hususta adamakıllı çalışıp çabalarsa bu çeşit kimseler, çalışmalarının mükafatını mutlaka görürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 20, 'Onlara da, bunlara da, hepsine, Rabbinin lütuf ve ihsanından yardımda bulunuruz, bağışlar dururuz ve Rabbinin ihsanı, kimseden men edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 21, 'Bak da gör, onların bir kısmını nasıl bir kısmından üstün ettik; elbette ahiretteki yücelik, dereceler bakımından da daha büyüktür, üstünlük bakımından da daha büyük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 22, 'Allah''la beraber başka bir mabut tanıma, sonra kınanmış bir halde ve tek başına, yardımdan mahrum olarak oturup kalırsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 23, 'Ve Rabbin, kendisinden başkasına kulluk etmemenizi ve anaya, babaya iyilik etmenizi hükmetmiştir; onlardan biri, yahut her ikisi, senin hayatında ihtiyarlık çağına ererse onlara üf bile deme, azarlama onları ve onlara güzel ve iyi söz söyle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 24, 'İkisine karşı da merhametle kanatlarını indir, mütevazı ol ve ya Rabbi de, onlar, çocukluğumda beni nasıl büyütüp yetiştirdilerse sen de onlara öylece merhamet et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 25, 'İçinizde ne var, Rabbiniz, sizden daha iyi bilir. Düzgün ve temiz kişiler olursanız şüphe yok ki o, tövbe edip hakka dönenlerin suçlarını örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 26, 'Akrabaya, yoksula, yolda kalmışa hakkını ver ve israfta ileri giderek boş yere, haksız yere malını saçma, savurma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 27, 'Gerçekten de malını boş yere saçıp savuranlar, Şeytanlara kardeş olurlar ve Şeytan, Rabbine karşı nankördür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 28, 'Rabbinden umduğun bir rahmeti dileyerek onlara bir şey veremez, yüz çevirmek zorunda kalırsan güzel sözler söyle onlara, gönüllerini al.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 29, 'Elini boynuna bağlama, tamamıyla da açma, sonra kendini kınar ve birşeye gücün yetmeyerek pişman bir halde otururkalırsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 30, 'Şüphe yok Rabbin, dilediğinin rızkını genişletir, daraltır, şüphe yok ki o, kullarından haberdardır, onları görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 31, 'Evladınızı, yoksulluk korkusuyla öldürmeyin; onları da biz rızıklandırırız, sizi de. Şüphe yok ki onları öldürmek, pek büyük bir suçtur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 32, 'Zinaya yaklaşmayın, şüphe yok ki zina, kötülüktür ve zinada bulunmak, kötü bir yol tutmaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 33, 'Haklı olmadıkça Allah''ın haram ettiği cana kıymayın ve kim, zulümle öldürülürse mirasçısına, öldürene karşı bir kudret ve salahiyet verdik ancak öldürmede aşırı gitmemeli; şüphe yok ki yardıma da mazhar edilmiştir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 34, 'Ergenlik çağına erişinceye dek yetimin malına yaklaşmayın, ancak çok güzel bir tarzda o malı idare edebilirsiniz ve ahitlerinizde durun, şüphe yok ki ahitlerden sorumlusunuz siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 35, 'Bir şey ölçtüğünüz vakit ölçeği tam tutun, tarttığınız şeyi doğru teraziyle tartın. Bu, hem daha hayırlıdır size, hem sonucu daha güzeldir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 36, 'Bilmediğin şeyin üstünde durup ısrar etme; çünkü kulak da, göz de, gönül de, hepsi de sorumludur bundan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 37, 'Yeryüzünde kibirlenerek yürüme; çünkü ne yeri yarabilirsin, ne de boyun dağlara erer, onlara erişebilirsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 38, 'Bunların hepsi de kötüdür ve Rabbinin katında hoşa gitmiyen şeylerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 39, 'Bunlar, Rabbinin, sana vahyettiği hikmetlerdendir ve Allah''la beraber başka bir mabut tanıma, sonra kınanmış, kovulmuş bir halde cehenneme atılırsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 40, 'Yoksa Rabbiniz, size erkek çocuklar verdi de kendisinin, meleklerden kız çocukları mı var? Gerçekten, ne de büyük bir söz söylüyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 41, 'Andolsun ki düşünüp ibret almaları için şu Kur''an''da bu meseleyi apaçık ve defalarca anlattık, fakat bu anlatış, onların ancak, gerçekten büsbütün uzaklaşmalarına sebep olmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 42, 'De ki: Onların dedikleri gibi Allah''la beraber başka mabutlar da olsaydı o zaman elbette arş sahibine ulaşmak için bir yol, bir sebep araştırırlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 43, 'Halbuki o, onların söylediklerinden tamamıyla münezzehtir, tamamıyla yücedir, büyüktür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 44, 'Yedi gök ve yerle onlarda ne varsa hepsi, onu noksan sıfatlardan tenzih eder ve hiçbir şey yoktur ki ona hamdederek onu noksan sıfatlardan tenzih etmesin, yalnız siz, onların tesbih edişlerini anlayamazsınız. Şüphe yok ki o, azap etmede acele etmez, halimdir ve suçları örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 45, 'Kur''an okuduğun zaman seninle ahirete inanmayanların arasına gizli bir perde gereriz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 46, 'Anlamamaları için gönüllerine perdeler gerer, kulaklarına ağırlık veririz ve sen, Kur''an''da, Rabbini, bir olarak andın mı yüz çevirirler, uzaklaşırlar senden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 47, 'Biz, seni dinleyecekleri zaman asıl neyi dinliyeceklerini ve birbirleriyle gizlice konuşurlarken o zalimlerin, siz ancak büyülenmiş bir adama uymuşsunuz diyeceklerini pek iyi biliriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 48, 'Bak da gör, sana nasıl örnekler getirip de saptılar ve artık bir yol bulmaya güçleri yetmeyecek onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 49, 'Biz dediler, kemik ve toz haline geldikten sonra mı yeniden halk edilecek, dirileceğiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 50, 'De ki: Taş, yahut demir olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 51, 'Yahut da aklınızca bundan da daha büyük bir başka mahluk olun; mutlaka dirileceksiniz. Diyecekler ki kim tekrar hayata getirecek bizi? De ki: İlk defa sizi yaratan. Alay ederek başlarını sallayacaklar da ne zaman olacak bu iş diyecekler; de ki: Umarım ki pek yakında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 52, 'O gün sizi çağıracak, hamd ederek icabet edeceksiniz ona ve sanacaksınız ki pek az bir müddet kalmışsınız dünyada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 53, 'Kullarıma söyle: Sözün en güzelini söylesinler. Şüphe yok ki Şeytan, aralarına fesat sokar. Şüphe yok ki Şeytan, insana apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 54, 'Rabbiniz, sizi daha iyi bilir; dilerse acır size, yahut dilerse azap eder size ve seni, onların amellerini gözetmek, onları korumak için göndermedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 55, 'Ve Rabbin pek iyi bilir ne varsa göklerde ve yeryüzünde. Andolsun ki bazı peygamberleri bazısından üstün ettik ve Davud''a Zebur''u verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 56, 'De ki: Allah''tan başka mabut sandıklarınızı çağırın, onlar, sizden ne bir zararı defedebilirler, ne onu çevirmeye güçleri yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 57, 'Onların taptıkları, öyle varlıklar ki bizzat kendileri de hangisi daha yakın acaba diye Rablerine ulaşmak için bir vesile arayıp durmadalar, onun rahmetini ummadalar ve azabından korkmadalar. Şüphe yok ki Rabbinin azabı, çekinip kaçınmaya değer bir azaptır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 58, 'Hiçbir şehir yoktur ki biz o şehri, kıyametten önce helak edip hak ile yeksan etmeyelim, yahut şiddetli bir azaba uğratmayalım. Bu, kitapta yazılmıştır, taktir edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 59, 'Bizi, mucizeler göndermekten meneden şey, ancak evvelki ümmetlerin, onları yalanlamalarıdır ve Semud''a apaçık bir mucize olarak dişi deveyi verdik de zulmettiler ona ve biz ayetleri, ancak korkutmak için göndeririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 60, 'An o zamanı, hani sana demiştik ki hiç şüphe yok, Rabbin, insanları çepeçevre kuşatmıştır ve biz sana gösterdiğimiz rüyayı da, Kur''an ''daki lanetlenmiş ağacı da ancak insanları sınamak için gösterdik ve onları korkutmadayız, fakat bu, ancak onların taşkınlıklarını arttırmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 61, 'Hani bir zaman meleklere, Âdem''e secde edin demiştik de İblis''ten başka hepsi secde etmişti ve o, balçıktan yarattığın mahluka secde mi edeyim demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 62, 'Bildir bana demişti, benden daha şerefli ve yüce olarak yarattığın bu mahluk kimdir? Kıyamet gününedek yaşatırsan beni andolsun ki pek azı müstesna, onun soyunu azdıracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 63, 'Git demişti, kim sana uyarsa onlardan, hepinizin de cezası cehennemdir gerçekten ve o ceza, noksansız, tastamam bir ceza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 64, 'Onlardan kime gücün yeterse seslen, oynat yerinden onu, atlı, yaya, bütün ordunla yürü üstlerine, malda, evlatta ortak ol onlarla ve vaadet onlara ve Şeytan, yalandan başka bir şey vaat edemez ki onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 65, 'Şüphe yok ki gerçek kullarımın üstünde hiçbir hükmün yoktur, onlara karşı hiçbir gücün olmaz senin ve Rabbin, koruyucu olarak yeter onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 66, 'Rabbiniz, öyle bir Rabdir ki lütuf ve ihsanını arayın diye sizin için denizde gemileri yürütür. Şüphe yok ki o, size rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 67, 'Denizde bir zarara uğradınız mı tapıp çağırdıklarınızın hepsi kaybolup gider, ancak o kalır. Sizi kurtarıp karaya çıkardı mı da yüz çevirirsiniz ve insan, pek nankördür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 68, 'Emin misiniz sizi herhangi bir yerde orasıyla beraber yere geçirmeyeceğinden, yahut üstünüze taşlıtopaçlı bir kasırga göndermeyeceğinden? Sonra bir koruyucu da bulamazsınız kendinize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 69, 'Yoksa emin misiniz bir kere daha sizi denize döndürüp üstünüze kırıp döken bir fırtına yollamayacağından ve nankörlüğünüze karşı sizi sulara gark etmeyeceğinden? Sonra bizden öcünüzü alacak bir kimse de bulamazsınız kendinize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 70, 'Andolsun ki biz Âdemoğullarını üstün ettik,karada suda taşıdık onları, tertemiz şeylerle rızıklandırdık onları ve yarattıklarımızın çoğundan üstün ettik onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 71, 'O gün, herkesi, her topluluğu, uydukları kişilerle beraber çağıracağız. Gerçekten de kitabı, sağ eline verilenler, çekirdekteki kıl kadar bile zulüm görmeden kitaplarını okuyacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 72, 'Ve burada kör olan, ahirette de kördür ve yolunu da tam sapıtmıştır, şaşırmış gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 73, 'Onlar, sana vahyettiğimizden başka şeyler düzüp bize iftira etmen için az kaldı ki seni bile fitneye düşüreceklerdi ve o vakit seni dost edineceklerdi işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 74, 'Sana sebat etme kabiliyeti vermeseydik andolsun ki birazcık meyledecektin onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 75, 'Eğer bunu yapsaydın hayatın acısını da iki kat olarak tattıracaktık sana, ölümün acısını da iki kat, sonra da bize karşı hiçbir yardımcı bulamayacaktın kendine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 76, 'Onlar, nerdeyse seni yurdundan çıkarmak için taciz edip duracaklar, fakat sen çıktıktan sonra arkandan onlar da pek az bir müddet kalacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 77, 'Senden önce gönderdiğimiz peygamberler hakkındaki yolyordam da buydu ve yolumuzda yordamımızda bir değişiklik bulamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 78, 'Ve namaz kıl güneşin zeval vaktinde, geceleyin karanlık basınca ve fecir çağında; şüphe yok ki sabah namazı, meleklerin tanık olduğu bir namazdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 79, 'Gecenin bir kısmında uyanıp namaz kıl, bu namaz, sana mahsustur ve farz namazlardan fazla bir namazdır. Umulur ki Rabbin, seni Makamı Mahmud''a sahip kılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 80, 'Ve de ki: Ya Rabbi, beni gireceğim yere gerçek olarak sok, çıkacağım yerden gerçek olarak çıkar ve katından, bana yardım eden bir kudret, kuvvet ver.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 81, 'Ve de ki: Gerçek geldi, batıl yok olup gitti, şüphe yok ki batıl, zaten yok olur gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 82, 'Ve biz, Kur''an''dan, inananlara şifa ve rahmet olan ayetleri indirmedeyiz ve bunlar, zalimlerin ancak ziyanlarını arttırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 83, 'İnsana nimet verdik mi yüz çevirir, uzaklaşır, fakat bir şerre uğradı mı ümidini tamamıyla keser, yeise düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 84, 'De ki: Herkes huylandığı huya göre hareket eder. Gerçekten de Rabbiniz, en doğru yolu kim bulmuştur, pek iyi bilir onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 85, 'Ve sana ruhu soruyorlar; de ki: Ruh, Rabbimin işindendir, hakındandır ve zaten size pek az bir bilgiden başka bir şey de verilmemiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 86, 'Ve dilersek sana vahyettiğimizi senden de gidermeye muktediriz, sonra bize karşı onu koruyacak bir kimse de bulamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 87, 'Ancak Rabbinin rahmeti onu korumuştur; gerçekten de onun lütfü, ihsanı pek büyüktür sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 88, 'De ki: İnsanlar ve cinler, bu Kur''an''ın bir benzerini meydana getirmek için bir araya gelseler bir benzerini meydana koyamazlar, hatta bir kısmı bir kısmına yardım etse bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 89, 'Andolsun ki bu Kur''an''da insanlara bütün örnekleri tekrartekrar anlattıksa da insanların çoğu kabul etmedi, ancak küfre kapıldı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 90, 'Dediler ki: Bize yeryüzünden bir kaynak çıkarıp akıtmadıkça inanmayız sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 91, 'Yahut hurma fidanlarıyla, üzüm çotuklarıyla dolu bir bahçen olup içinde de ırmaklar gürülgürül akmadıkça.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 92, 'Yahut umduğun gibi göğü, parçaparça üstümüze düşürmedikçe, yahut Allah''la melekleri karşımıza getirmedikçe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 93, 'Yahut altından yapılma bir evin olmadıkça, yahut da gökyüzüne gözümüzün önünde çıkmadıkça ve bunu yapsan bile herbirimize gökten yazılı bir kitap indirmedikçe ve biz, onu okumadıkça gene gerçeklemeyiz, seni, gene inanmayız sana. De ki: Rabbimi tenzih ederim, ben neyim, ancak insan bir peygamber.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 94, 'Fakat kendilerine doğru yolu gösteren bir peygamber geldi mi insanları inanmaktan meneden şey de Allah, hiçbir insanı peygamber olarak gönderir mi demeleridir zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 95, 'De ki: Yeryüzünde melekler bulunsaydı da rahatrahat gezselerdi onlara gökten bir meleği peygamber olarak gönderirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 96, 'De ki: Benimle sizin aranızda tanık olarak Allah yeter; şüphe yok ki o, kullarından haberdardır, onları görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 97, 'Allah, kimi doğru yola sevkederse odur doğru yolu bulan ve kimi saptırırsa o çeşit adamlara ondan başka hiçbir yardımcı bulamazsın ve biz onları, kıyamet günü, yüzü koyun kapanmış olarak kör ve dilsiz haşrederiz, yurtları da cehennemdir; orasının ateşi ve harareti sakin oldukça alevini fazlalaştırır, yakaryandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 98, 'Bu da, delillerimizi inkar edip kemik haline geldikten, toz olup gittikten sonra mı yeniden yaratılacağız da dirileceğiz demelerinin karşılığı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 99, 'Görmüyorlar mı ki Allah, öyle bir mabut ki hiç şüphesiz gökleri ve yeryüzünü yaratmıştır, onların benzerini de yaratmaya gücü yeter ve onlar için bir müddet tayin etmiştir ki şüphe yok bunda. Fakat zulmedenler, kabul etmezler de ancak küfre kapılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 100, 'De ki: Rabbimin rahmet hazineleri elinizde olsaydı harcayıp tükenmeden korkar, hasislik ederdiniz, zaten de insan, pek hasistir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 101, 'Andolsun ki biz, Musa''ya dokuz tane apaçık delil vermiştik; sor İsrailoğullarına; Musa, onlara gelince Firavun ya Musa demişti, şüphe yok ki ben seni büyülenmiş sanıyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 102, 'O da, sen de biliyorsun ki demişti, bunları, insanlara apaçık deliller olmak üzere ancak göklerin ve yeryüzünün Rabbi indirmiştir ve şüphe yok ki ey Firavun, ben de seni küfriyle helak olmuş sanıyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 103, 'Onları Mısır''dan çıkarmayı kurunca onu da onunla beraber bulunanların hepsini de sulara boğduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 104, 'Ve bundan sonra İsrailoğullarına dedik ki: Yeryüzünde oturun, eğleşin, ahiret hakkındaki vaadimizin yerine gelme zamanı çatınca hepinizi derleyip tapımıza getirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 105, 'Ve biz Kur''an''ı hak ve gerçek olarak indirdik, o da hak ve gerçek hükümlerle indi ve seni de ancak müjdeci ve korkutucu olarak gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 106, 'Bir Kur''an''dır ki onu insanlara duradura, yavaşyavaş okuman için ayetayet, suresure ayırdık ve onu azarazar indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 107, 'De ki: İster inanın, ister inanmayın; bundan önce kendilerine bilgi verilenlere okundu mu onlar, yüzüstü kapanıp secde ediyorlar', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 108, 'Ve noksan sıfatlardan münezzehtir Rabbimiz diyorlar, gerçekten de Rabbimizin vaadi, yerine gelmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 109, 'Ağlayaağlaya yüzüstü yere kapanıyorlar ve Kur''an''ı dinleyiş onların gönül alçaklığını ve itaatlerini arttırıyor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 110, 'De ki: İster Allah Adıyla dua edin, ister rahman adıyla, hangi adla dua ederseniz edin, gerçekten de bütün güzel adlar, onundur ve namazında pek yüksek sesle okuma, sesini pek de yavaşlatma, ikisinin arasında bir yol tut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (17, 111, 'Ve de ki: Hamd Allah''a ki oğul edinmemiştir kendisine ve saltanatta, tasarrufta ortağı yoktur ve aciz olmadığından yardımcıya da ihtiyacı yoktur ve pek büyük bil, onu, büyüklüğünü de bildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 1, 'Hamt Allah''a ki kuluna kitap indirdi ve o kitapta hiçbir eğrilik, ifrat veya tefrit yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 2, 'Dosdoğru bir kitaptır, katından kafirlere çetin bir azap olduğunu haber verip onları korkutmak ve inanıp iyi işlerde bulunanları da onlara güzel bir mükafat olduğunu söyleyip müjdelemek için indirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 3, 'O mükafat yurdunda ebedi kalacaktır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 4, 'Ve Allah, kendisine oğul edindi diyenleri korkutmak için indirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 5, 'Ne onların bir bilgisi var, ne atalarının; ağızlarından çıkan söz, ne de büyük söz. Onlar, ancak yalan söylüyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 6, 'Şu Kur''an''a inanmadıkları ve senden yüz çevirdikleri için üzülüp hayıflanarak kendini helak mi edeceksin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 7, 'Biz, gerçekten de insanların hangisi daha iyi ve güzel iş işleyecek, bunu sınamak için yeryüzünde ne varsa, yere biz ziynet olarak halkettik onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 8, 'Ve biz, elbette yeryüzünde ne varsa hepsini kupkuru toprak haline getiririz sonunda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 9, 'Kehf ve Rakıym ashabının ahvalini, delillerimiz içinde şaşılacak bir delil mi sandın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 10, 'Hani o zaman o yiğitler, mağaraya sığınmışlardı da Rabbimiz demişlerdi, katından bir rahmet ihsan et bize ve işimizin başarıyla doğruluğa ulaşması için sebepler hazırla bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 11, 'Onları bir uykuya daldırdık, yıllarca hiçbir şey duymadılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 12, 'Sonra da iki taraftan hangisi, onların ne kadar yatıp kaldıklarını hesab edip ayırt edecek, bilelim diye tekrar onları uyandırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 13, 'Onların ahvalini gerçek olarak sana haber veriyor, hikaye ediyoruz. Şüphe yok ki onlar, Rablerine inanmışlardı ve biz de hidayetlerini arttırmıştık onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 14, 'Ve kalplerini gerçeğe bağladık kalkıp da Rabbimiz, göklerin ve yeryüzünün Rabbidir, ondan başka bir mabuda tapmayız biz ve andolsun ki böyle bir şey söyledik mi gerçekten uzaklaşmış oluruz dedikleri zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 15, 'Ve şu kavmimiz, ondan başka mabut kabul etti, bari bu hususta açık bir delilleri olsaydı, kimdir yalan yere Allah''a iftira edenden daha zalim dedikleri zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 16, 'Ve mademki dediler, onlardan ayrıldınız ve Allah''tan başkasına ibadet etmeyeceksiniz, sığının mağaraya da Rabbiniz, rahmetiyle bir genişlik versin size ve işinizde de kolaylık sebepleri hazırlasın size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 17, 'Bir görseydin, güneş doğunca ışığı, mağaralarının içine değil de sağ tarafına vurmadaydı, batarken de sol tarafına ve onlar, mağaranın geniş bir yerindeydiler ve bu, Allah''ın delillerindendir. Allah, kimi doğru yola sevk ederse odur doğru yolu bulanve kimi saptırırsa artık ona, kesin olarak doğru yolu gösterecek bir dost bulamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 18, 'Onları uyanık sanırsın, halbuki uyuyor onlar ve biz onları sağ ve sol taraflarına çevirip durmadayız ve köpekleri de mağaranın girilecek yerinde, ön ayaklarını yere uzatmış, yatmada. Hallerini anlasaydın mutlaka onlardan kaçardın ve mutlaka onların halinden korku dolardı içine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 19, 'Onları uyuttuğumuz gibi birbirlerine sormaları için öylece de uyandırdık ve içlerinden biri, ne kadar kaldık burada dedi. Bir gün uyumuşuz, yahut günün bir kısmını uykuyla geçirmişiz dediler ve Rabbiniz, daha iyi bilir dediler, ne kadar kaldığınızı, hele şimdi birinizi şu gümüş parayla şehre yollayın da yiyeceklerin hangisi daha temizse bir miktar alsın, bir rızık getirsin size, ancak çok ihtiyatlı davransın ve hiçbir kimse sizi duyup anlamasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 20, 'Çünkü anlarlar, duyarlarsa ya taşlarlar sizi, yahut da dinlerine döndürürler ve artık kesin olarak kurtulamazsınız onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 21, 'İşte böylece Allah''ın vaadinin hak ve gerçek olduğunu ve gerçekten de kıyametin kopacağını ve onda hiçbir şüphe bulunmadığını bilmeleri için, tam bu hususlarda birbirleriyle çekişip dururlarken, insanları haberdar ettik de müşrikler dediler ki: Onların bulunduğu yere bir yapı yapın, halktan gizli kalsınlar. Halbuki Rableri, onların ahvalini daha iyi bilir. Hallerine vakıf olanlarsa onların bulundukları mağaranın önüne mutlaka bir mescit yapmalıyız dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 22, 'Diyecekler ki onlar üçtü, dördüncüleri, köpekleri ve beş taneydi onlar, altıncıları köpekleri; fakat bu sözler, ortada olmayan hedefe boşuna taş atmak ve diyecekler ki yedi taneydi onlar, sekizincileri köpekleri. De ki: Onların sayısını Rabbim daha iyi bilir, onları pek az kişi bilir ancak. Artık sen de onlar hakkında sana açıkladığımıza razı ol da fazla münakaşaya, mübahaseye girişme ve onlara dair kitap hakkında bir hüküm dilemeye kalkışma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 23, 'Ve hiçbir şey hakkında da bunu mutlaka yarın yapacağım deme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 24, 'Ancak Allah dilerse yaparım de ve birşeyi unutunca Rabbini an ve de ki: Umarım, Rabbim, beni bundan daha ziyade hayra ve doğruya yakın birşeye erdirir ve başarı verir bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 25, 'Onlar, mağaralarında üç yüz yıl yatıp kaldılar ve bu yıllara dokuz yıl daha kattılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 26, 'De ki: Ne kadar yatıp kaldıklarını Allah daha iyi bilir; onundur göklerdeki ve yeryüzündeki gizli şeyler, tam görüştür onun görüşü ve tam duyuştur duyuşu. Ondan başka bir dost ve yardımcı da yoktur onlara ve hükmüne hiçbir kimseyi ortak etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 27, 'Rabbinin kitabından sana vahyedileni oku sözlerini değiştirecek yoktur ve ondan başka sığınacak bir kimseyi de bulamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 28, 'Sabah, akşam, rızasını dileyerek Rablerine dua edenlerle beraber sabret ve dünya yaşayışının ziynetini dileyenlere uyup ayırma gözlerini onlardan ve bizi anmamaları için gönüllerine gaflet verdiğimiz heva ve heveslerine uymuş ve işi hadden aşıp taşmış kişiye itaat etme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 29, 'Ve de ki: Kur''an Rabbinizden hak ve gerçek olarak inmiştir, artık dileyen inansın, dileyen inkar etsin. Şüphe yok ki biz, zalimlere öyle bir ateş hazırladık ki etrafındaki duvarlar, onları çepeçevre kuşatır, susayıp su istedikleri zaman irin gibi bir su sunulur onlara ve bu su, yüzlerini bile yakıp kavurur, ne de kötü bir sudur ve orası, ne de kötü dayanılacak, oturulacak yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 30, 'İnanan ve iyi işlerde bulunanlara gelince: Şüphe yok ki biz, iyi işlerde bulunanların, güzel hareket edenlerin ecrini zayi etmeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 31, 'Öyle kişilerdir onlar ki onlarındır ebedi Adn cennetleri, kıyılarından ırmaklar akar, orada altın bilezikler takınarak süsleneceklerdir ve ince ve kalın ipekli yeşil elbiseler giyineceklerdir, orada tahtlarda oturacaklardır ve ne hoş ve güzel bir mükafattır bu ve o tahtlar, ne de güzel dayanılacak, oturulacak yerlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 32, 'Onlara iki adamı örnek getir: Onların birine iki üzüm bağı vermiş, bağların çevresini hurma ağaçlarıyla çevirmiş ve iki bağın arasını da ekinlik haline getirmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 33, 'Bu iki bağ, daima mahsul verirdi, veriminde noksan bulunmazdı, iki bağın arasında da bir ırmak akıtmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 34, 'Daha başka da gelirleri vardı da konuşurken arkadaşına dedi ki: Ben malca da senden üstünüm, evlat ve ayalce de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 35, 'Ve bağına girdi, kendi kendisine de zulmetmedeydi, dedi ki: Şu nail olduğum mal ve menalin zeval bulup tükeneceğini hiç mi ummam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 36, 'Ve kıyametin kopacağını da ummam ama Rabbimin tapısına gönderilmiş olsam bile mutlaka bundan daha da iyi nimetler bulurum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 37, 'Onunla konuşurken arkadaşı da seni dedi, topraktan, sonra bir damla sudan yaratıp bundan sonra da tam, azası düzgün bir insan haline getireni inkar mı ediyorsun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 38, 'Fakat ben, Rabbim olan Allah''ı inkar etmem ve Rabbime hiçbir varlığı eş tutmam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 39, 'Bağına girdiğin zaman Allah, neyi dilerse o olur, kuvvet, ancak Allah''ındır deseydin ya. Beni malca, evlatça senden düşkün gördün ama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 40, 'Umarım ki Rabbim, bana seninkinden daha hayırlı bir bağ verir, senin bağına da yıldırımlar yollar gökten de kaypak, kaygan bir toprak oluverir bağın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 41, 'Yahut da suyu öylesine çekilir ki onu arayıp bulmaya bile gücün yetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 42, 'Derken serveti mahvoldu da çardakları çökmüş, yerle bir olmuş bağında ellerini uğuşturarak keşke Rabbime hiçbir varlığı eş, ortak olarak tanımasaydım demeye başladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 43, 'Ona Allah''tan başka yardım edecek bir topluluk olmadığı gibi onun da bu zararı gidermeye bir kudreti yoktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 44, 'İşte bu makamda yardım ve nusret, ancak Allah''ındır ve ona itaat, hem mükafat bakımından daha hayılıdır, hem son bakımından daha hayırlı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 45, 'Onlara örnek getir: Dünya yaşayışı, gökten yağdırdığımız yağmura benzer, yeryüzünün nebatlarını sular, bünyelerine girer de onları yeşertir, yetiştirir, derken nebatlar kurur, ufalanır, yeller de onları savurur gider ve Allah''ın her şeye gücü yeter, hiçbir şeyden aciz değildir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 46, 'Mal ve oğullar, dünya yaşayışının ziynetidir. Ebedi olarak kalan hayır ve hasenatsa hem mükafat bakımından Rabbinin katında daha hayırlıdır, hem sonucu bakımından daha hayırlı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 47, 'Ve o gün dağları yerinden sökeriz ve görürsün ki yeryüzü dümdüz olmuş ve onları diriltiriz, haşrederiz, hiçbir tanesini bırakmayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 48, 'Hepsi de safsaf Rabbine arz edilir, andolsun ki der, önce nasıl yarattıysak sizi öylece geldiniz tapımıza; size muayyen bir zaman tayin etmedik mi sandınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 49, 'Kitap ortaya konmuştur, suçluları görürsün ki o kitapta yazılı olan şeyler yüzünden korku içinde ve eyvahlar olsun bize derler, ne biçim kitap bu, ne küçük bir şey bırakmış, ne büyük, hepsini de sayıp dökmüş ve ne yaptılarsa hepsini de karşılarında bulurlar ve Rabbin hiçbir kimseye zulmetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 50, 'An o zamanı hani biz meleklere, secde edin Âdem''e demiştik de İblis''ten başka hepsi secde etmişti, o, cin cinsindendi de Rabbinin emrinden çıkmıştı. Beni bırakıp da onu ve soyunu, dost mu ediniyorsunuz, halbuki onlar, size düşmandır; Allah''ı bırakıp Şeytanı dost edinmek, zalimler için ne de kötü bir değişme muamelesidir bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 51, 'Ne göklerle yerin yaratılışına tanık ettik onları, ne kendilerinin yaratılışına. İnsanları doğru yoldan saptıranları da yardımcı edinmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 52, 'Ve o gün bana eş ve ortak sandıklarınızı çağırın der de çağırırlar ama onlar icabet etmez ve aralarına cehennemde derin bir uçurum koymuşuzdur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 53, 'Ve suçlular cehennemi görürler de içine düşeceklerini anlarlar ama oradan savuşup gidecek bir yer bulamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 54, 'Andolsun ki biz bu Kur''an''da, insanlara her çeşit örneği tekrartekrar açıkça anlatmadayız ve insan, her mahluktan daha fazla mücadelecidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 55, 'İnsanları, kendilerine hidayet geldikten, doğru yol bildirildikten sonra da inanmaktan ve Rablerinden yarlıganma dilemekten meneden şey, ancak evvelkiler hakkındaki yolun, yordamın, dünyada helak edilişin gelmesini, yahut da apaçık bir surette ahiret azabının gelip çatmasını bekleyiş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 56, 'Ve biz, peygamberleri ancak müjdeci, korkutucu olarak göndeririz. Kafir olanlar, hakkı batılla gidermek için çalışırlar, çekişirler, ayetlerimizi ve kendilerine verilen korkulu haberleri alaya alırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 57, 'Rabbinin ayetleriyle kendisine öğütler verildiği halde onlardan yüz çeviren ve elleriyle hazırladığı şeyi unutan kişiden daha zalim kimdir ki? Gerçekten de biz, onların anlamamaları için gönüllerine perdeler gerdik ve kulaklarını ağırlaştırdık ve onları doğru yola çağırsan da imkan yok doğru yola gelmez onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 58, 'Ve Rabbin, suçları örter, rahmet sahibidir. Kazandıklarına karşılık onları helak ediverse çabucak azap ederdi; fakat onlara vaadedilmiş mukadder bir zaman var, o zaman geldi mi, ondan başka sığınacak hiçbir makam bulamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 59, 'İşte zulmettikleri için helak ettiğimiz bunca şehir ve biz, onların helaki için de mukadder bir zaman tayin etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 60, 'An o zamanı ki Musa, genç arkadaşına, ben demişti, iki denizin kavuştuğu yeredek durmadan, dinlenmeden gideceğim, yahut da yıllarca bu uğurda uğraşacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 61, 'İki denizin kavuştuğu yere vardıkları zaman balıklarını unutmuşlardı; balık, denize atlamış, dalıp bir yol tutmuş gitmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 62, 'Oradan geçtikten sonra Musa, genç arkadaşına kuşluk yemeğimizi getir dedi, gerçekten de şu yolculuk, yordu bizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 63, 'Arkadaşı, gördün mü dedi, kayanın üstünde oturduğumuz zaman balığı unutmuştum; onu bana unutturan ve sana söylememe mani olan da ancak Şeytan''dır; balık, şaşılacak bir surette denizde bir yoldur tuttu, dalıp gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 64, 'Musa, buydu aradığımız işte dedi ve kendi izlerini izleyerek geri döndüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 65, 'Derken kullarımızdan bir kulu buldular ki biz, katımızdan ona rahmet ihsan etmiştik ve katımızdan ilim belletmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 66, 'Musa, ona, sana öğretilen gerçek bilgiden bana da öğretmen şartıyla sana uyayım mı dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 67, 'O, sen dedi, benimle beraber bulunmaya dayanamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 68, 'İç yüzünü kavramana imkan olmayan birşeye nasıl sabredebilirsin ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 69, 'Musa, Allah dilerse dedi, görürsün, sabredeceğim ve hiçbir hususta sana isyan etmeyeceğim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 70, 'O, bana uyarsan dedi, sana ona ait bir söz söyleyinceyedek hiçbir şey sorma bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 71, 'Derken kalkıp yola düştüler, nihayet bir gemiye bindiler, o zat, gemiyi deldi. Musa, içindekileri boğmak için mi gemiyi deldin dedi, andolsun ki pek kötü bir iş yaptın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 72, 'O zat, demedim mi dedi, gerçekten de sen, benimle beraber bulunmaya dayanamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 73, 'Musa, unuttum dedi, bu yüzden azarlama beni ve şu arkadaşlığımızda ağır bir yük yükleme bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 74, 'Gene yola düştüler, derken bir erkek çocuğa rastladılar, o zat, çocuğu öldürdü. Musa bir cana kıymamışken tuttun, tertemiz birisini öldürdün, andolsun ki pek kötü ve menedilmiş bir şey yaptın sen dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 75, 'O, demedim miydi sana dedi, gerçekten de sen, benimle beraber bulunmaya dayanamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 76, 'Musa, bundan sonra dedi, sana bir şey sorarsam benimle arkadaş olma artık, bir daha bir şey sorarsam benden ayrılmada gerçekten de mazursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 77, 'Gene yola düştüler. Bir şehre geldiler, halkından yemek istedilerse de onları konuklayıp doyuran bir tek kişi bile çıkmadı. Orada bir duvar buldular, yıkılmak üzereydi. O zat, duvarı doğrulttu. Musa, dileseydin dedi, bu hizmete karşılık bir ücret alırdın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 78, 'O zat, işte dedi, seninle benim aramda artık ayrılık bu. Sabredemediğin şeylerin iç yüzünü haber vereyim sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 79, 'Gemi, denizde çalışan yoksul kimselerindi, onu kusurlu bir hale getirmek istedim, çünkü ilerde bir padişah var, bütün gemileri zaptetmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 80, 'Çocuğa gelince: Anası, babası inanmış kimseler. Bu çocuğun, onları azgınlığa ve kafirliğe sevketmesinden korktuk da öldürdük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 81, 'Rablerinin onlara, bu çocuğun yerine temizlikte daha ileri, merhametçe daha duygulu bir çocuğu vermesini diledik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 82, 'Duvarsa, şehirdeki iki yetim çocuğundu ve altında, onlara ait bir define vardı, babaları da temiz bir adamdı. Rabbin, onların ergenlik çağına gelmelerini ve definelerini çıkarıp elde etmelerini diledi. Bunları kendiliğimden yapmadım. İşte sabredemediğin şeylerin iç yüzü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 83, 'Sana Zülkarneyn''i sorarlar. De ki: Ona ait haberleri de okuyalım size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 84, 'Biz, gerçekten de onu yeryüzünde yerleştirip yüceltmiştik, her şeyin yolunayoradamına ait ne bilgi varsa vermiştik ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 85, 'O, batıya doğru bir yol tutmuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 86, 'Nihayet güneşin battığı yere gelince görmüştü ki güneş, kara bir balçığa batmada ve orada bir topluluğa rastladı. Dedik ki: Ey Zülkarneyn, istersen azaplandırırsın bunları, istersen iyilik edersin onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 87, 'Dedi ki: Zulmedeni azaplandırırız, sonra da Rabbinin tapısına götürülür de Rabbi, onu şiddetli bir azaba uğratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 88, 'Fakat inanan ve iyi iş işleyene güzel bir karşılık var ve biz ona emirlerimizden kolay olanını emredecek, o çeşit emirler vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 89, 'Sonra, bir yol daha tuttu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 90, 'Da gidegide güneşin doğduğu yere vardı, orada öyle bir topluluk buldu ki onların güneşten başka hiçbir elbisesi yoktu, öyle bir topluluğa doğmadaydı güneş orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 91, 'Böyleydi işte bu, gerçekten de nesi var, nesi yoksa bilgimiz hepsine şamildir, hepsinden de haberdarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 92, 'Sonra gene bir yol tuttu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 93, 'Ta iki setin arasına vardı, onların yanında bir topluluk buldu ki hemen hiçbir söz anlamıyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 94, 'Dediler ki: Ey Zülkarneyn, Ye''cuc''la Me''cuc, yeryüzünde bozgunculuk yapan taifelerdir, onlarla bizim aramıza bir set yapmak şartıyle sana mallarımızdan versek razı olur musun, yapar mısın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 95, 'Rabbimin bana verdiği devlet ve servet, daha hayırlıdır bana dedi, siz bana emeğinizle yardım edin de aranıza bir sed yapayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 96, 'Siz bana demir parçaları getirin. Dağların iki tarafı birbirine müsavi olunca üfleyin dedi. Onu ateş haline sokunca da getirin de dedi, üstüne erimiş bakır dökeyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 97, 'Artık bu seti aşmaya da güçleri yetmez, delmiye de güçleri yetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 98, 'Bu dedi, Rabbimin rahmetinden bir lütuf. Rabbimin vaadettiği zaman gelince bu seti dümdüz yapar, yerle bir eder ve Rabbimin vaadi de gerçektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 99, 'O gün deniz gibi dalgalanır, dalgadalga birbirlerine karışır onlar ve sur üfürülür de onların hepsini toplarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 100, 'Ve o gün kafirlere, cehennemi öyle bir gösteririz ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 101, 'Onların delillerimi görüp beni anmak hususunda gözleri perdelenmişti ve Kur''an''ı dinlemeye tahammülleri yoktu onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 102, 'Kafir olanlar, benden başka ve kullarımdan, kendilerine yardımcı edindiklerini mi sandılar? Biz, kafirlere, konak yeri olarak cehennemi hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 103, 'De ki: İşledikleri işler bakımından en fazla ziyan edenler kimlerdir, haber vereyim mi size?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 104, 'Onlardır en fazla ziyan edenler ki dünya yaşayışında bütün çalışmaları boşa gider, halbuki onlar, gerçekten de kendilerinin iyilik ettiklerini, iyi işlerde bulunduklarını sanırlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 105, 'Onlardır kafir olanlar Rablerinin delillerine ve ona ulaşacaklarını inkar edenler, bütün yaptıkları boşa gitmiştir ve biz, kıyamet günü onları hiçbir ölçüye vurmayız, onlara hiçbir değer vermeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 106, 'Bu, cezaları olan cehennemdir kafir olduklarından ve delillerimle peygamberlerimi alaya aldıklarından dolayı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 107, 'İnanıp iyi işlerde bulunanların konak yerleriyse Firdevs cennetleridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 108, 'Orada ebedi olarak kalırlar ve oradan ayrılmak da istemezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 109, 'De ki: Deniz mürekkep olsa tükenir, yazılmaz Rabbimin sözleri tükenmeden, hatta o deniz kadar bir deniz daha eklense gene tükenir, yazılamaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (18, 110, 'De ki: Ben de ancak sizin gibi bir insanım, bana vahyedildiki mabudunuz ancak ve ancak bir mabuttur, arttık Rabbiyle buluşmayı uman iyi işlerde bulunsun ve Rabbinin kulluğunda hiçbir kimseyi eş tutmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 1, 'Kaf ha ya ayn sad.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 2, 'Bu, kulu Zekeriyya''ya Rabbinin rahmetini anıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 3, 'Hani o, gizlice Rabbine niyaz etmişti de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 4, 'Demişti ki: Rabbim, kemiklerim bile incelip zayıfladı, saçımsakalım ağardı, parılparıl parlamada başım sanki ve sana ne dua etmişsem mahrum olmadım ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 5, 'Benden sonra yerime geçecek, mirasıma konacak yakınlarımdan endişelenmekteyim, karım da kısır, sen bana katından bir oğul ihsan et de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 6, 'Bana da mirasçı olsun, Yakup soyuna da mirasçı olsun ve Rabbim, onu, rızanı kazanmışlardan et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 7, 'Ey Zekeriyya, biz seni müjdelemekteyiz, bir oğlun olacak, adı da Yahya''dır ve ondan önce bu adla adlanmış hiç kimseyi yaratmadık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 8, 'Rabbim dedi, benim nasıl oğlum olabilir ki karım kısır ve ben de ömrümün sonlarına vardım, tamamıyla ihtiyarladım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 9, 'Böyledir bu dedi, Rabbine dedi, bu pek kolay ve sen yokken evvelce de seni yaratmıştım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 10, 'Rabbim dedi, bana bir delil göster. Sıhhatin yerindeyken dedi, tam üç gece insanlarla konuşamayacaksın, işte bu, sana delildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 11, 'Zekeriyya, mihraptan çıkıp kavmine, sabahakşam onu tenzih edin noksan sıfatlardan diye işaret etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 12, 'Ey Yahya, azim ve kuvvetle kitabı al. Ve ona çocukken peygamberlik verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 13, 'Katımızdan ona bir kalb yumuşaklığı, bir temizlik ihsan ettik ve o, mabudundan çekinirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 14, 'Anasınababasına iyilik ederdi ve cebbar ve asi değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 15, 'Ve esenlik ona doğduğu gün, öldüğü gün ve diriltilerek kabrinden çıkarılacağı gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 16, 'Kitapta Meryem''i de an. Hani o, ailesinden ayrılmış, doğu tarafında bir yere çekilmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 17, 'Ve ailesiyle arasına bir perde germişti. Derken ona ruhumuzu göndermiştik de gözüne, azası düzgün bir insan şeklinde görünmüştü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 18, 'O, fenalıklardan çekinen bir adamsan demişti, rahmana sığınırım senden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 19, 'Ruh, ben demişti, ancak Rabbinin bir elçisiyim, sana bir erkek çocuk vermeye geldim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 20, 'Meryem, benim nasıl oğlum olabilir ki hiç bir kimse, henüz bana dokunmadı demişti, hem kötü bir kadın da değilim ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 21, 'Böyledir bu demişti ruh, bu iş, Rabbin için pek kolay demişti. Çünkü biz, onu insanlara bir delil ve katımızdan bir rahmet olarak halkedecektik ve bu iş, zaten de mukadderdi, olup bitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 22, 'Sonunda ona gebe kaldı ve onunla uzak bir yere çekilip gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 23, 'Derken doğum sancısı, onu bir hurma ağacının dibine sevketti de keşke dedi, bundan önce ölseydim de unutulup gitseydim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 24, 'Uzaktan bir ses geldi ona: Mahzun olma, Rabbin, ayağının altından bir ırmak akıttı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 25, 'Hurma ağacını silk, sana terütaze hurmalar dökülecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 26, 'Ye, iç, gözün aydın. Fakat seni birisi görürse ben de, bugün rahman için oruç tutmadayım ve hiçbir kimseyle kesin olarak konuşamam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 27, 'Çocuğunu kucağına alıp kavmine gelince ey Meryem dediler, gerçekte de pek büyük bir iş işledin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 28, 'Ey Harun''un kız kardeşi, baban, fena bir adam değildi, anan da kötü bir kadın değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 29, 'Meryem, çocuğuna işaret etti. Nasıl olur da dediler, beşikteki çocuk konuşur?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 30, 'İsa, Şüphe yok ki dedi, ben Allah''ın kuluyum, bana kitap vermiştir ve beni peygamber etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 31, 'Ve Nerede olursam olayım kutlamıştır beni ve diri oldukça namaz kılmamı, zekat vermemi emretmiştir bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 32, 'Ve anama itaatli etmiştir beni ve cebbar, kötü kişi olarak yaratmamıştır beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 33, 'Esenlik bana doğduğum gün, öleceğim gün ve tekrar dirilip kabirden çıkacağım gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 34, 'İşte budur Meryemoğlu İsa. Onların şüpheye düştükleri şey hakkında gerçek söz, budur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 35, 'Evlat edinmesi, layık değildir Allah''a, noksan sıfatlardan münezzehtir o. Bir işin olmasını takdir etti mi ona ancak ol der, oluverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 36, 'Ve şüphe yok ki Allah, Rabbimdir ve Rabbiniz, ona kulluk edin; budur doğru yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 37, 'Aralarından bölükler ayrıldı, ayrılığaaykırılığa düştüler. Ulaşıp görecekleri büyük günün şiddetli azabı kafirlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 38, 'Neler duyacaklar, neler görecekler bize geldikleri gün; fakat zalimler, bugün, apaçık bir sapıklıkta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 39, 'Onları hasret günüyle korkut; iş olup biter o zaman ve onlar, şimdi gaflettedir ve onlar, inanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 40, 'Şüphe yok ki biziz yeryüzünün ve yeryüzünde olanların mirasçısı ve dönüp bizim tapımıza gelir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 41, 'Kitapta İbrahim''i de an. Şüphe yok ki o, çok gerçek bir peygamberdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 42, 'Hani o atasına ata demişti, ne diye taparsın duymaz, görmez, senden hiçbir şeyi gideremez şeylere?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 43, 'Gerçekten de ata, sence bilinmeyen bir bilgiye sahip oldum ben, artık bana uy da seni dosdoğru yola ileteyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 44, 'Ata, Şeytan''a kulluk etme, şüphe yok ki Şeytan, rahmana asidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 45, 'Ata, gerçekten de korkuyorum, sana rahmandan bir azap gelip çatar da Şeytan''a dost olursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 46, 'Atası, ey İbrahim dedi, benim mabutlarımdan yüz mü çevirmedesin? Bu işten vazgeçmezsen taşlarım seni, uzun bir zaman görünme, git, bırak beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 47, 'İbrahim, esenlik sana dedi, Rabbimden yarlıganmanı dileyeceğim, şüphe yok ki o, pek lutfeder bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 48, 'Ve sizi ve Allah''tan başka kulluk ettiğiniz şeyleri bırakıyor ve Rabbime dua ediyorum, umarım ki duamı kabul eden, mahrum etmez beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 49, 'Onların ve Allah''tan başka kulluk ettikleri şeyleri bırakınca ona İshak''ı ve Yakup''u verdik ve hepsini de peygamber ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 50, 'Ve onlara rahmetimizden ihsanlar ettik, gerçek şöhretlerini yaydık, adlarını yücelttik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 51, 'Kitapta Musa''yı da an; şüphe yok ki o, ihlasa mazhar olmuş şeriat sahibi bir peygamberdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 52, 'Ona, Tur''un sağ yanından nida ettik, bizimle konuşmak üzere tapımıza yaklaştırdık onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 53, 'Rahmetimizden bir lütuf olarak kardeşi Harun''u da peygamber ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 54, 'Kitapta İsmail''i de an; şüphe yok ki o, vaadinde gerçekti ve insanlara gönderilmiş olan bir peygamberdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 55, 'Ehline, ayaline namaz kılmalarını, zekat vermelerini emrederdi, Rabbinin katından da rızasını kazananlardandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 56, 'An kitapta İdris''i de; şüphe yok ki o çok gerçek bir peygamberdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 57, 'Biz onu pek yüce bir mevkie yükselttik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 58, 'İşte bunlar, Âdem soyundan, Nuh''la beraber gemiye yüklediklerimizin soylarından, İbrahim''in ve İsrail''in soylarından gelen ve Allah tarafından kendilerine nimetler ihsan edilen peygamberlerdendir, doğru yola sevkettiğimiz ve seçtiğimiz kişilerdendir. Rahmanın ayetleri, onlara okundu mu ağlayaağlaya hemen secdeye kapanırlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 59, 'Onlardan sonra öyle bir soy geldi ki namazı zayi etti onlar, şehvetlere uydular, azınlıklarının cezasına pek yakında uğrayacak onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 60, 'Ancak tövbe eden, inanan ve iyi işlerde bulunan müstesna. Bu çeşit kişiler cennete girerler ve hiçbir hususta zulüm görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 61, 'Ebedi Adn cennetlerine girerler ki rahman, kullarının gıyabında, onlara vaadetmiştir bu cennetleri. Şüphe yok ki onun vaadi, mutlaka yerine gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 62, 'Orada manasız bir söz işitmeyecekler, ancak esenlik size sözünü duyacaklar ve sabahakşam, rızıkları gelecek onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 63, 'Öylesine cennettir ki kullarımızdan kim, bizden çekinirse ona miras vereceğiz o cenneti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 64, 'Biz melekler, ancak Rabbinin emriyle inebiliriz; onundur ne varsa ilerimizde ve ne varsa gerimizde ve ne varsa ikisi arasında ve Rabbin, hiçbir şeyi unutmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 65, 'Rabbidir göklerin ve yeryüzünün ve ikisi arasında ne varsa hepsinin, ona kulluk et ve dayan ona ibadet etmede, onun Adıyla anılan başka bir varlık bilir misin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 66, 'Ve insan der ki: Ben öleceğim de sonra dirilip kabirden mi çıkarılacağım?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 67, 'İnsan hiç mi düşünmez ki o hiçbir şey değilken daha önce biz yarattık onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 68, 'Andolsun Rabbine onları da, Şeytanları da haşredeceğiz de sonra onları, diz çökmüş bir halde cehennemin çevresine getireceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 69, 'Sonra hangi taife, rahmana karşı en fazla azgınlıkta bulunduysa onu ayırıp önce cehenneme atacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 70, 'Sonra elbette biz daha iyi biliriz cehenneme girmeye daha layık olanı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 71, 'Sizden bir tek kişi bile yoktur ki oraya uğramasın; bu, Rabbinin takdir ettiği bir şeydir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 72, 'Sonra çekinenleri kurtarırız, zalimleriyse dizüstü çökmüş bir halde bırakırız orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 73, 'Onlara ayetlerimiz, apaçık okununca kafir olanlar, iki bölükten dediler, hangisinin durağı daha hayırlı, meclisi daha güzel?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 74, 'Onlardan önce nice ümmetler helak ettik ki mal bakımından da daha güzel mallara sahipti onlar, gösteriş bakımından da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 75, 'De ki: Kim sapıklıktaysa rahman, onun sapıklığını uzattıkça uzatır da sonunda azap olsun, kıyamet olsun, kendilerine vaat olunan şeyi görür bu çeşit adamlar ve görünce de bilirler kimin yurdu daha hayırlıymış ve kimin kuvveti daha zayıf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 76, 'Ve Allah, hidayete erenlerin hidayetini arttırdıkça arttırır ve ebedi kalacak iyi işler, Rabbinin katında sevapça da daha hayırlıdır, sonuç bakımından da daha hayırlı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 77, 'Gördün mü delillerimizi inkar edeni ve elbette bana mal da verilecek, evlat da diyeni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 78, 'Gizli olan bir şeyi mi anlamış, yoksa rahmandan bir söz mü almış?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 79, 'Haşa söylediğini yazarız onun ve azabını uzattıkça uzatırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 80, 'Söylediği şeylere biz mirasçı oluruz ve o bize yapayalnız gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 81, 'Onlar, kendilerine bir yücelik versinler, şefaatçi olsunlar diye Allah''tan başka mabutlar kabul etmişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 82, 'Haşa. Onların kulluğunu inkar edecek o mabut sandıkları şeyler ve onlara düşman kesilecek onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 83, 'Görmez misin, biz kafirlere. onları boyuna taciz edecek Şeytanlar gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 84, 'Onların azaba uğraması için acele etme, biz ancak yıllarını, günlerini saymadayız onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 85, 'O gün, çekinenleri bölükbölük, rahmanın huzurunda haşrederiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 86, 'Ve mücrimleri susamış bir halde cehenneme sevk ederiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 87, 'Rahmandan ahd almış olanlardan başkaları şefaat de edemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 88, 'Ve dediler ki: Rahman, oğul edindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 89, 'Andolsun ki pek çirkin bir söz söylediniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 90, 'Öylesine bir söz ki neredeyse gökler parçalanacak ve yer yarılacak ve dağlar dağılıp çökecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 91, 'Rahmanın oğlu var demeleri yüzünden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 92, 'Rahmana oğul edinmek yaraşmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 93, 'Göklerde ve yerde ne varsa hepsi de rahmanın tapısına kul olarak gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 94, 'Andolsun ki hepsini topluluk bakımından da saymıştır, tektek de ve hepsini, hepsinin ahvalini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 95, 'Ve hepsi de kıyamet günü, onun tapısına yapayalnız gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 96, 'Şüphe yok ki inanan ve iyi işlerde bulunanlara karşı rahman, gönüllere bir sevgidir verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 97, 'Gerçekten de biz, ancak çekinenleri müjdelemen, düşmanlıkta inat ve ısrar edenleri korkutman için Kur''an''ı, senin dilinle indirerek kolaylaştırdık sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (19, 98, 'Onlardan önce nice ümmetleri helak ettik. Onlardan bir kişiyi bile duyuyor musun, yahut bir tanesinin olsun, sesini işitiyor musun?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 1, 'Taha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 2, 'Kur''an''ı zahmet çekmen için indirmedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 3, 'Ancak, korkacaklara bir öğüt olarak indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 4, 'Yeryüzünü ve yüce gökleri yaratanın katından indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 5, 'Rahman, hakim ve mutasarrıftır arşa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 6, 'Onundur ne varsa göklerde ve ne varsa yeryüzünde ve ne varsa ikisinin arasında ve ne varsa yerin altında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 7, 'Sesini yükseltsen de, yükseltmesen de hiç şüphe yok ki o, gizliyi de bilir, açığa vurulanı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 8, 'Bir Allah''tır ki yoktur ondan başka tapacak, onundur güzel adlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 9, 'Musa hikayesi ulaşmadı mı sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 10, 'Hani bir ateş görmüştü de ailesine durun demişti, ben bir ateş görüyorum, ya gider, bir kor getiririm oradan size, yahut birine rastlarım da yol öğrenirim ateş başında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 11, 'Ateşe doğru gidince ona seslenildi: Ey Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 12, 'Şüphe yok ki benim senin Rabbin, çıkar ayakkabılarını, kutlu vadidesin, Tuva''dasın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 13, 'Ve seni seçtim ben, dinle vahyedileni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 14, 'Şüphe yok ki ben öyle bir Allah''ım, yoktur benden başka tapacak, bana kulluk et ancak ve namaz kıl beni anmak için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 15, 'Kıyamet gelip çatmada gerçekten de; herkes, yaptığının karşılığını bulsun diye gizlemekteyim vaktini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 16, 'Ona inanmayan ve havasına uyup giden, sakın seni inancından çevirmesin, yoksa helak olursun sen de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 17, 'Sağ elindeki nedir ey Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 18, 'Sopam dedi, ona dayanırım, davarlarıma yaprak silkerim onunla, başka işler de yaparım onunla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 19, 'Dedi ki: Elinden bırak onu ey Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 20, 'Bıraktı onu, bir de baktı ki bir yılan olmuş, koşup durmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 21, 'Al onu dedi, korkma, evvelce olduğu gibi sopa olarak vereceğiz onu sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 22, 'Elini koynuna sok da bir hastalık yüzünden olmamak şartıyla bembeyaz çıksın; bu da bir başka delil sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 23, 'Böylece de en büyük delillerimizden bir kısmını gösterelim sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 24, 'Git Firavun''a şüphe yok ki pek azdı o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 25, 'Rabbim dedi, kalbime genişlik ver.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 26, 'İşimi kolaylaştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 27, 'Dilimin bağını çöz de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 28, 'Anlasınlar sözümü iyice.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 29, 'Âilemden birini vezir et bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 30, 'Kardeşim Harun''u.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 31, 'Arka olsun bana, onunla kuvvetlendir beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 32, 'İşime ortak et onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 33, 'Bunları yap da şanını çok tenzih edelim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 34, 'Seni çok analım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 35, 'Şüphe yok ki sen, görmedesin bizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 36, 'Dedi ki: Gerçekten de verildi dileğin ey Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 37, 'Andolsun ki bir kere daha lutfetmiştik sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 38, 'Hani vahyedilecek şeyi ilham etmiştik anana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 39, 'Sandığa koy onu da nehre bırak, nehir onu kıyıya bırakır, benim düşmanım ve senin düşmanın, alır onu demiştim ve himayem altında yetişmen için sana karşı bir sevgi de vermiştim ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 40, 'Hani kız kardeşin gitmiş de onu yetiştirecek birisini bulayım mı size demişti, gözü aydın olsun, kederlenmesin diye tekrar anana kavuşturmuştuk seni ve birisini öldürmüştün de seni gamdan kurtarmıştık ve seni sınayıp durmuştuk ve yıllarca Medyen halkının içinde kalmıştın, sonra da mukadder olduğu gibi buraya geldin ey Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 41, 'Kendim için seçtim seni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 42, 'Delillerimle git kardeşinle ve beni anmayı ihmal etmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 43, 'Firavun''a gidin, çünkü o, gerçekten de azdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 44, 'Ona yumuşak bir tarzda söz söyleyin, belki öğüt alır, yahut korkar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 45, 'Rabbimiz dediler, korkarız aşırı davranır hakkımızda, yahut da büsbütün azar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 46, 'Korkmayın dedi, gerçekten de benim sizinle beraber, duyarım ben ve görürüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 47, 'Hemen gidin de biz deyin, şüphe yok ki Rabbinin iki peygamberiyiz bizimle gönder İsrailoğullarını ve onlara azap verme. Rabbinden delille geldik sana, esenlik hidayete uyana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 48, 'Gerçekten de bize vahyedildi ki azap, yalanlayanadır ve yüz çevirene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 49, 'Dedi ki: Kimdir Rabbiniz ey Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 50, 'Rabbimiz dedi, her şeye yaratılışını veren, sonra da yolunu gösterendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 51, 'Firavun, peki, önce gelenlerin halleri ne olacak dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 52, 'Musa, onlara ait bilgi de dedi, Rabbimin katındadır, yazılmıştır; ne yanılır Rabbim, ne unutur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 53, 'Öyle bir mabuttur ki yeryüzünü size döşek etmiş, orada size yollar açmış, gökten yağmur yağdırmış, o yağmur sebebiyle de çeşitçeşit ve çifterçifter nebatlar bitirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 54, 'Yiyin ve yedirin davarlarınıza; şüphe yok ki bunda, aklı olanlara deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 55, 'Oradan yarattık sizi, gene oraya iade edeceğiz ve oradan çıkaracağız sizi bir kere daha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 56, 'Andolsun ki ona bütün delillerimizi gösterdik, yalanladı, çekindi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 57, 'Bizi dedi, büyünle yerimizden, yurdumuzdan çıkarmaya mı geldin ey Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 58, 'O halde biz de onun gibi bir büyü yaparak karşı geleceğiz sana, aramızda bir buluşma yeri ve vakti tayin et de sen ve biz, vaadimizden caymayalım, buluşalım orada, hem de ikimize de müsavi mesafede, münasip bir yer olsun orası.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 59, 'Musa dedi ki: Herkesin süslenip bayram ettiği ziynet gününü buluşma zamanı olarak tayin ediyorum size, halkın toplandığı kuşluk çağında buluşalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 60, 'Derken Firavun dönüp gitti, sonra bütün hilesini derleyip geldi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 61, 'Musa, onlara, yazıklar olsun size dedi, Allah''a yalan yere iftirada bulunmayın, sonra size azap eder de kökünüzü kurutur ve muhakkak kim iftira ederse ziyan eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 62, 'Sonra bu iş hakkında aralarında çekişeçekişe görüşüp gizlice danıştılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 63, 'Bu iki büyücü dediler, büyüleriyle sizi yerinizden, yurdunuzdan çıkarmak istiyor, sizi yüce yolunuzdan çevirmek diliyor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 64, 'Hilelerinizi, düzenlerinizi bir araya getirin, sonra safsaf olun da gelin ve muhakkak olan şu ki: Bugün üstün olan, muradına ermiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 65, 'Büyücüler dediler ki: İstersen sen at önce sopanı, istersen biz atalım önce ya Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 66, 'Musa, siz atın önce dedi. Derken büyüleriyle ipleri ve sopaları, Musa''ya doğru koşuyormuş gibi göründü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 67, 'Musa''nın içine bir korku düştü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 68, 'Korkma dedik, hiç şüphe yok ki sen, daha üstünsün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 69, 'At sağ elindeki sopanı, onların meydana getirdikleri şeyleri yutsun, çünkü onlar, ancak büyücülük düzeniyle yaptılar bu işi ve büyücü, Nerede olursa olsun, eremez umduğuna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 70, 'Sonunda büyücüler secde ederek yere kapandılar ve inandık dediler, Harun''la Musa''nın Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 71, 'Siz dedi Firavun, ben size izin vermeden inandınız mı ona? Şüphe yok ki o size büyü öğreten büyüğünüz. Ellerinizi, ayaklarınızı çaprazlama kestireceğim ve hurma dallarına astıracağım sizi, o vakit bilir, anlarsınız hangimizin azabı daha çetin ve daha sürekli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 72, 'Şu bize gösterilen apaçık mucizelere karşı artık yaradanımıza tercih edemeyiz seni dediler, elinden geleni yap, zaten ancak şu dünya yaşayışında hükmünü yürütebilirsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 73, 'Gerçekten de biz, hatalarımızı ve bize zorla yaptırdığın büyüden dolayı girdiğimiz günahları yarlıgaması için inandık Rabbimize ve Allah, daha hayırlıdır, verdiği karşılık da daha sürekli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 74, 'Şüphe yok ki Rabbine mücrim olarak gelenedir cehennem; orada ne ölür, ne diri kalır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 75, 'Ve kim de inanmış ve iyi işlerde bulunmuş bir halde ona gelirse işte o çeşit kişileredir yüce dereceler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 76, 'Kıyılarından ırmaklar akan ebedi Adn cennetleri ve bu, inanış ve ibadetle temizlenen kişinin karşılığıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 77, 'Andolsun ki biz Musa''ya, kullarımla geceleyin yola çık, onlara denizde kuru bir yol aç, düşmanların yetişmelerinden, denizde boğulmadan korkma diye vahyetmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 78, 'Derken Firavun, askeriyle artlarına düştü, deniz de onları tamamıyla kuşatıp kapladı, boğulup gittiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 79, 'Ve saptırdı kavmini Firavun ve doğru yola sevketmedi onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 80, 'Ey İsrailoğulları, sizi kurtardık düşmanlarınızdan, sözleştik sizinle Turun sağ yanında ve size kudret helvasıyla bıldırcın yağdırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 81, 'Sizi rızıklandırdığımız tertemiz şeyleri yiyin ve bu hususta taşkınlık etmeyin, sonra size gazabım vacip olur ve kime gazabım vacip olursa uçuruma yuvarlanır, helak olur gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 82, 'Ve şüphe yok ki ben bütün suçlarını örterim tövbe edip inananın ve iyi işlerde bulunup sonra da doğru yolu bulanın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 83, 'Neden acele ettin, kavminden ayrıldın da geldin ey Musa?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 84, 'İşte dedi, onlar da arkamdan geliyorlar ve ben ya Rabbi, benden daha fazla razı olasın diye acele ettim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 85, 'Şüphe yok ki dedi, biz senden sonra kavmini sınadık ve doğru yoldan çıkardı Samiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 86, 'Musa, öfkeli bir halde hayıflanarak kavmine döndü de ey kavmim dedi, Rabbiniz size güzel bir farzda vaitte bulunmadı mı, çok mu uzun sürdü sizden ayrılışım, yoksa Rabbinizin gazabının vacip olmasını mı dilediniz size de bana verdiğiniz sözden caydınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 87, 'Dediler ki: Sana verdiğimiz sözden, kendimize malik olarak caymadık biz, fakat Mısırlıların ziynet eşyalarını almıştık ya, onları, erisin diye ateşe attık, böyle telkin etti Samiri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 88, 'O, onlara bir buzağı heykeli yapmıştı ki böğürmedeydi. O ve ona uyanlar işte bu dediler, sizin de mabudunuz, Musa''nın da mabudu, fakat Musa, unuttu bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 89, 'Görmüyorlar mıydı, onlara bir söz söyleyemiyordu bu heykel ve onlara ne bir zarar veriyordu, ne bir fayda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 90, 'Andolsun ki Harun, daha önce onlara, ey kavmim demişti, siz bununla sınanmadasınız ancak ve şüphe yok ki Rabbiniz rahmandır, bana uyun ve emrime itaat edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 91, 'Onlar, Musa, dönüp gelinceye dek demişlerdi, biz bu heykele tapmadan kesin olarak vazgeçmeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 92, 'Musa, ey Harun dedi, bunların doğru yoldan saptıklarını görünce ne mani oldu da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 93, 'Bana uymadın, yoksa emrime isyan mı ettin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 94, 'Anam oğlu dedi, sakalımı, başımı bırak benim, gerçekten de, sözüme tam uymadın da İsrailoğullarının arasına ayrılık saldın diyeceğinden korktum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 95, 'Sen ne diye bu işi işledin ey Samiri dedi Musa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 96, 'Samiri, onların görmediklerini gördüm ben, sana gelen elçi meleğin izinden bir avuç toprak aldım, eriyen külçeye attım onu ve nefsim, bu işi bana böylece hoş gösterdi dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 97, 'Git hadi dedi Musa, hiç şüphe yok ki hayatta cezan, rastladığına yaklaşma, dokunma bana demendir ve sana bir de azap vaadedilmiştir ki değişmesine imkan yok; kulluğunda bulunup durduğun mabuduna bak da gör, onu biz yakacağız, sonra da kaldırıp denize atacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 98, 'Mabudunuz, ancak Allah''tır ki yoktur ondan başka tapacak; bilgisi, her şeye şamildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 99, 'İşte böylece geçmişlerin ahvalinden bir kısmını sana hikaye etmedeyiz ve şüphe yok ki sana katımızdan bir de Kur''an verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 100, 'Kim yüz çevirirse ondan şüphe yok ki kıyamet günü, ağır bir yük yüklenecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 101, 'Ebedi olarak kalacak azab içinde; bu, kıyamet günü, onlara ne de kötü bir yük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 102, 'Surun üfürüleceği gün o mücrimleri gözleri göğermiş bir halde haşrederiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 103, 'Aralarında gizligizli konuşup ancak derler, on geceden fazla kalmadınız dünyada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 104, 'Ne dediklerini daha iyi biliriz biz aklı ve yolu yoradamı daha düzgün olanın ancak bir günceğiz kaldınız dediği zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 105, 'O gün dağlar ne olur diye soruyorlar sana; de ki: Rabbim onları unufak eder, kuma döndürür de savurur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 106, 'Yeryüzünü dümdüz bir hale getirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 107, 'Orada ne bir iniş görebilirsin, ne bir tümsek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 108, 'O gün hiçbir kimse kalmaz ki Allah''a davet edene uymasın ve rahmanın heybetinden sesler kesilir, ancak ayak sesleri, tıpırtılar halinde duyulabilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 109, 'O gün rahmanın izin verdiği ve sözünden hoşnut olduğu kimseden başka hiçbir fert şefaat de edemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 110, 'Önlerinde ne varsa onu da bilir, artlarında ne varsa onu da ve onların bilgisi, bunu ihata edemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 111, 'Bütün yüzler eğilir diri ve her an yarattıklarını tedbir ve tasarruf eden mabuda; bir zulüm yükünü yüklenmiş olanlarsa mahrumiyet içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 112, 'Fakat inanarak iyi işlerde bulunan ne günahının arttırılmasından korkar, ne sevabının eksiltilmesinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 113, 'İşte biz, belki çekinirler, yahut onlara bir öğüt olur, bir ibret verir diye Arapça olan Kur''an''ı indirdik ve onda, bazı tehditleri tekrartekrar söyledik, açıkladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 114, 'Çok yücedir her şeye sahip ve mutasarrıf olan gerçek Allah ve acele etme Kur''an''ı okumak için sana vahiy tamamlanmadan ve de ki: Rabbim, bilgimi çoğalt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 115, 'Andolsun ki daha önce Âdem''le de ahitleşmiştik de unutmuştu ve onu, bilerek, isteyerek günah işleyen bir adam olarak da bulmamıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 116, 'Hani, meleklere demiştik ki: Âdem''e secde edin, onlar da secde etmişlerdi, yalnız İblis secde etmekten çekinmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 117, 'Demiştik ki: Ey Âdem, şüphe yok ki bu, sana ve eşine düşmandır, sakın sizi cennetten çıkarmasın sonra zahmetlere uğrarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 118, 'Çünkü aç kalmaman da ancak oradadır, çıplak kalmaman da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 119, 'Ve sen orada susamazsın, güneşin harareti de dokunmaz sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 120, 'Şeytan, ona vesvese verdi de ey Âdem dedi, sana ebedilik ağacını ve zeval bulmayacak devleti göstereyim mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 121, 'İkisi de o ağacın meyvesından yediler de avret yerlerini gördüler ve cennetteki ağaçların yapraklarıyla avret yerlerini örtmeye koyuldular ve Âdem, Rabbinin emrine karşı geldi de umduğundan mahrum oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 122, 'Sonra da Rabbi seçti onu, kabul etti tövbesini ve onu doğru yola sevketti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 123, 'Hepiniz dedi, inin oradan; bir kısmınız, bir kısmınıza düşman olsun. Fakat benden, size bir yol gösteren geldi mi onu kabul edip doğru yoluma uyan, ne dünyada yoldan çıkar, ne ahirette kutsuzluğa düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 124, 'Beni anmadan yüz çevirene gelince: Dünyada ona dar bir geçim var, kıyamet günü de onu kör olarak haşrederiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 125, 'Ya Rabbi der, beni neden kör haşrettin, halbuki ben görüyordum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 126, 'Böylece der, sana delillerim geldi de unutuverdin onları, işte sen de tıpkı o çeşit unutulmadasın bugün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 127, 'Ve işte biz, suç işlemekte ileri gidenleri ve Rabbinin ayetlerine inanmayanları böyle cezalandırırız; ahiret azabıysa elbette daha da çetindir, daha da sürekli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 128, 'Onlardan önce nice ümmetleri helak ettik; bu, onları doğru yola sevketmez mi ki? Onların yerlerinde, yurtlarında gezip duruyorlar. Şüphe yok ki bunda, aklı başında olanlara deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 129, 'Rabbinin söylenmiş bir sözü, takdir edilmiş bir hükmü olmasaydı ve o hükmün muayyen bir zamanı bulunmasaydı onlara da azap gelip çetıverirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 130, 'Söyledikleri sözlere sabret ve Rabbini, hamd ederek gün doğmadan ve batmadan önce ve gecenin bir kısmıyle gün ortasında noksan sıfatlardan tenzih et de rızasına mazhar ol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 131, 'Ve onları, bunlara sınamak için dünya yaşayışının ziyneti olarak faydalandırdığımız malamenale gözünü dikme ve Rabbinin rızkı, hem daha hayırlıdır, hem daha sürekli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 132, 'Ehline, namaz kılmalarını emret ve sen de devam et namaza. Senden bir rızık istemiyoruz biz, biziz sana rızık veren ve sonuç, çekinenlerindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 133, 'Ve dediler ki: Bize Rabbinden bir delille, bir mucizeyle gelmeli değil miydin? Evvelki kitaplarda bulunan şeyler, onlara apaçık bildirilmedi mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 134, 'Daha önce, bir azapla helak etseydik onları derlerdi ki: Rabbimiz, bizi horhakir etmeden bir peygamber gönderseydin de delillerine uysaydık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (20, 135, 'De ki: Hepimiz beklemekte, gözetlemekteyiz, siz de gözetip durun, yakında bileceksiniz, doğru yola sahib olanlar kimlermiş, doğru yolu bulan kimmiş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 1, 'İnsanların hesap günü yaklaştı da hala onlar gaflet içinde, yüz çevirmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 2, 'Rablerinden, Kur''an''a ait yeni bir ayet geldi mi onu alaya alarak dinlerler, oyun sanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 3, 'Kalpleri de oyuna dalmıştır da o zalimler, fısıltıyla konuşarak bu da sizin gibi bir insandan başka bir mahluk mu ki, göz göre göre büyüye mi kapılacaksınız derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 4, 'Peygamber de, Rabbim der, gökte söylenen sözü de bilir, yeryüzünde söyleneni de ve odur duyan, bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 5, 'Hatta derler ki: Bu sözler, saçmasapan rüyadan ibaret, belki de kendisi uyduruyor bunları, hatta o, bir şair. Değilse neden evvelkilere gönderildiği gibi bize bir mucize gösteremiyor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 6, 'Onlardan önce helak ettiğimiz hiçbir şehir halkı inanmamıştı, şimdi bunlar mı inanacaklar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 7, 'Senden önce de, kendilerine vahyettiğimiz erleri göndermiştik insanlara, bilmiyorsanız sorun kitap ehlinin bilginlerine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 8, 'Ve onları yemek yemeyen bir kalıp olarak yaratmamıştık ve onlar, ebedi de değillerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 9, 'Sonra vaadimizi gerçekleştirmiştik onlara da onları da kurtarmıştık, dilediklerimizi de ve imansızlıkta ileri gidenleri helak etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 10, 'Sonra size bir kitap indirdik ki o kitapta şerefiniz, yüceliğiniz anılmadadır, hala mı akıl etmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 11, 'Zulmeden nice şehirleri helak ettik de ondan sonra diğer toplulukları yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 12, 'Azabımızı hissettiler mi hemen kaçmaya başlıyorlardı ondan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 13, 'Kaçmayın, dönün sahip olduğunuz mallara, nimetlere ve evlere; çünkü sorguya çekileceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 14, 'Yazıklar olsun bize derler, gerçekten de zulmetmiştik biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 15, 'Onları kesilmiş bir ot, ateşi yanıp bitmiş bir kül yığını haline getirinciye dek sözleri, ancak budur işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 16, 'Ve biz, göğü, yeryüzünü ve ikisinin arasında olanları, bir eğlence diye yaratmadık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 17, 'Eğlence için bir kadın edinmek isteseydik kendi katımızdakilerden edinirdik, fakat biz, böyle bir şey yapmayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 18, 'Biz, gerçeği, aslı olmayan şeye karşı izhar ederiz de onu tamamıyla iptal ederiz ve batıl, helak olup gider o zaman. Ona isnad ettiğiniz şeylerden dolayı yazıklar olsun size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 19, 'Ve onundur ne varsa göklerde ve yeryüzünde ve onun katındakiler, ona kulluk etmekten çekinip ululanmadıkları gibi yorulmazlar, bıkmazlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 20, 'Hiç durmadan gecegündüz onu noksan sıfatlardan tenzih ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 21, 'Yoksa onlar, yeryüzünde, ölüleri diriltecek mabutları mı edindiler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 22, 'Gökte ve yerde, Allah''tan başka bir mabut daha olsaydı gök de bozulup mahvolurdu, yer de. Şüphe yok ki arşın Rabbi Allah, onların söyledikleri şeylerden yücedir, münezzehtir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 23, 'Yaptığından sorulmaz ona, fakat onlardır sorumlu olanlar, sorguya çekilenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 24, 'Ondan başka bir mabut mu kabul ettiler? De ki: Getirin delilinizi öyleyse. İşte benimle beraber olanların kitabı ve işte benden öncekilerin kitapları. Hayır, onların çoğu, gerçeği bilmiyorlar ve bundan dolayı da yüz çeviriyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 25, 'Ve senden önce hiçbir peygamber göndermedik ki ona, benden başka yoktur tapacak, bana kulluk edin ancak diye vahyetmeyelim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 26, 'Derler ki: Rahman, kendisine evlat edinmiştir, haşa, yücedir, münezzehtir bundan, onlar, kadirleri yüceltilmiş kullardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 27, 'Onların sözleri, hep onun emrine uygundur ve onlar, daima onun emrini yerine getirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 28, 'O bilir, onların önlerinde ve artlarında ne varsa ve Tanrı rızasına mazhar olandan başkasına şefaat de edemezler ve onlar, onun korkusundan ürkerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 29, 'Onlardan kim, ben de ondan ayrı bir mabudum derse onu cehennemle cezalandırırız; zalimleri böyle cezalandırırız biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 30, 'Kafir olanlar görmezler mi ki gerçekten de göklerle yer birdi de biz onları ayırdık ve her şeyi, sudan yarattık, hala mı inanmazlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 31, 'İnsanlarla beraber çalkalanmasın diye yeryüzünde metin dağlar yarattık ve yollarını bulsunlar, maksatlarına ersinler diye de orada geniş yollar açtık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 32, 'Gökyüzünü, korunmakta olan bir tavan yaptık, onlarsa hala delillerinden yüz çevirmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 33, 'O, öyle bir mabut ki geceyi, gündüzü, güneşi ve ayı yaratmıştır, hepsi de gökte yüzüp durmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 34, 'Senden önce de ebedi olarak yaşayacak hiçbir insan yaratmadık; sen ölürsen onlar ebedi mi kalacaklar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 35, 'Herkes, ölümü tadacak ve sizi, bir sınama olarak hayırla, şerle de denemedeyiz ve dönüp tapımıza geleceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 36, 'Kafir olanlar, seni görünce ancak alaya alırlar, bu mudur derler, mabutlarınızı anan, halbuki onlar rahmanı anmayı inkar ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 37, 'İnsan, pek aceleci yaratılmıştır; delillerimi yakında göstereceğim size, acele etmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 38, 'Doğru söylüyorsanız derler, ne zaman yerine gelecek vaadiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 39, 'Bir bilselerdi kafir olanlar önlerinden, artlarından kendilerini saran ateşi defedemeyecekleri ve hiçbir yardım da göremeyecekleri zamanı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 40, 'Hatta o gün, onlara birdenbire geliverecek de şaşırtacak onları ve onu reddetmeye güçleri yetmeyeceği gibi mühlet de verilmeyecek onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 41, 'Andolsun ki senden önceki peygamberlerle de alay edilmiştir de onlarla alayları yüzünden alay ettikleri azaba uğrayıvermişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 42, 'De ki: Kim koruyabilir rahmandan sizi geceleyin ve gündüzün? Fakat onlar, Rablerini anmaktan yüz çevirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 43, 'Onların, azabımızı kendilerinden menedecek bir mabutları mı var yoksa? O mabutların, ne kendilerine yardım etmeye güçleri yeter, ne de bizden bir yardım görür kafirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 44, 'Hatta biz, onların da, atalarının da ömürlerini uzattık, ömürleri boyunca onları geçindirdik, fakat görmezler mi ki yerlerine, yurtlarına girip hakim oldukları yerleri daraltıp azaltmadayız; hala onlar mı üstün olanlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 45, 'De ki: Ben sizi vahiyle korkutup duruyorum ancak, fakat sağırlar, korkutuldukları zaman da kendilerini davet edenin sözünü duymazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 46, 'Fakat onlara Rabbinin azabından bir koku bile esse derhal eyvahlar olsun bize derler gerçekten de biz zalimdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 47, 'Kıyamet günü, adalet terazilerini kuracağız, hiçbir kimse hiçbir şeyde haksızlığa uğramıyacak, hatta hardal tanesi ağırlığında bir işin bile karşılığını vereceğiz, bizim hesap görüşümüz yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 48, 'Ve andolsun ki Musa''ya ve Harun''a, hakkı batıldan ayıran ve çekinenlere ışık ve öğüt olan kitabı verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 49, 'O çekinenler, görmedikleri halde Rablerinden korkarlar ve kıyametten ürküp titrerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 50, 'Ve bu da kutlu Kur''an''dır, bunu da indirdik; inkar mı edeceksiniz onu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 51, 'Andolsun ki daha önce İbrahim''e onu doğru yola sevkedecek delilleri vermiştik ve onun, buna ehil olduğunu da biliyorduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 52, 'Hani atasına ve kavmine, nedir bu tapıp durduğunuz heykeller demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 53, 'Biz dediler, atalarımızı bunlara tapıyor bulduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 54, 'O da andolsun ki demişti, siz de apaçık bir sapıklık içindesiniz, atalarınız da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 55, 'Onlar, bize bir gerçekle mi geldin demişlerdi, yoksa oyun oynayanlardan mısın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 56, 'O, hayır demişti, Rabbiniz, göklerin ve yeryüzünün Rabbidir, onları yaratmıştır ve ben de bu söze tanık olanlardanım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 57, 'Ve andolsun Allah''a ki siz dönüp gittikten sonra ben, onlara yapacağımı yapacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 58, 'Onları paramparça etti, yalnız, ona baş vursunlar diye büyüklerini bıraktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 59, 'Mabutlarımıza kim yaptı bu işi dediler, şüphe yok ki o gerçekten de zalimlerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 60, 'Bir genç duymuştuk dediler, İbrahim deniyordu adına, onlardan bahsediyordu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 61, 'Öyleyse dediler, onu halkın gözü önüne getirin de söylediği söze tanıklıkta bulunsunlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 62, 'Ey İbrahim dediler, bu işi sen mi yaptın mabutlarımıza?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 63, 'O, belki de şu put yapmıştır bu işi dedi, büyükleri bu, söyliyebilirse sorun ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 64, 'Birbirlerine dönüp de gerçekten de zalimsiniz siz dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 65, 'Sonra başlarını eğdiler ve andolsun ki dediler, sen de bunların konuşmadığını bilirsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 66, 'İbrahim, peki dedi, öyleyse Allah''ı bırakıp da ne diye tapıyorsunuz size ne bir faydası dokunan, ne bir zararı gelen şeylere?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 67, 'Yuh size de, Allah''ı bırakıp taptığınız şeylere de; akıl etmez misiniz ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 68, 'Bir şey yapacaksanız dediler, yakın onu da mabutlarınıza yardım edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 69, 'Ey ateş dedik, soğu İbrahim''e karşı ve bir zarar verme ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 70, 'Onlar, İbrahim''e bir düzen kurmak istedilerse de biz, onları en büyük bir ziyana uğrattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 71, 'Onu da, Lut''u da kurtarıp alemlere kutlu ettiğimiz yere ulaştırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 72, 'Ve ona İshak''ı verdik, Yakup''u da istemeden ihsan ettik ve hepsini de temiz ve iyi kişiler kıldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 73, 'Onları öyle rehberler ettik ki emrimizle halkı doğru yola sevk ederler ve onlara hayırlı işleri, namaz kılmayı, zekat vermeyi vahyettik ve onlar, bize ibadet eden kişilerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 74, 'Ve Lut''a da peygamberlik ve bilgi verdik ve halkı, kötü işlerde bulunan şehirden kurtardık onu; gerçekten de onlar, kötü ve buyruktan çıkmış bir topluluktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 75, 'Ve rahmetimize ithal ettik onu; gerçekten de temiz kişilerdendi o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 76, 'Ve Nuh da bundan önce hani nida etmişti de duasını kabul etmiştik, onu ve ailesini, yürekleri bile yakan pek büyük bir dertten kurtarmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 77, 'Ve delillerimizi yalanlayan bir topluluğa karşı yardım etmiştik ona; gerçekten de kötü bir topluluktu onlar ve bu yüzden hepsini de sulara boğmuştuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 78, 'Davud''la Süleyman da, hani bir topluluğun koyunları, geceleyin birisinin tarlasına yayılmış, harap etmişti de bu hususta hüküm vermişlerdi ve biz de hükümlerine tanık olmuştuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 79, 'O hükmü, biz anlatmıştık Süleyman''a ve hepsine de peygamberlik ve bilgi vermiştik ve beraberce Tanrıyı tenzih etmek için dağları ve kuşları, Davud''a ram ettik ve bunları yaptık, gücümüz yeter yapmaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 80, 'Ve ona, sizi savaşlarda koruması için zırh yapma sanatını öğrettik, hala mı şükretmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 81, 'Ve Süleyman''a kasırga gibi esen rüzgarı ram ettik, emriyle, kutladığımız yere esip giderdi ve biz her şeyi biliriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 82, 'Ve Şeytanlardan, onun için denize dalıp ona mücevherat çıkaranlar ve bundan başka daha ayrı işler yapanlar da vardı ve biz de onları korurduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 83, 'Ve Eyyub da hani Rabbine nida etmişti de gerçekten demişti, bana zarar dokundu ve sen, merhametlilerin en merhametlisisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 84, 'Derken duasını kabul ettik de ne zarara uğradıysa giderdik ve katımızdan rahmet ve ibadet edenlere ibret olmak üzere ona ailesini ve onlarla beraber daha da bir mislini verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 85, 'Ve İsmail de, İdris de, ZülKifl de, hepsi de sabredenlerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 86, 'Ve onları rahmetimize ithal ettik; gerçekten de temiz kişilerdendi onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 87, 'Ve Zünnun da hani öfkelenip gitmişti de sanmıştı ki bizim gücümüz yetmeyecek ona; derken karanlıklarda nida ederek gerçekten de senden başka yoktur tapacak, tenzih ederim seni ve şüphe yok ki ben, zalimlerden oldum demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 88, 'Derken duasını kabul etmiştik onun ve gamdan kurtarmıştık onu ve böyle kurtarırız insanları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 89, 'Ve hani Zekeriyya da Rabbine nida etmiş ve Rabbim demişti, beni yalnız bırakma ve sensin mirasçıların en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 90, 'Derken duasını kabul etmiştik onun ve ona Yahya''yı vermiştik ve karısının kısırlığını gidermiştik, doğurmaya kabiliyet vermiştik. Onlar, hayırlı işlerde koşuşurlar, yarışırlar ve umarak, korkarak bize dua ederlerdi ve onlar, bize karşı gönül alçaklığı gösterirlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 91, 'Hani, bir de ırzını koruyan o kız vardı, onu da an; biz, ona ruhumuzdan üflemiştik ve onu ve oğlunu, alemlere bir delil yapmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 92, 'Hiç şüphe yok ki bir tek ümmetsiniz siz ve ben Rabbinizim, bana kulluk edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 93, 'Dine ait işlerinde, kendi aralarında bölükbölük oldu onlar ve hepsi de dönüp bizim tapımıza gelecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 94, 'İnanarak iyi işlerde bulunanların çalışmaları, inkar edilmez ve biz, şüphe yok ki onları yazmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 95, 'Helak ettiğimiz bir şehir halkının, dönüp bizim tapımıza gelmemesine imkan yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 96, 'Sonunda Ye''cüc ve Me''cuc''un seti açılınca ve onlar, her tepeden yeryüzüne saldırınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 97, 'Ve gerçek vait yaklaşınca işte o zaman kafir olanlar, gözlerini dikip kalacaklar ve yazıklar olsun bize diyecekler, bundan gafildik, hatta zalimdik biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 98, 'Şüphe yok ki siz de, Allah''ı bırakıp taptıklarınız da cehennem odunusunuz, siz, oraya gireceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 99, 'Şunlar, mabud olsalardı oraya uğramazlardı, halbuki hepsi de orada ebedidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 100, 'Orada şiddetle inleyerek nefes alacak onlar ve onlar, orada hiçbir şey duymayacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 101, 'Fakat kendilerine, tarafımızdan güzel bir vaitte bulunulan, haklarında iyilik takdir edilen kimseler, oradan uzaklaşmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 102, 'Orasının en hafif bir sesini bilmezduymaz onlar ve canlarının dilediği, arzuladığı şeylerin içinde ebedidir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 103, 'O en büyük korku, onları hüzünlendirmez ve melekler, onları karşılarlar da işte derler, size vaadedilen gün, bugün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 104, 'Biz o gün göğü, kitap sahifelerini dürüp büker gibi dürüp bükeceğiz; önce nasıl yaratmaya başladıysak tekrar yaratacağız, bu, vaadimizdir bizim ve gerçekten de yapacağız bunu, gücümüz yeter yapmaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 105, 'Andolsun ki biz, Tevrat''tan sonra Zebur''da da yazdık: Şüphe yok ki yeryüzü, temiz kullarıma miras kalır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 106, 'Şüphe yok ki bu, kullukta bulunan topluluğa bir tebliğdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 107, 'Ve biz seni, ancak alemlere rahmet olarak gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 108, 'De ki: Bana, mabudumuzun, bir tek mabut olduğu vahyedildi ancak, Müslüman oluyor musunuz siz de?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 109, 'Eğer yüz çevirirlerse de ki: Aynı tarzda hepinize de bildirdim ve size vaadedilen yakında mı olacak, uzak bir zamanda mı, onu bilmem ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 110, 'Şüphe yok ki o, açık konuşulan sözü de bilir, gizlediğiniz sözü de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 111, 'Ve bildirdiğim, sizi bir sınama ve bir zamana dek geçindirme de olabilir, onu da bilmem ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (21, 112, 'Dedi ki: Rabbim, gerçek olarak hükmet ve Rabbimiz olan rahmanın yardımını dileriz onun hakkında söylediğiniz aslı olmayan sözler yüzünden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 1, 'Ey insanlar, çekinin Rabbinizden, şüphe yok ki kıyametin sarsıntısı, pek büyük birşeydir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 2, 'Onu gördüğünüz gün, bütün emzikli kadınlar; çocuklarını bile unutup bırakır, her gebe kadın, çocuğunu düşürür ve insanları sarhoş görürsün, fakat sarhoş değildir onlar, ancak Allah''ın azabı pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 3, 'İnsanlardan öylesi de var ki bilgisi olmadığı halde Allah hakkında münakaşaya girişir ve her azgın Şeytanın peşine düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 4, 'Ezelden takdir edilmiştir, kim, onu sever, kim ona uyarsa şüphe yok ki o, azdırır onu ve alevalev yanan ateşin azabına sürükler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 5, 'Ey insanlar, ölümden sonra dirilme hakkında şüphedeyseniz bilin ki hiç şüphe yok, sizi topraktan yarattık biz, sonra bir katre sudan, sonra donmuş bir parça kandan, sonra yaratılışı tamamlanmış, tamamlanmamış bir et parçasından size apaçık gösterelim kudretimizi diye. Ve sizi, dilediğimiz muayyen bir zamana dek rahimlerde kararlaştırırız, sonra çocuk olarak çıkarırız sizi, sonra da ergenlik çağına getiririz ve sizden ölen olur, gene sizden, bilgisinden sonra hiçbir şey bilmez bir hale gelen ve ömrün en aşağılık devresine sürüklenen olur. Ve yeryüzünü kupkuru görürsün, fakat ona yağmur yağdırdığımız zaman harekete gelir, kabarır ve çeşitli, çifterçifter güzelim nebatlar bitirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 6, 'Bu da, şüphe yok ki Allah''ın gerçek oluşundandır ve şüphe yok ki o, ölüyü de diriltir ve şüphe yok ki onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 7, 'Ve gerçekten de kıyamet gelmededir, şüphe yok onda ve gerçekten de Allah, kabirlerdekileri diriltecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 8, 'Ve insanlardan, bilgisi ve aydınlatıcı bir kitabı olmadığı halde Allah hakkında münakaşaya girişen var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 9, 'Halkı Allah yolundan saptırmak için kendi kendine ululanır durur. Ona, dünyada aşağılık bir durum var ve kıyamet günü de yakıp kavurucu azabı tattırırız ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 10, 'Bu da senin, kendi ellerinle kendine hazırladığın şeydir ve şüphe yok ki Allah, alabildiğine zulmetmez kullarına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 11, 'Ve insanlardan, Allah''a kalbiyle değil de diliyle kulluk eden de var; ona bir hayır isabet ederse kalbi yatışır o hayır yüzünden, fakat bir sınamaya uğrarsa yüzü dönüverir; dünyada da ziyan eder, ahirette de; işte budur apaçık ziyan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 12, 'Allah''ı bırakır da kendisine ne bir zarar verebilen, ne bir fayda verebilen şeyi çağırır. Budur işte doğruluktan tamamıyla uzak bir sapıklık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 13, 'Zararı, faydasından daha yakın olanı çağırır; fakat ne de kötü yardımcıdır o, ne de kötü arkadaş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 14, 'Şüphe yok ki Allah, inanan ve iyi işlerde bulunanları, kıyılarından ırmaklar akan cennetlere sokar; şüphe yok ki Allah, dilediğini yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 15, 'Allah, peygambere dünyada da, ahirette de yardım etmeyecek sanan bilsin ki yardım edecektir, isterse tavana bir ip takıp assın kendini de ölsün ve baksın da görsün, bu yaptığı düzen, kızdığı şeyi ortadan kaldırır mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 16, 'İşte biz, apaçık ayetleri böyle indirdik ona ve şüphe yok ki Allah, dilediğini doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 17, 'Şüphe yok ki inananlar ve Yahudi olanlar, Sabiiler, Nasraniler ve Mecusilerle bir de şirk koşan kişiler; şüphe yok ki Allah, kıyamet gününde onların aralarını ayırır; şüphe yok ki Allah, her şeye tanıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 18, 'Görmez misin, Allah, şüphe yok, öyle bir mabut ki ona secde eder ne varsa göklerde ve ne varsa yeryüzünde ve güneş, ay, yıldızlar, dağlar, ağaç, hayvanlar ve insanların çoğu ve çoğu da azabı hak etmiştir ve Allah, kimi hor kılarsa onu kutluluğa ulaştırıp ona lütuf ve ihsanda bulunan hiçbir kimse bulunamaz; şüphe yok ki Allah, dilediğini yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 19, 'Şu iki zümre, Rablerinin dini hakkında birbirleriyle çekişen iki düşmandır; kafir olanlara ateşten libaslar biçilmiştir, tepelerine de kaynar su dökülecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 20, 'Ve bu suretle karınlarında ne varsa o da eritilecek, derileri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 21, 'Onlara demirden çomaklar da var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 22, 'Ne zaman elemlerinden, oradan çıkmak isteseler gene oraya gönderilirler de tadın yakıp kavuran azabı denir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 23, 'Şüphe yok ki Allah, inanan ve iyi işlerde bulunanları, kıyılarından ırmaklar akan cennetlere koyar, orada altın bilezikler ve inciler takınıp bezenirler ve orada, elbiseleri de ipektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 24, 'Ve onlar, sözün en temizini söylemeye irşat edilmişlerdir ve onlar hamde layık Tanrının yoluna irşad edilmişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 25, 'Kafir olanlar ve halkı Allah''ın yolundan çıkaranlar ve insanlar için ibadet yeri olarak halkettiğimiz ve orada yurt tutanla orayı ziyaret için gelen hakkında aynı hükümleri yürüttüğümüz Mescidi Haram''dan men edenlerse. Ve kim orada nehy edilmiş birşeyi zulmederek yapmak isterse ona elemli azabı tattırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 26, 'An o zamanı ki hani biz İbrahim''e, bana hiçbir şeyi şerik tutma ve tavaf edenlere, namaz kılanlara, rüku edenlere, secde kılanlara tertemiz tut evimi diye Beyt''in yerini göstermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 27, 'Ve insanları hacca davet et, uzakuzak, bütün yerlerden yaya olarak, yahut hayvana binerek gelsinler sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 28, 'Gelsinler de kendilerine ait olan menfaatleri elde etsinler ve kendilerine rızık olarak verilen dört ayaklı hayvanları, muayyen günlerde Allah''ın adını anarak kessinler. Yiyin artık onlardan ve yokyoksul fakiri de doyurun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 29, 'Sonra ihramdayken yapılmayan şeyleri yapıp temizlensinler, adaklarını yerine getirsinler ve tavaf etsinler Beytalatıyk''ı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 30, 'İşte budur hac ve Allah''ın, hürmeti emrettiği şeylere tazim eden kişiye bu hareketi, Rabbi katında hayırlıdır ve size, okunan şeyler müstesna, öküz, inek, koyun, deve helal edilmiştir, artık çekinin putlara tapma pisliğinden ve çekinin yalan sözden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 31, 'Allah''ı bir tanıyıp ona şirk koşmaksızın ve kim, Allah''a şirk koşarsa sanki havadan düşmüştür de kuş kapmıştır onu, yahut da rüzgar almış, pek uzak bir yere sürüp atmıştır onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 32, 'İşte böyledir bu ve kim Allah dininin hükümlerini ulularsa şüphe yok ki bu hareket, yüreklerdeki çekinme duygusundandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 33, 'Kurbanlık hayvanlarda, muayyen bir zamanadek faydalar var size, sonra varıp gidecekleri yer, BeytalAtıyk''tir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 34, 'Her ümmete kurban kesmeyi meşru kıldık davarlardan onlara rızık olarak verdiklerimizi keserlerken Allah''ın adını anmaları şartıyla ve bilin ki mabudunuz, bir mabuttur artık ona teslim olun ve müjdele itaat edip alçak gönüllü olanları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 35, 'Öyle kişilerdir onlar ki Allah anılınca yürekleri oynar korkudan ve uğradıkları müsibetlere katlanırlar, namaz kılmaya devam ederler ve kendilerini rızıklandırdığımız şeylerin bir kısmını harcarlar yoksullara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 36, 'Büyük develeri de Allah''ın size meşru kıldığı kurbanlık hayvanlar olarak yarattık, onlarda hayır ve menfaat var size. Artık onlar, ayaktayken onları boğazlayın ve Allah''ın adını anın, yanüstü düştükleri zaman da hem siz yiyin ondan, hem de yoksulluğunu bildirip isteyen ve gizleyip istemeyen yoksulları doyurun; siz şükredesiniz diye böylece onları da ram ettik size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 37, 'Onların ne etleri Allah''a ulaşır, ne kanları, fakat sizin çekinmenizdir ki ona ulaşır. Sizi doğru yola sevkettiğinden dolayı Allah''ı büyük bilmeniz için onları da ram etti size ve müjdele iyilik edenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 38, 'Şüphe yok ki Allah, inananlardan müşriklerin şerrini defedecek; şüphe yok ki Allah, hainlikte ileri giden nankörlerin hiçbirini sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 39, 'Kendileriyle savaşa girişilenlere, zulme uğradıklarından dolayı savaşmaya izin verildi ve şüphe yok Allah''ın, onlara yardım etmeye gücü yeter elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 40, 'O kişilerdir onlar ki ancak Rabbimiz Allah''tır dediklerinden dolayı haksız olarak yurtlarından çıkarıldılar ve eğer Allah, insanların bir kısmını bir kısmıyle defetmeseydi, içlerinde Allah adının çok anıldığı manastırlar da yıkılırdı, havralar da, kiliseler de, mescitler de ve Allah, kendisine yardım edene mutlaka yardım eder; şüphe yok ki Allah, kuvvetlidir, üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 41, 'O kişilerdir onlar ki onları yeryüzünde yerleştirdik mi namaz kılarlar, zekat verirler, iyiliği emrederler, kötülükten vazgeçirmeye çalışırlar ve bütün işlerin sonucu, Allah''a varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 42, 'Seni yalanlarlarsa onlardan önce gelip geçen Nuh, Âd ve Semud kavimleri de yalanlamışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 43, 'Ve İbrahim kavmi de, Lut kavmi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 44, 'Ve Medyen ehli de yalanlamıştı ve Musa da yalanlanmıştı da onların azabını geciktirdim, bir mühlet verdim onlara da sonra helak ediverdim onları; nasılmış beni inkar etmek, nasıl da devletlerini felakete çevirmişim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 45, 'Nice şehirler var ki halkı zalim olduğundan helak ettik onları ve o şehirlerin tavanları, duvarlarına çökmüş, yerle bir olmuş, ıpıssız kalmış ve nice kuyular kuruttuk, nice yüce köşkler yıktık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 46, 'Akıl ve tedbire sahip olacak akıl, duyup anlayacak kulak elde etmek için hiç de mi yeryüzünde gezip dolaşmazlar? Gerçekten de gözler kör olmaz ama gönüllerdeki can gözleri körleşir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 47, 'Azabın, çabucak gelip çatmasını isterler senden ve Allah, vaadinden caymaz kesin olarak ve Rabbinin katında bir gün, sizin sayıp durduğunuz bin yıl gibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 48, 'Ve nice şehir var ki halkı zalim olduğundan mühlet verdik onlara da sonra helak ediverdim ve dönüp gelecekleri yer de benim tapımdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 49, 'De ki: Ey insanlar, ben ancak size, apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 50, 'İnanan ve iyi işlerde bulunanlaradır yarlıganmak ve güzel bir rızık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 51, 'Delillerimize karşı gelmeye uğraşanlara gelince: Onlar, alevalev yanan cehennemin ehlidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 52, 'Ve senden önce, şeriat sahibi veya başkasının şeriatine uymuş hiçbir peygamber göndermedik ki o, bir şey dilediği zaman Şeytan, onun dileğine bir fitne katmaya uğraşmasın. Fakat Allah, Şeytan''ın katmak istediği şeyi bozar, sonra da ayetlerini sağlamlaştırır ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 53, 'Bu da, Şeytan''ın katmak istediği şeyi, gönüllerinde hastalık olanlarla yürekleri katı bulunanlara bir sınama yapmak içindir ve şüphe yok ki zalimler, gerçekten pek uzak bir ayrılık içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 54, '- Bir de bu suretle kendilerine bilgi verilenler, bilirler ki Kur''an, Rabbinden gelen bir gerçektir ve artık inanırlar ona, gönülleri, onunla tevazuya erişir ve şüphe yok ki Allah, inananları elbette doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 55, 'Kafir olanlarsa, kıyamet gelip çatmadıkça, yahut o kısır gün, onlara gelmedikçe onun hakkında şüphe etmekten kurtulamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 56, 'O gün, saltanat ve tasarruf, Allah''ındır, aralarını hükmeder o, inanıp iyi işlerde bulunanlar, nimetlerle dolu cennetlerdedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 57, 'Kafir olup delillerimizi yalanlayanlarsa, onlar içindir horlayan, aşağılatan azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 58, 'Allah yolunda yurtlarından göçenleri, sonra öldürülenleri, yahut ölenleri Allah, mutlaka güzel bir rızıkla rızıklandıracaktır ve şüphe yok ki Allah, elbette rızık verenlerin en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 59, 'Mutlaka onları, hoşnut olacakları bir yere ithal edecektir ve şüphe yok ki Allah, her şeyi bilir ve azap etmede acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 60, 'Böyledir bu ve kim bir cezaya uğrar da ceza edeni ona benzer bir surette cezalandırırsa, sonra da gene aleyhine taşkınlıkta bulunulursa Allah yardım eder ona; şüphe yok ki Allah, suçları bağışlar, örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 61, 'Böyledir bu, çünkü Allah, geceyi kısaltır, gecenin bir kısmını gündüz yapar, gündüzü kısaltır, bir kısmını gece yapar ve şüphe yok ki Allah, her şeyi duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 62, 'Böyledir bu, çünkü Allah, gerçektir ve şüphe yok ki ondan başka neyi çağırırlarsa boştur, aslı yoktur ve şüphe yok ki Allah, pek yücedir, pek büyük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 63, 'Görmez misin, şüphe yok ki Allah, gökten yağmur yağdırır da yeryüzü yemyeşil olur; şüphe yok ki Allah, lütuf ve ihsan sahibidir, her şeyden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 64, 'Onundur ne varsa göklerde ve ne varsa yeryüzünde ve şüphe yok ki Allah, müstağnidir her şeyden ve odur hamde layık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 65, 'Görmez misin, şüphe yok ki Allah, ram etmiştir size yeryüzünde ne varsa ve emriyle denizde akıp giden gemiyi ve izni olmadıkça gökyüzünü yeryüzüne yıkmaz da tutar; şüphe yok ki Allah, insanları pek esirger ve rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 66, 'Öyle bir mabuttur ki sizi diriltti, sonra öldürür, sonra gene diriltir, fakat şüphe yok ki insan, pek nankördür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 67, 'Ve her ümmete bir din verdik, o dine göre ibadette bulunurlar, artık seninle her hususta çekişmeye kalkışmasınlar ve Rabbinin yoluna çağır, şüphe yok ki sen, doğru yolu bulmuşsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 68, 'Seninle mücadele ederlerse artık Allah de, ne yaptığınızı bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 69, 'Allah, kıyamet günü, ne hususta aykırılığa düştüyseniz, aranızda hükmeder sizin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 70, 'Bilmez misin ki Allah, gerçekten de bilir ne varsa göklerde ve ne varsa yeryüzünde; şüphe yok ki bu, bir kitapta tespit edilmiştir; şüphe yok ki bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 71, 'Ve bu hususta kendilerinin bir delilleri olmadığı ve bir bilgiye sahip bulunmadıkları halde Allah''ı bırakırlar da başka şeylere kulluk ederler ve zalimlere hiçbir yardımcı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 72, 'Onlara apaçık ayetlerimizi okudun mu yüzlerinde inkar alametleri belirir, görüp tanırsın sen de; neredeyse ayetlerimizi onlara okuyanlara saldırıverecekler. De ki: Bundan daha şer, daha da beter bir şey haber vereyim mi size: Ateş. Allah, kafir olanlara vaadetmiştir onu ve orası, dönüp gidilecek ne de kötü yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 73, 'Ey insanlar, bir örnek getirilmede, dinleyin onu: Allah''ı bırakıp da taptığınız putlar yok mu, onlar, bir sineği bile yaratamazlar kesin olarak, hatta hepsi bir araya gelse bile ve sinek, onlardan bir şey kapıp gitse onu da tekrar geri alamazlar ondan; isteyen de acizdir, istenen de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 74, 'Onlar, Allah''ın büyüklüğünü hakkıyla bilemediler; şüphe yok ki Allah, kuvvet sahibidir, üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 75, 'Allah, meleklerden ve insanlardan peygamberler seçmiştir; şüphe yok ki Allah, duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 76, 'Bilir ne varsa önlerinde ve ne varsa artlarında ve bütün işler, dönüp Allah''a varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 77, 'Ey inananlar, rüku edin, secde edin, kulluk edin Rabbinize ve hayır işleyin de kurtulun, erin muradınıza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (22, 78, 'Ve Allah için hakkıyla savaşın. O seçti sizi ve dinde bir güçlük vermedi size; babanız İbrahim''in dini. O mabuttur daha önce ve bu Kur''an''da size Müslüman adını takan, Peygamber, size tanık olsun, siz de insanlara tanıklık edin diye. Artık namaz kılın, zekat verin ve sarılın Allah''a, odur dostunuz; ne de güzel dosttur, ne de güzel yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 1, 'Gerçekten de kurtulmuşlardır, muratlarına ermişlerdir inananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 2, 'Öyle kişilerdir onlar ki namazlarını gönül alçaklığıyla kılarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 3, 'Ve öyle kişilerdir onlar ki boş şeylerden yüz çevirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 4, 'Ve öyle kişilerdir onlar ki zekatlarını verirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 5, 'Ve öyle kişilerdir onlar ki ırzlarını korurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 6, 'Ancak eşleri, ve malları olan cariyeleri müstesna ve bunda da hiç kınanmaz onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 7, 'Bunun ötesinde bir şey isteyenlerse, onlardır haddi aşanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 8, 'Ve öyle kişilerdir onlar ki emanetlerine ve ahitlerine riayet ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 9, 'Ve öyle kişilerdir onlar ki namazlarını korurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 10, 'Onlardır mirasçılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 11, 'Öyle kişilerdir onlar ki Firdevs''i miras alırlar ve onlar orada ebedi kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 12, 'Andolsun ki biz insanı, balçık mayasından yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 13, 'Sonra onu, sağlam bir karar yurdunda bir katre su kıldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 14, 'Sonra o bir katre suyu kan pıhtısı haline getirdik, derken kan pıhtısını bir parça et haline soktuk, derken ette kemikler yarattık, derken kemiklere et giydirdik, sonra da onu başka bir yaratılışla meydana getirdik; ne yücedir şanı yaratıcıların en güzeli Allah''ın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 15, 'Sonra şüphe yok ki siz öleceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 16, 'Sonra gene şüphe yok ki kıyamet günü tekrar diriltileceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 17, 'Ve andolsun ki üstünüzde yedi yol yarattık ve bu yaratıştan gafil değiliz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 18, 'Ve gökten, ihtiyaç miktarınca yağmur yağdırdık da yağmur suyunu yerde kararlaştırdık, topladık ve bizim, hiç şüphe yok ki onu gidermeye de gücümüz yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 19, 'Onunla da size hurmalıklar ve üzüm bağları meydana getirdik, oralarda sizin için birçok meyvelar var, onlardan yemedesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 20, 'Ve Turı Seyna''dan çıkan bir ağaç da meydana getirdik ki yağıyla ve yiyenlere, katığıyla biter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 21, 'Ve şüphe yok ki dört ayaklı hayvanlarda da ibret var sizin için elbette; karınlarındakini içiririz size ve onlarda, size daha birçok da faydalar var ve bir kısmını yersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 22, 'Onlara ve gemiye binersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 23, 'Ve andolsun ki Nuh''u kavmine gönderdik de ey kavmim dedi, kulluk edin Allah''a, size yoktur ondan başka bir mabut, hala mı çekinmeyeceksiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 24, 'Kavminin ileri gelenlerinden kafir olanlar, bu dediler, sizin gibi bir insandan başka bir şey değil, size üstün olmayı dilemekte ve Allah isteseydi melekleri indirirdi, fakat bizden önce gelip geçen atalarımız zamanında da böyle bir şey olduğunu duymadık biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 25, 'Bu, deliliğe tutulmuş bir adam ancak, artık bir zamanadek gözetleyin bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 26, 'Nuh, Rabbim dedi, beni yalanlamalarına karşı sen yardım et bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 27, 'Derken ona, nezaretimiz altında ve vahyimize uyarak bir gemi yap diye vahyettik; derken emrimiz gelip tandırın altından su kaynamaya başlayınca her mahluktan birer çifti ve helaki takdir edilenden başka ailenden olanları gemiye yükle ve zulmedenler hakkında bana söz söyleme, şüphe yok ki onlar garkolacaklar dedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 28, 'Sen ve seninle beraber bulunanlar, gemiye oturunca da hamdolsun Allah''a ki de, bizi zalim topluluktan kurtardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 29, 'Ve de ki: Rabbim, beni kutlulukla indir ve sensin indirenlerin en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 30, 'Şüphe yok ki bundan deliller var elbet ve şüphesiz ki biz, insanları deneriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 31, 'Sonra onların ardından, başka bir nesil meydana getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 32, 'Derken onlara, kendi cinslerinden bir peygamber gönderdik de kulluk edin Allah''a dedi, yoktur size ondan başka bir mabut, hala mı çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 33, 'Kavminin ileri gelenlerinden kafir olanlar ve ahirete ulaşmayı yalanlayanlar, onlara dünya yaşayışında nimetler verdiğimiz halde bu dediler, sizin gibi bir insandan başka bir şey değil; yediğiniz şeylerden o da yemekte ve içtiğiniz şeylerden o da içmekte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 34, 'Kendiniz gibi bir insana itaat ederseniz o zaman gerçekten de ziyan edersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 35, 'Ölüp toprak ve kemik kesildikten sonra kabirden çıkacağınızı mı vaadediyor size?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 36, 'Size vaadedilen şey, gerçekten ne de uzak, ne de uzak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 37, 'Yaşayış, ancak şu dünyadaki yaşayışımızdan ibaret; ölürüz, yaşarız ve tekrar dirilmeyiz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 38, 'Bu, ancak yalan yere Allah''a iftira eden bir adam ve biz, ona inanmayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 39, 'Rabbim dedi, beni yalanlamalarına karşı sen yardım et bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 40, 'Tanrı, az bir zamanda dedi, herhalde nadim olacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 41, 'Gerçek ve yerinde gelen bir bağırışla onları helak ediverdik de selle sürüklenip gelen çerçöpe döndürdük; artık uzaklık, zulmeden topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 42, 'Sonra onların ardından, başka bir nesil meydana getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 43, 'Hiçbir ümmet, helak edilmesi mukadder olan zamanı ileriye alamayacağı gibi geriye de atamaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 44, 'Sonra birbiri ardınca peygamberlerimizi gönderdik. Bir ümmete peygamber geldi mi yalanladılar onu, biz de bir kısmını, bir kısmının peşine takıp birbiri ardınca helak ettik onları ve adları, sözleri kaldı ancak; artık uzaklık inanmayan topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 45, 'Sonra Musa''yı ve kardeşi Harun''u, delillerimizle ve apaçık bir burhanla gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 46, 'Firavun''a ve kavminin ileri gelenlerine, ululanmak istediler ve kibirli bir topluluktu onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 47, 'Derken, inanacağız mı bizim gibi iki insana, kavimleri de bize kulluk etmede dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 48, 'Dediler de ikisini de yalanladılar ve onlar, helak edilenlerdi zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 49, 'Andolsun ki biz, doğru yolu bulsunlar diye Musa''ya kitap vermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 50, 'Ve Meryemoğlunu ve anasını kudretimize birer delil olarak yaratmış, onları düz, otlak ve sulak bir tepede barındırmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 51, 'Ey Peygamberler, yiyin temiz şeyleri ve iyi işlerde bulunun, şüphe yok ki ben, yaptıklarınızı bilirim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 52, 'Ve şüphe yok ki şu ümmetiniz, bir ümmetten ibarettir ve ben de Rabbinizim, artık çekinin benden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 53, 'Fakat din hususunda ayrıldılar ve ayrılanlar, kendi kitaplarından başka kitapları inkar ettiler ve her bölük, kendi elindekine razı oldu, onunla övünmiye koyuldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 54, 'Artık bir zamanadek sapıklıkları içinde bırak onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 55, 'Sanıyorlar mı ki onlara mal ve evlat vererek mükafatlandırmadayız, yardım etmedeyiz onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 56, 'Hayırlara ulaşıvermelerini sağlamadayız, hayır, anlamıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 57, 'Şüphe yok, öyle kişilerdir onlar ki Rablerinin büyüklüğünden korkarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 58, 'Öyle kişilerdir onlar ki Rablerinin delillerine inanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 59, 'Öyle kişilerdir onlar ki Rablerine şirk koşamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 60, 'Öyle kişilerdir onlar ki verecekleri neyse verirler ve yürekleri, şüphesiz olarak dönüp Rablerinin tapısına varacaklarını bildikleri için korkuyla dolar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 61, 'Onlardır hayırlara, yarışırcasına koşanlar ve onlardır hayırlarda önde bulunanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 62, 'Ve biz, hiç kimseye gücü, yetmeyeceği bir şey teklif etmeyiz ve katımızdadır gerçek olanı söyleyen kitap ve onlar, zulüm görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 63, 'Hayır, onların gönülleri, bu hususta sapıklık içindedir ve onların, bundan başka işledikleri işler var, onlar, o işleri işlerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 64, 'Sonunda nimet içinde yaşayanlarını azaba uğrattığımız zaman feryada ve yalvarmaya başlarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 65, 'Bugün feryat edip yalvarmayın, şüphe yok ki bizden bir yardım göremezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 66, 'Size ayetlerimiz okunduğu zaman gerisin geriye dönerdiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 67, 'Ululanırdınız orada ve geceleyin de Peygamber hakkında uluorta söylenirdiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 68, 'Şu Kur''an''ı bir iyice düşünmezler mi, yoksa evvelce gelip geçen atalarına gelmeyen bir şey mi geldi onlara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 69, 'Yoksa Peygamberlerini tanımazlar mı ki onu inkar etmedeler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 70, 'Yoksa onda delilik var mı derler? Hayır, o, gerçek olan Kur''an''la gelmiştir onlara, fakat çoğu gerçeği istemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 71, 'Gerçek Tanrı, onların dileklerine uysaydı elbette gökler de bozulurgiderdi, yeryüzü de, onlarda olan varlıklar da. Hayır, biz onlara kendi yüceliklerini getirdik, gösterdik, fakat onlar kendi yüceliklerinden de yüz çevirmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 72, 'Yoksa onlardan ücret mi istiyorsun? Gerçekten de Rabbinin mükafatı daha hayırlıdır ve o, rızık verenlerin en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 73, 'Şüphe yok ki sen, onları mutlaka doğru yola çağırmadasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 74, 'Fakat gerçekten de ahirete inanmayanlar, doğru yoldan sapıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 75, 'Onlara acırsan ve uğradıkları zararı giderirsen gene azgınlıklarında şaşkıncasına ısrar edip giderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 76, 'Andolsun ki biz onları azaplandırmıştık da gene Rablerine baş eğmemişlerdi ve yalvarmamışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 77, 'Sonunda, onlara çetin bir azap kapısı açmıştık da o zaman her şeyden ümitlerini kesmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 78, 'Ve o, bir mabuttur ki size kulak, gözler ve kalpler verdi ne de az şükrediyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 79, 'Ve o, bir mabuttur ki sizin için bitirdi yeryüzündekileri ve onun tapısında haşrolacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 80, 'Ve o, bir mabuttur ki diriltir ve öldürür ve geceyle gündüzün uzanıp kısalması da onun tedbiriyledir, akıl etmez misiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 81, 'Hayır, onlar, hep evvelkilerin dedikleri gibi demedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 82, 'Dediler ki: Öldükten ve toztoprak ve kemik kesildikten sonra mı diriltileceğiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 83, 'Andolsun ki bize de, daha önce atalarımıza da vaadedilmişti bu, fakat bu, öncekilerin masallarından başka bir şey değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 84, 'De ki: Kimindir yeryüzü ve orada bulunanlar biliyorsanız eğer?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 85, 'Diyecekler ki: Allah''ın. De ki: O halde ne diye hala düşünüp anlamazsınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 86, 'De ki: Kimdir Rabbi yedi göğün ve Rabbi pek büyük arşın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 87, 'Diyecekler ki: Bunlar da Allah''ın. De ki: Ne diye hala çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 88, 'De ki: Kimdir her şeyin saltanat ve tasarrufu elinde olan ve odur koruyan, oysa korunmaya muhtaç değil; biliyorsanız eğer?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 89, 'Diyecekler ki: Bunlar da Allah''ın. De ki: Ne diye hala boş şeylere kapılmadasınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 90, 'Hayır, biz onlara gerçeği getirdik ve şüphe yok ki onlar, yalan söylemedeler elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 91, 'Allah, hiç kimseyi evlat edinmez ve onunla birlikte bir başka mabut yoktur, olsaydı her mabut, kendi halkettiğini benimseyip alır gider ve bir kısmı, öbürlerinden üstün olurdu. Münezzehtir Allah onların söylediklerinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 92, 'Gizliyi de bilir, görüneni de; gerçekten de yücedir şirk koşanların ona eş tanıdıkları şeylerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 93, 'De ki: Rabbim, onlara vaadedileni bana göstereceksen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 94, 'Rabbim, beni zalim topluluğun içinde bırakma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 95, 'Ve şüphe yok ki bizim, onlara vaadettiğimiz şeyleri sana göstermeye gücümüz yeter elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 96, 'Kötülüğü, en güzel bir huyla defet, biz, onların neler dediğini, bizi ne çeşit tavsif ettiklerini daha iyi biliriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 97, 'Ve de ki: Rabbim, sana sığınırım Şeytanların vesveselerinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 98, 'Ve sana sığınırım Rabbim, onların yanımda bulunmalarından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 99, 'Sonunda, onlardan birine ölüm gelip çattı mı Rabbim der, beni geriye, tekrar dünyaya yolla da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 100, 'Belki iyi işler işlerim ve zayi ettiğim ömrü telafi ederim. Hayır, boş bir söz, onun söylediği söz. Onların önlerinde, diriltilip mezarlarından çıkarılacakları günedek bir berzah var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 101, 'Sura üfürülünce aralarında ne soysop var, ne de birbirlerinin halini soruştuRabilirler o gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 102, 'Kimin iyilikleri ağır gelirse o çeşit kişilerdir kurtulanlar, muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 103, 'Ve kimin iyilikleri hafif gelirse gerçekten de o çeşit kişilerdir kendilerini ziyana sokanlar, cehennemde ebedidir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 104, 'Yüzlerini yalar ateş ve onlar, orada somurtup kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 105, 'Siz değil miydiniz size ayetlerim okunurken onları yalanlayanlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 106, 'Rabbimiz derler, kötülüğümüz üst oldu bize ve doğru yoldan sapmış bir topluluk olduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 107, 'Rabbimiz, bizi buradan çıkar, gene kötülüğe dönersek gerçekten de zulmetmiş oluruz artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 108, 'Hoşt, defolun oraya ve bana da söz söylemeyin der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 109, 'Şüphe yok ki bir bölük vardır kullarımdan, Rabbimiz derler, inandık, yarlıga bizi ve acı bize ve sensin merhametliler merhametlisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 110, 'Halbuki siz, onları alaya aldınız da sonunda beni anmayı unutturdu size bu hal ve siz onlara gülerdiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 111, 'Şüphe yok ki ben de sabrettiklerine karşılık bugün onları mükafatlandıracağım; şüphe yok ki onlardır muratlarına erenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 112, 'Yeraltında kaç yıl kaldınız der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 113, 'Bir gün derler, yahut da bir günün bir kısmı kadar, artık, sayanlara sor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 114, 'Ancak pek az kaldınız der, fakat bir bilseniz ahiretin ebediliğini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 115, 'Yoksa sizi ancak boşu boşuna yarattık gerçekten de dönüp tapımıza gelmeyeceksiniz mi sanıyordunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 116, 'Yücedir her şeye sahip ve mutasarrıf olan gerçek Allah, yoktur ondan başka tapacak, güzelim arşın de sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 117, 'Ve kim Allah''la beraber bir başka mabudu çağırırsa onun, bu hususta bir burhanı yoktur; sorusu da Rabbine aittir onun; hiç şüphe yok ki kafirler, kurtulmazlar, muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (23, 118, 'Ve de ki Rabbim, yarlıga acı ve sensin acıyanların en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 1, 'Bir suredir ki onu indirdik ve hükümlerini farzettik ve anıp ibret alın diye onda nice apaçık deliller de gösterdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 2, 'Zina eden kadınla zina eden erkeğin herbirine yüzer sopa vurun ve Allah dinindeki bu hüküm hususunda onları esirgemeniz tutmasın ve azaplarını da inananların bir bölüğü görsün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 3, 'Zina eden erkek, ancak zina eden kadını, yahut şirk koşan kadını nikahlayabilir ve zina eden kadın da ancak zina eden erkekle, yahut şirk koşanla nikahlanabilir ve bu, inananlara haram edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 4, 'Hür namuslu kadınlara iftira edip de sonra dört tanık getiremeyenlere de seksen sopa vurun ve tanıklıklarını ebediyen kabul etmeyin ve onlardır buyruktan çıkanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 5, 'Ancak bundan sonra tövbe ederler ve düzgün bir hale gelirlerse artık şüphe yok ki Allah, suçları örter rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 6, 'Eşlerinin zina ettiğini söyleyenlere gelince: Kendilerinden başka tanık yoksa, gerçekten de doğru söyleyenlerden olduklarına dair herbirinin, dört kere tanıklık etmesi gerektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 7, 'Beşincide, yalancılardansam Allah''ın laneti yalancıya diye tanıklık eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 8, 'Kadının, Allah adına dört kere tanıklık edip kocasının, gerçekten de yalancılardan olduğunu söylemesi, cezayı, kendisinden giderir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 9, 'Beşincide, kocam doğru söyleyenlerdense gerçekten de Allah''ın gazabı bana der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 10, 'Allah''ın, size lütfü ve rahmeti olmasaydı ve şüphesiz bir surette Allah, tövbeleri kabul etmeseydi, hüküm ve hikmet sahibi bulunmasaydı ne yapardınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 11, 'O uydurma haberi size getiren sizden bir taifedir; onu şer sanmayın kendinize, hatta o, hayırdır size. Onlardan herbirinin kazandığı günah, kendisine aittir, içlerinden, suçun en büyüğünü yüklenene gelince: Onundur en büyük azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 12, 'Bunu duydukları zaman inanan erkeklerle kadınlar, kendilerine nasıl hüsnü zanda bulunuyorlarsa öylece hüsnü zanda bulunsalardı da bu, apaçık bir iftira deselerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 13, 'Bu işe ait dört tanık getirselerdi ya. Tanık getiremeyince de onlar, Allah katında yalancıların ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 14, 'Dünyada ve ahirette Allah''ın, size lütfü ve rahmeti olmasaydı daldığınız o dedikodu yüzünden mutlaka pek büyük bir azaba uğrardınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 15, 'O zaman siz, onu ağızdan ağıza naklediyor ve hiçbir bilginiz olmayan o şeyi ağızlarınızla söyleyip duruyordunuz ve sanıyordunuz ki o, kolay bir şey, halbuki o, Allah katında pek büyük birşeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 16, 'Duyduğunuz vakit, buna dair bir söz söylemek, bize düşmez; haşa, bu, pek büyük bir iftira deseydiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 17, 'Eğer inanmışsanız Allah size öğüt vermededir bir daha ebediyen buna benzer birşeye dönmemeniz hakkında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 18, 'Ve Allah, size delillerini apaçık bildirmededir ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 19, 'İnananlar arasında kötü şeylerin yayılmasını sevenleredir dünyada ve ahirette elemli azap ve Allah, her şeyi bilir, sizse bilmezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 20, 'Allah''ın, size lütfü ve merhameti olmasaydı ve şüphesiz bir surette Allah, esirgeyici ve rahim bulunmasaydı ne yapardınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 21, 'Ey inananlar, Şeytan''ın izini izlemeyin ve kim, Şeytan''ın izini izlerse bilsin ki hiç şüphe yok o, çirkin ve kötü şeyleri buyurur ve Allah''ın, size lütfü ve rahmeti olmasaydı içinizden hiçbiriniz, ebediyen temiz bir hale gelemezdi, fakat Allah dilediğini temizler ve Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 22, 'Üstün ve geçimi geniş olanlarınız, akrabaya, yoksullara ve Allah yolunda yurtlarından göçenlere vermekten çekinmesinler ve iyilik etmeyi terketmesinler ve bağışlasınlar ve suçtan geçsinler. Allah''ın, sizi yarlıgamasını sevmez, istemez misiniz? Ve Allah suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 23, 'Hiçbir şeyden haberi olmayan hür, namuslu, inanmış kadınlara iftira edenlere, dünyada da lanet edilmiştir, ahirette de ve onlaradır pek büyük azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 24, 'O günde ki kendi dilleri, elleri ve ayakları, yaptıkları şeylere dair kendilerinin aleyhinde tanıklık eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 25, 'O gün Allah, onların gerçek cezalarını tam olarak verir ve bilirler ki Allah, şüphesiz olarak apaçık gerçek mabuttur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 26, 'Pis kadınlar, pis erkeklerindir ve pis erkekler, pis kadınların ve temiz kadınlar, temiz erkeklerindir ve temiz erkekler, temiz kadınların; onlar, öbürlerinin söyledikleri sözlerden uzaktır, onlarındır yarlıganma ve güzelim bir rızık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 27, 'Ey inananlar, kendi evlerinizden başka evlere, sahipleriyle tanışmadan ve onlara selam vermeden girmeyin, düşünüp öğüt almanız için daha hayırlıdır bu size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 28, 'Orada kimseyi bulamazsanız size izin verilmedikçe girmeyin ve eğer, geri dönün denirse size dönün artık, bu, sizin için daha temiz bir harekettir ve Allah, ne yaparsanız hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 29, 'Orada bir menfaatiniz varsa içinde kimse oturmayan eve girmenizde bir suç yok size ve Allah, açığa vurduğunuzu da bilir, gizlediğinizi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 30, 'İnananlara söyle: Gözlerini haramdan sakınsınlar, ırzlarını korusunlar, bu, daha temiz bir harekettir size. Şüphe yok ki Allah, ne işlerseniz hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 31, 'İnanan kadınlara da söyle, gözlerini haramdan sakınsınlar, ırzlarını korusunlar ve açığa çıkanlardan, görünenlerden başka ziynetlerini göstermesinler ve örtülerini, göğüslerini örtecek bir tarzda omuzlarından aşağıya doğru salsınlar; kocalarından, yahut babalarından, yahut kocalarının babasından, yahut oğullarından, yahut üvey oğullarından, yahut erkek kardeşlerinden, yahut erkek kardeşlerinin oğullarından, yahut kız kardeşlerinin oğullarından, yahut Müslüman kadınlardan, yahut kendi malları olan kölelerden, yahut erkeklikten kesilmiş veya kudreti olmayan erkek hizmetçilerden, yahut da henüz kadınların gizli hallerine vakıf olmayan erkek çocuklardan başka erkeklere ziynetlerini göstermesinler; gizledikleri ziynetler, bilinsin diye ayaklarını da vurmasınlar ve tövbe edin hepiniz Allah''a ey inananlar da kurtulun, erin muradınıza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 32, 'Sizden bekar olanları ve kölelerinizden, cariyelerinizden temiz olanları nikahlayıp evlendirin; yoksulsalar Allah, lutfuyla zengin eder onları ve Allah''ın lütfü boldur ve o, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 33, 'Evlenmeye güçleri yetmeyenler de Allah, onları lutfuyla zengin edinceye dek ırzlarını korusunlar. Köle ve cariyelerinizden, bir müddet içinde birden veya taksitle bir mal veya para karşılığı azat olmak isteyenlerin dileklerini de, bunda bir hayır olduğunu bilirseniz kabul edin ve onlara, Allah''ın size verdiği maldan verin. Cariyelerinizi, onlar da namuslu yaşamayı istedikleri halde, geçici dünya malı için kötülük yapmaya mecbur etmeyin. Zorla kötülüğe sevkedildikten sonra da şüphe yok ki Allah, onların suçlarını örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 34, 'Andolsun ki biz, size apaçık deliller, sizden önce gelip geçenlere ait örnekler ve çekinenlere öğütler indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 35, 'Allah ışığıdır göklerin ve yeryüzünün. Işığının örneği, kandil konan bir yere benzer, orada bir kandil var, kandil, bir sırça içinde, sırça da parılparıl parlayan bir yıldız sanki; doğuda da olmayan, batıda da olmayan kutlu zeytin ağacından yakılmış;ateş dokunmadan da yağı, hemen ışık verecek; nur üstüne nur. Allah, doğru yolu gösterir nuruyla dilediğine ve Allah, örnekler getirir insanlara ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 36, 'Bu ışık, o evlerdedir ki Allah, oralarda adının yüceltilmesine ve anılmasına izin vermiştir ve oralarda, sabahakşam onu tenzih edenler vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 37, 'Öyle erler vardır ki onları ne ticaret, ne alımsatım, Allah''ı anmaktan ve namaz kılmaktan ve zekat vermekten alıkoymaz, gönüllerin ve gözlerin döneceği günden korkar onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 38, 'Allah''ın onları, yaptıkları işlerin daha da güzeliyle mükafatlandırması ve haklarında, lutfunu arttırması için ve Allah, dilediğini hesapsız olarak rızıklandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 39, 'Kafir olanlarsa, onların yaptıkları, çöldeki seraba benzer, susamış kimse, su sanır onu, fakat oraya gidince suya ait hiçbir şey bulamaz da kendi yanında bulur Allah''ı ve o, kafirin hesabını tamamıyla görüp karşılığını öder ve Allah, pek tez hesap görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 40, 'Yahut da derin bir denizi kaplayan karanlıklara benzer; onu bir dalgadır, sarmıştır, üstüne bir dalga daha gelir, daha üste de bulut çökmüştür, karanlıklar, karanlıklar üstüne yığılmıştır, öylesine ki elini çıkarsa onu bile nerdeyse göremez ve Allah, kime nur vermemişse artık bir nur yoktur ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 41, 'Görmez misin ki şüphesiz olarak Allah''ı tenzih eder göklerde bulunanlar da, yeryüzünde bulunanlar da ve kanatlarını çarpıp katarkatar uçan kuşlar da. Hepsi, dualarını da bilmede, onu tenzih etmeyi de ve Allah, ne yaparlarsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 42, 'Ve Allah''ındır göklerin ve yeryüzünün saltanatı ve tedbiri ve her şey, dönüp Allah tapısına varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 43, 'Görmez misin ki Allah, bulutları sürmede, sonra onları birbirine katıp birleştirmede, sonra yığın haline getirmededir. Görürsün ki bulutlardan yağmur yağmadadır ve gökte dağ gibi yığılmış bulutlarda dolu var, bunları yağdırmadadır da dilediğine afetler vermededir, dilediğine de isabet ettirmemede. Şimşeğinin parıltısıysa neredeyse gözleri alacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 44, 'Ve Allah, geceyle gündüzü, uzatıp kısaltmada, getirip götürmededir. Şüphe yok bunda, can gözü açık olanlara ibret var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 45, 'Ve Allah, her hayvanı sudan yaratmıştır onlardan, karnı üstünde sürünen var, onlardan, iki ayakla yürüyen var ve onlardan, dört ayakla yürüyen var. Allah, dilediğini yaratır; şüphe yok ki Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 46, 'Andolsun ki biz, her şeyi açıklayan deliller indirdik; ve Allah, dilediğini doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 47, 'Ve derler ki: İnandık Allah''a ve Peygambere ve itaat ettik, sonra da onların bir kısmı bu sözün ardından yüz çevirir ve onlar inanmış kişiler değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 48, 'Onlar, aralarında hükmetmesi için Allah''a ve Peygamberine çağrıldıkları zaman içlerinden bir kısmı, derhal yüzlerini döndürür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 49, 'Fakat hak kendilerindeyse ona koşakoşa gelirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 50, 'Gönüllerinde hastalık mı var, yoksa şüphe mi ediyorlar, yoksa Allah''ın ve Peygamberinin, onlara bir haksızlık edeceğinden mi korkuyorlar? Hayır, onlardır zalimlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 51, 'Aralarında hükmetmesi için Allah''a ve Peygamberine çağrıldıkları zaman inananların sözü, ancak duyduk ve itaat ettik sözüdür, böyle der onlar ve onlardır kurtulanların, muratlarına erenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 52, 'Ve kim Allah''a ve Peygamberine itaat eder, Allah''tan korkar ve ondan çekinirse o çeşit kişilerdir muratlarına erenlerin, kurtulup nusret bulanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 53, 'Emredersen onlara, savaşa çıkacaklarına dair olanca kuvvetleriyle yemin ederler elbette Allah''a de ki: Yemin etmeyin, bu, zaten adet olan, gerekli bulunan bir itaatten ibaret; şüphe yok ki Allah, ne yaparsanız hepsinden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 54, 'De ki: İtaat edin Allah''a ve itaat edin Peygambere. Gene de yüz çevirirlerse ona düşen, ancak kendisine yüklenen vazifedir ve size düşen de, size yüklenen ve eğer ona itaat ederseniz doğru yolu bulursunuz ve Peygambere, apaçık tebliğden başka bir şey düşmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 55, 'Allah, sizden inanıp iyi işlerde bulunanlara, onlardan önce gelip geçenleri nasıl yeryüzüne sahip ve hakim kıldıysa onları da mutlaka yeryüzüne sahip ve hakim kılmayı ve onlara, razı ve hoşnut oldukları dini nasip edip o dini, bütün dinlerden üstün etmeyi, korkularını emniyete tebdil eylemeyi vaadetmiştir; bana kulluk etsinler ve hiçbir şeyi eş tutmasınlar bana; ve bundan sonra kim kafir olursa o çeşit adamlardır, buyruktan çıkanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 56, 'Ve namaz kılın, zekat verin ve Peygambere itaat edin de acınmışlardan olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 57, 'Kafir olanlar, hiç ummasınlar ki yeryüzünde Allah''ı aciz bırakacaklar ve yurtları ateştir onların ve dönüp varılacak ne de kötü yerdir orası.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 58, 'Ey inananlar, malınız olan köle ve cariyelerle sizden olup henüz ergenlik çağına girmemiş çocuklar, yanınıza gelirlerken üç vakitte, izin alsınlar sizden: Sabah namazından önce, öğle sıcağında elbisenizi soyduğunuz zaman ve yatsı namazından sonra; bu üç vakit, halvet vaktidir size. Bu vakitlerden başka zamanlarda yanınıza izinsiz girerlerse ne size suç var, ne onlara ve birbirinizi de dolaşabilirsiniz. Allah, delillerini böyle apaçık bildirmede size ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 59, 'Çocuklarınız ergenlik çağına girince de evvelce nasıl izinle yanınıza geliyorlarsa gene öylece izin alsınlar. Allah, delillerini böylece açıklamadadır size ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 60, 'Nikah ümidi kalmamış, kadınlık halinden kesilmiş kadınlar, ziynetlerini göstermemek şartıyla dış elbiselerini çıkarırlarsa suç yok onlara; fakat giyerlerse bu, daha da hayırlıdır onlara ve Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 61, 'Köre vebal yok, topala vebal yok, hastaya vebal yok size de vebal yok evlerinizde, yahut babalarınızın evlerinde. Yahut analarınızın evlerinde, yahut erkek kardeşlerinizin evlerinde, yahut kız kardeşlerinizin evlerinde, yahut amcalarınızın evlerinde, yahut halalarınızın evlerinde, yahut dayılarınızın evlerinde, yahut teyzelerinizin evlerinde, yahut anahtarlarına sahib olduğunuz evlerde, yahut da dostunuzun evlerinde yemek yemenizde; toplu olarak, yahut ayrıayrı yemek yemenizde de bir vebal yok. Evlere girince, Allah tarafından kutlu ve temiz bir sağlık, esenlik vesilesi olmak üzere selam verin ev halkına. İşte Allah, aklınız ersin, düşünüp anlayın diye delillerini böyle açıklar size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 62, 'İnananlar, ancak Allah''a ve Peygamberine inanırlar ve onunla beraber, topluluğu icab ettiren bir işte bulunurlarsa izin almadan bırakıp gitmezler. Şüphe yok ki senden izin isteyenlerdir Allah''a ve Resulüne inananlar. Bazı işlerini görmek için izin istediler mi senden, sen de onlardan dilediğine izin ver ve onlar için Allah''tan yarlıganma dile; şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 63, 'Aranızda, birbirinizi çağırdığınız gibi çağırmayın Peygamberi. İçinizden, birbirini siper ederek gizlice gidenleri, gerçekten de bilir Allah; artık onun emrine aykırı hareket edenler, bir sınanmaya uğramaktan, yahut da elemli bir azaba düşmekten sakınsınlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (24, 64, 'Bilin ki Allah''ındır ne varsa göklerde ve yeryüzünde. Neyle oyalandığınızı mutlaka bilir ve dönüp tapısına vardığınız gün, ne yaptıklarını mutlaka haber verecek ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 1, 'Ne yücedir şanı, Furkan''ı alemleri korkutmak üzere kuluna indirenin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 2, 'Öyle bir mabuttur ki onundur saltanatı ve tedbiri göklerin ve yeryüzünün ve hiçbir kimseyi evlat edinmez, saltanat ve tasarrufta ortağı yoktur ve her şeyi yaratmıştır da mukadderatı takdir etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 3, 'Onu bırakıp da o çeşit tanrılar kabul etmişlerdir ki onlar, hiçbir şey yaratamazlar ve kendileri yaratılmıştır zaten ve kendilerinden bile bir zararı defedemezler, kendilerine bile bir fayda veremezler, ne öldürmeye güçleri yeter, ne yaşatmaya, ne de ölüleri diriltip kabirden çıkarmaya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 4, 'Ve kafir olanlar, bu dediler, ancak kendi uydurması ve bu hususta ona bir topluluk da yardım etmiştir; gerçekten de zulmettiler onlar ve yalan söylediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 5, 'Ve bunlar, evvelce gelip geçmiş olanlara dair masallar, onları başkasına yazdırıyor, sabahakşam ona okunup duruyor dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 6, 'De ki: Onu, göklerde ve yeryüzünde gizli olanları bilen indirdi; şüphe yok ki o, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 7, 'Ve bu ne çeşit peygamber dediler, yemek yiyor, sokaklarda geziyor; ona bir melek indirilseydi de yanında bir korkutucu olsaydı ya;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 8, 'Yahut ona bir define verilmeliydi, yahut da bir bahçesi olmalıydı da orada biten şeyleri yemeliydi ve zalimler, siz dediler, ancak büyülenmiş bir adama uyuyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 9, 'Bak da gör, senin için ne çeşit örnekler getirdi onlar da saptılar doğru yoldan ve artık gerçeğe varmak için hiçbir yol bulamaz onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 10, 'Ne yücedir şanı ki dilerse bunlardan daha da hayırlı cennetler verir sana, kıyılarından ırmaklar akar ve köşkler kurar senin için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 11, 'Hatta onlar, kıyameti de yalanladılar ve biz, kıyameti yalanlayana, alevalev yanan ateşi hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 12, 'Ateş, onları ta uzaktan gördü mü duyacak onlar, ateşin şiddetli kızgınlığını ve harılharıl yanarken çıkardığı sesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 13, 'Elleri, boyunlarına zincirlerle bağlanarak ateşin dar bir yerine atıldıkları zaman da helak olduk, bittik diye bağrışacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 14, 'Bugün, bittik, helak olduk diye bir kere bağırmayın, birçok kere bağırın bittik, helak olduk diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 15, 'De ki: Bu mu daha hayırlıdır, yoksa çekinenlere vaadedilen ebedilik cenneti mi? Bu, onlara bir mükafattır ve dönüp varacakları yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 16, 'Diledikleri gibi ebedilik, onlarındır orada; bu, yerine getirilmesi istenen ve getirilecek olan bir vaadidir Rabbinin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 17, 'O gün, onları da, Allah''tan başka kulluk ettiklerini de toplayacak da siz misiniz diyecek, kullarımı doğru yoldan saptıranlar, yoksa onlar mı doğru yoldan sapıttılar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 18, 'Diyecekler ki: Tenzih ederiz seni, senden başka dost ve yardımcı kabul etmek bize yaraşmaz; fakat sen, onları da, atalarını da nimetler vererek yaşattın, sonunda seni anmayı unuttular ve helake müstahak bir topluluk oldular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 19, 'Gerçekten de söylediklerinizi reddedip yalanlar sizi ve sizden ne azabı gidermeye güçleri yeter, ne size yardıma kudretleri var. Ve sizden kim zulmederse ona. büyük bir azap tattırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 20, 'Senden önce de peygamberlerden hiçbirini yollamadık ki onlar, yemek yememiş, sokaklarda gezmemiş olsunlar ve biz, sizin bir kısmınızı, bir kısmınızla denedik, bakalım dayanacak mısınız? Ve Rabbin, her şeyi görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 21, 'Bize ulaşacaklarını ummayanlar, bize melekler inmeliydi, yahut da Rabbimizi görmeliydik dediler. Andolsun ki onlar, kendi kendilerine ululanmadalar ve büyük bir azgınlığa ve inada düşmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 22, 'Melekleri görecekleri gün, mücrimlere hiçbir müjde yok ve melekler, müjde sözü bile mücrimlere haram diyecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 23, 'Ne yaptılarsa hepsini ele aldık da zerreler haline getirip dağıttık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 24, 'Cennet ehli, o gün, en hayırlı bir yurttadır, en güzel bir dinlenme yerinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 25, 'Ve o gün, gök yarılıp beyaz bir bulutla örtülecek ve melekler, boyuna indirilecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 26, 'O gün, saltanat ve tasarruf, gerçekten de rahmanındır ve kafirlere, çok güç bir gündür o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 27, 'O gün zalim, ellerini ısırıp duracak da ne olurdu diyecek, ben de Peygamberle aynı yolu tutsaydım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 28, 'Yazıklar olsun bana, ne olurdu filanı dost edinmeseydim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 29, 'Andolsun beni Kur''an''dan saptıran, hem de bana tebliğ edildikten sonra saptıran odur; ve Şeytan, insanı yardımcısız, horhakir bir halde bırakıverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 30, 'Ve Peygamber, ya Rabbi dedi, bu kavmim, şu Kur''an''ı ihmal etti, terkedilmiş bir hale getirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 31, 'Ve biz böylece her peygambere, mücrimlerden düşmanlar halkettik ve doğru yolu göstermek için de Rabbin yeter sana, yardım etmek için de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 32, 'Kafir olanlar, ona Kur''an dediler, birden ve toplu olarak indirilseydi ya. Biz, onu, gönlüne iyice yerleştirmen için böyle indirdik ve onu ayetayet ayırdık, birbiri ardınca indirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 33, 'Onlar, sana bir örnek getirdiler mi biz, gerçek olarak ve daha da güzel bir açıklıkla bir örnek veririz sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 34, 'Yüzüstü sürünerek cehennemde haşredilenlerin yerleri de en kötü yerdir, yolları da en sapık yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 35, 'Andolsun ki biz Musa''ya kitap verdik ve kardeşi Harun''u, ona vezir ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 36, 'Derken delillerimizi yalanlayan topluluğa gidin dedik, sonucu, onları tamamıyla helak ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 37, 'Nuh kavmini de, peygamberleri yalanladıkları zaman, sulara boğduk ve insanlara ibret olacak bir hale getirdik ve zalimlere, elemli bir azap hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 38, 'Âd''ı da helak ettik, Semud''u da, Ress ashabını da ve bunların arasında daha birçok soyları da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 39, 'Hepsine de örnekler getirdik, hepsini de kırıp geçirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 40, 'Andolsun ki onlar, uğramışlardır kötü bir yağmur yağdırılan o şehre, onu olsun görmüyorlar mı? Görüyorlar, fakat onlar, ölümden sonra dirileceklerini ummuyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 41, 'Seni, gördükleri zaman da Allah bunu mu peygamber olarak gönderdi diye alaya alıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 42, 'Kulluklarında sebat etmeseydik neredeyse bizi de mabutlarımızdan saptıracaktı derler ve yakında, azabı gördüler mi, bilecekler onlar, kimin yolu, daha yabanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 43, 'Gördün mü dileğini mabut yapanı? Sen mi koruyucu olacaksın ona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 44, 'Yoksa çokları dinlerler ve akıllarını başlarına alırlar mı sanıyorsun? Onlar, ancak hayvanlara benzerler, hatta yol yordam bakımından hayvandan da sapıktır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 45, 'Rabbinin işini görmedin mi? Nasıl da gölgeyi uzattı, dileseydi onu sakin eder, uzatıp kısaltmazdı; elbette, sonra güneşi, delil ettik gölgeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 46, 'Sonra da onu yavaşyavaş, gizlice kendimize çekip aldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 47, 'Ve öyle bir mabuttur o ki geceyi bir libas olarak yarattı size, uykuyu, bir dinlenme zamanı olarak ve gündüzü de, adeta yeni bir hayat olarak halketti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 48, 'Ve öyle bir mabuttur o ki rahmetinden önce bir müjde olarak rüzgarları göndermiştir ve biz, gökten tertemiz bir su olan yağmuru yağdırmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 49, 'Onunla ölü şehri diriltelim, yarattığımız hayvanları ve insanların çoğunu suya kandıralım diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 50, 'Ve andolsun ki biz onu, bulundukları yerlere akıttık düşünüp ibret alsınlar diye, fakat insanların çoğu, ibret almaya yanaşmadı, nankör olup gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 51, 'Ve dileseydik her şehre, bir korkutucu gönderirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 52, 'Artık kafirlere itaat etme ve onlara adamakıllı savaş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 53, 'Ve öyle bir mabuttur o ki iki denizi akıtmıştır; bu, tatlı ve içilecek sudur ve şu, tuzlu ve acı su ve aralarında da bir sınır, birbirlerine karışmalarına imkan bulunmayan bir engel halk etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 54, 'Ve öyle bir mabuttur o ki bir katre sudan insanı yaratmış ve ona anababa tarafından soysop, karıkoca tarafından akRabalık vermiştir ve Rabbinin, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 55, 'Allah''ı bırakıp da kendilerine ne bir faydası, ne bir zararı dokunan şeylere kulluk ederler ve insan, Rabbine karşı Şeytan''a yardımcıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 56, 'Ve biz seni, ancak müjdeci ve korkutucu olarak gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 57, 'De ki: Ben, Kur''an''ı tebliğ ettiğimden dolayı sizden bir ücret istemiyorum, ancak yolunu Rabbine doğrultan adamlar istiyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 58, 'Ve dayan o daimi diriye ki hiç ölmez ve ona hamd ederek şanını tenzih et ve kullarının suçlarından haberdar olması yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 59, 'Öyle bir mabuttur ki gökleri ve yeryüzünü ve ne varsa ikisinin arasında hepsini altı günde yaratmıştır da sonra arşa hakim ve mutasarrıf olmuştur, rahmandır, artık haberi olana sor bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 60, 'Onlara, secde edin rahmana dendi mi, rahman da nedir ki derler, bize emrettiğine mi secde edeceğiz? Ve bu, ancak uzaklaşmalarını arttırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 61, 'Ne yücedir şanı gökte burçlar yaratanın ve orada bir ışık ve aydınlatıcı bir ay halk edenin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 62, 'Ve öyle bir mabuttur o ki anıp ibret almaya niyetlenen, yahut şükretmeyi dileyen kimse için geceyi ve gündüzü birbiri ardınca gelmek üzere halketmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 63, 'Ve rahmanın kulları, öylesine kullardır ki yeryüzünde gönül alçaklığıyla yürürler ve bilgisizler, onlara söz söyleyince sağlık, esenlik size diye cevap verirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 64, 'Ve öyle kişilerdir onlar ki, gecelerini Rablerine secde ederek, onun tapısında kıyamda bulunarak geçirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 65, 'Ve öyle kişilerdir onlar ki Rabbimiz derler, savuştur cehennem azabını bizden; şüphe yok ki onun azabı daimidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 66, 'Gerçekten de orası, karar edilecek ne kötü yerdir, durulacak ne kötü yurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 67, 'Ve öyle kişilerdir onlar ki yoksullara bir şey verince ne israf ederler, ne de az verirler, ikisinin ortasını bulurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 68, 'Ve öyle kişilerdir onlar ki Allah''la beraber başka bir mabuda kulluk etmezler ve haklı olmadıkça Allah''ın haram ettiği bir cana kıyıp kimseyi öldürmezler ve zina etmezler ve kim, bunları yaparsa cezaya düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 69, 'Kıyamet günündeyse azabı katkat arttırılır ve horhakir bir halde, ebedi olarak azapta kalır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 70, 'Ancak tövbe edip inanan ve iyi işler işleyen müstesna. O çeşit kişilerdir ki Allah, kötülüklerini iyiliklere tebdil eder onların ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 71, 'Kim tövbe eder ve iyi işlerde bulunursa şüphe yok ki o, Allah''a, tövbesi kabul edilmiş olarak döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 72, 'Ve öyle kişilerdir onlar ki yalan yere tanıklıkta bulunmazlar ve suç yapılan bir yere uğrarlarsa oradan, suç yapmadan ve yapılan suça razı olmadan geçip giderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 73, 'Ve öyle kişilerdir onlar ki Rablerinin delilleri anıldığı ve Kur''an okunduğu zaman, sağır bir halde ve körü körüne yerlere kapanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 74, 'Ve öyle kişilerdir onlar ki Rabbimiz derler, eşlerimizden, soylarımızdan, gözlerimizi aydınlatacak kişiler ihsan et bize ve bizi, çekinenlere rehber kıl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 75, 'Onlar, sabrettiklerinden dolayı, cennetin yüce dereceleriyle mükafatlandırılır ve melekler, onlarla, sağlık, esenlik size diye buluşurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 76, 'Orada ebedi kalırlar; orası, karar edilecek ne güzel bir yerdir, durulup kalınacak ne güzel bir yurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (25, 77, 'De ki: Sizi imana davet etmeseydi ne değeriniz olabilirdi Rabbimin katında; ama siz gerçekten de yalanladınız tebliğ edilenleri, artık azaplandırmak gerekmekte sizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 1, 'Ta sin mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 2, 'Bunlardır gerçekle batılı açıklayan kitabın ayetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 3, 'Kendine kıyacaksın inanmıyorlar diye adeta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 4, 'Dileseydik gökten bir delil indirirdik onlara, onun karşısında başlarını eğerlerdi, kalakalırlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 5, 'Rahman katından, Kur''an''ın yeni bir ayeti indi mi, hemen yüz çevirirler ondan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 6, 'Gerçekten de yalanladılar, artık yakında alay ettikleri şeyin haberleri gelip çatacak onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 7, 'Bakmazlar mı yeryüzüne, nice güzelim nebatlar bitirdik çifterçifter orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 8, 'Bunda bir delil var elbette ve çoğu inanmaz gene de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 9, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 10, 'An o zamanı ki hani Rabbin, Musa''ya, git zalimler topluluğuna diye nida etmişti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 11, 'Firavun''un kavmine, hala mı çekinmeyecekler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 12, 'Musa, Rabbim demişti, gerçekten de beni yalanlarlar diye korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 13, 'Gönlüm daralır, dilim açılmaz, sen Harun''u gönder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 14, 'Ve bir de onlara karşı suçum var, korkarım, öldürürler beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 15, 'Rab, hayır dedi, ikiniz de, delillerimizle gidin, şüphe yok ki biz, sizinleyiz, her şeyi duyarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 16, 'Firavun''un tapısına geldiler de biz dediler, şüphe yok ki alemlerin Rabbinin peygamberleriyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 17, 'İsrailoğullarını bizimle gönder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 18, 'Firavun, sen dedi, çocukken içimizde büyüyüp yetişmedin mi ve ömrünün nice yılını aramızda geçirmedin mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 19, 'Ve o yaptığın işi de yaptın ve sen, nankörlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 20, 'Musa, o işi yaptım ama dedi, o vakit cahillerdendim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 21, 'Korktuğumdan da hemen kaçtım sizden, derken Rabbim bana peygamberlik verdi ve beni, peygamberler zümresine aldı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 22, 'Verdiğin nimeti başıma kakıyorsun ama bu da, İsrailoğullarını kendine kul edindiğinden meydana gelen bir şeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 23, 'Firavun, alemlerin Rabbi ne der ki dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 24, 'Musa, göklerin ve yeryüzünün ve ikisinin arasındakilerin Rabbi, dedi, iyice bilip anlıyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 25, 'Firavun, etrafındakilere, işitiyor musunuz? dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 26, 'Musa, sizin de Rabbinizdir dedi, sizden önce gelip geçen atalarınızın da Rabbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 27, 'Firavun, gerçekten de dedi, size gönderilen peygamberiniz, mutlaka deli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 28, 'Musa, doğunun da Rabbidir dedi, batının da ve ikisi arasında bulunanların da düşünüp akıl ediyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 29, 'Firavun, eğer dedi, benden başka bir mabut kabul edersen seni mutlaka zindana atılmışlara katarım, hapsederim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 30, 'Musa, ya sana dedi, apaçık bir delil gösterirsem,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 31, 'Firavun, doğru söyleyenlerdense hadi dedi, göster onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 32, 'Musa, sopasını attı, sopa hemen apaçık görünen koca bir ejderha oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 33, 'Elini koynundan çıkardı, derhal bakanlara parıl parıl parlayan bembeyaz bir el göründü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 34, 'Firavun, yanındaki ileri gelenlere, gerçekten de dedi, bu, pek bilgili bir büyücü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 35, 'Sizi, büyüsüyle yurdunuzdan çıkarmak istiyor, ne buyurursunuz şimdi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 36, 'Ona ve kardeşine bir zaman mühlet ver dediler ve şehirlere, büyücüleri toplayıp getirecek adamlar yolla da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 37, 'Adamakıllı bilgili bütün büyücüleri tapına getirsinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 38, 'Muayyen bir günün muayyen bir zamanında büyücüler toplandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 39, 'Halka da denildi ki siz de toplanıyor musunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 40, 'Umarız ki üst gelirlerse biz de büyücülere uyarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 41, 'Derken büyücüler gelince Firavun''a üst gelirsek dediler, bize bir mükafat var mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 42, 'Firavun, evet dedi, siz o zaman yakınlarımdan olursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 43, 'Musa, onlara, atacağınız şeyleri atın dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 44, 'İplerini sopalarını attılar ve Firavun''un yüceliği hakkı için dediler, biz elbette üst olacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 45, 'Derken Musa da sopasını attı, sopa, hemen onların düzüp meydana getirdiği şeyleri yutmaya başladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 46, 'Büyücüler, derhal secdeye kapandılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 47, 'Alemlerin Rabbine inandık dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 48, 'Musa ve Harun''un Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 49, 'Firavun, size izin vermeden inandınız ha dedi, şüphe yok ki o, sizin büyüğünüz, büyüyü o öğretti size; şimdi anlarsınız siz, mutlaka ellerinizi, ayaklarınızı çaprazvari kestireceğim ve hepinizi de astıracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 50, 'Zararı yok dediler, şüphe yok ki biz, dönüp Rabbimize varacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 51, 'İlk inananlardan olduğumuz için umarız ki Rabbimiz hatalarımızı yarlıgar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 52, 'Ve Musa''ya, kullarımı geceleyin yola çıkar, şüphe yok ki ardınızdan gelecekler diye vahyettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 53, 'Firavun, şehirlere asker toplayan adamlar yolladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 54, 'Bunlar, hiç şüphe yok azlık bir topluluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 55, 'Ve hiç şüphe yok ki gene de bizi kızdırmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 56, 'Bizse onların şerrine karşı uyanık ve kuvvetli bir topluluğuz diye haberler gönderdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 57, 'Derken onları bahçelerden, kaynaklardan sürüp çıkardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 58, 'Ve definelerden ve güzelim yerlerden ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 59, 'Böyle işte ve oralara İsrailoğullarını mirasçı kıldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 60, 'Firavun''a uyanlar, gün doğunca İsrailoğullarının artlarına düştüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 61, 'İki topluluk da birbirini görünce Musa''nın arkadaşları dediler ki: Mutlaka bize yetişecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 62, 'Musa, hayır dedi, şüphe yok ki Rabbim bana yol gösterecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 63, 'Derken Musa''ya, sopanı denize vur diye vahyettik. Vurunca deniz hemen yarıldı ve her parçası, koca bir dağa döndü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 64, 'Öbürlerini buraya yaklaştırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 65, 'Musa''yı ve onunla beraber bulunanların hepsini kurtardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 66, 'Sonra öbürlerini sulara garkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 67, 'Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 68, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 69, 'Onlara oku İbrahim''e ait haberi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 70, 'Hani atasına ve kavmine, neye tapıyorsunuz demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 71, 'Putlara tapıyoruz dediler ve onlara kulluk edip durmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 72, 'Çağırdığınız vakit dedi, duyuyorlar mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 73, 'Yahut size bir faydaları var mı, bir zarar veriyorlar mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 74, 'Hayır dediler, atalarımızı böyle bulduk, böyle yapıyordu onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 75, 'Şimdi gördünüz mü dedi, neye kulluk ediyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 76, 'Siz ve çok daha önce gelip geçen atalarınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 77, 'Hiç şüphe yok ki artık, alemlerin Rabbinden başka onlar, bana düşman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 78, 'Âlemlerin Rabbi, öyle bir mabuttur ki beni yaratmıştır ve odur doğru yolu gösteren bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 79, 'Ve öyle bir mabuttur ki beni doyurur ve suya kandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 80, 'Ve hastalandığım zaman o şifa verir bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 81, 'Ve öyle bir mabuttur ki beni öldürür, sonra da diriltir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 82, 'Ve öyle bir mabuttur ki kıyamet gününde umarım, hatamı da yarlıgar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 83, 'Rabbim, bana peygamberlik ver ve beni temiz kişilere kat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 84, 'Sonra gelenler arasında da güzel bir adsan ver bana, doğrulukla andır beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 85, 'Beni Naim cennetinin mirasçılarından et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 86, 'Atamı da yarlıga, şüphe yok o, sapıklardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 87, 'Utandırma beni insanların dirilecekleri günde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 88, 'O günde ki ne mal fayda verir o gün, ne evlat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 89, 'Ancak Allah''a, şirkten ve şüpheden arınmış bir gönülle gelen faydalanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 90, 'Ve cennet, o gün, çekinenlere yaklaştırılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 91, 'Ve cehennem, azgınlara gösterilmiş, meydana çıkarılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 92, 'Ve onlara, nerede kulluk ettikleriniz denilmiştir,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 93, 'Allah''ı bırakıp da tapıyordunuz onlara, size yardım ediyorlar mı, yoksa kendilerine bir yardımda bulunuyorlar mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 94, 'Hepsi de, birbiri üstüne, baş aşağı cehenneme atılmışlardır tapanlar da, tapılanlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 95, 'Ve İblis''in bütün ordusu da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 96, 'Orada birbirleriyle çekişerek derler ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 97, 'Allah hakkı için gerçekten de biz, apaçık bir sapıklık içindeydik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 98, 'Sizi, alemlerin Rabbiyle bir tuttuğumuz zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 99, 'Bizi, ancak o mücrimler saptırdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 100, 'Artık ne şefaatçilerden bir şefaatçi var bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 101, 'Ne bir can dostu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 102, 'Ne olurdu bir kere daha dünyaya dönebilseydik de inananlardan olsaydık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 103, 'Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 104, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 105, 'Nuh kavmi de peygamberleri yalanladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 106, 'Hani, kardeşleri Nuh, onlara demişti ki: Hala mı çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 107, 'Şüphe yok ki ben, size emin bir peygamberim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 108, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 109, 'Ve ben, tebliğime karşılık bir mükafat istemem sizden, benim mükafatım, ancak alemlerin Rabbine ait.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 110, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 111, 'Dediler ki: Sana, aşağılık kişiler uymuş, biz de mi inanalım sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 112, 'Nuh, benim onların yaptıklarına dair bir bilgim yok dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 113, 'Onların hesabı ancak Rabbime aittir eğer anlarsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 114, 'Ve ben, inananları kovamam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 115, 'Ben ancak, apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 116, 'Ey Nuh dediler, bu işten vazgeçmezsen seni mutlaka taşlarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 117, 'Rabbim dedi, gerçekten de kavmim, yalanladı beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 118, 'Sen, onlarla benim aramda hükmet ve beni de kurtar, inananlardan benimle beraber bulunanları da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 119, 'Derken onu da o dopdolu gemiyle kurtardık, onunla beraber bulunanları da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 120, 'Sonra da onlardan başka geri kalanları sulara garkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 121, 'Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 122, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 123, 'Âd kavmi de peygamberleri yalanladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 124, 'Hani , kardeşleri Hud, onlara demişti ki: Hala mı çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 125, 'Şüphe yok ki ben, size emin bir peygamberim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 126, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 127, 'Ve ben, tebliğime karşılık bir mükafat istemem sizden, benim mükafatım, ancak alemlerin Rabbine ait.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 128, 'Siz, her yüksek tepede, ihtiyacınız olmayan bir yapı kurarak eğlenip durur musunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 129, 'Sağlam yapılar, kaleler yaparsınız da ebedi kalacağını mı umarsınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 130, 'Tutup yakaladığınızı cebbarcasına mı yakalarsınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 131, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 132, 'Çekinin o mabuttan ki bildiğiniz nimetleri vererek yardım etti size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 133, 'Yardım etti size hayvanlar ve evlat vererek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 134, 'Ve bahçeler ve kaynaklar ihsan ederek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 135, 'Şüphe yok ki ben, o pek büyük günün azabı size gelip çatacak, ondan korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 136, 'Bizce bir dediler, istersen öğüt ver bize, istersen öğüt verenlerden olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 137, 'Bu, önce gelip geçenlerin uydurmalarından başka bir şey değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 138, 'Ve biz, azaba uğratılmayacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 139, 'Derken onu yalanladılar, biz de onları helak ettik. Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 140, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 141, 'Semud kavmi de peygamberleri yalanladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 142, 'Hani, kardeşleri Salih, onlara demişti ki: Hala mı çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 143, 'Şüphe yok ki ben, size emin bir peygamberim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 144, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 145, 'Ve ben, tebliğime karşılık bir mükafat istemem sizden, benim mükafatım, ancak alemlerin Rabbine ait.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 146, 'Burada emin bir halde bırakılacak mısınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 147, 'Bağlarda, kaynaklarda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 148, 'Ekinler içinde, tomurcukları nazik, yumuşak hurmalıklar yanında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 149, 'Ve büyük bir akılla, ustalıkla dağlarda evler yontmadasınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 150, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 151, 'Aşırı gidenlerin emrine uymayın,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 152, 'o aşırı gidenler ki yeryüzünde bozgunculuk ederler de ıslah etmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 153, 'Sen dediler, ancak büyülenmiş kişilerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 154, 'Bizim gibi bir insandan başka bir şey de değilsin sen. Doğru söyleyenlerdensen bir delil göster bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 155, 'Bu dedi, dişi bir deve; su içme hakkı, bir gün onun, malum bir gün de su içme hakkı sizin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 156, 'Ve ona kötülükle dokunmayın, sonra pek büyük bir günün azabı, helak eder sizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 157, 'Ayaklarını kesip öldürdüler onu da nadim oldular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 158, 'Azap, onları helak ediverdi. Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 159, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 160, 'Lut kavmi de peygamberleri yalanladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 161, 'Hani, kardeşleri Lut, onlara demişti ki: Hala mı çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 162, 'Şüphe yok ki ben, size emin bir peygamberim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 163, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 164, 'Ve ben, tebliğime karşılık bir mükafat istemem sizden, benim mükafatım, ancak alemlerin Rabbine ait.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 165, 'Siz, insanlardan erkeklere yaklaşıyor da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 166, 'Rabbinizin, sizin için yarattığı eşlerinizi bırakıyor musunuz? Hayır, siz, haddi aşmış bir topluluksunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 167, 'Ey Lut dediler, bu işten vazgeçmezsen seni mutlaka şehrimizden çıkarırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 168, 'Şüphe yok ki dedi, ben, sizin yaptığınızdan nefret etmedeyim, onu kınamadayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 169, 'Rabbim, beni de onların yaptıkları işin azabından kurtar, ailemi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 170, 'Derken onu da kurtardık, bütün ailesini de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 171, 'Ancak bir kocakarı, geri kalanların içindeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 172, 'Sonra berikileri mahvettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 173, 'Üstlerine öylesine bir yağmur yağdırdık ki, ne de kötüdür korkutulanlara yağdırılan yağmur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 174, 'Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 175, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 176, 'Ashabı Eyke de peygamberleri yalanladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 177, 'Hani Şuayb, onlara demişti ki: Hala mı çekinmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 178, 'Şüphe yok ki ben, size emin bir peygamberim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 179, 'Artık Allah''tan çekinin ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 180, 'Ve ben, tebliğime karşılık bir mükafat istemem sizden, benim mükafatım, ancak alemlerin Rabbine ait.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 181, 'Ölçeği tam ölçün, eksik ölçenlerden olmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 182, 'Doğru teraziyle tartın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 183, 'İnsanların haklarından hiçbir şeyi eksiltmeyin ve yeryüzünde bozguncu olmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 184, 'Çekinin o mabuttan ki sizi de yaratmıştır, önceki ümmetleri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 185, 'Sen dediler, ancak büyülenmiş kişilerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 186, 'Ve bizim gibi insandan başka bir şey de değilsin sen ve biz seni mutlaka yalancılardan sanmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 187, 'Gökyüzünden parçalar düşür üstümüze eğer doğru söyleyenlerdensen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 188, 'Rabbim dedi, yaptığınız şeyi daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 189, 'Derken onu yalanladılar da karanlık günün azabı helak etti onları; şüphe yok ki bu, o günün pek büyük bir azabıydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 190, 'Şüphe yok ki bunda bir delil var, fakat halkın çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 191, 'Ve şüphe yok ki Rabbin, elbette üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 192, 'Ve hiç şüphe yok ki Kur''an, alemlerin Rabbi tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 193, 'RuhülEmin indirmiştir onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 194, 'Senin gönlüne, korkutanlardan olasın diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 195, 'Apaçık Arapçayla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 196, 'Ve şüphe yok ki o hükümler, elbette önceki kitaplarda da var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 197, 'Onu, İsrailoğullarının bilginlerinin bilmesi de bir delil değil miydi onlara?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 198, 'Kur''an''ı Arap olmayanlardan, Arapça bilmeyenlerden birisine indirseydik de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 199, 'Onlara okusaydı gene inanmazlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 200, 'Biz, böylece Kur''an''ı, mücrimlerin gönüllerine kadar işlettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 201, 'Fakat elemli azabı görmedikçe inanmazlar ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 202, 'Ansızın gelip çatar onlara ve onlar anlamazlar bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 203, 'Derler ki: Bize mühlet verilir mi acaba?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 204, 'Hala azabımızın çabucak gelmesini mi isterler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 205, 'Diyelim ki yıllarca onları yaşattık, geçindirdik de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 206, 'Sonra onlara vaadedilen azap geldi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 207, 'O yaşayıp geçinmeleri, onları herhangi bir suretle kurtarabilir mi ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 208, 'Ve hiçbir şehri helak etmedik ki oraya, korkutucu peygamberler göndermeyelim de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 209, 'Öğüt vermesinler ve biz zulmetmeyiz hiç.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 210, 'Ve onu Şeytanlar indirmedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 211, 'Ve bu, onlara yakışmadığı gibi buna güçleri de yetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 212, 'Şüphe yok ki onlar, vahyi duymaktan uzaklaştırılmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 213, 'Sakın Allah''la beraber bir başka mabudu çağırma, yoksa azaba uğratılanlardan olursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 214, 'Ve en yakın hısımlarını korkut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 215, 'İnananlardan sana uyanlara karşı kanadını indir, mütevazi ol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 216, 'Sana isyan ederlerse de de ki: Şüphe yok ki ben, sizin yaptıklarınızdan uzağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 217, 'Ve dayan üstün ve rahim mabuda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 218, 'Öylesine mabut ki namaza kalktığın zaman da seni görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 219, 'Ve secde edenler arasında secde edişini de görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 220, 'Şüphe yok ki o, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 221, 'Haber vereyim mi size, kime iner Şeytanlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 222, 'Onlar, bütün yalancı ve suçlulara inerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 223, 'Ve onlar da Şeytanlara kulak verirler ve Şeytanların çoğuysa yalancıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 224, 'Ve şairlere de akılsızlar ve ziyankarlar uyar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 225, 'Görmez misin ki hiç şüphe yok, onlar, her vadide sersemce dolaşıp dururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 226, 'Ve hiç şüphe yok ki onlar, yapmadıkları şeyleri söylerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (26, 227, 'Ancak inananlar ve iyi işlerde bulunanlar ve Allah''ı çok ananlar ve zulme uğradıktan sonra yardıma mazhar olanlar müstesna. Ve zulmedenler, yakında bileceklerdir halleri neye varacak ve nereye varıp gidecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 1, 'Ta sin, bunlardır Kur''an''ın, gerçekle batılı açıklayan kitabın ayetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 2, 'Doğru yolu gösterir ve müjdedir inananlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 3, 'O inananlara ki namazlarını kılarlar, zekatlarını verirler ve onlardır ahirete adamakıllı inananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 4, 'Âhirete inanmayanların işledikleri işleri bezedik de artık onlar, şaşkın bir halde kalakaldılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 5, 'Onlar, o kişilerdir ki onlarındır kötü azap ve onlardır ahirette en fazla ziyan edenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 6, 'Ve şüphe yok ki sen, Kur''an''ı, hüküm ve hikmet sahibinin, her şeyi bilenin katından almadasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 7, 'An o zamanı, hani Musa, eşine demişti: Gerçekten de ben bir ateş görüyorum, ya gider, size bir haber getiririm oradan, yahut bir kor getiririm de ısınırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 8, 'Oraya gelince nida edildi: Ateşteki melekler de gerçekten kutlanmıştır, çevresindeki Musa da ve münezzehtir noksan sıfatlardan alemlerin Rabbi Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 9, 'Ey Musa, gerçek olan şey şu ki: Benim üstün olan, hüküm ve hikmet sahibi Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 10, 'Ve at sopanı. Musa, sopayı tıpkı bir yılan gibi kıvranıyor görünce arkasını dönüp kaçmıştı ve geriye de dönmemişti. Ey Musa dendi, korkma, şüphe yok, ben öyle bir mabudum ki korkmazlar benim katımda peygamberler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 11, 'Ancak zulmeden korkar; fakat kötülükten sonra onu iyiliğe döndürene gelince, hiç şüphe yok ki ben suçları örterim, rahimim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 12, 'Ve elini koynuna sok da bir hastalık yüzünden olmaksızın bembeyaz, parıl parıl parlar bir halde çıksın; bu, Firavun''la kavmine gösterilen dokuz delil içindedir; şüphe yok ki onlar, buyruktan çıkmış bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 13, 'Delillerimiz, gözle görünür bir surette onlara gösterilince bu, apaçık bir büyü dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 14, 'Kendileri de bunlara adamakıllı inandıkları, bunları iyice bilip anladıkları halde zulümle, ululanmayla inadına inkar ettiler; bak da gör, bozguncuların sonları ne oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 15, 'Ve andolsun ki biz, Davud''a ve Süleyman''a bilgi verdik ve hamdolsun Allah''a ki dediler, bizi inanan kullarının çoğundan üstün etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 16, 'Ve Süleyman, Davud''un mirasçısı oldu ve ey insanlar dedi, bize kuşdili öğretildi ve her şeye ait bilgi verildi bize; şüphe yok ki bu, elbette apaçık bir lütuf ve ihsandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 17, 'Ve Süleyman''ın, cinlerden, insanlardan ve kuşlardan meydana gelen orduları toplandı ve her takım, yerli yerince karar etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 18, 'Sonunda bir karınca vadisine geldikleri zaman bir karınca, ey karıncalar dedi, yuvalarınıza girin de Süleyman ve orduları, bilmeden çiğnemesinler sizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 19, 'Süleyman, onun sözünü duyunca hafifçe güldü de Rabbim dedi, bana ve anamla babama verdiğin nimetlere şükretmemi ve razı olacağın iyi işlerde bulunmamı ilham et bana ve rahmetinle, beni temiz kullarının arasına kat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 20, 'Kuşları araştırdı da ne oldu dedi, hüthüdü görmüyorum, yoksa bir yere mi gidip gizlendi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 21, 'Ona şiddetli bir surette azap edeceğim, yahut onu kestireceğim, yahut da bana, neden bulunmadığının sebebini açıklayan bir delil gösterir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 22, 'Derken hüthüt, çok geçmeden geldi de dedi ki: Senin henüz bilmediğin birşeyi öğrendim ve sana doğru bir haberle Sebe''den geliyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 23, 'Orada, onlara bir kadının hükümdar olduğunu gördüm ve kendisine her şey verilmiş ve bir de çok büyük tahtı var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 24, 'Onu ve kavmini, Allah''ı bırakıp güneşe secde eder buldum ve Şeytan, yaptıklarını bezemiş de yoldan çıkarmış onları ve onlar, doğru yolu bulamıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 25, 'Ve bunu da, göklerde ve yeryüzünde gizli olan şeyleri meydana çıkaran ve neyi gizliyorlar, neyi açığa vuruyorlarsa hepsini bilen Allah''a secde etmemek için yapıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 26, 'Öyle bir Allah ki yoktur ondan başka tapacak ve pek büyük Arşın da sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 27, 'Süleyman, bakayım dedi, doğru mu söyledin, yoksa yalancılardan mısın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 28, 'Git, şu mektubumu götür, ver onlara, sonra biraz çekil onlardan, bak bakalım, ne cevap verecekler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 29, 'Sebe hükümdarı, ey ulular dedi, bana pek güzel bir mektup geldi;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 30, 'O, gerçekten de Süleyman''dan geliyor ve gerçekten de içinde şunlar yazılı: Rahman ve rahim Allah Adıyla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 31, 'Bana karşı yücelik davasına girişmeyin ve teslim olarak gelin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 32, 'Ey ulular dedi, şu işi ne yapacağım, bana bir rey verin, sizi çağırmadan kesin bir karar vermedim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 33, 'Biz dediler; güçlükuvvetli ve şiddetli savaşır bir topluluğuz, fakat emir senin, ne yapacaksan sen düşün, yap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 34, 'Dedi ki: Padişahlar, bir şehre girdiler mi, o şehri harap ederler ve halkının yücelerini aşağılık bir hale getirirler ve bunlar da böyle yapacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 35, 'Onlara bir armağan göndereyim de bakalım elçiler, dönüp ne cevap getirecekler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 36, 'Elçiler, Süleyman''a gelince Süleyman, bana dedi, mal göndererek yardım mı ediyorsunuz? Allah''ın bana verdikleri, sizin getirdiklerinizden daha da hayırlı, fakat siz, armağanınızla sevinir, övünürsünüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 37, 'Dön, git onlara, öyle bir orduyla geleceğim ki karşı duramayacaklar ve oradan, horhakir bir halde çıkaracağım onları, aşağılık bir hale gelecek onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 38, 'Ey ulular dedi, onlar, bana teslim olup gelmeden onun tahtını kim getirebilir bana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 39, 'Cinlerden bir ifrit, sen yerinden kalkmadan dedi, ben onu sana getiririm ve şüphe yok ki ben, elbette güvenilecek bir kuvvete sahibim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 40, 'Kitaba ait bir bilgiye sahib olansa ben dedi, gözünü yumup açmadan onu getiririm sana. Derken baktı ki taht yanında durmada, onu görünce bu dedi, Rabbimin lutfundan, ihsanından, şükür mü edeceğim, nankör mü olacağım, beni sınamak istiyor. Fakat şükreden, mutlaka kendisini faydalandırmış olur ve nankörlük edene gelince hiç şüphe yok ki Rabbim, kullarından müstağnidir, onlara karşı lütuf ve kerem sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 41, 'Süleyman, tahtının şeklini değiştirin dedi, bakalım tanıyacak mı, tanımıyacak mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 42, 'Hükümdar gelince, tahtın bumuydu dendi, o da ona pek benziyor zaten daha önce de Süleyman''ın peygamberliğini bilmiş, anlamıştık ve teslim olmuştuk dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 43, 'Allah''ı bırakıp da kulluk ettiği şeyler, onu yoldan çıkarmıştı; şüphe yok ki o, kafirler topluluğundandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 44, 'Ona, saraya gir dendi. Billur döşemeyi görünce derin bir su sandı ve bacaklarını sıvadı. Süleyman, bu dedi, billur döşenmiş düz bir saha. Bunun üzerine o da Rabbim dedi, ben kendime zulmettim ve teslim oldum Süleyman''la beraber alemlerin Rabbi Allah''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 45, 'Ve andolsun ki biz, Semud kavmine, Allah''a kulluk edin diye kardeşleri Salih''i göndermiştik. O zaman onlar, birbiriyle çekişen, birbirine düşmanlık eden iki fırkaya ayrılmışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 46, 'Ey kavmim dedi, iyilikten önce ne diye çarçabuk kötülüğü istersiniz? Ne olur, Allah''tan yarlıganma dileseniz de merhamete layık olsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 47, 'Biz dediler, seninle ve yanında bulunanlarla uğrusuzluğa uğramadayız. O, uğradığınız uğursuzluk, Allah katından gelmede; hatta siz, sınanmakta olan bir topluluksunuz dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 48, 'Şehirde dokuz kişi vardı ki yeryüzünde bozgunculuk ediyorlar, düzene hiç yanaşmıyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 49, 'Allah adına, aralarında yemin ederek dediler ki: Bir gece Salih''i de, ailesini de öldürelim, sonra velisine, onu öldürmediğimiz gibi öldüreni de bilmiyoruz ve şüphe yok ki doğru söylüyoruz deriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 50, 'Onlar, bir düzendir kurdular, biz de düzenlerine bir cezadır verdik, fakat onlar, anlamıyorlardı bunu, haberleri bile yoktu bundan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 51, 'Düzenlerinin sonucu ne oldu, bak da gör; şüphe yok ki biz, onları da, topluluklarını da tamamıyla helak ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 52, 'İşte zulümleri yüzünden bomboş kalmış evleri; şüphe yok ki bunda, bilen topluluğa bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 53, 'Ve inanıp çekinenleri kurtardık biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 54, 'Ve Lut''u da göndermiştik de o zaman, kavmine demişti ki: Çirkin bir iş işlemedesiniz ve siz de onun çirkinliğini görüyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 55, 'Kadınları bırakıp da şehvetle erkeklerle mi temas edeceksiniz, hatta siz, bilgisiz bir topluluksunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 56, 'Kavminin cevabı, Lut''u ve soyunu şehrinizden çıkarın, hiç şüphe yok ki onlar, temizliğe pek düşkün bir topluluk sözünden başka bir söz değildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 57, 'Derken, onu ve ailesini kurtardık, ancak karısını kurtarmadık, onun, geri kalanlarla kalmasını takdir etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 58, 'Ve onlara öylesine bir yağmur yağdırdık ki, korkutulanlara yağan yağmur, ne de kötü yağmurdur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 59, 'De ki: Hamd Allah''a ve esenlik, seçtiği kullarına; Allah mı daha hayırlıdır, ona şirk koştukları şeyler mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 60, 'Gökleri ve yeryüzünü yaratan ve size gökten yağmur yağdıran mı hayırlı? Biz, o yağmurla, ağacını bile bitiremiyeceğiniz nice güzelim bahçelerdeki nebatları bitirmedeyiz; Allah''la beraber bir başka mabut var mı? Hayır, siz, yoldan sapmış kişilersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 61, 'Yoksa yeryüzünü, karar edilecek bir saha olarak yaratan ve yerin üstünden ırmaklar akıtan ve orada sağlam dağlar halkeden ve iki denizin arasına bir sınır çeken mi hayırlı? Allah''la beraber bir başka mabut var mı? Hayır, onların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 62, 'Yoksa darda kalana, dua ettiği zaman icabet eden ve kötülüğü gideren ve sizi, yeryüzüne sahip kılan mı hayırlı? Allah''la beraber bir başka mabut var mı? Ne de az düşünmedesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 63, 'Yoksa karanın ve denizin karanlıklarında sizi doğru yola sevkeden ve rahmetinden önce müjde olarak rüzgarları yollayan mı hayırlı? Allah''la beraber bir başka mabut var mı? Yücedir, münezzehtir Allah, onların şirk koştuklarından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 64, 'Yoksa daima halkı yaratıp duran, sonra da yeniden halkeden ve sizi, gökten ve yeryüzünden rızıklandıran mı hayırlı? Allah''la beraber bir başka mabut var mı? De ki: Gösterin delillerinizi doğru söylüyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 65, 'De ki: Göklerde ve yeryüzünde bulunanların hiçbiri, gizli şeyi bilemez, ancak Allah bilir ve onlar da ne vakit tekrar diriltileceklerini bilemezler', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 66, 'Hayır, onların bilgileri, bu dünyadayken, ahirete ulaşamaz; hayır, onlar, ahiret hakkında şüphe içindedir; hayır, onlar ahiret hususunda kördür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 67, 'Ve kafir olanlar, derler ki: Biz ve atalarımız, toprak olduktan sonra mı mezarlarımızdan çıkarılacağız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 68, 'Andolsun ki bu, bize de vaadedilmiştir, daha önce atalarımıza da vaadedilmişti; fakat bu, gelip geçenlere ait bir masal ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 69, 'De ki: Gezin yeryüzünde de bakın, görün, ne olmuş mücrimlerin sonu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 70, 'Ve üzülme onlar için ve daralma kurdukları düzenlerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 71, 'Ve derler ki: Bu vait, ne vakit yerine gelecek doğru söylüyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 72, 'De ki: Çarçabuk gelip çatmasını dilediğiniz o azabın birazcığı neredeyse gelmek üzere size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 73, 'Ve şüphe yok ki Rabbin, insanlara lütuf ve ihsan sahibidir, fakat çoğu şükretmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 74, 'Ve şüphe yok ki Rabbin, gönüllerinde gizlediklerini de bilir elbette, açığa vurduklarını da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 75, 'Gökte ve yeryüzünde hiçbir gizli şey yoktur ki apaçık kitapta tespit edilmemiş olsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 76, 'Şüphe yok ki bu Kur''an, İsrailoğullarına, ihtilafa düştükleri birçok şeyleri anlatmadadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 77, 'Ve şüphe yok ki Kur''an, elbette hidayettir ve rahmettir inananlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 78, 'Şüphe yok ki Rabbin, hükmüyle, aralarında takdir ettiğini yerine getirecektir ve odur üstün olan ve bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 79, 'Ve artık dayan Allah''a, şüphe yok ki sen, apaçık gerçek yoldasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 80, 'Şüphe yok ki sen, ölüye duyuramazsın ve arkalarını çevirip giderlerken çağırsan da sağırlara sesini işittiremezsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 81, 'Ve köre, sapıklığından döndürüp doğru yolu gösteremezsin sen; ancak delillerimize inanan kişiye duyurursun sesini ve onlardır gerçekten de Müslüman olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 82, 'Sözün, onlar hakkında yerine geleceği, tahakkuk edeceği zaman gelip çatınca yeryüzünden, onlara bir mahluk çıkarırız ki o, konuşur onlarla ve gerçekten de insanlar, delillerimize adamakıllı inanmazlar der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 83, 'Ve o gün, her ümmetten, delillerimizi yalanlayan bir topluluğu toplayacağız ve onlar, takımtakım duracaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 84, 'Sonunda, onlar geldi mi, delillerimi bir bilgi edinip kavramadığınız halde yalanladınız mı, neydi o yaptığınız der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 85, 'Zulmettiklerinden dolayı o söz, tahakkuk etmiş, başlarına gelmiştir, artık onlar konuşamazlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 86, 'Görmezler mi ki biz, şüphe yok ki dinlensinler diye geceyi yarattık, gözlerini açsınlar diye de gündüzü; şüphe yok ki bunda deliller var inanan topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 87, 'Ve o gün Sur üfürülür de göllerde kimler varsa ve yeryüzünde kimler varsa, Allah''ın dilediğinden başka hepsi, pek şiddetli bir korkuya kapılır ve hepsi de horhakir bir halde onun tapısına gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 88, 'Ve görürsün dağları da yerlerinde duruyor sanırsın, halbuki onlar, kıyamette bulut gibi geçip gider, dağılır. Her şeyi, adamakıllı ve yerli yerinde halkeden Allah''ın işidir bu; şüphe yok ki o, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 89, 'Kim, bir iyilikle gelirse yaptığı iyilikten de hayırlı bir mükafat var ona ve onlar, o günün şiddetli korkusundan emindirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 90, 'Ve kim, bir kötülükle gelirse o çeşit kişiler, yüzüstü cehenneme atılırlar; yaptığınıza karşılık neyse ondan başka bir şeyle mi size ceza verilecek sandınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 91, 'Bana, ancak orasını emin bir harem olarak halkeden bu şehrin Rabbine ibadet etmem emredildi ve onundur her şey ve Müslümanlardan olmam emredildi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 92, 'Ve Kur''an okumam emredildi. Artık kim doğru yolu bulursa faydası kendisine ait ve kim saparsa artık de ki: Ben ancak korkutanlardanım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (27, 93, 'Ve de ki: Hamd Allah''a, yakında delillerini gösterecek size ve siz de tanıyacaksınız onları ve Rabbin, ne yaptığınızdan gafil değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 1, 'Ta sin mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 2, 'Bunlardır gerçekle batılı açıklayan kitabın ayetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 3, 'Musa''ya ve Firavun''a ait haberlerden bir kısmını, gerçek olarak, inanan topluluğa bildirmen için okumaktayız sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 4, 'Şüphe yok ki Firavun, yeryüzünde yücelmişti ve halkını bölükbölük etmişti ve onlardan bir topluluğu zayıf bir hale getirmede, oğullarını kesmede, kadınlarını bırakmadaydı; hiç şüphe yok ki o, bozgunculardandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 5, 'Ve bizse yeryüzünde zayıf bir hale getirilmesi istenenlere lutfetmeyi ve onları, halka rehber kılmayı ve yeryüzüne, onları miras bırakmayı dilemedeydik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 6, 'İstiyorduk ki onları yeryüzünde yerleştirip kuvvetlendirelim ve Firavun''la Haman''a ve askerlerine de, onlardan çekindikleri şeyleri gösterelim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 7, 'Ve Musa''nın anasına, onu emzir, bir tehlikeye uğramasından ürkersen at onu nehre ve korkma, tasalanma, şüphe yok ki biz, onu sana tekrar veririz ve onu peygamberlere katar, peygamber yaparız diye vahyettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 8, 'Kendilerine düşman olması, onları tasalandırması için Firavun''un adamları, onu buldular; şüphe yok ki Firavun ve Haman''la askerleri, yanlış hareket etmedeydiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 9, 'Firavun''un karısı dedi ki: Senin de gözünü aydınlatır bu, benim de, öldürme bunu, umarım ki bize faydası dokunur, yahut da evlat ederiz onu kendimize ve onların, hiçbir şeyden haberleri yoktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 10, 'Musa''nın anası, gönlü bomboş bir halde kaldı, eğer inananlara katılması için gönlünü, bize bağlamasaydık nerdeyse açığa vuracaktı bunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 11, 'Ve kız kardeşine, sen dedi gözetle onu; o da, öbürleri anlamadan uzaktan gözetledi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 12, 'Ve Musa''ya daha önce bütün süt ninelerin sütünü haram etmiştik; kız kardeşi, ona süt verip yetiştirecek, ona öğüt verip büyütmeyi üstlerine alacak bir aileyi bildireyim mi size dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 13, 'Derken, gözü aydın olsun, ışıklansın ve mahzun olmasın ve Allah''ın vaadettiği şeyin, şüphesiz gerçek olduğunu bilsin diye tekrar anasına verdik onu, fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 14, 'Ergenlik çağına gelip olgunlaşınca ona peygamberlik ve bilgi verdik ve biz, iyilik edenleri böylece mükafatlandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 15, 'Halkı, gaflete dalmış, öğle uykusundayken şehre girdi de orada iki adamın kavga etmekte olduğunu gördü; bu, kendi taraftarlarındandı, öbürü, düşmanlarından. Derken, taraftarlarından olan, düşmanlarından olana karşı Musa''dan yardım istedi, o da düşmanlarından olan kişinin göğsüne bir yumruk indirdi de işini bitiriverdi; bu iş dedi, Şeytan''ın işlerinden; şüphe yok ki o, insanı apaçık sapıklığa sevkeden bir düşman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 16, 'Rabbim dedi, ben kendime zulmettim, sen yarlıga beni ve mabudu, onu yarlıgadı; şüphe yok ki o, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 17, 'Rabbim dedi, beni nimetlendirdiğin şeylerle mücrimlere kesin olarak arka olmayacağım artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 18, 'Korkarak, gözleyip bekleyerek şehirde sabahladı, derken dün kendisinden yardım isteyen, gene birisiyle çekişmedeydi ve gene kendisinden yardım istedi. Musa da ona, şüphe yok ki dedi sen, apaçık bir azgınsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 19, 'Kendilerine düşman olanı tutmak isteyince öbürü, Musa''yı kendi aleyhinde sanıp ey Musa dedi, dün birini öldürdüğün gibi beni de öldürmek istiyorsun galiba; sen, yeryüzünde mutlaka bir cebbar olmak istiyor, ara buluculardan olmayı hiç dilemiyorsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 20, 'Ve şehrin öte yanından koşa koşa birisi geldi de ey Musa dedi, ileri gelenler, seni öldürmek için birbirleriyle görüşüp danışmadalar, hemen çık git, şüphe etme ki ben sana öğüt verenlerdenim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 21, 'Musa, korkarak, çekinip gözetleyerek şehirden çıktı ve Rabbim dedi, sen beni zalim topluluktan kurtar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 22, 'Medyen tarafına yönelince de umarım ki dedi, Rabbim, beni doğru yola sevk eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 23, 'Medyen suyuna varınca orada, hayvanlarını sulayan bir bölük halk gördü. Gerilerinde de iki kadın vardı, onlar, hayvanlarını sudan menediyorlardı. Musa, ne yapıyorsunuz, niçin hayvanlarınızı sulamıyorsunuz deyince dediler ki çobanlar gidinceye dek biz, hayvanlarımızı sulayamıyoruz ve babamız da pek ihtiyar bir adam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 24, 'Musa, onların hayvanlarına su verdi, sonra da bir gölgeye çekilip Rabbim dedi, bana, hayra ait ne indirdiysen, ne lütufta bulunduysan şüphe yok ki hepsine de muhtacım ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 25, 'Derken o iki kadının biri, utanarak ona geldi de babam dedi, hayvanlarımızı suladığından dolayı seni mükafatlandırmak için çağırıyor. Musa, ona gidip başından geçenleri anlatınca o, korkma dedi, zalim topluluktan kurtuldun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 26, 'O iki kızın biri de babacığım dedi, onu ücretle tut, şüphe yok ki ücretle tutacağın adamların en hayırlısı, en emini bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 27, 'Babası, Musa''ya dedi ki: Bana sekiz yıl hizmet edersen buna karşılık sana şu iki kızımdan birini vermek istiyorum; ama sen on yılı doldurursan bu da sana ait artık ve ben, sana zahmet ve meşakkat vermek istemem; Allah dilerse beni iyi kişilerden bulursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 28, 'Musa, bu dedi, seninle benim aramda bir sözleşme. Hangi müddeti tamamlarsam tamamlayayım, demek bir haksızlık edilmeyecek bana ve Allah da şu sözlerimize tanık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 29, 'Derken Musa, o müddeti bitirince ailesiyle yola düştü ve Tur tarafında bir ateş gördü. Âilesine, siz durun dedi, gerçekten de bir ateş görüyorum ben, gideyim de orada birisi varsa yoldan haber alayım, yahut da ısınmanız için bir kor getireyim size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 30, 'Oraya gelince kutlu yerde bulunan vadinin sağ tarafındaki ağaçtan kendisine nida edildi: Ey Musa, şüphe yok ki ben, alemlerin Rabbi Allah''ım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 31, 'Ve at sopanı yere. Musa, sopayı, bir yılan gibi kıvranıyor görünce geri döndü ve bir daha da oraya gelmemek istedi. Rab, ey Musa dedi, gel ve korkma, şüphe yok ki sen, emniyete erenlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 32, 'Elini koynuna koy da bir hastalık yüzünden olmaksızın bembeyaz, parılparıl parlar bir halde çıksın, korkudan yanlarına düşen ellerini kavuştur göğsüne; bu iki şey, Rabbinden, Firavun''a ve ileri gelen adamlarına iki kesin delil; şüphe yok ki onlar, buyruktan çıkmış bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 33, 'Musa, Rabbim dedi, ben onlardan birisini öldürdüm, korkarım, beni öldürürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 34, 'Ve kardeşim Harun, dil bakımından benden daha fasih, onu da benimle beraber gönder de bana yardım etsin, gerçeklesin beni, çünkü ben yalanlamalarından korkmaktayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 35, 'Kardeşinle dedi, kolunu kuvvetlendireceğiz ve size öylesine bir kuvvet vereceğiz ki delillerimiz sayesinde size hiçbir fenalıkta bulunamayacaklar; siz ve size uyanlar, üstünsünüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 36, 'Musa, apaçık delillerimizle onlara gelince bu, uydurma bir büyüden başka bir şey değil, gelip geçmiş atalarımız zamanında böyle bir şey duymadık biz dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 37, 'Musa dedi ki: Kim hidayetle gelmiştir onun katından ve yurdun sonu, kimin için daha hayırlı olacak, bunu Rabbim, daha iyi bilir; şüphe yok ki zalimler, kurtulmazlar muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 38, 'Ve Firavun, ey ileri gelenler dedi, ben, benden başka bir mabudunuz olduğunu bilmiyorum. Ey Haman, balçığa bir ateş yak da tuğla yap bana ve yüksek bir köşk kur, belki oraya çıkar, Musa''nın mabudunu anlarım ve gene de şüphe yok ki ben yalancılardan sanıyorum onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 39, 'O da, askerleri de yeryüzünde haksız yere ululanmaya kalkıştılar ve şüphe yok ki dönüp tapımıza gelmeyecekler sandılar kendilerini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 40, 'Biz de hem onu, hem askerini helak ettik, onları suya boğduk; artık bak da gör, zalimlerin sonucu ne olmuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 41, 'Ve onları, halkı ateşe çağıran rehberler yaptık ve kıyamet günü de yardım edilmez onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 42, 'Ve şu dünyada artlarından lanet ettik onlara ve kıyamet günü de onlar, çirkin bir azaba uğrayanlara katılacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 43, 'Ve andolsun ki gelip geçen eski çağlardaki ümmetleri helak ettikten sonra öğüt alsınlar, ibret alsınlar diye insanlara cangözleri, hidayet ve rahmet olarak Musa''ya kitap verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 44, 'Ve Musa''ya o emri verip takdirimizi yerine getirdiğimiz zaman sen, ne batı tarafındaydın, ne de görüyordun onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 45, 'Fakat biz, Musa''dan sonra da nice nesiller meydana getirdik de ömürleri uzayıp gitti onların ve sen, Medyen halkı içinde oturup ayetlerimizi onlardan okumak suretiyle de bellemedin, fakat biziz onları gönderen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 46, 'Nida ettiğimiz zaman Tur tarafında da değildin; fakat senden önce kendilerine bir peygamber gelmeyen topluluğu, belki ibret alırlar, öğüt dinlerler diye korkutmak için Rabbinden bir rahmet olarak gönderildin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 47, 'Onlara, elleriyle hazırladıkları bir felaket gelip çatsaydı Rabbimiz derlerdi, bize bir peygamber gönderseydin de delillerine uysaydık ve inananlara katılsaydık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 48, 'Fakat katımızdan o gerçek gelince de Musa''ya verilen mucizeler gibi mucizeler verilseydi ona derler; önce Musa''ya verilen mucizeleri de inkar edip iki büyü, birbirini desteklemede bunlar demediler mi ve şüphesiz biz, hepsini de inkar ediyoruz demediler mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 49, 'De ki: Şu iki kitaptan daha fazla doğru yola sevkeden bir kitap getirin doğru söylüyorsanız, getirin de uyayım ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 50, 'Bunu kabul etmezlerse artık bil ki onlar, ancak kendi dileklerine uyuyorlar ve Allah''ın hidayetini bırakıp kendi dileğine uyan kişiden daha sapık kimdir ki? Şüphe yok ki Allah, zalim topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 51, 'Ve andolsun öğüt alsınlar diye sözü, birbiri ardınca ayetayet ulayıp indirmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 52, 'Bundan önce kendilerine kitap verdiklerimiz, inanıyorlar buna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 53, 'Onlara okundu mu inandık ona diyorlar, şüphe yok ki o, Rabbimizden gelen bir gerçek, bundan önce de gerçeğe teslim olmuştuk biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 54, 'İşte onlardır ki mükafatları iki kat verilir onlara sabrettiklerinden dolayı ve onlar, iyilikle giderirler kötülüğü ve kendilerini rızıklandırdığımız şeylerden bir kısmını yoksullara harcarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 55, 'Ve onlar, kötü ve çirkin söz duyunca yüz çevirirler ve bizim yaptıklarımız derler, bize ait, sizin yaptıklarınız size, esenlik size, biz bilgisizleri dilemez, sevmeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 56, 'Şüphe yok ki sen, sevdiğini doğru yola sevkedemezsin ve fakat Allah, dilediğini doğru yola sevk eder ve odur hidayete erecekleri daha iyi bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 57, 'Ve dediler ki: Seninle beraber doğru yola uyarsak yerimizden, yurdumuzdan oluruz, bizi çıkarıverirler buradan. Biz onları, her çeşit yiyeceklerin, meyvelerin getirilip toplandığı emin bir haremde yerleştirmedik mi, onlara katımızdan rızık olarak vermedik mi bunları ve fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 58, 'Ve biz, geçim bolluğuna nail olmuş ve şükretmemiş nice şehirlerin halkını helak ettik; işte pek azı müstesna, kendilerinden sonra insanlara yurt olmayan evleri ve oralara biz varis olmuşuzdur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 59, 'Ve Rabbin, ana şehirlerine, halka ayetlerimizi okuyacak peygamber göndermedikçe şehirleri helak etmez ve biz, halkı zalim olan şehirlerden başka şehirleri helak etmedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 60, 'Ve size ne verildiyse, dünya yaşayışına ait metalardan, dünya ziynetinden ibaret ve Allah katındaki, daha hayırlıdır ve daha sürekli; hala mı akıl etmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 61, 'Kendisine güzelim bir vaitte bulunduğumuz ve vaadettiğimize kavuşmuş olan, dünya yaşayışında nimetlendirdiğimiz, sonra da kıyamet gününde tapımıza getirdiğimiz kimseye mi benzer?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 62, 'O gün, onlara nida eder de nerede der, bana eş, ortak sandığınız şeyler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 63, 'Azap edeceğimize dair söylediğimiz sözü hakedenler, Rabbimiz derler, işte şunlar, azdırdığımız kişiler, biz nasıl azmışsak onları da öyle azdırdık. Onlardan uzaklaştık, tapına geldik; onlar, bize tapmıyorlardı zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 64, 'Ve çağırın şirk koştuğunuz şeyleri denir, onlar da çağırırlar, fakat icabet etmezler onlara ve azabı görürler; ne olurdu doğru yolu bulsalardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 65, 'Ve o gün onlara nida eder de ne cevap verdiniz der, gönderilen peygamberlere?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 66, 'O gün bütün bahaneler kör olur onlarca ve hiçbir şey söyleyemezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 67, 'Fakat tövbe eden ve inanan ve iyi işlerde bulunan, umulur ki kurtulanlardan olur, muradına erer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 68, 'Ve Rabbin, dilediğini yaratır ve seçer; seçmek, onlara ait bir hak değildir; münezzehtir Allah ve yücedir şirk koştukları şeylerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 69, 'Ve Rabbin bilir, gönüllerinde ne saklıyorlarsa ve neyi açıklıyorlarsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 70, 'Ve o, bir Allah''tır ki yoktur ondan başka tapacak, onadır hamd önde de, sonda da ve onundur hüküm ve dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 71, 'De ki: Allah, kıyamet gününe dek geceyi uzatsaydı size, Allah''tan başka kim bir ışık verebilirdi size? Hala mı duymazsınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 72, 'De ki: Allah, kıyamet gününe dek gündüzü uzatsaydı, içinde huzura erip dinleneceğiniz geceyi Allah''tan başka kim getirebilirdi size? Hala mı görmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 73, 'Ve rahmetindendir ki sükun ve huzura ermeniz ve lutfundan rızkınızı arayıp bulmanız ve şükretmeniz için geceyle gündüzü halketti size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 74, 'Ve o gün onlara nida edilir de Nerede denir, bana eş sandıklarınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 75, 'Ve biz her ümmetten bir tanık getirir de getirin bakalım deriz, delillerinizi. Artık bilirler ki şüphesiz gerçek, Allah''ındır ve uydurdukları şeylerin hepsi de gözlerinden kaybolup gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 76, 'Şüphe yok ki Karun, Musa''nın kavmindendi de onlara karşı isyan etti; ona öyle hazineler vermiştik ki anahtarlarını bile güçlükuvvetli on, onbeş kişi götüremezdi. Hani kavmi ona sevinip övünme demişti, şüphe yok ki Allah, sevinip övünenleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 77, 'Allah''ın sana verdiği malmenal yüzünden ahiret yurdunu aramaya bak ve dünyadaki nasibini de unutma ve Allah sana nasıl ihsan ettiyse sen de ihsan et ve yeryüzünde bozgunculuk etmeye kalkışma; şüphe yok ki Allah, bozguncuları sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 78, 'O, bu dedi, ancak bendeki bilgi sayesinde bana verilmiştir. Bilmez miydi ki Allah, hiç şüphesiz ondan önce, kuvvet bakımından ondan daha üstün, topluluk bakımından ondan daha fazla nice nesilleri helak etmiştir ve suçluların suçlarını bile sormaya hacet yok zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 79, 'Derken kavminin karşısına süslenip çıktı da dünya yaşayışını dileyenler, ne olurdu dediler, bize de Karun''a verilen verilseydi, şüphe yok ki o, dünya malından büyük bir nasibe sahip.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 80, 'Ve kendilerine bilgi verilenlerse yazıklar olsun size dediler, inanan ve iyi işlerde bulunana Allah''ın sevabı, daha da hayırlıdır ve buna da ancak sabredenler nail olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 81, 'Derken onu da, sarayını da yere geçirdik, Allah''tan başka ona yardım edecek bir topluluğa sahip değildi ve kendisinin de kendisine bir yardımı dokunamadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 82, 'Dün, onun yerinde olmayı dileyenler, öylesine sabahladılar ki hey gidi hey diyorlardı, şüphe yok ki Allah, kullarından dilediğinin rızkını bollaştırmada, dilediğini daraltmada, Allah lutfetmeseydi bize, bizi de yere geçirirdi ve hey gidi hey, şüphe yok ki kafirler kurtulmazlar, muratlarına ermezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 83, 'İşte ahiret yurdu; biz onu, yeryüzünde yücelik ve bozgunculuk dilemeyenlere veririz ve sonuç, çekinenlerindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 84, 'Kim bir iyilikle gelirse ona, yaptığından daha hayırlı mükafat var ve kim, bir kötülükle gelirse o kötülükleri işleyenler, ancak yaptıklarının karşılığı neyse onunla cezalandırılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 85, 'Şüphe yok ki sana, Kur''an''ın hükümlerini farz eden, elbette döneceğin yere döndürecek seni. De ki: Rabbim daha iyi bilir, kimdir doğru yola gelen ve kimdir apaçık sapıklıkta kalan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 86, 'Sana ancak Rabbinden bir rahmet olarak kitabın vahyedilmesini umuyordun, artık kafirlere arka olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 87, 'Ve sakın sana indirildikten sonra seni Allah''ın ayetlerinden çevirmesinler ve Rabbine çağır halkı ve sakın şirk koşanlardan olma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (28, 88, 'Ve Allah''la beraber bir başka mabudu çağırma; yoktur tapacak ondan başka; her şey helak olur, ancak onun zatıdır kalan, onundur hüküm ve hepiniz, dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 1, 'Elif lam mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 2, 'İnsanlar, sanırlar mı ki inandık derler de öylece bırakılıverirler ve sınanmaz onlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 3, 'Ve andolsun ki biz onlardan öncekileri de sınadık; artık Allah, doğru olanları da mutlaka bilir, yalancıları da mutlaka bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 4, 'Yoksa kötülük edenler, sanırlar mı ki bizden kurtulacaklar, ne de kötü hükmediyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 5, 'Kim, Tanrı''ya kavuşmayı umarsa artık şüphe yok ki Allah''ın takdir ettiği zaman elbette gelecek ve odur duyan, bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 6, 'Ve kim savaşırsa ancak kendisi için savaşır; şüphe yok ki Allah, alemlerden müstağnidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 7, 'İnananların ve iyi işlerde bulunanların kötülüklerini elbette örteriz ve onları, yaptıklarından daha güzeliyle mükafatlandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 8, 'Ve insana, anasına babasına iyilikte bulunmasını tavsiye ettik ve senin bir bilgin olmayan birşeyi bana eş tutman için seninle çekişirlerse artık itaat etme onlara; dönüp geleceğiniz yer, benim tapımdır, neler yaptıysanız size ben haber vereceğim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 9, 'İnananları ve iyi işlerde bulunanları elbette temiz kişilere katacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 10, 'Ve insanlardan Allah''a inandık diyen var ki Allah uğrunda bir eziyete uğratılınca insanların, kendisini sınamasını Allah''ın azabıymış gibi sayar ve Rabbinden bir yardım ve zafer de gelirse bu çeşit kişiler, biz sizinleyiz derler mutlaka; Allah, alemlerin gönüllerinde ne var, daha iyi bilmez mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 11, 'Ve Allah elbette inananları da bilir, münafıkları da bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 12, 'Kafir olanlar, iman edenlere bizim yolumuza uyun dediler, hatalarınızı biz yükleniriz; halbuki onlar, bunların hatalarından hiç mi hiç, bir şey yüklenemezler, şüphe yok onlar, yalancılardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 13, 'Onlar, elbette kendi yüklerini de yüklenecekler, o yüklerle beraber başka yükleri de ve kıyamet gününde de iftira ettikleri şeyler, elbette sorulacak onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 14, 'Ve andolsun ki biz Nuh''u, kavmine gönderdik de aralarında tam bin yıldan elli yıl eksik bir müddet kaldı; derken onları tufan helak etti ve onlar zalimlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 15, 'Onu ve gemidekileri kurtardık ve bunu, alemlere ibret olarak yaptık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 16, 'Ve İbrahim de hani kavmine demişti ki: Allah''a kulluk edin ve çekinin ondan; bilseniz bu, size daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 17, 'Gerçekten de Allah''ı bırakıp da putlara tapıyor, yalanlar uyduruyorsunuz; Allah''ı bırakıp taptığınız şeylerin, size bir rızık vermeye güçleri yetmez; rızkı, Allah katında arayın ve kulluk edin ona ve şükredin ona; dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 18, 'Ve yalanlarsanız sizden önceki ümmetler de yalanlamıştı ve Peygambere düşen iş, ancak apaçık tebliğden ibaret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 19, 'Görmezler mi ki Allah, nasıl yaratmaya başlıyor, sonra yaratışı, nasıl yeniliyor? Şüphe yok ki bu, Allah''a pek kolay.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 20, 'De ki: Yeryüzünü gezin de bakıp görün, nasıl yaratmaya başlamıştır; sonra Allah ahiret yaşayışını da meydana getirecektir; şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 21, 'Dilediğini azaplandırır ve dilediğine acır ve siz, döndürülüp onun tapısına götürüleceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 22, 'Siz onu, ne yeryüzünde aciz bırakabilirsiniz, ne gökyüzünde ve size, Allah''tan başka da ne bir dost var, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 23, 'Allah''ın delillerine kafir olanlar ve onunla buluşacaklarını inkar edenlerse onlardır rahmetimden tamamıyla ümitlerini kesenler ve onlaradır elemli bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 24, 'Kavminin cevabı, ancak onu öldürün, yahut yakın sözü olmuştu da Allah, onu ateşten kurtarmıştı; şüphe yok ki bunda elbette deliller var inananlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 25, 'Ve siz dedi, dünya yaşayışında birbirinize dost olduğunuzdan bu dostluk yüzünden Allah''ı bırakıp da putları mabud edindiniz, sonra da kıyamet günü, bir kısmınız, bir kısmınızı inkar edecek, bir kısmınız, bir kısmınıza lanet okuyacak ve yurdunuz ateştir ve size hiçbir yardımcı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 26, 'Lut, ona inandı ve İbrahim, ben dedi, bunlardan göçecek, Rabbime sığınacağım, şüphe yok ki o üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 27, 'Ve ona İshak ve Yakup''u verdik ve soyuna, peygamberlik ve kitap ihsan ettik ve dünyada, mükafatını verdik onun ve şüphe yok ki o, ahirette de elbette temiz kişilerdendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 28, 'Ve Lut''u da göndermiştik de hani kavmine demişti ki: Siz, sizden önce, alemlerde hiçbir kimsenin yapmadığı çirkin bir işi yapmadasınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 29, 'Siz, boyuna erkeklerle mi temas edecek, meşru yolu mu kesecek, meclislerinizde hep kötü işlerde mi bulunacaksınız? Kavminin cevabı, ancak eğer doğru söyleyenlerdensen Allah azabını getir bize sözü olmuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 30, 'O da, Rabbim demişti, bozgunculukta bulunan kavme karşı sen yardım et bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 31, 'Elçilerimiz, İbrahim''e müjdeyle gelince, şüphe yok ki demişlerdi, biz şu şehrin halkını helak edeceğiz; şüphe yok ki o şehrin halkı zalim oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 32, 'İbrahim, orada Lut da var demişti de onlar, biz daha iyi biliriz demişlerdi, orada kim var; onu ve ailesini kurtaracağız, ancak karısı kurtulmayacak, o, şüphe yok ki orada kalanlardan olacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 33, 'Elçilerimiz Lut''a gelince Lut, onların yüzünden kederlenmişti, gönlü daralmıştı. Onlar, korkma ve tasalanma demişlerdi; şüphe yok ki biz, seni de, aileni de kurtaracağız, ancak karın müstesna ve şüphe yok o, orada kalanlardan olacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 34, 'Şüphe yok ki bu şehir halkının üstüne, buyruktan çıkarak yapageldikleri işler yüzünden, gökten bir azap indireceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 35, 'Ve andolsun ki biz, akıl eden topluluk için, onlara ait apaçık bir delil bıraktık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 36, 'Ve Medyen''e de kardeşleri Şuayb''i göndermiştik de ey kavmim demişti, kulluk edin Allah''a ve umun ahiret gününü ve yeryüzünde bozgunculuğa çalışmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 37, 'Derken yalanlamışlardı onu da onları bir sarsıntı, helak edivermişti, derken evlerinde diz çökmüş bir halde yerlere yığılıp helak oluvermişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 38, 'Ve Âd''le Semud''u da helak etmiştik ve gerçekten de yerlerinden apaçık anlamaktasınız ve Şeytan, onların yaptıklarını, bezemişti kendilerine ve gerçeği gördükleri halde yoldan çelmişti onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 39, 'Ve Karun''u ve Firavun''u ve Haman''ı da helak etmiştik ve andolsun ki Musa, onlara apaçık delillerle gelmişken tuttular da, yeryüzünde ululanmaya kalkıştılar ve azabı da savuşturamadılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 40, 'Hepsini de suçları yüzünden helak ettik. Onlardan, üstlerine kasırgayla taş yağdırdıklarımız var ve onlardan, bir bağırışla helak olanlar var ve onlardan yere geçirdiğimiz var ve onlardan sulara garkettiğimiz var ve Allah zulmetmemişti onlara ve fakat onlar, kendi kendilerine zulmetmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 41, 'Allah''tan başka dost ve yardımcı edinenler, ağ kuran örümceğe benzerler ve evlerin en çürüğü, elbette örümcek ağıdır bir bilseler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 42, 'Şüphe yok ki Allah, kendisinden başka neye tapıyorlarsa hepsini bilir ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 43, 'Ve işte örnekler, onları insanlara gösterip durmadayız ve bilgi sahiplerinden başkaları anlamaz onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 44, 'Allah, gökleri ve yeryüzünü gerçek olarak yarattı; şüphe yok ki bunda, inananlara deliller var elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 45, 'Oku kitaptan ne vahyedildiyse sana ve namaz kıl; şüphe yok ki namaz, çirkin ve kötü şeylerden alıkoyar insanı ve elbette Allah''ı anmak, pek büyük birşeydir ve Allah, ne işlerseniz hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 46, 'Ve kitap ehliyle, ancak en güzel bir tarzda mücadele edin; yalnız içlerinden zulmedenler müstesna ve deyin ki: İnandık bize indirilene de, size indirilene de ve mabudumuz ve mabudunuz birdir ve biz, ona teslim olmuşuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 47, 'Ve işte sana böyle bir kitap indirdik biz ve bu yüzden kendilerine kitap verilenler, inanıyorlar ona ve şunlardan da inanan var ona ve delillerimizi, kafirlerden başkası da bilerek inkar etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 48, 'Ve sen, bundan önce hiçbir kitap okumazdın ve sağ elinle de bir şey yazmamıştın, öyle olsaydı, batıl, şeylere kapılanlar mutlaka şüpheye düşerlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 49, 'Hayır, o, kendilerine bilgi verilenlerin gönüllerinde kökleşip yerleşmiş olan apaçık delillerdir ve delillerimizi, zalimlerden başkası da bilerek inkar etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 50, 'Ve derler ki ona Rabbinden deliller indirilseydi. De ki: Deliller, ancak Allah katında ve ben, ancak apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 51, 'Onlara yetmez mi ki şüphe yok, sana kitap indirdik, onlara okunup durmada; şüphe yok ki bu kitapta elbette inanan topluluğa hem rahmet var, hem öğüt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 52, 'De ki: Aramda ve aranızda tanık olarak Allah yeter; bilir ne varsa göklerde ve yeryüzünde ve batıla inanıp Allah''a kafir olanlara gelince: Onlardır ziyan edenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 53, 'Ve senden, azabın çarçabuk gelmesini isterler ve muayyen bir zamanı olmasaydı azap, gelip çatardı onlara ve azap, onlara apansız gelecek ve onların haberleri bile olmayacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 54, 'Senden, azabın, çabucak gelmesini isterler ve şüphe yok cehennem elbette kafirleri kuşatmıştır zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 55, 'O gün azap, üstlerinden, ayaklarının altından saracak onları ve tadın diyecek, yaptıklarınızın cezasını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 56, 'Ey inanan kullarım, şüphe yok ki benim yeryüzüm geniştir, artık siz de yalnız bana kulluk edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 57, 'Herkes tadacak ölümü, sonra da dönüp tapımıza geleceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 58, 'İnananları ve iyi işlerde bulunanları, kıyılarından ırmaklar akan cennetin en yüce yerlerinde yerleştireceğiz, orada ebedi olarak kalacaklar; iyi işlerde bulunanlara verilen mükafat, ne de güzeldir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 59, 'Öyle kişilerdir onlar ki sabrederler ve Rablerine dayanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 60, 'Ve nice mahluk vardır ki rızıklarını kendileri bulup götürmezler; onları da Allah rızıklandırır; sizi de ve odur duyan, bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 61, 'Andolsun ki onlara, kim yarattı gökleri ve yeryüzünü ve kim ram etti güneşi ve ayı diye sorsan Allah derler mutlaka, o halde ne diye ona kulluktan dönüp uydurma şeylere kapılıyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 62, 'Allah, kullarından dilediğinin rızkını bollaştırır, dilediğinin daraltır; şüphe yok ki Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 63, 'Andolsun ki onlara, kim yağdırır gökten yağmuru da onunla, ölümünden sonra diriltir yeryüzünü diye sorsan Allah derler mutlaka; de ki: Hamd Allah''a, fakat çoğu akıl etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 64, 'Ve bu dünya yaşayışı, ancak aslı olmayan bir eğlenceden, bir oyundan başka bir şey değil ve şüphe yok ki ahiret yurdunda gerçek yaşayış, bunu bir bilselerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 65, 'Gemiye bindiler mi din hususunda yalnız onu tanıyarak ihlasla Allah''ı çağırırlar, fakat onları karaya çıkarıp da kurtardık mı o zaman derhal şirk koşarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 66, 'Bu da onlara verdiğimiz nimetlere nankörlük edip dünyada geçinip gitmeleri içindir, fakat yakında bilecek onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 67, 'Görmezler mi ki etraflarındaki insanlar, birbirlerini öldürüp dururken biz Harem''i, emin ettik; hala mı batıla inanırlar da Allah''ın nimetine nankörlük ederler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 68, 'Ve kimdir Allah''a yalan yere iftira edenden, yahut Kur''an, kendisine geldikten sonra onu yalanlayandan daha zalim? Kafirlere, cehennemde konaklayacak yer mi yok?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (29, 69, 'Bizim için savaşanları yollarımıza sevk ederiz biz ve şüphe yok ki Allah, elbette beraberdir iyilik edenlerle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 1, 'Elif lam mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 2, 'Rum mağlub edildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 3, 'En yakın bir yerde, fakat onlar bu mağlubiyetten sonra galip olacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 4, 'Birkaç yıl içinde; emir, önde de Allah''ın, sonda da ve o gün inananlar, ferahlayacak, sevinecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 5, 'Allah''ın yardımıyla; o, dilediğine yardım eder ve odur üstün ve rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 6, 'Allah''ın vaadidir; Allah vaadinden caymaz ve fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 7, 'Dünya yaşayışının yalnız dış yüzünü bilirler ve onlar, ahiretten gafil olanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 8, 'Hiç olmazsa kendi kendilerine bir düşünmezler mi ki Allah, gökleri ve yeryüzünü ve ikisinin arasındakileri gerçek olarak ve mukadder bir zaman için yaratmıştır ve şüphe yok ki insanların çoğu, Rablerine kavuşacaklarını inkar ederler elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 9, 'Yeryüzünü gezip de görmezler mi kendilerinden öncekilerin sonları ne olmuş; onlar, kuvvet bakımından daha üstündü bunlardan ve yeryüzünün altını üstüne getirerek ekmişler ve orasını, bunların imar ettiğinden daha da fazla imar etmişlerdi ve onlara da apaçık delillerle gelmişti peygamberleri; derken Allah zulmetmemişti onlara ve fakat onlar, kendilerine zulmetmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 10, 'Sonra da Allah''ın delillerini yalanladıkları ve onlarla alay ettikleri için o kötülük edenlerin sonu kötü oldu gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 11, 'Allah, önce yaratır da sonra öldürerek tekrar halkeder ve yaratılışı yeniler, sonra da hepiniz döndürülür, onun tapısına götürülürsünüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 12, 'Ve kıyametin koptuğu gün, suçlular, rahmetten meyus olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 13, 'Ve onlara, Tanrı''ya ortak sandıkları şeylerden şefaat eden de olmaz ve onlar da Tanrı''ya şerik sandıkları şeylere kafir olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 14, 'Ve kıyametin koptuğu gün yok mu, işte o gün tamamıyla ayrılırlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 15, 'İnanan ve iyi işlerde bulunanlar, cennet bahçesinde sevinip nimetlere nail olur onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 16, 'Ve fakat kafir olanlara ve delillerimizi ve ahirete kavuşacaklarını yalanlayanlara gelince: Artık onlardır azap için hazırlananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 17, 'Artık tenzih edin Allah''ı akşama girince ve sabaha erince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 18, 'Ve onadır hamd göklerde ve yeryüzünde; ve tenzih edin onu gündüzün sonlarında ve öğle vaktinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 19, 'Ölüden diri izhar eder, diriden ölü izhar eder ve yeryüzünü diriltir ölümünden sonra ve böylece çıkarır mezarlarınızdan sizi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 20, 'Ve delillerindendir ki sizi topraktan yaratmıştır da sonra insan haline gelir, yeryüzünün her yanına dağılırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 21, 'Ve delillerindendir ki sizin cinsinizden eşler yaratmıştır size, onlarla uzlaşıp geçinesiniz diye ve aranıza da sevgi ve merhamet ihsan etmiştir; şüphe yok ki bunda, düşünen topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 22, 'Ve delillerindendir göklerin ve yeryüzünün yaratılışı ve dillerinizin ve renklerinizin ayrılığı; şüphe yok ki bunda, bilenlere deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 23, 'Ve delillerindendir uykunuz geceleyin ve gündüzün ve lutfundan rızkınızı arayıp buluşunuz. Şüphe yok ki bunda duyan topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 24, 'Ve delillerindendir ki sizi hem korkutan, hem umduran şimşeği göstermede ve gökten yağmur yağdırmada da o suretle ölümünden sonra yeryüzünü diriltmede. Şüphe yok ki bunda, akıl eden topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 25, 'Ve delillerindendir ki gökle yer, öylece durmada; sonra sizi bir çağırdı mı hemen yeraltından çıkacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 26, 'Ve onundur göklerde ve yeryüzünde ne varsa; hepsi de ona itaat eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 27, 'Öyle bir mabuttur ki her şeyi önce yaratır, sonra öldürür de tekrar diriltir ve bu, pek kolaydır ona ve onundur göklerde ve yeryüzünde yüce sıfatlar ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 28, 'Size, kendinize ait birşeyle örnek getirmede: Kölelerinizden, cariyelerinizden, sizi rızıklandırdığımız şeylerde size ortak olanlar var mı ve siz, o mallarda, onlarla bir olur musunuz, onları mallarınıza ortak eder de onlar da, sizin korkup titrediğiniz gibi o malların üstüne korkup titrerler mi? İşte, akıl eden topluluğa delilleri böylece tekrarlayıp açıklarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 29, 'Hayır, o zulmedenler, bilgisizce kendi havalarına uydular; Allah''ın saptırdığı kişiyi kim doğru yola sevkedebilir? Ve onlara bir yardımcı da yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 30, 'Artık, yüzünü tam doğru dine döndür, Allah''ın ilk yarattığı selamet haline ki insanları, o tabii halde, selamet halinde yaratmıştır; Allah''ın yaratışı, din, değiştirilemez; budur en doğru din ve fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 31, 'Ne emrettiyse ona uyarak hepiniz, yüzünüzü o dine döndürün ve namaz kılın ve şirk koşanlardan olmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 32, 'O şirk koşanlardan ki dinlerinde aykırılığa düşmüşler de bölükbölük olmuşlardır ve her zümre, kendisinde bulunana razı olup gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 33, 'Ve insanlara bir zarar erişti mi dönüp Rablerini çağırırlar, sonra onlara, kendi katından bir rahmet tattırınca da onların bir bölüğü, Rablerine şirk koşarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 34, 'Şirk koşarlar, onlara verdiğimiz nimetlere nankörlük etmek için; şimdilik geçinin bakalım, yakında bilip anlarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 35, 'Yoksa biz onlara kesin bir delil mi indirdik de şirk koştukları şeyler hakkında onlara söz söyledi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 36, 'İnsanlara bir rahmet tattırdık mı onunla sevinir, övünürler ve onlara, elleriyle yapıp hazırladıkları bir kötülük gelip çatınca da hemen ümitlerini keserler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 37, 'Görmezler mi ki şüphe yok Allah, dilediğinin rızkını bollaştırır, dilediğinin de daraltır. Şüphe yok ki bunda, inanan topluluğa deliller var elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 38, 'Artık yakınlara, yoksula ve yolda kalana hakkını ver, Allah''ın rızasını dileyenlere bu, daha hayırlıdır ve onlardır kurtulanların, muratlarına erenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 39, 'Halkın malı artsın diye faize ait verdiğiniz şeyler, Allah katında artmaz; Allah''ın rızasını dileyerek verdiğiniz zekat artar ve sevaplarını katkat arttıranlar, onlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 40, 'Öyle bir Allah''tır ki sizi yaratmıştır, sonra rızık vermiştir size, sonra öldürür, sonra da diriltir sizi. Ona eş sandıklarınızın içinde bunlardan bir şey yapabilen var mı? Münezzehtir ve yücedir o şirk koşanların şirk koştukları şeylerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 41, 'Bozgun belirdi karada ve denizde, insanların elleriyle kazandıkları suçlar yüzünden; bu da, belki dönerler, vazgeçerler diye yaptıklarına karşılık çekecekleri cezanın az bir kısmını onlara tattırmak için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 42, 'De ki: Gezin yeryüzünde de bakın, görün önce gelip geçenlerin sonları neye varmış; onların çoğu müşrikti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 43, 'Reddine imkan bulunmıyan o gün, Allah tarafından gelmezden önce yüzünü tam doğru olan dine çevir, o gün onlar, bölükbölük olacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 44, 'Kim kafir olursa küfrünün suçu, ona aittir ve kim, iyi işlerde bulunursa bu çeşit adamlar da o iyiliği kendileri için hazırlamışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 45, 'Bu da, inanan ve iyi işlerde bulunanları, lutfundan mükafatlandırmak içindir, şüphe yok ki o, kafirleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 46, 'Ve delillerindendir şükretmeniz için müjdeci rüzgarları göndermesi ve rahmetini size tattırması ve emriyle gemileri yürütmesi ve lutfundan rızkınızı aratıp buldurması.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 47, 'Ve andolsun ki senden önce de kavimlerine peygamberler gönderdik de apaçık delillerle geldiler onlara; derken cürmettiklerinden dolayı öç aldık onlardan ve inananlara yardım, bir haktır bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 48, 'Öyle bir Allah''tır ki rüzgarları yollar da bulutları sürer onlar, gökyüzünde bulutu yayar dilediği gibi ve dağınık, parçaparça bir hale de koyar onları, derken bakarsın ki bulutlardan yağmur yağmaya başlar da kullarından dilediğine nasip eder o yağmuru ve onlar da müjdelerler birbirlerini, sevinirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 49, 'Halbuki onlara yağmur yağdırılmadan önce hepsi de ümitlerini kesmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 50, 'Artık Allah''ın rahmet eserlerine bak da gör, ölümünden sonra nasıl diriltir yeryüzünü; şüphe yok ki o, elbette ölüyü de diriltir ve onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 51, 'Ve andolsun ki bir rüzgar yolladık da nebatları sararmış gördüler mi ardından hemen nankörlüğe başlarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 52, 'Hiç şüphe yok ki sen, sesini duyuramazsın ölüye ve ardına dönüp giderlerken davetini duyuramazsın sağırlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 53, 'Ve sen, körleri sapıklıklarından döndürüp doğru yola sevkedemezsin. Sen, ancak delillerimize inananlara duyurursun; gerçekten de onlardır Müslüman olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 54, 'Öyle bir Allah''tır ki sizi zayıf bir sudan yaratmıştır, sonra bir zayıflık olan çocukluk çağından çıkarıp güçkuvvet vermiştir size, sonra kuvvetli çağdan gene bir zayıflık çağına ve ihtiyarlık yaşına getirmiştir sizi; yaratır ne dilerse ve odur bilen, gücü yeten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 55, 'Ve kıyametin koptuğu gün suçlular, ancak bir an yatıp eğlendiklerine and içerler; işte böyle asılsız şeylere kapılıyordu onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 56, 'Kendilerine bilgi ve inanç verilenlerse derler ki: Andolsun ki siz, Allah''ın takdiri ne kadarsa, ta tekrar dirileceğiniz günedek yatıp eğlendiniz, gerçekten de budur tekrar dirileceğiniz gün ve fakat siz bilmiyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 57, 'Bir gündür o gün ki kendilerine zulmedenlerin özürleri de kabul edilmeyecek o gün, tövbe edip yaptıklarından vazgeçmeleri de istenmeyecek artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 58, 'Ve biz, bu Kur''an''da, insanlara her çeşit örneği getirdik ve sen, onlara bir delil göstersen: Siz derler, ancak aslı olmayan şeyleri öne sürenlersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 59, 'İşte, Allah, bilmeyenlerin gönüllerini, bu çeşit mühürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (30, 60, 'Dayan, şüphe yok ki Allah''ın vaadi gerçektir ve adamakıllı inanmayanlar, sakın senin gayretini hafifletip gevşetmesin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 1, 'Elif lam mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 2, 'Bunlardır beyanında hikmet, hükümlerinde metanet bulunan kitabın ayetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 3, 'O kitap, iyilik edenleri doğru yola sevkeden, onlara rahmet olan bir kitaptır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 4, 'Onlar, namaz kılarlar ve zekat verirler ve ahirete de iyice inanmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 5, 'Onlardır Rablerinden doğru yolu bulanlar, onlardır kurtulup muratlarına erenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 6, 'İnsanlardan, asılsız ve boş lafları satın alan var, halkı, bilgisi olmadığı halde Allah yolundan saptırmak ve Kur''an''ı alaya almak için; onlar, öyle kişilerdir ki onlaradır horhakir bir hale getiren azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 7, 'Ona ayetlerimiz okununca başını çevirir; sanki duymaz onu, sanki iki kulağında da ağırlık var; artık müjdele onu elemli bir azapla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 8, 'Şüphe yok ki inananlarındır ve iyi işlerde bulunanlarındır Naim cennetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 9, 'Ebedi kalırlar orada; Allah''ın vaadi gerçektir ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 10, 'Gökleri direksiz yaratmıştır, onları görüp durursunuz ve yeryüzüne de sallanıp sizi sarsmaması için metin dağlar koymuştur ve oraya bütün mahlukatı yaymıştır ve gökten yağmur yağdırmıştır da yerde her çeşit güzelim nebatı, çifterçifter bitirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 11, 'İşte bunlar, Allah''ın yarattıklarıdır, ondan başkasının ne yarattığını gösterin bana; hayır, zulmedenler, apaçık bir sapıklık içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 12, 'Ve andolsun ki biz, şükret Allah''a diye Lokman''a hikmet verdik ve kim şükrederse faydası kendisinedir ve kim nankörlük ederse artık şüphe yok ki Allah, müstağnidir, hamde layık odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 13, 'An o zamanı ki hani Lokman, oğluna öğüt verirken oğulcağızım demişti, Allah''a şirk koşma; şüphe yok ki şirk, elbette pek büyük bir zulümdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 14, 'Ve biz, insana, anasınababasına itaat etmesini tavsiye ettik; anası, yaratılışı zayıf olduğu halde gebelikle büsbütün zayıflamış, fakat gene de onu taşımıştı ve gebelikle sütten kesme müddeti, iki yıl sürmüştü; artık şükret bana ve ananla babana; dönüp geleceğin yer, benim tapımdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 15, 'Eğer o hususta bir bilgin olmadığı halde, bana şirk koşman için savaşırlarsa seninle, itaat etme onlara ve dünyada iyilik et onlara ve dönüp benim itaatimi kabul edenlerin yoluna uy, sonra dönüp geleceğiniz yer, benim tapımdır; neler yaptığınızı ben haber vereceğim size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 16, 'Ey oğulcağızım, yaptığın hayır veya şer, bir hardal tanesi kadar bile olsa, o da bir taş içinde, yahut göklerde, yahut da yeryüzünde bulunsa Allah, onu gene meydana çıkarır; şüphe yok ki Allah''ın lütfü boldur, o, her şeyden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 17, 'Ey oğulcağızım, namaz kıl, iyiliği emret, kötülükten vazgeçirmeye çalış halkı ve bu hususta uğradığın sıkıntılara dayan; şüphe yok ki bunlar, kesin olarak yapılması gereken işlerdendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 18, 'Ve ululanıp insanlardan yüz çevirme ve yeryüzünde, kendini beğenerek kibirle yürüme; şüphe yok ki Allah, ululanıp övünenlerin hiçbirini sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 19, 'Ululanarak değil, miskince de değil, vakarla yürümeye bak, sesini fazla çıkarma; şüphe yok ki seslerin en çirkini, eşek anırmasıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 20, 'Görmediler mi ki gerçekten de Allah, ram etti size ne varsa göklerde ve ne varsa yeryüzünde ve görünen ve gizli olan nimetlerini size yaydı, tamamladı ve insanlar içinde, Allah hakkında mücadeleye girişen var bilgisi, delili ve aydınlatıcı bir kitabı yokken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 21, 'Ve onlara, Allah ne indirdiyse ona uyun dendi mi hayır derler, biz, atalarımızı neye uymuş bulduysak ona uyarız; ya Şeytan, onları yakıp kavuran azaba çağırıyorduysa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 22, 'Ve kim, özünü, iyiliklerde bulunarak Allah''a teslim ederse gerçekten de o, şüphe yok ki sağlam bir kulpa yapışmıştır ve işler, sonucu, Allah tapısına varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 23, 'Ve kim, kafir olursa onun kafirliği, tasalandırmasın seni; dönüp varacakları yer, bizim tapımızdır da ne yaptılarsa biz haber veririz onlara; şüphe yok ki Allah, gönüllerde ne varsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 24, 'Onları az bir müddet geçindiririz de sonra istemedikleri halde onları ağır bir azaba atarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 25, 'Onlara, andolsun ki, gökleri ve yeryüzünü kim yarattı diye sorsan Allah derler mutlaka. De ki: Hamd Allah''a, hayır, onların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 26, 'Allah''ındır ne varsa göklerde ve yeryüzünde; şüphe yok ki Allah, müstağnidir, hamde layıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 27, 'Yeryüzünde ne kadar ağaç varsa hepsi kalem, deniz de mürekkeb olsa ve bundan sonra da yedi deniz daha mürekkeb olup o denize katılsa gene Allah''ın sözleri yazılıp tükenmez; şüphe yok ki Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 28, 'Sizin yaratılışınız da, tekrar diriltilmeniz de bir kişinin yaratılması ve diriltilmesi gibidir ancak; şüphe yok ki Allah, duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 29, 'Görmedin mi ki Allah, geceyi kısaltır, bir kısmı gündüz olur, gündüzü kısaltır, bir kısmı gece olur ve ram etmiştir güneşi ve ayı; hepsi de mukadder bir zamana kadar yollarında akıp durur ve şüphe yok ki Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 30, 'Bu da şu yüzdendir; çünkü Allah, gerçektir ve ondan başka herneye kulluk ediyorsanız hepsi de boştur ve şüphe yok ki Allah, öyle bir mabuttur ki odur pek yüce ve büyük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 31, 'Görmedin mi ki gemiler, gerçekten de Allah''ın nimetiyle denizlerde akıp gider size onun delillerini göstermek için; şüphe yok ki bundan adamakıllı sabreden ve adamakıllı şükreden herkese, elbette deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 32, 'Onları, gölgeler yapan, dağlar gibi dalgalar sardı mı dini, yalnız ona ait bilerek ve özlerini yalnız ona bağlayarak Allah''ı çağırırlar; onları kurtarınca içlerinde aşırı gitmeyen, geri kalmayan ve vaadine vefa eden kişiler bulunur ve zaten de ahdine hiç vefa etmeyen nankör kişilerden başkası bilebile inkar etmez delillerimizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 33, 'Ey insanlar, çekinin Rabbinizden ve korkun o günden ki baba, oğluna bir fayda veremediği gibi oğulun da babaya hiçbir hayrı olmaz ve sakın aldatmasın sizi dünya yaşayışı ve sakın o hilebaz Şeytan, aldatmasın sizi Allah hakkında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (31, 34, 'Şüphe yok ki Allah katındadır kıyametin kopacağı zaman ve yağmurun ne vakit ve nereye yağacağı ve o bilir rahimlerdekini ve hiçbir kimse, yarın ne kazanacağını bilmez ve hiçbir kimse, Nerede öleceğini bilmez; şüphe yok ki Allah, her şeyi bilir, her şeyden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 1, 'Elif lam mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 2, 'Bu kitap, alemlerin Rabbi tarafından indirilmiştir, hiç şüphe yok bunda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 3, 'Yoksa, bunu o mu uyduruyor diyorlar? Hayır, o, gerçektir Rabbinden, senden önce, kendilerine bir korkutucu gelmemiş olan topluluğu, doğru yolu bulsunlar diye korkutman için indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 4, 'Öyle bir Allah''tır ki gökleri ve yeryüzünü ve ikisinin arasında ne varsa hepsini altı günde yaratmıştır da sonra arşa hakim olmuştur; ondan başka ne bir dost ve yardımcı var size, ne bir şefaatçi; hala mı düşünüp öğüt almazsınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 5, 'Gökten yeredek her işi tedbir eden odur, sonra o işe memur olan melek, sizin sayışınıza göre miktarı bin yıl tutan bir günde, onun tapısına yükselip çıkar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 6, 'İşte budur gizliyi de bilen, açıktakini de bilen üstün ve hüküm ve hikmet sahibi mabut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 7, 'Öylesine mabut ki her şeyin yaratılışını güzel ve tam yerinde yapmıştır da insanı da balçıktan yaratmaya koyulmuştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 8, 'Sonra onun soyunu, duru bir sudan, aşağılık bir su katresinden yaratmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 9, 'Sonra da onu tamamlamıştır, ona kabiliyet vermiştir ve ona ruhundan üfürmüştür ve size kulak, gözler ve gönüller halketmiştir; ne de az şükredersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 10, 'Ve dediler ki: Yeryüzüne karışıp kaybolduktan sonra mı yeniden yaratılacağız? Hayır, onlar, Rablerine kavuşacaklarını inkar etmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 11, 'De ki: Size memur olan ölüm meleği öldürecek sizi, sonra da dönüp Rabbinizin tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 12, 'Rableri katında başlarını eğerek Rabbimiz, gördük ve duyduk, artık bizi tekrar dünyaya döndür de iyi işlerde bulunalım, gerçekten de adamakıllı inandık dedikleri zaman bir görsen mücrimleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 13, 'Ve dileseydik herkesi doğru yola sevk ederdik ve fakat benden şu söz çıkmıştır, mukadderdir bu: Elbette cehennemi, bütün insanlarla, cinlerle dolduracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 14, 'Tadın azabı, şu güne ulaşacağınızı unuttuğunuzdan dolayı, şüphe etmeyin ki biz de unuttuk sizi ve tadın ebedi olarak azabı yaptıklarınıza karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 15, 'Âyetlerimize, ancak kendilerine anılıp öğüt verildiği zaman yerlere kapanıp secde edenler ve Rablerine hamd ederek onu tenzih edenler ve hiç ululanmaya kalkışmayanlar, inanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 16, 'Yanları, yatak nedir, görmez, korkarak, umarak Rablerini çağırırlar ve kendilerini rızıklandırdığımız şeylerin bir kısmını yoksullara harcarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 17, 'Hiç kimsecik bilmez onlar için gözleri aydınlatacak ne gizli şeyler var; yaptıklarına karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 18, 'İnanan kişi, inançtan çıkan kişiye benzer mi hiç? Eşit olmaz bunlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 19, 'İnananlara ve iyi işlerde bulunanlaradır Me''va cennetleri, yaptıklarına karşılık konuk olmak için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 20, 'Fakat buyruktan çıkanlara gelince: Onların yurtları ateştir; oradan çıkmak istedikleri zaman tekrar atılırlar oraya ve onlara denir ki: Tadın yalanladığınız ateşin azabını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 21, 'Biz, belki dönerler diye pek büyük azaptan önce de onlara yakın bir azabı tattıracağız mutlaka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 22, 'Kendisine Rabbinin delillerinden bir kısmı anılıp onlarla öğüt verildikten sonra da onlardan yüz çevirenden daha zalim kimdir ki? Şüphe yok ki biz, mücrimlerden öç alacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 23, 'Ve andolsun ki Musa''ya da kitap vermiştik, ona kavuşacağında şüphen olmasın ve biz, İsrailoğullarına o kitabı, doğru yolu gösteren bir rehber yapmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 24, 'Ve içlerinden, sabrettikleri takdirde onları, emrimizle doğru yola sevkedecek rehberler tayin etmiştik ve onlar, delillerimize adamakıllı inanmışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 25, 'Şüphe yok ki Rabbin, kıyamet gününde, ayrılığa düştükleri şeyler hakkında, aralarında hükmedecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 26, 'Onları doğru yola sevketmez mi onlardan önce nice ümmetleri helak etmemiz, onların yurtlarında gezip durmadalar; şüphe yok ki bunda deliller var elbet, hala mı işitmezler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 27, 'Görmediler mi ki biz, suyu, kurak ve çorak yerlere akıtırız da o sayede hayvanlarının ve kendilerinin yiyecekleri otları bitiririz; hala mı görmezler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 28, 'Ve derler ki: Doğru söylüyorsanız ne vakit olacak bu fetih?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 29, 'De ki: Fetih günü, kafir olanlar imana gelseler de faydası yok ve onlara mühlet de verilmeyecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (32, 30, 'Artık yüz çevir onlardan ve bekle; şüphe yok ki onlar da beklemedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 1, 'Ey Peygamber, çekin Allah''tan ve itaat etme kafirlerle münafıklara; şüphe yok ki Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 2, 'Ve Rabbinden ne vahyedildiyse ona uy; şüphe yok ki Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 3, 'Ve dayan Allah''a ve Allah yeter koruyucu olarak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 4, 'Allah, bir kişiye iki yürek vermedi ve zıhar yaptığınız eşlerinizi de analarınız yerine koymadı ve evlatlıklarınızı öz oğullarınız olarak halk etmedi; bunlar, sizin ağızlarınızdaki laflar ve Allah, doğruyu söyler ve o, doğru yolu gösterir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 5, 'Onları, babalarının adlarını da anarak çağırın, bu, Allah katında daha doğrudur. Babalarını bilmiyorsanız zaten onlar din bakımından kardeşleriniz ve yardımcılarınızdır ve bir yanlışlıkta bulunursanız bir vebal yok size ve fakat yüreklerinizden bir kasıtla hareket ederseniz vebal altına girersiniz ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 6, 'Peygamber, inananlar üzerinde, kendilerinden ziyade tasarruf ve vilayet sahibidir ve onun eşleri de inananların analarıdır ve akrabalar da, Allah''ın kitabında, diğer inananlardan ve yurtlarından göçenlerden fazla birbirlerine yakındır miras dolayısıyla, ancak dostlarınıza herhangi bir suretle iyilikte bulunabilirsiniz; bu hüküm, kitapta yazılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 7, 'An o zamanı ki biz, peygamberlerden kesin söz almıştık ve senden ve Nuh''tan ve İbrahim''den ve Musa''dan ve Meryemoğlu İsa''dan da ve biz, onlardan pek sağlam ve kesin söz almıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 8, 'Doğruların doğruluğunu sormak için ve kafirlere, elemli bir azap hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 9, 'Ey inananlar, anın size Allah''ın nimetini, hani askerler saldırmıştı üstünüze de onlara bir yel ve görmediğiniz askerler göndermiştik ve Allah, sizin yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 10, 'Hani size hem üst tarafınızdan hücum etmişlerdi, hem alt tarafınızdaki yerlerden ve hani gözler yılmıştı ve korkudan yürekler, ağızlara gelmişti ve Allah hakkında çeşitli zanlara kapılmıştınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 11, 'İşte orada, inananlar, bir sınanmaya uğratılmıştı ve adamakıllı da sarsılmışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 12, 'Hani münafıklarla gönüllerinde hastalık olanlar, Allah ve Peygamberi demişlerdi, bizi ancak aldattılar, vaatlerinde aldatıştan başka bir şey yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 13, 'Ve hani onların bir bölüğü, ey Yesribliler demişti, burada durmanıza imkan yok, dönün artık ve bir bölüğü de Peygamberden, evlerimiz açık, sağlam değil diye izin istemişti, halbuki evleri açık değildi ve sağlamdı, onlar, ancak kaçmayı diliyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 14, 'Eğer şehrin etrafından girilip onların üstlerine varılsaydı da şirk koşmaları istenseydi hemen işe girişirler ve şehirde pek az bir müddet kalırlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 15, 'Halbuki onlar, andolsun ki bundan önce söz de vermişlerdi Allah''a geri dönmemeleri için ve Allah''a verilen söz, sorulacaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 16, 'De ki: Ölümden, yahut öldürülmeden kaçmak, size hiçbir fayda vermez ve o zaman pek az bir müddet geçinir, yaşarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 17, 'De ki: Allah size bir kötülük gelmesini dilerse, yahut bir rahmete nail olmanızı isterse kimdir sizi Allah''tan kurtaracak ve Allah''tan başka onlar, ne bir dost bulabilirler, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 18, 'Gerçekten de sizden geri kalanları ve kardeşlerine de bize gelin diyenleri bilir ve bunların pek azı savaşa gelir ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 19, 'Gelseler de can bakımından pek hasis bir halde gelir onlar, hele bir korkulu çağ, gelip çattı mı görürsün ki gözleri dönmüş, sana bakıyorlar, sanki ölüm yüzünden bayılmışlar, kendilerinden geçmişler; derken korku geçti mi keskin dilleriyle sizi incitmeye başlarlar ve hayra pek düşkün gibi bir tavır alırlar. Onlardır inanmayanlar, derken Allah da onların yaptıklarını hiçe saymıştır ve bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 20, 'Sanırlar ki düşman bölükleri gitmedi ve ö bölükler, bir daha gelseler isterler ki çöllerde, bedevilerin aralarında bulunsunlar da size ait haberleri soruştursunlar ve zaten sizin içinizde de olsalar pek az savaşacaktır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 21, 'Andolsun ki Allah''ın Resulünde, sizin için uyulacak en güzel bir örnek var, o, size en güzel bir numune ve Allah''tan mükafat umana ve ahiret gününde mükafat umana ve Allah''ı çok çok anana da en güzel bir örnektir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 22, 'İnananlar, düşman bölüklerini gördüler mi işte dediler, bu, bize Allah''ın ve Peygamberinin vaadettiği şey ve doğru söylemiştir Allah ve Peygamberi ve bu, onların ancak inançlarını ve teslim oluşlarını arttırmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 23, 'İnananlardan öyle erler var ki Allah''a verdikleri sözde sadakat gösterirler; onlardan kimisi, adağını ödedi, kimisi de beklemede ve onlar, sözlerini, özlerini hiçbir suretle değiştirmediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 24, 'Çünkü Allah, doğruları, doğrulukları yüzünden mükafatlandıracak, münafıklaraysa dilerse azap edecek, dilerse tövbe nasib edecek; şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 25, 'Ve Allah, kafirleri, hiddetleriyle, şiddetleriyle defetti, onlar hiçbir hayra nail olamadan; ve Allah, savaş için yetti inananlara ve Allah, pek kuvvetlidir, üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 26, 'Kitap ehli oldukları halde onlara yardım edenleri de, yüreklerine korku düşürüp kalelerinden sürdü çıkardı, bir kısmını öldürüyordunuz, bir kısmını da tutsak ediyordunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 27, 'Onların yerlerine, yurtlarına, mallarına ve ayak basmadığınız bir yere sizi mirasçı yaptı ve Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 28, 'Ey Peygamber, eşlerine söyle: Dünya yaşayışını ve ziynetini diliyorsanız hadi gelin, size nikah paralarınızı vereyim de güzellikle bırakayım sizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 29, 'Yok, eğer Allah''ı ve Peygamberini ve ahiret gününü istiyorsanız bilin ki hiç şüphe yok, Allah, iyilik edenlerinize büyük bir mükafat hazırlamıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 30, 'Ey Peygamberin eşleri, içinizden kim, apaçık çirkin bir harekette bulunursa iki kat azap edilir ona ve bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 31, 'Ve sizden kim, Allah''a ve Peygamberine itaat eder ve iyi işlerde bulunursa mükafatını iki kat veririz ve ona güzelim bir rızık da hazırlamışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 32, 'Ey Peygamberin eşleri, siz, öbür kadınlardan birine benzemezsiniz; çekiniyorsanız sözü yumuşak bir tarzda söylemeyin ki gönlünde bir hastalık olan ümide düşer sonra ve doğru ve güzel söz söyleyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 33, 'Ve evlerinizde oturun ve ilk cahiliyet devrinde olduğu gibi sokaklara çıkmayın ve namaz kılın ve zekat verin ve itaat edin Allah''a ve Peygamberine. Ancak ve ancak Allah, ey Ehli Beyt, sizden her çeşit pisliği, suçu gidermek ve sizi tam bir temizlikle tertemiz bir hale getirmek diler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 34, 'Ve ey Peygamberin eşleri, evlerinizde okunan ayetleri ve hikmeti anın; şüphe yok ki Allah''ın lütfü boldur ve o, her şeyden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 35, 'Şüphe yok ki Müslüman erkeklere ve Müslüman kadınlara, inanan erkeklere ve kadınlara, itaat eden erkeklere ve kadınlara, doğru söyleyen erkeklere ve kadınlara, sabreden erkeklere ve kadınlara, korkan erkeklere ve kadınlara, sadaka veren erkeklere ve kadınlara, oruç tutan erkeklere ve kadınlara, ırzlarını koruyan erkeklere ve kadınlara, Allah''ı çokçok anan erkeklere ve kadınlara; Allah, onlara yarlıganma ve büyük bir mükafat vaadetmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 36, 'Allah ve Resulü, bir işe hükmetti mi erkek olsun, kadın olsun, hiçbir inananın, o işi istediği gibi yapmakta muhayyer olmasına imkan yoktur ve kim, Allah''a ve Peygamberine isyan ederse gerçekten de apaçık bir sapıklığa düşmüş, sapıtıp gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 37, 'An o zamanı ki Allah''ın, kendisine nimet verdiği ve senin de nimetler verdiğin kişiye eşini bırakma ve çekin Allah''tan diyordun ve Allah''ın açığa vuracağı şeyi, içinde gizliyordun ve insanlardan korkuyordun ve Allah''tan korkman daha doğruydu ve o, daha layıktı buna. Derken Zeyd, eşinden ilişiğini kesince biz o kadını sana eş ettik, bu da, oğul edinilen kişiler, eşlerinden ayrıldıkları zaman onların bıraktıkları kadınları inananların almalarında bir beis olmadığını bildirmek içindi ve Allah''ın emri yerine gelmiş oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 38, 'Allah''ın, ona farzettiğini yapmasında hiçbir vebal yok Peygambere; daha önce gelip geçenler hakkında da Allah''ın koyduğu yol yoradam buydu ve Allah''ın emri, takdir edilmiş ve yerine gelmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 39, 'O gelip geçen peygamberler, öyle kişilerdi ki Allah''ın elçiliğini yapıp hükümlerini tebliğ ederler ve ondan korkarlar ve Allah''tan başka hiçbir kimseden korkmazlardı ve hesap görmeye de Allah yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 40, 'Muhammed, sizden birisinin babası değildir ve fakat Allah''ın resulüdür ve peygamberlerin sonuncusu ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 41, 'Ey inananlar, Allah''ı çok çok anın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 42, 'Ve onu sabah, akşam, tenzih edin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 43, 'Öyle bir mabuttur ki sizi karanlıklardan aydınlığa çıkarmak için o ve melekleri, rahmetler ihsan eder size ve o, inananlara rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 44, 'Ve ona kavuşacakları gün, birbirlerine iltifatları, esenlik size sözüdür ve onlara pek güzel bir mükafat hazırlamıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 45, 'Ey Peygamber, gerçekten de seni, bir tanık, bir müjdeci ve bir korkutucu olarak gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 46, 'Ve izniyle, halkı Allah''a davetçi ve aydınlatıcı bir ışık olarak yolladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 47, 'Ve müjdele inananları ki şüphe yok, onlara, Allah''tan büyük bir lütuf ve ihsan var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 48, 'Ve itaat etme kafirlerle münafıklara ve eziyetlerine aldırış etme ve dayan Allah''a ve koruyucu olarak Allah, yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 49, 'Ey inananlar, inanan kadınları nikahladıktan sonra onlara dokunmadan boşarsanız onlar için sayacağınız bir bekleme müddeti yoktur; onlara geçinecek bir şey verin ve güzellikle bırakın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 50, 'Ey Peygamber, mehirlerini verdiğin eşlerini ve Allah''ın ganimet olarak sana ihsan ettiği ve senin de temellük ettiğin cariyeleri, amcanın, halanın, dayının ve teyzenin, seninle beraber yurdundan göçen kızlarını helal ettik sana. Bir de inanan bir kadın, kendisini Peygambere bağışlar da Peygamber de dilediği takdirde onu nikahla almak isterse bu, yalnız sana helaldir, başka inananlara değil. Sana bir güçlük olmasın diye onlara, eşleri ve sahip oldukları cariyeleri hakkında ne farz ettiğimizi de gerçekten bildirdik ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 51, 'Bunlardan dilediğini bırakabilirsin, dilediğini de alabilirsin ve bıraktığını tekrar almada da bir vebal yok sana; bu, gözlerinin ışıklanması, mahzun olmamaları ve verdiğin şeye, hepsinin de razı olması bakımından daha iyidir ve Allah, gönüllerinizdene varsa bilir ve Allah, her şeyi bilir, azap etmede de acele etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 52, 'Bundan sonra kadın almak ve onlardan birini, değiştirmek, hatta güzellikleri seni hayretlere salsa bile, helal değildir sana, ancak malınla temellük ettiğin cariyeler müstesna ve Allah, her şeyi görür, gözetir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 53, 'Ey inananlar, yemeğe davet edilmeden Peygamberin evlerine gitmeyin, davet edilirseniz yemek vaktini beklemek üzere daha önce gitmeyin; fakat çağrılınca gidin ve yemek yiyince dağılın, konuşmak için uzun uzadıya oturmayın; şüphe yok ki bunlar, Peygamberi incitir de utanır sizden ve Allah''sa doğruyu söylemekten çekinmez ve kadınlarından bir şey istediğiniz zaman perde ardından isteyin; bu, sizin yürekleriniz bakımından da daha temizdir, onların yürekleri bakımından da ve Allah''ın Peygamberini incitmeniz caiz olmadığı gibi onun eşlerini de bundan böyle ebediyen almayın; şüphe yok ki bu, Allah katında pek büyük bir günahtır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 54, 'Birşeyi açığa vursanız da, gizleseniz de hiç şüphe yok ki Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 55, 'Peygamberin kadınlarının, babalarına, oğullarına, erkek kardeşlerine, erkek kardeşlerinin oğullarına, kız kardeşlerinin oğullarına, inanan kadınlara ve sahip oldukları kölelere ve cariylere görünmelerinde bir vebal yok ve çekinin Allah''tan; şüphe yokki Allah her şeye tanıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 56, 'Şüphe yok ki Allah ve melekleri, salavat getirir Peygambere; ey inanlar, siz de ona salavat getirin, tam teslim olarak da selam verin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 57, 'Gerçekten de Allah''ı ve Peygamberini incitenlere Allah, dünyada da lanet etmiştir, ahirette de ve onlara, horlayıcı, aşağılatıcı bir azap hazırlamıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 58, 'Kadın ve erkek, inananlara, yapmadıkları suçlar yüzünden eziyet edenler, pek büyük bir yalan ve apaçık bir günah yüklenmişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 59, 'Ey Peygamber, eşlerine ve kızlarına ve inananların kadınlarına söyle; dışarı çıkacakları vakit dışarıya mahsus elbiselerini giysinler; bu, onların tanınıp incinmemelerini daha iyi sağlar ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 60, 'Münafıklarla gönüllerinde hastalık olanlar ve Medine''de kötü haberler yayanlar, bu işten vazgeçmezlerse andolsun ki sana, onlara karşı bir kuvvet veririz de sonra artık orada pek az bir müddet komşu olabilirler sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 61, 'Lanet edilmişler; nerede bulunurlarsa yakalanırlar ve boyuna öldürülüp dururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 62, 'Bundan önce gelip geçenler hakkında da Allah''ın yoluyoradamı buydu ve Allah''ın yolundayoradamında bir değişme bulamazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 63, 'İnsanlar, kıyameti sorarlar sana; de ki: Onun bilgisi, ancak Tanrı katında ve ne bilirsin, belki de kıyamet, pek yakında kopacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 64, 'Şüphe yok ki Allah, kafirlere lanet etmiştir ve onlara, yakıp kavurucu bir azap hazırlamıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 65, 'Orada ebedi ve daimi kalırlar; ne bir dost bulurlar, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 66, 'O gün yüzleri, ateş içinde renkten renge girerken ne olurdu derler, Allah''a itaat etseydik ve Peygambere itaat etseydik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 67, 'Ve Rabbimiz derler, gerçekten de ulularımıza ve büyüklerimize itaat ettik de onlar, sapıttı yolumuzu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 68, 'Rabbimiz, onları iki kat azaplandır ve onlara, pek büyük bir lanetle lanet et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 69, 'Ey inananlar, Musa''yı incitenlere benzemeyin; Allah, onu, onların söyledikleri şeylerden temize çıkardı, uzaklaştırdı tamamıyla ve o, Allah katında pek değerliydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 70, 'Ey inananlar, çekinin Allah''tan ve sözün düzünü, doğrusunu söyleyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 71, 'Söyleyin de yaptığınız işleri iyi ve düzgün bir hale getirsin ve suçlarınızı yarlıgasın ve kim, Allah''a ve Peygamberine itaat ederse gerçekten de pek büyük bir kurtuluşa nail olur, muradına erer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 72, 'Şüphe yok ki biz arzettik emaneti göklere ve yeryüzüne ve dağlara, derken onlar, onu yüklenmekten çekindiler ve ondan korktular ve onu yükledik insana; şüphe yok ki çok zalim oldu, çok bilgisiz bir hale geldi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (33, 73, 'Emanete hıyanet etmeleri yüzünden Allah, münafık erkeklerle münafık kadınları ve şirk koşan erkeklerle şirk koşan kadınları azaplandıracak, hıyanette bulunmayan inanmış erkeklerle inanmış kadınlara da tövbe nasip edecektir ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 1, 'Hamd Allah''a ki onundur ne varsa göklerde ve ne varsa yeryüzünde ve onundur hamd ahirette de ve odur hüküm ve hikmet sahibi ve her şeyden haberdar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 2, 'Yere gireni, oradan çıkanı, gökten ineni, göğe ağanı bilir ve odur rahim olan, suçları örten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 3, 'Kafir olanlar dediler ki: Kıyamet kopmayacak; de ki: Hayır, gizli şeyleri bilen Rabbime andolsun ki kopacak kıyamet başınıza; zerre kadar bir şey bile gizli kalmaz ondan; göklerde olsun, yeryüzünde bulunsun, bundan da küçük olsun, bundan da büyük olsun, hepsi de apaçık kitaptadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 4, 'İnananları ve iyi işlerde bulunanları mükafatlandırmak için; onlar, öyle kişilerdir ki onlarındır yarlıganma ve güzelim bir rızık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 5, 'Delillerimizi boşa çıkarmaya uğraşanlara gelince: Onlar, öyle kişilerdir ki onlarındır elemli ve kötü bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 6, 'Kendilerine bilgi verilenlerse bilirler ki sana Rabbinden indirilen, gerçektir ve üstün ve hamde layık mabudun yolunu göstermededir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 7, 'Ve kafir olanlar dediler ki: Size bir adam gösterelim mi ki paramparça olup dağıldıktan sonra şüphe yok yeniden dirileceğinizi size haber vermede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 8, 'Yalan yere Allah''a mı iftira etmede, yoksa bir delilik mi var onda? Hayır, ahirete inanmayanlar, azapta ve pek büyük bir sapıklık içinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 9, 'Önlerinde ve artlarında, onları kuşatan göğe ve yere bakmıyorlar mı hiç? Dilersek yere geçiririz onları, göğün bir parçasını başlarına yıkarız; şüphe yok ki bunda, mabuduna dönüp teslim olan her bir kula elbette bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 10, 'Ve andolsun ki biz, Davud''a, katımızdan lutfettik, üstünlük verdik. Ey dağlar dedik, onunla beraber tenzih edin beni ve ey kuşlar, siz de ve ona, demiri yumuşattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 11, 'Zırhlar yap dedik ve onları ne ince, ne kalın, tam münasip bir metanette ör ve iyi işlerde bulunun; şüphe yok ki ben ne yaparsanız hepsini görürüm.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 12, 'Ve Süleyman''a da rüzgarı ram ettik, sabahleyin bir aylık yol alırdı, akşamleyin bir aylık yol ve ona bakır madenini, sel gibi akıttık ve cinlerden, huzurundan iş işliyenler vardı Rabbinin izniyle ve onlardan, emrimizden çıkana yakıp kavuran azabı tattırırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 13, 'Kalelerden, heykellerden, büyük havuzlara benzer çanaklardan ve sağlam, yerinden kalkmaz kazanlardan ne isterse yaparlardı ona; ey Davud soyu, şükredin ve kullarımdan pek azı şükreder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 14, 'Mukadder ölümünü hükmettiğimiz zaman da sopasını yiyen kurttan başka hiçbir mahluk, öldüğünü bildirmedi onlara; yere yıkılınca anlaşıldı ki cinler, gizli olan şeyleri bilselerdi aşağılatıcı azap içinde kalıp durmazlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 15, 'Andolsunki Sebe kavmine, oturdukları yerde bile bir delil vardı, sağda, solda iki bahçe bulunmadaydı; yiyin Rabbinizin rızkından ve şükredin ona; tertemiz bir şehir ve suçları örten bir Rab.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 16, 'Derken yüz çevirdiler de onlara setin suyunu gönderdik ve bahçelerini, ancak böğürtlen, ılgın ve birazcık da köknar yetiştiren iki çorak tarlaya çevirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 17, 'İşte nankörlükleri yüzünden böyle cezalandırdık onları ve biz, nankör olandan başkasına ceza verir miyiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 18, 'Onların şehirleriyle kutladığımız şehirler arasında, adeta birbirine bitişik nice şehirler halketmiştik ve o şehirlere gidip gelmeyi kolay bir hale getirmiştik; demiştik ki: Geceleri, gündüzleri emniyet içinde gezin, dolaşın oralarda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 19, 'Rabbimiz dediler, gidip geleceğimiz yerlerin aralarını uzaklaştır ve kendilerine zulmettiler, derken onları masala çevirdik, paramparça ettik onları; şüphe yok ki bunda, adamakıllı sabreden ve iyiden iyiye şükreden her kişiye deliller var elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 20, 'Ve andolsun ki İblis''in, onlar hakkındaki zannı doğru çıktı, derken, inananlardan bir bölükten başka hepsi de ona uydu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 21, 'Ve onlar üzerinde hiçbir kudreti yoktu onun, ancak biz, ahirete inananla o hususta şüphe içinde kalanı ayırt etmek için yaptık bunu ve Rabbin, her şeyi adamakıllı korur, hiçbir şey, bilgisinden dışarı değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 22, 'De ki: Çağırın Allah''tan başka mabut sandıklarınızı; göklerde ve yeryüzünde bir zerre kadar bile bir şeyleri yoktur onların ve ne eşlikleri, ortaklıkları var Tanrıyla, ne de onun, bunlardan bir yardımcısı var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 23, 'Katında, izin vermediğinin şefaati kabul edilmez; sonunda, yüreklerindeki korku giderilince Rabbiniz ne dedi derler, onlar da derler ki: Gerçek söz dedi ve odur pek yüce ve pek büyük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 24, 'De ki: Kimdir sizi rızıklandıran göklerden ve yeryüzünden? De ki: Allah ve şüphe yok ki biz, yahut siz elbette doğru yoldayız, yahut da apaçık sapıklık içinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 25, 'De ki: Bizim işlediğimiz suçlar, sizden sorulmaz ve sizin yaptıklarınız da bizden sorulmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 26, 'De ki: Rabbimiz, bizi bir araya toplar, sonra aramızda gerçekle hükmeder ve odur her şeyi bilen ve tam hükmeden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 27, 'De ki: Gösterin bana ona eş sanıp mabutluğa kattıklarınızı; haşa; ancak odur üstün, hüküm ve hikmet sahibi Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 28, 'Ve biz, seni bütün insanlara, ancak müjdeci ve korkutucu olarak gönderdik ve fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 29, 'Ve derler ki: Ne vakit yerine gelecek bu vait, doğru söylüyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 30, 'De ki: Size vaadedilen gün, öylesine bir gündür ki zamanından bir an bile geriye kalmayacağı gibi ileriye de atılmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 31, 'Ve kafir olanlar, biz dediler, ne şu Kur''an''a inanırız, ne de ondan önceki kitaplara. Bir görmeliydin zalimlerin, Rablerinin katında öylece kalakaldıkları ve birbirlerinin sözlerini kesip söylendikleri günkü hallerini; o zayıf ve aşağılık sanılanlar, ululuk satanlara derler ki: Siz olmasaydınız biz mutlaka inanırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 32, 'Ululuk satanlarsa aşağılık sanılanlara biz mi derler, sizi doğru yoldan çıkardık, o doğru yol, size bildirildikten sonra? Hayır, siz suçlusunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 33, 'Ve aşağılık sanılanlar da büyüklük satanlara, hayır derler, gecegündüz düzenler kurup duruyor ve o zamanlar, bize de Allah''a kafir olmamızı ve ona eşler tanımamızı emrediyordunuz ve azabı görünce hepsinde de nedamet belirir ve biz de kafir olanların boyunlarına zincirler vururuz. Onların yaptıklarına karşılık başka bir şey mi verecektik ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 34, 'Ve hiçbir şehre korkutuculardan birini göndermedik ki oradaki nimete, mala sahib olanlar, şüphe yok ki biz, size gönderilen şeyleri inkar ediyoruz demesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 35, 'Ve biz demişlerdi, mal bakımından da daha fazla mala sahibiz, evlat bakımından da topluluğumuz daha çok ve bize azap edilemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 36, 'De ki: Şüphe yok ki Rabbim, dilediğinin rızkını bollaştırır, dilediğinin daraltır ve fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 37, 'Sizi, bizim katımıza ne mallarınız yakınlaştırabilir, ne evladınız, ancak kim inanır ve iyi işlerde bulunursa o, yaklaşır bize ve işte onlar, öyle kişilerdir ki onlaradır yaptıklarına karşılık katkat mükafat ve onlardır yüce derecelerde emniyet içinde olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 38, 'Ve onlar ki delillerimizi boşa çıkarmaya uğraşırlar, onlardır, azapta hazır bulundurulanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 39, 'De ki: Şüphe yok ki Rabbim, kullarından dilediğinin rızkını bollaştırır, dilediğininse daraltır ve hayır için herhangi bir şey harcarsanız derhal onun karşılığını verir ve odur rızık verenlerin en hayırlısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 40, 'Ve o gün, hepinizi toplar da sonra meleklere, bunlar mı der, size tapıyorlardı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 41, 'Melekler, tenzih ederiz seni derler, sensin bizim sahibimiz ve yardımcımız, onlar değil. Hayır, onlar, cinlere kulluk ediyorlardı, çoğu, onlara inanıyordu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 42, 'İşte bugün birbirinize ne bir faydanız dokunabilir, ne bir zararınız ve zulmedenlere, tadın yalanladığınız ateşin azabını deriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 43, 'Onlara, apaçık ayetlerimizi okuduğun zaman bu adam derler, sizi atalarınızın kulluk ettiği şeylerden vazgeçirmek isteyen birisi ancak ve bu derler, uydurulmuş düzme bir şey ancak ve kafir olanlar, onlara gerçeğe ait bir şey geldi mi, bu derler, apaçık bir büyü ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 44, 'Ve halbuki biz, onlara okuyup ders alacakları kitaplar vermediğimiz gibi senden önce bir kokutucu da göndermemiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 45, 'Onlardan öncekiler de yalanlamışlardı ve bunlar, onlara verdiklerimizin onda birine bile nail olamadılar, öyle olduğu halde yalanladılar da ceza ve azabım, nasıl gelip çattı, helak etti onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 46, 'De ki: Ben size tek bir öğüt vermedeyim ancak: İkişerikişer, tekerteker kalkın da sonra bir düşünün ki sizinle konuşanda deliliğe ait bir emare bile yok; o, ancak ve ancak, şiddetli bir azaptan önce sizi korkutan biri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 47, 'De ki: Sizden bir ücret, bir mükafat da istemiyorum, sizin olsun o. Benim ecrim, ancak Allah''a ait ve o, her şeye tanık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 48, 'De ki: Şüphe yok ki Rabbim, gerçeği yerine getirir, gizli şeyleri de en iyi ve adamakıllı bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 49, 'De ki: Gerçek geldi ve boş şey gitti, ne bir daha zuhur eder, ne de yeniden ve tekrar gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 50, 'De ki: Ben sapıtmışsam suçu, bana ait ve eğer doğru yolu bulmuşsam bu da ancak Rabbimin bana vahyetmesiyle; şüphe yok ki o, her şeyi bilir ve bize bizden de yakındır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 51, 'Ve dehşetli bir korkuya kapıldıkları ve hiçbirinin kurtulamayıp en yakın bir yerde azaba uğratıldıkları gün, bir görsen onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 52, 'Ve diyecekler ki: İnandık ona, fakat bu uzak bir yerde nereden imana kavuşacaklar, ondan faydalanacaklar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 53, 'Ve gerçekten de önce ona kafir olmuşlardı ve uzak bir yerdeyken gizli şeye dair dillerine geleni söylüyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (34, 54, 'Onlarla dileyip arzuladıkları şeylerin arasına bir engeldir çekildi artık, nitekim daha önce onların yolunu tutanlara da böyle olmuştu; şüphe yok ki onlar, tereddüt içindeydiler, şüpheye düşmüşlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 1, 'Hamd Allah''a ki gökleri ve yeryüzünü yaratandır ve melekleri, ikişer, üçer, dörder kanatlı halkedendir; yaratışta neyi dilerse çoğaltır da; şüphe yok ki Allah''ın her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 2, 'Allah''ın, kullarına rahmet ve ihsanına dair lutfedeceği şeye mani olan bulunamaz ve eğer kısar da vermezse ondan başka gönderecek de olamaz ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 3, 'Ey insanlar, anın Allah''ın size verdiği nimetleri; Allah''tan başka bir yaratıcı var mıdır ki sizi rızıklandırsın gökten ve yeryüzünden; ondan başka yoktur tapacak, o halde ne diye boş şeylere kapılıyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 4, 'Seni yalanlıyorlarsa senden önceki peygamberler de yalanlandı ve işler, dönüp Allah''a varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 5, 'Ey insanlar, şüphe yok ki Allah''ın vaadi gerçektir, sakın dünya yaşayışı aldatmasın sizi ve sakın hilebaz Şeytan, aldatmasın sizi Allah hakkında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 6, 'Şüphe yok ki Şeytan, size düşmandır, sizde ona düşman olun. Onun taifesi, sizi yakıp kavuran ateş ehli olmaya davet eder ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 7, 'O kişiler ki kafir olmuşlardır, onlaradır çetin azap ve o kişiler ki inanmışlardır ve iyi işlerde bulunmuşlardır, onlaradır yarlıganma ve pek büyük bir mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 8, 'İşlediği kötü iş kendisine bezenen ve onu güzel gören adam, iyiyi, kötüyü bilen gibi midir? Hiç şüphe yok ki Allah, dilediğini saptırır ve dilediğini doğru yola sevk eder; onlar için hasretlere düşüp üzüntüler verme kendine; şüphe yok ki Allah, onların işledikleri şeyleri bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 9, 'Ve Allah, öyle bir mabuttur ki rüzgarları yollar da bulutu sürer, derken ölü şehri yağmurla suya kandırırız da ölümünden sonra yeryüzünü diriltiriz onunla, işte ölülerin diriltilmesi de böyledir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 10, 'Kim yücelik, üstünlük dilerse bilsin ki bütün yücelik, üstünlük, Allah''ındır; güzel sözler, ona ağar, iyi işler de o sözleri yüceltir ve onlar ki düzenlerle kötülüklerde bulunurlar, onlaradır çetin bir azap ve onların düzenleri de zaten mahvolup gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 11, 'Ve Allah, sizi topraktan yaratmıştır, sonra bir katre sudan, sonra da size eşler halketmiştir. Hiçbir kadın, onun bilgisi olmadıkça gebe kalamaz ve doğuramaz ve hiçbir ömrü uzun adam, ömür süremez ve hiç kimsenin ömrü eksilmez ki bunlar, kitapta mukadder olmasın; şüphe yok ki bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 12, 'Ve iki deniz, bir ve eşit olamaz; şu, tatlı ve içilecek sudur, içilince kandırır adamı, boğazdan kolaycacık ve iyi bir surette kayıp gider; buysa tuzludur, acıdır ve hepsinden de terütaze balıklar çıkarır, yersiniz ve takıp süsleneceğiniz ziynet eşyası çıkarırsınız ve görürsün ki, lütuf ve ihsanını arayıp bulmanız ve şükretmeniz için hepsinde de, suları yarayara gemiler gitmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 13, 'Ve geceyi kısaltır, bir kısmı gündüz olur, gündüzü kısaltır, bir kısmı gece olur ve ram etmiştir güneşi ve ayı; hepsi de mukadder bir zamana kadar yollarında akardurur; işte budur Rabbiniz Allah ve onundur saltanat ve tasarruf; onlar ki onu bırakıp da putlara taparlar, o putlar, çekirdeğin içindeki tek bir kıla bile sahip değildirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 14, 'Onları çağırsanız çağırışınızı duymazlar, imkan olsa da duysalar cevap veremezler size ve kıyamet gününde de şirk koşmanızı inkar ederler ve hiçbir şey, her şeyden haberdar olan gibi haber veremez sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 15, 'Ey insanlar, siz Allah''a karşı yoksulsunuz ve Allahsa, odur müstağni ve hamde layık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 16, 'Ve dilerse sizi giderir, mahveder de yepyeni mahlukat yaratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 17, 'Ve bu, Allah''a göre güç bir şey de değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 18, 'Ve hiçbir suçlu, bir başkasının yükünü yüklenmez ve ağır bir yük taşıyan, onu yüklenmesi için bir başkasını çağırsa, çağırdığı, akrabası bile olsa o yükün bir kısmını bile yüklenemez. Sen, gizli olduğu, görmedikleri halde Rablerinden korkanları ve namaz kılanları korkutabilirsin ancak ve kim, temiz bir hale gelirse faydası, ancak kendisinedir ve dönüp varılacak yer, Allah tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 19, 'Ve ne körle gören eşit olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 20, 'Ve ne karanlıklarla aydınlık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 21, 'Ve ne gölgeyle ısı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 22, 'Ve ne de dirilerle ölüler eşit olur; şüphe yok ki Allah, dilediğine duyurur ve sen kabirlerdeki ölülere duyuramazsın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 23, 'Sen, ancak bir korkutucusun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 24, 'Şüphe yok ki biz seni gerçek üzere bir müjdeci ve bir korkutucu olarak gönderdik ve hiçbir ümmet yoktur ki içlerinden bir korkutucu çıkmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 25, 'Ve seni yalanlarlarsa gerçekten de onlardan öncekiler de, peygamberleri, onlara apaçık delillerle, sahifelerle ve aydınlatıcı kitapla geldikleri halde yalanladılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 26, 'Sonra o kafir olanları helak ettim ben, benim onları inkarım ve cezalandırmam nasılmış, gördüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 27, 'Görmez misin ki şüphe yok, Allah, gökten yağmur yağdırır da o sayede renkleri çeşitçeşit meyveler bitirir ve dağlarda da beyaz, kırmızı, çeşitli renklerde ve kapkara yollar meydana getirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 28, 'Ve insanlardan da, havanlardan da, davarlardan da çeşitli renkte mahluklar yaratır tıpkı bunun gibi; Allah''tan, ancak kullarının bilgili olanları korkar, şüphe yok ki Allah, üstündür, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 29, 'O kişiler ki kitabı okurlar ve namaz kılarlar ve onları rızıklandırdığımız şeylerin bir kısmını gizli, aşikar, yoksullara harcarlar ve bu suretle de kesat bulmaz bir alışveriş umarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 30, 'Onların mükafatını, tamamıyla öder elbette ve lutfundan, ihsanından, mükafatlarını arttırır da; şüphe yok o, suçları örter, mükafatlarını da fazlasıyla verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 31, 'Sana vahyettiğimiz kitap, gerçektir, önceki kitapların gerçekliğini bildirmededir; şüphe yok ki Allah, kullarından haberdardır ve onları görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 32, 'Sonra kitabı, kullarımızdan seçtiklerimize miras bıraktık; derken onlardan nefsine zulmeden var ve onlardan mutedil hareket eden var ve onlardan, hayırlarda herkesten ileri giden var Allah izniyle; işte bu, pek büyük bir lütuf ve ihsandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 33, 'Ebedi olan Adn cennetlerine girerler, orada altın bilezikleri takınırlar, incilerle bezenirler ve elbiseleri de ipektir orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 34, 'Ve hamd Allah''a ki derler, bizden gamı, gussayı giderdi; şüphe yok ki Rabbimiz, suçları örter, mükafatlarını da fazlasıyle verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 35, 'Öyle bir mabuttur ki bizi, tam konaklanacak yurda kondurdu lütfüyle; burada bize ne bir yorgunluk gelir, ne bir usanç gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 36, 'Kafir olanlaraysa cehennem ateşi var, öldürülmezler ki ölüp kurtulsunlar ve cehennem azabı da hafifletilmez onlara; işte biz, fazlasıyla kafir olanları böyle cezalandırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 37, 'Ve onlar bağrışırlar orada: Rabbimiz, bizi çıkar da yaptığımız işlerden başka işlerde bulunalım. Size, düşünenin düşünüp öğüt alanın öğüt alacağı kadar ömür vermedik mi ve size korkutucu da gelmişti; artık tadın azabı, zalimlere bir yardım eden de yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 38, 'Şüphe yok ki Allah göklerdeki gizli şeyleri de bilir, yeryüzündeki gizli şeyleri de; şüphe yok ki o, gönüllerde olanları da bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 39, 'Öyle bir mabuttur o ki sizi yeryüzüne hakim etmiştir; kim kafir olursa zararı kendisine; kafirlerin kafirlikleri, Rablerinin katında ancak gazabıni arttırır; kafirlerin kafirlikleri, ancak ziyanlarını arttırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 40, 'De ki: Gördünüz mü Allah''tan başka taptığınız ve Tanrıya eş sandığınız şeyleri? Gösterin bana, ne yarattılar onlar yeryüzünde, yoksa göklere bir ortaklıkları mı var onların, yahut da onlara bir kitap mı verdik de onlar, apaçık bir delile sahip? Hayır, zalimler, birbirlerine ancak yalan vaitte bulunmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 41, 'Şüphe yok ki Allah, gökleri ve yeryüzünü tutar, mahvolmaktan korur, fakat takdiriyle gökler ve yeryüzü yok olup giderse ondan başka hiç kimse onları koruyamaz, yok olmalarına mani olamaz; şüphe yok ki o, azap etmede acele etmez, suçları örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 42, 'Ve bütün kuvvetleriyle adamakıllı ant içtiler Allah adına, onlara bir korkutucu gelirse ümmetler arasında doğru yolu bulan en mükemmel bir ümmet olacağız diye; fakat onlara korkutucu gelince de bu, ancak onların uzaklaşmalarını sağladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 43, 'Yeryüzünde ululuk satmalarını ve kötü düzenlere baş vurmalarını icabettirdi, halbuki kötü düzen, ancak sahibinindir; onlar, evvelkiler hakkında yürüyen yoldanyoradamdan başka bir şey mi bekliyorlar? Gerçekten de Allah''ın yolununyoradamının yerini hiç bir şey tutmaz ve Allah''ın yoluyoradamı, kesin olarak değişmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 44, 'Yeryüzünde dolaşıp da kendilerinden öncekilerin sonucu ne olmuş, görmezler mi? Ve onlar, bunlardan daha güçlü, daha kuvvetliydi ve Allah''ı aciz bırakamaz hiçbir şey, ister göklerde olsun, ister yeryüzünde; şüphe yok ki o, her şeyi bilir, onun her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (35, 45, 'Allah, kazandıkları suç yüzünden insanlara azap verecek olsaydı yeryüzünde yürür, bir tek mahluk bırakmazdı ve fakat onları, mukadder bir zamanadek bırakır; derken zamanları geldi miydi artık şüphe yok ki Allah, kullarını görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 1, 'Ya Sin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 2, 'Andolsun, beyanında hikmet, hükmünde metanet olan Kur''an''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 3, 'Şüphe yok ki sen, gönderilenlerdensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 4, 'Doğru bir yoldasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 5, 'Üstün ve rahim tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 6, 'Korkutman için, ataları korkutulmamış topluluğu; onlardır gafil olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 7, 'Andolsun ki onların çoğu hakkında şu söz gerçekleşmiştir: Onlardır inanmayanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 8, 'Şüphe yok ki biz, boyunlarına laleler vurduk, elleri, adeta çenelerine kenetlendi lalelerle, bu yüzden onlar, başlarını dimdik tutarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 9, 'Ve önlerine bir set çektik, arkalarına bir set ve gözlerini bağladık da bu yüzden onlar, görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 10, 'Ve birdir onlara korkutsan da, korkutmasan da; onlar, inanmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 11, 'Sen, ancak Kur''an''a uyan ve rahmandan, halk görmese de korkan kişiyi korkutabilirsin; müjdele onu yarlıganmayla ve güzelim bir mükafatla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 12, 'Şüphe yok ki biz, ölüyü diriltiriz ve yazarız önceden, dünyada yaptıklarını ve sonradan bıraktıkları izleri ve her şeyi apaçık bir kitapta sayıp yazdık, takdir ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 13, 'Örnek getir onlara o şehir halkını; hani oraya peygamberler gelmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 14, 'Hani onlara iki kişi göndermiştik de onları yalanlamışlardı, derken bir üçüncü kişiyle kuvvetlendirmiştik onları da şüphe yok ki demişlerdi, biz, size gönderilmiş peygamberleriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 15, 'Onlar, siz demişlerdi, ancak bizim gibi insansınız ve rahman da hiçbir şey indirmemiştir, siz, ancak yalan söylemektesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 16, 'Rabbimiz bilir ki demişlerdi, şüphe yok, biz size gönderildik elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 17, 'Ve bize düşen vazife, ancak apaçık tebliğden ibaret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 18, 'Demişlerdi ki: Gerçekten de sizin yüzünüzden uğursuzluğa uğramadayız, andolsun ki bu işten vazgeçmezseniz elbette taşlarız sizi ve elbette bizden, elemli bir azaba uğrarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 19, 'Onlar da, uğursuzluğunuz demişlerdi, kendinizden; öğüt verilirse de mi yapacaksınız bunu? Hayır, siz, haddi aşmış bir topluluksunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 20, 'Ve şehrin ta öte ucundan birisi, koşarak gelmişti de ey kavmim demişti, uyun peygamberlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 21, 'Uyun sizden hiçbir ücret istemeyenlere ve onlardır doğru yolu bulanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 22, 'Ve ne olmuş bana da beni yaratana kulluk etmeyecekmişim ve siz de, sonunda dönüp onun tapısına gideceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 23, 'Onu bırakıp da başka mabutlar mı kabul edeyim? Rahman, bana bir zarar vermeyi isterse onların şefaatleri, bana hiçbir fayda veremeyeceği gibi onlar, beni kurtaramazlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 24, 'O vakit şüphe yok ki apaçık bir sapıklık içinde kalırım elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 25, 'Şüphe yok ki ben, Rabbinize inandım, duyun sözümü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 26, 'Denildi ki: Gir cennete. Ne olurdu dedi, kavmim de bilseydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 27, 'Ne yüzden Rabbimin beni yarlıgadığını ve yüce derecelere ermişler arasına kattığını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 28, 'Ve ondan sonra kavmine, gökten asker indirmedik ve helak ettiklerimize bu çeşit asker de indirmemiştik zaten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 29, 'Azabımız, ancak bir bağrıştan ibaretti, o anda hepsi de sönüp gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 30, 'Yazıklar olsun kullara, onlara hiçbir peygamber gelmedi ki onunla alay etmesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 31, 'Görmediler mi onlardan önce nice ümmetleri helak ettik ki gerçekten de bir daha dünyaya dönmedi onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 32, 'Ve şüphesiz hepsi de tapımıza getirilmiştir onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 33, 'Ve bir delildir onlara, ölü yeryüzünü dirilttik ve oradan taneler çıkardık da onları yerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 34, 'Ve orada hurmalıklardan, üzüm bağlarından bahçeler halkettik ve orada kaynaklar çıkarıp akıttık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 35, 'Yesinler diye kendi elleriyle meydana getirmedikleri o meyveleri, hala mı şükretmezler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 36, 'Şanı yücedir, münezzehtir yerden bitirdiği şeyleri ve kendilerinden meydana gelen çocukları ve daha da bilmedikleri şeyleri çifterçifter halk edenin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 37, 'Ve bir delildir onlara gece; gündüzü ve güneşin ziyasını çekip sıyırırız ondan da o anda karanlığa dalarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 38, 'Ve güneş de karar edeceği yere kadar akıp gider bu, üstün, hüküm ve hikmet sahibi mabudun takdiridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 39, 'Ve ay için de muayyen zamanlarda konaklar takdir ettik, her devrin sonunda, eski, kuru ve eğri hurma salkımının çöpüne döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 40, 'Ne güneş, aya yetişebilir ve ne gece, gündüzü geçebilir; hepsi de bir gökte yüzüp durur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 41, 'Ve onlara bir delil de, soylarını, dopdolu gemide taşımamızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 42, 'Ve daha da buna benzer nice binecekleri şeyler yarattık onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 43, 'Dilersek sulara boğarız onları da ne bir imdatlarına yeten olur, ne de kurtarılır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 44, 'Ancak bizden bir rahmet olur ve bir zamanadek yaşayıp geçinmeleri takdir edilmiş bulunursa o başka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 45, 'Ve onlara, önünüzde bulunanla ardınızda olan azaptan çekinin de rahmete erin dendi mi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 46, 'Ve onlara, Rablerinin delillerinden bir delil geldi mi ancak yüz çevirirler ondan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 47, 'Ve onlara, Allah''ın, sizi rızıklandırdığı şeylerin bir kısmını hayır yoluna harcayın dendi mi kafir olanlar, inananlara derler ki: Dileseydi Allah doyururdu onu, biz mi doyuralım? Siz, ancak apaçık bir sapıklık içindesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 48, 'Ve derler ki: Bu vait, ne vakit yerine gelecek doğru söylüyorsanız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 49, 'Bir tek bağrıştan başka bir şey beklemiyor onlar, ansızın helak ediverir onları birbirleriyle düşmanlık edip dururlarken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 50, 'Derken bir vasiyette bile bulunmaya imkan bulamazlar ve ailelerine bile dönemezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 51, 'Ve Sur üfürülmüştür de o anda kabirlerinden çıkıp Rablerinin tapısına koşuyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 52, 'Ve demişlerdir ki: Yazıklar olsun bize, kim kaldırdı bizi uyuduğumuz yerden; bu, rahmanın bize vaadettiği şey ve peygamberler gerçek söylemişler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 53, 'Bu, ancak bir bağrıştan ibaret, derken onların hepsi, tapımızda hazır bulunmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 54, 'Gerçekten de bugün, hiç kimseye, hiçbir suretle zulmedilmez ve size de, ancak yaptığınız şeylerin karşılığı verilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 55, 'Şüphe yok ki cennet ehli bugün, nimetler içinde sevinç ve ferah içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 56, 'Onlar da, eşleri de, gölgeliklerde, tahtlara oturup dayanmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 57, 'Onlarındır orada yemişler ve onlarındır diledikleri her şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 58, 'Onlara, rahim Rabden söylenen söz de esenlik size sözüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 59, 'Ayrılın bugün ey suçlular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 60, 'Ey Âdem oğulları, sakın Şeytan''a kulluk etmeyin, şüphe yok ki o, apaçık bir düşmandır size diye emredip söz almadı mı sizden?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 61, 'Ve bana kulluk edin ancak, budur doğru yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 62, 'Ve andolsun ki sizden birçok halk yığınını doğru yoldan saptırdı o, aklınız mı yoktu da akıl edemediniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 63, 'Budur o cehennem ki size vaadedilmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 64, 'Girin mutlaka oraya kafir olduğunuza karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 65, 'O gün, ağızlarını mühürleriz ve ne kazandılarsa elleri, söyler bize ve tanıklık eder ayakları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 66, 'Ve dileseydik onları kör ederdik de doğru yolu ararlar, bulamazlardı, nasıl görebilirlerdi ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 67, 'Ve dileseydik onları çarpıp, durdukları yerde bir başka şekle sokardık da kalakalırlardı, ne ileriye gitmeye güçleri yeterdi, ne geriye dönmeye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 68, 'Ve kimin ömrünü uzatırsak yaratılışta adeta geriye döndürürüz onu, çocuklaşır; hala mı akıl etmezler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 69, 'Ve biz, ona şiir belletmedik ve bu, ona yakışmaz da; bu, ancak bir öğüttür ve her şeyi açıklayan Kur''an.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 70, 'Diri olanı korkutması ve kafirler hakkındaki sözün gerçeğe çıkması için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 71, 'Görmediler mi ki kudretimizle yapıp meydana getirdiklerimizden davarlar halkettik onlara ve onlar da bu davarlara sahib oldular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 72, 'Ve bu davarları onlara münkad ettik de binecekleri hayvanlar da onlardan ve onların bazısını da yerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 73, 'Ve daha da nice menfaatleri var onlarda ve içecekleri de onlardan meydana gelmede; hala mı şükretmezler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 74, 'Ve bir yardıma ermek için Allah''ı bırakırlar da başka mabutlar kabul ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 75, 'Onların, güçleri yetmez yardım etmeye onlara ve asıl onlardır o uydurma mabutların hizmetine hazırlanmış askerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 76, 'Mahzun etmesin seni onların sözleri; şüphe yok ki biz, gizlediklerini de biliriz, açığa vurduklarını da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 77, 'İnsan, kendisini, hiç şüphesiz bir katre sudan yarattığımızı görmedi mi de şimdi o, apaçık bir düşman olmaya kalkışmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 78, 'Ve bize bir örnek getirmede ve yaratılışını da unutmada, çürüyüp dağılmış kemikleri kim diriltir demede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 79, 'De ki: Onu ilk defa yapıp meydana getiren diriltir ve o, her çeşit yaratmayı bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 80, 'Öyle bir mabuttur ki size, yemyeşil ağaçtan ateş halketmiştir de ateşlerinizi onunla yakarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 81, 'Gökleri ve yeryüzünü yaratanın, onların benzerini yaratmaya gücü yetmez mi? Evet ve o, her şeyi yaratan mabuttur, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 82, 'Emri, bir şeyin yaratılmasına taalluk eder, birşeyi yaratmayı dilerse ona ol der, hemen oluverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (36, 83, 'Yücedir, münezzehtir o mabut ki her şeyin tasarrufu ve tedbiri, onun elindedir ve hepiniz de dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 1, 'Andolsun saf saf dizilenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 2, 'Halkı kötülükten menedenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 3, 'Kur''an okuyanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 4, 'Şüphe yok ki mabudunuz birdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 5, 'Rabbidir göklerin ve yeryüzünün ve ikisinin arasındakilerin ve Rabbidir doğuların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 6, 'Şüphe yok ki biz, yakın göğü ziynetlerle bezedik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 7, 'Ve onu, her inatçı ve asi Şeytandan koruduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 8, 'En yüce melekler topluluğunun sözlerini duyamazlar ve her yandan sürülüp kovulurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 9, 'Horhakir bir halde ve onlar içindir ardıarası kesilmeyen azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 10, 'Ancak hırsızlama bir söz duyan olursa hemen onun ardından da aydınlatıcı ve delip geçen bir ateştir atılır, onu yakar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 11, 'Şimdi sor bir onlara, yaratılış bakımından onlar mı daha güçlükuvvetli, yoksa bizim diğer yarattıklarımız mı? Şüphe yok ki biz, onları cıvık bir balçıktan yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 12, 'Belki de şaştın sen ve alay eder onlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 13, 'Ve öğüt verilince Kur''an''la öğüt almazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 14, 'Ve bir delil gördüler mi alay etmeye kalkarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 15, 'Ve derler ki: Bu, ancak apaçık bir büyüden başka bir şey değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 16, 'Ölüp toprak ve kemik olduktan sonra mı diriltileceğiz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 17, 'Önceki atalarımız da mı diriltilecekler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 18, 'De ki: Evet ve siz horhakir bir halde dirileceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 19, 'Gerçekten de ancak bir tek bağrıştan ibarettir de birdenbire görüverirler ki dirilmişler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 20, 'Ve yazıklar olsun bize derler, işte bugün, ceza günü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 21, 'İşte bugün, sizin yalanlayıp durduğunuz ayırt ediş günü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 22, 'Toplayın bir araya zulmedenleri, onlara eş olanları ve kulluk ettikleri şeyleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 23, 'Allah''ı bırakıp da, hepsine de o koca cehennemin yolunu gösterin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 24, 'Ve durdurun onları, şüphe yok ki sorulacak onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 25, 'Ne oldu size de yardım etmiyorsunuz birbirinize?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 26, 'Hayır, bugün onlar, tamamıyla teslim olmuşlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 27, 'Ve bir kısmı, bir kısmına yönelir de, birbirlerini sorumlu sayarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 28, 'Gerçekten de derler, siz sağımızdan çıkagelir, iyilik ediyor görünürdünüz bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 29, 'Hayır derler öbürleri, siz inanmamıştınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 30, 'Ve size karşı bir gücümüzkuvvetimiz yoktu bizim, hayır, siz azgın kişilerdiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 31, 'O yüzden de Rabbimizin, bize söylediği söz, gerçekleşti, şüphe yok ki azabı tadacağız elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 32, 'Gerçekten sizi azdırdık biz, şüphe yok ki biz de azmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 33, 'Hiç şüphe yok ki bugün onlar, azapta ortaktırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 34, 'Şüphe yok ki biz, suçlulara böyle yaparız işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 35, 'Şüphe yok ki onlara Allah''tan başka yoktur tapacak dendi mi ululanmaya kalkışırlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 36, 'Ve biz derlerdi, deli bir şair için mabutlarımızı bırakalım mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 37, 'Hayır, o, gerçeği getirmiştir ve peygamberlerin gerçek olduğunu bildirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 38, 'Hiç şüphe yok ki o elemli azabı tadacaksınız elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 39, 'Ve ancak yaptığınız neyse onun karşılığı olarak cezalanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 40, 'Ancak ihlasa eren Allah kulları müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 41, 'Öyle kişilerdir onlar ki onlaradır malum rızık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 42, 'Yemişler ve onlar, büyük derecelere nail olanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 43, 'Ebedi Naim cennetlerinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 44, 'Karşılıklı tahtlara otururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 45, 'Kaynakları meydanda, akıp duran şarap ırmaklarından taslar sunulur onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 46, 'Bembeyazdır o şarap, lezzetlidir içenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 47, 'Orada ne bir sersemlik var, ne de sarhoş olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 48, 'Ve yanlarında, gözlerini kendi eşlerinden ayırmayan iri gözlü huriler var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 49, 'Sanki kuş tüyleriyle örtülmüş yumurtalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 50, 'Bir kısmı, bir kısmına döner de bir birlerine sorarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 51, 'Birisi söze gelir de der ki: Bir arkadaşım vardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 52, 'Sen de mi derdi, gerçek sayanlardansın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 53, 'Ölüp bir yığın toprak ve kemik olduktan sonra mı soruya çekileceğiz, cezalanacağız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 54, 'Der ki: Ne oldu o, bakıp gördünüz mü acaba?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 55, 'Derken kendisi bakıp görür ki o, cehennemin ta ortasında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 56, 'Allah''a andolsun ki der, az kalmıştı, beni de helak edecektin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 57, 'Ve Rabbimin nimeti olmasaydı ben de orada bulunanlardan olurdum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 58, 'Biz artık ölmeyecek değil miyiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 59, 'İlk ölümümüzden sonra ve biz, azaba da uğramayacağız değil mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 60, 'Şüphe yok ki bu, elbette büyük bir kurtuluş, büyük bir kutluluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 61, 'Artık çalışanlar da böylesine çalışsınlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 62, 'Böyle bir nimete ve ziyafete ermek mi hayırlı, yoksa zakkum ağacından yemek mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 63, 'Şüphe yok ki biz onu, zulmedenleri sınamak için yarattık,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 64, 'Şüphe yok ki o, cehennemin ta dibinden çıkar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 65, 'Tomurcukları Şeytanların başlarına benzer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 66, 'Derken onlar, onu yerler de karınları şişer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 67, 'Sonra da içimi bu zakkum gibi acı kaynar sular içerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 68, 'Sonra da gene cehennemdir dönüp varacakları yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 69, 'Şüphe yok ki onlar, atalarını, sapıtmış bir halde bulmuşlardı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 70, 'Onlar da, koşa koşa onların izlerini izlemişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 71, 'Ve andolsun ki onlardan önce gelip geçenlerin de çoğu sapıtmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 72, 'Ve andolsun ki biz, onların içinden, korkutucular göndermiştik onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 73, 'Bak da gör, korkutulanların sonucu ne oldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 74, 'Ancak ihlasa eren Allah kulları müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 75, 'Ve andolsun ki Nuh, bize nida etmişti, biz de ne güzel icabet etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 76, 'Ve onu ve ailesini, pek büyük bir sıkıntıdan kurtarmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 77, 'Ve soyunu, yeryüzünde kalan bir soy haline getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 78, 'Ve sonradan gelenler arasında da ona iyi bir adsan verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 79, 'Esenlik Nuh''a alemler içinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 80, 'Şüphe yok ki biz, böyle mükafatlandırırız iyilik edenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 81, 'Şüphe yok ki o, inanan kullarımızdandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 82, 'Sonra da öbürlerini sulara boğduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 83, 'Ve şüphe yok ki İbrahim de onun taraftarlarındandı elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 84, 'Hani Rabbine tertemiz bir yürekle gelmişti o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 85, 'Hani atasına ve kavmine siz demişti, nelere kulluk ediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 86, 'Allah''ı bırakıp da tamamıyla uydurma mabutlara mı tapmak istiyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 87, 'Âlemlerin Rabbine karşı zannınız ne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 88, 'Derken yıldızlara bir bakmıştı da,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 89, 'Ben, demişti, gerçekten de hastayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 90, 'Derken, arkalarını çevirip gitmişlerdi onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 91, 'Derken o da onların mabutları olan putlara gidip demişti ki: Neye yemek yemiyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 92, 'Ne oldu size, niçin konuşmuyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 93, 'Derken sağ eliyle vurup kırmıştı onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 94, 'Derken koşakoşa yanına gelmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 95, 'O demişti ki: Elinizde yontup yaptığınız şeylere mi kulluk ediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 96, 'Halbuki sizi de Allah yaratmıştır, o yontup yaptığınız şeyleri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 97, 'Onun için bir yapı yapın da demişlerdi, atın onu ateşe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 98, 'Ona bir düzen yapmak istemişlerdi de biz onları alçaltmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 99, 'Ve ben demişti, Rabbimin tapısına gidiyorum, o, doğru yolu gösterir bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 100, 'Rabbim, bana temiz kişilerden olmak şartıyla bir oğul ihsan et.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 101, 'Derken biz de ona tedbirle hareket eden ve aceleci olmayan bir oğul vereceğimizi müjdelemiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 102, 'İbrahim''le beraber koşup gezecek çağa gelince İbrahim, oğulcağızım demişti, ben, rüyamda, seni kesiyorum gördüm, bir bak, düşün, sen ne dersin buna? O da babacığım demişti, ne emredildiyse sana, onu yap, Allah dilerse beni sabredenlerden bulursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 103, 'İkisi de teslim olunca onun alnını yere koymuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 104, 'Ve biz, ona ey İbrahim diye nida etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 105, 'Rüyanı gerçekleştirdik. Şüphe yok ki biz, böyle mükafatlandırırız iyilik edenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 106, 'Şüphe yok ki bu, elbette apaçık bir sınamaydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 107, 'Ve onun yerine, kesilmek üzere büyük bir koç ihsan ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 108, 'Ve sonradan gelenler arasında da ona iyi bir adsan verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 109, 'Esenlik İbrahim''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 110, 'Biz, böyle mükafatlandırırız iyilik edenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 111, 'Şüphe yok ki o, inanan kullarımızdandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 112, 'Ve ona, temiz kişilerden ve peygamber olacak İshak''ı müjdelemiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 113, 'Onu da kutladık, İshak''ı da ve ikisinin de soyundan iyilik eden de var, apaçık nefsine zulmeden de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 114, 'Ve andolsun ki biz, Musa''ya ve Harun''a nimetler verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 115, 'İkisini ve kavimlerini, büyük bir sıkıntıdan kurtardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 116, 'Ve yardım ettik onlara da üst geldiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 117, 'Ve ikisine de her şeyi apaçık gösteren kitabı verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 118, 'Ve ikisini de dosdoğru yola sevkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 119, 'Ve ikisine de, sonradan gelenler arasında iyi bir adsan verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 120, 'Esenlik Musa''ya ve Harun''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 121, 'Şüphe yok ki biz, böyle mükafatlandırırız iyilik edenleri;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 122, 'Şüphe yok ki ikisi de inanan kullarımızdandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 123, 'Ve şüphe yok ki İlyas, elbette peygamberlerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 124, 'Hani kavmine demişti ki: Çekinmez misiniz siz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 125, 'Ba''l''i mi çağırırsınız da yaratıcıların en güzelini bırakırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 126, 'O Allah''tır ki Rabbinizdir sizin ve Rabbidir gelip geçmiş atalarınızın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 127, 'Derken yalanladılar onu; şüphe yok ki tapımıza getirilecektir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 128, 'Ancak ihlasa eren Allah kulları müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 129, 'Ve sonradan gelenler arasında ona iyi bir adsan verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 130, 'Esenlik İlyas''a ve ona uyanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 131, 'Şüphe yok ki biz, böyle mükafatlandırırız iyilik edenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 132, 'Şüphe yok ki o, inanan kullarımızdandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 133, 'Ve şüphe yok ki Lut da elbette peygamberlerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 134, 'Hani onu ve bütün ailesini kurtarmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 135, 'Ancak bir kocakarı, kalanlar arasındaydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 136, 'Sonra öbürlerinin kökünü kazıdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 137, 'Ve şüphe yok ki siz de onların yurtlarına uğramadasınız sabahları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 138, 'Ve akşamları; hala mı akıl etmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 139, 'Ve şüphe yok ki Yunus da peygamberlerdendi elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 140, 'Hani, yolcularla dolu bir gemiye kaçmıştı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 141, 'Derken kura çekmişlerdi de kur''a ona düşmüştü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 142, 'Kınanmış bir haldeydi ki onu balık yutuvermişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 143, 'Eğer Rabbini tenzih edenlerden olmasaydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 144, 'Halkın tekrar dirileceği günedek balığın karnında kalırdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 145, 'Derken onu ıssız bir yere çıkardık ve o, hastaydı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 146, 'Ve ona gölge versin diye bir kabak fidanı bitirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 147, 'Ve onu yüz bin kişiye, yahut daha da artmakta olan bir topluluğa peygamber olarak gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 148, 'Derken inandılar da onları muayyen bir zamanadek yaşattık, geçindirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 149, 'Artık sor onlara, kızlar, Rabbinin de.oğullar, onların mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 150, 'Yoksa melekleri kız halkettik de tanık mıydı onlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 151, 'Haberin olsun ki şüphe yok, onlar, bu sözü uydurup söylemedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 152, 'Allah doğurdu demedeler ve şüphe yok ki onlar, yalancıdır elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 153, 'Oğulları bırakmış da kızları mı seçmiş?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 154, 'Ne oluyor size, nasıl da hükmediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 155, 'Öğüt almaz mısınız hala?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 156, 'Yoksa apaçık bir deliliniz mi var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 157, 'Doğru söylüyorsanız getirin kitabınızı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 158, 'Ve onunla cinler arasında bir.akRabalık uydurmadalar ve andolsun ki cinler de onun tapısına götürüleceklerini, orada hazır bulunacaklarını bilmişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 159, 'Yücedir,.münezzehtir vasfettiklerinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 160, 'Ancak ihlasa eren Allah kulları müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 161, 'Gerçekten de ne siz, ne de kulluk ettikleriniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 162, 'Onları bir sınamaya uğratamazsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 163, 'Ancak cehenneme girecek kişiyi azdıRabilirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 164, 'Ve melekler derler ki: Bizden hiçbir fert yoktur ki onun malum ve muayyen bir makamı olmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 165, 'Ve şüphe yok ki biz, safsaf dizilmişiz elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 166, 'Ve şüphe yok ki biz, mabudumuzu tenzih ederiz elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 167, 'Ve kafirler, gerçekten de diyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 168, 'Katımızda evvelkilere ait bir kitap olsaydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 169, 'Elbette biz de ihlasa eren Allah kulları olurduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 170, 'Derken kitap geldi de inanmadılar ona, yakında ne olacaklarını bilecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 171, 'Ve andolsun ki gönderilen kullarımıza şu sözü söylemiştik, şu hükmü takdir etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 172, 'Şüphe yok ki onlar, elbette yardıma mazhar olacaklardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 173, 'Ve şüphe yok ki bizim ordumuz, elbette üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 174, 'Artık yüz çevir onlardan bir zamanadek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 175, 'Hele bir bak, bir gözle onları, onlar da sonuçları neymiş, yakında görecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 176, 'Azabımızın çabucak gelmesini mi istiyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 177, 'Fakat azabımız, yurtlarına gelip çökünce korkutulanlar, ne de kötü bir sabaha kavuşacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 178, 'Ve yüz çevir onlardan bir zamana dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 179, 'Ve bir bak, bir gözle, onlar da sonuçları neymiş, yakında görecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 180, 'Yücedir, münezzehtir Rabbin ve yücelik, üstünlük ıssı Rab, onların vasfettiklerinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 181, 'Ve esenlik peygamberlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (37, 182, 'Ve hamd, alemlerin Rabbi Allah''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 1, 'Sad, andolsun şerefli Kur''an''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 2, 'Kafir olanlar, ululanmadalar ve isyan içindeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 3, 'Onlardan önce nice ümmetleri helak ettik de bağrışıp çığrıştılar ama kurtuluş vakti çoktan geçmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 4, 'Onların cinsinden bir korkutucu geldi mi şaşıp kalırlar da kafirler derler ki: Bu, bir büyücü ve pek yalancı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 5, 'Mabutları bir tek mabut mu kabul.etmiş? Gerçekten de bu, elbette pek şaşılacak şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 6, 'Ve ileri gelenlerinden.bir kısmı, kalkıp gitmiş ve yürüyün demiştir ve dayanın mabutlarınıza kulluk etmede; şüphe yok ki istenen şey de budur elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 7, 'Biz bunu son dinlerin hiçbirinde duymadık, bu, ancak bir yalan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 8, 'Kur''an, aramızdan ona mı indirildi? Hayır, onlar, benim vahyimden şüphedeler; hayır, onlar daha tatmadılar azabımı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 9, 'Yoksa üstün ve vergisi bol Rabbinin hazineleri, onların yanında mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 10, 'Yahut da göklerin ve yeryüzünün ve ikisinin arasındakilerin saltanat ve tedbiri, onların mı? Öyleyse ağsınlar göklerin kapılarına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 11, 'Bir ordudur onlar ki bölükbölük toplanmış ve buracıkta bozguna uğrayacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 12, 'Onlardan önce de Nuh''un ve Âd''ın ve ordular sahibi Firavun''un kavimleri, yalanladılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 13, 'Ve Semud''un kavmi ve Lut kavmi ve Ashabı Eyke; işte bunlardır bölükler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 14, 'Her biri, peygamberleri ancak yalanladılar da azabı hak ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 15, 'Ve bunlar da bekliyorlar ancak o tek bağrışı ki vakti geldi miydi, gecikmesine, dönmesine imkan yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 16, 'Ve Rabbimiz derler, soru gününden önce tez ver azabımızı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 17, 'Sabret ne derlerse ve an güçlükuvvetli kulumuz Davud''u, şüphe yok ki o, daima Rabbine dönen, tövbe eden bir kuldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 18, 'Şüphe.yok ki biz, dağları ram etmiştik ona, akşam ve kuşluk çağlarında, onunla beraber Rabbi tenzih ederlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 19, 'Ve kuşlar da toplanmıştı, hepsi de ona itaat ederdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 20, 'Ve onun saltanatını kuvvetlendirdik ve ona peygamberlik ve gerçekle batılı ayırt ediş bilgisini verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 21, 'Sen, o davacılardan haber aldın mı? Hani Davud''un ibadet ettiği yerin duvarına tırmanmışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 22, 'Hani Davud''un tapısına girmişlerdi de Davud, onlardan pek korkmuştu; korkma demişlerdi, iki hısımız, birimiz, öbürünün hakkına tecavüz etti, adaletle hükmet aramızda, birimize meylederek hakkı aşma ve bizi dosdoğru yola sevket.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 23, 'Şüphe yok ki şu, benim kardeşimdir, doksan dokuz dişi koyunu var ve benimse bir tek dişi koyunum; öyleyken onu da bana ver dedi ve konuşmamızda beni alt da etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 24, 'Dedi ki: Senin dişi koyununu, kendi koyunlarına katmayı istemekle gerçekten de zulmetmiş sana ve şüphesiz ki ortakların çoğu, birbirinin hakkına tecavüz eder, ancak inanan ve iyi işlerde bulunanlar müstesna ve fakat bunlar da pek azdır ve Davud, biz, kendisini sınadık sandı da Rabbinden yarlıganma diledi ve eğilerek yere kapandı ve Rabbine döndü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 25, 'Ve biz de onun bu.suçunu örttük ve şüphe yok ki onun, katımızda bir yakınlık derecesi ve dönüp geleceği güzel bir makamı vardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 26, 'Ey Davud, biz seni yeryüzüne hakim ettik, artık insanlar arasında, adaletle hükmet ve dileğine uyma ki seni Allah yolundan saptırır; Allah yolundan sapanlaraysa şiddetli bir azap var soru gününü unuttuklarından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 27, 'Ve biz, göğü ve yeryüzünü ve ikisinin arasındakileri boş yere yaratmadık; bu, kafir olanların zannı; artık vay haline kafirlerin ateşten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 28, 'İnananlarla iyi işlerde bulunanları, yeryüzündeki bozguncular gibi mi tutacağız, yahut çekinenlere, doğru yoldan çıkanlara ettiğimiz muameleyi mi yapacağız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 29, 'Bir kitaptır bu ki onu, kutlu olarak sana indirdik, ayetlerini iyice bir düşünsünler aklı başında olanlar ve ondan öğüt alsınlar diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 30, 'Ve Davud''a.Süleyman''ı ihsan ettik, ne güzel bir kuldu, şüphe yok ki o, daima Rabbine dönen, tövbe eden bir kuldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 31, 'Hani ona, üç ayağının üstünde duran ve ön ayaklarından birini büküp tırnağını yere dayayan yürük atlar arzedilmişti öğleden sonra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 32, 'Derken gerçekten de demişti, ben, güzel atları, Rabbimi anarak severim ve sonunda güneş, perde altına girmişti de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 33, 'Getirin onları bana demişti, atlar getirilince de onların ayaklarını, boyunlarını okşamıya, yelerini taramaya koyulmuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 34, 'Ve andolsun ki biz Süleyman''ı sınamıştık ve tahtının üstüne bir ölü koymuştuk, sonra o da tövbe edip Rabbine dönmüştü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 35, 'Rabbim demişti, beni yarlıga ve bana öyle bir saltanat ver ki benden sonra hiçbir kimse nail olamasın o saltanata, şüphe yok ki senin vergin, ihsanın, boldur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 36, 'Ve ona rüzgarı ram etmiştik de emriyle dilediği yere hafif hafif esip giderdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 37, 'Ve Şeytanlardan bütün mimarları ve dalgıçları da ram etmiştik ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 38, 'Ve bir başka kısmı da bukağılarla bağlanmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 39, 'Bu, bizim vergimizdir demiştik, istersen sayısız olarak sen de ihsan et; istersen elini yum, verme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 40, 'Ve şüphe yok ki onun, katımızda bir yakınlık derecesi ve dönüp geleceği güzel bir makamı vardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 41, 'Ve an kulumuz Eyyub''u da, hani Rabbine nida.edip de demişti ki: Gerçekten de Şeytan beni yordu ve azaba uğrattı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 42, 'Vur yere ayağını, bu yıkanılacak ve içilecek serin su işte demiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 43, 'Ve ona ailesini de ve onlarla beraber daha bir mislini de, bizden bir rahmet ve aklı başında.olanlara da bir öğüt ve ibret olmak üzere verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 44, 'Eline dedik, bir demet sap al da onunla vur ve yeminini.bozma. Şüphe yok ki biz onu, sabırlı bulduk, ne güzel bir kuldu ve şüphe yok ki o, daima Rabbine dönen, tövbe eden bir kuldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 45, 'Ve an kullarımız İbrahim''i ve İshak''ı ve Yakup''u ki ibadette kuvvetliydi bunlar, dinde gözleri açıktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 46, 'Biz onları, daima yurtları olan ahireti anma huyuyla yarattık da özleri temiz, ihlas sahibi kullar ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 47, 'Ve şüphe yok ki onlar, katımızda, seçilmiş, hayırlı kişilerdendi elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 48, 'Ve an İsmail''i, ElYesa''ı ve ZülKifl''i ve hepsi de hayırlı kişilerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 49, 'Ve bu, güzel bir anılıştır ve şüphe yok ki çekinenlere elbette dönülüp varılacak pek güzel bir yer var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 50, 'Ebedi Adn cennetleri ki onlara açıktır kapıları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 51, 'Oralarda yaslanıp oturacaklar, diledikleri birçok yemişler ve içecek şeyler, hemen sunulacak kendilerine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 52, 'Ve yanlarında,.eşlerinden gözlerini ayırmayan huriler olacak ki her biri de eşit ve aynı yaşta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 53, 'İşte bu, soru gününde size vaadedilen şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 54, 'Şüphe yok ki bu, elbette bizim.rızkımız, hem de öylesine ki bitip tükenmesi yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 55, 'Şu da var: Ve şüphe yok ki azgınlara elbette dönülüp gidilecek en kötü bir yer mevcut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 56, 'Cehennem. Oraya atılırlar ve orası, gerçekten, yatılıp kalınacak ne de kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 57, 'İşte budur azap, artık tatsınlar gayet sıcak ve gayet soğuk suları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 58, 'Ve daha da buna eşit çeşitçeşit azaplar var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 59, 'Bu topluluk, size uyup sizinle beraber cehenneme girenler; rahat yüzü görmesinler; onlar, mutlaka ateşe atılacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 60, 'Onlar da hayır diyecekler, asıl siz, rahat yüzü görmeyin; siz getirdiniz başımıza bunu, gerçekten de karar edilecek ne kötü yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 61, 'Rabbimiz diyecekler, kim bizi buna uğrattıysa ateşte, azabını bir kat daha arttır onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 62, 'Ve ne oldu bize ki diyecekler, kötü saydığımız erleri göremiyoruz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 63, 'Onları alaya alırdururduk, yoksa gözümüzden mi kaçtılar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 64, 'Şüphe yok ki cehennem ehlinin, birbirleriyle şu münakaşaları, gerçektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 65, 'De ki: Ben, ancak bir korkutucuyum ve yoktur tapacak bir ve her şeye üstün Allah''tan başka;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 66, 'Rabbidir göklerin ve yeryüzünün ve ikisinin arasındakilerin o üstün olan ve suçları, ceza vermeden önce ve tamamıyla örten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 67, 'De ki: Bu Kur''an, en büyük bir haberdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 68, 'Siz ondan yüz çevirmedesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 69, 'En yüce melekler topluluğu, münakaşa ederlerken benim hiçbir bilgim yoktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 70, 'Bana vahyedilmede ve ben, ancak apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 71, 'Hani Rabbin, meleklere, ben balçıktan bir insan yaratacağım demişti de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 72, 'Onu tamamlayınca ve ona, ruhumdan üfürünce karşısında yerlere kapanıp secde etmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 73, 'Meleklerin hepsi birden secde etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 74, 'Ancak İblis secde etmemişti, ululanmıştı ve o, kafirlerden olmuştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 75, 'Ey İblis demişti, kudret ellerimle yarattığıma, ne mani oldu da secde etmedin? Ululuk mu satmadasın, yoksa yücelerden misin sen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 76, 'O, ben demişti, ondan hayırlıyım, ateşten yarattın beni ve onuysa balçıktan halkettin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 77, 'Çık git buradan hemen demişti, gerçekten de taşlanmışsın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 78, 'Ve şüphe yok ki ceza gününedek benden lanet sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 79, 'Rabbim demişti, ölüleri dirilteceğin günedek öldürme beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 80, 'Gerçekten de demişti, sen, ölmeyenlere katıl.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 81, 'Bilinen vaktin gününe dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 82, 'Gerçek demişti, yüceliğine andolsun ki onların hepsini azdıracağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 83, 'Ancak içlerinden, ihlasa eren kulların müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 84, 'Bu gerçek demişti ve ben de gerçek olarak söylüyorum ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 85, 'Andolsun, dolduracağım cehennemi seninle ve sana uyanların hepsiyle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 86, 'De ki: Ben, tebliğime karşılık, sizden bir ücret istemiyorum ve ben, kendiliğimden bir şey de istememekteyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 87, 'O, ancak alemlere bir öğüt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (38, 88, 'Onun doğruluğunu, bir müddet sonra mutlaka bilip anlayacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 1, 'Kitabın indirilişi, üstün, hüküm ve hikmet sahibi Allah tarafındandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 2, 'Şüphe yok ki biz, o kitabı gerçek olarak indirdik sana, artık sen de, onun dininde bütün özünü ona bağla da ona kulluk et yalnız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 3, 'Bilin ki özden kulluk, yalnız Allah''a olur, ondan başka mabutlar kabul edenler, biz derler, onlara, ancak bizi Allah''a yakınlaştırıp manevi bir yakınlık derecesine ulaştırırsınlar diye tapıyoruz; şüphe yok ki Allah, ihtilafa düştükleri şeyler hakkında aralarında hükmeder; şüphe yok ki Allah, yalan söyleyen ve kafirlikte ileri giden hiçbir kimseyi doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 4, 'Allah, birisini oğul edinmek dileseydi elbette yarattıklarından birini seçerdi, yücedir, münezzehtir o bundan, odur bir ve her şeye üstün Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 5, 'Gökleri ve yeryüzünü gerçek olarak yaratmıştır; geceyi kısaltır, gündüze katar ve gündüzü kısaltır, geceye katar ve ram etmiştir güneşi ve ayı; hepsi de muayyen ve mukadder bir zamana dek akardurur; bilin ki odur üstün olan ve suçları, ceza vermeden önce ve tamamıyla örten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 6, 'Sizi bir tek kişiden yarattı, sonra ondan da eşini halketti ve sizin için davarlardan erkeklidişili, sekiz tane çift mahluk meydana getirdi; sizi, analarınızın karınlarında ve üç karanlık içinde yaratıştan yaratışa düşürür; işte budur Rabbiniz ki onundur saltanat ve tedbir; yoktur ondan başka tapacak, ondan nereye dönmedesiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 7, 'Kafir olursanız bilin ki Allah, sizden müstağnidir ve fakat kullarının kafir oluşuna da razı olmaz ve şükrederseniz sizden razı olur ve hiçbir kimse, bir başkasının yükünü yüklenemez; sonra da dönüp varacağınız yer, Rabbinizin tapısıdır da o, neler yaptığınızı haber verir size; şüphe yok ki.o, gönüllerde ne varsa hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 8, 'İnsan bir zarara uğrarsa tamamıyla Rabbine dönerek dua eder, sonra, ona bir nimet verdi mi önceden ona dua ettiğini unutur insan ve halkı, onun yolundan çıkarmak için Allah''a da eşler kabul eder; de ki: Kafirliğinle bir müddet geçin bakalım; hiç şüphe yok ki sen, cehennem ehlindensin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 9, 'Hiç o, ahiretten sakınarak ve Rabbinin rahmetini umarak geceleri secde eden, kıyamda bulunan ve böylece itaat ve ibadet eden kişiye benzer mi? De ki: Eşit olur mu bilenlerle bilmeyenler? Bunu ancak aklı başında olanlar düşünür, bundan ancak onlar öğüt alır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 10, 'De ki: Ey inanan kullarım, çekinin Rabbinizden; bu dünyada iyilik eden kişileredir iyilik ve Allah''ın yeryüzü, geniştir; sabredenlerin mükafatları, sayısız bir surette ödenir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 11, 'De ki: Şüphe yok, onun dininde, özümü yalnız ona bağlayarak Allah''a kulluk etmem emredildi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 12, 'Ve ona teslim olanların ilki olmam, emredildi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 13, 'Ve de ki: Şüphe yok ki isyan edersem Rabbime, pek büyük günün azabından korkarım ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 14, 'De ki: dinimde, özüm ona bağlı, yalnız Allah''a kulluk ederim ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 15, 'Artık siz, onu bırakıp dilediğinize kulluk edin. De ki: şüphe yok, ziyana düşenler, o kişilerdir ki kıyamet günü, kendilerini ve kendileriyle ilgisi olanları ziyana sokarlar; bilin ki budur apaçık ziyan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 16, 'Onların üstlerinde de ateşten tabakalar var, altlarında da tabakalar. İşte Allah, kullarını korkutmada bundan; ey kullarım, çekinin benden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 17, 'Şeytan''dan, ona kulluk etme hususunda sakınanlara ve Allah''a dönenlere gelince: onlara müjde olsun, müjdele kullarımı artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 18, 'O kullarım ki sözü dinlerler de en güzeline uyarlar, onlar, öyle kişilerdir ki Allah, doğru yola sevk etmiştir onları ve onlardır aklı başında bulunanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 19, 'Ya azap hükmünü hak edene ne dersin? Sen mi cehennemde bulunanı kurtaracaksın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 20, 'Fakat Rablerinden çekinenlerse, onlarındır köşkler, gene köşkler üstüne kurulmuş köşkler, altlarından ırmaklar akar, Allah''ın vaadidir; Allah vaadinden hiç caymaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 21, 'Görmedin mi ki Allah, gökten yağmur yağdırmada, derken yağmur suyunu yeryüzündeki kaynaklara sızdırmada, sonra da o suyla çeşitli renklerde nebatlar bitirmede, sonra da onları kurutmada da sen onları görürsün ki sararmış, sonra da onları unufak etmede; şüphe yok ki bunda, aklı başında olanlara öğüt ve ibret var elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 22, 'Allah''ın, İslam için gönlünü açtığı kişiye kim benzer ki o, gerçekten de Rabbinden bir ışığa, bir aydınlığa nail olmuştur; yazıklar olsun Allah''ı anmıya karşı yürekleri kaskatı olanlara, onlardır apaçık bir sapıklık içinde olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 23, 'Bir Allah''tır ki sözün en güzelini indirmiştir bir kitap halinde, bir kısmı, bir kısmına benzer, bir kısmı, bir kısmını gerçekleştirir, her şeyi tekrartekrar bildirir; Rablerinden korkanların tüyleri dikendiken olur onu dinlerken, sonra da bedenleri ve gönülleri, Allah''ı anmak için yumuşar; işte bu, Allah''ın bir hidayetidir ki dilediğini, onunla doğru yola sevk eder ve Allah, kimi doğru yoldan saptırırsa ona yol gösterecek yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 24, 'Kıyamet gününde, yüzünü o kötü azaptan kurtarmaya çalışana kim benzer ki? Ve zalimlere, kazandığımız şeylerin karşılığı olan azabı tadın denir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 25, 'Onlardan öncekiler de yalanladılar da azap, hiç anlamadıkları, ummadıkları yerden gelip çatıverdi onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 26, 'Derken Allah, onlara dünya yaşayışındayken aşağılığı tattırdı ve ahiret azabıyse elbette daha da büyük eğer bilselerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 27, 'Öğüt ve ibret alsınlar diye biz, andolsun ki, bu Kur''an''da her çeşit örnek getirmedeyiz insanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 28, 'Çekinsinler diye Arapça, eğrisibüğrüsü olmayan, dosdoğru Kur''an bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 29, 'Allah, bir örnek getirmede: Bir adamın ortakları var, ahlakları kötü, geçimsiz ve birbirleriyle çekişip durmadalar ve bir adam da varki bir kişiye teslim olmuş, yalnız onun hizmetinde, bunlar hiç bir olur mu? Hamd Allah''a, hayır, fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 30, 'Şüphe yok ki sen de öleceksin ve onlar da ölecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 31, 'Sonra da şüphesiz ki sizin, kıyamet gününde Rabbinizin katında davanız görülür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 32, 'Kimdir Allah''a karşı yalan söyleyenden ve doğru, kendisine gelip anlatıldıktan sonra onu yalanlayandan daha zalim? Kafirlere, cehennemde yer yurt mu yok?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 33, 'Doğrulukla gelen kişiye ve onun doğru olduğunu tasdik edenlere gelince: Onlardır çekinenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 34, 'Onlarındır Rableri katında diledikleri; budur iyilik edenlerin mükafatı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 35, 'Allah, onların önce işledikleri en kötü suçları bile örtecek ve ettikleri iyiliklerin mükafatını daha da güzel bir surette verecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 36, 'Allah, yetmez mi kuluna? Ve seni, ondan başka mabut saydıklarıyla mı korkutuyorlar? Ve Allah kimi doğru yoldan saptırırsa ona yol gösterecek yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 37, 'Ve Allah, kimi doğru yola sevk ederse onu saptıracak hiçbir kimse yok; Allah, öç alan üstün bir kudrete sahip mi değildir?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 38, 'Ve andolsun ki onlara, gökleri ve yeryüzünü kim yarattı diye sorsan elbette Allah derler. De ki: Gördünüz mü şu halde, onu bırakıp kimlere kulluk etmedesiniz? Allah, bana bir zarar vermek istese onun zararını giderebilir mi onlar, yahut bana rahmet etmek dilese rahmetini menedebilirler mi? De ki: Yeter bana Allah, ona dayansın dayananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 39, 'De ki: Ey kavmim, gücünüz neye yetiyorsa yapadurun, şüphe yok ki ben de yapmadayım, yakında bilir, anlarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 40, 'Aşağılatıcı azap kime gelecek ve daimi azabı kim hakedecek?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 41, 'Şüphe yok ki biz, o kitabı, insanlara bildirmen için gerçek olarak indirdik sana, artık doğru yolu bulanın faydası kendine ve kim yolunu azıtır da azarsa zararı, gene kendine ve sen, onlara bir koruyucu değilsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 42, 'Allah, ölüm zamanında, ölenin ruhunu alır, ölmeyecek kişinin de uyuduğu zaman; ölümün mukadder olanın ruhunu, gerçekten de geri vermez, öbürünün ruhunuysa yollar muayyen ve mukadder bir zamanadek; şüphe yok ki bunda, düşünen topluluğa bir delil var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 43, 'Yoksa, Allah''ı bırakıp da şefaatçiler mi kabul ettiler? De ki: Onların hiçbir şeye güçleri yetmez ve hiçbir şey akıl etmezler, değil mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 44, 'De ki: Bütün şefaat, Allah''ın; onundur göklerin ve yeryüzünün saltanatı ve tedbiri, sonra da dönüp onun tapısına gideceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 45, 'Allah bir olarak övülüp anıldı mı ahirete inanmayanların yüreklerinden bir nefrettir kopar, fakat ondan başka, onların mabut sandıkları anılınca ferahlanıp sevinirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 46, 'De ki: Gökleri ve yeryüzünü yaratan, gizliyi de, açıkta olanı da bilen Allah''ım, ihtilafa düştükleri şeyler hakkında, kullarının arasında sen hüküm vereceksin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 47, 'Yeryüzünde ne varsa hepsi ve onlarla beraber de daha bir misli, zulmedenlerin olsa kıyamet günü, azabın kötülüğünü giderip kurtulmak için elbette bağışlarlardı; ve o gün, onların hiç hesaplamakdıkları şeyler, Allah tarafından karşılarına çıkarılıverecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 48, 'Kazandıkları kötülükler, ortaya çıkmıştır ve alay ettikleri şey, başlarına gelmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 49, 'İnsana bir zarar geldi mi bizi çağırır, sonra katımızdan bir nimet verdik mi ona, der ki: Bana bu nimet, bilgim yüzünden verilmiştir; hayır, o bir sınamadır ve fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 50, 'Gerçekten, onlardan öncekiler de bu sözü söylemişlerdi de kazandıkları şeylerin, onlara hiçbir faydası dokunmamıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 51, 'Derken kazandıkları, elde ettikleri şeylerin kötülüklerine uğramışlardı. Bunlardan zulmedenler de kazançlarının kötülüklerine uğrayacaklar, suçlarının mücazatını görecekler ve onlar, bizim vereceğimiz cezaya mani olamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 52, 'Bilmezler mi ki Allah, şüphe yok ki dilediğinin rızkını bollaştırır ve dilediğinin daraltır. Şüphe yok ki bunda, inananlara deliller var elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 53, 'De ki: Ey nefislerine uyup hadden aşırı hareket eden kullarım, Allah rahmetinden ümit kesmeyin; şüphe yok ki Allah, bütün suçları örter, şüphe yok ki o, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 54, 'Ve dönün Rabbinize ve teslim olun ona, size azap gelip çatmadan, sonra yardım edilmez size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 55, 'Ve uyun Rabbinizden size indirilen en güzel kitaba, Kur''an''a, ansızın ve siz hiç anlamadan size azap gelip çatmadan önce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 56, 'Herkesin, Allah katından bir sevap kazanamadım, hey gidi hey ve gerçekten de alay edenlerdendim dediği.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 57, 'Yahut Allah beni doğru yola sevketseydi elbette çekinenlerden olurdum dediği.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 58, 'Yahut da azabı görünce, bir kere daha dünyaya dönmeme imkan olsaydı mutlaka iyilik edenlerden olurdum dediği günden önce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 59, 'Hayır, dönemezsin; sana bunca delillerim geldiği halde yalanladın onları ve ululuk satmaya kalkıştın ve kafirlerden oldun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 60, 'Ve kıyamet günü görürsün ki Allah''a karşı yalan söyleyenlerin yüzleri, kapkara olur; ululananlara cehennemde yeryurt mu yok?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 61, 'Allah, kendisinden çekinenleri, kurtuluşlarına sebep olan şeyle kurtarır, onlar, bir kötülüğe uğramazlar ve mahzun da olmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 62, 'Allah, her şeyi yaratandır ve o, her şeyi korur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 63, 'Onundur kilitleri göklerin ve yeryüzünün ve Allah''ın delillerini yalanlayanlara gelince: Onlardır ziyana uğrayanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 64, 'De ki: Allah''tan başkasına kulluk etmemi mi emrediyorsunuz bana a bilgisizler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 65, 'Ve andolsun ki sana ve senden öncekilere, gerçekten de şirk koşarsan yaptıklarını boşa çıkarırım ve elbette ziyana uğrayanlardan olursun diye vahyedildi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 66, 'Hayır, artık Allah''a kulluk et ve şükredenlerden ol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 67, 'Allah''ı, gereği gibi ululamadılar ve yeryüzü, kıyamet gününde, tamamıyla kudret avucundadır onun ve gökler de, kudretiyle dürülmüştür; münezzehtir ve yücedir o, şirk koşanların şirk koştukları şeylerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 68, 'Ve Sur''a üfürülmüştür de göklerdekilerin ve yeryüzündekilerin hepsi de, o sesin şiddetinden ölüp gitmiştir, sonra bir daha üfürülünce o zaman hepsi dirilmiştir, ne olacak diye bakınıp durmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 69, 'Ve ışıklanmıştır yeryüzü, Rabbinin nuruyla ve yaptıklarının yazıldığı kitap, ellerine verilmiştir ve peygamberlerle tanıklar, getirilmiştir ve aralarında, gerçek bir hükümle hükmedilmiştir ve onlara zulmedilmemiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 70, 'Ve herkese, ne yaptıysa karşılığı, ödenmiştir ve o, ne yaptıklarını daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 71, 'Ve kafir olanlar, bölükbölük cehenneme sürülmüştür, oraya geldikleri zaman kapıları açılmıştır da bekçileri, onlara, sizin içinizden, Rabbinizin ayetlerini okuyan ve sizi, bugüne kavuşacağınızı söyleyerek korkutan peygamberler gelmedi mi size derler. Onlar da evet derler ve fakat azap hükmü, hak olmuştur kafirlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 72, 'Girin denilir cehennem kapılarından, ebedi kalırsınız orada; ululananların ne de kötüdür yurtları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 73, 'Ve Rablerinden çekinenler de bölükbölük cennete sürülmüştür, oraya geldikleri zaman kapıları açılmıştır da bekçileri, esenlik size, tertemiz oldunuz, artık girin ebedi olarak derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 74, 'Onlar da hamd Allah''a ki derler, bize vaadettiğini gerçekleştirdi ve cennetten, dilediğimiz yerde konaklamamız için bu yeri miras verdi bize; ne de güzeldir iyi işlerde bulunanların mükafatı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (39, 75, 'Ve görürsün ki, melekler, Rablerine hamd ederek onu tenzih edip arşın çevresinde dönmedeler ve aralarında gerçek bir adaletle hükmedilmiştir ve denilmiştir ki: Hamd, alemlerin Rabbi Allah''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 2, 'Bu kitap, üstün ve her şeyi bilen Allah tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 3, 'Odur suçları örten ve tövbeleri kabul eden ve azabı şiddetli olan ve kullarına nimetler ihsan eden; yoktur ondan başka tapacak ve dönüp varılacak yer, onun tapısıdır ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 4, 'Allah''ın delilleri hakkında, ancak kafir olanlar çekişirler, onların, şehirlerde dönüp dolaşmaları aldatmasın seni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 5, 'Onlardan önce de Nuh kavmi, yalanladı, onlardan sonraysa bölükbölük halk ve her ümmet, peygamberini yalanlamayı kendine iş edindi, buna kasdetti, onu öldürmek istedi ve gerçeği boşa çıkarmak için boş şeylere dayanarak çekiştiler, derken onları helakediverdim; azap nasıl olurmuş, görsünler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 6, 'İşte böylece Rabbinin verdiği hüküm, kafirlere hak oldu: Şüphe yok ki onlar, cehennemliktir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 7, 'Arşı taşıyanlarla onun çevresindekiler, Rablerine hamd ederek onu tenzih ederler ve inanırlar ona ve inananlara yarlıganma dilerler, Rabbimiz derler, rahmetin ve bilgin, her şeyi kavramış, kaplamıştır, artık tövbe edenleri ve senin yoluna uyanları yarlıga ve koru onları, yakıp kavuran cehennem azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 8, 'Rabbimiz ve sok onları ebedi Adn cennetlerine, nitekim vait de etmiştin onlara ve atalarından ve eşlerinden ve soylarından kendilerini düzgün bir hale getirenlere. Şüphe yok ki sen, üstünsün, hüküm ve hikmet sahibisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 9, 'Ve koru onları kötülüklerden ve kimi kötülüklerden korursan o gün, gerçekten de ona acımışsın ve budur işte o pek büyük kurtuluş, murada eriş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 10, 'Şüphe yok ki kafir olanlara nida edilir de denir ki: Bugün kendinize karşı duyduğunuz nefretten, buğuzdan daha büyüktü size karşı Allah''ın duyduğu nefret ve buğuz o zaman ki inanca çağrılıyordunuz da kafir oluyordunuz siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 11, 'Onlarsa Rabbimiz derler, iki kere öldürdün bizi ve iki kere dirilttin, artık suçlarımızı da söyledik, buradan çıkmamıza bir yol yok mu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 12, 'Bu da, Allah birdir dendi mi kafir olmamızdan ve ona eşler olduğu söylenince inanmanızdandır; artık hüküm, pek yüce ve pek büyük Allah''ın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 13, 'Öyle bir mabuttur ki delillerini göstermededir size ve rızıklandırmak için gökten yağmur yağdırmadadır size ve ona dönen kişiden başkası ibret ve öğüt almaz bundan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 14, 'Artık, dininde, özünüzü tamamıyla ona bağlıyarak çağırın Allah''ı kafirler istemese de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 15, 'Dostlarının derecelerini yüceltir, arşın sahibidir; kavuşma gününden korkutmak için kullarından dilediğine Ruh''u, emriyle indirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 16, 'O kavuşma günü, onlar, kabirlerinden çıkarlar, Allah''a karşı hiçbir şeyleri gizli kalmaz; o gün, saltanat ve tedbir kimindir, bir ve her şeye üstün Allah''ın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 17, 'O gün herkes, ne kazandıysa onun karşılığını bulur; o gün zulüm yoktur; şüphe yok ki Allah''ın hesabı, pek tezdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 18, 'Ve onları, yaklaşmakta olan o günle korkut, o gün, korkudan yürekler, ağızlara gelir, gönüller, dertle dolar, zalimlere ne yardımı dokunacak bir dost bulunur, ne şefaati kabul edilecek bir şefaatçi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 19, 'O, hıyanetle gizlice bakışı da bilir, gönüllerde gizlenen şeyleri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 20, 'Ve Allah, gerçek olarak hükmeder. Ondan başka kulluk ettikleri şeyler, hiçbir şey hakkında hüküm veremezler; şüphe yok ki Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 21, 'Yeryüzünü gezip dolaşmazlar mı ki onlardan önce gelip geçenlerin ne olmuş sonları, bir bakıp görsünler? Onlar, kuvvet bakımından da üstündü bunlardan, yeryüzünde yaptıkları şeyler bakımından da; derken kafir oldular da Allah, onları helak ediverdi ve onları, Allah''a karşı koruyacak hiçbir kimse çıkmadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 22, 'Bu da, peygamberleri, onlara apaçık delillerle geldi mi, inkar etmelerindendir, derken Allah onları helak edivermiştir; şüphe yok ki o, kuvvetlidir, azabı da çetindir onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 23, 'Ve andolsun ki Musa''yı delillerimizle ve apaçık bir burhanla göndermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 24, 'Firavun''a, Haman''a ve Karun''a; derken onlar, bu demişlerdi, pek yalancı bir büyücü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 25, 'Musa, katımızdan gerçekle onlara gelince öldürün demişlerdi, onunla beraber inananların oğullarını ve bırakın kadınlarını; kafirlerin düzeni, ancak gerçekten dışarıdır, boştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 26, 'Ve Firavun, bırakın beni de dedi, Musa''yı öldüreyim ve Rabbini çağırsın bakalım; şüphe yok ki ben, dininizi değiştireceğinden, yahut da yeryüzünde bir bozgun çıkaracağından korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 27, 'Ve Musa, ben dedi, şüphe yok ki soru gününe inanmayan her ululuk satan kişinin şerrinden, Rabbime ve Rabbinize sığınırım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 28, 'Ve Firavun''un soyundan inanan ve inancını gizleyen bir er, dedi ki: Rabbim Allah''tır dediği için mi adam öldüreceksiniz ve gerçekten de o, Rabbinizden apaçık deliller de getirmiştir size ve yalancıysa yalanı kendisine ait ve doğru söylüyorsa size vaadettiklerinin bir kısmına uğrarsınız; şüphe yok ki Allah, haddini aşan ve çok yalan söyleyen kişiyi doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 29, 'Ey kavmim, bugün saltanat sizin, üstünsünüz yeryüzünde, fakat Allah''ın azabı gelince kim kurtaracak bizi? Firavun dedi ki: Ben size hangi reyi işaret ediyorsam o, tamamıyla doğrudur ve ben sizi, doğrudürüst yoldan başka bir yola sevketmiyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 30, 'O inanan, ey kavmim dedi, ben bir bölük ümmetin uğradıkları azaba uğrayacaksınız diye korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 31, 'Nuh, Âd ve Semud kavimlerine ve onlardan sonrakilere olduğu gibi ve Allah, kullarına zulmetmeyi istemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 32, 'Ve ey kavmim, ben, o feryadü figan, o boşuna bağırıp söylenme günündeki halinizden korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 33, 'O gün, bir gündür ki arkanızı döndürüp kaçacaksınız ama doğru cehenneme gideceksiniz ve Allah''ın azabından sizi bir kurtaran olmayacak ve Allah, kimi doğru yoldan çıkarıp saptırdıysa ona bir yol gösteren yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 34, 'Ve andolsun ki daha önce Yusuf da, apaçık delillerle gelmişti de size getirdiği şey hakkında bir türlü şüpheden kurtulamamıştınız, sonunda ölünce de artık dediniz, bundan sonra Allah, başka bir peygamber göndermez kesin olarak; işte Allah, haddini aşan şüpheli kişiyi böyle saptırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 35, 'Öyle kişilerdir onlar ki kendilerine hiçbir kesin delil gelmediği halde Allah''ın delilleri hakkında çekişmiye girişirler; Allah katında da bir nefrete ve buğza uğrarlar, inananlar katında da; Allah, her kibirli ve cebbar kişinin gönlünü böyle mühürler işte.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 36, 'Ve Firavun, ey Haman demişti, bana bir köşk yap da belki kapılara erişirim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 37, 'Göklerin kapılarına ve derken Musa''nın mabudunu anlamış olurum ve gerçekten de sanıyorum ki o, yalancı ve Firavun''a, kötü işi, böyle bezendi de böyle çıkarıldı yoldan ve Firavun''un düzeni, ancak ziyana uğradı, boşa çıktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 38, 'Ve inanan da ey kavmim dedi, bana uyun da size doğru yolu göstereyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 39, 'Ey kavmim, şu dünya yaşayışı, ancak geçici bir metadan ibaret ve şüphe yok ki ahirettir, karar edilecek yurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 40, 'Kim bir kötülükte bulunursa ancak onun misli olan bir ceza ile cezalanır ve erkek olsun, kadın olsun, inanarak iyi bir işte bulunansa işte o çeşit kişilerdir ki cennete girerler, orada sayısız rızıklanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 41, 'Ve ey kavmim, ne oluyor bana da ben sizi kurtuluşa çağırmadayım, halbuki siz beni ateşe çağırıyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 42, 'Allah''a kafir olmaya ve ona şirk koşmaya çağırıyorsunuz beni bu hususta hiçbir bilgim olmadığı halde ve bense sizi üstün ve bütün suçları tamamıyla örten mabuda çağırmadayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 43, 'Gerçeğin ta kendisi şu ki: Siz beni, dünyada da çağırmaya salahiyetli olmayan, ahirette de salahiyetli olmayan birşeye çağırıyorsunuz ancak ve dönüp gideceğimiz yer, Allah tapısıdır ve şüphe yok ki haddini aşanlar, cehennem ehlinin ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 44, 'Yakında, size neler dediysem, anlıyacak, hatırlıyacaksınız onları ve ben, işimi Allah''a ısmarladım; şüphe yok ki Allah, kullarını görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 45, 'Derken Allah, onların düzenlerinin kötülüklerinden korudu onu ve Firavun soyunaysa azabın kötüsü gelip çattı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 46, 'Ateş, sabahakşam, onlara gösterilecek ve kıyametin koptuğu günde Firavun soyunu denecek, sokun azabın en çetinine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 47, 'Ve ateşte, birbirleriyle çekişmeye başladıkları zaman düşkünler, ululuk satanlara diyecekler ki: Gerçekten size uymuştuk, sizin adamlarınızdık biz, ateşin bir miktarını olsun defedebilir misiniz bizden?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 48, 'Ululuk satanlarsa, şüphe yok ki diyecekler, hepimiz de ateş içindeyiz; şüphe yok ki Allah, kullar arasında hükmetti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 49, 'Ve ateştekiler, cehennemin kapıcılarına, Rabbinize yalvarın da diyecekler, ne olur, bir günceğiz olsun azabımızı hafifletsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 50, 'Onlar da, peygamberleriniz, apaçık delillerle gelmedi miydi size diyecekler; onlar, evet diyecekler, bekçiler, öyleyse diyecekler, siz yalvarın ve kafirlerin duasıysa ancak boşa gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 51, 'Şüphe yok ki biz, elbette peygamberlerimize ve inananlara, dünya yaşayışında da yardım ederiz, tanıkların getirileceği günde de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 52, 'Bir gündür o gün ki zalimlerin özürleri fayda vermez ve onlaradır lanet ve onlarındır kötü yeryurt.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 53, 'Ve andolsun ki biz, Musa''ya doğru yolu gösteren kitabı verdik ve İsrailoğullarını da mirasçı ettik o kitaba ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 54, 'Aklı başında olanları doğru yola sevk eder, onlara ibrettir, öğüttür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 55, 'Artık sabret, şüphe yok ki Allah''ın vaadi gerçektir ve suçunun yarlıganmasını dile ve akşam ve sabah çağlarında, Rabbine hamd ederek tenzih et onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 56, 'Allah''ın ayetleri hakkında, kendilerine hiçbir kesin delil gelmemişken çekişmeye girişenlerin gönüllerinde, ancak ulaşmalarına imkan olmayan bir büyüklenme duygusu var; artık Allah''a sığın, şüphe yok ki o, duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 57, 'Elbette gökleri ve yeryüzünü yaratmak, insanları yaratmaktan daha büyük bir şey ve fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 58, 'Ve eşit değildir körle gören ve inanıp iyi işlerde bulunanla kötülükler eden; ne de az düşünmede, ne de az ibret almadasınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 59, 'Kıyamet, elbette kopacak, şüphe yok bunda ve fakat insanların çoğu inanmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 60, 'Ve Rabbiniz dedi ki: Çağırın beni, icabet edeyim size; şüphe yok ki bana kulluk etmekten, ululuk satarak çekinenler, aşağılık bir halde cehenneme gireceklerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 61, 'Öyle bir Allah''tır ki size geceyi yarattı, dinlenmeniz için ve gündüzü yarattı, göregöre işlerinizi yapmanız için; şüphe yok ki Allah, elbette insanlara karşı lütuf ve ihsan sahibidir ve fakat insanların çoğu şükretmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 62, 'İşte budur Rabbiniz Allah ki her şeyi halk eden odur, yoktur ondan başka tapacak; ne diye asılsız şeylere kapılmadasınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 63, 'İşte böyle kapılırlar Allah''ın delillerini, bilebile inkar edenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 64, 'Bir Allah''tır ki yeryüzünü, size karar edecek bir yurt, göğü de bir kubbe olarak yaratmıştır ve size suret vermiştir, suretinizi de en güzel bir şekle sokmuştur ve sizi, tertemiz şeylerle rızıklandırmıştır; işte budur Rabbiniz; ne yücedir alemlerin Rabbi Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 65, 'Odur daimi diri, yoktur ondan başka tapacak, artık onun dininde, yüreğinizi ona bağlayarak çağırın onu; hamd, alemlerin Rabbi Allah''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 66, 'De ki: Şüphe yok ki ben, Allah''tan başka sizin taptıklarınıza tapmaktan menedildim, Rabbimden apaçık deliller gelince bana ve alemlerin Rabbine teslim olmam emredildi bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 67, 'Öyle bir mabuttur ki sizi topraktan, sonra bir katre sudan, sonra bir pıhtı kandan yaratmıştır, sonra sizi, çocuk olarak dünyaya çıkarmıştır, sonra ergenlik çağına erişmeniz, sonra da ihtiyar olmanız için sizi yaşatmadadır ve sizden, daha önce öldürülen de var ve hepinizi de muayyen ve mukadder bir zamanadek yaşatır ve bütün bunlar da akıl edesiniz diye olup biter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 68, 'Öyle bir mabuttur ki diriltir ve öldürür; derken bir işin olmasını hükmetti mi ancak, ol der o işe, oluverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 69, 'Görmedin mi Allah''ın delilleri hakkında çekişmeye girişenleri, nereye gitmedeler, neye kapılmadalar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 70, 'Onlar, öyle kişilerdir ki kitabı ve peygamberlerimizle gönderdiğimiz şeyleri yalanlamışlardır, yakında bilip anlayacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 71, 'Boyunlarına demirden laleler ve zincirler takılıp sürüklendikleri zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 72, 'Sıcak su içinde, sonra cehenneme atıldıkları zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 73, 'Sonra da denecek ki nerede şirk koştuklarınız,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 74, 'Allah''ı bırakıp da? Diyecekler ki: Gözümüzden kayboldular, zaten de bundan önce tapmaya layık birşeye tapmamıştık biz; işte Allah, kafirleri böyle saptırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 75, 'Bu da, yeryüzünde haksız yere sevinip övündüğünüzden ve ululanıp kendinizi gördüğünüzdendir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 76, 'Girin kapılarından cehennemin, orada ebedi olarak kalacaksınız; gerçekten de ululananların yeriyurdu, ne de kötüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 77, 'Artık sabret, şüphe yok ki Allah''ın vaadi gerçektir. Derken ya onlara vaadettiğimiz şeylerin bazısını göstereceğiz sana, yahut da seni öldüreceğiz, derken hepsi de dönüp tapımıza gelecekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 78, 'Ve andolsun ki senden önce nice peygamberler gönderdik, onlardan, sana anlattıklarımız da var, anlatmadıklarımız da ve hiç bir peygamber, Allah''ın izni olmadıkça bir delil, bir mucize gösteremez; derken Allah''ın emri gelince gerçek olarak hükmedilir ve işte buracıkta, boş şeylere uyanlar, ziyan eder gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 79, 'Öyle bir Allah''tır ki onların bir kısmına binin, bir kısmını da yiyin diye davarlar yaratmıştır size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 80, 'Ve onlarda başka faydalar da var size ve gönüllerinizdeki murada ulaşmak için onlara ve gemilere biniyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 81, 'Ve size delillerini göstermede, Allah''ın delillerinden hangisini inkar edebilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 82, 'Yeryüzünü gezip dolaşmazlar mı ki onlardan önce gelip geçenlerin ne olmuş sonları, bir bakıp görsünler? Onlar, topluluk bakımından daha çoktu, kuvvet ve yeryüzünde yaptıkları şeyler bakımından da daha üstündü bunlardan; derken elde ettikleri şeylerin, onlara hiçbir faydası olmadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 83, 'Peygamberleri, apaçık delillerle onlara gelince kendilerindeki bilgiye güvenip övündüler, kendilerini gördüler de alay ettikleri şey, başlarına geliverdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 84, 'Derken azabını görünce de Allah''ın birliğine inandık dediler ve şirk koştuğumuz şeyleri inkar ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (40, 85, 'Fakat azabımızı gördükleri zaman inanmaları, onlara bir fayda vermez; Allah''ın, kulları hakkında icra edilegelen yoluyoradamıdır bu ve işte buracıkta kafirler, ziyan edip giderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 2, 'Rahman ve rahimden indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 3, 'Bir kitaptır ki tamamıyla açıklanmıştır ayetleri, Arapça Kur''an''dır bilen topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 4, 'Müjdecidir ve korkutucu, fakat çoğu yüz çevirmiştir, onlar, duymazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 5, 'Ve derler ki: Bizi davet ettiğin şeye karşı gönüllerimizde perdeler var ve kulaklarımızda ağırlık var ve seninle bizim aramızda da bir perde var, artık sen, dinince çalış, biz de çalışmadayız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 6, 'De ki: Ben, ancak sizin gibi bir insanım, bana vahyedilmede ki mabudunuz ancak bir mabut; artık dosdoğru ona yönelin ve yarlıganma dileyin ondan; ve yazıklar olsun şirk koşanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 7, 'Öyle kişilerdir onlar ki zekat vermezler ve onlar, ahirete inanmayanların da ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 8, 'İnanan ve iyi işlerde bulunanlarsa: Onlarındır minnetsiz mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 9, 'De ki: Siz mi kafir olmadasınız, inkar etmedesiniz bir mabudu ki yeryüzünü iki günde yaratmıştır ve siz mi ona eşler kabul etmedesiniz? Budur işte alemlerin Rabbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 10, 'Ve yeryüzünün üstünde metin dağlar yaratmıştır ve kutlamıştır orasını, bereket ihsan etmiştir ve rızık olacak şeyleri takdir etmiştir de meydana getirmiştir bunları orada, tam dört gün içinde, dileyenler için hepsi de eşittir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 11, 'Sonra bir duman halinde olan göğü yaratmayı hükmetmiştir de ona ve yeryüzüne, dileyerekdilemeyerek meydana gelin demiştir, ikisi de, dileyerek geldik demişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 12, 'Derken onları yedi gök olarak iki günde yaratmış ve her göğe yapacağı işi vahyetmiştir. Ve dünya göğünü kandillerle bezedik ve koruduk; işte bu, üstün olan ve her şeyi bilen mabudun takdiridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 13, 'Yüz çevirirlerse artık de ki: Sizi, Âd ve Semud''un uğradıkları helak edici azaba benzer bir azapla korkutmadayım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 14, 'Hani onlara, kendilerinden önce de, kendilerinden sonra da peygamberler gelmişti de Allah''tan başkasına kulluk etmeyin demişlerdi. Onlar, Rabbimiz dileseydi demişlerdi, melekler indirirdi elbette, biz, gerçekten de sizin gönderildiğiniz şeyleri inkar etmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 15, 'Âd''a gelince: Gerçekten de yeryüzünde, haksız yere ululanmaya kalkıştılar ve kimdir dediler, bizden daha kuvvetli? Görmediler mi ki şüphe yok, onları halkeden Allah, onlardan da kuvvetlidir; ve onlar, delillerimizi bilebile inkar ediyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 16, 'Derken onlara, dünya yaşayışında, aşağılık azabını tatsınlar diye uğursuz günlerde bir kasırgadır, yolladık ve elbette ahiret azabı, daha da aşağılatıcıdır ve onlar, bir yardım da görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 17, 'Semud''aysa doğru yolu gösterdik de onlar, körlüğü, hidayetten üstün görüp sevdiler, onları da, kazandıklarına karşılık aşağılatıcı bir azabın gelip çatıvermesiyle helak ettim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 18, 'Ve inananları kurtardık ve onlar, çekinen kişilerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 19, 'Ve o gün, Allah düşmanları, bir araya toplanır da toplu bir halde cehenneme sürülürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 20, 'Oraya gelince de kulakları, gözleri ve derileri, yaptıkları şeyler hakkında, kendi aleyhlerine tanıklıkta bulunur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 21, 'Ve bedenlerine, ne diye aleyhimizde tanıklık ettiniz derler, onlar da her şeyi söyleten Allah derler, bizi de söyletti ve odur sizi halkeden ilk defa ve gene de dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 22, 'Ve siz, kulaklarınızın, gözlerinizin, derilerinizin, aleyhinizde tanıklık edeceklerini ummuyor, onlardan hiçbir şeyinizi gizlemiyordunuz ve hatta sanıyordunuz ki yaptıklarınızın çoğunu Allah bile, şüphe yok ki bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 23, 'Ve Rabbiniz hakkında beslediğiniz şu kötü zan yok mu, sizi o helak etti de ziyana uğrayıverdiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 24, 'Artık sabredebilirlerse ateştir yurtları onların ve onlar suçlarından geçilmesini isterlerse dilekleri kabul edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 25, 'Ve onlara öyle arkadaşlar hazırladık ve verdik ki önlerindeki dünya işlerini ve artlarındaki ahireti inkar etmeyi bezediler onlara ve onlardan önce, cinlerden ve insanlardan gelip geçmiş ümmetler arasında azap hükmünü hakettiler, şüphe yok ki onlar, ziyana uğrayanlardandı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 26, 'Ve kafir olanlar, dediler ki: Şu Kur''an''ı dinlemeyin ve okunurken gürültü edin, bağırıp çağırın da onun sesini bastırın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 27, 'Biz de mutlaka kafir olanlara çetin bir azabı tattıracağız ve yaptıkları şeyin en kötü karşılığıyle cezalandıracağız onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 28, 'İşte bu ateş, Allah düşmanlarının cezasıdır, onlara, ebedilik var orada; bu da delillerimizi bilebile inkar etmelerinin karşılığı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 29, 'Ve kafir olanlar, Rabbimiz diyecekler, cinlerden, insanlardan, bizi azdıranları göster bize de en aşağılık bir hale gelmeleri için onları ayaklarımızın altına alalım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 30, 'Gerçekten de, Rabbimiz Allah''tır dedikten sonra da dosdoğru hareket edenlere melekler indiririz de sakın korkmayın ve mahzun olmayın ve müjdelenin, sevinin size vaadedilen cennetle deriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 31, 'Biz, dünya yaşayışında da size dostuz, ahirette de ve burada, canınız ne isterse var ve burada dilediğiniz her şey sizin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 32, 'Suçları örtenden, rahim olandan bir ziyafet, bir ihsan bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 33, 'Allah''a çağırandan ve iyi işlerde bulunandan ve şüphe yok ki ben Müslümanlardanım diyenden daha güzel sözlü kimdir ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 34, 'Ve eşit değildir iyilikle kötülük. Kötülüğü, en güzel bir muameleyle karşıla, gider, bir de bakarsın ki aranızda düşmanlık olan kişi, sanki senin en yakın bir dostun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 35, 'Bu huy, sabredenlerden başkasına verilmez ve akıldan, tedbirden büyük bir hisseye sahip olmayanlara bu huy, nasip olmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 36, 'Ve eğer Şeytan, seni vesveseye düşürür de bu huydan geçirmeye kalkışırsa hemen sığın Allah''a; şüphe yok ki o, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 37, 'Ve onun delillerindendir gece ve gündüz ve güneş ve ay; secde etmeyin ne güneşe, ne de aya ve secde edin, onları yaratan Allah''a, yalnız ona kulluk ediyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 38, 'Eğer ululanmaya kalkışır, bunu kabul etmezlerse zaten Rabbinin katındakiler, gece ve gündüz, onu tenzih etmededir durmadan, dinlenmeden ve usanmadan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 39, 'Ve onun delillerindendir, şüphesiz, yeryüzünü kupkuru, donmuş bir halde görürsün, derken oraya yağmur yağdırdık mı harekete gelir, kabarır, yeşerir, nebatlar bitirir; onu dirilten, elbette ölüyü de diriltir şüphe yok ki onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 40, 'Bizim delillerimizle eğri yola sapanlar gizli değildir bize. Artık ateşe atılan mı hayırlıdır, yoksa kıyamet günü emin olarak gelen mi? Ne dilerseniz yapın, şüphe yok ki o, bütün yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 41, 'Kur''an, kendisine tebliğ edildikten sonra kafir olanlar; ve hem de şüphe yok ki bu Kur''an, eşsiz ve sütün bir kitaptır ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 42, 'Ne önceden onun hükümlerini iptal eden bir kitap gelmiştir, ne de ondan sonra gelir ve batıl, ona zarar veremez; hüküm ve hikmet sahibinden, hamde layık mabut tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 43, 'Zaten sana söylenen, ancak senden önceki peygamberlere de söylenen sözlerdir; şüphe yok ki Rabbin, suçları örtme sıfatına sahip olmakla beraber elemli bir azaba da sahiptir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 44, 'Eğer yabancı bir dille meydana getirseydik Kur''an''ı, elbette derlerdi ki ayetleri Arapça olarak açıklansaydı da anlasaydık olmaz mıydı? Bu, yabancı bir dille söylenmiş söz, söyleyen de Arap ha? De ki: O, inananlara doğru yolu gösterir ve şifadır; inanmayanlarınsa kulaklarında ağırlık var ve Kur''an, onları kör etmede; sanki onlara pek uzak bir yerden nida edilmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 45, 'Ve andolsun ki biz Musa''ya da kitap verdik de o kitapta ihtilafa düştüler ve eğer Rabbinden azaplarının mukadder bir zamana tehir edilmesi hakkında bir emir verilmemiş olsaydı çoktan hükmedilirdi aralarında ve şüphe yok ki onlar, bu hususta elbette şüphe içindeler, tereddüde düşmüşler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 46, 'Ve kim iyi bir iş yaparsa faydası kendisinedir ve kim kötülükte bulunursa zararı kendisine ve Rabbin, kullarına zulmetmez kesin olarak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 47, 'Kıyametin, ne vakit kopacağına dair bilgi, Allah''a aittir ve onun hükmü ve bilgisi olmadan meyveler, tomurcuklarından ve kabuklarından çıkamaz ve hiçbir kadın gebe kalamaz ve çocuğunu doğuramaz ve o gün, nerede şeriklerim diye nida edilir onlara da sana bildirdik zaten derler, bu hususta bir tanığımız bile yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 48, 'Ve önceden çağırdıkları putlar, gözlerinden kaybolup gitmiştir ve onlar, kaçıp sığınacakları bir yerleri olmadığını da iyideniyiye anlamışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 49, 'İnsan, hayır istemekten hiç usanmaz ve bir şerre uğrarsa da iyideniyiye yeise düşer, ümitsizliğe kapılıp gider.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 50, 'Ve andolsun ki bir sıkıntıdan sonra katımızdan bir rahmet tattırsak ona, bu der, zaten benim hakkım ve hiç sanmıyorum ki kıyamet kopsun ve andolsun ki Rabbimin tapısına dönüp varsam bile hiç şüphesiz, onun katında daha güzel bir lütuf var bana; artık biz de, andolsun ki kafir olanlara, neler yaptıklarını elbette haber veririz ve elbette onlara çok ağır azabı tattırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 51, 'Ve insana bir nimet verdik mi yüz çevirir ve şükürden uzaklaşır ve eğer bir şerre uğrarsa uzunuzadıya dua eder durur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 52, 'De ki: Kur''an''ın Allah katından geldiğini görmüşseniz, sonra da ona kafir olmuşsanız haber verin bana, gerçeğe tamamıyla aykırı kalandan daha sapık kimdir ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 53, 'Yakında delillerimizi, alemde de göstereceğiz, kendi varlıklarında da, böylece sonucu, onlarca da apaçık anlaşılacaktır ki o, gerçektir şüphesiz; Rabbinin, her şeye tanık olması, yetmez mi sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (41, 54, 'İyice bil ki onlar, şüphe yok, Rablerine kavuşacaklarından şüphe etmedeler; iyice bil ki şüphe yok, o, her şeyi kuşatmış, kavramıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 2, 'Ayn sin kaaf.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 3, 'İşte böyle vahyetmededir sana ve senden öncekilere o üstün, o hüküm ve hikmet sahibi Allah.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 4, 'Onundur ne varsa göklerde ve ne varsa yeryüzünde ve odur pek yüce, pek ulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 5, 'Müşriklerin sözlerinden neredeyse gökler, üstlerinden çatlayıp yarılacak ve melekler, ona hamd ederek tenzih ederler onu ve yeryüzündekilere yarlıganma dilerler; iyice bil ki şüphe yok Allah, odur örten ve rahim olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 6, 'Onun bırakıp da ondan başka dostlar ve tanrılar kabul edenlerin yaptıklarını Allah, görür, gözetir ve onların yaptıklarını görüp gözetecek, sen değilsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 7, 'Ve işte sana, böylece Arapça Kur''an''ı vahyettik, şehirlerin aslı ve temeli olan Mekke''yi ve çevresindeki bütün şehirleri korkutman ve geleceğinde şüphe olmayan topluluk gününü haber vererek o günün dehşetiyle korkutman için; halkın bir bölüğü cennettedir ve bir bölüğü yakıp kavuran cehennemde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 8, 'Ve Allah isteseydi elbette onları bir ümmet olarak halkederdi ve fakat dilediğini rahmetine ithal eder ve zalimlere gelince: Onlara ne bir dost vardır, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 9, 'Yoksa, onu bırakıp kendilerine sahip olacak başka mabutlar mı kabul ettiler? Gerçekten de kudret sahibi ancak o Allah''tır ve odur ölüyü dirilten ve onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 10, 'Ve bir şeyde ihtilafa düştünüz mü onun hükmü, Allah''a aittir, budur mabudunuz olan Rabbim Allah, ona dayandım ben ve her hususta ona dönerim ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 11, 'Odur yoktan var eden gökleri ve yeryüzünü, size kendi cinsinizden eşler halketmiştir, davarları da çifterçifter halketmiştir, bu suretle üretip çoğaltmadadır sizi; ona hiçbir benzer yoktur ve odur duyan, gören.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 12, 'Onundur göklerin ve yeryüzünün kilitleri, dilediğine bolbol rızık verir, dilediğinin rızkını daraltır; şüphe yok ki o, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 13, 'Dine ait hükümlerden, Nuh''a tavsiye ettiğini ve sana vahyettiklerimizi ve İbrahim''e, Musa ve İsa''ya tavsiye ettiklerimizi, size de gidilecek yol olarak bildirdi, açıkladı; dine yapışın ve o hususta hiçbir ayrılığa düşmeyin. Onları, inanmaya çağırdığın şey, müşriklere pek büyük, pek ağır gelmede; Allah, dilediğini kendisine seçer ve kim, ona dönerse doğru yolu gösterir ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 14, 'Onlar, aralarındaki hırs ve haset yüzünden, kendilerine bu hususta bilgi geldikten sonra ayrılığa düştüler ve Rabbin, muayyen bir zamana kadar onlara azap etmemeyi takdir etmeseydi aralarında çoktan hükmedilirdi ve onlardan sonra kitaba varis olanlarda bu hususta elbette şüphe içindedir, tereddüde düşmüşlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 15, 'Ve işte bunun için artık onları çağır ve doğru hareket et emredildiğin gibi ve uyma onların dileklerine ve de ki: Ben, kitaptan ne indirdiyse Allah, inandım ona ve bana, aranızda adaletle hükmetmem emredildi; Allah, Rabbimizdir ve Rabbiniz; bizim yaptıklarımız, bize aittir, sizin yaptıklarınız size; düşmanlık yok bizimle sizin aranızda; Allah, bir yerde toplayacak bizi ve sonunda dönüp onun tapısına varılacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 16, 'Halk tarafından, ona icabet edildikten sonra Allah hakkında cedelleşmeye girişenlerin gösterdikleri düşmanlık, Rableri katında boştur ve onlaradır gazep ve onlaradır çetin bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 17, 'Öyle bir Allah''tır ki gerçek olarak kitabı ve adaleti indirmiştir ve ne bilirsin, belki de kıyamet, pek yakındır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 18, 'Buna inanmayanlar, çabuk gelmesini isterler ve inananlarsa gelip çatmasından korkarlar ve bilirler ki o, gerçektir; iyice bil ki kıyametten şüphe edip o hususta mücadeleye girişenler, elbette doğrudan pek uzak bir sapıklık içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 19, 'Allah, kullarına lutfeder, dilediğini rızıklandırır ve odur pek kuvvetli ve üstün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 20, 'Kim, ahiret kazancı isterse kazancını arttırırız ve kim, dünya kazancını isterse ona da dünyaya ait şeylerin bir kısmını veririz ve ahiretten bir nasibi yoktur onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 21, 'Yoksa Allah''ın emir ve izin vermediği bir dini onlara kuran ortaklar mı var? Azabın, mukadder bir zamana geciktirilmesi takdir edilmemiş olsaydı çoktan aralarında hükmedilirgiderdi ve şüphe yok ki zalimleredir elemli azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 22, 'Görürsün ki zulmedenler, kazandıkları şeylerden dolayı korkup durular ve korktukları da başlarına gelecek ve inananlar ve iyi işlerde bulunanlarsa cennet bahçelerindedir, onlarındır Rableri katında ne dilerlerse; bu, pek büyük bir lütuftur, ihsandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 23, 'Bu, Allah''ın, inanan ve iyi işlerde bulunan kullarını müjdelemesidir işte. De ki: Sizden, tebliğime karşılık bir ücret istemiyorum, istediğim, ancak yakınlarıma sevgidir ve kim güzel ve iyi bir iş yaparsa onun güzelim mükafatını arttırırız; şüphe yokki Allah, suçları örter, iyiliğe, mükafatla karşılık verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 24, 'Yoksa bunu Allah''a isnat ederek o uydurdu mu derler? Gerçekten de Allah dilerse gönlünü mühürler senin ve Allah, batılı mahveder ve gerçeği gerçekleştirir sözleriyle; şüphe yok ki o, gönüllerde olanları bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 25, 'Ve o, bir mabuttur ki kullarının tövbesini kabul eder ve kötülükleri bağışlar ve ne yapıyorsanız, hepsini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 26, 'İnanan ve iyi işlerde bulunanların dileklerine icabet eder ve onlar hakkındaki ihsan ve keremini, lütfüyle arttırır ve kafirlere gelince: Onlaradır çetin azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 27, 'Ve Allah, kullarının rızkını yaysaydı, bollaştırsaydı yeryüzünde azgınlıkta bulunurlardı ve fakat o, ne kadar dilerse o kadar indirir; şüphe yok ki o, kullarından haberdardır, onları görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 28, 'Ve öyle bir mabuttur ki onlar, tamamıyla ümitsizliğe düşerler de ondan sonra yağmur yağdırır ve rahmetini yayar ve odur onların işlerini tedbir ve tasarruf eden ve hamde layık olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 29, 'Ve delillerindendir gökleri ve yeryüzünü yaratması ve her ikisinde mahlukatı yayıp dağıtması ve onun, elbette onları toplamaya da gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 30, 'Ve size gelip çatan her felaket, ellerinizle kazandığınız bir şeydir ancak ve çoğunu da bağışlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 31, 'Ve siz, yeryüzünde onu aciz bir hale getiremezsiniz ve size, Allah''tan başka ne bir dost vardır, ne bir yardımcı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 32, 'Ve onun delillerindendir denizde akıp giden yüce dağlar gibi gemiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 33, 'Dilerse rüzgarı durdurur da denizin üstünde, öylece kalakalırlar; şüphe yok ki bunda, iyideniyiye sabreden ve çok şükreden herkese elbette deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 34, 'Yahut da, kazandıkları suçlar yüzünden fırtınalarla helak eder gemileri ve çoğunu da bağışlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 35, 'Delillerimiz hakkında cedelleşmeye kalkışanlar, bilsinler ki onlara hiçbir yer yok ki kaçıp da kurtulsunlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 36, 'Gerçekten de size verilenler, dünya yaşayışına ait metalardan ibaret ve Allah katındakiyse daha da hayırlıdır ve daha da fazla kalır inananlara ve Rablerine dayananlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 37, 'Ve suçların büyüklerinden ve çirkin şeylerden kaçınanlara ve kızdıkları zaman, suçları örtenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 38, 'Ve Rablerinin davetine icabet edenlere ve namaz kılanlara ve işlerini, aralarında danışarak yapanlara ve onları rızıklandırdığımız şeylerin bir kısmını ayırıp yoksulları doyuranlara, hayra harcayanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 39, 'Ve bir zulme uğradıkları zaman haddi aşmaksızın birbirlerine yardım ederek karşı duranlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 40, 'Ve kötülüğün karşılığı, ona benzer bir kötü cezadır. Gerçekten de kim bağışlar ve barışı sağlarsa mükafatı, Allah''a aittir; şüphe yok ki o, zulmedenleri sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 41, 'Ve kim, zulme karşı savunursa bu çeşit kişileri suçlu saymaya bir yol yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 42, 'Ancak halka zulmedenleri ve haksız yere, yeryüzünde azgınlıkta bulunanları suçlu saymaya yol var, onlaradır elemli azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 43, 'Ve kim, dayanır ve suçları örterse şüphe yok ki bu, azme, iradeye dayanan işlerdendir elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 44, 'Ve Allah, kimi saptırırsa artık ona, bundan böyle bir dost yoktur ve zalimleri görürsün ki azabı görünce, geriye dünyaya dönmeye derler, bir yol var mı ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 45, 'Ve görürsün ki onlar, ateşin önüne getirildikleri zaman düştükleri horluktan ürküp titremedeler ve cehenneme, göz ucuyla gizlice bakmadalar ve inananlarsa şüphe yok ki derler, ziyana düşenler, kıyamet gününde kendilerini ve yakınlarını ziyana düşürenlerdir. İyice bil ki zulmedenler, şüphesiz, sürekli bir azap içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 46, 'Ve Allah''tan başka onlara yardım edecek bir dost da yoktur ve Allah, kimi saptırırsa artık bir yol yok ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 47, 'Rabbinizin davetine icabet edin reddine imkan olmayan gün Allah tarafından gelip çatmadan; o gün, ne kaçıp sığınılacak bir yer var size ve ne suçlarını inkara mecal var size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 48, 'Yüz çevirirlerse artık biz, seni onları korumaya göndermedik ki; sana ancak tebliğ etmek düşer ve şüphe yok ki biz, insana, katımızdan bir rahmet tattırdık mı sevinir, övünür onunla, fakat elleriyle hazırlayıp kazandıkları bir kötülüğe uğrarlarsa da gerçekten insan, pek nankördür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 49, 'Allah''ındır göklerin ve yeryüzünün saltanatı ve tedbiri, dilediğini yaratır, dilediğine kız evlat verir ve dilediğine oğlan evlat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 50, 'Yahut da çift olarak hem kız evlat verir, hem oğlan ve dilediğini de kısır yaratır; şüphe yok ki onun her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 51, 'Ve hiçbir insana söz söylemez Allah, ancak vahiyle, yahut perde ardından, yahut da bir elçi gönderir de, izniyle dilediğini vahyeder ona; şüphe yok ki o, pek yücedir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 52, 'Ve işte biz, emrimizle sana böylece Ruh''u gönderdik de vahyettik; ne kitap nedir, bilirdin, ne de iman ve fakat onu, kullarımızdan dilediğimizi doğru yola sevk eden bir nur olarak yarattık ve şüphe yok ki sen de elbette doğru yola sevk edersin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (42, 53, 'O yoluna Allah''ın ki onundur ne varsa göklerde ve ne varsa yeryüzünde; iyice bilin ki bütün işler, dönüp Allah tapısına varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 2, 'Andolsun her şeyi açıklayan kitaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 3, 'Şüphe yok ki biz, akıl edesiniz, anlayasınız diye Kur''an''ı Arap diliyle meydana getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 4, 'Ve şüphe yok ki o, bizim katımızda, kitabın aslındadır, temelindedir, elbette pek yücedir, hüküm ve hikmetle doludur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 5, 'Haddi aşmış bir topluluk olduğunuzdan dolayı size Kur''an''ı bildirmekten vaz mı geçelim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 6, 'Önce gelenler içinde de nice peygamberler gönderdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 7, 'Ve hiçbir peygamber gelmedi onlara ki onunla alay etmesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 8, 'Derken kuvvet bakımından, bunlardan çok daha çetin oldukları halde helak ettik onları ve öncekilere ait kıssalar, sana anlatıldı evvelce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 9, 'Ve andolsun ki onlara, kim yarattı gökleri ve yeryüzünü diye sorsan elbette onları diyeceklerdir, üstün olan ve her şeyi bilen yarattı;', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 10, 'Öyle bir mabuttur ki yeryüzünü, size karar edilecek bir yurt olarak yaratmıştır ve istediğinizi elde etmeniz için de orada yollar halketmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 11, 'Ve öyle bir mabuttur ki ihtiyaç miktarınca yağmur yağdırır gökten, derken onunla ölü şehri diriltiriz, işte böylece sizi de diriltip kabirlerinizden çıkarır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 12, 'Ve öyle bir mabuttur ki bütün mahlukatı erkek ve dişi olarak yaratmıştır ve bindiğiniz gemileri ve hayvanları halketmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 13, 'Binip oturun da sonra onların üstünde doğruldunuz mu Rabbinizin nimetini anın ve yücedir, münezzehtir noksan sıfatlardan o mabut ki ram etmiştir bunu bize, yoksa biz, zaptedemezdik onu deyin diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 14, 'Ve şüphe yok ki biz, Rabbimize döneceğiz deyin diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 15, 'Ve bazı kullarının, onun bir parçası olduğuna, ondan vücuda geldiğine hükmettiler, gerçekten de insan, apaçık bir nankördür elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 16, 'Yoksa o, yarattıklarından kızları, kendisine kız ediniyor da oğulları size mi bırakıyor?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 17, 'Ve onlardan biri, bir kızın oldu diye müjdelendi mi, Allah''ın kızı var dediği halde yüzü kapkara olur ve kızar, kederlenir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 18, 'Onlar, süslenip bezenerek yetişen ve münakaşada, düşmanlıkta, apaçık bir delil bile getiremeyen, istediğini söyliyemeyen bir mahluku mabuda mı nispet ediyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 19, 'Ve rahmanın kulları olan meleklerin, kız olduğuna hükmediyorlar, onları yarattığımız vakit gördüler mi ki? Tanıklıklarını yazacağız ve soruya çekilecek onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 20, 'Ve rahman isteseydi derler, kulluk etmezdik onlara; bu hususta hiçbir bilgileri yok; onlar, yalandan başka bir şey söylemiyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 21, 'Yoksa onlara, bu kitaptan önce bir kitap mı verdik de ona sımsıkı yapışmışlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 22, 'Hayır, şüphe yok ki dediler, biz atalarımızı bir dine, bir inanca sahip bulduk ve şüphe yok ki biz de onların izini izlemede, o yola gitmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 23, 'Ve böylece senden önce de hiçbir şehre bir korkutucu göndermedik ki o şehrin, halivakti yerinde olanları, şüphe yok ki biz, atalarımızı bir dine, bir inanca sahip bulduk ve şüphe yok ki biz de onların izine uyduk demesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 24, 'Peygamber, onlara, ben dedi, atalarınızdan bulduğunuz dinden daha doğru bir dinle gelsem de gene atalarınızın yoluna mı gideceksiniz? Şüphe yok ki biz dediler, sizin gönderildiğiniz şeyleri zaten inkar etmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 25, 'Derken öç aldık onlardan, bak da gör, yalanlayanların sonları ne oldu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 26, 'Ve an o zamanı ki hani İbrahim, atasına ve kavmine demişti: Şüphe yok ki ben, sizin kulluk ettiklerinizden tamamıyla uzağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 27, 'Ben, ancak beni yoktan var edene taparım, artık o da doğru yolu gösterir bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 28, 'Ve bu birlik sözünü, gerçeğe dönsünler diye soyu arasında da daima kalacak ve zeval bulmayacak bir vasiyet olarak bıraktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 29, 'Belki de ben, onları da, atalarını da, onlara bir gerçek ve apaçık bir peygamber gelinceye dek geçindirmedeydim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 30, 'Ve onlara gerçek gelince de bu dediler, büyü ve biz şüphe yok ki inkar etmedeyiz onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 31, 'Ve bu Kur''an dediler, iki şehirden birinin en büyük, en ileri gelen adamına inseydi ne olurdu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 32, 'Onlar mı Rabbinin rahmetini pay edecekler? Biziz geçimlerini, aralarında paylaştıran dünya yaşayışında ve bir kısmı, bir kısmına hizmet etsin diye bazılarını derece bakımından bazılarından üstün halkettik ve Rabbinin rahmeti, onların toplayıp biriktirdiklerinden daha hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 33, 'Bütün insanların, kafir olmaları gibi bir mahzur bulunmasaydı rahmanı inkar edenlerin evlerindeki tavanları ve üstüne basıp çıktıkları merdivenleri bile gümüşten halk ederdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 34, 'Ve evlerinin kapılarını ve üstüne oturup yaslandıkları tahtları gümüşten yapardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 35, 'Ve onları altınlara, mücevherlere boğardık ve bütün bunlar, dünya yaşayışına ait metalardan ibaret ve ahiretse, Rabbinin katında, çekinenlerin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 36, 'Ve kim, rahmanı anmadan yüz çevirirse ona bir Şeytan musallat ederiz, artık o, arkadaş olur ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 37, 'Ve şüphe yok ki Şeytanlar, onları yoldan çıkarır ve şüphe yok ki doğru yolu bulduklarını sanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 38, 'Sonunda bizim tapımıza geldi mi keşke der, seninle benim aramda doğuyla batı kadar bir uzaklık olsaydı, gerçekten de ne kötü arkadaşmış.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 39, 'Ve o zaman zulmetmiştiniz, bugün pişmanlık kesin olarak fayda vermez size, şüphe yok ki azapta da müştereksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 40, 'Sen mi sağıra duyuracaksın, yahut köre ve apaçık bir sapıklık içinde bulunana yol göstereceksin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 41, 'Seni, katımıza alsak bile hiç şüphe yok ki mutlaka onlardan öç alırız biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 42, 'Yahut da onlara vaadettiğimiz azabı mutlaka sana gösteririz, gerçekten de onlara gücümüz yeter bizim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 43, 'Sen yapış sana vahyedilene, şüphe yok ki doğru yoldasın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 44, 'Ve şüphe yok ki o, sana da elbet öğüttür, kavmine de ve soruya çekileceksiniz yakında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 45, 'Ve sor senden önce peygamberlerimizden gönderdiklerimize: Rahmandan başka kulluk edilen mabutlar yarattık mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 46, 'Ve andolsun ki Musa''yı, delillerimizle Firavun''a ve kavminin ileri gelenlerine gönderdik de ben dedi, şüphe yok ki alemlerin Rabbinin peygamberiyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 47, 'Onlara delillerimizle gelince o delillere gülmeye başladılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 48, 'Onlara hiçbir delil göstermedik ki biri, öbüründen büyük olmasın ve tuttukları yoldan dönsünler diye de azaplandırdık onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 49, 'Ve ey büyücü demişlerdi, sana söz verdiğini sandığın Rabbine yalvar bizim için, şüphe yok ki biz de elbette doğru yola geliriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 50, 'Derken onlardan azabı kaldırdık mı sözlerinden döndüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 51, 'Ve Firavun, kavminin arasında bağırıp dedi ki: Ey kavmim, Mısır saltanatı ve ayağımın altından akıp duran şu ırmaklar, benim değil mi, görmüyor musunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 52, 'Ben, şu aşağılık ve doğrudüzen söz bile söyliyemeyen adamdan daha hayırlı değil miyim?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 53, 'Ne olurdu, bari ona altın bilezikler takılmış olsaydı, yahut da onunla, ona uyan, yardım eden melekler gelseydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 54, 'Derken kavminin aklını çeldi de ona itaat ettiler, şüphe yok ki onlar, yoldan çıkmış bir topluluktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 55, 'Bizi gazaba getirdiler mi öç aldık onlardan, derken hepsini de sulara boğduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 56, 'Gerçekten de kafirlerin önde gidenleri kıldık onları ve sonradan gelenlere ibret ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 57, 'Meryemoğlu örnek getirilince kavmin hemen bağrışmaya başladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 58, 'Ve bizim mabutlarımız mı hayırlı, yoksa o mu dediler, onlar, bu örneği ancak çekişmek için getirdiler; zaten de onlar düşmanlık ededuran bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 59, 'Oysaki o, kendisine nimetler verdiğimiz ve İsrailoğullarına örnek gösterdiğimiz bir kuldu ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 60, 'Ve dileseydik yeryüzüne melekler getirirdik, sizin yerinize onları geçirirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 61, 'Onun gökten inmesi, kıyametin yaklaştığını bildirir, sakın kıyamet hakkında şüpheye düşmeyin ve uyun bana; budur doğru yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 62, 'Ve Şeytan, sizi yoldan çıkarmasın; şüphe yok ki o, size apaçık bir düşmandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 63, 'Ve İsa, apaçık delillerle gelince ben demişti, andolsun ki size peygamber olarak geldim ve ayrılığa düştüğünüz bazı şeyleri elbette açıklayıp bildireceğim size; artık çekinin Allah''tan ve itaat edin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 64, 'Şüphe yok ki Allah, Rabbimdir ve Rabbinizdir o, kulluk edin ona. Budur doğru yol.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 65, 'Aralarından bölükler, ayrılığa düştü; yazıklar olsun zulmedenlere elemli günün azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 66, 'Onlar, kıyametin kopmasından başka bir şey mi bekliyorlar ki ansızın kopuverir başlarına ve onlar, anlamazlar bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 67, 'Dostların bir kısmı, bir kısmına düşman olur o gün, ancak çekinenler müstesna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 68, 'Ey kullarım, korku yok size bugün, kederlenmezsiniz de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 69, 'O kullarım, inananlardır delillerimize ve onlar, teslim olanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 70, 'Girin cennete siz ve eşleriniz kutlulukla, sevinerek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 71, 'Onlara altından yapılmış tabaklar ve testiler sunulacak ve orada nefsin istediği ve gözün hoşlandığı her şey var ve siz, orada ebedi olarak kalırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 72, 'Ve şu cennete mirasçı oldunuz işlediğiniz şeyler yüzünden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 73, 'Size orada birçok meyveler de var, onlardan yersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 74, 'Şüphe yok ki mücrimler, cehennem azabında ebedi olarak kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 75, 'Azapları hafifletilmiyecek ve orada ümitsiz bir halde kalacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 76, 'Ve biz zulmetmedik onlara ve fakat onlar zulmettiler kendi kendilerine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 77, 'Ve ey Malik diye bağıracaklar, yalvar Rabbine de öldürsün bizi; Malik, şüphe yok ki siz diyecek, ebedi olarak azaptasınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 78, 'Andolsun ki size gerçeği gönderdik ve fakat çoğunuz gerçeği hoş görmüyor, istemiyordunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 79, 'Onlar, kafirlikte ısrar ettiler, biz de onları cezalandırmada ısrar edeceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 80, 'Yoksa onların gizlediklerini ve gizligizli konuştuklarını işitmedik mi sanırlar? Hayır ve elçilerimiz, ne dediklerini, ne yaptıklarını yazıp durmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 81, 'De ki: Rahmanın çocuğu olsaydı gerçekten de ben, mabuduma kulluk edenlerin ilki olurdum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 82, 'Yücedir, münezzehtir göklerin ve yeryüzünün Rabbi, arşın Rabbi, onların dediklerinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 83, 'Bırak onları, vaadedilen güne ulaşıncaya dek didinip oynasınlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 84, 'Ve o öyledir ki gökte de mabuttur o, yerde de mabut ve odur hüküm ve hikmet sahibi olan ve her şeyi bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 85, 'Ve yücedir o ki onundur saltanatı ve tedbiri göklerin ve yeryüzünün ve ikisinin arasındakilerin ve onun katındadır kıyametin ne vakit kopacağına ait bilgi ve hep dönüp onun tapısına varacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 86, 'Ve ondan başkalarına tapanlar, şefaate nail olmazlar, ancak gerçeğe tanık olanlar müstesna ve onlar, gerçeği bilirler de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 87, 'Ve andolsun ki onları kim yarattı diye sorsan elbette Allah derler; artık ne diye boş şeylere kapılırlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 88, 'Ve der ki Ya Rabbi: Şüphe yok ki bunlar, inanmayan bir topluluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (43, 89, 'Artık yüzçevir onlardan ve de ki: Esenlik size, yakında bilip anlarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 2, 'Andolsun her şeyi açıklayan Kur''an''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 3, 'Şüphe yok ki biz onu, kutlu bir gecede indirdik, şüphe yok ki biz, insanları korkuturuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 4, 'O gecede ayrılır, takdir edilir her hükmolunan iş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 5, 'Bir iş ki katımızdan hükmolunur, şüphe yok ki biz göndermişizdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 6, 'Rahmet olarak Rabbinden; şüphe yok ki o, duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 7, 'Rabbidir göklerin ve yeryüzünün ve ikisinin arasındakilerin. Adamakıllı inanır, iyice bilirseniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 8, 'Yoktur ondan başka tapacak, diriltir ve öldürür; Rabbinizdir ve Rabbidir gelip geçen atalarınızın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 9, 'Hayır, onlar şüphe içindedir, alay edip dururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 10, 'Artık gözetle gökyüzünden apaçık, gözle görünür bir dumanın geleceği günü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 11, 'Bütün insanlara yayılır, budur elemli azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 12, 'Rabbimiz, bizden azabı, gider, şüphe yok ki inandık biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 13, 'Siz neredesiniz, öğüt alma nerede ve andolsun ki onlara, her şeyi açıklayan bir Peygamber geldi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 14, 'Sonra yüz çevirdiler ondan ve kendisine birşeyler öğretilmiş delinin biri dediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 15, 'Şüphe yok ki birazcık gidereceğiz azabı, fakat gene şüphe yok ki kafirliğe döneceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 16, 'O gün pek şiddetli bir surette tutar, cezalandırırız, şüphe yok ki öc alırız biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 17, 'Ve andolsun ki onlardan önce Firavun''un kavmini de sınamıştık ve onlara güzel huylu bir peygamber gelmişti de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 18, 'Allah''ın kullarını demişti, bana teslim edin, şüphe yok ki ben, emin bir peygamberim size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 19, 'Ve Allah''a karşı yücelik satmaya kalkışmayın; şüphe yok ki ben size, apaçık bir delil getirdim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 20, 'Ve şüphe yok ki ben Rabbime ve Rabbinize sığınırım beni taşlayıp öldürmenizden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 21, 'Bana inanmıyorsanız bırakın tek başıma beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 22, 'Derken Rabbine dua edip şüphe yok ki bunlar demişti, mücrim bir topluluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 23, 'Artık kullarımla geceleyin yola düş, şüphe yok ki ardınızdan geleceklerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 24, 'Deniz açılmışken öylece bırak, şüphe yok, onlar bir ordudur ki boğulacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 25, 'Nice bahçeler terkettiler ve nice akarsular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 26, 'Ve tarlalar ve güzelim meclisler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 27, 'Ve bolbol yeyip geçindikleri nice nimetler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 28, 'Böyle işte ve onları miras verdik bir başka topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 29, 'Derken ne gök ağladı onlara, ne yer ve mühlet de verilmedi onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 30, 'Ve andolsun ki İsrailoğullarını aşağılatıcı bir azaptan kurtardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 31, 'Firavun''dan; şüphe yok ki o haddi aşanlardan yücelik satan, ululanan biriydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 32, 'Ve andolsun ki İsrailoğullarını, bilerek bütün alemlerden üstün olmak üzere seçtik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 33, 'Ve onlara, apaçık nimetleri muhtevi deliller verdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 34, 'Gerçekten de şunlar elbette derler ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 35, 'İlk ölümümüzden başka ölüm yok bize ve biz, tekrar dirilmeyiz de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 36, 'Doğru söylüyorsanız getirin babalarımızı bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 37, 'Bunlar mı daha hayırlıdır, yoksa Tubba'' kavmiyle onlardan öncekiler mi? Helak ettik onları, şüphe yok ki mücrimlerdi onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 38, 'Ve biz gökleri ve yeryüzünü ve ikisinin arasındakileri eğlence için, boşuboşuna yaratmadık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 39, 'Biz onları, ancak gerçek olarak yarattık ve fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 40, 'Ayrılma günü, gerçekten de hepsinin muayyen bir günüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 41, 'O gün dostun dosta faydası olmaz ve onlar, bir yardım da görmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 42, 'Ancak Allah kime acırsa o başka; şüphe yok ki odur üstün ve rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 43, 'Şüphe yok ki zakkum ağacı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 44, 'Suçluların yemeğidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 45, 'Erimiş bakıra, kurşuna benzer, karınlarda kaynar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 46, 'Kaynar su gibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 47, 'Tutun onu da sürüyün koca cehennemin ta ortasına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 48, 'Sonra da dökün kaynar suyu azab olarak tepesine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 49, 'Tat, şüphe yok ki sen üstündün, kerem sahibiydin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 50, 'Gerçekten de buydu şüphe ettiğiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 51, 'Şüphe yok ki çekinenler, emin bir makamdadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 52, 'Cennetlerde ve akarsuların kıyılarında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 53, 'İnce ve kalın ipekliler giyerler, karşıkarşıya otururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 54, 'Böyle işte ve onları evlendiririz iri gözlü hurilerle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 55, 'Orada emin bir halde her çeşit meyvelar isterler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 56, 'İlk ölümden başka ölüm tatmazlar orada ve onları korur koca cehennemin azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 57, 'Rabbinden bir lütuf ve ihsan olarak; budur o büyük kurtuluşun, murada erişin ta kendisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 58, 'Gerçekten de öğüt alsınlar diye Kur''an''ı senin dilinle indirdik, okuyuşunu da kolaylaştırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (44, 59, 'Artık gözetle, bekle; şüphe yok ki onlar da gözetlemedeler, beklemedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 2, 'Bu kitap, üstün ve her şeyi bilen Allah tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 3, 'Şüphe yok ki göklerde ve yeryüzünde deliller var elbet inananlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 4, 'Ve sizin yaratılışınızda ve yürüyen mahlukatı yayışında iyice inanıp anlamış topluluğa deliller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 5, 'Ve geceyle gündüzün, birbiri ardınca gelip gitmesi ve Allah''ın, gökten, rızka ait yağmur yağdırıp da o sayede ölümünden sonra yeryüzünü diriltmesi ve rüzgarı dilediği yerden dilediği yere estirmesi, delillerdir akıl eden topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 6, 'İşte bunlar, Allah''ın ayetleridir ki gerçek olarak okuyoruz sana; Allah''ın sözünden ve delillerinden sonra hangi söze inanırlar ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 7, 'Yazık boyuna yalan söyleyip durmadan suç işleyene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 8, 'Ona okununca Allah''ın ayetlerini dinler de sonra gene hiç duymamış gibi ululanıp ısrar eder; artık müjdele onu elemli bir azapla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 9, 'Ve ayetlerimizden bir şey öğrendi mi onu alaya alır; onlar, öyle kişilerdir ki onlaradır aşağılatıcı azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 10, 'Bulundukları halin ardında da cehennem var ve ne kazandıkları, azaplarından birşeyceğizi defedebilir, ne Allah''ı bırakıp da kabul ettikleri mabutlar ve onlaradır pek büyük bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 11, 'Bu Kur''an, doğru yolu gösterir ve Rablerinin ayetlerini inkar edenlere gelince: Onlaradır elemli ve en çetin azabın cezası.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 12, 'Öyle bir Allah''tır ki üstünde gemi, emriyle kayıp gitsin ve siz de lutfundan, ihsanından nasibinizi arayıp elde edin de şükreyleyin diye ram etmiştir denizi size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 13, 'Ve ram etmiştir size, ne varsa göklerde ve ne varsa yeryüzünde, hepsi de onun rahmetindendir; şüphe yok ki bunda da deliller var düşünen topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 14, 'Îman edenlere de ki: İşlediklerine karşılık ceza vermesi için, Allah''ın günlerinin gelip çatacağını ummayanların suçlarını, şimdilik örtsünler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 15, 'Kim iyilik ederse kendisinedir ve kim kötülükte bulunursa gene kendisine, sonra da dönüp Rabbinizin tapısına varırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 16, 'Ve andolsun ki biz, İsrailoğullarına kitap ve hüküm ve peygamberlik verdik ve onları, temiz şeylerle rızıklandırdık ve alemlere üstün ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 17, 'Ve sonradan olacak işe ait de apaçık deliller gösterdik onlara; derken, o hususta kendilerine bir bilgi geldikten sonradır ki ancak aralarındaki hırs ve haset yüzünden ayrılığa düştüler; şüphe yok ki Rabbin, kıyamet gününde, ayrılığa düştükleri şeyler hakkında, aralarında hüküm verecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 18, 'Sonra seni, dine ait bir şeriata sahip ettik, artık uy ona ve bilmeyenlerin dileklerine uyma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 19, 'Şüphe yok ki onlar, senden Allah''ın azabına ait hiçbir şeyi defedemezler ve şüphe yok ki zulmedenlerin bir kısmı, bir kısmına yardım eder ve Allah''sa, çekinenlerin yardımcısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 20, 'Bu, can gözleridir insanlara ve doğru yolu gösterir ve rahmettir iyideniyiye inanıp anlamış topluluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 21, 'Yoksa kötülük kazananlar, kendilerini de iman edenler ve iyi işlerde bulunanlarla eşit mi tutacağız, dirimleri de, ölümleri de onlarla bir olacak mı sanıyorlar? Ne de kötü hükmediyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 22, 'Ve halketmiştir Allah gökleri ve yeryüzünü gerçek olarak ve herkes, kazancına göre karşılık bulsun diye ve onlara zulmedilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 23, 'Gördün mü dileğini mabud edineni ve halini bildiği halde Allah tarafından sapıklığa terkedileni ve onun kulağını ve kalbini mühürlemiştir ve gözüne de perde çekmiştir; artık Allah''tan sonra kim doğru yolu gösterebilir ona? Hala mı öğüt ve ibret almazsınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 24, 'Ve dediler ki: Yaşayış, ancak bu dünyadaki yaşayışımızdan ibaret, ölürüz ve diriliriz ve bizi zamandan başka bir şey öldürmez ve bu hususta bir bilgileri yoktur onların, yalnız zanna kapılmışlardır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 25, 'Ve onlara apaçık ayetlerimiz okununca kesin delilleri, ancak doğru söylüyorsanız getirin atalarımızı bize demelerinden ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 26, 'De ki: Allah diriltir sizi, sonra öldürür, sonra da şüphe bile olmayan kıyamet günü, toplar sizi ve fakat insanların çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 27, 'Ve Allah''ındır göklerin ve yeryüzünün saltanatı ve tedbiri ve kıyametin koptuğu gün, gerçeği kabul etmeyip boş şeylere kapılanlar, ziyan ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 28, 'Ve görürsün ki her ümmet, diz çökmüş, kendi kitabına çağrılmada. O gün, ne yaptıysanız onun karşılığını bulur, ona göre mücazata ve mükafata erişirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 29, 'Bu kitabımız, size gerçeği söyler; şüphe yok ki biz, ne yaptıysanız hepsini yazdırmışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 30, 'İnanan ve iyi işlerde bulunanları, artık Rableri, rahmetine alır, budur apaçık kurtuluşun, murada erişin ta kendisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 31, 'Ve ama kafir olanlara gelince: Âyetlerim okunmuyor muydu size? Derken ululandınız ve mücrim bir topluluk oldunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 32, 'Ve size, şüphe yok ki Allah''ın vaadi gerçektir ve kıyamette şüphe yoktur dendi mi, kıyamet nedir derdiniz, bilmiyoruz ki, ancak bir zanda bulunmadayız ve biz, iyideniyiye bilmedik, anlamadık ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 33, 'Ve belirir, görünür onlara yaptıkları işlerin kötülükleri ve başlarına gelir alay ettikleri şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 34, 'Ve denir ki: Siz nasıl bugüne kavuşacağınızı unuttuysanız bugün de biz, sizi unuttuk ve yurdunuz ateştir ve size bir yardımcı da yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 35, 'Bu da, Allah ayetlerini alaya almanızdan ve dünya yaşayışının sizi aldatmasından geldi başınıza; artık bugün oradan çıkarılmaz onlar ve özür de istenmez onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 36, 'Artık hamd, göklerin Rabbine ve yeryüzünün Rabbine, alemlerin Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (45, 37, 'Ve onundur ululuk göklerde ve yeryüzünde ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 1, 'Ha mim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 2, 'Bu kitap, üstün ve her şeyi bilen Allah tarafından indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 3, 'Gökleri ve yeryüzünü ancak gerçek olarak ve muayyen bir zaman için yarattık ve kafir olanlarsa korkutuldukları şeylerden yüz çevirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 4, 'De ki: Allah''tan başka taptıklarınız, gösterin bana, ne yarattılar yeryüzünde, yoksa göğü idarede bir ortaklıkları mı var? Doğru söylüyorsanız bundan önceki bir kitabı, yahut bir bilgi eserini getirin bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 5, 'Allah''ı bırakıp da kıyamet günü, kendisine cevap vermeyecek olan ve kendisine tapanlardan haberleri bile bulunmayan şeylere tapandan daha sapık kimdir ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 6, 'Ve insanların toplandığı zaman onlar, düşman kesilirler ve kendilerine tapanların kulluklarını da inkar ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 7, 'Onlara apaçık ayetlerimiz okundu mu gerçeği inkar edenler, gerçek, onlara gelince bu derler, aşikar bir büyü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 8, 'Yoksa bunu, kendisi uyduruyor mu derler? De ki: Ben uyduruyorsam Allah''ın azabından hiçbir şeyi gideremezsiniz benden; o, Kur''an hakkında neler dediğinizi daha iyi bilir; benimle sizin aranızda tanık olarak o yeter ve odur suçları örten, rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 9, 'De ki: İlk gönderilen peygamber değilim ben ve bana ne yapılacağını da bilmem, size ne yapılacağını da; ancak bana vahyedilene uyarım ve ben, apaçık bir korkutucudan başka bir şey de değilim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 10, 'De ki: Ne dersiniz, Allah katındansa ve siz onu inkar ettiyseniz; İsrailoğullarından bir tanık, onun gerçek olup Allah''tan geldiğine tanıklık etti de inandı, halbuki gene de siz ululandınız, kibirinize yediremediniz; şüphe yok ki Allah, zulmeden topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 11, 'Kafir olanlar, inananlara dediler ki: Eğer bir hayır olsaydı onlar, bizi geçemezlerdi ve Kur''an''la doğru yolu bulmadıkları için de diyecekler ki bu, çok eski bir yalan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 12, 'Ve bundan önce de Musa''nın kitabı, uyulan bir kitaptı ve rahmetti ve bu da bir kitaptır ki onu gerçekleştirir, Arap diliyledir, zulmedenleri korkutmak içindir ve müjdedir iyilik edenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 13, 'Şüphesiz, onlar ki Rabbimiz Allah''tır dediler de sonra doğru hareket ettiler, artık onlara ne bir korku vardır, ne de kederlenir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 14, 'Onlardır cennet ehli, ebedi kalırlar orada, yaptıklarına karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 15, 'Ve biz, insana, anasınababasına iyilik etmesini emrettik; anası, onu zahmetle taşımıştır ve zahmetle doğurmuştur ve gebelik müddetiyle sütten kesilme müddeti, otuz ayı tutar; sonunda ergenlik çağına gelmiştir ve kırk yaşına ermiştir de demiştir ki: Rabbim, bana da, anamababama da verdiğin nimetine karşı şükretmeyi nasip ve müyesser et bana ve soyumdan gelenleri de doğru ve düzgün kişiler yap da hoşnut ol benden; şüphe yok ki tövbe ettim sana ve şüphe yok ki teslim olanlardanım, emrine uyanlardanım ben.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 16, 'Öyle kişilerdir onlar ki yaptıklarının en güzelini kabul ederiz ve kötülüklerinden geçeriz, cennet ehlinin içindedir bunlar; dosdoğru bir vaittir ki vaadedilmiştir onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 17, 'Ve öbürü de, anasınababasına, uf sizden, tekrar kabirden çıkacağımı mı söylüyor, buna inanmaya mı çağırıyorsunuz beni? Ve benden önce nice nesiller gelipgeçti demiştir ve onlar da Allah''a yalvarırlar da yazık sana derler, inan, şüphe yok ki Allah''ın vaadi gerçektir, derken o, bu der, eskilerin masallarından başka bir şey değil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 18, 'Bunlar, öyle kişilerdir ki, onlardan önce cinden ve insanlardan gelip geçen ümmetler içinde, onlara da, azaba uğrayacaklarına dair söylenen söz hak olmuştur; şüphe yok ki onlar, ziyana uğramışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 19, 'Ve herkesin, yaptığı işlere göre dereceleri var ve yaptıklarının karşılığını elbette tamamıyla öder ve onlara zulmedilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 20, 'Ve o gün, kafir olanlar, ateşe arzedilirler, dünya yaşayışınızda bütün temiz şeylerinizi kaybettiniz denir ve orada, bunlarla geçinip gitmiştiniz, bugünse, yeryüzünde, haksız yere ululuk sattığınızdan ve buyruktan çıktığınızdan dolayı aşağılanma azabıyla cezalanırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 21, 'Ve an Âd''ın kardeşini, hani kavmini Ahkaaf''ta korkutmuştu ve ondan önce ve ondan sonra gelip geçen korkutucular da, ancak Allah''a kulluk edin diye korkutmuşlardı; o da öyle demiş ve şüphe yok ki ben demişti, o pek büyük günün azabına uğrayacağınızdan korkuyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 22, 'Onlar, sen demişlerdi, bizi mabutlarımızdan vaz geçirmeye mi geldin, doğru söyleyenlerdensen bize vaadettiğini getir başımıza artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 23, 'Demişti ki: Azabın ne vakit geleceğine dair bilgi, ancak Allah katındadır ve ben neyle gönderilmişsem onu tebliğ ediyorum size ve fakat görüyorum ki siz, bilgisiz bir topluluksunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 24, 'O bulutun, vadilerine doğru gelmekte olduğunu görünce bu demişlerdi, bize yağmur getiren bulut. Hayır, o, çarçabuk gelmesini istediğiniz şey, bir yel ki onda elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 25, 'Bir azap var ki Rabbinin emriyle her şeyi mahvedip gider, derken hepsi de helak olup gitti, öyle bir güne erdiler ki evlerinden başka hiçbir şey görülmez oldu. İşte böylece cezalandırırız mücrim topluluğu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 26, 'Ve andolsun ki biz onlara, size vermediğimiz gücükuvveti vermiştik ve onlara kulak, göz ve gönül vermiştik; derken Allah''ın delillerini, bilebile inkar ettikleri zaman onlara gelen azabı, ne kulakları menedebilmişti ve ne gözleri ve ne gönülleri ve alay ettikleri, başlarına gelmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 27, 'Ve andolsun ki çevrenizdeki şehirleri de helak ettik ve tuttukları yoldan dönsünler diye de delilleri tekrartekrar açıklamadayız, bildirmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 28, 'Peki, Allah''ı bırakıp da mabud olarak kabul ettikleri ve Tanrıya yaklaşmak için tapındıkları putlar, ne diye yardım etmedi onlara? Hayır, hatta kaybolup gittiler gözlerinden ve bu, onların yalanıydı ve onların iftirası.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 29, 'An o zamanı ki hani cinlerin bir bölüğünü, Kur''an dinlesinler diye senin bulunduğun tarafa yollamıştık; oraya gelince birbirlerine, susun demişlerdi; okunuşu bitince de korkutmak için kavimlerine dönmüşlerdi de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 30, 'Ey kavmimiz demişlerdi, gerçekten de biz, Musa''dan sonra indirilmiş bir kitap duyduk ki önceki kitapları gerçeklemede, gerçeği ve doğru yolu göstermede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 31, 'Ey kavmimiz, icabet edin Allah''a çağırana ve inanın ona da suçlarınızın bir kısmını örtsün ve sizi korusun elemli azaptan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 32, 'Ve kim icabet etmezse Allah''a çağırana, artık o, yeryüzünde Allah''ı aciz bırakamaz ve ondan başka yardımcılar da yoktur ona; bu çeşit kişilerdir apaçık sapıklığa düşenler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 33, 'Görmezler mi ki şüphe yok, Allah, öyle bir mabuttur ki gökleri ve yeryüzünü yaratmıştır ve onları yaratırken yorulmayanın, aciz kalmayanın, elbette ölüyü de diriltmeye gücü yeter; evet, şüphe yok ki her şeye gücü yeter onun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 34, 'Ve o gün, kafir olanlar, ateşe arz edilirler de bu gerçek değil mi denir, evet derler, andolsun Rabbimize; der ki: İnkar ettiğinizden dolayı artık tadın azabı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (46, 35, 'Artık, peygamberlerden azim ve irade sahipleri nasıl sabrettilerse sen de sabret ve azaba uğramaları için acele etme. Onlara vaadedilen azabı gördükleri gün sanırlar ki dünyada bir günün bir anı kadar kalmışlar; bu, bir tebliğdir, buyruktan çıkan topluluktan başkası helak mı olur?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 1, 'Kafir olanların ve halkı, Allah yolundan çıkaranların, hayır sanarak yaptıklarını boşa çıkarmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 2, 'İnananların ve iyi işlerde bulunanların ve Rablerinden gelen bir gerçek olan ve Muhammed''e indirilen şeylere iman edenlerinse yaptıkları kötülükleri örtmekte, gizlemekte ve hallerini düzene sokmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 3, 'Bu da, şüphe yok ki kafir olanların, boş şeylere uymalarından ve gene şüphe yok ki inananların, Rablerinden gelen gerçeğe uymalarındandır ve işte Allah, insanlara böyle örnekler getirmekte, hallerini böyle anlatmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 4, 'Kafir olanlarla savaşa giriştiniz mi vurun boyunlarını, onları iyice yaralayıp kırdınız, bozguna uğratıp da onlara üst geldiniz mi işe sağlam yapışın, bağlayın sımsıkı tutsakları, ondan sonra da isterseniz öylece salıverirsiniz onları, isterseniz para alır da bırakırsınız savaş ağırlığını atıncaya dek, bu, böyle; ve Allah dileseydi savaşsız da helak ederdi onları ve fakat bir kısmınızı, bir kısmınızla sınamak ister ve Allah yolunda öldürülenlerin yaptıklarını asla boşa çıkarmamaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 5, 'İlerde de onları doğru yola götürmektedir ve hallerini düzene sokmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 6, 'Ve cennete sokar onları ve cenneti, onlara tanıtmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 7, 'Ey inananlar, siz yardım ederseniz Allah''a, o da yardım eder size ve ayaklarınızı diretir, size sebat verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 8, 'Kafir olanlara gelince: Kötülük onlara ve yaptıklarını boşa çıkarmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 9, 'Bu da, Allah''ın indirdiğine hoşlanmadıklarındandır, artık o da, yaptıklarını mahvetmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 10, 'Gezmezler mi yeryüzünde de bakıp görsünler kendilerinden öncekilerin sonunu, Allah helak edivermiştir onları ve kafirlere de bunlara benzer azaplar var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 11, 'Böyle bu, çünkü şüphe yok ki Allah, inananların yardımcısıdır ve şüphe yok ki kafirlerin yardımcısı yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 12, 'Şüphe yok ki Allah, inanan ve iyi işlerde bulunanları kıyılarından ırmaklar akan cennetlere sokar ve kafir olanlarsa geçinip dururlar ve hayvanlar gibi yerler ve ateş, onlara yurt olmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 13, 'Ve nice şehirlerin halkını helak ettik ki onlar, seni çıkardıkları şehirdekilerden daha da güçlü kuvvetliydiler; onlara bir yardım eden bile yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 14, 'Rabbinden, kesin bir delile sahip olan, o kişiye benzer mi ki kötü işi, kendisine bezetilmiştir ve onlar, kendi havalarına, dileklerine uymaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 15, 'Çekinenlere vaadedilen cennet, şöyledir adeta: Orada su ırmakları var, bozulup kokmaz ve süt ırmakları var, lezzetleri bozulmaz ve şarap ırmakları var, içenlere safi lezzet ve bal ırmakları var, süzme ve onlara, orada bütün meyvelerden sunulur ve Rablerinden yarlıganma var; buna nail olan, o kişiye benzer mi ki ateşte ebedidir ve kaynar sularla sulanır da onların bağırsakları parçalanmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 16, 'Ve onlardan seni dinleyenler de var, sonunda yanından çıkınca kendilerine bilgi verilenlere, demin ne söylüyordu o derler; öyle kişilerdir onlar ki Allah, gönüllerini mühürlemiştir onların; onlar, kendi havalarına, dileklerine uymaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 17, 'Ve doğru yolu bulanlara gelince: Onların başarısını arttırmaktadır ve onlara, korunma duygusu vermektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 18, 'Onlar, kıyametin gelmesinden, apansızın başlarına kopuvermesinden başka bir şey mi bekliyorlar? Gerçekten de alametleri geldi; onlara gelip çatınca ibret almaları neye yarar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 19, 'Artık bil ki şüphe yok, Allah''tan başka yoktur tapacak ve kendi suçun ve inanan erkeklerle kadınların suçları için yarlıganma dile ve Allah, sizin dönüp dolaştığınız yeri de, size yurt olacak yeri de bilmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 20, 'Ve inananlar, derler ki: Bir sure indirilseydi; bir hükmü kesin sure indirildi mi ve onda, savaş anıldı mı da gönüllerinde hastalık olanları görürsün ki sana, ölümden baygınlık geçiriyorlarmış gibi baygınbaygın bakarlar; artık ölüm, onlara daha da uymaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 21, 'İtaat etmek ve güzel söz söylemek gerekti, derken işe iyice sarılınca da Allah''ın gerçek söylediğini kabul etselerdi görürlerdi ki bu, kendilerine daha da hayırlı olmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 22, 'Artık iş başına gelir de yeryüzünde bozgunculuk eder; yakınlarınızı kestirip doğratır mısınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 23, 'Öyle kişilerdir onlar ki Allah, lanet etmiştir onlara, onları sağırlaştırmakta ve gözlerini kör etmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 24, 'Ne diye Kur''an''ı, bir iyice düşünüp taşınmazlar, yoksa gönüllerinde kilitler mi var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 25, 'Gerisin geriye, hem de doğru yol, kendilerince apaçık anlaşıldıktan sonra, eski dinlerine dönenlere gelince: Şeytan, yanlış hareketlerini, kendilerine bezemektedir ve onları, uzun uzun dileklere düşürmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 26, 'Bu, böyledir; çünkü onlar, Allah''ın indirdiği şeyden hoşlanmayanlara, biz demişlerdir, bazı işlerde size itaat edeceğiz ve Allah''sa onların gizlice konuştuklarını bilmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 27, 'Nasıl olacak halleri o zaman ki melekler, canlarını alırken yüzlerine, artlarına vurmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 28, 'Bu, böyledir, çünkü onlar, Allah''ın gazap ettiği şeylere uymuşlar ve razılığından hoşlanmamışlardır da o da, yaptıklarını mahvetmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 29, 'Yoksa, gönüllerinde hastalık olanlar, Allah, onların kinlerini, hasetlerini hiç meydana çıkarmayacak mı sanmaktadır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 30, 'Ve dileseydik onları, sana gösterirdik de yüzlerinden tanırdın elbet ve elbette sözlerinden tanırsın, anlarsın onları ve Allah, yaptıklarınızı bilmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 31, 'Ve andolsun ki sizden savaşanları ve sabredenleri bildirmek ve gizlediklerinizi haber vermek için sizi sınamaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 32, 'Kafir olanlar ve halkı, Allah yolundan çıkaranlar ve doğru yol, kendilerince de apaçık olarak anlaşıldıktan sonra Peygambere karşı gelenler, Allah''a hiçbir zarar veremezler ve görürler ki Allah, onların yaptıklarını yakında, mahvetmektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 33, 'Ey inananlar, itaat edin Allah''a ve itaat edin Peygambere ve yaptıklarınızı boşa çıkarmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 34, 'Kafir olanlar ve halkı Allah yolundan çıkaranlar, sonra da kafir olarak ölenler yok mu? Allah, kesin olarak onları yarlıgamamaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 35, 'Artık gevşemeyin ve üstün olduğunuz halde barışa çağırmayın ve Allah, sizinledir ve yaptıklarınızın sevabını, hiç azaltmamaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 36, 'Dünya yaşayışı, ancak bir oyundur, bir eğlence ve inanır ve çekinirseniz göreceksiniz ki size mükafatınızı vermektedir ve bütün mallarınızı istememektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 37, 'Eğer hepsini istese ve zorlasa sizi, nekesliğe kalkışırdınız da görürdünüz ki kinlerinizi, hasetlerinizi meydana çıkarmaktadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (47, 38, 'Bilin ki siz, şunlarsınız: Allah yolunda malınızı, mülkünüzü harcamaya çağrılıyorsunuz da içinizden, nekeslik edenler var ve kim nekeslik ederse ancak kendisine zarar etmiş olur ve Allah, müstağnidir ve sizsiniz yoksullar ve itaatten yüz çevirirseniz yerinize bir başka topluluğu getirir, sonra görürsünüz ki onlar, size benzememektedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 1, 'Şüphe yok ki biz, sana apaçık bir fetih vermişizdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 2, 'Allah, ümmetinin önce yapılan ve sona kalmış olan suçlarını sana bağışlasın ve sana, nimetini tamamlasın ve seni, doğru yola götürsün diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 3, 'Ve sana, üstün bir yardımla yardım etsin diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 4, 'Öyle bir mabuttur ki inançlarına inanç katsın diye inananların gönüllerine, tam bir sükun ve huzur indirmiştir ve Allah''ındır göklerin ve yeryüzünün orduları ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 5, 'Erkek ve kadın, inananları, ebedi olarak kalacakları cennetlere soksun ve kötülüklerini örtsün diye ve bu da, Allah katında pek büyük bir kutluluktur, murada eriştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 6, 'Ve Allah, erkek ve kadın münafıkları ve erkek ve kadın şirk koşanları azaplandırsın diye, kötülük, dönüp başlarına gelesi helak olasılar ve Allah gazap etmiştir onlara ve lanetlemiştir onları ve hazırlamıştır onlara cehennemi ve orası, gidilecek ne de kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 7, 'Ve Allah''ındır göklerin ve yeryüzünün orduları ve Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 8, 'Şüphe yok ki biz seni tanık ve müjdeci ve korkutucu olarak göndermişizdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 9, 'Allah''a ve Peygamberine inansınlar ve onu kuvvetlendirsinler ve ululasınlar ve sabah ve akşam onu noksan sıfatlardan tenzih etsinler diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 10, 'Şüphe yok ki seninle biatlaşanlar, ancak Allah''la biatlaşmışlardır, Allah''ın eli, onların ellerinin üstündedir; artık kim dönerse zararı kendi nefsinedir ve kim Allah''la ahitleştiği şeyde durursa ona, yakında büyük bir ecir verilecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 11, 'Bedevilerden geri kalanlar, diyecekler ki sana: Bizi mallarımız ve çoluğumuz çocuğumuz oyaladı, artık sen, yarlıganma dile bize; gönüllerinde olmayanı dilleriyle söylerler; de ki: Gerçekten de size bir zarar eriştirmek isterse, yahut bir fayda vermek dilerse Allah''tan, herhangi bir suretle ona ait birşeyi kim giderebilir? Hayır; Allah, bütün yaptıklarınızdan haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 12, 'Hatta siz, sandınız ki Peygamber ve inananlar, artık bir daha çoluklarınaçocuklarına dönemeyecekler ve bu zan, gönüllerinizde bezendi ve kötü bir zanna kapıldınız ve hiçbir hayra yaramaz kötü bir topluluk haline geldiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 13, 'Ve kim, Allah''a ve Peygambere inanmazsa bilsin ki gerçekten de biz, kafirlere, yakıp kavuran bir ateştir, hazırlamışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 14, 'Ve Allah''ındır göklerin ve yeryüzünün saltanatı ve tedbiri, dilediğini yarlıgar ve dilediğini azaplandırır ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 15, 'Geri kalanlar, siz ganimetleri almaya giderken bizi de bırakın da derler, biz de size uyalım; onlar, Allah sözünü değiştirmek isterler, de ki: Siz, kesin olarak bize uyamazsınız, Allah da önceden böyle dedi; onlar, diyecekler ki: Hayır, siz bizi kıskanıyorsunuz, bize haset ediyorsunuz; hayır, onlar, anlayışları pek az bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 16, 'Bedevilerden, geride kalanlara de ki: Yakında çok savaşkan ve kuvvetli bir toplulukla savaşa çağrılacaksınız; onlarla sonuna dek savaşacaksınız, yahut da Müslüman olacak onlar; artık itaat ederseniz Allah, size güzelim bir mükafat verir ve fakat evvelce döndüğünüz gibi gene dönerseniz sizi elemli bir azapla azaplandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 17, 'Köre vebal yok ve topala vebal yok ve hastaya vebal yok ve kim, Allah''a ve Peygamberine itaat ederse onu, kıyılarından ırmaklar akan cennetlere sokar ve kim, yüz çevirirse onu elemli bir azapla azaplandırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 18, 'Ve andolsun ki Allah, ağaç altında, seninle biatleştikleri zaman, inananlardan razı olmuştur da onlara sükun ve huzur indirmiştir ve onlara pek yakın bir fethi mükafat olarak da vermiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 19, 'Ve elde edecekleri birçok ganimetleri ihsan etmiştir ve Allah, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 20, 'Ve Allah, size, elde edeceğiniz birçok ganimetler vaadetmiştir ve bunu çabuklamıştır ve inananlara bir delil olsun ve size, doğru yolda başarı versin diye de insanların ellerini, sizden çekmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 21, 'Ve daha başka ganimetler de vaadetmiştir ki siz, henüz onları elde edemezsiniz, andolsun ki Allah, bilgisiyle onları kavrayıp kuşatmıştır ve Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 22, 'Kafirler, sizinle savaşa girişirlerse mutlaka arkalarını dönerler de sonra bir dost da bulamazlar, bir yardımcı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 23, 'Allah''ın, önceden de olup bitegelen yoluyoradamıdır bu ve Allah''ın yoluyoradamı, hiç mi hiç değişmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 24, 'Ve o, bir mabuttur ki, onlara karşı zafer kazandınız da ondan sonra Mekke vadisinde onların ellerini sizden çekti, sizin ellerinizi de onlardan ve Allah, ne yaparsanız hepsini görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 25, 'Onlar, kafir olan ve sizi Mescidi Haram''dan meneden ve kurbanlarınızı, yerlerine ulaştırmayan kişilerdi ve Mekke''de, sizin bilmediğiniz ve bilgisizlik yüzünden çiğneyip geçeceğiniz ve bu yüzden de günaha gireceğiniz inanmış erkekler ve inanmış kadınlar olmasaydı sizi Mekke''ye sokardı, fakat Allah, dilediğini rahmetine ithal etsin diye, onlardan ellerinizi çekti sizin; birbirlerinden seçilip ayrılmış olsalardı, onlardan kafir olanları elbette elemli bir azapla azaplandırırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 26, 'O sırada, kafir olanların yüreklerinde coşup kabaran gayret ve kızgınlık, cahiliyet devrine ait bir gayret ve kızgınlıktı; derken Allah, Peygamberine ve inananlara sükun ve huzur verdi ve onlara, çekinme sözünü gerekli kıldı ve bu, Tanrının birliğini bildiren söze de zaten onlar, daha layıktı ve o sözün ehliydi onlar ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 27, 'Ve andolsun ki Allah, Peygamberine gerçek bir rüya göstermiştir; Allah dilerse emin olarak ve başlarınızı tıraş ettirerek, saçlarınızı kestirip kısaltarak elbette sizi Mescidi Haram''a sokacak; gerçekten de o, sizin bilmediğinizi bilmektedir, derken bundan başka da yakın bir fetih ve zafer gerçektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 28, 'Öyle bir mabuttur o ki Peygamberini, doğru yolu göstermek üzere gerçek dinle, bütün dinlere üstün olmak için göndermiştir ve Allah''ın tanıklığı yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (48, 29, 'Muhammed, Allah''ın peygamberidir ve onunla beraber bulunanlar, kafirlere karşı çetindirler, kendi aralarında merhametli, onları görürsün ki rüku etmekteler, secdeye kapanmaktalar Allah''tan lütuf ve ihsan ve razılık dileyerek; yüzlerinde, secde eserinin alametleri görünmededir ve onların bu vasıfları, Tevrat''ta da vardır ve onlara ait bu vasıflar, İncil''de de var; adeta ekilmiş bir taneye benzer ki filiz vermiştir, derken filizi kuvvetlenmiştir, derken kalınlaşmıştır da dümdüz boy vermiştir, gövdelerine dayanıp yücelmiştir; ekincileri şaşırtır, sevindirir, kafirleri, bununla kızdırıp yerindirmek için. Allah, inananlara ve iyi işlerde bulunanlara yarlıganma ve pek büyük bir mükafat vaad etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 1, 'Ey inananlar, her hususta Allah''ın ve Peygamberinin huzurunda, onların önüne geçmeyin ve çekinin Allah''tan; şüphe yok ki Allah, her şeyi duyar, bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 2, 'Ey inananlar, seslerinizi, Peygamberin sesinden daha üstün bir tarzda yükseltmeyin ve onunla, yüksek sesle konuşmayın, birbirinizle konuştuğunuz gibi, sonra yaptıklarınız mahvolup gider de anlamazsınız bile.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 3, 'Allah''ın Peygamberinin yanında seslerini alçaltanlar, o kişilerdir ki Allah, onların gönüllerini, çekinmeyle sınamıştır; onlaradır yarlıganma ve pek büyük bir mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 4, 'Odaların ardından bağırarak sana seslenenlerin çoğu, akıl etmeyen kişilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 5, 'Ve gerçekten de onlar, sabretselerdi de sen, çıkıp yanlarına gelseydin daha da hayırlıydı onlara ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 6, 'Ey inananlar, buyruktan çıkmış biri, size bir haber getirdi mi doğru, yahut yanlış veya yalan olup olmadığını araştırıp iyice bir anlayın, yoksa bir topluluğa, bilgisizlikle bir kötülükte bulunur da yaptığınıza nadim oluverirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 7, 'Ve bilin ki içinizde Allah''ın Peygamberi var; işlerin çoğunda size itaat etseydi günaha girer, helak olurdunuz ve fakat Allah, size inancı sevdirdi ve gönüllerinizde bezedi onu ve çirkin gösterdi size kafirliği ve buyruktan çıkmayı ve isyanı; işte onlardır en güzel işlerde başarı kazananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 8, 'Allah''tan bir lütuf ve bir nimet olarak ve Allah, her şeyi bilir, hüküm sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 9, 'İnananlardan iki kısım, birbiriyle savaşa girişirse hemen aralarını bulun, bir bölüğü, öbürüne saldırırsa o saldırganlarla, Allah''ın emrine itaat edinceye dek savaşın; Allah''ın emrine itaat ederlerse adaletle aralarını bulup barıştırın ve adaletle muamele edin; şüphe yok ki Allah, adaletle muamele edenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 10, 'Hiç şüphe yok ki inananlar, ancak kardeştirler, artık kardeşlerinizin arasını bulun, barıştırın, uzlaştırın onları ve çekinin Allah''tan da acınmışlardan olun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 11, 'Ey inananlar, içinizden bir topluluk, başka bir toplulukla alay etmesin, olabilir ki alay edilenler, öbürlerinden daha hayırlıdır ve kadınların bir kısmı da başka kadınlarla alay etmesin, olabilir ki alay edilen kadınlar, öbürlerinden daha hayırlıdır ve birbirinizi kınamayın ve kötü lakaplarla çağırmayın; inançtan sonra buyruktan çıkmışlara ait adlar, ne de kötüdür ve kim tövbe etmezse artık onlar, zulmedenlerin ta kendileridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 12, 'Ey inananlar, sakının fazla şüphe etmekten, şüphe yok ki bazı zan ve şüpheler suçtur ve ayıplarınızı, gizli işleri arayıp gözetmeyin ve bir kısmınız, bir kısmınızın gıyabında kötülüğünü de söylemesin; biriniz, ölü kardeşinin etini yemeyi sever mi? Tiksindiniz, değil mi? Ve çekinin Allah''tan, şüphe yok ki Allah, tövbeleri kabul eder, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 13, 'Ey insanlar, şüphe yok ki biz sizi bir erkekle bir dişiden yarattık ve sizi, aşiretler ve kabileler haline getirdik tanışın diye; şüphe yok ki Allah katında sevabı en çok ve derecesi en yüce olanınız, en fazla çekineninizdir; şüphe yok ki Allah, her şeyi bilir, her şeyden haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 14, 'Bedeviler, inandık dediler; de ki: İnanmadınız ve fakat Müslüman olduk deyin ve inanç, henüz gönüllerinize girmedi sizin ve Allah''a ve Peygamberine itaat ederseniz yaptığınız iyiliklerin sevabından hiçbir şey eksilmez, şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 15, 'İnananlar, ancak o kişilerdir ki Allah''a ve Peygamberine inanırlar da sonra şüpheye düşmezler ve mallarıyla ve canlarıyla savaşırlar Allah yolunda, işte onlardır doğru söyleyenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 16, 'De ki: Dininizi, Allah''a mı bildireceksiniz? Ve Allah bilir ne varsa göklerde ve ne varsa yeryüzünde ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 17, 'Müslüman olduk diye seni minnet altında mı bırakırlar? De ki: Müslümanlığınızdan dolayı beni minnet altında bırakmaya kalkışmayın, hayır, Allah''a karşı siz minnet altındasınız, sizi doğru yola sevkedip imanda başarı verdiğinden, eğer doğru söylüyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (49, 18, 'Şüphe yok ki Allah, göklerin ve yeryüzünün gizli şeylerini bilir ve Allah, bütün yaptıklarınızı görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 1, 'Kaaf, andolsun büyük ve şerefli Kur''an''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 2, 'Hayır, onlar, içlerinden bir korkutucunun gelmesine şaşıp kaldılar da kafirler, gerçekten de dediler, bu şaşılacak bir şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 3, 'Ölüp bir yığın toprak olduktan sonra mı? Bu, pek uzak, pek olmayacak bir dönüş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 4, 'Gerçekten de yeryüzü, onlardan neyi eksiltir, biliriz biz ve katımızdadır her şeyi koruyan ve zapteden kitap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 5, 'Hayır, gerçek olan Kur''an, onlara gelince yalanladılar da şimdi darmadağın bir işe daldılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 6, 'Bakmazlar mı üstlerindeki göğe? Nasıl kurduk onu ve bezedik ve bir yarığı, yırtığı da yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 7, 'Ve yeryüzünü nasıl yaydık ve oraya metin dağlar koyduk ve orada, gözler, gönüller açan güzelim nebatları çifterçiftter bitirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 8, 'Mabuduna dönen her kulun, can gözünü açmak ve ona, ibret ve öğüt vermek için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 9, 'Ve gökten de kutlu bir yağmur yağdırmadayız da o sayede bağlar, bahçeler ve biçilecek taneler, yeşertip bitirmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 10, 'Ve hurma ağaçları ki boy atıp uzar ve meyveleri, birbirine bitişmiş, adeta istiflenmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 11, 'Kullara rızık olarak ve o yağmurla ölü şehri diriltiriz, işte kabirden çıkış da böyledir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 12, 'Onlardan önce Nuh kavmi ve Ashabı Ress ve Semud kavmi de yalanlamışlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 13, 'Ve Âd ve Firavun kavimleri ve Lut''un kardeşleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 14, 'Ve Ashabı Eyke ve Tubba'' kavmi; hepsi de peygamberleri yalanlamışlardı da helak olmayı hak ettiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 15, 'İlk yaratışta aciz mi kaldık ki? Hayır; ama onlar, yeni bir yaratışta şüphe içindeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 16, 'Ve andolsun ki biz insanı yarattık ve nefsi, onu ne gibi vesveselere düşürür, biliriz ve biz, ona, şah damarından daha yakınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 17, 'Ne söyler, ne yaparsa yazan iki melek var, biri sağda oturmuş, biri solda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 18, 'Hiçbir söz söylemez ki yanında, onu zapteden, gözetip kollayan biri bulunmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 19, 'Ölüm baygınlığı, gerçek olarak gelip çattı mı buydu işte denir, senin kaçıp durduğun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 20, 'Ve üfürülür su''ra, işte bu gündür azap günü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 21, 'Ve herkes, yanında bir sürüp götüren ve bir tanık olarak gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 22, 'Andolsun ki gafletteydin bundan, derken perdeyi kaldırdık gözünden, artık gözün keskin bugün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 23, 'Arkadaşı olan melek, der ki: İşte, ne yaptıysa hepsi bende, hepsi hazır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 24, 'Artık atın cehenneme adamakıllı kafir olan ve gerçeğe karşı inat eden herkesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 25, 'Hayrı tamamıyla meneden zalim şüpheciyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 26, 'Ki Allah''la beraber bir başka mabut da kabul etmiştir, atın artık onu çetin azaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 27, 'Arkadaşı, Rabbimiz der, onu, taşkınlığa ben sevketmedim ve fakat o, pek uzak bir sapıklık içindeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 28, 'Der ki: Huzurumda çekişmeyin ve ben, önceden azap edeceğimi bildirmiştim size.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 29, 'Katımda söz değiştirilemez ve ben, kullara zulmetmem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 30, 'O gün deriz cehenneme: Doldun mu? Ve der ki: Daha yok mu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 31, 'Ve yaklaştırılır cennet, çekinenlere ve onlardan uzak değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 32, 'İşte denecek, size, mabuduna tövbe eden, emri, iyideniyiye koruyan herkese vaadedilen bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 33, 'Görmediği halde rahmandan korkan ve ona yönelmiş bir yürekle gelen kişiye vaadedilen bu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 34, 'Esenlikle girin oraya; bugün, ebedilik günü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 35, 'Onlaradır ne dilerlerse orada ve katımızda daha da fazlası var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 36, 'Ve nice nesiller helak ettik onlardan önce; onlar, bunlardan daha çokluktu, daha güçlü kuvvetliydi, derken şehirleri delikdeşik etmişlerdi, her tarafı ellerine geçirmişlerdi, fakat bir kaçacak yer mi var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 37, 'Şüphe yok ki bunda, gönlü olana, yahut görerek kulak verene ibret ve öğüt var elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 38, 'Ve andolsun ki biz, gökleri ve yeryüzünü altı günde yarattık ve bir yorgunluk gelmedi bize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 39, 'Artık sabret ne derlerse ve Rabbine ham ederek onu tenzih et güneş doğmadan önce ve batmadan önce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 40, 'Ve geceleyin ve secdelerden sonra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 41, 'Ve dinle o nida edenin, yakın bir yerden bağıracağı gün, sesini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 42, 'O gün, o bağrışı, gerçek olarak işitecekler; işte o gündür kabirlerden çıkış günü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 43, 'Şüphe yok ki biz diriltiriz ve biz öldürürüz ve dönülüp gelinecek tapı, bizim tapımızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 44, 'O gün yarılır yeryüzü de çıkarlar oradan ve hızlıhızlı koşarlar; bu toplayış, bize pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (50, 45, 'Biz daha iyi biliriz ne dediklerini ve senin, onlara, dilediğini yapacak bir kudretin yok, artık, azaptan korkana Kur''an''la öğüt ver.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 1, 'Andolsun tozutup savuranlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 2, 'Derken ağır bir yük yüklenenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 3, 'Derken kolayca akıp gidenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 4, 'Derken işi ayıranlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 5, 'Gerçekten de size vaadedilen, doğrudur ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 6, 'Ve ceza, mutlaka olacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 7, 'Andolsun yolyol hareli göğe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 8, 'Şüphe yok ki siz, elbette çeşitli ve birbirini tutmaz sözler söylemektesiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 9, 'Ondan saptırılan, saptırılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 10, 'Lanet olsun geberesi yalancılara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 11, 'Ki onlar, daldıkları gaflette habersiz bir halde bocalayıp dururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 12, 'Sorarlar: Ne zaman gelecek ceza günü?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 13, 'O gün onlar, ateşe atılıp sınanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 14, 'Tadın azabınızı; işte buydu çabucak gelmesini istediğiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 15, 'Şüphe yok ki çekinenler, cennetlerdedir, pınar başlarında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 16, 'Alırlar Rablerinin, kendilerine verdiklerini; şüphe yok ki onlar, bundan önce, iyilik ederlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 17, 'Gecelerin az bir kısmında uyurlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 18, 'Ve seher çağları, yarlıganma dilerlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 19, 'Ve mallarında, dileyene ve mahrum olana bir hak vardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 20, 'Ve yeryüzünde deliller var iyideniyiye inanmış olanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 21, 'Ve kendi özünüzde de, hala mı görmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 22, 'Ve gökte de rızkınız ve size vaadedilen var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 23, 'Gerçekten de andolsun göğün ve yeryüzünün Rabbine ki hiç şüphe yok, gerçektir o, nasıl siz konuşup söylüyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 24, 'İbrahim''in, ağırlanan konuklarına ait haber, geldi mi sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 25, 'Hani, tapısına girmişlerdi de esenlik sana demişlerdi; o da esenlik size demişti, ey yabancılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 26, 'Derken bir bahaneyle ailesinin yanına gitmişti de bir semiz dana getirmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 27, 'Onların önüne koymuştu da yemez misiniz demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 28, 'Derken onlardan, içine bir korkudur düşmüştü de korkma demişlerdi, ve ona, bilgi sahibi bir oğlu olacağını müjdelemişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 29, 'Derken karısı, onlara dönmüştü de bir çığlık atıp eliyle yüzüne vurmuştu ve ben kısır bir kocakarıyım demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 30, 'Onlar, bu, böyle dediler, Rabbin böyle dedi; şüphe yok ki o, bir hüküm ve hikmet sahibidir ki her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 31, 'İbrahim, işiniz nedir ey elçiler demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 32, 'Onlar, şüphe yok ki biz demişlerdi, mücrim bir topluluğa gönderildik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 33, 'Üstlerine balçıktan taşlar yağdırmak için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 34, 'Öyle taşlar ki Rabbinin katında damgalanmış, haddi aşanlar için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 35, 'Derken, orada inananlardan kim varsa çıkarmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 36, 'Gerçekten de bir ev halkından başka Müslüman da bulamamıştık orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 37, 'Ve orada, elemli azaptan korkanlara bir delil bırakmıştık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 38, 'Ve Musa''da da; hani onu apaçık bir delille Firavun''a göndermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 39, 'Derken bütün kuvvetiyle dönmüştü de ya büyücü demişti, yahut da deli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 40, 'Derken onu ve ordusunu helak etmiş, onları denize atıvermiştik de o kendisini kınayıp durmadaydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 41, 'Âd kavminde de bir delil var; hani onlara, her şeyi kasıp kavuran bir fırtına göndermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 42, 'Nereden geçmiş, neye dokunmuşsa orasını ve o şeyi çürümüş kemiğe döndürmüştü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 43, 'Ve Semud''da da delil var; hani, muayyen bir zamanadek geçinin demiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 44, 'Derken Rablerinin emrine karşı azgınlıkta bulunmuşlardı da onları bir yıldırımdır, gelip helak edivermişti ve onlar da bakıp duruyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 45, 'Derken ne ayakta durmıya güçleri kalmıştı, ne de bir yardım görmüşlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 46, 'Ve daha önce de Nuh kavmi ki şüphe yok, onlar, buyruktan çıkmış bir topluluktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 47, 'Ve biz, gökleri kurduk kudretle, onlardan daha üstününü, daha büyüğünü kurmaya da gücümüz yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 48, 'Ve yeryüzünü yayıp döşedik, daha da güzel döşeriz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 49, 'Ve anar, ibret alırsınız diye her şeyi çift yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 50, 'Artık kaçın Allah''a, şüphe yok ki ben size, onun tarafından, apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 51, 'Ve Allah''la beraber bir başka mabut kabul etmeyin; şüphe yok ki ben size, onun tarafından, apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 52, 'Böylece onlardan önce de hiçbir peygamber gelmedi ki ona büyücü, yahut da deli demesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 53, 'Onlar, bunu birbirlerine tavsiye mi ettiler? Hayır, onlar, azgın bir topluluktu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 54, 'Artık yüz çevir onlardan, bundan dolayı da kınanmazsın sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 55, 'Ve öğüt ver, gerçekten de öğüt, inananlara fayda verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 56, 'Ve ben, cinleri ve insanları, ancak bana kulluk etsinler diye yarattım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 57, 'Onlardan ne bir rızık istiyorum ve ne beni doyurmalarını istiyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 58, 'Şüphe yok ki Allah''tır rızık veren kuvvet sahibi ve kuvvetine aciz gelmesi mümkün olmayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 59, 'Kendilerine zulmedenlere, arkadaşlarının payı, gibi bir azap payı var, artık acele etmesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (51, 60, 'Yazık kafirlere, kendilerine vaadedilen günden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 1, 'Andolsun Tur''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 2, 'Ve yazılmış kitaba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 3, 'Yayılmış kağıtta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 4, 'Ve mamur eve.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 5, 'Ve yüceltilmiş tavana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 6, 'Ve taşkın, coşkun, dalgalanıp duran denize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 7, 'Şüphe yok ki Rabbinin azabı, yerine gelip olacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 8, 'Onu bir defedip gideren bulunmayacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 9, 'O gün gök, bir çalkantıya düşüp döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 10, 'Ve dağlar, yerlerinden oynayıp yürür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 11, 'Artık yazıklar olsun o gün yalanlayanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 12, 'Öyle kişilerdir onlar ki daldıkları batakta oynayıp dururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 13, 'O gün itilip kakılarak cehenneme atılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 14, 'İşte budur yalanladığınız ateş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 15, 'Bir büyü mü bu, yoksa görmüyor musunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 16, 'Girin ona da artık sabredin, yahut etmeyin, birdir size; ancak yaptığınızın karşılığı olarak cezalanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 17, 'Şüphe yok ki çekinenler, cennetlerdedir ve nimetler içinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 18, 'Nimetlenirler orada Rablerinin verdiği nimetlerle ve Rableri korur onları koca cehennemin azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 19, 'Yiyin ve için, afiyetler olsun, yaptığınız şeylere karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 20, 'Safsaf dizilmiş tahtlara dayanarak ve onları, iri gözlü hurilerle evlendiririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 21, 'Ve inananlarla soylarından, inanarak onlara uyanları, soylarından gelenlerle birleştirir, buluştururuz ve yaptıklarının mükafatından hiçbir şeyi eksiltmeyiz; herkes, kazancına bağlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 22, 'Ve onlara meyve ve gönüllerinin tam istediği et vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 23, 'Ve birbirlerine öyle bir kadeh sunarlar ki içtikleri şaRabın sonucunda ne boş şeylerden bahsediş var, ne günaha giriş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 24, 'Ve öylesine genç hizmetçiler, etraflarında dönerdurur ki sanki onlar, haznelerde saklanmış inciler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 25, 'Ve birbirlerine dönüp sorarlar, konuşurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 26, 'Derler ki: Gerçekten de daha önce ehlimizin içinde, ilimizde, yurdumuzda, korku içindeydik biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 27, 'Derken Allah lutfetti bize ve korudu bizi ta iliklere işleyen sam yelinin azabından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 28, 'Gerçekten de önceden onu çağırırdık; şüphe yok ki o, şanı yüce bir lütuf sahibidir, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 29, 'Artık öğüt ver, gerçekten de Rabbinin nimeti sayesinde sen, ne kahinsin, ne deli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 30, 'Yoksa onlar, bir şair ki ölmesini, zamanın kötülüklerine uğramasını gözetiyoruz mu diyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 31, 'De ki: Gözetin bakalım, gerçekten ben de sizinle beraber gözetmedeyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 32, 'Yoksa bu sözleri akılları mı emrediyor onlara, yoksa azgın bir topluluk mu onlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 33, 'Yoksa onu kendisi uyduruyor mu diyorlar? Hayır, inanmamışlardır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 34, 'Artık buna benzer bir söz getirin meydana sözünüz doğruysa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 35, 'Yoksa boşuboşuna mı yaratıldı onlar, yoksa onlar mı yaratıcılar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 36, 'Yoksa gökleri ve yeryüzünü mü yarattı onlar? Hayır, iyideniyiye inanmamışlardır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 37, 'Yoksa onların yanında mı Rabbinin hazneleri, yoksa onlar sorumsuz bir saltanata mı sahip?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 38, 'Yoksa merdivenleri var da gökten mi duyuyorlar? Öyleyse duyanları, apaçık bir delil göstersin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 39, 'Yoksa kızlar onların da erkek evlatları sizin mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 40, 'Yoksa onlardan ücret istiyorsun da bu yüzden ağır bir borca mı giriyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 41, 'Yoksa gizli şey, yanlarında da yazıyorlar mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 42, 'Yoksa bir düzen mi kurmak istiyorlar? Asıl düzene uğrayıp cezalanacaklar, kafir olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 43, 'Yoksa Allah''tan başka bir mabutları mı var? Şanı yücedir, münezzehtir Allah, şirk koşanların şirk koştukları şeylerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 44, 'Gökten bir parçanın düştüğünü görseler, birbiri üstüne yığılmış bulut derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 45, 'Artık bırak onları helak olacakları güne dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 46, 'Bir gündür o gün ki düzenleri, onlardan hiçbir şeyi gideremez ve onlara yardım da edilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 47, 'Ve şüphe yok ki zulmedenlere, bundan başka azap da var ve fakat çoğu bilmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 48, 'Ve sabret Rabbinin hükmüne, gerçekten de gözümüzün altındasın sen ve Rabbine hamdederek tenzih et onu kalkınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (52, 49, 'Ve geceleyin de onu tenzih et ve yıldızların batacağı sırada da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 1, 'Andolsun yıldıza, inerken.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 2, 'Arkadaşınız, gerçekten ne saptı, ne ayrıldı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 3, 'Ve kendi dileğiyle söz de söylemedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 4, 'Sözü, ancak vahyedilen şeyden ibaret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 5, 'Ona öğretti kuvvetleri çok çetin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 6, 'Kuvvetli biri; sonra doğruldu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 7, 'Ve o, en yüce tanyerindeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 8, 'Sonra yaklaştı, yakınlaştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 9, 'İki yay kadar kaldı araları, yahut daha da yakın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 10, 'Derken kuluna vahyetti, ne vahyettiyse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 11, 'Gönlü, gördüğünü yalanlamadı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 12, 'Hala münakaşa mı edersiniz gördüğü şeyleri?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 13, 'Ve andolsun ki onu, inerken bir kere daha gördü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 14, 'En son sidrenin yanında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 15, 'Mev''a cenneti de yanındaydı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 16, 'Sidreyi, o sırada neler bürümüş, kaplamıştı, neler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 17, 'Gözü, ne kaydı, ne haddini aştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 18, 'Andolsun ki Rabbinin pek büyük delillerinden bir kısmını gördü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 19, 'Siz de gördünüz mü, Lat''ı ve Uzza''yı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 20, 'Ve üçüncü öbür putu, Menat''ı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 21, 'Erkek evlatlar sizin de kızlar onun mu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 22, 'Bu, pek insafsızca bir pay şimdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 23, 'Bunlar, ancak sizin taktığınız, atalarınızın taktığı adlardan başka bir şey değil, Allah, onlara ait kesin bir delil indirmemiştir, ancak zanna ve nefislerinin dileğine kapılmıştır onlar ve andolsun ki Rablerinden doğru yolu gösteren de gelmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 24, 'Yoksa insan, her umduğunu elde eder mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 25, 'Gerçekten de ahiret de Allah''ındır, dünya da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 26, 'Ve göklerde nice melekler vardır ki Allah, dilediğine ve razı olduğuna şefaat etmeleri için izin vermedikçe şefaatleri, hiçbir şeye yaramaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 27, 'Şüphe yok ki ahirete inanmayanlar, meleklere dişi adları takıp duruyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 28, 'Onların, bu hususta hiçbir bilgisi yok, ancak zanna kapılıyorlar ve şüphe yok ki zan, gerçeğe karşı hiçbir şeye yaramaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 29, 'Artık yüz çevir, bizi anmadan yüz çevirenden ve ancak dünya yaşayışını isteyenden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 30, 'İşte bilgide ulaşabildikleri şey bu; şüphe yok ki Rabbin, kendi yolundan çıkıp sapanı daha iyi bilir ve odur doğru yola gireni daha iyi bilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 31, 'Ve Allah''ındır ne varsa göklerde ve ne varsa yeryüzünde kötülük edenleri, yaptıklarına karşılık elbette cezalandırır ve iyilik edenlereyse yaptıklarından daha da iyi mükafat verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 32, 'Israr etmemek şartıyle küçük günahlardan başka suçların büyüklerinden ve çirkin şeylerden sakınanlara gelince: Şüphe yok ki Rabbinin yarlıgaması pek geniştir. O, sizi yeryüzünden yaratıp meydana getirdiği zaman ve siz, analarınızın karnında birer dölken de bilir; artık siz, kendinizi temize çıkarmaya kalkışmayın, o, kim çekinmededir, daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 33, 'Gördün mü artık yüz çevireni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 34, 'Ve az bir şey verip sonra kısanı, nekeslik edeni?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 35, 'Gizli şeylere ait bilgi, onun katında mı da görmede.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 36, 'Yoksa Musa''nın sahifelerindeki şey bildirilmedi mi ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 37, 'Ve İbrahim''in sahifelerindeki, o İbrahim ki ahdine iyiden iyiye vefa etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 38, 'Hiçbir suçlu, bir başkasının suçunu yüklenemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 39, 'Ve gerçekten de insan, ancak çalıştığını elde eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 40, 'Ve şüphe yok ki çalıştığının karşılığı da gösterilir ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 41, 'Sonra da ona, en değerli mükafat verilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 42, 'Ve şüphe yok ki son varılacak tapı, Rabbinin tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 43, 'Ve şüphe yok ki odur adamakıllı güldüren ve ağlatan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 44, 'Ve şüphe yok ki odur öldüren ve dirilten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 45, 'Ve şüphe yok ki o halk etmiştir erkeği ve dişiyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 46, 'Bir katre sudan, o suyu çıkardığı zaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 47, 'Ve şüphe yok ki ikinci defa yaratış da ona aittir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 48, 'Ve şüphe yok ki odur zengin eden ve sermaye veren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 49, 'Ve şüphe yok ki odur Şi''ra yıldızının Rabbi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 50, 'Ve şüphe yok ki odur önceden gelip geçen Âd''ı helak eden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 51, 'Ve Semud''u da bırakmayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 52, 'Ve onlardan önceki Nuh kavmini de; şüphe yok ki onlar, daha da zalimdi ve daha da azgın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 53, 'Lut kavminin şehirlerini de altüst edip yerle yeksan etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 54, 'Derken o şehirleri, örten örttü gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 55, 'Artık Rabbinin hangi nimetinden şüphe etmedesin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 56, 'Bu Peygamber, gelip geçen korkutuculardan bir korkutucu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 57, 'Yaklaşacak, yaklaştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 58, 'Allah''tan başkası, çeviremez onu geri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 59, 'Bu söze mi şaştınız siz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 60, 'Ve gülüyorsunuz ve ağlamıyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 61, 'Ve siz oyalanıyorsunuz, gaflet ediyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (53, 62, 'Artık secde edin Allah''a ve kullukta bulunun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 1, 'Yaklaştı kıyamet ve yarıldı ay.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 2, 'Ve onlar, bir delil gördüler mi yüz çevirirler de sürüp giden bir büyü derler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 3, 'Ve yalanlarlar ve dileklerine uyarlar ve her iş, kararlaştırılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 4, 'Ve andolsun, öyle haberler geldi onlara ki o haberlerde onları vazgeçirecek, onlara öğüt verecek şeyler vardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 5, 'Yüksek hikmet vardı, derken korkutuşlar fayda vermedi gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 6, 'Artık yüz çevir onlardan; o gün çağıran, hoşlanılmayan birşeye çağırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 7, 'Gözleri yerde, kabirlerden çıkarlar, sanki onlar, dağılmış çekirgelerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 8, 'Yönelirler çağırana; kafirler, bugün derler, ne de zorlu gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 9, 'Onlardan önce Nuh kavmi de kulumuzu yalanlamıştı ve delil dediler ona, pek fena incittiler onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 10, 'Derken Rabbine dua etti: Şüphe yok ki altoldum ben, artık sen yardım et bana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 11, 'Derken açtık göklerin kapılarını da şarıl şarıl ardı gelmez yağmurlar yağdırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 12, 'Ve yerden de sular fışkırttık, derken sular, mukadder bir emre göre birleşti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 13, 'Ve onu, tahtalardan yapılmış ve mıhlarla kenetlenmiş bir gemide taşıdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 14, 'Gözümüzün önünde akıp giderdi; bir mükafattı nankörlük görene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 15, 'Ve andolsun ki bir delil olarak bıraktık onu, fakat bir ibret alan mı var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 16, 'Derken nasıldı azabım benim ve korkutuşlarım?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 17, 'Ve andolsun öğüt ve ibret için Kur''an''ı kolaylaştırdık, fakat bir ibret alan mı var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 18, 'Âd da yalanlamıştı, derken nasıldı azabım benim ve korkutuşlarım?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 19, 'Şüphe yok ki sürüp giden uğursuz bir günde onlara bir kasırgadır yolladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 20, 'Onları kökünden koparmadaydı, sanki köklerinden kopup baş aşağı devrilen hurma kütükleriydi onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 21, 'Derken nasıldı azabım benim ve korkutuşlarım?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 22, 'Ve andolsun ki öğüt ve ibret için Kur''an''ı kolaylaştırdık, fakat bir ibret alan mı var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 23, 'Semud da korkutucuları yalanladı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 24, 'Derken bizden bir adama mı uyacağız dediler, gerçekten de o zaman elbette sapıklığa düşeriz, ateşlere yanarkavruluruz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 25, 'Vahiy, içimizden gelegele ona mı geliyor? Hayır, o, yalancı kendini beğenmiş birisi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 26, 'Yarın bilirler kimmiş yalancı kendini beğenmiş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 27, 'Şüphe yok ki onları sınamak için dişi deveyi gönderiyoruz, artık gözetle onları ve dayan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 28, 'Ve haber ver onlara, su, aralarında paylaştırılmıştır, her bölük, nöbetinde hazır olur, su alır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 29, 'Derken arkadaşlarına seslendiler, derken kılıcını çekti de devenin ayaklarını kesti, öldürdü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 30, 'Derken nasıldı azabım benim ve korkutuşlarım?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 31, 'Gerçekten de bir bağırış gönderdik onlara, derken hayvan ağılına konan çalıya çırpıya döndüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 32, 'Ve andolsun ki öğüt ve ibret için Kur''an''ı kolaylaştırdık, fakat bir ibret alan mı var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 33, 'Lut kavmi de korkutucuları yalanladılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 34, 'Gerçekten de, Lut''un ailesi müstesna, onlara taş yağdıran bir yel gönderdik, Lut''un ailesini de bir seher çağı kurtardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 35, 'Katımızdan bir nimet olarak; işte böyle mükafatlandırırız şükredeni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 36, 'Ve andolsun ki o, bizim helakimizle korkutmuştu onları da onlar, bu korkutuşlardan şüpheye düşmüşlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 37, 'Ve gerçekten de onun konuklarını istemişlerdi de biz, kör edivermiştik gözlerini, artık tadın azabımı ve korkutuşlarımın sonucunu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 38, 'Ve andolsun ki bir sabah çağı üstlerine bir azap çöküvermişti onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 39, 'Artık tadın azabımı ve korkutuşlarımı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 40, 'Ve andolsun ki öğüt ve ibret için Kur''an''ı kolaylaştırdık, fakat bir ibret alan mı var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 41, 'Ve andolsun ki Firavun soyuna da korkutucular gelmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 42, 'Bütün delillerimizi yalanladılar, derken onları üstün ve mutlak kudretli bir helak edişle helak ediverdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 43, 'Sizin kafirleriniz, onlardan hayırlı mı, yoksa kitaplarda bir kurtuluş mu var size?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 44, 'Yoksa biz, birbirine yardım eden bir topluluğuz mu derler?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 45, 'O topluluk, yakında bozguna uğrayacak ve ardını dönüp kaçacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 46, 'Onlara vaadedilen azabın mukadder zamanı kıyamettir ve kıyametin azabı, daha da zararlıdır ve daha da acı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 47, 'Şüphe yok ki suçlular, sapıklık içinde ve yakıp kavuran ateşlerdedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 48, 'O gün, yüzüstü ateşe sürüklenip atılırlar; tadın bakalım, cehennemin yakışını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 49, 'Şüphe yok ki biz; her şeyi, bilgimizde mukadder olduğu gibi ve zamanında yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 50, 'Ve bizim emrimiz, birdir, ancak bir göz kırpış, bir göz yumup açış gibi tezdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 51, 'Ve andolsun ki taraftarlarınızı da helak ettik, fakat bir ibret alan mı var?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 52, 'Ve işledikleri her şey, kitaplardadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 53, 'Ve küçük, büyük, hepsi de yazılıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 54, 'Şüphe yok ki çekinenler, cennetlerdedir, ırmakların başlarında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (54, 55, 'Gerçeklik makamında, çok kudretli bir büyük padişah katında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 1, 'Rahman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 2, 'Kur''an''ı öğretti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 3, 'insanı halketti,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 4, 'ona dilleri, konuşmayı belletti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 5, 'Güneş ve ay, hesapla hareket eyler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 6, 'Ve gövdesiz bitki ve gövdeli ağaç secde eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 7, 'Ve göğü yüceltti ve ölçüyü koydu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 8, 'Ölçüde, tartıda insafsızlık etmeyin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 9, 'Teraziyi doğru tutun, adaletle tartın ve eksik tartmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 10, 'Yeryüzünü alçalttı halka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 11, 'Orada meyveler ve lifli, kabuklu hurmalar var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 12, 'Yapraklı taneler var ve güzel kokulu otlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 13, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 14, 'İyice pişmiş gibi kupkuru balçıktan, insanı halketti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 15, 'Ve cinleri, coşup kaynayan ateşten yarattı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 16, 'Artık Rabbinizin nimetlerinden hangisini yalanlıyabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 17, 'Rabbidir iki doğunun ve Rabbidir iki batının.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 18, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 19, 'İki denizi salmıştır, nerdeyse karışacaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 20, 'Fakat aralarında bir berzah var, birbirlerine karışmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 21, 'Artık Rabbinizin nimetlerinden hangisini yalanlıyabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 22, 'Her ikisinden de inci ve mercan çıkar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 23, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 24, 'Ve onundur denizde akıp giden dağlar gibi gemiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 25, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 26, 'Yerin üstünde ne varsa fanidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 27, 'Ve ancak ululuk ve kerem ıssı Rabbinin zatıdır kalan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 28, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 29, 'Ondan ister kim varsa göklerde ve yeryüzünde; o, her gün bir iştedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 30, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 31, 'Ey iki ağır topluluk, insanlar ve cinler, yakında hesabınıza bakacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 32, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 33, 'Ey cin ve insan topluluğu, ölümden kurtulmak için, göklerin ve yer yüzünün bucaklarından geçip kaçmaya gücünüz yeterse geçin, kaçın; fakat geçemezsiniz bir kudret olmadıkça.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 34, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 35, 'Üstünüze bir ateş yalımı ve erimiş bakır gönderilir de kaçamazsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 36, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 37, 'Derken gök yarılıp kırmızı bir gül rengine gelerek yağ gibi eriyince...', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 38, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 39, 'Ne insan, ne cin, artık o gün suçlu mudur, sorulmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 40, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 41, 'Suçlular, yüzlerindeki alametten tanınırlar da perçemlerinden ve ayaklarından tutulurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 42, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 43, 'İşte bu, suçluların yalanladıkları cehennem.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 44, 'Cehennemle içecekleri kaynar suyun arasında dolanıp dururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 45, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 46, 'Rabbinin tapısına varmaktan korkana iki cennet var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 47, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 48, 'İkisinde de türlütürlü nimetler var, çeşitçeşit ağaçlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 49, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 50, 'İkisinde de iki ırmak var, akar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 51, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 52, 'İkisinde de her çeşit meyve, çifterçifter var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 53, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 54, 'Öylesine döşemelere yaslanacaklar ki astarları kalın ipekten, her iki cennetin, devşirilip toplanacak meyveleri de ellerinin altında, pek yakın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 55, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 56, 'O cennetlerde, gözlerini, eşlerinden ayırmayan ve eşlerinden önce ne bir insan tarafından dokunulmuş, ne bir cin tarafından dokunulmuş eşler var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 57, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 58, 'O eşler, sanki yakut ve mercan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 59, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 60, 'İyiliğin karşılığı, iyilikten başka bir şey olabilir mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 61, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 62, 'Bu iki cennetten başka iki cennet daha var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 63, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 64, 'İkisi de koyu yeşil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 65, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 66, 'İkisinde de iki pınar var, fışkırıp çıkar da akar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 67, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 68, 'Her ikisinde de meyveler ve hurma ve nar var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 69, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 70, 'O cennetlerde güzel huylu güzeller var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 71, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 72, 'Beyaz tenli, kara gözlü, otağlarda huriler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 73, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 74, 'Eşlerinden önce ne bir insan dokunmuş onlara, ne bir cin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 75, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 76, 'Yeşil ipeklilerle düşenmiş sedirlere ve güzelim döşemelere yaslanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 77, 'Artık Rabbinizin nimetlerinden hangisini yalanlayabilirsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (55, 78, 'Ululuk ve kerem ıssı Rabbinin adının şanı, pek yücedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 1, 'Ansızın kopacak kıyamet kopunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 2, 'Kopacağına dair söylenen sözlerde yalan yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 3, 'Halkı alçaltır, yüceltir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 4, 'Yeryüzü şiddetli bir sarsıntıyla sarsılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 5, 'Ve dağlar, paramparça olunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 6, 'Dağılmış zerre zerre toz haline gelince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 7, 'Artık üç bölük olursunuz siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 8, 'Sağ taraf ehli, ama ne de sağ taraf ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 9, 'Ve sol taraf ehli, ama ne de sol taraf ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 10, 'Ve bir de ileri geçenler ki herkesi geçmişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 11, 'Onlardır mabutlarına yaklaştırılanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 12, 'Naim cennetlerinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 13, 'Öncekilerin birçoğu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 14, 'Sonra gelenlerdense azı onlardan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 15, 'Altınlarla, mücevherlerle bezenmiş tahtlarda otururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 16, 'Onlara yaslanırlar, birbirlerine karşı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 17, 'İhtiyarlamıyan delikanlı hizmetçiler dolaşır etraflarında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 18, 'Kaynağından doldurulmuş şaraplarla dolu taslarla ve ibriklerle ve kadehlerle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 19, 'O şaraptan başları da ağrımaz ve sarhoş da olmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 20, 'Beğendikleri meyvelerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 21, 'İstedikleri kuş etlerinden sunulur onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 22, 'Ve onlara kara gözlü huriler de var ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 23, 'Sanki haznelerde saklanmış inciler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 24, 'Yaptıklarına karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 25, 'Orada boş ve çirkin bir söz de duymazlar, günaha ait bir söz de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 26, 'Ancak, esenlik size, esenlik denir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 27, 'Ve sağ taraf ehli, ama ne de sağ taraf ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 28, 'Dikensiz sedir ağaçlarıyla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 29, 'Ve meyveleri birbirine yaslanıp istiflenmiş muz ağaçlarıyla dolu bir yerdedir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 30, 'Ve uzayıp giden bir gölgelik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 31, 'Ve çağlayaçağlaya akan sular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 32, 'Ve birçok meyveler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 33, 'Ne biter, zamanları geçer, ne yiyene yeme denir, yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 34, 've yüksek döşekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 35, 'Şüphe yok ki biz, onların eşlerini de yeniden yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 36, 'Onları, kız oğlan kız olarak halkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 37, 'Cilveli, şirin sözlü, eşlerine aşık ve onlarla yaşıt kıldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 38, 'Sağ taraf ehli için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 39, 'Onlarda, evvelkilerden de birçok topluluk var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 40, 'Ve sonra gelenlerden de birçok topluluk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 41, 'Ve sol taraf ehli, ama ne de sol taraf ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 42, 'Onlar, iliklere kadar işleyen bir sam yeli içinde, kaynar sular içmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 43, 'Ve karardıkça kararan bir dumanın gölgesindeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 44, 'Ne bir serinlik var, ne bir güzellik var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 45, 'Bundan önce onlar, nimetler içindeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 46, 'Ve büyük günahları yapmada ısrar ederlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 47, 'Ve biz derlerdi, ölüp bir yığın toprak ve kemik olduktan sonra mı dirileceğiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 48, 'Yoksa önceden gelip geçen atalarımız mı dirilecek?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 49, 'De ki: Şüphe yok, öncekiler de, sonra gelenler de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 50, 'Elbette bilinen günün muayyen ve mukadder vaktinde toplanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 51, 'Sonra da siz ey yalanlayan sapıklar, şüphe yok ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 52, 'Zakkum ağacının meyvesinden yiyeceksiniz elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 53, 'Derken karınlar, dolup şişecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 54, 'Derken üstüne, kaynar su içeceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 55, 'Derken susuzluk illetine uğrayıp içecekiçecek de kanmayacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 56, 'Budur ceza günü ziyafetleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 57, 'Biz yarattık sizi, hala mı gerçeklemezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 58, 'Görmez misiniz rahimlere döktüğüm bir katre suyu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 59, 'Siz mi yaratıyorsunuz onu, yoksa biz mi yaratmadayız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 60, 'Biz takdir ettik aranızda ölümü ve kimse geçemez önümüze bizim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 61, 'Sizin gibi bir topluluk yaratıp yerinize geçirmek istersek ve sizi de, bilmediğiniz bir şekle döndürmeyi dilersek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 62, 'Ve andolsun ki ilk yaratılışı biliyorsunuz, biliyorsunuz da ne diye düşünmüyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 63, 'Görmez misiniz ektiğiniz tohumu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 64, 'Siz mi bitiriyorsunuz onu, yoksa biz mi bitirmedeyiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 65, 'Dilersek elbette onu kurutup çerçöp haline getirirdik de şaşırırkalır, nadim olurdururdunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 66, 'Gerçekten de biz derdiniz, ziyan ettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 67, 'Hayır, biz mahrum olduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 68, 'Görmez misiniz içtiğiniz suyu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 69, 'Siz mi yağdırıyorsunuz onu buluttan, yoksa biz mi yağdırmadayız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 70, 'Dileseydik onu tuzlu, acı bir su haline getirirdik, hala mı şükretmezsiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 71, 'Görmez misiniz çakmakla çakıp yaktığınız ateşi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 72, 'Siz mi onun ağacını meydana getiriyorsunuz, yoksa biz mi meydana getirmedeyiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 73, 'Biz onu, cehennem ateşini bir andırma ve çöllerde konup göçenlere bir fayda olarak halkettik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 74, 'Artık pek ulu Rabbinin adını anarak tenzih et onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 75, 'Andolsun yıldızların yerlerine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 76, 'Ve şüphe yok ki bu, elbette pek büyük bir anttır bilseniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 77, 'Şüphe yok ki bu, pek güzel ve şerefli Kur''an''dır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 78, 'Saklanmış bir kitapta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 79, 'Ona, temiz olanlardan başkaları dokunamaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 80, 'Alemlerin Rabbinden indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 81, 'Artık siz, bu sözü mü yalanlayacaksınız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 82, 'Ve o kitaptan nasibiniz, yalnız onu yalanlamaktan ibaret mi olacak?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 83, 'Hani can gırtlağa gelince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 84, 'Siz de o sırada bakar durursunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 85, 'Ve biz, ona sizden daha yakınız ve fakat göremezsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 86, 'İnanmıyorsanız, ceza görmeyeceğinizi sanıyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 87, 'O gırtlağa gelen canı geri çevirin bakalım doğru söylüyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 88, 'Artık o kişi yakınlaştırılanlardansa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 89, 'Artık ona huzur ve rahat ve rızık ve Naim cenneti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 90, 'Ve ama sağ taraf ehlindense.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 91, 'Artık esenlik sana sağ taraf ehlinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 92, 'Ve ama yalanlayan sapıklardansa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 93, 'Kaynar suyla ziyafet ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 94, 'Ve cehenneme atılma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 95, 'Şüphe yok ki bu, haktır, gerçeğin ta kendisidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (56, 96, 'Artık pek ulu Rabbinin adını anarak tenzih et onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 1, 'Tenzih eder Allah''ı ne varsa göklerde ve yeryüzünde ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 2, 'Onundur saltanatı ve tedbiri göklerin ve yeryüzünün, yaşatır ve öldürür ve onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 3, 'Ve odur her şeyden önce var olan ve her şeyden sonra kalan ve her şeye üstün olup delilleriyle bilinen ve her şeyi bilen de duygularla bilinmeyen ve o, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 4, 'Öyle bir mabuttur ki gökleri ve yeryüzünü altı günde yaratmıştır da sonra arşa hakim olmuştur, bilir, ne girerse yere ve ne çıkarsa oradan ve ne yağarsa gökten ve ne ağarsa oraya ve o, sizinledir nerede olursanız; ve Allah, ne yapıyorsanız görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 5, 'Onundur saltanatı ve tedbiri göklerin ve yeryüzünün; ve bütün işler, dönüp Allah tapısına varır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 6, 'Geceyi kısaltır, bir kısmı gündüz olur ve gündüzü kısaltır, bir kısmı gece olur ve o, gönüllerdekini bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 7, 'İnanın Allah''a ve Peygamberine ve sizi sahib ettiği, sizin tasarrufunuza verdiği malların bir kısmını, onun yolunda harcayın; artık sizden inanan ve mallarını harcayanlara büyük bir mükafat var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 8, 'Ve ne oluyor size de Allah''a inanmıyorsunuz? Ve Peygamber, Rabbinize inanın diye sizi çağırmada ve andolsun ki sizden söz de almıştı inanmışsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 9, 'Ve öyle bir mabuttur ki sizi karanlıklardan aydınlığa çıkarmak için kuluna apaçık deliller indirmededir ve şüphe yok ki Allah, sizi esirger ve size rahimdir elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 10, 'Ve ne oluyor size de Allah yolunda mallarınızı harcamıyorsunuz? Ve Allah''ındır göklerin ve yeryüzünün mirası; sizden, fetihten önce mallarını harcayan ve savaşan, başkalarıyla bir değildir; onların, fetihten sonra mallarını harcayan ve savaşanlara karşı derece bakımından pek büyük bir üstünlükleri var; ve hepsine de Allah, güzel mükafatlar vaadetmiştir ve Allah, ne yapıyorsanız, hepsinden de haberdar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 11, 'Kimdir o ki Allah''a adeta güzel bir borç verir de o, katkat fazlasını verir ona ve ona pek güzel de bir mükafat var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 12, 'O gün görürsün ki erkek ve kadın, inananların nurları, önlerinde ve sağlarında parlayıp koşmada; müjde bugün size; kıyılarından ırmaklar akan cennetlerde ebedi olarak kalacaksınız ve bu, en büyük kutluğun, murada erişin ve başarının ta kendisidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 13, 'O gün, erkek ve kadın münafıklar, inananlara, bizi de bekleyin de derler, gelelim, nurunuzdan alalım; onlara dönün ardınıza da bir nur isteyin artık denir. Derken aralarına bir duvardır çekilir ki bir kapısı vardır, içinde rahmet vardır da dış tarafında azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 14, 'Onlar bağırırlar da derler ki: Biz, sizinle beraber değil miydik? Evet derler ve fakat siz, kendinizi fitnelere saldınız ve iman edenlerin bir felakete uğramasını beklediniz ve şüphe ettiniz ve olmayacak istekler, sizi aldatıp durdu, sonunda Allah''ın emri, gelip çattı ve sizi Şeytan, aldatmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 15, 'Artık bugün ne sizden, azaptan kurtulmanız için bir şey alınır, ne kafir olanlardan ve yurdunuz ateştir sizin, odur size layık olan ve orası, dönüp gidilecek ne de kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 16, 'İnananlara, o çağ gelmedi mi henüz, Allah''ı anış ve Kur''an''dan inen şeyler, onların gönüllerini yumuşatsın da tamamıyla korkup itaat etsinler ve önceden kendilerine kitap verilenlere benzemesinler; onların, peygamberleriyle araları, uzayıp açıldıkça kalpleri katılaştı ve onların çoğu, buyruktan çıktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 17, 'Bilin ki Allah, yeryüzünü, ölümünden sonra diriltir; andolsun ki akıl edesiniz diye size delillerimizi apaçık bildirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 18, 'Şüphe yok ki sadaka veren erkek ve kadın inananlarla Allah''a güzel bir borç verenlerin verdikleri şey, gene kendileri için katkat arttırılır ve onlara, güzel bir mükafat vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 19, 'Ve Allah''a ve Peygamberlerine inananlar yok mu, onlardır Rableri katında gerçeklerin ve tanıkların ta kendileri; onların mükafatları da vardır, nurları da; kafir olanlara ve delillerimizi yalanlayanlara gelince: Onlardır cehennem ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 20, 'Bilin ki dünya yaşayışı, ancak bir oyundur, bir eğlencedir, bir bezentidir ve aranızda bir övünmedir ve bir mal ve evlat çokluğu gayretidir ancak ve bunlardan ibarettir de; halbuki dünya yaşayışı, bir yağmura benzer, bitirdiği nebatlar, ekincileri şaşırtır, sevindirir, sonra kuruyuverir de bir de bakarsın, sapsarı olmuş, sararıp solmuş, sonra da unufak olmuş, dağılıp gitmiş; ve ahiretteyse çetin bir azap var ve Allah''tan yarlıganma ve razılık; ve dünya yaşayışı, ancak bir aldanış metaından ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 21, 'Ve yarışarak koşun Rabbinizin yarlıgamasına ve cennete ki genişliği, göğün ve yeryüzünün genişliği gibidir, hazırlanmıştır Allah''a ve peygamberlerine inananlara; bu, Allah''ın lutfudur, ihsanıdır, dilediğine verir onu ve Allah, pek büyük bir lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 22, 'Yeryüzüne, yahut canlarınıza gelip çatan hiçbir felaket yoktur ki biz, onları yaratmadan önce onu, bir kitapta tespit etmemiş olalım; şüphe yok ki bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 23, 'Bunu da, elinizden çıkarıp kaybettiğiniz şeye kederlenmeyin ve size verdiğimize sevinmeyin diye yapmışızdır ve Allah, övünüp kibirlenen hiçbir kimseyi sevmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 24, 'Onlar, öyle kişilerdir ki nekeslik ederler ve insanlara da nekes olmalarını emrederler; gerçekten de Allah, müstağnidir ve hamde layık, odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 25, 'Andolsun ki biz, peygamberlerimizi, apaçık delillerle gönderdik ve onlarla beraber de kitap ve terazi indirdik, insanlar adaletle doğru muamele etsinler diye ve demiri de indirdik ki onda çetin bir azap var ve insanlara faydalar; ve bu da, Allah''ın kendisine ve peygamberlerine, henüz tapısına varmadan yardım edenleri bildirmesi için; şüphe yok ki Allah, üstündür ve pek kuvvetlidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 26, 'Ve andolsun ki biz, Nuh''u ve İbrahim''i gönderdik ve soylarına da peygamberlik ve kitap verdik; derken onlardan doğru yolu bulanlar var ve çoğuysa buyruktan çıkmış olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 27, 'Sonra izlerinden peygamberler gönderdik ve onların izince de Meryem oğlu İsa''yı yolladık ve ona İncil''i verdik ve ona uyanların gönüllerinde fazla bir yumuşaklık ve merhamet yarattık; ve rahipliği, onlara biz farzetmediysek de onlar ancak Allah rızasını kazanmak için icat ettiler, derken onun hakkına da gereği gibi riayet edemediler, derken onlardan inananlara, mükafatlarını verdik ve onların çoğuysa buyruktan çıkmış olanlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 28, 'Ey inananlar, çekinin Allah''tan ve inanın Peygamberine de size rahmetinden iki pay versin ve size bir nur halketsin ki onunla doğru yolu bulun ve sizi yarlıgasın, suçlarınızı örtsün ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (57, 29, 'Ve bunlar da, kitap ehlinin, şunu bilmeleri için bildirilmiştir: Onlar, Allah''ın lütuf ve ihsanından hiçbir şeyi menedemezler ve lütuf ve ihsan, Allah''ın elindedir, dilediğine verir ve Allah, pek büyük bir lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 1, 'Gerçekten de Allah, seninle, kocası hakkında çekişirken Allah''a şikayette bulunan kadının sözünü işitti ve Allah sizin konuşmanızı duyuyordu; şüphe yok ki Allah, duyar, görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 2, 'Sizden, karılarına zıhar yapanlar, bilsinler ki karıları, anaları değildir, anaları, ancak onları doğuran kadınlardır ve şüphe yok ki onlar, çirkin bir laftır, ediyorlar ve yalan söylüyorlar ve şüphe yok ki Allah, elbette bağışlayıcıdır, suçları örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 3, 'Ve karılarına zıhar yapıp sonra dediklerinden dönenler, karılarıyla temastan önce bir kul azat etmelidirler; bu, size, onunla öğüt almanız için bir emir ve Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 4, 'Kimin, buna gücü yetmezse artık ona, birbiri ardınca tam iki ay oruç tutma var, karı, koca, birbirlerine temas etmeden önce; buna da gücü yetmeyen kişiyeyse altmış yoksulu doyurmak düşer; bu, Allah''a ve Peygamberine inanmanız içindir ve bunlar, Allahın sınırlarıdır ve kafirlereyse elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 5, 'Allah''ın ve Peygamberinin emrine aykırı hareket edenler, aşağılık bir hale gelir, rüsva olurlar. Nitekim onlardan öncekiler de aşağılık bir hale geldiler ve rüsva oldular, halbuki gerçekten de apaçık deliller indirmiştik ve kafirlere, aşağılatıcı birazap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 6, 'O gün, Allah, onların hepsini de diriltip toplar da neler yaptılarsa haber verir onlara; onlar, unutmuşlardır ama Allah birbir hesaplamış, tespit etmiştir ve Allah, her şeye tanıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 7, 'Görmez misin ki Allah, şüphe yok ki bilir ne varsa göklerde ve ne varsa yeryüzünde; üç kişi gizli konuşmaz ki o, dördüncüleri olmasın ve beş kişi yoktur ki altıncıları, o olmasın ve bundan daha az ve daha çok olsalar da o, onlarla beraberdir nerede olurlarsa, sonra da kıyamet günü, ne yaptılarsa onlara haber verir; şüphe yok ki Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 8, 'Bakmaz mısın gizli ve fısıltıyla konuşmadan vazgeçmeleri emredilenlere, sonradan gene vazgeçmeleri emredilen şeye dönerler ve suça ve düşmanlığa ve Peygambere isyana ait şeyleri gizlice konuşurlar ve senin yanına gelince de Allah''ın, sana verdiği selamdan başka bir tarzda selam verirler sana ve birbirlerine de şu söylediklerimiz yüzünden derler, Allah''ın bizi azaplandırması gerekmez miydi? Cehennem yeter onlara, oraya atılıp yanacaklardır ve gerçekten de orası, dönülüp gidilecek ne de kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 9, 'Ey inananlar, gizli konuşursanız suça ve düşmanlığa ve Peygambere karşı isyana dair konuşmayın da hayra ve çekinmeye dair konuşup danışın ve çekinin o Allah''tan ki onun tapısında toplanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 10, 'O gizli konuşmalar, inananları mahzun etmek için ancak Şeytan''ın iğvasıyla meydana gelir ve halbuki Allah''ın izni olmadıkça onlara hiçbir şey zarar vermez ve dayananlar, artık Allah''a dayansınlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 11, 'Ey inananlar, meclislerde, size yer açın denince, yer açın artık, genişletin meclisi de Allah da size genişlik versin ve kalkın, şuraya geçin dendiği zaman kalkın, geçin; Allah da, içinizden, gerçekten iman edenleri de yükseltsin, kendilerine bilgi verilenleri de derecederece yüceltsin ve Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 12, 'Ey inananlar, Peygamberlere gizlice konuşacağınız vakit, konuşmaya başlamadan bir sadaka verin; bu, sizin için hem daha hayırlıdır, hem de daha temiz; bulamazsanız artık Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 13, 'Gizlice konuşmadan önce sadakalar vermeden korktunuz mu? Mademki yapmadınız, Allah da tövbe nasip etti artık size ve kabul etti tövbenizi, şu halde namaz kılın ve zekat verin ve itaat edin Allah''a ve Peygamberin''e ve Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 14, 'Bakmaz mısın şunlara ki Allah''ın gazap ettiği bir topluluğa dostluk ederler; onlar, ne sizdendir, ne onlardan ve bilip dururken de yalan yere yemin ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 15, 'Allah, onlara çetin bir azap hazırlamıştır; gerçekten de ne kötü işler yapıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 16, 'Yeminlerini bir kalkan edinmedeler de halkı Allah yolunda menetmedeler, onlaradır artık aşağılatıcı bir azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 17, 'Onları, malları ve evlatları, hiçbir suretle ve kesin olarak Allah''tan kurtaramaz, onlardır cehennem ehli, orada ebedidir onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 18, 'Allah''ın, onların hepsini diriltip topladığı gün, size yemin ettikleri gibi ona da yemin ederler ve sanırlar ki bir şey yapıyorlar gerçekten de; bilin ki şüphe yok, yalancılardır onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 19, 'Şeytan, üstlerine saldırmıştır, üst olmuştur da onlara Allah''ı anmayı unutturmuştur; onlardır Şeytan''ın fırkası; bilin ki şüphe yok, Şeytan''ın fırkası, ziyan edenlerin ta kendisidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 20, 'Allah''ın ve Peygamberinin sınırlarına uymayanlar ve karşı gelenler yok mu, onlardır en aşağılık kişilerin içinde bulunanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 21, 'Allah yazdı, takdir etti ki andolsun, ben ve peygamberlerim üstün geleceğiz; şüphe yok ki Allah pek kuvvetlidir, üstündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (58, 22, 'Allah''a ve ahiret gününe inanan bir topluluğu, Allah''ın ve Peygamberinin sınırlarına aykırı hareket edip onlara karşı gelen birisini sever bulamazsın ve isterse onlar, babaları, yahut oğulları, yahut kardeşleri, yahut da aşiretlerinden olsun; onlar, öyle kişilerdir ki Allah, gönüllerine iman nasip ve mukadder etmiştir ve onları, kendinden bir ruhla, imanla kuvvetlendirmiştir ve onları, kıyılarından ırmaklar akan cennetlere sokar, orada ebedi olarak kalırlar; razı olmuştur Allah onlardan ve razı olmuşlardır onlar da ondan; onlardır Allah fırkası; bilin ki şüphe yok, Allah fırkası, kurtulanların, muradına erenlerin ta kendisidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 1, 'Tenzih eder Allah''ı ne varsa göklerde ve ne varsa yeryüzünde ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 2, 'Öyle bir mabuttur ki kitap ehlinden kafir olanları, ilk defa toplanmaları için ülkelerinden çıkardı; siz, onların çıkacaklarını hiç sanmazdınız, onlar da şüphesiz ki kaleleri, kendilerini Allah''tan korur sanırlardı. Derken Allah, onların hesaplamadıkları yerden gelip çattı da yüreklerine dehşetli bir korku düşürdü, evlerini, kendi elleriyle ve inananların elleriyle yıkmadalar, artık ibret alın ey can gözü açık olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 3, 'Ve eğer Allah, onlara sürgünü takdir etmemiş olsaydı elbette onları dünyada azaplandırırdı; ve onlara, ahirette de ateşle azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 4, 'Bu da, onların, şüphe yok ki Allah''a ve Peygamberine karşı gelmelerindendir ve kim Allah''a karşı gelirse bilsin ki artık Allah, pek çetin azap eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 5, 'Güzelim hurmalardan kestikleriniz de, kesmeyip öyle boy atmış bir halde bıraktıklarınız da Allah''ın izniyledir gerçekten ve bu da, buyruktan çıkanları horhakir bir hale getirmesi içindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 6, 'Ve Allah''ın, onların mallarından, Peygamberine verdiği şeyler için siz, gerçekten de ne deve sürdünüz, ne at oynattınız ve fakat Allah, peygamberlerini, dilediği kimselerin üstüne atıp üstün eder ve Allah''ın, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 7, 'Allah''ın, fethedilen köylerin mallarından Peygamberine verdiği ganimetler artık Allah''ındır ve Peygamberin ve yakınların ve yetimlerin ve yoksulların ve yolda kalmışların; bu da, o malın, sizin içinizdeki zenginlerin ellerinde devreden bir mal, bir sermaye olmaması içindir ve Peygamber, size ne verirse alın onu ve neden vazgeçmenizi emrederse vazgeçin ondan ve çekinin Allah''tan; şüphe yok ki Allah''ın azabı çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 8, 'O mallar, yurtlarından göçenlerin yoksullarına aittir; onlar, ülkelerinden çıkarılmışlar, mallarından ayrılmışlar, Allah''tan ancak bir lütuf ve razılık dileyegelmişlerdir ve Allah''a ve Peygamberine yardım etmişlerdir; onlardır gerçeklerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 9, 'Ve onların göçmesinden önce yurtlarını hazırlayıp orasını bir iman konağı haline getirenlere ve yurtlarına göçenleri sevenlere ve onlara verilen şeylere karşı gönüllerinde bir ihtiyaç, bir istek duymayanlara ve ihtiyaçları bile olsa onları kendilerinden üstün tutanlara gelince: Ve kim, nefsinin hırsından, kıskançlık ve nekesliğinden geçerse gerçekten de o çeşit kimselerdir kurtulanların, muratlarına erenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 10, 'Ve onlardan sonra gelenler de Rabbimiz derler, suçlarımızı ört bizim ve bizden önce inanan kardeşlerimize ve inananlara karşı gönlümüze bir kin, bir haset verme; Rabbimiz, şüphe yok ki sen esirgeyicisin, rahimsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 11, 'Bakmaz mısın münafık olanlara, kitap ehlinden kafir olan kardeşlerine, andolsun ki derler, siz yurdunuzdan çıkarılırsanız biz de mutlaka sizinle beraber çıkarız ve aleyhinizde itaat etmeyiz hiç kimseye ebediyen ve eğer sizinle savaşırlarsa elbette size yardım ederiz ve Allah, tanıklık eder ki onlar, şüphe yok, yalancılardır elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 12, 'Ve andolsun ki çıkarılırlarsa yurtlarından onlarla beraber çıkmazlar ve andolsun ki savaşılırsa onlarla, yardım etmezler onlara ve andolsun ki yardım etseler bile artlarını dönüp kaçarlar mutlaka, sonra da onlara hiçbir kimse yardım etmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 13, 'Mutlaka gönüllerinde, Allah''tan ziyade sizin korkunuz vardır, bu da, şüphe yok ki anlamayan bir topluluk olmalarındandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 14, 'Onların, hepsi birden sizinle savaşmazlar, ancak müstahkem yerlerde, yahut da surların ardında çarpışırlar; onların gücü kuvveti, aralarında çetindir, onları bir topluluk sanırsın ama gönülleri dağınıktır, ayrıayrıdır; bu da akıl etmez bir topluluk olmalarındandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 15, 'Onlar, kendilerinden az önce gelip de yaptıkları işin vebalini tatmış olanlara benzerler ve onlara elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 16, 'Şeytan gibi, hani insana, kafir ol der de insan kafir oldu muydu, şüphe yok ki der, ben senden tamamıyla uzağım, şüphe yok ki ben, alemlerin Rabbi Allah''tan korkarım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 17, 'Derken ikisinin de sonları şu olur: Şüphe yok ki ikisi de, ebedi kalmak üzere ateşe girerler ve budur zulmedenlerin cezası.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 18, 'Ey inananlar, sakının Allah''tan ve herkes, yarın için ne hazırladı, ona baksın ve çekinin Allah''tan; şüphe yok ki Allah, ne yapıyorsanız hepsinden haberdar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 19, 'Ve o kişilere benzemeyin ki Allah''ı unutmuşlar da o da, kendilerini unutturmuştur onlara; onlardır, buyruktan çıkanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 20, 'Bir değildir cehennem ehli ve cennet ehli; cennet ehlidir kurtulup üst olanların, kutluluğa erip muratlarını bulanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 21, 'Bu Kur''an''ı, bir dağın üstüne indirseydik elbette görürdün ki dağ, Allah korkusundan eğilip çatlamış, paramparça olmuş ve işte insanlara bu örnekleri, düşünsünler diye getirmedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 22, 'O, bir Allah''tır ki yoktur ondan başka tapacak; gizliyi de bilir, görüneni de, odur rahman ve rahim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 23, 'O, bir Allah''tır ki yoktur ondan başka tapacak; her şeye sahiptir, ayıplardan ve noksanlardan arıdır, kullarını esenliğe erdirir ve kendi esendir, kullarına zulmetmez ve onları emniyete ulaştırır, her şeyi görüp gözetir, üstündür, saltanatında mutlaktır ve iradesini geçirir de sınıkları onarır ve eksikleri tamamlar, ululuk ıssıdır ve ulu sıfatlara layıktır; münezzehtir, yücedir Allah, şirk koşanların şirk koştukları şeylerden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (59, 24, 'O Allah, yaratandır, varedip olgunlaştırandır, suret verendir, onundur bütün güzel adlar; tenzih eder onu ne varsa göklerde ve ne varsa yeryüzünde ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 1, 'Ey inananlar, düşmanlarımı ve düşmanlarınızı dost edinip onları sevmeyin, onlara haber yolluyorsunuz ama onlar, size gerçek olarak gelen şeye kafir olmuşlardır da Peygamberi ve sizi, Rabbiniz Allah''a inanıyorsunuz diye yurdunuzdan çıkarıyorlar; benim yolumda savaşmak ve razılığımı arayıp elde etmek için yurdunuzdan çıktıysanız, bu, böyle; siz, onlara sevgiyle sır veriyorsunuz ve bense sizin gizlediğiniz şeyi de daha iyi bilirim, açığa vurduğunuz şeyi de ve sizden kim bu işi yaparsa gerçekten dedüz ve doğru yoldan sapmış, yolunu kaybetmiş gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 2, 'Size üst olurlar da ele geçirirlerse düşman olurlar size ve ellerini ve dillerini, kötülükle uzatırlar size ve onlar isterler ki siz kafir olasınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 3, 'Kıyamet gününde yakınlarınız da kesin olarak bir fayda veremez size, evlatlarınız da, aranızı ayırır ve Allah, ne yapıyorsanız hepsini de görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 4, 'Gerçekten de İbrahim''de ve onunla beraber bulunanlarda güzel bir örnek var size; hani kavimlerine demişlerdi ki: Şüphe yok ki biz, sizden ve Allah''tan başka kulluk ettiklerinizden tamamıyla uzağız, inkar ettik sizi ve aramızla aranızda, bir Allah''a siz de inanıncaya dek ebedi bir düşmanlık ve nefret belirmiştir; ancak İbrahim''in, atasına, elbette senin için yarlıganma dileyeceğim ve fakat Allah''tan sana gelecek hiçbirşeyi de menedemem sözü başka; Rabbimiz, sana dayandık ve sana yöneldik ve dönüpgeleceğimiz yer de senin tapın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 5, 'Rabbimiz, bizi kafirlere sınanma konusu yapma ve suçlarımızı ört Rabbimiz, şüphe yok ki sen üstünsün, hüküm ve hikmet sahibisin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 6, 'Andolsun ki onlarda, size, Allah''a ve ahiret gününe kavuşmayı umanlara, güzel bir örnek var ve kim, yüz çevirirse bilsin ki Allah, şüphe yok ki müstağnidir, hamde layık olan odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 7, 'Umulur ki Allah, sizinle, düşmanlık ettiklerinizin arasına yakında bir sevgi de verir ve Allah''ın gücü yeter ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 8, 'Allah, din hususunda sizinle savaşmayan ve sizi, ülkenizden çıkarmayanlara iyilik etmenizi, onlara karşı insafla, adaletle muamelede bulunmanızı nehyetmez; şüphe yok ki Allah, adaletle muamele edenleri sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 9, 'Allah, ancak din uğrunda sizinle savaşanlara ve sizi ülkenizden çıkaranlara ve çıkmanız için onlara yardımda bulunanlara dost olmanızı nehy etmektedir ve kimler, onları severse onlardır gerçekten de zalimlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 10, 'Ey inananlar, size, yurtlarından göçmüş olan iman sahibi kadınlar geldi mi onları sınayın artık, Allah, onların inançlarını daha iyi bilir; siz de onların inanmış olduklarını bilince onları gerisingeriye kafirlere göndermeyin; ne onlar, kafirlere helaldir, ne kafirler, onlara helal ve onlara, kocalarının vereceği nikah parasını verin ve nikah paralarını verdikten sonra onları, kendinize nikahlamanızda da bir vebal yoktur size; kafir kadınlarıysa nikahlamayın, nikahınızın altında tutmayın onları ve sarfettiklerinizi isteyin ve kafirler de, size gelen inanmış kadınlara sarfettiklerini istesinler; işte budur size Allah''ın hükmü, o hükmeder aranızda ve Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 11, 'Ve eşlerinizin nikah paralarından bir miktarı, onlar gider de, elinizden çıkarsa nöbet size gelince, kafir kadınlarından inanıp size göçen bulununca eşleri gitmiş olanlara, ettikleri masraf kadar para verin ve çekinin o Allah''tan ki siz, ona inanmışsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 12, 'Ey Peygamber, inanmış kadınlar, hiçbir şeyi Allah''a ortak kabul etmeyip şirk koşmamak ve hırsızlık etmemek ve zinada bulunmamak ve çocuklarını öldürmemek ve kendi çocuklarından başkasını eşlerine, ben doğurdum diye tanıtıp iftira etmemek ve sana, meşru ve güzel işlerde karşı gelmemek üzere biatlaşmaya geldikleri zaman biatlaş onlarla ve onlar için Allah''tan yarlıganma dile; şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (60, 13, 'Ey inananlar, Allah''ın gazabına uğrattığı toplulukla dostluk etmeyin; gerçekten de onlar, ahiretten, tamamıyla ümitlerini kesmişler, nitekim kafirler de, kabirlerdekilerden tamamıyla ümit kesmişlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 1, 'Tenzih eder Allah''ı, ne varsa göklerde ve ne varsa yeryüzünde ve odur üstün, hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 2, 'Ey inananlar, ne diye yapmayacağınız şeyi söylersiniz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 3, 'Allah katında en nefret edilen şey, yapmayacağınız şeyi söylemenizdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 4, 'Şüphe yok ki Allah, kendi yolunda, yanyana, kurşunla kenetlenip kurulmuş bir duvar gibi saf kurarak savaşanları sever.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 5, 'Ve an o zamanı ki hani Musa, kavmine, ey kavmim demişti, ne diye beni incitirsiniz ve gerçekten de bilirsiniz ki ben, şüphe yok ki Allah''ın gönderdiği peygamberim size; derken onlar, eğrilince Allah da gönüllerini gerçekten batıla meylettirdi ve Allah, buyruktan çıkan topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 6, 'Ve an o zaman ki hani Meryem oğlu İsa, ey İsrailoğulları demişti, şüphe yok ki ben, size, elimdeki Tevrat''ı gerçekleyen ve benden sonra gelecek ve adı Ahmed olacak bir peygamberi müjdeleyen Allah elçisiyim; fakat o, onlara, apaçık delillerle gelince bu dediler, apaçık bir büyü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 7, 'Ve Müslümanlığa çağrıldığı halde yalan yere Allah''a iftira edenden daha zalim kimdir ki? Ve Allah, zalim topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 8, 'Allah nurunu, ağızlarıyla üfleyip söndürmek isterler ve Allah''sa nurunu tamamlayacak, kuvvetlendirecektir ve isterse kafirlerin zoruna gitsin, istemesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 9, 'O, bir mabuttur ki Peygamberini, müşrikleri istemese de dini, bütün dinlere üst olsun diye doğru yolla ve gerçek dinle göndermiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 10, 'Ey inananlar, size bir alışveriş haber vereyim mi ki elemli azaptan kurtarsın sizi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 11, 'İnanırsanız Allah''a ve Peygamberine ve savaşırsanız Allah yolunda mallarınızla, canlarınızla; işte bu, bilseniz, size daha da hayırlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 12, 'Suçlarınızı örter ve sizi, kıyılarından ırmaklar akan cennetlere ve ebedi Adn cennetlerinde tertemiz evlere sokar; bu, pek büyük bir kurtuluş, kutluluk ve murada eriştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 13, 'Ve başka bir şey daha var ki seversiniz: Yardım ve zafer Allah''tan ve pek yakın bir fetih; ve müjdele inananları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (61, 14, 'Ey inananlar, Allah''ın yardımcıları olun, nitekim Meryem oğlu İsa da Havariyyun''a, Allah yolunda yardımcılarım kimdir demişti, Havariyyun, biziz Allah''ın yardımcıları demişlerdi; derken İsrailoğullarından bir bölük inanmıştı, bir bölük de kafir olmuştu; derken biz, inananları, düşmanlarına karşı kuvvetlendirmiştik de üst gelmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 1, 'Tenzih eder ne varsa göklerde ve ne varsa yeryüzünde; her şeye sahip ve mutasarrıf olan, ayıplardan ve noksanlardan arı bulunan üstün, hüküm ve hikmet sahibi Allah''ı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 2, 'O, bir mabuttur ki Mekkeliler içinden, kendi cinslerinden bir peygamber göndermiştir; onlara ayetlerini okumaktadır ve onları tertemiz bir hale getirmektedir ve onlara kitabı ve şeriatlerin hikmetlerini öğretmektedir ve bundan önce onlar, elbette apaçık bir sapıklık içindeydiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 3, 'Ve onlardan başkalarına ki henüz onlara katılmamışlardır ve odur üstün olan hüküm ve hikmet sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 4, 'Bu, Allah''ın lütufudur, ihsanıdır, dilediğine verir onu ve Allah, pek büyük bir lütuf ve ihsan sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 5, 'Kendilerine Tevrat yüklenenler, sonra da onunla amel etmeyenler, eşşeğe benzerler ki kocakoca kitaplar taşımada; Allah''ın delillerini yalanlayan topluluğa getirilen örnek, ne de kötü bir örnek ve Allah, zalim topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 6, 'De ki: Ey Yahudi olanlar, eğer gerçekten de öbür insanlar hariç, kendinizi, Allah''ın dostları sanıyorsanız, sözünüz doğruysa isteyin ölümü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 7, 'Ve ebediyen istiyemezler onu, elleriyle hazırladıkları şeyler yüzünden ve Allah, zalimleri bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 8, 'De ki: Gerçekten de ondan kaçıp durduğunuz ölüm yok mu; hiç şüphe yok ki size ulaşacaktır o da sonra gizliyi de, görüneni de bilen mabudun tapısına götürüleceksiniz, derken size, bütün yaptıklarınızı haber verecek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 9, 'Ey inananlar cuma günü namaz için nida edilince size, hemen Allah''ı anmaya koşun ve bırakın alışverişi; bu, daha da hayırlıdır size bilirseniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 10, 'Namazı kıldınız mı da artık yeryüzüne dağılın ve Allah''ın lutfunu, ihsanını arayın ve çok anın Allah''ı da kurtulup murada erin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (62, 11, 'Ve onlar, bir alışveriş, yahut eğlence görünce ona gidip dağıldılar ve seni ayakta bıraktılar; de ki: Allah''ın katındaki daha da hayırlıdır alışverişten ve eğlenceden ve Allah, rızık verenlerin en hayırlısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 1, 'Münafıklar, sana gelince, tanıklık ederiz ki dediler, sen, şüphe yok, elbette Allah''ın peygamberisin ve Allah bilir ki şüphe yok, sen, onun peygamberisin ve Allah tanıklık eder ki şüphe yok, münafıklar, elbette yalancılardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 2, 'Antlarını kalkan edinmişler de halkı, Allah yolundan çıkarmışlardır; şüphe yok ki ne de kötüdür bu yaptıkları şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 3, 'Bu da, hiç şüphesiz, inandıklarından, sonra kafir olduklarındandır; derken Allah, gönüllerini mühürlemiştir; gerçekten de onlar, anlamayan bir topluluktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 4, 'Ve onları gördün mü, bedenleri hoşuna gider; ve konuşurlarsa sözlerini dinlersin; sanki onlar, dayanmış kerestelerdir; her bağrışı, kendi aleyhlerine sanırlar; onlar düşmandır, artık sakın onlardan, Allah gebertsin onları, nelere de kapılıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 5, 'Ve onlara, gelin de Allah''ın Peygamberi size yarlıganma dilesin denirse başlarını sallarlar alay ederek ve görürsün ki ululuk satarak dönüp gitmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 6, 'Birdir onlara, yarlıganmalarını dilesen de, yahut dilemesen de; Allah kesin olarak yarlıgamaz onları; şüphe yok ki Allah, buyruktan çıkmış topluluğu doğru yola sevketmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 7, 'Onlar, öyle kişilerdir ki Allah''ın Peygamberinin yanında olanlara bir şey vermeyin de derler, sonunda dağılıp gitsinler ve Allah''ındır hazineleri göklerin ve yeryüzünün ve fakat münafıklar, anlamazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 8, 'Derler ki: Medine''ye dönünce andolsun ki üstün olan, elbette aşağılık kişiyi çıkarır oradan ve Allah''ındır üstünlük ve Peygamberinin ve inananların ve fakat münafıklar, bilmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 9, 'Ey inananlar, sizi alıkoymasın mallarınız ve evlatlarınız, Allah''ı anmadan ve kim, bunu yaparsa artık onlardır ziyana uğrıyanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 10, 'Ve birinize ölüm gelip çatmadan ve derken o da Rabbim, beni yakın bir zamanadek öldürmeyip bıraksaydın da ben de sadaka vermeye çalışsaydım ve temiz kullardan olsaydım demeden önce sizi rızıklandırdığımız şeylerden harcayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (63, 11, 'Ve Allah, mukadder zamanı geldi mi hiç kimseyi geri bırakmaz kesin olarak ve Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 1, 'Tenzih eder Allah''ı, ne varsa göklerde ve ne varsa yeryüzünde, onundur saltanat ve tedbir ve onadır hamd ve onun, her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 2, 'O, öyle bir mabuttur ki sizi yaratmıştır da sizden kafir olan da vardır, inanan da ve Allah, ne yapıyorsanız görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 3, 'Yaratmıştır gökleri ve yeryüzünü gerçek olarak ve size suret vermiştir ve suretinizi de en güzel bir tarzda meydana getirmiştir ve sonunda da dönülüp gidilecek yer, onun tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 4, 'Bilir ne varsa göklerde ve ne varsa yeryüzünde ve bilir neyi gizlerseniz ve neyi açığa vurursanız ve Allah, gönüllerde olanı da bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 5, 'Daha önce kafir olanların haberi gelmedi mi size? Yaptıkları işin vebalini tattılar ve onlara elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 6, 'Bu da, peygamberlerinin, apaçık delillerle onlara geldikleri halde onların, bir insan mı bize doğru yolu gösterecek deyip de kafir olmalarından ve yüz çevirmelerindendir ve Allah da onlardan müstağni olduğunu göstermiştir ve Allah, müstağnidir ve hamde layık, odur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 7, 'Kafir olanlar, sanırlar ki öldükten sonra dirilmeyecekler kesin olarak; de ki: Evet ve Rabbime andolsun ki elbette dirileceksiniz, sonra da ne yaptıysanız size haber verilecek ve bu, Allah''a pek kolaydır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 8, 'Artık inanın Allah''a ve Peygamberine ve indirdiğimiz nura ve Allah, ne yapıyorsanız hepsinden de haberdardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 9, 'O gün, sizi toplantı günü için bir araya getirecektir ve bugün, aldananın, aldatanın, kar ve ziyan edenin meydana çıkacağı gündür ve kim inanırsa Allah''a ve iyi işlerde bulunursa onun kötülüklerini örter ve kıyılarından ırmaklar akan cennetlere, ebedi kalmak üzere sokar onu; bu, pek büyük bir kurtuluş, kutluluk ve murada eriştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 10, 'Ve kafir olan ve delillerimizi yalanlayanlarsa cehennemliklerdir, ebedi kalırlar orada ve orası, dönüp varılacak ne kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 11, 'Hiçbir felaket, Allah''ın izni olmadıkça gelip çatmaz ve kim inanırsa Allah''a, o da, onun gönlüne doğru yolu ilham eder ve Allah, her şeyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 12, 'Ve itaat edin Allah''a ve Peygambere; yüz çevirecek olursanız artık Peygamberimize düşen vazife, ancak apaçık tebliğden ibarettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 13, 'Bir Allah''tır ki yoktur ondan başka tapacak ve artık Allah''a dayansın inananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 14, 'Ey inananlar, şüphe yok ki eşlerinizin ve evlatlarınızın bazısı, düşmandır size, artık sakının onlardan ve bağışlar ve yüzlerine vurmaz ve suçlarını örterseniz artık bilin ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 15, 'Mallarınız ve evlatlarınız, bir sınamadır size ancak ve Allah katındaysa pek büyük bir mükafat var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 16, 'Artık çekinin Allah''tan gücünüz yettiği kadar ve dinleyin ve itaat edin ve mallarınızı harcayın hayır yolunda, sizin için hayırlıdır ve kimler, nefsinin hırsından, nekesliğinden korunursa artık onlardır kurtulanların, muratlarına erenlerin ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 17, 'Eğer Allah''a güzel bir tarzda borç verirseniz o, verdiğinizi katkat arttırır size ve suçlarınızı örter ve Allah, iyilik edenlere fazlasıyla mükafat verir, azaplandırmada da aceleci değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (64, 18, 'Gizliyi de bilir, görüneni de, üstündür, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 1, 'Ey Peygamber, kadınları boşayacağınız zaman temiz oldukları vakit boşayın ve müddetlerini sayın ve çekinin Rabbiniz Allah''tan; çıkarmayın onları evlerinden ve onlar da çıkmasınlar, ancak apaçık bir çirkin harekette bulunurlarsa o başka ve işte bunlardır Allah''ın sınırları ve kim Allah''ın sınırlarını aşarsa gerçekten de kendisine zulmeder; bilmezsin, belki de Allah, bundan sonra bir iş çıkarıverir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 2, 'Müddetlerini tamamlayınca da onları güzellikle alın, yahut da güzellikle ayrılın onlardan ve sizden iki tane adalet sahibi tanığı bulundurun da tanıklık etsinler ve tanıklığı da Allah için doğru yapın; işte Allah''a ve ahiret gününe inanana böylece öğüt verilmededir; ve kim, çekinirse Allah''tan, ona sıkıntıdan bir kurtuluş vesilesi yaratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 3, 'Ve onu, hesaplamadığı yerden rızıklandırır ve kim Allah''a dayanırsa o, yeter ona; şüphe yok ki Allah, yapacağı işi yerine getirir, gerçekten de Allah, her şeye bir ölçü, bir miktar tayin etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 4, 'Kadınlarınızdan adetten kesilmişlerin, kesilip kesilmedikleri hakkında şüpheye düşerseniz müddetleri, üç aydır ve adet görmeyenlerin de böyle ve gebe olanların müddeti, çocuklarını doğuruncaya dek ve kim çekinirse Allah''tan, onun işine bir kolaylık verir o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 5, 'Budur Allah''ın emri ki size indirmiştir onu ve kim, çekinirse Allah''tan, onun kötülüklerini örter ve mükafatını büyültür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 6, 'Onları, gücünüz yeterse oturduğunuz yerin bir kısmında oturtun ve onları sıkıştırarak zararlandırmayın ve gebeyseler doğuruncaya dek doyurun onları ve çocuklarınızı emziriyorlarsa da artık ücretlerini verin ve karıkoca; güzelce danışıp görüşerek yapın bu işleri ve bir güçlük çıkarsa çocuğu başka bir kadın emzirir artık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 7, 'Vaktihali yerinde ve eli geniş olan, vaktinehaline göre nafaka versin ve rızkı dar olana gelince, Allah, kendisine ne verirse onun bir kısmını nafaka olarak versin; Allah, hiç kimseye, kendi verdiği miktardan daha fazla bir şey teklif etmez; Allah, güçlükten sonra bir kolaylık verecektir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 8, 'Nice şehirler var ki halkı, Rablerinin ve onun peygamberlerinin emirlerine karşı gelmiştir de onları, çetin bir surette hesaba çekmişizdir ve onları helak ederek azaplandırmışızdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 9, 'Derken yaptıklarının vebalini tatmışlardır da işlerinin sonu, ziyan olup gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 10, 'Allah onlara çetin bir azap da hazırlamıştır, artık çekinin Allah''tan ey aklı başında olanlar; ey iman edenler, andolsun ki Allah, size bir öğüt olan Kur''an''ı indirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 11, 'Peygamberi de göndermiştir ki size Allah''ın apaçık ayetlerini okumadadır inananları ve iyi işlerde bulunanları karanlıklardan aydınlığa çıkarmak için ve kim, Allah''a inanır ve iyi işlerde bulunursa onu, ebedi kalmak üzere, kıyılarından ırmaklar akan cennetlere koyar, gerçekten de Allah, ona en güzel bir rızık verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (65, 12, 'Bir Allah''tır ki yaratmıştır yedi göğü ve yeryüzünü de onun misli olarak yedi kat halketmiştir; bunların arasında, emri, inip durmadadır Allah''ın, şüphesiz, her şeye gücü yettiğini bilmeniz ve şüphe yok ki Allah''ın bilgisinin, gerçekten de her şeyi kavradığını, kuşattığını anlamanız için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 1, 'Ey Peygamber, eşlerinin razılığını arayarak ne diye Allah''ın sana helal ettiğini kendine haram etmedesin ve Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 2, 'Gerçekten de Allah, kefaretle yeminlerinizi bozmanızı, size meşru etmiştir ve Allah''tır yardımcınız ve odur bilen ve rahim olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 3, 'Ve hani Peygamber, eşlerinden birine gizli bir şey söylemişti de o, bu sözü, başkasına haber verince ve Allah da bunu, Peygambere açınca Peygamber, bu olayın bir kısmını söylemiş, bir kısmındansa vazgeçmiş, söylememişti. Peygamber, bunu eşine haber verince o, kim haber verdi bunu sana demişti, o da demişti ki: Her şeyi bilen haber verdi bana, her şeyden haberdar olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 4, 'İkiniz de tövbe ederseniz Allah''a; çünkü gerçekten de gönülleriniz suça meyletmiştir; ve fakat Peygamberin aleyhine, birbirinize arka verirseniz artık o Allah''tır onun yardımcısı ve Cibril''dir ve inananların en temizi ve melekler de bunlardan sonra ona arkadır, yardımcıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 5, 'Umulur ki sizi boşarsa Rabbi ona, sizin yerinize sizden de hayırlı Müslüman, inanmış itaatli, tövbekar, ibadette bulunan, ömrünü itaatle geçiren dul ve kız eşler verir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 6, 'Ey inananlar, koruyun kendinizi ve ailenizi o ateşten ki yakacağı şeyler, insanlardır ve kibrit taşlarıyla da harareti ve alevi çoğalıp durur, kalpleri katı ve kuvvetli melekler de ona memurdur ki Allah ne emrettiyse isyan etmezler ve emredildikleri şeyi işlerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 7, 'Ey kafir olanlar, bugün özür getirmeyin; ancak ne yaptıysanız onun karşılığıyla cezalanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 8, 'Ey inananlar, tövbe edin Allah''a halis bir tövbeyle; umulur ki Rabbiniz; kötülüklerinizi örter ve sizi, kıyılarından ırmaklar akan cennetlere sokar, o gün Allah, Peygamberi ve inananlardan onunla beraber bulunanları horlamaz, nurları, önlerinde ve sağ yanlarında koşar, parlar da Rabbimiz derler, nurumuzu tamamla, kuvvetlendir bize ve ört suçlarımızı bizim, şüphe yok ki senin, her şeye gücün yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 9, 'Ey Peygamber, savaş kafirlerle ve münafıklarla ve sert davran onlara ve yurtları cehennemdir onların ve orası, dönülüp gidilecek ne kötü yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 10, 'Allah, kafir olanlara, Nuh''un karısıyla ve Lut''un karısıyla örnek getirmededir; ikisi de, temiz kullarımızdan ikisinin nikah altındaydı, derken onlara karşı hainlikte bulundular da o iki temiz kul, hiçbir suretle onları kurtaramadı Allah''ın cezasından ve onlara girin denildi ateşe, girenlerle beraber.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 11, 'Ve gene Allah, inananlara, Firavun''un karısını örnek getirmede; hani Rabbim demişti, bana cennette bir ev kur ve beni kurtar Firavun''dan ve yaptığı şeyden ve beni kurtar zalim topluluktan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (66, 12, 'Ve İmran kızı Meryem''le örnek getirmede ki o, ırzını korumuştu, derken biz, ona ruhumuzdan üfürmüştük ve Rabbinin sözlerini ve kitaplarını gerçekleştirmişti ve o, itaat edenlerdendi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 1, 'Saltanat, tasarruf ve tedbir, elinde olan mabudun şanı yücedir, münezzehtir ve onun her şeye gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 2, 'Öyle bir mabuttur ki yaratmıştır ölümü ve dirimi, hanginiz daha güzel işte bulunacak, sınamak için sizi ve odur üstün olan ve suçları örten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 3, 'Öylesine ki birbiri üstünde olarak yedi kat göğü yaratmıştır; rahmanın yaratışında hiçbir uygunsuzluk, aykırılık göremezsin; artık çevir gözünü de bak, görebilir misin bir yarık, bir çatlak?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 4, 'Gene de gözünü çevir de bir daha, bir daha bak; aradığını bulamaz da gözün, mahrum bir halde sana döner ve yorgundur o, bitkindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 5, 'Ve andolsun ki biz, en yakın olan dünya göğünü ışıklarla bezedik ve onları, Şeytanlara atılacak şeyler olarak halkettik ve Şeytanlara, yakıp kavuran bir azaptır, hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 6, 'Ve Rablerine kafir olanlara cehennem azabı var ve cehennem, dönülüp varılacak ne de kötü yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 7, 'Oraya atıldılar mı duyarlar ki cehennem, kesikkesik nefes almada ve coşup kaynıyor o.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 8, 'Neredeyse hışmından patlayıp dağılacak; ona, her bölük atıldıkça muhafız memurları onlara sorarlar: Size bir korkutucu gelmedi mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 9, 'Evet derler, andolsun ki geldi bize korkutucu da yalanladık onu ve Allah dedik, hiçbir şeyi indirmemiştir; siz ancak, pek büyük bir sapıklığa düşmüşsünüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 10, 'Ve eğer derler, duysaydık, yahut akıl etseydik yakıp kavuran cehennem ehli olmazdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 11, 'Derken suçlarını söylerler; artık ırak olsun yakıp kavuran cehennemin ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 12, 'Şüphe yok ki görmedikleri halde Rablerinden korkanlaradır yarlıganma ve pek büyük bir mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 13, 'Ve sözünüzü gizli tutun, yahut açığa vurun onu, şüphe yok ki o, gönüllerde olanı bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 14, 'Hiç bilmez mi yaratan ve odur kullarına lutfeden ve her şeyden haberdar olan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 15, 'O, öyle bir mabuttur ki yeryüzünü, size karşı aşağı gönüllü, münkat ve sakin bir halde yaratmıştır, köşesinde, bucağında dolaşın artık ve yiyin mabudunuzun rızkından ve dönüp gideceğiniz yer, gene onun tapısıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 16, 'Kudreti ve emri, gökte bulunan, yüce olan mabudun, sizi yerle beraber batırmayacağından emin misiniz? O vakit görürsün ki o sakin yeryüzü, çalkanıp durmada, titreyip kıvranmada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 17, 'Yoksa kudreti ve emri; gökte bulunan, yüce olan mabudun, size taşlar yağdıran bir rüzgar yollamayacağından emin misiniz? Derken yakında bilirsiniz nasılmış benim korkutmam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 18, 'Ve andolsun ki onlardan öncekiler de yalanlamışlardı, derken nasıl da gelip çattı azabım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 19, 'Görmezler mi üstlerinde uçan kuşları? Kanatlarını açmada ve kapamada onlar, onları gökte, ancak rahman tutmada, şüphe yok ki o, her şeyi görür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 20, 'Yoksa sizi rahmandan kurtaracak ordunuz mu var? Kafirler, ancak bir aldanışa dalmışlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 21, 'Yoksa kimdir o ki mabudunuz, rızkınızı kısarsa sizi rızıklandıracak? Hayır, onları, azgınlık içinde, gerçekten tamamıyla uzak bir halde inat edip durmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 22, 'Artık yüzüstü sürünerek giden mi daha ziyade doğru yolu bulur, yoksa doğru yolda dümdüz giden mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 23, 'O, öyle bir mabuttur ki sizi meydana getirmiştir ve sizin için kulak ve gözler ve gönüller halketmiştir, ne de az şükredersiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 24, 'De ki: O, öylesine bir mabuttur ki sizi yaratmıştır yeryüzünde ve gene de tapısında toplanacaksınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 25, 'Ve derler ki: Bu vait, ne vakit yerine gelecek doğru söylüyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 26, 'De ki: Bilgi, ancak Allah katındadır ve ben, ancak apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 27, 'Azabın yaklaştığını gördüler mi kafir olanların yüzleri kararır ve işte denir, bu, isteyip durduğunuz şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 28, 'De ki: Haber verin bana, Allah beni ve benimle beraber olanları helak etse, yahut da bize acısa bile kim kurtaRabilir kafirleri elemli azaptan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 29, 'De ki: Odur rahman, ona inandık ve ona dayandık; artık yakında bilirsiniz, kimdir apaçık sapıklıkta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (67, 30, 'De ki: Haber verin bana, suyunuz, tamamıyla batıp çekiliverse artık kimdir size bir akarsu pınarı peydahlayacak?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 1, 'Nun, andolsun kaleme ve yazdıklarına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 2, 'Sen, Rabbinin nimeti sayesinde deli değilsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 3, 'Ve sana, tükenmez, minnetsiz bir mükafat var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 4, 'Ve şüphe yok ki sen, pek büyük bir ahlaka sahipsin elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 5, 'Yakında sen de görürsün ve onlar da görürler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 6, 'Deliliğe uğramış hanginiz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 7, 'Şüphe yok ki Rabbin, kendi yolundan sapanı da daha iyi bilir ve o, doğru yolu bulanları da daha iyi bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 8, 'Artık yalanlayanlara itaat etme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 9, 'Onlara yumuşaklık göstermeni arzularlar, öyle hareket etsen onlar da yumuşaklık gösterirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 10, 'Ve itaat etme çok yemin edenlerin, reyinde isabet bulunmayanların hiçbirine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 11, 'Ayıp arayan, kovucu ve söz getirip götürücüyle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 12, 'Hayrı tamamıyla meneden haddini aşmış suçluya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 13, 'Ayrıca da çirkin ve kötü huylu soysuza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 14, 'Malmülk ve evlat sahibi bile olsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 15, 'Ona ayetlerimizi okuyunca eskilere ait masallar dedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 16, 'Büyüyüp bir hortuma dönen burnuna, yakında bir damga vururuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 17, 'Ve biz, onları açlıkla, kıtlıkla sınarız, nitekim o bahçe sahiplerini de sınamıştık; hani, sabahleyin erkenden, bahçelerindeki mahsulü kesmeye ant içmişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 18, 'Ve Tanrı dilerse de dememişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 19, 'Halbuki bahçenin üstünde, Rabbinden gelen bir felaket dolaşmadaydı ki onlar uyuyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 20, 'Derken bahçe, bütün mahsulü kesilip biçilmiş, kupkuru çorak bir yere, bir çöle dönmüştü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 21, 'Sabahleyin birbirlerine sesleniyorlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 22, 'Mahsulünüzü kesip devşirecekseniz erkence koşun, gidin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 23, 'Derken yola düştüler ve birbirlerine de gizlice diyorlardı ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 24, 'Bugün hiçbir yoksula yol vermeyin, yanınıza gelmesin sakın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 25, 'Ve kendilerini, yoksulları men etmeye güçleri yeter sanarak erkenden gittiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 26, 'Bahçeyi görünce gerçekten de dediler, elbette yolumuzu şaşırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 27, 'Hayır dediler, biz mahrum olup gitmişiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 28, 'İçlerinden en iyileri, ben demedim miydi size dedi, mabudunuzu tenzih etseniz ne olurdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 29, 'Dediler ki: Şanı yücedir Rabbimizin, gerçekten de zalimlerden olduk biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 30, 'Bir birlerine dönerek birbirlerini kınamaya başladılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 31, 'Yazıklar olsun bize dediler, gerçekten de azmışız biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 32, 'Umulur ki Rabbimiz, onun yerine bize daha da hayırlısını verir, gerçekten de biz, Rabbimizi dilemede, ondan istemedeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 33, 'İşte bunun gibidir azap ve elbette ahiret azabı, daha da büyüktür bilirseniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 34, 'Şüphe yok ki çekinenlere, Rableri katında Naim cennetleri var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 35, 'Artık Müslümanları da suçlularla bir mi tutacağız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 36, 'Ne oldu size ki? Nasıl hükmediyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 37, 'Yoksa size mahsus bir kitap var da oradan mı okuyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 38, 'Orada, neyi beğenir, isterseniz sizindir diye mi yazılı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 39, 'Yoksa hükmü kıyametedek sürecek antlar mı ettik size, şüphe yok ki ne buyurursanız o olacak sizin için diye?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 40, 'Onlara sor, bunlara kefil olan kimmiş içlerinden?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 41, 'Yoksa ortakları mı var? Doğru söylüyorlarsa gelsinler bakalım ortaklarıyla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 42, 'O gün, işler güçleşir ve secdeye davet edilirler, derken güçleri yetmez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 43, 'Gözleri yere dikilir, üstlerine aşağılık çöker ve gerçekten de sağ esenken de secdeye davet edilmişlerdir de secde etmemişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 44, 'Artık sen, bu sözü yalanlayanı bırak bana, biz onları yavaşyavaş, hiç bilmedikleri yerden cehenneme çekerdururuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 45, 'Ve onlara mühlet vermedeyim, fakat şüphe yok ki azabım, pek kuvvetlidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 46, 'Yoksa onlardan ücret istiyorsun da derken onlar da ağır bir borç altında mı kaldılar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 47, 'Yoksa gizli alem, onların yanında da onu mu yazıyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 48, 'Artık sabret Rabbinin hükmüne ve balıkla arkadaş olana benzeme; hani o, dertten boğulmuş bir halde Rabbine nida etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 49, 'Rabbinden bir nimet erişmeseydi ona elbette bir yere, fena bir halde bırakılır giderdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 50, 'Derken Rabbi, onu seçti de temiz kişilerden kıldı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 51, 'Ve az kalmıştı ki kafirler, Kur''an''ı duydukları zaman seni gözleriyle yiyip helak etsinler ve derlerdi ki: Şüphe yok, bu, bir deli elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (68, 52, 'Halbuki o, ancak alemlere bir öğüttür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 1, 'Gerçek olan kıyamet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 2, 'Nedir gerçek olan kıyamet?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 3, 'Ve nedir bildiren sana ki nedir gerçek kıyamet?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 4, 'Yalanladı Semud ve Âd, insanların başına kopan, akıllarını dağıtan kıyameti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 5, 'Derken Semud, helak edildi taşkınlığıyla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 6, 'Ve ama Âd, helak edildi müthiş bir ses çıkaran, yıkıp götüren, silip süpüren soğuk bir kasırgayla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 7, 'Onu, yedi gece ve sekiz gün, birbiri ardınca musallat etti onlara, o topluluğa baksaydın görürdün ki bu kadar zaman içinde yıkılıvermişler yerlere, sanki içleri kof hurma kütükleriymiş onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 8, 'Artık görebilir misin, var mı onlardan kalanlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 9, 'Ve Firavun ve ondan önce şehirleri altüst olanlar da suçlar işlemişlerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 10, 'Derken Rablerinin peygamberine isyan etmişlerdi de onları gittikçe artan bir azapla helak etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 11, 'Şüphe yok ki akıp giden gemide taşıdık sizi sular köpürüp coşunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 12, 'Bu, size bir öğüt ve ibret olsun ve belleyip unutmayan kulaklarda kalsın diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 13, 'Sura bir kerecik üfürülünce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 14, 'Ve yeryüzü ve dağlar, bir kerecik birbirlerine çarpıp dağılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 15, 'İşte o gün ansızın kopacak kıyamet kopar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 16, 'Ve gök yarılır, o gün bitkin bir hale gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 17, 'Melekler, etrafında toplanırlar ve Rabbinin arşını o gün, onların üstünde, sekiz melek taşır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 18, 'O gün ahvaliniz öylesine meydana çıkarılır ki hiçbir şeyiniz gizli kalmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 19, 'Derken kimin kitabı, sağ yanından verilirse artık der ki: Gelin, işte okuyun kitabımı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 20, 'Zaten ben biliyordum ki kıyamet günü kavuşacağım hesabıma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 21, 'Artık o, razı olduğu bir yaşayış, bir zevk içindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 22, 'Yüce cennettedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 23, 'Meyveleri pek yakındır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 24, 'Yiyin için, afiyetler olsun, geçmiş günlerdeki yaptıklarınızın karşılığı olarak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 25, 'Ve ama kimin kitabı, sol yanından verilirse artık der ki: Keşke verilmeseydi kitabım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 26, 'Ve keşke bilmeseydim, nedir hesabım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 27, 'Keşke ölümle olup bitseydi her işim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 28, 'Bir fayda vermedi bana mallarım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 29, 'Helak olup gitti gücümkuvvetim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 30, 'Tutun onu da zincirle bağlayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 31, 'Sonra koca cehenneme atın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 32, 'Sonra da onu, boyu yetmiş zira, bir zincire vurun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 33, 'Şüphe yok ki o, pek ulu Allah''a inanmazdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 34, 'Ve yoksulun yiyeceğine bakmazdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 35, 'Artık bugün, ona, burada bir dost yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 36, 'Ve irinden başka bir yemek de yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 37, 'Onu da ancak suçlular yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 38, 'Artık iş, sizin sandığınız gibi değil, andolsun gördüğünüze.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 39, 'Ve görmediğinize.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 40, 'Şüphe yok ki bu, kerem sahibi bir elçinin sözü elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 41, 'Ve bu, şair sözü değil, ne de az inanırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 42, 'Ve kahin sözü de değil, ne de az düşünürsünüz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 43, 'Âlemlerin Rabbinden indirilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 44, 'Ve eğer bize isnad ederek bazı laflar etseydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 45, 'Elbette onu kudretimizle alırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 46, 'Sonra da elbette şah damarını çeker koparırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 47, 'Artık buna mani olamazdı sizden hiçbir kimsecik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 48, 'Ve şüphe yok ki Kur''an, çekinenlere öğüttür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 49, 'Ve şüphe yok ki biz, elbette biliriz, sizden, yalanlayanlar vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 50, 'Ve şüphe yok ki Kur''an, kafirlere adeta bir hasrettir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 51, 'Ve şüphe yok ki o, elbette gerçeğin ta kendisidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (69, 52, 'Artık pek ulu Rabbinin adını anarak tenzih et onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 1, 'İsteyen biri, istedi gelip çatacak azabı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 2, 'O azabı ki kafirlerin başından defedecek yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 3, 'Yüksek dereceler sahibi Allah''tandır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 4, 'Melekler ve Ruh, kendilerine emredilen yere çıkarlar bir günde ki miktarı elli bin yıldır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 5, 'Artık sabret güzel bir sabırla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 6, 'Şüphe yok ki onlar uzak görürler onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 7, 'Ve bizse pek yakın görürüz onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 8, 'O gün gök, yağ tortusuna döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 9, 'Ve dağlar, atılmış renkrenk pamuğa benzer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 10, 'Ve hiçbir dost, dostunu sormaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 11, 'Birbirlerini görüp tanırlar da ve suçlu, o günün azabına karşılık oğlunu da vermek ister.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 12, 'Eşini de, kardeşini de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 13, 'Kendisini barındıran kabile halkını da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 14, 'Ve kim varsa yeryüzünde hepsini de feda etmek ve sonra da kendini kurtarmak ister.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 15, 'Fakat imkanı yok; şüphe yok ki cehennem alevalev yanmadadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 16, 'Ne el bırakmadadır, ne ayak, ne et bırakmadadır, ne deri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 17, 'Çağırır dönüp gideni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 18, 'Ve toplayıp biriktireni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 19, 'Şüphe yok ki insan haris yaratılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 20, 'Bir şerre uğrarsa bağırır, sızlanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 21, 'Ve bir hayır elde ederse vermez, kıskanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 22, 'Ancak müstesnadır namaz kılanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 23, 'Öylesine kılanlar ki namazlarını daima kılarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 24, 'Ve öyle kişilerdir onlar ki mallarında malum bir hak var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 25, 'İsteyene ve mahrum olana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 26, 'Ve öyle kişilerdir onlar ki ceza gününü gerçek bilirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 27, 'Ve öyle kişilerdir onlar ki Rablerinin azabından korkarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 28, 'şüphe yok ki Rablerinin azabından da kimse emin olamaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 29, 'Ve öyle kişilerdir onlar ki ırzlarını korurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 30, 'Ancak eşleri ve temellük ettikleri müstesna ve artık bu hususta da kınanmazlar onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 31, 'Bunlarda başkasını isteyenlere gelince, onlardır haddi aşanların ta kendileri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 32, 'Ve öyle kişilerdir onlar ki emanetlerine ve ahitlerine riayet ederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 33, 'Ve öyle kişilerdir onlar ki tanıklıklarında doğrudurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 34, 'Ve öyle kişilerdir onlar ki namazlarını korurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 35, 'İşte onlardır cennetlerde ağırlananlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 36, 'Ne oluyor kafirlere ki sana doğru koşmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 37, 'Sağdan ve soldan parçaparça ve bölükbölük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 38, 'Onların her biri, Naim cennetine sokulacaklarını mı umuyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 39, 'Fakat imkanı yok; şüphe yok ki biz, onları, onların da bildikleri şeyden yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 40, 'Andolsun doğuların Rabbine ve batıların Rabbine, gerçekten de bizim gücümüz yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 41, 'Onlardan daha hayırlısını, yerlerine geçirmeye ve kimse önümüze geçemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 42, 'Bırak artık onları dalsınlar daldıklarına ve oynasınlar oynadıklarıyla, kendilerine vaadedilen güne kavuşuncaya dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 43, 'O gün, kabirlerinden çıkarlar da koşmaya başlarlar, sanki dikilmiş hedeflere yelmedeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (70, 44, 'Gözleri yerde, üstlerine aşağılık çökmüş; işte onlara vaadedilen gün, bugündür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 1, 'Şüphe yok ki biz, onlara elemli bir azap gelmeden korkut kavmini diye göndermiştik Nuh''u, kavmine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 2, 'Demişti ki: Ey kavmin, ben, sizi apaçık bir korkutucuyum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 3, 'Gayrı kulluk edin Allah''a ve çekinin ondan ve itaat edin bana da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 4, 'Suçlarınızı yarlıgasın ve sizi, muayyen bir vaktedek geciktirsin. Şüphe yok ki Allah''ın takdir ettiği vakit geldi mi gecikmesine imkan yoktur eğer biliyorsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 5, 'Rabbim demişti, ben kavmimi gece ve gündüz çağırdım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 6, 'Benim çağırmam, ancak onların kaçmasını arttırdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 7, 'Ve gerçekten de ben, onları, sen yarlıgayasın, suçlarını örtesin diye ne vakit çağırdıysam parmaklarıyla kulaklarını tıkadılar ve elbiselerine büründüler ve ısrar ettiler ve ululandıkça ululanmaya kalkıştılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 8, 'Sonra onları, gerçekten de yüksek sesle çağırdım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 9, 'Sonra açığa vurup yaydım onlara ve gizlice konuştum, davet ettim onları da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 10, 'Dedim ki: Rabbinizden yarlıganma dileyin, şüphe yok ki o, bütün suçları, tamamıyla örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 11, 'Size gökten faydalı ve bol yağmurlar yollar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 12, 'Ve size, mallar, oğullar vererek yardım eder ve size bağlar, bahçeler halk eder ve ırmaklar yaratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 13, 'Ne oldu size ki Allah''ın, büyük, ulu ve şerefli bir mabud olduğunu ummuyorsunuz?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 14, 'Ve halbuki o, sizi haldenhale koyarak halk etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 15, 'Görmez misiniz Allah, nasıl da gökleri yedi kat yaratmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 16, 'Ve o göklerde, aya bir ışık vermiş ve güneşi de, her yanı aydınlatan bir çırağ olarak halk etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 17, 'Ve Allah, yeryüzünden size nebatlar bitirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 18, 'Sonra da sizi gene oraya yollar ve oradan çıkarır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 19, 'Ve Allah, yer yüzünü size bir döşeme, bir yaygı olarak yaratmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 20, 'Oradaki genişgeniş yollara dalıp gidin diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 21, 'Nuh demişti ki: Rabbim, şüphe yok ki onlar, bana isyan ettiler ve malı ve evladı, ancak ziyanını arttırıp duran kişiye uydular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 22, 'Ve pek büyük düzenler kurmaya giriştiler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 23, 'Ve sakın dediler, mabutlarınızı bırakmayın, hele ne Vedd''i bırakın, ne Suva''ı, ne de Yaguus''u ve Yauk''u ve Nesr''i.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 24, 'Ve andolsun ki bunlar, birçok kişileri doğru yoldan çıkardılar ve zalimlerin, ancak sapıklığını arttır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 25, 'Suçları yüzünden de bunlar, sulara boğuldular da ateşe atıldılar, derken Allah''tan başka bir yardımcı da bulamadılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 26, 'Ve Nuh, demişti ki: Rabbim, yeryüzünde kafirlerden bir tek kişi bile bırakma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 27, 'Şüphe yok ki onları bırakacak olursan kullarını yoldan çıkarırlar ve ancak gerçekten sapan ve iyiden iyiye kafir olan evlatlar yetiştirirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (71, 28, 'Rabbim, benim suçlarımı ört ve anamınbabamın ve inanarak evime kimler girdiyse onların ve erkek, kadın bütün inananların suçlarını ve zalimleri de ancak mahvet, helak vesilelerini arttır onların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 1, 'De ki: Bana vahyedildi bu gerçekten de; cinlerin bir topluluğu, beni dinlediler de şüphe yok ki dediler, biz, şaşılacak bir Kur''an duyduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 2, 'Doğru yolu göstermede, derken inandık ona ve kesin olarak hiçbir kimseyi, Rabbimize ortak saymayacağız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 3, 'Ve şüphe yok ki Rabbimizin şanı, yücelerden de yüce, ne bir arkadaş edinmiştir ve ne bir oğul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 4, 'Ve şüphe yok ki aklı olmayanımız, Allah hakkında saçma ve boş laflar ediyormuş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 5, 'Ve bizse şüphe yok ki ne insanlar, ne de cinler, Allah hakkında yalan şeyler söylemez sanıyorduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 6, 'Ve gene şüphe yok ki insanlardan bazı kimseler, cinlerden bazılarına sığınıyorlar da onların taşkınlığını, zulümlerini arttırıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 7, 'Ve şüphe yok ki onlar da sizin sandığınız gibi Allah''ın, kesin olarak hiçbir kimseyi tekrar diriltmiyeceğini sanıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 8, 'Ve gerçekten de biz, göğü yokladık da orasını, kuvvetli bekçilerle ve şihaplarla dolu bulduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 9, 'Ve gerçekten de biz, orada, bir söz duymak için bazı yerlere otururduk, fakat şimdi kim, dinlemeye kalkışsa kendisini gözetliyen bir şihap buluyor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 10, 'Ve gerçekten de bilmiyoruz, yeryüzündekilere bir kötülük gelmesi mi isteniyor, yoksa Rabbleri, onlara doğru yolu buldurmayı mı diledi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 11, 'Ve gerçekten bizden temiz kişiler de vardı, içimizde, böyle olmayanlar da vardı; ayrıayrı yollar tutmuştuk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 12, 'Ve gerçekten de iyice anladık ki yeryüzünde Allah''ı aciz bırakmamıza imkan yok ve kaçmakla da asla onu acze düşüremeyiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 13, 'Ve gerçekten de doğru yolu gösteren Kur''an''ı duyunca inandık ona; kim Rabbine inanırsa artık ne mükafatın azalmasından korkar, ne de zulümden ve kötülükten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 14, 'Ve gerçekten de bizden, Müslüman olanlar da var, gerçekten sapıp zulmedenler de; artık kimler Müslüman olursa onlardır doğruluk yolunu arayıp bulanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 15, 'Fakat gerçekten sapıp zulmedenlere gelince, onlar da cehenneme odun olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 16, 'Ve eğer yolda dosdoğru yürüselerdi onları bolbol suvarırdık elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 17, 'Sınamak için onları böylece ve kim, Rabbini anmaktan yüz çevirirse onu, gittikçe artıp duran bir azaba sokar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 18, 'Ve şüphe yok ki secde edilen yerler, Allah''a aittir, artık orada Allah''la beraber hiçbir kimseyi çağırmayın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 19, 'Ve şüphe yok ki Allah''ın kulu, ona çağırmaya kalktı mı cinler, öylesine toplanıyorlardı etrafına ki neredeyse birbirlerini ezeceklerdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 20, 'De ki: Ben, ancak Rabbime çağırmadayım ve ona, hiçbir kimseyi ortak olarak kabul etmemedeyim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 21, 'De ki: Benim, size bir zarar vermeye de gücüm yetmez, sizi doğru yola götürmeye de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 22, 'De ki: Beni, hiçbir kimse, Allah''ın azabından kurtaramaz ve ben ondan başka sığınacak birisini de bulamam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 23, 'Bana düşen, ancak Allah''tan tebliğdir ve onun hükümlerini size bildirmektir; ve kim, Allah''a ve Peygamberine karşı gelirse artık onun hakkıdır cehennem ateşi, ebedi olarak da kalır orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 24, 'Sonunda, vaadedilen şeyi gördüler mi artık bilirler kimmiş yardımcısı daha zayıf ve sayı bakımından taraftarı daha az?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 25, 'De ki: Ben bilmem, size vaadedilen pek mi yakın, yoksa Rabbim, onu bir müddet uzattı mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 26, 'Gizliyi bilen odur, gizlediği şey de hiçbir kimseye açılmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 27, 'Ancak peygamberlerden seçtiği müstesna; onların da önlerinde, artlarında gözetleyiciler yollar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (72, 28, 'Gerçekten de Rablerinin elçiliklerini hakkıyla yaptıklarını, hükümlerini tebliğ ettiklerini bilsin diye ve onların her halini de bilgisiyle kavramış, kuşatmıştır ve her şeyi, birbir sayıp tespit etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 1, 'Ey elbisesine bürünen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 2, 'Geceleyin kalk namaza ama gecenin az bir kısmında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 3, 'Gece yarısında, yahut ondan biraz da sonra.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 4, 'Yahut biraz önce ve oku Kur''an''ı, harfleri sayılırcasına, tanetane ve yavaşyavaş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 5, 'Gerçekten de sana ağır bir şey vahyedeceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 6, 'Şüphe yok ki geceleyin kalkmak, pek meşakkatlidir, fakat ibadet için de gece, pek uygun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 7, 'Şüphe yok ki gündüzün, işingücün vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 8, 'Ve an Rabbinin adını ve gönlünü ona tam bağla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 9, 'Rabbidir doğunun ve batının, yoktur ondan başka tapacak, artık ona dayan, onu koruyucu say.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 10, 'Ve sabret dediklerine ve gönlünden onlara aykırı olmakla beraber kötülüklerine karşı vermeyerek bırak onları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 11, 'Ve bana bırak nimet sahibi olan yalanlayanları ve az bir zaman mühlet ver onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 12, 'Şüphe yok ki katımızda bağlar var ve koca cehennem var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 13, 'Ve boğazdan geçmez dikenli yemek var ve elemli bir azap var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 14, 'O gün, şiddetli bir sarsıntıyla yeryüzü ve dağlar sarsılır ve hepsi de esintiyle tozan kum yığınlarına döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 15, 'Şüphe yok ki biz, size tanık olmak üzere bir Peygamber gönderdik, nitekim Firavun''a da peygamber göndermiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 16, 'Derken Firavun, peygambere isyan etmişti de onu, pek şiddetli bir surette helak etmiştik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 17, 'Nasıl korursunuz kendinizi, kafir olursanız, o günün şerrinden ki çocukları bile ihtiyarlatır da saçlarını ağartır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 18, 'Gök, o gün yarılır, vaadi, yerine gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 19, 'Şüphe yok ki bu, bir öğüttür; artık dileyen, Rabbine yol bulur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (73, 20, 'Şüphe yok ki Rabbin daha iyi bilir, gerçekten de senin, gecenin üçte ikisinden ve yarısından daha az ve bazı vakitlerde de üçte biri kadar bir zamanında kalktığını ve seninle beraber bulunanların bir bölüğünün de kalktıklarını ve Allah, gecenin ve gündüzün vakitlerini ölçer; bilmiştir ki siz, onu layıkıyla hesaplayamazsınız, bu yüzden de tövbenizi kabul etmiştir, artık, Kur''an''dan, kolay geleni okuyun; bilmiştir ki sizden hastalar bulunabilir ve bir başka kısmınız da Allah''ın lütfünü, ihsanını elde etmek için yeryüzünde yolculuk eder ve başka bir bölük de Allah yolunda savaşır, artık, ondan, kolay geleni okuyun ve kılın namazı ve verin zekatı ve Allah''a, güzel bir borç verin ve kendiniz için, önceden ne hayır yaparsanız ondan daha hayırlısıyla ve mükafat bakımından daha büyüğüyle bulursunuz onu Allah katında ve yarlıganma dileyin Allah''tan ve şüphe yok ki Allah, suçları örter, rahimdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 1, 'Ey elbisesiyle başını örten.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 2, 'Kalk da korkut.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 3, 'Ve Rabbini büyük bil.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 4, 'Ve elbiseni temizle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 5, 'Ve putlardan çekin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 6, 'Ve birşeyi, daha fazlasını elde etmek için ve başa kakarak verme.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 7, 'Ve Rabbine dayan, sabret.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 8, 'O boru, çalınınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 9, 'Artık o gündür pek güç bir gün.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 10, 'Kafirlere kolay değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 11, 'Bırak beni ve yarattığımı yapayalnız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 12, 'O yarattığımı ki yarattım ve ona hayliden hayli mal verdim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 13, 'Gözlerinin önünde duran oğullar verdim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 14, 'Ve onun geçimini yaydım da yaydım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 15, 'Sonra da daha fazlalaştırmamı umar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 16, 'Hayır, mümkün değil; şüphe yok o, delillerimize karşı adamakıllı inada girişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 17, 'Ben de onu, rahat ve huzur yüzü görmeyeceği bir azaba uğratacağım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 18, 'Şüphe yok ki o, iyice bir düşündü de kendince ölçtübiçti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 19, 'Geberesice nasıl da ölçtübiçti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 20, 'Sonra gene de geberesice, nasıl da ölçütübiçti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 21, 'Sonra baktı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 22, 'Sonra kaşını çattı, suratını astı,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 23, 'sonra ardını döndü ve ululanmaya kalkıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 24, 'Derken bu, ancak dedi, eskiden beri söylenegelen bir büyü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 25, 'Bu ancak insan sözü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 26, 'Onu yakıcı cehenneme atarım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 27, 'Ve bilir misin, nedir yakıcı cehennem?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 28, 'Yakar bitirir de gene bırakmaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 29, 'Derileri tamamıyla yakar kavurur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 30, 'On dokuz memuru vardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 31, 'Ve biz, cehennem memurlarını, meleklerden tayin ettik ve kendilerine kitap verilenlerin iyideniyiye anlayıp inanmaları için ve inananların inancını arttırsın ve kendilerine kitap verilenlerle inananlar, şüpheye düşmesinler ve gönüllerinde hastalık olanlar ve kafirlerse, Allah bununla, bu örnekle neyi kastediyor ki desinler diye sayılarını on dokuz olarak taktir ettik. İşte böylece Allah, bildiğini saptırır ve dilediğini doğru yola sokar ve Rabbinin ordusu ne kadardır, ancak Allah bilir ve bu, insanlara bir öğüttür ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 32, 'Hayır, gerçekten de andolsun aya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 33, 'Ve andolsun çekilip giderken geceye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 34, 'Ve ışıklanıp doğarken güne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 35, 'Cehennem, şüphe yok ki pek büyük mahluklardan biridir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 36, 'Korkutucudur insanları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 37, 'Sizden, ileri geçip itaat edenleri ve geri kalıp isyana dalanları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 38, 'Herkes, kazancına bağlıdır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 39, 'Ancak sağ taraf ehli başka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 40, 'Cennetlerdedir onlar, soralar, konuşurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 41, 'Mücrimlerin halinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 42, 'Nedir derler cehenneme sokan sizi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 43, 'Derler ki: Namaz kılmazdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 44, 'Ve yoksulu doyurmazdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 45, 'Ve boş laflarla azgınlığa dalanlarla biz de dalardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 46, 'Ve ceza gününü yalanlardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 47, 'Bize ölüm gelip çatıncaya dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 48, 'Derken şefaatçilerin şefaati fayda vermez onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 49, 'Derken ne oluyor onlara ki öğütten, Kur''an''dan yüz çevirmedeler, kaçmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 50, 'Sanki yabani eşeklerdir onlar da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 51, 'Arslandan kaçıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 52, 'Hayır, onların herbiri, ister ki apaçık sahifeler verilsin onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 53, 'Hayır, öyle değil, onlar, ahiretten korkmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 54, 'Gerçekten de Kur''an, bir öğüttür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 55, 'Artık dileyen, öğüt alır onunla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (74, 56, 'Ve Allah''ın dilediğinden başkası öğüt alamaz; odur çekinilmeye değer ve yarlıgayıp suçları örter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 1, 'Andolsun kıyamet gününe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 2, 'Ve andolsun kendini kınayıp duran nefse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 3, 'Sanıyor mu insan, kemiklerini hiç mi toplayamayız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 4, 'Evet, değil kemiklerini, parmak uçlarını bile düzüp koşmaya gücümüz yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 5, 'Hayır, insan, ilerde olanı yalanlamak ister.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 6, 'Ve kıyamet günü ne vakit diye sorar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 7, 'Ve şaşırıp gözler dikilince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 8, 'Ve ay tutulunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 9, 'Ve güneşle ay birleştirilince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 10, 'İnsan der ki o gün, nerede kaçacak yer?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 11, 'Hayır, yok kaçacak, sığınacak yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 12, 'O gün Rabbinin katındadır karar edilecek yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 13, 'O gün önce yaptığı da haber verilir insana, sonra yaptığı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 14, 'Hayır, insanın azası, aleyhine tanıklık eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 15, 'Özürlerini ortaya dökse de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 16, 'Vahyi, acele edip okumak için dilini oynatıp durma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 17, 'Şüphe yok ki onu toplayıp unutturmamak da bize düşer, okumak ve tertib etmek de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 18, 'Onu okuduk mu, uy okuyuşuna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 19, 'Onu anlatıp bildirmek de şüphesiz, bize düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 20, 'Hayır, siz geçip gideni seversiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 21, 'Ve ahireti bırakırsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 22, 'O gün yüzler parlar, güzelleşir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 23, 'Ve Rablerine bakar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 24, 'Ve yüzler, asılır, kararır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 25, 'Bellerini kıracak bir felaketi bekler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 26, 'Hayır; can, köprücük kemiklerine gelince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 27, 'Ve bir okuyup üfleyen yok mu denince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 28, 'Ve şüphe yok ki bu çağın, bir ayrılık çağı olduğunu anlayınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 29, 'Ve baldır, baldıra dolaşınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 30, 'O gün, Rabbinin tapısına götürülür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 31, 'O, ne birşeyi vermiştir sadaka olarak, ne namaz kılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 32, 'Ve fakat yalanlamıştır, yüz çevirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 33, 'Sonra da salınasalına yakınlarının yanına gitmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 34, 'Kötülük sana gerek, gene de kötülük sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 35, 'Sonra da kötülük sana gerek de gene kötülük sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 36, 'Yoksa insan, sanır mı ki kendi keyfine bırakılır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 37, 'Erlik suyundan dökülen bir katre değil miydi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 38, 'Sonra bir kan pıhtısı oldu da onu yarattı, azasını düzüp koştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 39, 'Derken ondan da erkek, dişi, çiftler yarattı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (75, 40, 'Bunları yapanın, ölüyü diriltmeye gücü mü yetmez?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 1, 'Gerçekten de insana, zamanın bir çağı gelmişti ki anılır bir şey bile değildi insan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 2, 'Şüphe yok ki biz insanı, bir katre sudan, erkeklik suyuyla kadınlık suyunun rahimde birleşmesinden yarattık sınamak için, derken onu, duyar, görür bir hale getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 3, 'İster şükretsin, ister nankör olsun, gerçekten de biz ona doğru yolu gösterdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 4, 'Şüphe yok ki kafirlere zincirleri, boyundurukları ve yakıp kavuran cehennemi hazırladık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 5, 'İtaat eden ve iyilikte bulunanlar, şüphe yok ki kaselerle şaraplar içerler ki kafur ırmağının suyu da karıştırılmıştır bu şaraba.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 6, 'Allah''ın has kullarının içtiği bu şarap, bir kaynaktan çıkar ki onlar, diledikleri gibi, diledikleri yerlerde, onu akıtıp fışkırtırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 7, 'Adaklarını yerine getirir onlar ve şerri, her yanı saran, kaplayan günden korkarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 8, 'Ve ona ihtiyaçları olduğu halde yemeklerini yoksula ve yetime ve tutsağa verirler, onları doyururlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 9, 'Sizi, ancak Allah rızası için doyurmadayız ve sizden istemeyiz ne bir karşılık, ne bir şükür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 10, 'Şüphe yok ki biz, suratları astıran, azabı pek şiddetli olan gün, Rabbimizden korkarız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 11, 'Derken Allah da korumuştur onları, bugünün şerrinden ve yüzlerine bir parlaklık, gönüllerine bir sevinçtir, vermiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 12, 'Ve sabretmelerine karşılık da mükafatları, cennettir ve ipeklilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 13, 'Yaslanırlar orada tahtlara, orada ne güneş görürler, ne zemheri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 14, 'Ağaçların gölgeleri, yakındır onlara ve meyveleri, adamakıllı ram olmuştur onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 15, 'Ve sunulur onlara gümüş kadehler ve sırça sağraklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 16, 'Öylesine sırça ki incecik gümüşten ve hepsini de içecekleri miktara, susuzluklarına göre ölçmüşlerdir adeta.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 17, 'Ve bir kadehle susuzlukları giderilir ki içindeki şaraba zencefil karıştırılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 18, 'Orada bulunan ve şarılşarıl akan, her yana giden, boğazdan kayan selsebil kaynağından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 19, 'Etraflarında, ölümsüz delikanlılar dolaşır, onları görünce sanırsın ki saçılmış incilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 20, 'Ne yana baksan nimetler görürsün, ne yana baksan, pek büyük ve zevalsiz bir saltanat ve devletler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 21, 'Üstlerinde, ipincecik yeşil ve ipek elbiseler, kalın ipekten dokunmuş libaslar vardır ve gümüş bilezikler takınırlar ve Rableri, onları tertemiz bir şarapla suvarır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 22, 'Şüphe yok ki bu, size bir mükafattır ve çalışmanız, makbuldür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 23, 'Şüphe yok ki biz indirdik Kur''an''ı sana ayetayet ve zamanzaman.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 24, 'Artık sabret Rabbinin hükmüne ve uyma, onlardan suçlu, yahut nankör olana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 25, 'Ve an Rabbinin adını sabah ve akşam.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 26, 'Ve geceleyin de secde et artık ona ve tenzih et uzun gecelerde onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 27, 'Şüphe yok ki bunlar çabucak gelipgeçeni severler de o ağır günü artlarına atar, bırakırgiderler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 28, 'Biz yarattık onları ve kuvvetlendirdik yaratılışlarını ve dilersek onları değiştiririz de yerlerine, onlara benzer başkalarını getiririz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 29, 'Şüphe yok ki bu, bir öğüttür, artık kim dilerse Rabbine doğru, bir yol tutar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 30, 'Ve Allah dilemedikçe onlar, dileyemezler; şüphe yok ki Allah, her şeyi bilir, hüküm ve hikmet sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (76, 31, 'Dilediğini rahmetine alır; ve zalimlere gelince: Elemli bir azap hazırlamıştır onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 1, 'Andolsun, ardı ardınca, iyilikle gönderilenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 2, 'Şiddetle esip yelenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 3, 'Bulutları yayıp sürenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 4, 'Gerçekle aslı olmayanı ayırt edenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 5, 'Öğütleri telkin edenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 6, 'Özürle suçu yok etmek hususunda olsun, yahut korkutma hususuna ait bulunsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 7, 'Şüphe yok ki size vaat edilen, mutlaka olacak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 8, 'Yıldızların ışıkları sönünce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 9, 'Ve gök yarılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 10, 'Ve dağlar, yerlerinden kopup dümdüz olunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 11, 'Ve peygamberler toplanınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 12, 'Hangi gün için geciktirildi bunlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 13, 'Ayırma günü için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 14, 'Ve nedir, bilir misin ayırma günü?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 15, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 16, 'Önce gelenleri helak etmedik mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 17, 'Sonra da son gelenleri tutar, katarız onlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 18, 'Böyle yaparız günahkarlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 19, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 20, 'Sizi, bayağı ve azıcık bir sudan yaratmadık mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 21, 'Derken onu, karar edilecek kuvvetli bir yerde tutmadık mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 22, 'Bilinen bir müddete dek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 23, 'Derken taktir ettik yaratılışını, ne güzel de takdir ederiz biz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 24, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 25, 'Yeryüzünü, bir toplantı yeri olarak halk etmedik mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 26, 'Dirilere ve ölülere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 27, 'Ve orada, sabit ve metin dağlar yarattık ve sizi, tatlı suyla suvardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 28, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 29, 'Haydi yürüyün yalanladığınıza doğru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 30, 'Yürüyün üç kola ayrılmış gölgeye doğru.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 31, 'Ne gölgelendirir sizi o, ne alevden korur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 32, 'O, köşk gibi kıvılcımlar fırlatır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 33, 'Sanki o kıvılcımlar, birer sarı erkek devedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 34, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 35, 'Bu, bir gündür ki söz söyleyemezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 36, 'Onlara izin de verilmez, özür getiremezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 37, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 38, 'Budur ayırma günü, sizi de toplarız, öncekileri de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 39, 'Artık bir düzeniniz varsa düzüp koşun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 40, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 41, 'Şüphe yok ki çekinenler, gölgeliklerdedir ve pınar başlarında,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 42, 'arzuladıkları meyveleri bulurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 43, 'Yiyin ve için, afiyetler olsun yaptıklarınıza karşılık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 44, 'Şüphe yok ki böyle mükafatlandırırız iyilik edenleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 45, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 46, 'Yiyin ve geçinin az bir müddet, şüphe yok ki suçlularsınız siz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 47, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 48, 'Rüku edin denince onlara, rüku etmezler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 49, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (77, 50, 'Bundan sonra artık hangi söze inanırlar ki?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 1, 'Neyi birbirlerine sorup dururlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 2, 'Pek ulu haberi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 3, 'Öylesine haber ki onlar, bu hususta aykırılığa düşmüşlerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 4, 'Hayır, bilirler yakında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 5, 'Gene de hayır, bilirler yakında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 6, 'Yeryüzünü, hazır bir yaygı olarak yaymadık mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 7, 'Ve dağları, çiviler gibi çaktık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 8, 'Ve sizi, çiftçift yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 9, 'Ve uykunuzu, vakitli bir istirahat zamanı kıldık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 10, 'Ve geceyi, her şeyi örten bir örtü yaptık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 11, 'Ve gündüzü de geçim zamanı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 12, 'Ve üstünüzde, yedi sağlam yapı kurduk.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 13, 'Ve yalımyalım yanan bir kandil yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 14, 'Ve sıkılan bulutlardan şarılşarıl sular akıttık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 15, 'Akıttık da o sayede tohumları, otları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 16, 'Ve birbirine sarmaşdolaş bahçeleri, bağları meydana getirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 17, 'Şüphe yok ki ayırma gününün vakti de tayin edilmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 18, 'O gün Sur üfürülür de gelirsiniz bölükbölük.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 19, 'Ve gök açılmış, kapılar haline gelmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 20, 've dağlar yürütülmüş, seraba dönmüştür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 21, 'Şüphe yok ki cehennem pusudadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 22, 'Azanlara dönüp varılacak son yerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 23, 'Yıllar boyunca kalırlar orada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 24, 'Ne bir serinlik tadarlar, ne içilecek bir şey.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 25, 'Ancak bir kaynar su, ancak bir kan ve irin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 26, 'Bir cezadır ki tam uygun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 27, 'Şüphe yok ki onlar, hiçbir soru ummazlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 28, 'Ve delillerimizi boyuna yalanlarlardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 29, 'Ve biz her şeyi birbir sayıp yazdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 30, 'Artık tadın, ancak azabınızı arttırırız sizin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 31, 'Şüphe yok ki çekinenlere bir kurtuluş, bir kutluluk ve murada eriş yeri var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 32, 'Bahçeler, üzümler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 33, 'Ve memeleri yeni sertleşmiş yaşıt kızlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 34, 'Ve dopdolu kadeh.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 35, 'Ne boş bir söz duyarlar orada, ne birbirlerini yalanlama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 36, 'Rabbinden, fazlasıyle bir lütuf ve ihsan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 37, 'Göklerin ve yeryüzünün ve ikisinin arasındakilerin Rabbidir rahman, onun hitabına nail olmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 38, 'O gün, Ruh ve melekler, saf saf dururlar; konuşamazlar, ancak rahmanın izin verdiği konuşur ve gerçek söyler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 39, 'Bugün, gerçektir, artık dileyen, dönüp Rabbinin tapısına varmaya bir vesile edinir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (78, 40, 'Şüphe yok ki biz sizi, yakın bir azapla korkutmadayız; o gün kişi, elleriyle hazırladığına bakar ve kafir de ne olurdu der, keşke toprak olaydım.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 1, 'Andolsun şiddetle çekip alanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 2, 'Ve neşeli neşeli yürüyenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 3, 'Ve yüze yüze gidenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 4, 'Ve herkesi geçenlere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 5, 'Ve işi tedbirle yapanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 6, 'O gün, bir sarsıntıdır, sarsar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 7, 'Ardından bir sarsıntı daha gelir çatar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 8, 'Yürekler, belinleyip korkar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 9, 'Gözleri yere dikilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 10, 'Onlar derler ki: Çukura atıldıktan sonra mı dirileceğiz de çıkacağız?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 11, 'Ufalanmış bir kemik yığını haline geldikten sonra mı olacak bu iş?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 12, 'Öyleyse derler, bu, pek ziyanlı bir dönüş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 13, 'Halbuki o, bir tek haykırış.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 14, 'Derken onlar dümdüz bir yerde toplanırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 15, 'Gelmedi mi Musa''ya ait söz sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 16, 'Hani Rabbi, kutlu Tuva vadisinde nida etmişti ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 17, 'Git Firavun''a, şüphe yok ki o, azdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 18, 'De ki: İster misin temizlenmeyi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 19, 'Ve sana Rabbinin yolunu göstereyim de korkasın, saygı duyasın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 20, 'Derken ona en büyük delili göstermişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 21, 'Oysa yalanlamıştı, karşı gelmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 22, 'Sonra da geri dönmüştü de koşup gitmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 23, 'Derken halkı toplamıştı da bağırmıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 24, 'Ben, sizin en yüce Rabbinizim demişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 25, 'Derken Allah onu, dünyada da, ahirette de azaplandırarak helak etmişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 26, 'Şüphe yok ki bunda bir ibret var korkanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 27, 'Sizi yaratmak mı daha güç sizce, yoksa göğü yaratmak mı? Onu kurdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 28, 'Tavanını yücelti, düzüp koştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 29, 'Ve gecesini kararttı, kuşluk çağını meydana çıkarttı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 30, 'Ve yeryüzünü de bundan sonra yaydı, döşedi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 31, 'Oradan suyunu, otlağını çıkarıp meydana getirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 32, 'Ve dağlarını oturttu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 33, 'Sizin ve hayvanlarınızın faydası için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 34, 'Derken o pek büyük felaket gelip çatınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 35, 'İnsan, o gün anlar, hatırlar neye çalıştığını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 36, 'Ve cehennem, belirtilir görene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 37, 'Artık kim azmışsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 38, 'Dünya yaşayışını üstün tutmuşsa,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 39, 'Artık cehennemdir onun yeriyurdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 40, 'Ve ama kim, Rabbinin durağından korkup da nefsi, dileğinden çekmişse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 41, 'Şüphe yok ki cennettir onun yeriyurdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 42, 'Senden sorarlar kıyameti, ne vakit kopacak?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 43, 'Sen, onu ne bilirsin ki ne anlatacaksın?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 44, 'Onun sonu, Rabbine aittir, o bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 45, 'Sen ancak, korkanı korkutansın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (79, 46, 'Onu gördükleri gün, bir akşamcık yaşamışa dönerler, yahut da günün kuşluk çağı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 1, 'Yüzünü ekşitti ve döndürdü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 2, 'Yanına kör geldi diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 3, 'Belki o, arınacaktır, ne bilirsin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 4, 'Yahut da öğüt alacaktır da ondan faydalanacaktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 5, 'Fakat ihtiyacı olmayana gelince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 6, 'Artık sen onun üstüne düştükçe düşüyorsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 7, 'O arınmazsa sana ne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 8, 'Ve fakat sana koşup gelen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 9, 'Ve korkan kişi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 10, 'Sen ondan gaflet ediyor, ona aldırış bile etmiyorsun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 11, 'Öyle değil, şüphe yok ki Kur''an, ancak bir öğüttür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 12, 'Dileyen dinler, öğüt alır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 13, 'Büyük, şerefli sayfalardadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 14, 'Yüceltilmiştir, arıtılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 15, 'Yazıcıların ellerinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 16, 'Büyüklerdir, hayırlı ve itaatlilerdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 17, 'Geberesice insan, ne de kafirdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 18, 'Onu, neden yaratmıştır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 19, 'Bir katre sudan; yaratmıştır onu da halden hale döndürmüştür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 20, 'Sonra ona yolu kolaylatmıştır da dünyaya getirmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 21, 'Sonra öldürmüştür onu da kabre sokmuştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 22, 'Sonra da dilerse diriltir onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 23, 'Gerçekten de insan, onun emrini tam yerine getirmedi gitti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 24, 'Artık insan, yediğine de bir baksın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 25, 'Şüphe yok ki biz, bir yağmurdur, yağdırdık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 26, 'Sonra yeryüzünü bir iyice yardık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 27, 'Derken orada tohumlar bitirdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 28, 'Ve üzüm ve yoncalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 29, 'Ve zeytin ve hurma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 30, 'Ve çeşitli büyük ağaçları bulunan bahçeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 31, 'Ve meyveler ve otlaklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 32, 'Sizin ve hayvanlarınızın faydası için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 33, 'Derken adeta kulakları sağır eden o bağırış gelip çattı mı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 34, 'O gün, bir gündür ki kişi kaçar kardeşinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 35, 'Ve anasından ve babasından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 36, 'Ve eşinden ve çocuğundan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 37, 'Ve onların herbirinin bir derdi var ki başkalarına bakmaya vakti bile yok.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 38, 'Nice yüzler o gün parılparıl parlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 39, 'Güler, sevinir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 40, 'Ve nice yüzler o gün tozlarla bulanır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 41, 'Üstlerine bir karalıktır çöker.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (80, 42, 'İşte onlardır kafirler, suçlular.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 1, 'Güneş dürülünce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 2, 'Ve yıldızlar kararınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 3, 'Ve dağlar yürütülünce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 4, 'Ve dişi develer bile başı boş bırakılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 5, 'Ve vahşi hayvanlar bile bir araya toplanınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 6, 'Ve denizler, coşup kabarınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 7, 'Ve insanlar, haldeşleriyle birleşince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 8, 'Diridiri gömülen kıza sorulunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 9, 'Hangi suç yüzünden öldürüldün diye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 10, 'Ve sahifeler dağılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 11, 'Ve göğün perdesi kaldırılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 12, 'Ve cehennem alevlendirilince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 13, 'Ve cennet yaklaştırılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 14, 'Herkes bilir ne hazırladığını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 15, 'Artık andolsun dönüp kaybolan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 16, 'Doğup yürüyen ve burçlarına giren yıldızlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 17, 'Ve geçmeye başladığı çağda, geceye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 18, 'Ve ışıdığı çağda, sabaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 19, 'Şüphe yok ki Kur''an, büyük bir elçinin sözüdür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 20, 'Kuvvetlidir, arş sahibinin katında kadri yüce.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 21, 'İtaat edilir, emniyetlidir de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 22, 'Sizinle konuşan, deli değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 23, 'Ve andolsun, onu, apaydın tanyerinde gördü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 24, 'Arkadaşınız, gizli şeyler hakkında da nekes değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 25, 'Ve Kur''an, taşlanmış Şeytan''ın sözü de değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 26, 'Artık nereye gidiyorsunuz öyleyse?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 27, 'O, bütün alemlere bir öğüttür ancak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 28, 'Ve hele içinizden doğru hareket etmek isteyene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (81, 29, 'Ve isteyemezsiniz, alemlerin Rabbi Allah istemedikçe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 1, 'Gök yarılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 2, 'Ve yıldızlar dökülüp saçılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 3, 'Ve denizler, kaynayıp karışınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 4, 'Ve kabirlerin altı üstüne gelince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 5, 'Bilir herkes, neyi öne sürmüştür, neyi sona bırakmış.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 6, 'A insan, kerem sahibi Rabbine karşı seni gururlandıran ne?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 7, 'Öylesine Rab ki seni yarattı, azanı düzüp koştu da seni düzgün bir hale getirdi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 8, 'Dilediği surete de benzetti seni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 9, 'İş, sandığınız gibi değil, hayır siz ceza gününü de yalanlıyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 10, 'Ve şüphe yok ki size koruyucular memur edilmiştir elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 11, 'Büyüktür onlar, yazarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 12, 'Bilirler ne yaparsanız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 13, 'Ve şüphe yok ki itaat eden iyi kişiler, elbette cennettedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 14, 'Ve şüphe yok ki kötülük edenler, elbette cehennemde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 15, 'Ceza gününde oraya girerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 16, 'Ve oradan hiç ayrılmazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 17, 'Ve bilir misin, nedir ceza günü?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 18, 'Sonra gene de bilir misin nedir ceza günü?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (82, 19, 'Bir gündür ki hiçbir kimse, hiçbir kimseye yardım edemez o gün ve hüküm, o gün Allah''ın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 1, 'Yazık ölçüye, tartıya hile katanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 2, 'Öyle kişilerdir onlar ki insanlardan bir şey alırlarken tamam ölçerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 3, 'Ve insanlara ölçüp tartarlarken eksik ölçerler, eksik tartarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 4, 'Onlar, gerçekten de tekrar dirilip kalkacaklarını sanmıyorlar mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 5, 'Pek büyük bir gün için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 6, 'Öylesine bir gün ki insanlar, alemlerin Rabbinin emriyle kalkarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 7, 'İş sandıkları gibi değil; şüphe yok ki kötülük edenlerin amel defterleri, elbette siccindedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 8, 'Ve nedir, bilir misin siccin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 9, 'Bir kitaptır ki yazılmış.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 10, 'Vay hallerine o gün yalanlayanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 11, 'Onların ki yalanlarlardı ceza gününü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 12, 'Ve o günü, yalnız haddini aşan ve boyuna suç işleyip duran kişiler yalanlarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 13, 'Onlara ayetlerimizi okuyunca derler ki: Öncekilere ait masallar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 14, 'İş öyle değil, hayır, kazandıkları şeyler, üstüste kalplerine yığılmıştır da kalpleri pas tutmuştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 15, 'İş öyle değil, hayır, şüphe yok ki onlar, o gün elbette Rablerinin lütfünden, bir perdeyle, bir engelle uzak kalırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 16, 'Sonra da şüphe yok ki onlar, elbette cehenneme atılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 17, 'Sonra denir ki: İşte buydu yalanladığınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 18, 'İş öyle değil, şüphe yok ki iyi kişilerin amel defterleri, illiyyin''dedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 19, 'Ve nedir, bilir misin illiyyin?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 20, 'Bir kitaptır ki yazılmış.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 21, 'Onu görür ancak mabutlarına yaklaştırılanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 22, 'Şüphe yok ki iyi kişiler, elbette cennettedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 23, 'Tahtlar üstünde bakarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 24, 'Tanırsın onları, yüzlerinde cennetin parlaklığı var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 25, 'Sunulur, içirilir onlara halis şarap ki içiminin sonu pek hoştur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 26, 'Ve sonunda misk kokar; ve özleyip dileyenler, bunu özlesinler, bunu dilesinler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 27, 'Ve bu şaRaba Tesnim ırmağının suyu da karıştırılmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 28, 'Öyle bir kaynaktır bu ki ondan, mabutlarına yaklaşanlar içer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 29, 'Şüphe yok ki suç işliyenler, inananlara gülerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 30, 'Ve onların yanlarından geçerlerken, kaşlarıylagözleriyle onları işaret ederler,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 31, 'Ve kendi adamlarının yanlarına dönünce de eğlenerek gülegüle dönerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 32, 'Ve onları görünce de şüphe yok ki derler bunlar, elbette sapıklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 33, 'Ve bunlar, inananların yaptıklarını görüp bellemek için gönderilmediler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 34, 'Artık bugün, inananlar, kafirlere gülerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 35, 'Tahtlar üstünden bakarlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (83, 36, 'Cezalandılar mı kafirler, yaptıklarına karşılık?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 1, 'Gök yarılıp çatlayınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 2, 'Ve Rabbini dinleyip itaat ederek sözünü haklayınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 3, 'Ve yeryüzü, dümdüz çekilince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 4, 'Ve içindekileri atıp boşalınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 5, 'Ve Rabbini dinleyip itaat ederek sözünü haklayınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 6, 'Ey insan, şüphe yok ki sen, Rabbine ulaşmak için meşakkatler içinde didinirdurursun da sonunda ona kavuşursun.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 7, 'Ama kimin kitabı, sağ yanından verilirse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 8, 'Artık onun hesabı, kolayca görülür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 9, 'Ve ailesinin yanına sevinç içinde döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 10, 'Ve ama kimin kitabı, ardından verilirse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 11, 'O, helak olmasını diler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 12, 'Ve cehenneme atılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 13, 'Şüphe yok ki o, ailesinin içinde sevinmedeydi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 14, 'Şüphe yok ki o, öldükten sonra tekrar hayata dönmeyeceğini sanırdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 15, 'Evet, şüphe yok ki Rabbi, onu görürdü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 16, 'Andolsun gün battıktan sonraki kızıllığa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 17, 'Ve geceye ve gecenin kapladıklarına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 18, 'Ve aya, dolunay olunca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 19, 'Elbette geçeceksiniz bir halden bir hale.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 20, 'Artık ne oldu onlara da inanmıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 21, 'Ve onlara Kur''an okununca secde etmiyorlar?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 22, 'Hayır, kafir olanlar, yalanlıyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 23, 'Ve Allah, daha iyi bilir, gönüllerinde ne var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 24, 'Artık müjdele onları elemli bir azapla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (84, 25, 'Ancak inananlar ve iyi işlerde bulunanlar başka; onlar içindir başa kakılmıyan mükafat.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 1, 'Andolsun burçları bulunan göğe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 2, 'Ve vaadedilen güne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 3, 'Ve tanığa ve görünene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 4, 'Kahrolsun yerde hendekler kazıp ateşler yakanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 5, 'Öylesine ateş ki odunları var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 6, 'O sırada kendileri de kıyısında oturmuşlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 7, 'İnananlara yaptıklarını seyrediyor onlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 8, 'Ve ancak üstün ve hamde layık Allah''a inandıkları için onları azaplandırmadalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 9, 'O mabut ki onundur saltanatı ve tedbiri göklerin ve yeryüzünün ve Allah her şeye tanıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 10, 'Kadın ve erkek, inananları azaplandıranlar, sonra da tövbe etmeyenler yok mu, onlaradır cehennem azabı ve onlaradır yakıp kavuran azap.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 11, 'İnananlara ve iyi işlerde bulunanlara gelince: Onlaradır kıyılarından ırmakla akan cennetler ve buysa pek büyük bir kurtuluştur, bu kutluluk ve murada eriş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 12, 'Şüphe yok ki Rabbinin, tutup helak edişi, pek çetindir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 13, 'Şüphe yok ki o, ilk defa var eder ve ölümden sonra gene de yaratır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 14, 'Ve odur suçları örten ve çokçok seven.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 15, 'Şerefli arşın sahibi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 16, 'Dilediğini işlerdurur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 17, 'Sana, ordulara ait olan söz gelmedi mi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 18, 'Firavun''a ve Semud''a aid olan?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 19, 'Kafir olanlar, zaten de yalanlamaya dalmışlardır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 20, 'Ve Allah''sa yaptıkları işin ardından onları kavramış, kuşatmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 21, 'Hayır, o şerefli Kur''an''dır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (85, 22, 'Korunmuş levhada.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 1, 'Andolsun göğe ve geceleyin gelene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 2, 'Ve bilir misin nedir geceleyin gelen?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 3, 'Parıl parıl parlıyan yıldız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 4, 'Hiçbir kimse yoktur ki onun bir gözetip koruyan memuru bulunmasın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 5, 'Artık insan, bir baksın neden yaratıldı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 6, 'Yaratıldı sıçrayarak akan bir sudan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 7, 'Belden çıkar ve kaburga kemiklerinin arasından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 8, 'Şüphe yok ki ölümden sonra tekrar onu hayata döndürmiye de gücü yeter.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 9, 'O gün, bütün gizli şeyler, meydana vurulur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 10, 'Artık onun ne bir gücü kalır, ne de ona yardım eden olur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 11, 'Andolsun yağmur yağdıran göğe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 12, 'Ve nebat bitirmek için çatlayıp yarılan yere.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 13, 'Şüphe yok ki o, her şeyi ayırt eden kesin bir söz elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 14, 'Ve o, şaka değil elbet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 15, 'Şüphe yok ki onlar, bir düzendir, kurup duruyorlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 16, 'Ve ben de onlara karşı koyup duruyorum.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (86, 17, 'Artık mühlet ver kafirlere mühlet ver onlara az bir müddet.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 1, 'Tenzih et yücelerden yüce Rabbinin adını.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 2, 'Bir Rab ki yarattı, derken düzüp koştu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 3, 'Bir Rab ki ölçüp biçti, derken doğru yolu buldurdu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 4, 'Bir Rab ki otlağı çıkardı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 5, 'Derken onu kapkara, kupkuru bir hale döndürdü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 6, 'Seni okutacağız da unutmayacaksın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 7, 'Ancak Allah dilerse o başka; şüphe yok ki o, açığa vurulanı da, gizli kalanı da bilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 8, 'Ve sana, en kolay yolda başarı vereceğiz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 9, 'Artık öğüt ver, fayda verirse eğer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 10, 'Korkan, öğüt alır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 11, 'En kötü ve bahtsız olan, ondan sakınır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 12, 'Öyle bahtsız ki o, pek büyük ataşe atılır, yanar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 13, 'Sonra da orada ne ölür, ne dirilir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 14, 'Gerçekten de kurtulur, murada erer kendini temizleyen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 15, 'Ve Rabbinin adını anıp da namaz kılan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 16, 'Hayır, siz dünya yaşayışını üstün tutarsınız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 17, 'Ahiretse daha hayırlıdır ve daha da sürekli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 18, 'Şüphe yok ki bu vardı, elbette daha önceki sahifelerde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (87, 19, 'İbrahim''in ve Musa''nın sahifelerinde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 1, 'Geldi mi sana her yanı ve herkesi kavrayıp kaplayan o felaketin haberi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 2, 'O gün yüzler eğilirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 3, 'Çalışıp çabalarlar, zahmete girip yorulurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 4, 'Pek kızgın ateşe atılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 5, 'Pek ıssı bir suyla suvarılırlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 6, 'Onlara orada yemek olarak ancak zehirli diken var,', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 7, 'Ne besler ve ne doyurur, açlığı defeder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 8, 'O gün yüzler, sevinçlidir, neşeye dalar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 9, 'Çalıştıklarından hoşnut olurlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 10, 'Yüce cennettedirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 11, 'Orada boş söz duymazlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 12, 'Orada akan bir pınar var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 13, 'Orada yükseltilmiş tahtlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 14, 'Ve konmuş sağraklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 15, 'Ve sırasıra konmuş yastıklar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 16, 'Yeryer yayılmış döşemeler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 17, 'Hala mı bakmazlar deveye, nasıl da yaratılmış?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 18, 'Ve göğe, nasıl da yüceltilmiş?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 19, 'Ve dağlara, nasıl da dikilmiş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 20, 'Ve yeryüzüne, nasıl da yayılmış?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 21, 'Artık korkut, öğüt ver, sen, ancak bir korkutucusun, bir öğütçü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 22, 'Onlara musallat olmuş biri değilsin.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 23, 'Ancak kabul etmeyen ve kafir olana gelince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 24, 'Artık onu Allah azaplandırır pek büyük bir azapla.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 25, 'Şüphe yok ki tapımızdır gelecekleri yer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (88, 26, 'Sonra da şüphe yok ki hesaplarını görmek, bize düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 1, 'Andolsun ağaran sabaha.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 2, 'Ve on geceye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 3, 'Ve çifte ve teke.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 4, 'Ve ışırken geceye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 5, 'Bu antta büyük bir şey yok mu aklı başında olana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 6, 'Görmedin mi Rabbin neler yaptı Âd''a?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 7, 'Direklerle dolu İrem''e.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 8, 'Öylesine bir şehirdi ki yaratılmamıştı eşi şehirler arasında.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 9, 'Ve vadileri oyan, kayaları kesen Semud''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 10, 'Ve direk gibi sağlam kumandanları olan Firavun''a?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 11, 'Öylesine ki azdılar şehirlerde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 12, 'Derken bozgunculuğu çoğalttılar oralarda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 13, 'Derken Rabbin de onlara bir azap kamçısıdır, yağdırdı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 14, 'Şüphe yok ki Rabbin kullarının yollarında, pusudadır, onları görüp gözetir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 15, 'İnsan, öyle bir mahluktur ki Rabbi, onu sınadı da büyüttü, ve nimetler verdi mi, Rabbim der, layıktım da büyüttün beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 16, 'Ve fakat sınadı da rızkını daralttı mı, Rabbim der, alçalttı beni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 17, 'İş öyle değil, hayır; siz, ne yetimi ağırlıyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 18, 'Ve ne birbirinizi, yoksulu doyurmaya teşvik ediyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 19, 'Ve mirası, habbesine dek yiyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 20, 'Ve malı, alabildiğine seviyorsunuz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 21, 'İş öyle değil, hayır, yer bir kere paramparça olup dümdüz bir hale geldi mi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 22, 'Ve Rabbinin emri gelip çattı da melekler, safsaf oldu mu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 23, 'Ve o gün cehennem, ortaya çıktı mı, insan, öğüt alır, anlar ama öğütün, anlayışın artık ne faydası var ona?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 24, 'Keşke der, önceden, daha sağken iyilik etseydim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 25, 'Derken o gün öylesine bir azaplandırır onu ki kimsecikler, o çeşit azab edemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 26, 'Ve öylesine bağlar onu ki kimsecikler, o çeşit bağlayamaz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 27, 'Ey iyideniyiye inanmış, şüpheden kurtulmuş can.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 28, 'Dön Rabbine, ondan razı olarak ve rızasını kazanmış bulunarak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 29, 'Artık katıl kullarımın arasına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (89, 30, 'Ve gir cennetime.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 1, 'Andolsun bu şehre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 2, 'Ki sen oturmadasın bu şehirde.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 3, 'Ve babaya ve oğula.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 4, 'Gerçekten de biz insanı sıkıntı içinde yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 5, 'Hiçbir kimsenin, ona gücü yetmez mi sanır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 6, 'Ben, birçok mal helak ettim der.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 7, 'Hiçbir kimse, onu görmez mi sanır?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 8, 'Onun için halketmedik mi iki göz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 9, 'Ve bir dille iki dudak?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 10, 'Ve ona iki sarp yol gösterdik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 11, 'Derken dayanmadı o yokuşa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 12, 'Ve bilir misin, yokuş nedir?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 13, 'Bir kul azat etmek.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 14, 'Yahut açlık, kıtlık gününde doyurmak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 15, 'Yakınlığı olan bir yetimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 16, 'Yahut yerlere döşenmiş bir yoksulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 17, 'Sonra da inananlardan ve birbirlerine sabrı tavsiye edenlerden ve acımayı tavsiye edenlerden olmak.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 18, 'Onlardır işte sağ taraf ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 19, 'Delillerimize kafir olanlara gelince: Onlardır sol taraf ehli.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (90, 20, 'Onlaradır kapıları, üstlerine örtülmüş ateş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 1, 'Andolsun güneşe ve ışığına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 2, 'Ve ondan ışık aldığı, ardına düşüp seyrettiği zaman aya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 3, 'Ve ışıdığı zaman güne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 4, 'Ve kapladığı zaman geceye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 5, 'Ve göğe ve onu kurana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 6, 'Ve yere ve onu döşeyene.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 7, 'Ve cana ve azasını düzüp koşana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 8, 'Derken ona kötülüğünü de, çekinmesini de ilham etmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 9, 'Andolsun ki kim, özünü iyice temizlemişse kurtulmuştur, muradına ermiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 10, 'Ve andolsun ki kim, özünü kirletmiş, kötülüğe gömmüşse ziyana girmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 11, 'Semud, azgınlığıyle yalanlamıştı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 12, 'O zaman ki en bahtsızları atılmıştı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 13, 'Derken Allah''ın Peygamberi, bu demişti onlara, Allah''ın dişi devesi, çekinin ondan ve suvarılmasından.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 14, 'Derken yalanlamışlardı onu da ayaklarını kesip öldürmüşlerdi deveyi, derken Rableri de suçları yüzünden onları helak etmişti de orasını düzleyivermişti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (91, 15, 'Bu işin sonundan korkmazdı ki.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 1, 'Andolsun basınca, geceye.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 2, 'Ve ışıyınca, güne.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 3, 'Ve erkeği ve dişiyi yaratana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 4, 'Şüphe yok ki çalışmanız, elbette çeşitlidir, başkabaşka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 5, 'Ve kim verdi ve çekindiyse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 6, 'Ve en güzel sözü gerçeklediyse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 7, 'Artık ona en kolay yolu kolaylaştırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 8, 'Ve ama kim nekeslik etti ve zenginleşmeyi dilediyse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 9, 'Ve en güzel sözü yalanladıysa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 10, 'Artık ona da en güç yolu kolaylaştırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 11, 'Ve helak olduğu zaman malı, ona bir fayda vermez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 12, 'Şüphe yok ki doğru yolu göstermek, bize düşer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 13, 'Ve şüphe yok ki bizimdir son yaşayış da ve önceki de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 14, 'Artık sizi korkuttum alevalev parlayan ateşle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 15, 'Oraya da ancak pek bahtsız kişi atılır, yanar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 16, 'Öyle ki yalanlamıştır o ve yüzünü döndürmüştür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 17, 'Ve ondan, ancak, pek ziyade çekinen uzak kalır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 18, 'Öylesine ki malını verir de özünü tertemiz bir hale kor.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 19, 'Ve hiçbir kimseden, bir nimetle mükafatlanmayı dilemez.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 20, 'Yaptığını, ancak yücelerden yüce Rabbinin rızası için yapar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (92, 21, 'Ve o da, razı olacaktır ondan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 1, 'Andolsun kuşluğa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 2, 'Ve geceye, karanlığı basınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 3, 'Rabbin, seni ne terketti, ne de darıldı sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 4, 'Ve elbette ahiret, önceki dünyadan da hayırlıdır sana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 5, 'Ve elbette yakında Rabbin, öyle şeyler verecek ki sana, sonucu razı olacaksın.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 6, 'Seni bir yetim olarak bulup da yeryurt vermedi mi sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 7, 'Ve seni, yol yitirmiş bulup da yol göstermedi mi sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 8, 'Ve seni yoksul bulup da zenginlik vermedi mi sana?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 9, 'Artık sen de yetimi horlama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 10, 'Ve bir şey dileyeni boş çevirme, azarlama.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (93, 11, 'Ve Rabbinin nimetini an, söyle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 1, 'Senin göğsünü açıp genişletmedik mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 2, 'Ve senin yükünü kaldırıp attık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 3, 'Öylesine yük ki çökertmişti belini.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 4, 'Ve adını yücelttik.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 5, 'Artık şüphe yok ki her güçlükle beraber bir de kolaylık var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 6, 'Şüphe yok ki her güçlükle beraber bir de kolaylık var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 7, 'Artık sen de ibadeti bitirince yorul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (94, 8, 'Ve ancak Rabbinden iste, ona doğrul.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 1, 'Andolsun Tin''e ve Zeytun''a.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 2, 'Ve Turı Sina''ya.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 3, 'Ve bu emin şehre.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 4, 'Gerçekten de biz, insanı, en güzel bir surete sahip olarak yarattık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 5, 'Sonra da onu döndürdük, aşağıların en aşağısına attık.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 6, 'Ancak inananlar ve iyi işlerde bulunanlar başka, gerçekten de onlara bitmez tükenmez, başa kakılmaz bir mükafat var.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 7, 'Artık dini yalanlamana sebep nedir?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (95, 8, 'Allah, hükmedenlerin en üstünü değil midir?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 1, 'Oku Rabbinin adıyla ki bütün mahlukatı yarattı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 2, 'İnsanı da bir parça kan pıhtısından var etti.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 3, 'Oku ve Rabbin, pek büyük bir kerem sahibidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 4, 'Öyle bir Rab ki kalemle öğretmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 5, 'İnsana bilmediğini belletmiştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 6, 'İş öyle değil, şüphe yok ki insan, azar elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 7, 'Kendini ihtiyacı yok görürse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 8, 'Şüphe yok ki dönüş, Rabbinin tapısına.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 9, 'Gördün mü nehyedeni.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 10, 'Bir kulu, namaz kılarsa.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 11, 'Bir düşün, ya o doğru yolu bulup giderse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 12, 'Yahut da çekinmeyi emrederse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 13, 'Gördün mü sen de, ya öbürü yalanlar ve yüz çevirirse.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 14, 'Bilmez mi ki Allah, bilir gerçekten de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 15, 'İş öyle değil, vaz geçmezse eğer elbette tutarız perçeminden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 16, 'Yalan söyleyenin, yanlış hareket edenin perçeminden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 17, 'Derken hemdemlerini, kavmini, kabilesini çağırır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 18, 'Biz de yakında zebanileri çağırırız.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (96, 19, 'İş öyle değil, itaat etme ona ve artık secde et de yaklaş.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 1, 'Şüphe yok ki indirdik Kur''an''ı Kadir gecesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 2, 'Ve ne bildirdi sana, nedir Kadir gecesi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 3, 'Bin aydan daha da hayırlıdır Kadir gecesi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 4, 'O gece melekler ve Ruh, takdir edilen her iş için, Rablerinin izniyle inerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (97, 5, 'Esenliktir, o gece, gün ışığıncaya dek sürer.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 1, 'Vaz geçemezlerdi kafirlikten kitap ehlinden kafir olanlar ve şirk koşanlar, kendilerine apaçık kesin bir delil gelmedikçe.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 2, 'Bir kesin delil, bir peygamber, Allah tarafından, onlara tertemiz sahifeleri okumadıkça.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 3, 'O sahifelerdedir hükmü sabit doğru kitaplar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 4, 'Ve ancak kendilerine apaçık kesin bir delil geldikten sonradır ki aykırılığa düştüler, kendilerine kitap verilmiş olanlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 5, 'Ve ancak özleri halis olarak ve onun gerçek dinine uyarak Allah''a kulluk etmeleri emredildi onlara, doğru olmaları emredildi ve namaz kılmaları ve zekat vermeleri ve işte budur hükümleri sabit doğru kitaplardaki din de.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 6, 'Kitap ehlinden kafir olanlar ve şirk koşanlar, şüphe yok ki cehennem ateşindedir, ebedidir onlar orada, onlardır yaratılmışların en kötüleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 7, 'İnananlar ve iyi işlerde bulunanlarsa: Onlardır şüphe yok ki yaratılmışların en hayırlıları.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (98, 8, 'Rablerinin katındaki mükafatları, kıyılarından ırmaklar akan ebedi Adn cennetleridir, ebedidir onlar orada, Allah razı olmuştur onlardan ve onlar da razı olmuşlardır ondan; ve bu mükafat, Rabbinden korkanadır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 1, 'Yeryüzü, şiddetli bir depremle sarsılınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 2, 'Ve yeryüzü, ağırlıklarını çıkarınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 3, 'Ve insan, ne oluyor ki buna deyince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 4, 'O gün, bütün haberlerini anlatınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 5, 'Çünkü Rabbin, vahyetmiştir, bildirmiştir ona.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 6, 'O gün insanlar, gittikleri yerden gelirler, yaptıklarını görmek için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 7, 'Artık kim, bir zerre ağırlığı hayır yapmışsa görür onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (99, 8, 'Ve kim, bir zerre ağırlığı şer yapmışsa görür onu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 1, 'Andolsun soluya soluya koşanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 2, 'Tırnaklarıyle bastıkça taştan kıvılcım saçanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 3, 'Sabah çağı, düşmanı basanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 4, 'Derken her yanı toza, dumana boğanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 5, 'Derken düşman topluluğunun ta ortasına dalanlara.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 6, 'Şüphe yok ki insan, Rabbine karşı pek inatçıdır, pek nankördür.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 7, 'Ve şüphe yok ki o, buna tanıktır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 8, 'Ve şüphe yok ki insan, hayrına yarıyan malamülke karşı da pek düşkündür, pek nekestir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 9, 'Fakat bilmez mi ki kabirlerdekiler, dışarı çıkınca.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 10, 'Ve gönüllerdekiler, meydana vurulup bilinince.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (100, 11, 'Şüphe yok ki Rabbin, o gün, onların her şeyini bilir elbette.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 1, 'O şiddetli bir gürültüyle gelip çatacak, yürekleri koparacak felaket.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 2, 'Nedir o şiddetli bir gürültüyle gelip çatacak, yürekleri kopacak felaket?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 3, 'Ve ne bildirdi sana, nedir o şiddetli bir gürültüyle gelip çatacak, yürekleri koparacak felaket?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 4, 'O gün, insanlar, kendilerini ateşlere atan, dağılıp uçuşan pervanelere benzerler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 5, 'Ve dağlar, atılmış renkli pamuklara döner.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 6, 'Artık kimin ki terazilerindeki tartısı ağır gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 7, 'O, hoşnut, razı bir geçimdedir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 8, 'Ve fakat kimin ki terazilerdeki tartısı hafif gelir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 9, 'Onun, ana kucağı gibi sığınacak yeri, ana yurdu, cehennem uçurumudur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 10, 'Ve ne bildirdi sana, nedir cehennem uçurumu?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (101, 11, 'O, pek kızgın bir ateştir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 1, 'Oyaladı mal-mülk çokluğuyla öğünmek sizleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 2, 'Ziyaret edinceye dek kabirleri.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 3, 'İş öyle değil, yakında bilirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 4, 'Sonra da gene iş öyle değil, yakında bilirsiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 5, 'İş öyle değil, şüphesiz olarak iyideniyiye bir bilseniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 6, 'Andolsun ki o koca cehennemi göreceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 7, 'Sonra da andolsun ki gözlerinizle göreceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (102, 8, 'Sonra da andolsun ki o gün nimetlerden soruya çekileceksiniz.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 1, 'Andolsun zamana.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 2, 'Şüphe yok ki insan, elbette zararda, ziyanda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (103, 3, 'Ancak inananlar ve iyi işlerde bulunanlar ve birbirlerine gerçeği gözetmeyi ve sabretmeyi tavsiye edenler başka.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 1, 'Bütün incedeninceye alay eden kovucuların vay hallerine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 2, 'Öylesine ki mal yığar ve onu sayardurur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 3, 'Sanır ki gerçekten de malı, onu ebedileştirir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 4, 'İş öyle değil, andolsun ki o, kırıp döken, silip süpüren cehenneme atılır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 5, 'Ve ne bildirdi sana, o kırıp döken, silip süpüren cehennem nedir?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 6, 'Allah''ın tutuşturulmuş bir ateşidir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 7, 'Öylesine ateş ki yürekleri sarar, kaplar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 8, 'Şüphe yok ki üstlerine kapıları kapanmıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (104, 9, 'Upuzun uzatılmış direklerle.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 1, 'Fil ashabına Rabbin ne yaptı, neler etti, görmedin mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 2, 'Düzenlerini boşa çıkarmadı mı?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 3, 'Ve onlara, çeşitli yerlerden bölükbölük, birbiri ardınca kuşlar göndermedi mi?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 4, 'Onları, balçıktan taşlarla taşladılar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (105, 5, 'Onlar da içi boş ekin saplarına, kırılıp ezilmiş samanlara döndüler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 1, 'Bunu da Kurayş''ın uzlaşması, hallerinin düzene girmesi için yaptı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 2, 'Yaz ve kış, alışveriş için göçüp konarak yolculuk ederlerken uzlaşıp düzene girmeleri için.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 3, 'Artık kulluk edin bu evin Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (106, 4, 'Öyle Rab ki doyurdu da kurtardı sizi açlıktan ve emin etti sizi korkudan.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 1, 'Gördüm mü yalanlayanı dini?', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 2, 'İşte budur o kimse ki horlar yetimi.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 3, 'Ve doyurmaz da, önayak olmaz da doyurmaya yoksulu.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 4, 'Vay hallerine o namaz kılanların.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 5, 'Öylesine namaz kılanların ki namazlarını unuturlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 6, 'Ve onlar, bütün işlerini gösteriş için yaparlar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (107, 7, 'Ve zekat vermeyi menederler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 1, 'Şüphe yok ki biziz sana kevseri veren.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 2, 'Artık namaz kıl Rabbine ve kurban kes sen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (108, 3, 'Şüphesiz, sana buğzeden yok mu, odur nesli kesilen.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 1, 'De ki: Ey kafirler.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 2, 'Tapmam sizin taptıklarınıza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 3, 'Ve siz de tapmazsınız benim taptığıma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 4, 'Ve ne ben taparım sizin taptıklarınıza.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 5, 'Ve ne siz taparsınız benim taptığıma.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (109, 6, 'Size, sizin dininiz, bana, benim dinim.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 1, 'Allah''ın yardımı ve fetih, gelip çattı mı.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 2, 'Ve insanların, bölükbölük, Allah dinine girdiğini gördün mü.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (110, 3, 'Artık, Rabbine hamd ederek tenzih et onu ve yarlıganma dile ondan; şüphe yok ki o, bütün tövbeleri kabul eder.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 1, 'Elleri kuruyasıca AbuLeheb ve kendi, kurudu da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 2, 'Malı da bir fayda vermedi ona, kazandığı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 3, 'Alevalev yanan bir ateşe atılacaktır o da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 4, 'Ve odun hamalı, karısı da.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (111, 5, 'Hurma lifinden örülmüş bir ip de güzelim boynunda.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 1, 'De ki: O Allah, birdir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 2, 'Her şey ve herkes, ona muhtaçtır, onun zevali yoktur, birşeye muhtaç değildir.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 3, 'Doğurmaz ve doğmamıştır.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (112, 4, 'Ve ona, bir tek eşit ve benzer olamaz, yoktur.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 1, 'De ki: Sığınırım karanlığı yarıp ışıtan sabahın Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 2, 'Yarattığı mahlukların şerrinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 3, 'Çöküp etrafı kapladığı zaman karanlığın şerrinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 4, 'Ve düğümlere üfleyen kadınların şerrinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (113, 5, 'Ve hasetçinin haset ettiği zaman, şerrinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 1, 'De ki: Sığınırım insanların Rabbine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 2, 'İnsanların sahibine.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 3, 'İnsanların mabuduna.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 4, 'Gizlice, sinsisinsi vesveseler verenin şerrinden.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 5, 'Öylesine ki insanların gönüllerine vesveseler sokar.', '');
INSERT INTO verses (sura, aya, text, footnotes) VALUES (114, 6, 'Cinden olsun, insandan olsun, bu çeşit kişilerin şerrinden.', '');
